text./plugins/alipfx/shaders/4-color-gradient:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// ---- Custom properties (Panzoid: spaces become underscores) ----
uniform vec2 Point_1;
uniform vec3 Color_1;

uniform vec2 Point_2;
uniform vec3 Color_2;

uniform vec2 Point_3;
uniform vec3 Color_3;

uniform vec2 Point_4;
uniform vec3 Color_4;

uniform float Blend;         // 0..100
uniform float Jitter;        // 0..100
uniform float Opacity;       // 0..100
uniform float Blending_Mode; // 0..17 (integers)

// --------------------- Utility: hash noise (stable per-pixel) ---------------------
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
  // Two independent hashes -> vec2 in [0,1)
  float n1 = hash12(p + vec2(17.13, 91.7));
  float n2 = hash12(p + vec2(71.7, 23.13));
  return vec2(n1, n2);
}

// --------------------- Color conversion: RGB <-> HSL ---------------------
float hue2rgb(float p, float q, float t) {
  if (t < 0.0) t += 1.0;
  if (t > 1.0) t -= 1.0;
  if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
  if (t < 1.0/2.0) return q;
  if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
  return p;
}

vec3 rgb2hsl(vec3 c) {
  float maxc = max(c.r, max(c.g, c.b));
  float minc = min(c.r, min(c.g, c.b));
  float h = 0.0;
  float s = 0.0;
  float l = (maxc + minc) * 0.5;

  if (maxc != minc) {
    float d = maxc - minc;
    s = (l > 0.5) ? d / (2.0 - maxc - minc) : d / (maxc + minc);

    if (maxc == c.r)      h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0);
    else if (maxc == c.g) h = (c.b - c.r) / d + 2.0;
    else                  h = (c.r - c.g) / d + 4.0;

    h /= 6.0;
  }
  return vec3(h, s, l);
}

vec3 hsl2rgb(vec3 hsl) {
  float h = hsl.x;
  float s = hsl.y;
  float l = hsl.z;

  if (s == 0.0) return vec3(l);

  float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
  float p = 2.0 * l - q;

  float r = hue2rgb(p, q, h + 1.0/3.0);
  float g = hue2rgb(p, q, h);
  float b = hue2rgb(p, q, h - 1.0/3.0);

  return vec3(r, g, b);
}

// --------------------- Blend modes ---------------------
vec3 blend_normal(vec3 base, vec3 blend) { return blend; }
vec3 blend_add(vec3 base, vec3 blend) { return base + blend; }
vec3 blend_multiply(vec3 base, vec3 blend) { return base * blend; }
vec3 blend_screen(vec3 base, vec3 blend) { return 1.0 - (1.0 - base) * (1.0 - blend); }

vec3 blend_overlay(vec3 base, vec3 blend) {
  vec3 low  = 2.0 * base * blend;
  vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
  return mix(low, high, step(0.5, base));
}

vec3 blend_hard_light(vec3 base, vec3 blend) {
  vec3 low  = 2.0 * base * blend;
  vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
  return mix(low, high, step(0.5, blend));
}

float softlight_channel(float base, float blend) {
  if (blend < 0.5) {
    return base - (1.0 - 2.0 * blend) * base * (1.0 - base);
  } else {
    float g = (base <= 0.25)
      ? (((16.0 * base - 12.0) * base + 4.0) * base)
      : sqrt(base);
    return base + (2.0 * blend - 1.0) * (g - base);
  }
}

vec3 blend_soft_light(vec3 base, vec3 blend) {
  return vec3(
    softlight_channel(base.r, blend.r),
    softlight_channel(base.g, blend.g),
    softlight_channel(base.b, blend.b)
  );
}

vec3 blend_color_dodge(vec3 base, vec3 blend) {
  return min(vec3(1.0), base / max(vec3(1e-6), (1.0 - blend)));
}

vec3 blend_color_burn(vec3 base, vec3 blend) {
  return 1.0 - min(vec3(1.0), (1.0 - base) / max(vec3(1e-6), blend));
}

vec3 blend_darken(vec3 base, vec3 blend) { return min(base, blend); }
vec3 blend_lighten(vec3 base, vec3 blend) { return max(base, blend); }
vec3 blend_difference(vec3 base, vec3 blend) { return abs(base - blend); }
vec3 blend_exclusion(vec3 base, vec3 blend) { return base + blend - 2.0 * base * blend; }

vec3 blend_hue(vec3 base, vec3 blend) {
  vec3 b = rgb2hsl(base);
  vec3 f = rgb2hsl(blend);
  return hsl2rgb(vec3(f.x, b.y, b.z));
}

vec3 blend_saturation(vec3 base, vec3 blend) {
  vec3 b = rgb2hsl(base);
  vec3 f = rgb2hsl(blend);
  return hsl2rgb(vec3(b.x, f.y, b.z));
}

vec3 blend_color(vec3 base, vec3 blend) {
  vec3 b = rgb2hsl(base);
  vec3 f = rgb2hsl(blend);
  return hsl2rgb(vec3(f.x, f.y, b.z));
}

vec3 blend_luminosity(vec3 base, vec3 blend) {
  vec3 b = rgb2hsl(base);
  vec3 f = rgb2hsl(blend);
  return hsl2rgb(vec3(b.x, b.y, f.z));
}

vec3 apply_blend_mode(int mode, vec3 base, vec3 blend) {
  if (mode == 1)  return blend_normal(base, blend);
  if (mode == 2)  return blend_add(base, blend);
  if (mode == 3)  return blend_multiply(base, blend);
  if (mode == 4)  return blend_screen(base, blend);
  if (mode == 5)  return blend_overlay(base, blend);
  if (mode == 6)  return blend_soft_light(base, blend);
  if (mode == 7)  return blend_hard_light(base, blend);
  if (mode == 8)  return blend_color_dodge(base, blend);
  if (mode == 9)  return blend_color_burn(base, blend);
  if (mode == 10) return blend_darken(base, blend);
  if (mode == 11) return blend_lighten(base, blend);
  if (mode == 12) return blend_difference(base, blend);
  if (mode == 13) return blend_exclusion(base, blend);
  if (mode == 14) return blend_hue(base, blend);
  if (mode == 15) return blend_saturation(base, blend);
  if (mode == 16) return blend_color(base, blend);
  if (mode == 17) return blend_luminosity(base, blend);
  return blend_normal(base, blend);
}

// --------------------- AE-like 4-color gradient core ---------------------
// AE: “four solid-color circles blended together”; Blend higher => more gradual transitions. [1](https://helpx.adobe.com/after-effects/using/generate-effects.html)
vec3 four_color_gradient(vec2 fragPx) {
  float diag = max(1.0, length(resolution));

  float d1 = distance(fragPx, Point_1) / diag;
  float d2 = distance(fragPx, Point_2) / diag;
  float d3 = distance(fragPx, Point_3) / diag;
  float d4 = distance(fragPx, Point_4) / diag;

  float t = clamp(Blend / 100.0, 0.0, 1.0);
  float power = mix(24.0, 1.0, t); // higher Blend => lower power => smoother

  float eps = 1e-4;
  float w1 = 1.0 / pow(d1 + eps, power);
  float w2 = 1.0 / pow(d2 + eps, power);
  float w3 = 1.0 / pow(d3 + eps, power);
  float w4 = 1.0 / pow(d4 + eps, power);

  float ws = w1 + w2 + w3 + w4;
  vec3 col = (Color_1 * w1 + Color_2 * w2 + Color_3 * w3 + Color_4 * w4) / max(1e-6, ws);

  return clamp(col, 0.0, 1.0);
}

void main() {
  // Original layer sample (Panzoid input buffer) [2](https://panzoid.com/community/official/37192?c=3)
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // Convert Panzoid UV to AE-style pixel coords:
  // Panzoid vUv is bottom-left; AE points are top-left => flip Y. [2](https://panzoid.com/community/official/37192?c=3)
  vec2 uvAE = vec2(vUv.x, 1.0 - vUv.y);
  vec2 fragPx = uvAE * resolution;

  float jit = clamp(Jitter / 100.0, 0.0, 1.0);

  // --------------------- NEW: spatial jitter ("scattering") ---------------------
  // Jitter in AE is mainly for banding reduction, but you want visible scattering.
  // So we jitter the sampling position by a few pixels at high values.
  // Tune MAX_SCATTER_PX to taste (8.0 = visible but not crazy).
  const float MAX_SCATTER_PX = 8.0;

  vec2 rnd2 = hash22(gl_FragCoord.xy);
  vec2 scatterOffsetPx = (rnd2 - 0.5) * (MAX_SCATTER_PX * jit);

  vec2 fragPxJ = fragPx + scatterOffsetPx;

  // Compute gradient using jittered position
  vec3 grad = four_color_gradient(fragPxJ);

  // --------------------- Dither jitter (anti-banding) ---------------------
  // Keep this subtle; scale it like a dither (roughly ~1/255 .. ~4/255 at max)
  vec3 n = vec3(
    hash12(gl_FragCoord.xy + vec2(0.0, 0.0)),
    hash12(gl_FragCoord.xy + vec2(19.19, 73.73)),
    hash12(gl_FragCoord.xy + vec2(47.47, 11.11))
  );

  float ditherAmp = mix(0.0, 4.0 / 255.0, jit);
  grad = clamp(grad + (n - 0.5) * ditherAmp, 0.0, 1.0);

  float op = clamp(Opacity / 100.0, 0.0, 1.0);
  int mode = int(floor(Blending_Mode + 0.5));

  vec3 outRGB;

  // Your rule: mode 0 mixes with original layer (normal composite)
  if (mode == 0) {
    outRGB = mix(texel.rgb, grad, op);
  } else {
    vec3 blended = apply_blend_mode(mode, texel.rgb, grad);
    outRGB = mix(texel.rgb, blended, op);
  }

  // Keep original alpha (Opacity is “gradient alpha strength”, not changing cutout)
  gl_FragColor = vec4(clamp(outRGB, 0.0, 1.0), texel.a);
}

text./plugins/alipfx/shaders/8bit-pixcam.glsl:
precision highp float;
precision highp int;

// Default Panzoid Uniforms & Varyings
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUv;
varying vec2 vUvScaled;

// Custom 8Bit PixCam Uniforms (Automatically linked to PZ Properties)
uniform float Factor;
uniform float Brightness;
uniform float Contrast;
uniform float Dither_Level;
uniform vec3 Color_1;
uniform vec3 Color_2;
uniform vec3 Color_3;
uniform vec3 Color_4;
uniform float Draw_Grid_Lines;
uniform vec3 Grid_Color;

// Procedural 4x4 Bayer Dither Matrix Generation
float getBayer(vec2 pos) {
    int x = int(mod(pos.x, 4.0));
    int y = int(mod(pos.y, 4.0));
    int index = x + y * 4;

    float val = 0.0;
    if (index == 0) val = 0.0;
    else if (index == 1) val = 8.0;
    else if (index == 2) val = 2.0;
    else if (index == 3) val = 10.0;
    else if (index == 4) val = 12.0;
    else if (index == 5) val = 4.0;
    else if (index == 6) val = 14.0;
    else if (index == 7) val = 6.0;
    else if (index == 8) val = 3.0;
    else if (index == 9) val = 11.0;
    else if (index == 10) val = 1.0;
    else if (index == 11) val = 9.0;
    else if (index == 12) val = 15.0;
    else if (index == 13) val = 7.0;
    else if (index == 14) val = 13.0;
    else if (index == 15) val = 5.0;

    return val / 16.0;
}

void main() {
    // 1. Prevent division by zero and set minimum pixelation factor
    float safeFactor = max(1.0, Factor);
    vec2 fragCoord = vUv * resolution;

    // 2. Pixelate coordinates based on Factor
    vec2 pixelCoord = floor(fragCoord / safeFactor) * safeFactor;

    // 3. Convert back to UV space and apply Panzoid's uvScale buffer fix
    vec2 pUv = (pixelCoord + 0.5 * safeFactor) / resolution;
    vec2 pUvScaled = pUv * uvScale;

    // 4. Sample the underlying layer
    vec4 texel = texture2D(tDiffuse, pUvScaled);

    // 5. Apply Brightness and Contrast
    // Adjusting from a 1.0 baseline as default neutral
    vec3 adjusted = (texel.rgb - 0.5) * Contrast + 0.5 + (Brightness - 1.0);

    // 6. Calculate Grayscale Luminance (NTSC formula)
    float lum = dot(adjusted, vec3(0.299, 0.587, 0.114));

    // 7. Generate and Apply Bayer Dithering
    vec2 ditherCoord = floor(fragCoord / safeFactor);
    float ditherVal = getBayer(ditherCoord);

    // Center the dither value and apply intensity
    lum = lum + (ditherVal - 0.5) * Dither_Level;
    lum = clamp(lum, 0.0, 1.0);

    // 8. Map to 4-Color Palette based on luminance thresholds
    vec3 outColor;
    float stepNum = floor(lum * 4.0); // Bins into 0.0, 1.0, 2.0, 3.0, 4.0

    if (stepNum <= 0.0) {
        outColor = Color_1;
    } else if (stepNum <= 1.0) {
        outColor = Color_2;
    } else if (stepNum <= 2.0) {
        outColor = Color_3;
    } else {
        outColor = Color_4;
    }

    // 9. Overlay Grid Lines (1 pixel thick lines mapping to the Factor edge)
    if (Draw_Grid_Lines >= 0.5) {
        if (mod(fragCoord.x, safeFactor) < 1.0 || mod(fragCoord.y, safeFactor) < 1.0) {
            outColor = Grid_Color;
        }
    }

    // 10. Output Final Pixel
    gl_FragColor = vec4(outColor, texel.a);
}

text./plugins/alipfx/shaders/a-bayangan.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

uniform vec3 Color;
uniform float Opacity;           // 0..100
uniform float Softness;          // pixels
uniform float Distance;          // pixels
uniform float Angle;             // degrees
uniform float Unmult;            // 0/1
uniform float Invert;            // 0/1
uniform float Composite_Order;   // 0 = In Front, 1 = Behind
uniform float Colorize;          // 0/1
uniform float Master_Hue;        // degrees
uniform float Master_Saturation; // percent
uniform float Master_Lightness;  // percent

float hue2rgb(float p, float q, float t)
{
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;
    if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
    if (t < 1.0 / 2.0) return q;
    if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    return p;
}

vec3 rgb2hsl(vec3 c)
{
    float maxc = max(max(c.r, c.g), c.b);
    float minc = min(min(c.r, c.g), c.b);
    float h = 0.0;
    float s = 0.0;
    float l = 0.5 * (maxc + minc);
    float d = maxc - minc;

    if (d > 1e-6)
    {
        s = (l > 0.5) ? (d / (2.0 - maxc - minc)) : (d / (maxc + minc));

        if (maxc == c.r)
            h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0);
        else if (maxc == c.g)
            h = (c.b - c.r) / d + 2.0;
        else
            h = (c.r - c.g) / d + 4.0;

        h /= 6.0;
    }

    return vec3(h, s, l);
}

vec3 hsl2rgb(vec3 hsl)
{
    float h = fract(hsl.x);
    float s = clamp(hsl.y, 0.0, 1.0);
    float l = clamp(hsl.z, 0.0, 1.0);

    if (s <= 1e-6)
    {
        return vec3(l);
    }

    float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
    float p = 2.0 * l - q;

    return vec3(
        hue2rgb(p, q, h + 1.0 / 3.0),
        hue2rgb(p, q, h),
        hue2rgb(p, q, h - 1.0 / 3.0)
    );
}

vec4 readTex(vec2 uv)
{
    vec4 c = texture2D(tDiffuse, uv);
    if (Unmult > 0.5 && c.a > 1e-6)
    {
        c.rgb /= c.a;
    }
    return c;
}

float alphaAt(vec2 uv)
{
    return readTex(uv).a;
}

float blurredAlpha(vec2 uv, float radiusPx)
{
    vec2 o = max(radiusPx, 0.0) / resolution;

    float sum = 0.0;
    float w = 0.0;

    sum += alphaAt(uv) * 0.18; w += 0.18;

    sum += alphaAt(uv + vec2( 1.0,  0.0) * o) * 0.08; w += 0.08;
    sum += alphaAt(uv + vec2(-1.0,  0.0) * o) * 0.08; w += 0.08;
    sum += alphaAt(uv + vec2( 0.0,  1.0) * o) * 0.08; w += 0.08;
    sum += alphaAt(uv + vec2( 0.0, -1.0) * o) * 0.08; w += 0.08;

    sum += alphaAt(uv + vec2( 1.0,  1.0) * o) * 0.07; w += 0.07;
    sum += alphaAt(uv + vec2(-1.0,  1.0) * o) * 0.07; w += 0.07;
    sum += alphaAt(uv + vec2( 1.0, -1.0) * o) * 0.07; w += 0.07;
    sum += alphaAt(uv + vec2(-1.0, -1.0) * o) * 0.07; w += 0.07;

    sum += alphaAt(uv + vec2( 2.0,  0.0) * o) * 0.05; w += 0.05;
    sum += alphaAt(uv + vec2(-2.0,  0.0) * o) * 0.05; w += 0.05;
    sum += alphaAt(uv + vec2( 0.0,  2.0) * o) * 0.05; w += 0.05;
    sum += alphaAt(uv + vec2( 0.0, -2.0) * o) * 0.05; w += 0.05;

    return sum / w;
}

vec3 applyColorize(vec3 base)
{
    if (Colorize < 0.5)
    {
        return base;
    }

    vec3 hsl = rgb2hsl(base);

    // -- AFTER EFFECTS COLORIZE LOGIC --
    hsl.x = fract(Master_Hue / 360.0);
    hsl.y = clamp(Master_Saturation / 100.0, 0.0, 1.0);
    hsl.z = clamp(hsl.z + (Master_Lightness / 100.0), 0.0, 1.0);

    return hsl2rgb(hsl);
}

vec4 overStraight(vec4 top, vec4 bottom)
{
    float outA = top.a + bottom.a * (1.0 - top.a);

    vec3 topP = top.rgb * top.a;
    vec3 bottomP = bottom.rgb * bottom.a;

    vec3 outP = topP + bottomP * (1.0 - top.a);
    vec3 outRGB = (outA > 1e-6) ? (outP / outA) : vec3(0.0);

    return vec4(outRGB, outA);
}

void main()
{
    vec2 uv = vUvScaled;

    vec4 src = readTex(uv);

    float ang = radians(Angle);
    vec2 dir = vec2(cos(ang), -sin(ang));
    vec2 shadowUV = uv - dir * (Distance / resolution);

    float op = clamp(Opacity / 100.0, 0.0, 1.0);

    float srcA   = src.a;
    float shMask = clamp(blurredAlpha(shadowUV, Softness), 0.0, 1.0);
    float shA    = shMask * op;

    vec3 srcBaseRGB = src.rgb;
    vec3 shBaseRGB  = readTex(shadowUV).rgb;

    vec3 srcColorRGB = applyColorize(srcBaseRGB);
    vec3 shColorRGB  = applyColorize(shBaseRGB);

    vec4 srcNormal    = vec4(srcBaseRGB, srcA);
    vec4 srcColorized = vec4(srcColorRGB, srcA);

    // back darkening uses opacity as 0 -> 100 color mix
    vec4 srcDark      = vec4(mix(srcBaseRGB, Color, op), srcA);

    vec4 shOriginal   = vec4(shBaseRGB, shA);
    vec4 shColorized  = vec4(shColorRGB, shA);
    vec4 shDark       = vec4(Color, shA);

    // special front for Invert ON + In Front:
    // stays colorized and does NOT fade with Opacity
    vec4 shFrontColor = vec4(shColorRGB, shMask);

    vec4 outCol;

    if (Composite_Order < 0.5)
    {
        // 0 = In Front
        //
        // Invert OFF:
        //   front = dark shadow
        //   back  = colorized source
        //
        // Invert ON:
        //   front = colorized shadow
        //   back  = dark source (affected by Opacity 0..100)

        if (Invert < 0.5)
        {
            outCol = overStraight(shDark, srcColorized);
        }
        else
        {
            outCol = overStraight(shFrontColor, srcDark);
        }
    }
    else
    {
        // 1 = Behind
        //
        // Invert OFF:
        //   front = normal source
        //   back  = colorized shadow
        //
        // Invert ON:
        //   front = colorized source
        //   back  = original / non-dark shadow

        if (Invert < 0.5)
        {
            outCol = overStraight(srcNormal, shColorized);
        }
        else
        {
            outCol = overStraight(srcColorized, shOriginal);
        }
    }

    gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/a-glossy.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;
uniform vec2 uvScale;

// -- PROPERTIES --
uniform vec3 Global_Color;
uniform float Enable_4_Colors;
uniform float Random_Seed;
uniform vec3 Fill_Color_1;
uniform vec3 Fill_Color_2;
uniform vec3 Fill_Color_3;
uniform vec3 Fill_Color_4;

uniform float Angle;
uniform float Gap;
uniform float Distance;
uniform float Choker_1;
uniform float Roundness;
uniform float Choker_2;
uniform float Softness;
uniform float Opacity;
uniform float Blend_Mode;
uniform float Glossy_Only;

// -- BLEND MODE FUNCTIONS --
vec3 blendDarken(vec3 base, vec3 blend) { return min(blend, base); }
vec3 blendMultiply(vec3 base, vec3 blend) { return base * blend; }
vec3 blendAdd(vec3 base, vec3 blend) { return min(base + blend, vec3(1.0)); }
vec3 blendLighten(vec3 base, vec3 blend) { return max(blend, base); }
vec3 blendScreen(vec3 base, vec3 blend) { return 1.0 - (1.0 - base) * (1.0 - blend); }
vec3 blendOverlay(vec3 base, vec3 blend) {
    return mix(
        2.0 * base * blend,
        1.0 - 2.0 * (1.0 - base) * (1.0 - blend),
        step(0.5, base)
    );
}
vec3 blendSoftLight(vec3 base, vec3 blend) {
    return mix(
        2.0 * base * blend + base * base * (1.0 - 2.0 * blend),
        sqrt(max(base, 0.0)) * (2.0 * blend - 1.0) + 2.0 * base * (1.0 - blend),
        step(0.5, blend)
    );
}
vec3 blendHardLight(vec3 base, vec3 blend) { return blendOverlay(blend, base); }
vec3 blendDifference(vec3 base, vec3 blend) { return abs(base - blend); }

// Blur alpha using a Vogel spiral kernel (Much better for smooth roundness)
float blurredAlpha(vec2 uv, float radiusPx) {
    if (radiusPx <= 0.001) {
        return texture2D(tDiffuse, uv).a;
    }

    const int taps = 32; // Increased taps for a smoother liquid feel
    float acc = 0.0;
    const float goldenAngle = 2.39996323; // 137.5 degrees in radians

    for (int i = 0; i < taps; i++) {
        float fi = float(i);
        // Distribute sample points evenly inside a solid circle
        float r = sqrt((fi + 0.5) / float(taps)); 
        float theta = fi * goldenAngle;

        vec2 dir = vec2(cos(theta), sin(theta));
        vec2 offset = dir * r * (radiusPx / resolution) * uvScale;

        acc += texture2D(tDiffuse, uv + offset).a;
    }

    return acc / float(taps);
}

// Smooth 4-color ramp
vec3 getGlossColor(vec2 lightDir) {
    vec3 colorOut = Global_Color;

    if (Enable_4_Colors > 0.5) {
        vec2 pos = (vUv - 0.5) * resolution;
        vec2 tangent = vec2(-lightDir.y, lightDir.x);

        // Stable 0..1 coordinate along the gloss
        float t = dot(pos, tangent) / max(resolution.x, resolution.y);
        t = fract(t + 0.5 + Random_Seed * 0.01);

        if (t < 0.25) {
            colorOut = mix(Fill_Color_1, Fill_Color_2, t / 0.25);
        } else if (t < 0.50) {
            colorOut = mix(Fill_Color_2, Fill_Color_3, (t - 0.25) / 0.25);
        } else if (t < 0.75) {
            colorOut = mix(Fill_Color_3, Fill_Color_4, (t - 0.50) / 0.25);
        } else {
            colorOut = mix(Fill_Color_4, Fill_Color_1, (t - 0.75) / 0.25);
        }
    }

    return colorOut;
}

void main() {
    vec4 baseTexel = texture2D(tDiffuse, vUvScaled);

    // Early out for transparent pixels
    if (baseTexel.a <= 0.0) {
        gl_FragColor = vec4(0.0);
        return;
    }

    // Light / gloss direction
    float rad = radians(Angle);
    vec2 lightDir = normalize(vec2(cos(rad), sin(rad)));

    // Convert 1 pixel in the chosen direction into scaled UV space
    vec2 stepUv = (lightDir / resolution) * uvScale;

    // Gap = inset from the edge
    // Distance = thickness of the glossy band
    float insetPx = max(Gap, 0.0);
    float bandWidthPx = max(Distance, 0.001);
    float blurPx = max(Roundness, 0.0);

    // Sample two "eroded" alpha fields
    float alphaNear = blurredAlpha(vUvScaled - stepUv * insetPx, blurPx);
    float alphaFar  = blurredAlpha(vUvScaled - stepUv * (insetPx + bandWidthPx), blurPx);

    // -- INDEPENDENT CHOKERS --
    // Choker 1 applies to the outer edge of the gloss
    // Choker 2 applies to the inner edge of the gloss
    float t1 = 0.5 + (Choker_1 * 0.005);
    float t2 = 0.5 + (Choker_2 * 0.005);
    float edge = max(Softness * 0.005, 0.001);

    // Apply the thresholds directly to the near/far alphas before subtracting
    float chokedNear = smoothstep(t1 - edge, t1 + edge, alphaNear);
    float chokedFar  = smoothstep(t2 - edge, t2 + edge, alphaFar);

    // Continuous inner-rim mask
    float finalAlphaMask = clamp(chokedNear - chokedFar, 0.0, 1.0);

    // Hard-clamp inside original source alpha
    finalAlphaMask *= baseTexel.a;

    float glossyAlpha = finalAlphaMask * clamp(Opacity / 100.0, 0.0, 1.0);

    // Color
    vec3 finalColor = getGlossColor(lightDir);

    // Blend modes
    vec3 blendedColor = finalColor;
    int mode = int(Blend_Mode + 0.5);

    if (mode == 1) blendedColor = blendDarken(baseTexel.rgb, finalColor);
    else if (mode == 2) blendedColor = blendMultiply(baseTexel.rgb, finalColor);
    else if (mode == 3) blendedColor = blendAdd(baseTexel.rgb, finalColor);
    else if (mode == 4) blendedColor = blendLighten(baseTexel.rgb, finalColor);
    else if (mode == 5) blendedColor = blendScreen(baseTexel.rgb, finalColor);
    else if (mode == 6) blendedColor = blendOverlay(baseTexel.rgb, finalColor);
    else if (mode == 7) blendedColor = blendSoftLight(baseTexel.rgb, finalColor);
    else if (mode == 8) blendedColor = blendHardLight(baseTexel.rgb, finalColor);
    else if (mode == 9) blendedColor = blendDifference(baseTexel.rgb, finalColor);

    // Composite
    if (Glossy_Only > 0.5) {
        gl_FragColor = vec4(finalColor, glossyAlpha);
    } else {
        vec3 compositeRGB = mix(baseTexel.rgb, blendedColor, glossyAlpha);
        float compositeAlpha = max(baseTexel.a, glossyAlpha);
        gl_FragColor = vec4(compositeRGB, compositeAlpha);
    }
}

text./plugins/alipfx/shaders/a-halfdots.glsl:
precision highp float;
precision highp int;

// Panzoid Built-ins
uniform sampler2D tDiffuse;
varying vec2 vUv;
varying vec2 vUvScaled;
uniform vec2 uvScale;
uniform vec2 resolution;

// Custom 20 Properties
uniform float Composite;
uniform float Source_Map;
uniform float Dot_Shape;
uniform float Shape_1;
uniform float Shape_2;
uniform float Shape_3;
uniform float Shape_4;
uniform vec3 Fill_Color;
uniform float Dot_Size;
uniform float Grid_Spacing;
uniform float Grid_Angle;
uniform float Dots_Angle;
uniform float Scale;
uniform float Rotate;
uniform float Random_Seed;
uniform float Invert_Pattern;
uniform float Enable_Ramp;
uniform float Ramp_Style;
uniform vec2 Start_Point;
uniform vec2 End_Point;

// Helper: Pseudo-random number generator
float rand(vec2 co) {
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

// Helper: RGB to HSL conversion
vec3 rgb2hsl(vec3 c) {
    float cMin = min(min(c.r, c.g), c.b);
    float cMax = max(max(c.r, c.g), c.b);
    float l = (cMax + cMin) / 2.0;
    float s = 0.0;
    float h = 0.0;
    if (cMax != cMin) {
        float d = cMax - cMin;
        s = l > 0.5 ? d / (2.0 - cMax - cMin) : d / (cMax + cMin);
        if (cMax == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
        else if (cMax == c.g) { h = (c.b - c.r) / d + 2.0; }
        else { h = (c.r - c.g) / d + 4.0; }
        h /= 6.0;
    }
    return vec3(h, s, l);
}

// Helper: Source Map Interpreter
float getSourceVal(vec4 col) {
    int sm = int(Source_Map);
    if (sm == 0) return 1.0; // None
    if (sm == 1) return col.r;
    if (sm == 2) return col.g;
    if (sm == 3) return col.b;
    if (sm == 4) return col.a;
    if (sm == 5) return dot(col.rgb, vec3(0.299, 0.587, 0.114)); // Luminance

    vec3 hsl = rgb2hsl(col.rgb);
    if (sm == 6) return hsl.x; // Hue
    if (sm == 7) return hsl.z; // Lightness
    if (sm == 8) return hsl.y; // Saturation
    if (sm == 9) return max(max(col.r, col.g), col.b); // Full
    if (sm == 10) return (col.r + col.g + col.b) / 3.0; // Half

    return 1.0;
}

// Helper: Ramp Generator (Pixel Space)
float getRamp(vec2 u) {
    if (Enable_Ramp < 0.5) return 1.0;

    vec2 pixelU = u * resolution;
    pixelU.y = resolution.y - pixelU.y;

    vec2 dir = End_Point - Start_Point;
    float len2 = dot(dir, dir);
    if (len2 == 0.0) return 0.5;

    float t = dot(pixelU - Start_Point, dir) / len2;
    int style = int(Ramp_Style);

    if (style == 0) { // Linear
        return clamp(t, 0.0, 1.0);
    } else if (style == 1) { // Radial
        float d = distance(pixelU, Start_Point) / (distance(Start_Point, End_Point) + 0.0001);
        return clamp(1.0 - d, 0.0, 1.0);
    } else if (style == 2) { // Symmetric
        return clamp(1.0 - abs(t * 2.0 - 1.0), 0.0, 1.0);
    } else { // Box (Fixed Logic)
        // Use Start_Point as the true center, distance to End_Point as X/Y bounds
        vec2 extents = abs(End_Point - Start_Point);
        extents = max(extents, vec2(0.001)); // Prevent division by zero

        vec2 d = abs(pixelU - Start_Point) / extents;
        // max(d.x, d.y) gives a perfect square/rectangular fade
        return clamp(1.0 - max(d.x, d.y), 0.0, 1.0);
    }
}

// Helper: SDF Shapes
float getShapeDist(vec2 p, int type) {
    if (type == 0) return length(p); // Circle
    if (type == 1) return max(abs(p.x), abs(p.y)); // Square
    if (type == 2) return abs(p.x) + abs(p.y); // Diamond 
    if (type == 3) { // Love
        vec2 lp = p * 1.3;
        lp.y += 0.2;
        return length(vec2(lp.x, lp.y - 0.5 * sqrt(abs(lp.x)))); 
    }
    if (type == 4) { // Sparkle 
        float ax = abs(p.x);
        float ay = abs(p.y);
        return ax + ay + 2.0 * sqrt(ax * ay);
    }
    return 999.0;
}

void main() {
    // 1. Setup Grid and Aspect Ratio
    vec2 aspect = vec2(resolution.x / resolution.y, 1.0);
    vec2 gridUv = vUv * aspect;

    float ga = radians(Grid_Angle);
    float s = sin(ga), c = cos(ga);
    mat2 rotGrid = mat2(c, -s, s, c);
    gridUv = rotGrid * gridUv;

    float safeSpacing = max(Grid_Spacing, 0.1);
    float density = resolution.x / safeSpacing; 
    vec2 cellP = gridUv * density;

    vec2 cellId = floor(cellP);
    vec2 cellLocal = fract(cellP) - 0.5;

    // 2. Locate center of current cell for sampling
    vec2 centerGrid = (cellId + 0.5) / density;
    mat2 invRotGrid = mat2(c, s, -s, c);
    vec2 sampleUv = (invRotGrid * centerGrid) / aspect;

    vec4 srcColor = texture2D(tDiffuse, sampleUv * uvScale);

    // 3. Obtain the source map data
    float mapVal = getSourceVal(srcColor);
    bool invertShape = false;

    if (Invert_Pattern > 0.5) {
        if (int(Source_Map) != 0) {
            // Invert the size map if an actual source map is selected
            mapVal = 1.0 - mapVal;
        } else {
            // If source map is "None", invert the shape so dots don't vanish
            invertShape = true;
        }
    }

    mapVal *= getRamp(sampleUv); 

    // 4. Dot Processing & Mixing
    int currentShape = int(Dot_Shape);

    if (currentShape >= 5) {
        float rnd = rand(cellId + Random_Seed + 5.5);
        int choice = int(mod(rnd * 4.0, 4.0));

        int shapeChoice = 0;
        if (choice == 0) shapeChoice = int(Shape_1);
        else if (choice == 1) shapeChoice = int(Shape_2);
        else if (choice == 2) shapeChoice = int(Shape_3);
        else shapeChoice = int(Shape_4);

        currentShape = shapeChoice - 1;
    }

    // 5. Transformations
    float r1 = rand(cellId + Random_Seed);
    float r2 = rand(cellId + Random_Seed + 1.23);

    float dAngle = radians(Dots_Angle) + (r1 * 2.0 - 1.0) * radians(Rotate);
    float dS = sin(dAngle), dC = cos(dAngle);
    mat2 rotDot = mat2(dC, -dS, dS, dC);

    vec2 p = rotDot * cellLocal;

    // Convert 0-100 Scale parameter to a 0.0 - 1.0 percentage multiplier
    float normScale = clamp(Scale / 100.0, 0.0, 1.0);

    // Random Scale: Only scale DOWN from the maximum Dot_Size.
    // This guarantees the largest randomly-scaled dots will still fit flawlessly 
    // edge-to-edge without spilling out of their grid cells and clipping.
    float dotScaleFactor = max(1.0 - (r2 * normScale), 0.001);
    p /= dotScaleFactor;

    // 6. Draw Shape
    float d = getShapeDist(p, currentShape);

    float targetSize = (Dot_Size * mapVal) / (safeSpacing * 2.0);
    float aa = 1.0 / safeSpacing; 

    float dotAlpha = smoothstep(targetSize + aa, targetSize - aa, d);
    if (currentShape < 0) dotAlpha = 0.0; 

    if (invertShape) {
        dotAlpha = 1.0 - dotAlpha;
    }

    // 7. Composite
    vec4 orig = texture2D(tDiffuse, vUvScaled);
    int comp = int(Composite);

    if (comp == 0) {
        gl_FragColor = mix(vec4(0.0, 0.0, 0.0, 1.0), vec4(Fill_Color, 1.0), dotAlpha);
    } else if (comp == 1) {
        gl_FragColor = mix(orig, vec4(Fill_Color, 1.0), dotAlpha);
    } else if (comp == 2) {
        gl_FragColor = vec4(Fill_Color, dotAlpha);
    } else {
        gl_FragColor = orig;
    }
}

text./plugins/alipfx/shaders/a-innergradation:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 resolution;
uniform vec2 uvScale;

// -- Core Parameters --
uniform float Inner_Mode;
uniform float Inner_Blur;
uniform vec3 Inner_Fill;
uniform vec3 Fill_Color;
uniform float Size;
uniform float Blend_Mode;
uniform float Softness;
uniform float Choker;
uniform float Opacity;
uniform float Distance;
uniform float Angle;

// -- Color Selections Settings --
uniform float View_All_Selection_Color;
uniform float Split_Touching_Colors;

// -- Selection 1 --
uniform float Enable;
uniform float View_Selection_Only;
uniform vec3 Target_Color;
uniform float Tolerance;
uniform float Use_Local_Transform;
uniform float Local_Distance;
uniform float Local_Angle;

// -- Selection 2 --
uniform float Enable_2;
uniform float View_Selection_Only_2;
uniform vec3 Target_Color_2;
uniform float Tolerance_2;
uniform float Use_Local_Transform_2;
uniform float Local_Distance_2;
uniform float Local_Angle_2;

// -- Selection 3 --
uniform float Enable_3;
uniform float View_Selection_Only_3;
uniform vec3 Target_Color_3;
uniform float Tolerance_3;
uniform float Use_Local_Transform_3;
uniform float Local_Distance_3;
uniform float Local_Angle_3;

// -- Selection 4 --
uniform float Enable_4;
uniform float View_Selection_Only_4;
uniform vec3 Target_Color_4;
uniform float Tolerance_4;
uniform float Use_Local_Transform_4;
uniform float Local_Distance_4;
uniform float Local_Angle_4;

// -- Selection 5 --
uniform float Enable_5;
uniform float View_Selection_Only_5;
uniform vec3 Target_Color_5;
uniform float Tolerance_5;
uniform float Use_Local_Transform_5;
uniform float Local_Distance_5;
uniform float Local_Angle_5;

// -- Selection 6 --
uniform float Enable_6;
uniform float View_Selection_Only_6;
uniform vec3 Target_Color_6;
uniform float Tolerance_6;
uniform float Use_Local_Transform_6;
uniform float Local_Distance_6;
uniform float Local_Angle_6;

// -- Selection 7 --
uniform float Enable_7;
uniform float View_Selection_Only_7;
uniform vec3 Target_Color_7;
uniform float Tolerance_7;
uniform float Use_Local_Transform_7;
uniform float Local_Distance_7;
uniform float Local_Angle_7;

// -- Selection 8 --
uniform float Enable_8;
uniform float View_Selection_Only_8;
uniform vec3 Target_Color_8;
uniform float Tolerance_8;
uniform float Use_Local_Transform_8;
uniform float Local_Distance_8;
uniform float Local_Angle_8;

// -- Selection 9 --
uniform float Enable_9;
uniform float View_Selection_Only_9;
uniform vec3 Target_Color_9;
uniform float Tolerance_9;
uniform float Use_Local_Transform_9;
uniform float Local_Distance_9;
uniform float Local_Angle_9;

// -- Selection 10 --
uniform float Enable_10;
uniform float View_Selection_Only_10;
uniform vec3 Target_Color_10;
uniform float Tolerance_10;
uniform float Use_Local_Transform_10;
uniform float Local_Distance_10;
uniform float Local_Angle_10;

// -- Helper: Photoshop/AE Blend Modes --
vec3 applyBlendMode(vec3 base, vec3 blend, float mode) {
    if (mode < 0.5) return blend; // 0: Normal
    if (mode < 1.5) return clamp(base + blend, 0.0, 1.0); // 1: Add
    if (mode < 2.5) return base * blend; // 2: Multiply
    if (mode < 3.5) return 1.0 - (1.0 - base) * (1.0 - blend); // 3: Screen

    // 4: Overlay
    if (mode < 4.5) {
        vec3 overlay;
        for(int i=0; i<3; i++) {
            overlay[i] = base[i] < 0.5 ? (2.0 * base[i] * blend[i]) : (1.0 - 2.0 * (1.0 - base[i]) * (1.0 - blend[i]));
        }
        return overlay;
    }

    if (mode < 5.5) return min(base, blend); // 5: Darken

    // 6: Hard Light
    vec3 hardLight;
    for(int i=0; i<3; i++) {
        hardLight[i] = blend[i] < 0.5 ? (2.0 * base[i] * blend[i]) : (1.0 - 2.0 * (1.0 - base[i]) * (1.0 - blend[i]));
    }
    return hardLight;
}

// -- Helper: Check which Selection Mask a pixel belongs to --
int getMaskId(vec4 c) {
    if (c.a < 0.01) return -1; // Transparent layer bounds

    if (Enable > 0.5 && distance(c.rgb, Target_Color) <= (Tolerance / 100.0)) return 1;
    if (Enable_2 > 0.5 && distance(c.rgb, Target_Color_2) <= (Tolerance_2 / 100.0)) return 2;
    if (Enable_3 > 0.5 && distance(c.rgb, Target_Color_3) <= (Tolerance_3 / 100.0)) return 3;
    if (Enable_4 > 0.5 && distance(c.rgb, Target_Color_4) <= (Tolerance_4 / 100.0)) return 4;
    if (Enable_5 > 0.5 && distance(c.rgb, Target_Color_5) <= (Tolerance_5 / 100.0)) return 5;
    if (Enable_6 > 0.5 && distance(c.rgb, Target_Color_6) <= (Tolerance_6 / 100.0)) return 6;
    if (Enable_7 > 0.5 && distance(c.rgb, Target_Color_7) <= (Tolerance_7 / 100.0)) return 7;
    if (Enable_8 > 0.5 && distance(c.rgb, Target_Color_8) <= (Tolerance_8 / 100.0)) return 8;
    if (Enable_9 > 0.5 && distance(c.rgb, Target_Color_9) <= (Tolerance_9 / 100.0)) return 9;
    if (Enable_10 > 0.5 && distance(c.rgb, Target_Color_10) <= (Tolerance_10 / 100.0)) return 10;

    return 0; // Global Layer Mask
}

// -- Helper: Check if sampled pixel is INSIDE the current Mask boundary --
bool isInsideMask(vec4 c, int maskId, vec4 centerColor, bool selectionsActive) {
    if (c.a < 0.01) return false;

    // Check Split Touching Colors FIRST. 
    // If active AND selections are enabled, any distinct color change generates a boundary.
    if (Split_Touching_Colors > 0.5 && selectionsActive) {
        if (distance(c.rgb, centerColor.rgb) > 0.015) return false; 
    }

    if (maskId == 1) return (distance(c.rgb, Target_Color) <= (Tolerance / 100.0));
    if (maskId == 2) return (distance(c.rgb, Target_Color_2) <= (Tolerance_2 / 100.0));
    if (maskId == 3) return (distance(c.rgb, Target_Color_3) <= (Tolerance_3 / 100.0));
    if (maskId == 4) return (distance(c.rgb, Target_Color_4) <= (Tolerance_4 / 100.0));
    if (maskId == 5) return (distance(c.rgb, Target_Color_5) <= (Tolerance_5 / 100.0));
    if (maskId == 6) return (distance(c.rgb, Target_Color_6) <= (Tolerance_6 / 100.0));
    if (maskId == 7) return (distance(c.rgb, Target_Color_7) <= (Tolerance_7 / 100.0));
    if (maskId == 8) return (distance(c.rgb, Target_Color_8) <= (Tolerance_8 / 100.0));
    if (maskId == 9) return (distance(c.rgb, Target_Color_9) <= (Tolerance_9 / 100.0));
    if (maskId == 10) return (distance(c.rgb, Target_Color_10) <= (Tolerance_10 / 100.0));

    return true; 
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    int mId = getMaskId(texel);

    bool selectionsActive = (Enable > 0.5 || Enable_2 > 0.5 || Enable_3 > 0.5 || Enable_4 > 0.5 || Enable_5 > 0.5 || 
                             Enable_6 > 0.5 || Enable_7 > 0.5 || Enable_8 > 0.5 || Enable_9 > 0.5 || Enable_10 > 0.5);

    // -- 1. Debug Views (View Masks / Selection Colors) --
    if (View_All_Selection_Color > 0.5) {
        if (mId == 1) { gl_FragColor = vec4(Target_Color, texel.a); return; }
        if (mId == 2) { gl_FragColor = vec4(Target_Color_2, texel.a); return; }
        if (mId == 3) { gl_FragColor = vec4(Target_Color_3, texel.a); return; }
        if (mId == 4) { gl_FragColor = vec4(Target_Color_4, texel.a); return; }
        if (mId == 5) { gl_FragColor = vec4(Target_Color_5, texel.a); return; }
        if (mId == 6) { gl_FragColor = vec4(Target_Color_6, texel.a); return; }
        if (mId == 7) { gl_FragColor = vec4(Target_Color_7, texel.a); return; }
        if (mId == 8) { gl_FragColor = vec4(Target_Color_8, texel.a); return; }
        if (mId == 9) { gl_FragColor = vec4(Target_Color_9, texel.a); return; }
        if (mId == 10) { gl_FragColor = vec4(Target_Color_10, texel.a); return; }

        // Render unselected areas as black with the original alpha bounds
        gl_FragColor = vec4(0.0, 0.0, 0.0, texel.a);
        return;
    }

    // Individual Mask Views (Now renders the Target Color instead of white)
    if (Enable > 0.5 && View_Selection_Only > 0.5) { gl_FragColor = vec4(mId == 1 ? Target_Color : vec3(0.0), texel.a); return; }
    if (Enable_2 > 0.5 && View_Selection_Only_2 > 0.5) { gl_FragColor = vec4(mId == 2 ? Target_Color_2 : vec3(0.0), texel.a); return; }
    if (Enable_3 > 0.5 && View_Selection_Only_3 > 0.5) { gl_FragColor = vec4(mId == 3 ? Target_Color_3 : vec3(0.0), texel.a); return; }
    if (Enable_4 > 0.5 && View_Selection_Only_4 > 0.5) { gl_FragColor = vec4(mId == 4 ? Target_Color_4 : vec3(0.0), texel.a); return; }
    if (Enable_5 > 0.5 && View_Selection_Only_5 > 0.5) { gl_FragColor = vec4(mId == 5 ? Target_Color_5 : vec3(0.0), texel.a); return; }
    if (Enable_6 > 0.5 && View_Selection_Only_6 > 0.5) { gl_FragColor = vec4(mId == 6 ? Target_Color_6 : vec3(0.0), texel.a); return; }
    if (Enable_7 > 0.5 && View_Selection_Only_7 > 0.5) { gl_FragColor = vec4(mId == 7 ? Target_Color_7 : vec3(0.0), texel.a); return; }
    if (Enable_8 > 0.5 && View_Selection_Only_8 > 0.5) { gl_FragColor = vec4(mId == 8 ? Target_Color_8 : vec3(0.0), texel.a); return; }
    if (Enable_9 > 0.5 && View_Selection_Only_9 > 0.5) { gl_FragColor = vec4(mId == 9 ? Target_Color_9 : vec3(0.0), texel.a); return; }
    if (Enable_10 > 0.5 && View_Selection_Only_10 > 0.5) { gl_FragColor = vec4(mId == 10 ? Target_Color_10 : vec3(0.0), texel.a); return; }

    // If completely outside all masks (transparent pixel), process Fill/Original logic and discard shadowing early
    if (mId == -1) {
        if (Inner_Mode > 1.5 && !selectionsActive) gl_FragColor = vec4(Fill_Color, 0.0);
        else if (Inner_Mode > 0.5) gl_FragColor = vec4(0.0);
        else gl_FragColor = texel;
        return;
    }

    // Flag to determine if we should process the effect on this specific pixel
    // If selections are active, we DO NOT process the global image border (mId == 0)
    bool processEffect = !(selectionsActive && mId == 0);

    // -- 2. Determine Transform Settings (Local vs Global) --
    float activeDist = Distance;
    float activeAngle = Angle;

    if (mId == 1 && Use_Local_Transform > 0.5) { activeDist = Local_Distance; activeAngle = Local_Angle; }
    else if (mId == 2 && Use_Local_Transform_2 > 0.5) { activeDist = Local_Distance_2; activeAngle = Local_Angle_2; }
    else if (mId == 3 && Use_Local_Transform_3 > 0.5) { activeDist = Local_Distance_3; activeAngle = Local_Angle_3; }
    else if (mId == 4 && Use_Local_Transform_4 > 0.5) { activeDist = Local_Distance_4; activeAngle = Local_Angle_4; }
    else if (mId == 5 && Use_Local_Transform_5 > 0.5) { activeDist = Local_Distance_5; activeAngle = Local_Angle_5; }
    else if (mId == 6 && Use_Local_Transform_6 > 0.5) { activeDist = Local_Distance_6; activeAngle = Local_Angle_6; }
    else if (mId == 7 && Use_Local_Transform_7 > 0.5) { activeDist = Local_Distance_7; activeAngle = Local_Angle_7; }
    else if (mId == 8 && Use_Local_Transform_8 > 0.5) { activeDist = Local_Distance_8; activeAngle = Local_Angle_8; }
    else if (mId == 9 && Use_Local_Transform_9 > 0.5) { activeDist = Local_Distance_9; activeAngle = Local_Angle_9; }
    else if (mId == 10 && Use_Local_Transform_10 > 0.5) { activeDist = Local_Distance_10; activeAngle = Local_Angle_10; }

    // Convert AE angle to Offset Vector
    float rad = radians(activeAngle);
    vec2 offsetDir = vec2(cos(rad), -sin(rad)) * activeDist / resolution * uvScale;

    // -- 3. Calculate Distance to Edge (Multi-tap Disc Sampling) --
    float minOutsideDist = Size + 1.0;

    if (Size > 0.0 && processEffect) {
        const int SAMPLES = 48; // Excellent balance of precision/performance for up to Size ~100
        for(int i = 0; i < SAMPLES; i++) {
            float fi = float(i);
            float r = sqrt(fi + 0.5) / sqrt(float(SAMPLES)) * Size;
            float theta = fi * 2.3999632; // Golden Angle constant

            vec2 sampUv = vUvScaled - offsetDir + vec2(cos(theta), sin(theta)) * (r / resolution * uvScale);
            vec4 sCol = texture2D(tDiffuse, sampUv);

            // Passed selectionsActive into the function here
            if (!isInsideMask(sCol, mId, texel, selectionsActive)) {
                minOutsideDist = min(minOutsideDist, r);
            }
        }
    } else if (!processEffect) {
        minOutsideDist = Size + 1.0; // Pushes it outside falloff range so shadowAlpha becomes 0
    } else {
        minOutsideDist = 0.0;
    }

    // -- 4. Compute Gradation Falloff --
    float currentEdge = max(0.0, Size - Choker);
    float shadowAlpha = 0.0;

    if (Size > 0.0 && processEffect) {
        if (Inner_Blur > 0.5) {
            // Soft Blur Style
            shadowAlpha = smoothstep(currentEdge, currentEdge - Softness, minOutsideDist);
        } else {
            // Default Blur Style (Linear)
            if (Softness > 0.0) {
                shadowAlpha = clamp(1.0 - (minOutsideDist - (currentEdge - Softness)) / Softness, 0.0, 1.0);
            } else {
                shadowAlpha = minOutsideDist <= currentEdge ? 1.0 : 0.0;
            }
        }
    }

    // Bind by Global Opacity and Pixel Alpha constraint
    shadowAlpha *= (Opacity / 100.0) * texel.a;

    // -- 5. Base Rendering & Inner Modes --
    vec4 baseColor = texel;

    // Fill Color Override Mode (Inactive when Selection is Enabled)
    if (Inner_Mode > 1.5 && !selectionsActive) {
        baseColor.rgb = Fill_Color;
    }

    vec3 blendedRGB = applyBlendMode(baseColor.rgb, Inner_Fill, Blend_Mode);
    vec4 finalColor;

    // Output Mode Composite
    if (Inner_Mode > 0.5 && Inner_Mode < 1.5) {
        // Transparent Mode
        if (!processEffect) {
            finalColor = vec4(0.0); // Keep non-targeted areas transparent in Transparent mode
        } else {
            finalColor = vec4(Inner_Fill, shadowAlpha);
        }
    } else {
        // Original Layer & Fill Modes
        finalColor.rgb = mix(baseColor.rgb, blendedRGB, shadowAlpha);
        finalColor.a = baseColor.a;
    }

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/a-outline.glsl:
precision highp float;
precision highp int;

// Panzoid Built-ins
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 resolution;

// --- Properties Map ---
uniform vec3 Color;
uniform float Size;
uniform vec2 Offset;
uniform float Opacity; // Now expects 0 - 100
uniform float Sharp;
uniform float Long_Shadow;

uniform float Enable_Outline_2;
uniform vec3 Color_Outline_2;
uniform float Size_Outline_2;
uniform vec2 Offset_Outline_2;
uniform float Opacity_Outline_2; // Now expects 0 - 100
uniform float Sharp_Outline_2;
uniform float Long_Shadow_Outline_2;

// --- Premultiplied Alpha Compositing ---
vec4 blend(vec4 top, vec4 bot) {
    return top + bot * (1.0 - top.a);
}

// --- Outline Generation Logic ---
float getAlpha(vec2 uv, float size, vec2 offset, float sharp, float ls) {
    float a = 0.0;
    vec2 px = 1.0 / resolution;

    // Loop steps for Long Shadow extrusion
    // 30 steps gives a buttery smooth continuous shadow
    for(int j = 0; j < 30; j++) {
        // Break early if Long Shadow is disabled to save massive GPU performance
        if (ls < 0.5 && j > 0) break;

        float t = (ls > 0.5) ? float(j) / 29.0 : 1.0;
        vec2 c = uv - offset * px * t; // Offset is converted to pixel space

        // Sample center baseline
        a = max(a, texture2D(tDiffuse, c).a);

        // Sample surrounding radius for "Size"
        if (size > 0.0) {
            // Outer Ring (12 samples)
            for (int i = 0; i < 12; i++) {
                float ang = float(i) * 0.52359877; // 2PI / 12
                a = max(a, texture2D(tDiffuse, c + vec2(cos(ang), sin(ang)) * size * px).a);
            }
            // Inner Ring (6 samples) for structural integrity on thick sizes
            for (int i = 0; i < 6; i++) {
                float ang = float(i) * 1.04719755; // 2PI / 6
                a = max(a, texture2D(tDiffuse, c + vec2(cos(ang), sin(ang)) * size * 0.5 * px).a);
            }
        }
    }

    // Hard clamp edges if Sharp is enabled
    if (sharp > 0.5) {
        a = step(0.01, a);
    }

    return clamp(a, 0.0, 1.0);
}

void main() {
    // WebGL textures (tDiffuse) are inherently premultiplied by default
    vec4 original = texture2D(tDiffuse, vUvScaled);
    vec4 result = vec4(0.0); // Start with transparent empty layer

    // Convert 0-100 Opacity down to 0.0-1.0 range
    float op1 = clamp(Opacity * 0.01, 0.0, 1.0);
    float op2 = clamp(Opacity_Outline_2 * 0.01, 0.0, 1.0);

    // 1. Render Outline 2 (Bottom-most Layer)
    if (Enable_Outline_2 > 0.5 && op2 > 0.0) {
        float a2 = getAlpha(vUvScaled, Size_Outline_2, Offset_Outline_2, Sharp_Outline_2, Long_Shadow_Outline_2);
        a2 = clamp(a2 * op2, 0.0, 1.0);

        // Pre-multiply RGB by Alpha
        result = vec4(Color_Outline_2 * a2, a2);
    }

    // 2. Render Outline 1 (Middle Layer)
    if (op1 > 0.0) {
        float a1 = getAlpha(vUvScaled, Size, Offset, Sharp, Long_Shadow);
        a1 = clamp(a1 * op1, 0.0, 1.0);

        // Pre-multiply RGB by Alpha
        vec4 layer1 = vec4(Color * a1, a1);
        result = blend(layer1, result); // Blend Outline 1 over Outline 2
    }

    // 3. Render Original Input (Top Layer)
    result = blend(original, result); // Blend Original over everything else

    // Final output
    gl_FragColor = result;
}

text./plugins/alipfx/shaders/a-wiggle.glsl:
precision highp float;
precision highp int;

// Built-in Panzoid Uniforms & Varyings
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;
uniform float time; // Panzoid's built-in time variable

// Custom Plugin Properties (17 Parameters)
uniform float Wiggle_Type; // 0 = Smooth Random, 1 = Consistent Amplitude
uniform float Global_Amplitude;
uniform float Global_Frequency;
uniform vec2 Anchor_Point; // In pixels (e.g., 960, 540)

uniform float Pos_Separate_Dimension; // 0 = Disabled, 1 = Enabled
uniform float Pos_X;
uniform float Pos_Freq_X_Mult;
uniform float Pos_Y;
uniform float Pos_Freq_Y_Mult;

uniform float Scale_Separate_Dimension; // 0 = Disabled, 1 = Enabled
uniform float Scale_X;
uniform float Scale_Freq_X_Mult;
uniform float Scale_Y;
uniform float Scale_Freq_Y_Mult;

uniform float Rot_Angle;
uniform float Rot_Freq_Mult;

uniform float Random_Seed;

// --- NOISE & WIGGLE FUNCTIONS ---

// Simple 1D Hash for pseudo-randomness
float hash(float n) { 
    return fract(sin(n) * 1e4); 
}

// 1D Value Noise (Upgraded with Smootherstep)
float noise(float x) {
    float i = floor(x);
    float f = fract(x);

    // Ken Perlin's "Smootherstep" formula for silkier, less mechanical transitions
    float u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);

    return mix(hash(i), hash(i + 1.0), u) * 2.0 - 1.0; // Returns -1.0 to 1.0
}

// Fractal Brownian Motion (Mimics the organic feel of After Effects Wiggle)
float aeWiggleNoise(float x) {
    float v = 0.0;
    float a = 0.5; // Amplitude of the first octave

    // 2 Octaves gives that subtle, organic secondary shake AE is known for
    for (int i = 0; i < 2; ++i) {
        v += a * noise(x);
        x = x * 2.0 + 100.0; // Double the frequency, shift the phase
        a *= 0.5; // Halve the amplitude for the secondary detail
    }

    // Reduced intensity for subtle random shake
    return v * 0.15; 
}

// Core Wiggle Logic
float wiggleVal(float t, float seed, float type) {
    // Offset time using the seed to ensure unique waves for every parameter
    float phaseOffset = seed * 13.753; // Smaller, more predictable offset

    if (type > 0.5) {
        // Type 1: Consistent Amplitude (Sine wave)
        // REDUCED BASE AMPLITUDE: Lowered from 0.25 to 0.12 so the sine wave
        // displacement feels more in line with the random noise displacement.
        return sin((t * 1.57079632679) + phaseOffset) * 0.12; 
    } else {
        // Type 0: Smooth Random (AE-style fBm Noise)
        // The random noise still needs a slightly faster progression to feel like a "shake"
        return aeWiggleNoise(t * 3.0 + phaseOffset); 
    }
}

// --- MAIN RENDER ---

void main() {
    vec2 uv = vUv;
    float aspect = resolution.x / resolution.y;

    // Base time adjusted by Global Frequency
    float t = time * Global_Frequency;
    float amp = Global_Amplitude;

    // 1. CALCULATE WIGGLE OFFSETS

    // Position Offset (in pixels)
    float p_x = 0.0, p_y = 0.0;
    if (Pos_Separate_Dimension > 0.5) {
        p_x = wiggleVal(t * Pos_Freq_X_Mult, Random_Seed + 1.1, Wiggle_Type) * Pos_X * amp;
        p_y = wiggleVal(t * Pos_Freq_Y_Mult, Random_Seed + 1.2, Wiggle_Type) * Pos_Y * amp;
    } else {
        // If not separate, use X values for both, but different seeds so they don't move diagonally
        p_x = wiggleVal(t * Pos_Freq_X_Mult, Random_Seed + 1.1, Wiggle_Type) * Pos_X * amp;
        p_y = wiggleVal(t * Pos_Freq_X_Mult, Random_Seed + 1.2, Wiggle_Type) * Pos_X * amp;
    }

    // Scale Offset (Percentage -> Decimal)
    float s_x = 1.0, s_y = 1.0;
    if (Scale_Separate_Dimension > 0.5) {
        s_x += wiggleVal(t * Scale_Freq_X_Mult, Random_Seed + 2.1, Wiggle_Type) * (Scale_X / 100.0) * amp;
        s_y += wiggleVal(t * Scale_Freq_Y_Mult, Random_Seed + 2.2, Wiggle_Type) * (Scale_Y / 100.0) * amp;
    } else {
        // Uniform scaling applies the exact same randomized value to both X and Y
        float s_uni = wiggleVal(t * Scale_Freq_X_Mult, Random_Seed + 2.1, Wiggle_Type) * (Scale_X / 100.0) * amp;
        s_x += s_uni;
        s_y += s_uni;
    }

    // Prevent scale from hitting exactly 0 to avoid division errors
    if (abs(s_x) < 0.001) s_x = 0.001 * sign(s_x);
    if (abs(s_y) < 0.001) s_y = 0.001 * sign(s_y);

    // Rotation Offset (Degrees -> Radians)
    float r_ang = wiggleVal(t * Rot_Freq_Mult, Random_Seed + 3.1, Wiggle_Type) * Rot_Angle * amp;
    float rad = r_ang * 3.14159265359 / 180.0;

    // 2. APPLY TRANSFORMATIONS (UV Mapping)

    // Convert AE pixel Anchor Point to normalized UV space (0.0 to 1.0)
    vec2 norm_anchor = Anchor_Point / resolution;

    // Adjust for Aspect Ratio so rotation doesn't warp/squash the texture
    uv.x *= aspect;
    norm_anchor.x *= aspect;

    // Move UV origin to the Anchor Point
    uv -= norm_anchor;

    // A. Apply Scale (Shaders read dest -> src, so we divide by scale)
    uv /= vec2(s_x, s_y);

    // B. Apply Rotation (Negative rad applies a clockwise rotation natively)
    float c = cos(-rad);
    float s = sin(-rad);
    mat2 rotMatrix = mat2(c, -s, s, c);
    uv *= rotMatrix;

    // C. Apply Position Translation
    // Convert the pixel offset to normalized space
    vec2 translation = vec2(p_x, p_y) / resolution;
    translation.x *= aspect; // Adjust translation to our aspect-corrected space

    // Subtract translation to move the image layer in the expected direction
    uv -= translation;

    // Restore the UV origin
    uv += norm_anchor;

    // Restore the Aspect Ratio
    uv.x /= aspect;

    // Apply Panzoid's buffer UV scale requirement
    uv *= uvScale;

    // Output final rendered pixel
    gl_FragColor = texture2D(tDiffuse, uv);
}

text./plugins/alipfx/shaders/after-effects-mi:
precision highp float;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUv;

// Parameters matching AE Mirror
uniform vec2 reflectionCenter; // Position in pixels
uniform float reflectionAngle; // Rotation in degrees

void main() {
    // Convert angle to radians
    float angle = radians(reflectionAngle);

    // Convert UV to pixel space
    vec2 uvPx = vUv * resolution;

    // Translate so reflectionCenter is origin
    vec2 centered = uvPx - reflectionCenter;

    // Rotate coordinates by -angle (mirror axis rotation)
    float cosA = cos(-angle);
    float sinA = sin(-angle);
    vec2 rotated = vec2(
        centered.x * cosA - centered.y * sinA,
        centered.x * sinA + centered.y * cosA
    );

    // Mirror horizontally across axis (flip X)
    rotated.x = abs(rotated.x);

    // Rotate back
    vec2 unrotated = vec2(
        rotated.x * cosA + rotated.y * sinA,
        -rotated.x * sinA + rotated.y * cosA
    );

    // Translate back to original space
    vec2 mirroredPx = unrotated + reflectionCenter;

    // Convert back to UV
    vec2 mirroredUV = mirroredPx / resolution;

    // Sample texture
    vec4 color = texture2D(tDiffuse, mirroredUV);
    gl_FragColor = color;
}

text./plugins/alipfx/shaders/analogtv.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
uniform float time;

uniform float Scanline_Intensity;
uniform float Scanline_Width;
uniform float Dot_Mask;
uniform float CRT_Gamma;
uniform float Monitor_Gamma;

uniform float Halation;
uniform float Halation_Threshold;
uniform float Bloom_Threshold;
uniform float Bloom_Intensity;
uniform float Bloom_Radius;

uniform float Red_Offset_X;
uniform float Red_Offset_Y;
uniform float Green_Offset_X;
uniform float Green_Offset_Y;
uniform float Blue_Offset_X;
uniform float Blue_Offset_Y;

uniform float Color_Bleed;
uniform float Noise;
uniform float Jitter;
uniform float Hum_Bar_Strength;
uniform float Hum_Bar_Speed;
uniform float Hum_Bar_Count;

uniform float Corner_Size;
uniform float Barrel;
uniform float Pincushion;
uniform float H_Keystone;
uniform float V_Keystone;

uniform float Expand_Beyond_Layer;
uniform float Exposure;
uniform float Vignette;
uniform float Mix;

varying vec2 vUv;
varying vec2 vUvScaled;

float hash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float hash(vec3 p) {
    p = fract(p * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yzx + 33.33);
    return fract((p.x + p.y) * p.z);
}

vec2 applyGeometry(vec2 uv) {
    vec2 centered = uv - 0.5;
    if (H_Keystone != 0.0) {
        float hFactor = 1.0 + H_Keystone * 0.01 * centered.y;
        centered.x *= hFactor;
    }
    if (V_Keystone != 0.0) {
        float vFactor = 1.0 + V_Keystone * 0.01 * centered.x;
        centered.y *= vFactor;
    }
    if (Barrel != 0.0) {
        float r2 = dot(centered, centered);
        float distortion = 1.0 + Barrel * 0.01 * r2;
        centered *= distortion;
    }
    if (Pincushion != 0.0) {
        float r2 = dot(centered, centered);
        float distortion = 1.0 / (1.0 + Pincushion * 0.01 * r2);
        centered *= distortion;
    }
    return centered + 0.5;
}

float cornerMask(vec2 uv) {
    if (Corner_Size <= 0.0) return 1.0;
    vec2 centered = abs(uv - 0.5);
    float corner = Corner_Size;
    vec2 dist = max(centered + corner - 0.5, 0.0);
    float d = length(dist);
    return 1.0 - smoothstep(0.0, corner, d);
}

vec4 sampleChromatic(vec2 uv) {
    vec2 redOff = vec2(Red_Offset_X, Red_Offset_Y) * 0.001;
    vec2 greenOff = vec2(Green_Offset_X, Green_Offset_Y) * 0.001;
    vec2 blueOff = vec2(Blue_Offset_X, Blue_Offset_Y) * 0.001;
    float r = texture2D(tDiffuse, uv + redOff).r;
    float g = texture2D(tDiffuse, uv + greenOff).g;
    float b = texture2D(tDiffuse, uv + blueOff).b;
    float a = texture2D(tDiffuse, uv).a;
    return vec4(r, g, b, a);
}

vec4 applyColorBleed(vec4 color, vec2 uv) {
    if (Color_Bleed <= 0.0) return color;
    float bleed = Color_Bleed * 0.0015;
    vec4 blurred = vec4(0.0);
    float total = 0.0;
    for (int i = -6; i <= 6; i++) {
        float fi = float(i);
        float weight = exp(-abs(fi) * 0.5);
        blurred += texture2D(tDiffuse, uv + vec2(fi * bleed, 0.0)) * weight;
        total += weight;
    }
    blurred /= total;
    return mix(color, blurred, Color_Bleed * 0.01);
}

vec4 applyBloom(vec4 color, vec2 uv) {
    if (Bloom_Intensity <= 0.0) return color;
    float radius = Bloom_Radius * 0.002;
    vec4 bloom = vec4(0.0);
    float samples = 0.0;
    for (int x = -3; x <= 3; x++) {
        for (int y = -3; y <= 3; y++) {
            vec2 off = vec2(float(x), float(y)) * radius;
            vec4 s = texture2D(tDiffuse, uv + off);
            float bright = dot(s.rgb, vec3(0.299, 0.587, 0.114));
            float thresh = Bloom_Threshold * 0.01;
            if (bright > thresh) {
                bloom += s * (bright - thresh);
            }
            samples += 1.0;
        }
    }
    bloom /= samples;
    return color + bloom * Bloom_Intensity * 0.05;
}

vec4 applyHalation(vec4 color, vec2 uv) {
    if (Halation <= 0.0) return color;
    vec3 halationCol = vec3(0.0);
    float totalWeight = 0.0;
    for (int x = -5; x <= 5; x++) {
        for (int y = -5; y <= 5; y++) {
            vec2 off = vec2(float(x), float(y)) * 0.003;
            vec4 s = texture2D(tDiffuse, uv + off);
            float bright = dot(s.rgb, vec3(0.299, 0.587, 0.114));
            float thresh = Halation_Threshold * 0.01;
            if (bright > thresh) {
                float w = bright - thresh;
                halationCol += vec3(1.0, 0.35, 0.15) * w;
                totalWeight += w;
            }
        }
    }
    if (totalWeight > 0.0) {
        halationCol /= totalWeight;
        color.rgb += halationCol * Halation * 0.015;
    }
    return color;
}

vec4 applyScanlines(vec4 color, vec2 uv) {
    if (Scanline_Intensity <= 0.0) return color;
    float freq = resolution.y / max(Scanline_Width, 0.1);
    float scanline = sin(uv.y * freq * 3.14159);
    float factor = 1.0 - (scanline * 0.5 + 0.5) * Scanline_Intensity * 0.01;
    return vec4(color.rgb * factor, color.a);
}

vec4 applyDotMask(vec4 color, vec2 uv) {
    if (Dot_Mask <= 0.0) return color;
    float x = uv.x * resolution.x;
    float strength = Dot_Mask * 0.01;
    float triad = mod(x, 3.0);
    vec3 mask;
    if (triad < 1.0) {
        mask = vec3(1.0, 0.5, 0.5);
    } else if (triad < 2.0) {
        mask = vec3(0.5, 1.0, 0.5);
    } else {
        mask = vec3(0.5, 0.5, 1.0);
    }
    color.rgb = mix(color.rgb, color.rgb * mask, strength);
    return color;
}

vec4 applyNoise(vec4 color, vec2 uv) {
    if (Noise <= 0.0) return color;
    float n = hash(vec3(uv * resolution, fract(time * 30.0)));
    n = n * 2.0 - 1.0;
    color.rgb += n * Noise * 0.008;
    return color;
}

vec2 applyJitter(vec2 uv) {
    if (Jitter <= 0.0) return uv;

    float jitterAmount = Jitter * 0.001;
    float pixelY = uv.y * resolution.y;
    float frameTime = floor(time * 60.0);

    // 3 frequency layers for realistic analog instability
    float fine   = hash(vec2(floor(pixelY),      frameTime))      * 2.0 - 1.0;
    float medium = hash(vec2(floor(pixelY / 4.0), frameTime * 0.7)) * 2.0 - 1.0;
    float coarse = hash(vec2(floor(pixelY / 16.0), frameTime * 1.3)) * 2.0 - 1.0;

    float displacement = fine * 0.5 + medium * 0.3 + coarse * 0.2;

    // Horizontal displacement only
    return uv + vec2(displacement * jitterAmount, 0.0);
}

vec4 applyHumBars(vec4 color, vec2 uv) {
    if (Hum_Bar_Strength <= 0.0) return color;
    float speed = Hum_Bar_Speed;
    float count = Hum_Bar_Count;
    float strength = Hum_Bar_Strength * 0.01;
    float barPhase = time * speed;
    float barPattern = sin((uv.y + barPhase) * count * 3.14159 * 2.0);
    barPattern = barPattern * 0.5 + 0.5;
    float effect = 1.0 - barPattern * strength;
    return vec4(color.rgb * effect, color.a);
}

vec4 applyVignette(vec4 color, vec2 uv) {
    if (Vignette <= 0.0) return color;
    vec2 centered = uv - 0.5;
    float dist = length(centered) * 1.4142;
    float vig = 1.0 - smoothstep(0.3, 0.85, dist);
    vig = mix(1.0, vig, Vignette * 0.01);
    return vec4(color.rgb * vig, color.a);
}

vec4 applyExposure(vec4 color) {
    if (Exposure == 0.0) return color;
    float factor = pow(2.0, Exposure * 0.1);
    color.rgb *= factor;
    return color;
}

vec4 applyGamma(vec4 color) {
    if (CRT_Gamma > 0.0 && CRT_Gamma != 1.0) {
        color.rgb = pow(max(color.rgb, 0.0), vec3(CRT_Gamma));
    }
    if (Monitor_Gamma > 0.0 && Monitor_Gamma != 1.0) {
        color.rgb = pow(max(color.rgb, 0.0), vec3(1.0 / Monitor_Gamma));
    }
    return color;
}

void main() {
    vec2 uv = vUvScaled;
    uv = applyJitter(uv);
    vec2 distortedUV = applyGeometry(uv);
    bool outOfBounds = distortedUV.x < 0.0 || distortedUV.x > 1.0 || 
                       distortedUV.y < 0.0 || distortedUV.y > 1.0;
    vec4 color = sampleChromatic(distortedUV);
    color = applyColorBleed(color, distortedUV);
    color = applyBloom(color, distortedUV);
    color = applyHalation(color, distortedUV);
    color = applyGamma(color);
    color = applyScanlines(color, distortedUV);
    color = applyDotMask(color, distortedUV);
    color = applyNoise(color, distortedUV);
    color = applyHumBars(color, distortedUV);
    color = applyVignette(color, distortedUV);
    color = applyExposure(color);
    float corner = cornerMask(distortedUV);
    color.rgb *= corner;
    if (outOfBounds && Expand_Beyond_Layer < 0.5) {
        color = vec4(0.0);
    }
    vec4 original = texture2D(tDiffuse, vUvScaled);
    color = mix(original, color, Mix * 0.01);
    gl_FragColor = color;
}

text./plugins/alipfx/shaders/apple-ii-pixelat:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution; // Panzoid's built-in layer resolution

// 16-Color Palette
uniform float Pixel_Size;
vec3 palette[16];

void initPalette() {
    palette[0] = vec3(0.000, 0.000, 0.000); // Black
    palette[1] = vec3(0.890, 0.180, 0.380); // Deep Red
    palette[2] = vec3(0.120, 0.150, 0.600); // Dark Blue
    palette[3] = vec3(0.900, 0.350, 0.900); // Purple
    palette[4] = vec3(0.000, 0.450, 0.150); // Dark Green
    palette[5] = vec3(0.333, 0.333, 0.333); // Dark Gray
    palette[6] = vec3(0.150, 0.660, 0.950); // Medium Blue
    palette[7] = vec3(0.600, 0.750, 1.000); // Light Blue
    palette[8] = vec3(0.500, 0.300, 0.000); // Brown
    palette[9] = vec3(1.000, 0.400, 0.000); // Orange
    palette[10]= vec3(0.666, 0.666, 0.666); // Light Gray
    palette[11]= vec3(1.000, 0.600, 0.600); // Pink
    palette[12]= vec3(0.100, 0.900, 0.100); // Light Green
    palette[13]= vec3(1.000, 0.900, 0.000); // Yellow
    palette[14]= vec3(0.300, 0.900, 0.700); // Aqua
    palette[15]= vec3(1.000, 1.000, 1.000); // White
}

// 4x4 Bayer Dither Matrix Generator (Optimized for pixel chunks)
float getBayer(vec2 p) {
    vec2 v = mod(p, 4.0);
    float f = 0.0;
    if (v.y < 1.0) {
        if (v.x < 1.0) f=0.0; else if (v.x < 2.0) f=8.0; else if (v.x < 3.0) f=2.0; else f=10.0;
    } else if (v.y < 2.0) {
        if (v.x < 1.0) f=12.0; else if (v.x < 2.0) f=4.0; else if (v.x < 3.0) f=14.0; else f=6.0;
    } else if (v.y < 3.0) {
        if (v.x < 1.0) f=3.0; else if (v.x < 2.0) f=11.0; else if (v.x < 3.0) f=1.0; else f=9.0;
    } else {
        if (v.x < 1.0) f=15.0; else if (v.x < 2.0) f=7.0; else if (v.x < 3.0) f=13.0; else f=5.0;
    }
    return f / 16.0 - 0.5; 
}

// Perceptual distance for color matching
float colorDist(vec3 c1, vec3 c2) {
    vec3 diff = c1 - c2;
    vec3 weights = vec3(0.299, 0.587, 0.114);
    diff = diff * diff * weights;
    return diff.x + diff.y + diff.z;
}

vec3 quantize(vec3 color) {
    vec3 closest = palette[0];
    float minDist = 999.0;
    for(int i = 0; i < 16; i++) {
        float d = colorDist(color, palette[i]);
        if(d < minDist) { minDist = d; closest = palette[i]; }
    }
    return closest;
}

void main() {
    initPalette();

    // --- CONFIGURATION ---
    // Increase this number to make the pixels chunkier!
    // Try 2.0, 4.0, or 6.0
    float pixelSize = Pixel_Size; 
    // ---------------------

    // Calculate how many chunky "blocks" fit on the screen
    vec2 grid = resolution / pixelSize;

    // Snap the UV coordinates to that grid
    vec2 pixelatedUv = floor(vUv * grid) / grid;

    // Sample the video layer at those pixelated coordinates
    vec4 texel = texture2D(tDiffuse, pixelatedUv * uvScale);
    vec3 color = texel.rgb;

    // Contrast boost to ensure vibrant retro color mapping
    color = (color - 0.5) * 1.3 + 0.5;

    // Calculate the Bayer dither mapping to the chunky pixel grid
    // This ensures the dither pattern scales properly with your pixel size
    float ditherVal = getBayer(floor(vUv * grid));

    // Apply the dither spread
    color += ditherVal * 0.4;

    // Snap to the closest Apple II color
    vec3 finalColor = quantize(clamp(color, 0.0, 1.0));

    // Output to Panzoid
    gl_FragColor = vec4(finalColor, texel.a);
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

// Custom Property: You will need to create a Dynamic Number property named "Pixel_Size"
uniform float Pixel_Size;

void main() {
    // 1. Setup fallback to prevent divide-by-zero crashes if Pixel_Size is set to 0
    float pSize = max(Pixel_Size, 2.0);

    // 2. Pixelation (Mosaic Effect)
    // Divide the screen into blocks based on resolution and user's Pixel_Size
    vec2 pixelCoord = floor(vUv * resolution / pSize) * pSize;
    vec2 pixelatedUv = pixelCoord / resolution;

    // Apply Panzoid's UV scaling to the newly pixelated UV map
    vec2 sampleUv = pixelatedUv * uvScale;

    // Sample the original texture footage at the pixelated coordinates
    vec4 texel = texture2D(tDiffuse, sampleUv);
    vec3 col = texel.rgb;

    // 3. Simulated CRT Dithering / Artifacting
    // Adds a slight checkerboard noise pattern to push border colors into alternating pixels
    vec2 ditherCoord = floor(vUv * resolution / pSize);
    float dither = (mod(ditherCoord.x + ditherCoord.y, 2.0) - 0.5) * 0.15;
    col += dither;

    // 4. Apple II HGR 6-Color Palette
    vec3 c_black  = vec3(0.00, 0.00, 0.00);
    vec3 c_white  = vec3(1.00, 1.00, 1.00);
    vec3 c_green  = vec3(0.08, 0.89, 0.22);
    vec3 c_violet = vec3(0.89, 0.22, 0.89);
    vec3 c_orange = vec3(0.96, 0.44, 0.11);
    vec3 c_blue   = vec3(0.11, 0.66, 0.96);

    // 5. Color Quantization (Nearest Neighbor Mapping)
    // Finds which Apple II color is mathematically closest to the current original pixel
    vec3 outColor = c_black;
    float minDist = distance(col, c_black);

    float d = distance(col, c_white);
    if(d < minDist) { minDist = d; outColor = c_white; }

    d = distance(col, c_green);
    if(d < minDist) { minDist = d; outColor = c_green; }

    d = distance(col, c_violet);
    if(d < minDist) { minDist = d; outColor = c_violet; }

    d = distance(col, c_orange);
    if(d < minDist) { minDist = d; outColor = c_orange; }

    d = distance(col, c_blue);
    if(d < minDist) { minDist = d; outColor = c_blue; }

    // Output the final mapped color, preserving original alpha transparency
    gl_FragColor = vec4(outColor, texel.a);
}

text./plugins/alipfx/shaders/ascii.glsl:
precision highp float;
precision highp int;

// Panzoid built-in uniforms
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// Custom Uniforms (configured as float uniforms in Panzoid)
uniform float Charset;
uniform float Detail_columns;
uniform float Font_Size;
uniform float Line_Height;
uniform float Character_Aspect;
uniform float Contrast;
uniform float Brightness;
uniform float Invert;
uniform float Transparent_Background;
uniform float Color_From_Image;
uniform vec3 Text_Color;

// Helper to get powers of 2 for cross-platform WebGL 1.0 bit extraction
float getBitPower(int index) {
    if (index == 0) return 1.0;
    if (index == 1) return 2.0;
    if (index == 2) return 4.0;
    if (index == 3) return 8.0;
    if (index == 4) return 16.0;
    if (index == 5) return 32.0;
    if (index == 6) return 64.0;
    if (index == 7) return 128.0;
    if (index == 8) return 256.0;
    if (index == 9) return 512.0;
    if (index == 10) return 1024.0;
    if (index == 11) return 2048.0;
    if (index == 12) return 4096.0;
    if (index == 13) return 8192.0;
    return 16384.0; // index == 14
}

// Function that returns the packed 3x5 font pixel grid mask
int getGlyphMask(int charsetType, float luma, int cellX, int cellY) {
    if (luma < 0.05) return 0; // Blank for dark pixels

    if (charsetType == 0) { // 0: Standard
        int idx = int(luma * 7.99);
        if (idx == 0) return 8192;  // .
        if (idx == 1) return 1040;  // :
        if (idx == 2) return 448;   // -
        if (idx == 3) return 1488;  // +
        if (idx == 4) return 2728;  // *
        if (idx == 5) return 21653; // X
        if (idx == 6) return 24441; // #
        return 33647;               // 0
    }
    else if (charsetType == 1) { // 1: Dense
        int idx = int(luma * 10.99);
        if (idx == 0) return 8192;  // .
        if (idx == 1) return 1040;  // :
        if (idx == 2) return 448;   // -
        if (idx == 3) return 1488;  // +
        if (idx == 4) return 3640;  // =
        if (idx == 5) return 2728;  // *
        if (idx == 6) return 21653; // X
        if (idx == 7) return 24441; // #
        if (idx == 8) return 33647; // 0
        return 32767;               // Full solid block
    }
    else if (charsetType == 2) { // 2: Minimal
        int idx = int(luma * 4.99);
        if (idx == 0) return 8192;  // .
        if (idx == 1) return 1488;  // +
        if (idx == 2) return 24441; // #
        if (idx == 3) return 33647; // 0
        return 32767;               // Full solid block
    }
    else if (charsetType == 3) { // 3: Blocks
        int idx = int(luma * 4.99);
        if (idx == 0) return 4369;  // Sparse dots
        if (idx == 1) return 21845; // Light dither
        if (idx == 2) return 10922; // Medium dither
        if (idx == 3) return 27305; // Heavy dither
        return 32767;               // Full solid block
    }
    else if (charsetType == 4) { // 4: Retro (Procedural Source Code lines)
        // Fixed WebGL 1.0 integer modulo limitation
        int wordCycle = int(mod(floor(float(cellX) / 6.0), 5.0));
        int charIdx = int(mod(float(cellX), 6.0));

        if (wordCycle == 0) { // "class"
            if (charIdx == 0) return 29311; // c
            if (charIdx == 1) return 29193; // l
            if (charIdx == 2) return 31247; // a
            if (charIdx == 3) return 31111; // s
            if (charIdx == 4) return 31111; // s
            return 0;
        }
        if (wordCycle == 1) { // "void "
            if (charIdx == 0) return 18949; // v
            if (charIdx == 1) return 33647; // o
            if (charIdx == 2) return 9362;  // i
            if (charIdx == 3) return 33647; // d
            return 0;
        }
        if (wordCycle == 2) { // "main()"
            if (charIdx == 0) return 24441; // m
            if (charIdx == 1) return 31247; // a
            if (charIdx == 2) return 9362;  // i
            if (charIdx == 3) return 29311; // n
            if (charIdx == 4) return 4802;  // (
            return 8720;                    // )
        }
        if (wordCycle == 3) { // "float"
            if (charIdx == 0) return 31239; // f
            if (charIdx == 1) return 29193; // l
            if (charIdx == 2) return 33647; // o
            if (charIdx == 3) return 31247; // a
            if (charIdx == 4) return 4714;  // t
            return 0;
        }
        // "vec4"
        if (charIdx == 0) return 18949; // v
        if (charIdx == 1) return 31239; // e
        if (charIdx == 2) return 29311; // c
        if (charIdx == 3) return 24441; // 4
        return 0;
    }
    else { // 5: Binary (0 and 1 stream)
        if (mod(float(cellX + cellY), 2.0) == 0.0) {
            return 33647; // 0
        } else {
            return 9362;  // 1
        }
    }
}

void main()
{
    float screenAspect = resolution.x / resolution.y;

    // Fallback safe limits
    float cols = max(Detail_columns, 1.0);
    float charAspect = max(Character_Aspect, 0.1);

    // Normalization logic if user provides percent notation instead of scale factor
    float lineHeight = max(Line_Height, 0.1);
    if (lineHeight > 5.0) lineHeight /= 100.0;

    float normContrast = Contrast;
    if (normContrast > 5.0) normContrast /= 100.0;

    float normBrightness = Brightness;
    if (abs(normBrightness) > 2.0) normBrightness /= 100.0;

    // Calculate precise grid sizes in normalized coordinates
    float cellW = 1.0 / cols;
    float cellH = cellW * charAspect * screenAspect * lineHeight;

    // Locate the current tile
    vec2 cellIndex = floor(vUvScaled / vec2(cellW, cellH));
    vec2 cellCenterUV = (cellIndex + 0.5) * vec2(cellW, cellH);

    // Fixed clamp limitation for WebGL 1.0
    cellCenterUV = vec2(clamp(cellCenterUV.x, 0.0, 1.0), clamp(cellCenterUV.y, 0.0, 1.0));

    // Sample texture source color
    vec4 texel = texture2D(tDiffuse, cellCenterUV);

    // Calculate contrast and brightness updated luminance
    float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114));
    luma = (luma - 0.5) * normContrast + 0.5 + normBrightness;
    luma = clamp(luma, 0.0, 1.0);

    if (Invert > 0.5) {
        luma = 1.0 - luma;
    }

    // Local internal coordinate [0.0, 1.0] inside the cell
    vec2 localUV = fract(vUvScaled / vec2(cellW, cellH));

    // Scale handling for font size (Accepts both absolute pixel width or scale ratio)
    float cellWidthPixels = resolution.x / cols;
    float glyphScale = Font_Size;
    if (glyphScale > 2.0) {
        glyphScale = glyphScale / cellWidthPixels;
    }
    glyphScale = max(glyphScale, 0.05);

    // Map local coordinates into centered glyph bounding box
    vec2 glyphUV = (localUV - 0.5) / glyphScale + 0.5;

    bool isTextPixel = false;

    if (glyphUV.x >= 0.0 && glyphUV.x <= 1.0 && glyphUV.y >= 0.0 && glyphUV.y <= 1.0) {
        int px = int(glyphUV.x * 3.0);
        int py = int((1.0 - glyphUV.y) * 5.0); // Flip Y vector for font tracking top-to-bottom

        // Fixed clamp integer limitation for WebGL 1.0
        px = int(clamp(float(px), 0.0, 2.0));
        py = int(clamp(float(py), 0.0, 4.0));

        int bitIndex = py * 3 + px;
        int mask = getGlyphMask(int(Charset), luma, int(cellIndex.x), int(cellIndex.y));

        float p = getBitPower(bitIndex);
        isTextPixel = mod(floor(float(mask) / p), 2.0) >= 1.0;
    }

    // Output assignment based on options mapping
    vec3 finalColor = vec3(0.0);
    float finalAlpha = 1.0;

    if (isTextPixel) {
        if (Color_From_Image > 0.5) {
            finalColor = texel.rgb;
        } else {
            finalColor = Text_Color;
        }
    } else {
        if (Transparent_Background > 0.5) {
            finalAlpha = 0.0;
        } else {
            finalColor = vec3(0.0);
        }
    }

    gl_FragColor = vec4(finalColor, finalAlpha);
}

text./plugins/alipfx/shaders/az-bend-it.glsl:
// Panzoid CM3 – CC Bend It–style shader
precision highp float;
precision highp int;

// Panzoid built-ins
uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
varying vec2 vUv;
varying vec2 vUvScaled;

// User properties (create these in Panzoid as dynamic properties)
uniform float Bend;              // degrees, positive bends "towards +v"
uniform vec2 Start;              // pixels
uniform vec2 End;                // pixels
uniform float Render_Prestart;   // enum as float: 0=None, 1=Static, 2=Bend, 3=Mirror
uniform float Distort;           // enum as float: 0=Legal, 1=Extended

// ---- Helpers ---------------------------------------------------------------

const float PI = 3.14159265358979323846;

int toMode(float v) { return int(floor(v + 0.5)); }

vec2 toScaledUV(vec2 pixel) {
    // Map a pixel-space coordinate to buffer UV, honoring Panzoid's uvScale.
    return (pixel / resolution) * uvScale;
}

bool inUnit(vec2 uv) {
    return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0;
}

// Distort sampling behavior:
//  - Legal (0): crop both X and Y; outside -> transparent
//  - Extended (1): crop X only; clamp Y; outside X -> transparent
vec4 sampleWithDistort(vec2 uv, int dMode) {
    if (dMode == 0) {
        // Legal
        if (!inUnit(uv)) return vec4(0.0);
        return texture2D(tDiffuse, uv);
    } else {
        // Extended
        if (uv.x < 0.0 || uv.x > 1.0) return vec4(0.0);
        float yClamped = clamp(uv.y, 0.0, 1.0);
        return texture2D(tDiffuse, vec2(uv.x, yClamped));
    }
}

// ---- Core bend math --------------------------------------------------------
//
// We bend a "sheet" along the line from Start to End.
// Axis unit: u. Perpendicular unit: v = rotate90(u).
// Param x = dot(p-Start, u)  : along the axis
//      y = dot(p-Start, v)  : perpendicular to axis
//
// For 0 <= x <= L, map to a circular arc with radius R = L / theta,
// where theta = radians(Bend). The base point follows the arc,
// and the sheet offset y moves along the local normal.
//
// For x > L, we continue straight along the end tangent (t̂ = [cosθ, sinθ])
// For x < 0, behavior depends on Render_Prestart mode:
//    0 None   : crop (transparent)
//    1 Static : sample original (no bend)
//    2 Bend   : continue arc backwards (φ negative)
//    3 Mirror : mirror about Start (use x' = |x|)

void main() {
    // Early exit when layer or handles degenerate
    vec2 p = vUv * resolution;

    vec2 axis = End - Start;
    float L = length(axis);
    if (L < 1e-6) {
        // No axis -> pass-through
        gl_FragColor = texture2D(tDiffuse, vUvScaled);
        return;
    }

    // Build local frame
    vec2 u = axis / L;
    vec2 v = vec2(-u.y, u.x);

    // Coordinates in local (u,v) frame
    vec2 q = p - Start;
    float x = dot(q, u);
    float y = dot(q, v);

    // Read modes
    int rMode = toMode(Render_Prestart);
    int dMode = toMode(Distort);

    // Bend angle in radians
    float theta = radians(Bend);
    // Near-zero bend -> straight
    bool noBend = abs(theta) < 1e-6;

    // Handle prestart "None" (crop) before we do any heavy math
    if (x < 0.0 && rMode == 0) {
        gl_FragColor = vec4(0.0);
        return;
    }

    // Handle prestart "Static" (no bending before Start)
    if (x < 0.0 && rMode == 1) {
        // Sample original pixel (unwarped)
        gl_FragColor = texture2D(tDiffuse, vUvScaled);
        return;
    }

    // Straight pass-through if no bend at all
    if (noBend) {
        // For Mirror mode (prestart), reflect x<0 to x>=0 in sampling? AE keeps straight.
        // We'll just pass-through for simplicity (closest to AE when Bend=0).
        gl_FragColor = texture2D(tDiffuse, vUvScaled);
        return;
    }

    // Arc radius. Sign of theta determines direction.
    float R = L / theta;

    // Local tangent and normal at a given φ
    // t̂(φ) = (cosφ)u + (sinφ)v
    // n̂(φ) = (-sinφ)u + (cosφ)v
    // Base arc point in global coords:
    // base(φ) = Start + u*(R*sinφ) + v*(R*(1 - cosφ))

    float phi; // effective bend angle at this x

    if (x <= L && x >= 0.0) {
        // Between Start and End: map to arc proportionally
        phi = theta * (x / L);
    } else if (x > L) {
        // Past End: use end tangent continuation (φ = θ)
        phi = theta;
    } else { // x < 0
        if (rMode == 2) {
            // Bend: continue arc backwards (φ negative)
            phi = theta * (x / L);
        } else if (rMode == 3) {
            // Mirror: reflect about Start
            phi = theta * (abs(x) / L);
            x = abs(x);
        } else {
            // Shouldn't reach here (None/Static handled above)
            phi = theta * (x / L);
        }
    }

    // Compute base point on arc at φ
    vec2 base = Start + u * (R * sin(phi)) + v * (R * (1.0 - cos(phi)));

    // Tangent and normal at φ
    vec2 tHat = u * cos(phi) + v * sin(phi);
    vec2 nHat = -u * sin(phi) + v * cos(phi);

    vec2 pWarp;

    if (x <= L && x >= 0.0) {
        // Within the handles: along the arc + local normal offset
        pWarp = base + y * nHat;
    } else if (x > L) {
        // Past End: straight continuation along end tangent, normal carries y
        pWarp = base + (x - L) * tHat + y * nHat;
    } else { // x < 0
        if (rMode == 2 || rMode == 3) {
            // Bent or Mirrored prestart: arc + normal (already set phi/x above)
            pWarp = base + y * nHat;
        } else {
            // Fallback (should not occur): transparent
            gl_FragColor = vec4(0.0);
            return;
        }
    }

    // Sample with Distort behavior
    vec2 uvSample = toScaledUV(pWarp);
    vec4 texel = sampleWithDistort(uvSample, dMode);

    gl_FragColor = texel;
}

text./plugins/alipfx/shaders/az-bender.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

uniform float Bend;            // Bend intensity
uniform int Style;             // 1=Bend, 2=Marilyn, 3=Sharp, 4=Boxer
uniform int AdjustToDistance;  // 0=off, 1=on
uniform vec2 Top;              // Top position
uniform vec2 Base;             // Base position

#define PI 3.141592653589793

vec4 samplePix(vec2 uv) {
    return texture2D(tDiffuse, uv);
}

vec2 applyDistortion(vec2 uv) {
    vec2 pos = uv * resolution;

    if (pos.y < Base.y) return uv;

    float range = Top.y - Base.y;
    float t = (pos.y - Base.y) / max(range, 1.0);

    float bendFactor = Bend * 0.02; // Softer bend globally
    if (AdjustToDistance == 1) {
        bendFactor *= range / resolution.y;
    }

    float offset = 0.0;
    if (Style == 1) { // Bend
        offset = bendFactor * t;
    } else if (Style == 2) { // Marilyn (AE-like)
        offset = bendFactor * (sin(t * PI) * 1.2);
    } else if (Style == 3) { // Sharp (AE-like, sharper than Marilyn)
        float sharpCurve = sin((t - 0.5) * PI * 3.0);
        sharpCurve = clamp(sharpCurve, -1.0, 1.0);
        offset = bendFactor * sharpCurve * 1.5;
    } else if (Style == 4) { // Boxer (AE-like)
        offset = bendFactor * (pow(t, 1.5) * 0.8);
    }

    pos.x += offset * (resolution.x * 0.05);

    return pos / resolution;
}

void main() {
    vec2 uv = vUvScaled;
    vec2 distortedUV = applyDistortion(uv);
    gl_FragColor = samplePix(distortedUV);
}

text./plugins/alipfx/shaders/az-blobbylize.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

uniform float Property;   // 1:R, 2:G, 3:B, 4:A, 5:Luma, 6:Lightness
uniform float Softness;   // Single slider: controls fusion + displacement
uniform float CutAway;    // AE-style 0..100 or normalized 0..1

varying vec2 vUvScaled;

float getChannel(vec4 c) {
    int p = int(Property + 0.1);
    if (p == 1) return c.r;
    if (p == 2) return c.g;
    if (p == 3) return c.b;
    if (p == 4) return c.a;
    if (p == 5) return dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
    if (p == 6) {
        float mx = max(max(c.r,c.g), c.b);
        float mn = min(min(c.r,c.g), c.b);
        return 0.5 * (mx + mn);
    }
    return c.a;
}

float srcField(vec2 uv) { return getChannel(texture2D(tDiffuse, uv)); }

float fixedBlur(vec2 uv) {
    vec2 texel = 1.0 / resolution;
    float sum = 0.0, wsum = 0.0;
    for (int x = -2; x <= 2; ++x)
    for (int y = -2; y <= 2; ++y) {
        vec2 o = vec2(float(x), float(y));
        float w = exp(-dot(o,o) * 0.35);
        sum  += getChannel(texture2D(tDiffuse, uv + o * texel)) * w;
        wsum += w;
    }
    return sum / wsum;
}

float blobField(vec2 uv) {
    if (Softness <= 0.0) return srcField(uv);
    float s = clamp(Softness, 0.0, 100.0);
    float fuse = 1.0 - exp(-s * 0.06);
    return mix(srcField(uv), fixedBlur(uv), fuse);
}

vec3 fieldNormal(vec2 uv, float h) {
    vec2 texel = 1.0 / resolution;
    float hx = blobField(uv + vec2(texel.x, 0.0)) - h;
    float hy = blobField(uv + vec2(0.0, texel.y)) - h;
    return normalize(vec3(-hx * 28.0, -hy * 28.0, 1.0));
}

float normalizeCut(float c) { return (c > 1.0) ? clamp(c * 0.01, 0.0, 1.0) : clamp(c, 0.0, 1.0); }

void main() {
    vec2 uv = vUvScaled;
    float h = blobField(uv);
    float cut = normalizeCut(CutAway);
    float feather = 0.004;

    float mask = (CutAway <= 0.001) ? 1.0 : smoothstep(cut - feather, cut + feather, h);
    if (mask <= 0.0) {
        gl_FragColor = texture2D(tDiffuse, uv);
        return;
    }

    // Strong displacement even at Softness = 20
    float heightFactor = clamp(Softness * 0.05, 0.0, 5.0); // more aggressive scaling

    // Displacement for blob depth
    vec3 N = fieldNormal(uv, h);
    vec2 displacedUV = uv + N.xy * heightFactor * 0.002;
    vec4 src = texture2D(tDiffuse, displacedUV);

    // AE-style shading: darken for contour
    vec3 L = normalize(vec3(-0.55, -0.75, 1.0));
    float diff = max(dot(N, L), 0.0);
    vec3 shading = vec3(1.0 - diff * 0.3);

    vec3 outRgb = mix(src.rgb, src.rgb * shading, mask);
    float outA = src.a;

    gl_FragColor = vec4(outRgb, outA);
}

text./plugins/alipfx/shaders/az-block-load.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

// Dynamic Properties
uniform float Completion;
uniform float Scans;

// Checkbox Properties
uniform bool Start_Cleared;
uniform bool Bilinear;

// Function to handle soft/bilinear block blending
vec4 getBilinearBlock(vec2 uv, vec2 pixelSize) {
    vec2 st = uv / pixelSize - 0.5;
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Get the centers of the 4 nearest blocks
    vec2 p00 = clamp((i + vec2(0.5, 0.5)) * pixelSize, 0.0, 1.0) * uvScale;
    vec2 p10 = clamp((i + vec2(1.5, 0.5)) * pixelSize, 0.0, 1.0) * uvScale;
    vec2 p01 = clamp((i + vec2(0.5, 1.5)) * pixelSize, 0.0, 1.0) * uvScale;
    vec2 p11 = clamp((i + vec2(1.5, 1.5)) * pixelSize, 0.0, 1.0) * uvScale;

    // Sample the textures at those block centers
    vec4 col00 = texture2D(tDiffuse, p00);
    vec4 col10 = texture2D(tDiffuse, p10);
    vec4 col01 = texture2D(tDiffuse, p01);
    vec4 col11 = texture2D(tDiffuse, p11);

    // Interpolate the colors
    return mix(mix(col00, col10, f.x), mix(col01, col11, f.x), f.y);
}

// Function to resolve what the image looks like at a specific "Scan Pass"
vec4 getColorForPass(float pass) {
    float S = max(1.0, floor(Scans)); // Ensure at least 1 pass

    // If the pass has exceeded the scan count, it is perfectly loaded
    if (pass >= S) {
        return texture2D(tDiffuse, vUvScaled);
    }

    // Initial unloaded state
    if (pass <= 0.0) {
        if (Start_Cleared) {
            return vec4(0.0); // Completely invisible
        }
        // If Start_Cleared is false, do not return early! 
        // Let it fall through to generate the massive blocks.
    }

    // Calculate the block size dynamically based on how many passes are left
    // We clamp the pass to 0.0 so negative passes don't break the math
    float blocksLeft = S - max(pass, 0.0);
    float blockSize = pow(2.0, blocksLeft + 2.0); // e.g., 32x32 -> 16x16 -> 8x8 -> Clear

    // Create the pixel grid relative to the current buffer resolution
    vec2 pixelSize = max(vec2(1.0) / resolution, blockSize / resolution);

    if (Bilinear) {
        return getBilinearBlock(vUv, pixelSize);
    } else {
        // Nearest neighbor snap (sharp edges)
        vec2 blockUv = floor(vUv / pixelSize) * pixelSize + (pixelSize * 0.5);
        return texture2D(tDiffuse, clamp(blockUv, 0.0, 1.0) * uvScale);
    }
}

void main() {
    // Normalize completion from 0-100 down to 0.0-1.0
    float comp = clamp(Completion / 100.0, 0.0, 1.0);
    float S = max(1.0, floor(Scans));

    // Map total completion against the number of defined scans
    float scan_progress = comp * S;

    // Determine the current full pass index, and how far along the vertical sweep we are
    float current_pass = floor(scan_progress);
    float y_progress = fract(scan_progress);

    float active_pass = current_pass;

    // AE's CC Block Load sweeps vertically from Top to Bottom
    // vUv.y is 1.0 at the top, 0.0 at the bottom.
    // If the fragment is above the sweeping threshold, it advances to the next pass
    if (vUv.y > 1.0 - y_progress) {
        active_pass += 1.0;
    }

    // Output the computed block load fragment
    gl_FragColor = getColorForPass(active_pass);
}

text./plugins/alipfx/shaders/az-bubbles.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// Panzoid custom properties
uniform float Bubble_Amount;
uniform float Bubble_Speed;
uniform float Wobble_Amplitude;
uniform float Wobble_Frequency;
uniform float Bubble_Size;
uniform float Reflection_Type; // 0 = Liquid, 1 = Metal
uniform float Shading_Type;    // 0=None, 1=Lighten, 2=Darken, 3=Fade Inwards, 4=Fade Outwards
uniform float time;

const int MAX_BUBBLES = 180;
const float TAU = 6.28318530717958647692;

float saturate(float x) {
    return clamp(x, 0.0, 1.0);
}

vec2 safeUV(vec2 uv) {
    return clamp(uv, vec2(0.0), vec2(1.0));
}

vec4 sampleScene(vec2 uv) {
    return texture2D(tDiffuse, safeUV(uv) * uvScale);
}

float hash11(float p) {
    return fract(sin(p * 127.1) * 43758.5453123);
}

vec4 blendBubble(vec4 underCol, vec3 bubbleCol, float alpha, float shadingType) {
    vec4 result = underCol;

    if (shadingType < 0.5) {
        // None
        result.rgb = mix(result.rgb, bubbleCol, alpha);
        result.a = max(result.a, alpha);
        return result;
    }

    if (shadingType < 1.5) {
        // Lighten
        vec3 mixedCol = mix(result.rgb, bubbleCol, alpha);
        result.rgb = max(result.rgb, mixedCol);
        result.a = max(result.a, alpha);
        return result;
    }

    if (shadingType < 2.5) {
        // Darken
        vec3 mixedCol = mix(result.rgb, bubbleCol, alpha);
        result.rgb = min(result.rgb, mixedCol);
        result.a = max(result.a, alpha);
        return result;
    }

    // Fade Inwards / Fade Outwards
    result.rgb = mix(result.rgb, bubbleCol, alpha);
    result.a = max(result.a, alpha);
    return result;
}

void main() {
    vec2 uv = vUv;
    vec4 baseCol = sampleScene(uv);
    vec4 outCol = baseCol;

    float aspect = resolution.x / max(resolution.y, 1.0);
    float bubbleCount = clamp(Bubble_Amount, 0.0, float(MAX_BUBBLES));

    float speed = Bubble_Speed * 0.10;
    float wobbleAmpUV = Wobble_Amplitude / max(resolution.x, 1.0);
    float wobbleFreq = max(Wobble_Frequency, 0.0);
    float baseRadiusUV = max(Bubble_Size, 0.1) / max(resolution.y, 1.0);

    vec2 lightDir = normalize(vec2(-0.6, 0.8));
    vec2 darkDir  = normalize(vec2(0.7, -0.5));

    for (int i = 0; i < MAX_BUBBLES; i++) {
        if (float(i) >= bubbleCount) break;

        float fi = float(i) + 1.0;

        float s1 = hash11(fi * 1.371);
        float s2 = hash11(fi * 2.913);
        float s3 = hash11(fi * 5.127);
        float s4 = hash11(fi * 7.411);

        float x0 = s1;
        float y0 = s2;
        float sizeVar = mix(0.78, 1.22, s3);
        float r = baseRadiusUV * sizeVar;

        float y = fract(y0 + time * speed);
        float phase = s4 * TAU;

        float wobble = 0.0;
        wobble += sin((time * wobbleFreq + y * 0.8) * TAU + phase);
        wobble += 0.5 * sin((time * wobbleFreq * 0.61 + y * 1.3) * TAU + phase * 1.71);
        wobble *= wobbleAmpUV;

        float x = x0 + wobble;
        vec2 center = vec2(x, y);

        vec2 dp = uv - center;
        vec2 p = vec2(dp.x * aspect, dp.y);

        float dist = length(p);
        float d = dist / max(r, 1e-5);

        if (d > 1.02) continue;

        vec2 local = p / max(r, 1e-5);
        float rr = dot(local, local);
        if (rr > 1.0) continue;

        float nz = sqrt(max(1.0 - rr, 0.0));
        vec3 N = normalize(vec3(local, nz));

        vec2 nUV = vec2(N.x / aspect, N.y);

        float interior = 1.0 - smoothstep(0.96, 1.0, d);

        float ringOuter = 1.0 - smoothstep(0.88, 1.0, d);
        float ringInner = 1.0 - smoothstep(0.70, 0.84, d);
        float rim = saturate(ringOuter - ringInner);

        float fresnel = pow(1.0 - nz, 2.2);

        float spec = pow(max(dot(normalize(N.xy), lightDir), 0.0), 18.0) * interior;
        float shadow = pow(max(dot(normalize(N.xy), darkDir), 0.0), 2.5) * interior;

        vec3 sceneCenter = sampleScene(uv).rgb;

        // Bubble vector in UV space
        vec2 bubbleVecUV = vec2(local.x / aspect, local.y) * r;

        // =========================================================
        // LIQUID (normal modes)
        // center clearer, edge more refractive / reflective
        // =========================================================
        float liquidEdgeFactor = smoothstep(0.15, 1.0, d);
        float liquidEdgeDistort = r * (0.08 + 0.55 * liquidEdgeFactor * liquidEdgeFactor);

        vec2 liquidRefractUV = uv + nUV * liquidEdgeDistort;
        vec2 liquidReflectUV = uv + nUV * (r * (0.18 + 0.55 * fresnel));

        vec3 sceneLiquidRefract = sampleScene(liquidRefractUV).rgb;
        vec3 sceneLiquidReflect = sampleScene(liquidReflectUV).rgb;

        // =========================================================
        // LIQUID + FADE OUTWARDS
        // Strong CC Lens-style spherical bulge:
        // - center strongly magnified
        // - edge returns to normal
        // =========================================================
        float liquidLensMask = 1.0 - rr;

        // Stronger radial compression for noticeable bulge.
        // At center this becomes much less than 1, causing magnification.
        // At the edge it becomes 1, so the rim stays anchored.
        float liquidLensScale = 1.0 - 0.90 * pow(liquidLensMask, 0.55);

        vec2 liquidBulgedLocal = local * liquidLensScale;
        vec2 liquidBulgeUV = center + vec2(liquidBulgedLocal.x / aspect, liquidBulgedLocal.y) * r;

        vec3 sceneLiquidBulge = sampleScene(liquidBulgeUV).rgb;

        // Optional faint shell refraction near the outside so it still reads as a bubble
        float liquidShellMask = smoothstep(0.45, 1.0, d);
        vec2 liquidShellUV = uv + nUV * (r * 0.22 * liquidShellMask * liquidShellMask);
        vec3 sceneLiquidShell = sampleScene(liquidShellUV).rgb;

        // =========================================================
        // METAL
        // =========================================================
        vec2 metalFlipUV = center + vec2(bubbleVecUV.x, -bubbleVecUV.y);
        vec3 sceneMetalFlip = sampleScene(metalFlipUV).rgb;

        float metalEdgeMask = pow(smoothstep(0.35, 1.0, d), 1.6);
        float metalCenterMask = pow(max(1.0 - d, 0.0), 0.85);

        bool isLiquid = (Reflection_Type < 0.5);
        bool isFadeOut = (Shading_Type >= 3.5);

        vec3 bubbleCol = sceneCenter;
        float alpha = 0.0;

        if (isLiquid) {
    if (isFadeOut) {
        // Liquid + Fade Outwards
        bubbleCol = sceneLiquidBulge;
        bubbleCol = mix(bubbleCol, sceneLiquidShell, 0.18 * liquidShellMask);
        bubbleCol += vec3(spec * 0.05);
        bubbleCol += vec3(rim * 0.02);
        alpha = interior;
    } else {
        // Liquid normal
        vec3 transmitted = mix(sceneCenter, sceneLiquidRefract, liquidEdgeFactor * 0.85);
        vec3 rimReflect = mix(transmitted, sceneLiquidReflect, fresnel * 0.75);

        bubbleCol = rimReflect;
        bubbleCol += vec3(rim * (0.08 + 0.35 * fresnel));
        bubbleCol += vec3(spec * 0.22);
        bubbleCol -= vec3(shadow * 0.07);

        if (Shading_Type < 0.5) {
            // None (Liquid)
            float liquidNoneDistort = r * (0.22 + 0.95 * pow(liquidEdgeFactor, 1.15));
            vec2 liquidNoneUV = uv + nUV * liquidNoneDistort;
            vec3 sceneLiquidNone = sampleScene(liquidNoneUV).rgb;

            bubbleCol = sceneLiquidNone;
            bubbleCol += vec3(rim * 0.015);
            bubbleCol += vec3(spec * 0.02);

            alpha = interior;
        }
        else if (Shading_Type < 1.5) {
            // Lighten
            alpha = saturate(rim * 0.95 + fresnel * 0.32 + interior * 0.18);
        }
        else if (Shading_Type < 2.5) {
            // Darken
            bubbleCol *= 0.75;
            alpha = saturate(interior * 0.72 + rim * 0.28);
        }
        else {
            // Fade Inwards
            float liquidFadeInEdgeAlpha = smoothstep(0.25, 1.0, d);
            alpha = saturate(rim * 0.85 + liquidFadeInEdgeAlpha * 0.25);
        }
    }
} else {
    if (isFadeOut) {
        // Metal + Fade Outwards
        bubbleCol = mix(sceneCenter, sceneMetalFlip, metalCenterMask);
        bubbleCol += vec3(spec * 0.06);
        bubbleCol -= vec3(shadow * 0.05);
        alpha = saturate(interior * 0.82);
    } else {
        // Metal normal
        vec3 metalBody = mix(sceneCenter, sceneMetalFlip, metalEdgeMask);
        metalBody *= (0.94 - 0.08 * (1.0 - nz));
        metalBody += vec3(spec * 0.22);
        metalBody += vec3(rim * 0.06);
        metalBody -= vec3(shadow * 0.10);

        bubbleCol = metalBody;

        if (Shading_Type < 0.5) {
            // None (Metal)
            float metalNoneFlipMask = smoothstep(0.08, 0.95, d);

            bubbleCol = mix(sceneCenter, sceneMetalFlip, metalNoneFlipMask);
            bubbleCol += vec3(spec * 0.01);
            bubbleCol -= vec3(shadow * 0.015);

            alpha = interior * 0.95;
        }
        else if (Shading_Type < 1.5) {
            // Lighten
            alpha = saturate(rim * 0.55 + metalEdgeMask * 0.42 + spec * 0.12);
        }
        else if (Shading_Type < 2.5) {
            // Darken
            bubbleCol *= 0.72;
            alpha = saturate(interior * 0.58 + metalEdgeMask * 0.30 + rim * 0.12);
        }
        else {
            // Fade Inwards
            alpha = saturate(metalEdgeMask * 0.62 + rim * 0.30);
        }
    }
}
        outCol = blendBubble(outCol, bubbleCol, alpha, Shading_Type);
    }

    gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/az-burn-film.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUvScaled;

// --- Panzoid properties ---
uniform float Burn;           // 0..100
uniform vec2  Center;         // pixels, top-left origin (AE-like)
uniform float Random_Seed;    // any float

// ------------------------------------------------------------
// Hash / Noise
// ------------------------------------------------------------
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
  float n = hash12(p);
  return vec2(n, hash12(p + n + 17.13));
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);

  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * valueNoise(p);
    p = p * 2.03 + 19.19;
    a *= 0.5;
  }
  return v;
}

float voronoi(vec2 x) {
  vec2 n = floor(x);
  vec2 f = fract(x);
  float md = 10.0;

  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 o = hash22(n + g);
      vec2 r = g + o - f;
      float d = dot(r, r);
      md = min(md, d);
    }
  }
  return sqrt(md);
}

// Soft circular kernel (gaussian-ish)
float kernel(vec2 x, float r) {
  float dd = dot(x, x);
  return exp(-dd / (r * r + 1e-4));
}

// ------------------------------------------------------------

void main() {
  vec2 uv = vUvScaled;

  // Center: AE-like pixels from TOP-LEFT -> flip Y for UV space
  vec2 centerPx = vec2(Center.x, resolution.y - Center.y);
  vec2 center = (centerPx / resolution) * uvScale;

  // Aspect-correct space
  vec2 aspect = vec2(resolution.x / max(resolution.y, 1.0), 1.0);
  vec2 p = (uv - center) * aspect;

  // Normalize distance 0..1 using farthest corner
  vec2 c0 = (vec2(0.0, 0.0) - center) * aspect;
  vec2 c1 = (vec2(uvScale.x, 0.0) - center) * aspect;
  vec2 c2 = (vec2(0.0, uvScale.y) - center) * aspect;
  vec2 c3 = (vec2(uvScale.x, uvScale.y) - center) * aspect;
  float maxD = max(max(length(c0), length(c1)), max(length(c2), length(c3)));
  maxD = max(maxD, 1e-4);

  float d = length(p) / maxD;

  // Burn progress
  float t = clamp(Burn / 100.0, 0.0, 1.0);
  t = pow(t, 1.12);

  // Cinematic ramps:
  float smokeRamp = smoothstep(0.020, 0.120, t);
  float bigRamp   = smoothstep(0.060, 0.240, t);
  float smallRamp = smoothstep(0.160, 0.420, t);

  // Seed
  float seed = Random_Seed * 31.73 + 17.17;

  // Pattern space
  vec2 q = p + vec2(seed * 0.01, seed * 0.013);

  // -----------------------------------------
  // CHAINED ignition cluster (2–3 sparks)
  // -----------------------------------------
  // Tightness of the cluster (smaller = closer sparks)
  float cluster = 0.10;

  // Three nearby offsets (seeded)
  vec2 j1 = (hash22(vec2(seed + 11.1, seed * 0.31)) - 0.5) * cluster;
  vec2 j2 = (hash22(vec2(seed + 27.7, seed * 0.57)) - 0.5) * cluster;
  vec2 j3 = (hash22(vec2(seed + 49.4, seed * 0.93)) - 0.5) * cluster;

  // Slightly correlated positions so they're "nearby"
  vec2 ign1 = p - j1;
  vec2 ign2 = p - (j1 * 0.55 + j2 * 0.85);
  vec2 ign3 = p - (j1 * 0.65 + j3 * 0.90);

  // Spark size grows early (heat-up)
  float ignGrow = smoothstep(0.020, 0.190, t);
  float r1 = mix(0.020, 0.28, ignGrow);
  float r2 = mix(0.018, 0.24, ignGrow);
  float r3 = mix(0.016, 0.22, ignGrow);

  // ✅ CHAIN gates (the key feature)
  // Spark1 first, then Spark2, then Spark3
  float g1 = smoothstep(0.020, 0.080, t);
  float g2 = smoothstep(0.060, 0.140, t);
  float g3 = smoothstep(0.100, 0.200, t);

  // Also ensure absolute zero at the very beginning
  float baseGate = smoothstep(0.012, 0.070, t);

  // Kernels (two strong, one weaker) multiplied by chain gates
  float k1 = kernel(ign1, r1) * 1.00 * g1;
  float k2 = kernel(ign2, r2) * 0.95 * g2;
  float k3 = kernel(ign3, r3) * 0.70 * g3;

  // Use max so you see distinct sparks rather than averaging them
  float ignition = max(k1, max(k2, k3));
  ignition = clamp(ignition, 0.0, 1.0) * baseGate;

  // This controls how long it stays localized before spreading globally
  float spread = smoothstep(0.180, 0.620, t);
  float localize = mix(ignition, 1.0, spread);

  // -----------------------------
  // Two-scale holes (big + small)
  // -----------------------------
  float vBig   = voronoi(q * 5.6  + seed * 1.31);
  float vSmall = voronoi(q * 13.5 + seed * 2.07);

  float cellsBig   = 1.0 - smoothstep(0.22, 0.78, vBig);
  float cellsSmall = 1.0 - smoothstep(0.12, 0.64, vSmall);

  float n1 = fbm(q * 10.0 + seed * 0.21);
  float n2 = fbm(q * 22.0 + seed * 0.47);

  float bigMask = smoothstep(0.38, 0.95, cellsBig) * (0.55 + 0.45 * n1);
  bigMask = pow(clamp(bigMask, 0.0, 1.0), 1.25) * bigRamp;

  float smallMask = smoothstep(0.28, 0.95, cellsSmall) * (0.60 + 0.40 * n2);
  smallMask = pow(clamp(smallMask, 0.0, 1.0), 1.05) * smallRamp;

  float holePattern = clamp(bigMask * 0.85 + smallMask * 0.55, 0.0, 1.0);

  // Hole boost (localized early, global later)
  float holeBoost = (bigMask * bigMask) * 0.28 + (smallMask * smallMask) * 0.18;
  holeBoost *= (0.65 + 0.35 * n1);
  holeBoost *= localize;

  // -----------------------------
  // Bands (fixed)
  // -----------------------------
  float preW  = 0.095;
  float edgeW = 0.055;
  float holeW = 0.032;

  float field = d - holeBoost;

  // Guarantee full wipe at 100%
  float eps = 1e-4;
  field = clamp(field, 0.0, 1.0 - holeW - eps);

  // Derivative-free smoothing based on pixel size
  float px = 1.0 / min(resolution.x, resolution.y);
  float fw = px * 4.8;

  float preW2  = preW  + fw;
  float edgeW2 = edgeW + fw;
  float holeW2 = holeW + fw * 0.85;

  // Burn=0 clean
  float preA  = max(field - preW2,  0.0);
  float preB  = max(field,          eps);
  float edgeA = max(field - edgeW2, 0.0);
  float edgeB = max(field,          eps);

  // Smoke is localized early, then spreads
  float pre  = smoothstep(preA, preB, t) * smokeRamp * (0.35 + 0.65 * localize);

  float edge = smoothstep(edgeA, edgeB, t) - smoothstep(field, field + edgeW2, t);
  edge = clamp(edge, 0.0, 1.0) * baseGate;

  float burned = smoothstep(field, field + holeW2, t);

  // ---------------------------------
  // Smoke trails: big + small
  // ---------------------------------
  vec2 dir  = normalize(p + vec2(1e-4, 0.0));
  vec2 perp = vec2(-dir.y, dir.x);

  float along  = dot(q, dir);
  float across = dot(q, perp);

  vec2 trailBigUV = vec2(along * 6.6,  across * 1.25) + vec2(seed * 0.09, seed * 0.04);
  float trailBig = fbm(trailBigUV + n1 * 1.35);

  vec2 trailSmallUV = vec2(along * 14.0, across * 3.2) + vec2(seed * 0.13, seed * 0.06);
  float trailSmall = fbm(trailSmallUV + n2 * 1.8);

  float soot = fbm(q * 24.0 + seed * 0.41);

  float smokeBig   = pre * bigMask   * (0.28 + 0.72 * trailBig);
  float smokeSmall = pre * smallMask * (0.18 + 0.82 * trailSmall);

  float ambientSmoke = pre * (0.10 + 0.35 * soot) * (0.35 + 0.65 * n1) * (0.25 + 0.75 * localize);

  float smokeStrength = clamp(smokeBig * 1.05 + smokeSmall * 0.60 + ambientSmoke, 0.0, 1.0);

  float charMask = edge * (0.45 + 0.55 * soot) * (0.50 + 0.50 * holePattern);

  // Sample source with tiny wobble near edge
  vec2 jitter = (hash22(q * 40.0 + seed) - 0.5);
  vec2 wobble = jitter * (0.006 * edge);
  vec4 texel = texture2D(tDiffuse, uv + wobble);

  vec3 rgb = texel.rgb;

  vec3 sootCol = vec3(0.02, 0.02, 0.02);
  vec3 charCol = vec3(0.03, 0.015, 0.01);

  rgb = mix(rgb, sootCol, smokeStrength);
  rgb = mix(rgb, charCol, charMask);

  rgb *= (1.0 - pre  * 0.13);
  rgb *= (1.0 - edge * 0.20);

  // End fade ensures Burn=100 wipes everything
  float endFade = 1.0 - smoothstep(0.985, 1.0, t);

  float rimAlpha = edge * (0.70 + 0.30 * soot);
  float outA = texel.a * clamp((1.0 - burned) + rimAlpha * 0.60, 0.0, 1.0) * endFade;

  gl_FragColor = vec4(clamp(rgb, 0.0, 1.0), outA);
}

text./plugins/alipfx/shaders/az-cross-blur.gl:
// CC Cross Blur — Panzoid CM3 (GLSL ES 1.0)
// Fixed loop index GLSL ES constraints (no non-constant loop init)

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

uniform float RadiusX;
uniform float RadiusY;
uniform int Transfer_Mode;      // 0 Blend, 1 Add, 2 Screen, 3 Multiply, 4 Lighten, 5 Darken
uniform int Repeat_Edge_Pixels; // 0 Off, 1 On

const int MAX_TAPS = 31; // must be odd and constant
const int HALF_TAPS = MAX_TAPS / 2;

// Sample with optional edge repeat
vec4 sampleTex(vec2 uv) {
  if (Repeat_Edge_Pixels == 1) {
    uv = clamp(uv, vec2(0.0), vec2(1.0));
    return texture2D(tDiffuse, uv);
  } else {
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return vec4(0.0);
    return texture2D(tDiffuse, uv);
  }
}

// Blur along axis dir (in pixel units: (1,0) or (0,1))
vec4 blurAxis(vec2 uv, vec2 dir, float radius) {
  if (radius <= 0.0) return sampleTex(uv);

  float sigma = max(radius * 0.5, 0.0001);
  float twoSigma2 = 2.0 * sigma * sigma;

  vec4 sum = vec4(0.0);
  float total = 0.0;

  // iterate over a fixed, constant range to satisfy GLSL ES
  for (int i = 0; i < MAX_TAPS; ++i) {
    int idx = i - HALF_TAPS; // can be negative
    float fi = float(idx);

    // skip samples outside the desired radius to reduce work
    if (abs(fi) > ceil(radius)) continue;

    float w = exp(-(fi * fi) / twoSigma2);
    vec2 offset = dir * fi / resolution;
    sum += sampleTex(uv + offset) * w;
    total += w;
  }

  if (total <= 0.0) return sampleTex(uv);
  return sum / total;
}

// Blend/transfer modes
vec4 transfer(vec4 a, vec4 b) {
  if (Transfer_Mode == 1) {
    // Add
    return min(a + b, vec4(1.0));
  } else if (Transfer_Mode == 2) {
    // Screen
    return vec4(1.0) - (vec4(1.0) - a) * (vec4(1.0) - b);
  } else if (Transfer_Mode == 3) {
    // Multiply
    return a * b;
  } else if (Transfer_Mode == 4) {
    // Lighten
    return max(a, b);
  } else if (Transfer_Mode == 5) {
    // Darken
    return min(a, b);
  }
  // default Blend (average)
  return (a + b) * 0.5;
}

void main() {
  vec2 uv = vUvScaled;

  vec4 blurX = blurAxis(uv, vec2(1.0, 0.0), max(0.0, RadiusX));
  vec4 blurY = blurAxis(uv, vec2(0.0, 1.0), max(0.0, RadiusY));

  gl_FragColor = transfer(blurX, blurY);
}

text./plugins/alipfx/shaders/az-cylinder.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 resolution;

/* ----------- User properties ----------- */
uniform float Radius_percent;      // % of comp height (100 -> radius = half height)
uniform float Position_X;          // pixels
uniform float Position_Y;          // pixels
uniform float Position_Z;          // pixels (positive = toward camera)

uniform vec3  Rotation_degs;       // degrees
uniform float Rotation_Order_f;    // 0..5
uniform float Render_Mode_f;       // 0=Full, 1=Outside, 2=Inside

const float PI = 3.141592653589793;

/* ----------- Helpers ----------- */
float d2r(float d){ return d * PI / 180.0; }

mat3 rotX(float a){
  float c=cos(a), s=sin(a);
  return mat3(
    1.0,0.0,0.0,
    0.0,c,-s,
    0.0,s,c
  );
}
mat3 rotY(float a){
  float c=cos(a), s=sin(a);
  return mat3(
     c,0.0,s,
     0.0,1.0,0.0,
    -s,0.0,c
  );
}
mat3 rotZ(float a){
  float c=cos(a), s=sin(a);
  return mat3(
    c,-s,0.0,
    s, c,0.0,
    0.0,0.0,1.0
  );
}

mat3 composeRotation(int o, vec3 a){
  mat3 RX=rotX(a.x), RY=rotY(a.y), RZ=rotZ(a.z);
  if(o==0) return RZ*RY*RX; // XYZ
  if(o==1) return RY*RZ*RX; // XZY
  if(o==2) return RZ*RX*RY; // YXZ
  if(o==3) return RX*RZ*RY; // YZX
  if(o==4) return RY*RX*RZ; // ZXY
  return RX*RY*RZ;          // ZYX
}

mat3 transpose3(mat3 m){
  return mat3(
    m[0][0], m[1][0], m[2][0],
    m[0][1], m[1][1], m[2][1],
    m[0][2], m[1][2], m[2][2]
  );
}

vec4 over(vec4 A, vec4 B){
  return A + (1.0 - A.a) * B;
}

// Sample cylinder at t in cylinder-local space
vec4 sampleCylinder(vec3 ro, vec3 rd, float t, bool backFace){
  vec3 ph = ro + rd * t;  // cylinder-local hit point

  // ✅ FIX #1: Correct cylinder wrap angle (around Y axis)
  float u = atan(ph.x, ph.z) / (2.0 * PI) + 0.5;

  // ✅ FIX #2: Push seam behind the cylinder so it doesn't cut your text
  // (Half turn shift; you can remove +0.5 if you prefer original seam position)
  u = fract(u + 0.5);

  // ✅ Keep inside readable (no mirrored text)
  if(backFace){
    u = fract(1.0 - u);
  }

  // Rigid 3D V mapping (y in [-1..1] maps to v in [0..1])
  float v = 0.5 - 0.5 * ph.y;
  if(v < 0.0 || v > 1.0) return vec4(0.0);

  return texture2D(tDiffuse, vec2(u, v));
}

void main(){
  int rotOrder   = int(floor(Rotation_Order_f + 0.5));
  int renderMode = int(floor(Render_Mode_f + 0.5));

  float aspect = resolution.x / resolution.y;

  // Camera at +Z looking toward screen plane at z=0
  float camDist = 2.0;

  vec2 uv = vUvScaled;
  vec2 screen = (uv - 0.5) * vec2(aspect * 2.0, 2.0);

  vec3 rayOrigin = vec3(0.0, 0.0, camDist);
  vec3 target    = vec3(screen.x, -screen.y, 0.0);
  vec3 rayDir    = normalize(target - rayOrigin);

  // Cylinder center (pixels -> world units)
  vec3 cylCenter = vec3(
    ((Position_X / resolution.x) - 0.5) * (aspect * 2.0),
    -((Position_Y / resolution.y) - 0.5) * 2.0,
    (Position_Z / resolution.y) * 2.0
  );

  // Radius: 100% = radius of 1.0 (half height)
  float R = max(0.001, (Radius_percent * 0.01) * 1.0);

  vec3 ang = vec3(d2r(Rotation_degs.x), d2r(Rotation_degs.y), d2r(Rotation_degs.z));
  mat3 Rm = composeRotation(rotOrder, ang);
  mat3 Ri = transpose3(Rm);

  // Ray into cylinder local
  vec3 ro = Ri * (rayOrigin - cylCenter);
  vec3 rd = Ri * rayDir;

  // Intersect infinite cylinder (axis Y)
  vec2 roxz = ro.xz;
  vec2 rdxz = rd.xz;

  float a = dot(rdxz, rdxz);
  float b = 2.0 * dot(roxz, rdxz);
  float c = dot(roxz, roxz) - R * R;
  float d = b*b - 4.0*a*c;

  if(d < 0.0 || a < 1e-8){
    gl_FragColor = vec4(0.0);
    return;
  }

  float sqrtD = sqrt(d);
  float tNear = (-b - sqrtD) / (2.0*a);
  float tFar  = (-b + sqrtD) / (2.0*a);

  if(tFar < 0.0){
    gl_FragColor = vec4(0.0);
    return;
  }

  if(tNear > tFar){
    float tmp = tNear; tNear = tFar; tFar = tmp;
  }

  bool hasNear = (tNear > 0.0);
  bool hasFar  = (tFar  > 0.0);

  // Outside only
  if(renderMode == 1){
    if(!hasNear){ gl_FragColor = vec4(0.0); return; }
    gl_FragColor = sampleCylinder(ro, rd, tNear, false);
    return;
  }

  // Inside only
  if(renderMode == 2){
    if(!hasFar){ gl_FragColor = vec4(0.0); return; }
    gl_FragColor = sampleCylinder(ro, rd, tFar, true);
    return;
  }

  // Full: both sides (front over back)
  vec4 colFront = hasNear ? sampleCylinder(ro, rd, tNear, false) : vec4(0.0);
  vec4 colBack  = hasFar  ? sampleCylinder(ro, rd, tFar,  true)  : vec4(0.0);

  gl_FragColor = over(colFront, colBack);
}

text./plugins/alipfx/shaders/az-drizzle.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// Panzoid dynamic number properties
uniform float time;
uniform float Drip_Rate;
uniform float Longevity;
uniform float Rippling;
uniform float Displacement;
uniform float Ripple_Height;
uniform float Spreading;

// ------------------------------------------------------------
// Hash helpers
// ------------------------------------------------------------
float hash21(vec2 p)
{
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec2 hash22(vec2 p)
{
    float n = sin(dot(p, vec2(127.1, 311.7)));
    return fract(vec2(262144.0, 32768.0) * n);
}

vec2 toBufferUV(vec2 uv)
{
    return uv * uvScale;
}

// A narrow ring profile centered on x=0.
// This is used to create thin drizzle bands rather than fat glowing arcs.
float ringProfile(float x, float w)
{
    float a = abs(x);
    return exp(-(a * a) / max(w * w, 1e-6));
}

// Growth curve driven by normalized lifetime.
// Higher Longevity = slower progression in real seconds.
// Lower Longevity = faster progression in real seconds.
float growthCurve(float t)
{
    t = clamp(t, 0.0, 1.0);
    return 1.0 - pow(1.0 - t, 3.4);
}

// ------------------------------------------------------------
// Main
// ------------------------------------------------------------
void main()
{
    vec2 uv = vUv;

    // Aspect correction so rings stay circular
    float aspectRatio = resolution.x / max(resolution.y, 1.0);
    vec2 aspect = vec2(aspectRatio, 1.0);

    // --------------------------------------------------------
    // AE-like tuning constants
    // --------------------------------------------------------
    const float SPAWN_PROB = 0.075;
    const int CELL_RADIUS = 2;
    const int MAX_HISTORY = 10;

    // Slightly larger cells -> less clutter / more AE-like spacing
    float cellPx = 185.0;

    vec2 grid = max(vec2(1.0), resolution / cellPx);
    vec2 cell = floor(uv * grid);

    float rate = max(Drip_Rate, 0.0001);
    float life = max(Longevity, 0.0001);

    // Spreading controls final ripple reach, not lifetime speed.
    float spreadN = max(Spreading / 100.0, 0.001);
    float maxRadius = 0.018 + 0.055 * pow(spreadN, 0.65);

    // Rippling influences how many internal wave bands appear,
    // but in an AE-like restrained way.
    float bandCount = 1.0 + 0.015 * max(Rippling, 0.0);

    // Ripple Height should mostly affect steepness/sharpness,
    // not brute force brightness.
    float sharpness = clamp(Ripple_Height / 100.0, 0.0, 2.0);

    // Narrower ring widths for thinner AE-style crescents.
    float ringWidth = mix(0.020, 0.0065, clamp(sharpness * 0.7, 0.0, 1.0));

    // Much lower wave energy than earlier versions.
    float heightAmp = 0.006 + Ripple_Height * 0.00042;

    float h = 0.0;
    vec2 grad = vec2(0.0);

    float historyNeeded = min(float(MAX_HISTORY - 1), ceil(life * rate) + 1.0);

    // --------------------------------------------------------
    // Accumulate procedural drizzle events
    // --------------------------------------------------------
    for (int oy = -CELL_RADIUS; oy <= CELL_RADIUS; oy++)
    {
        for (int ox = -CELL_RADIUS; ox <= CELL_RADIUS; ox++)
        {
            vec2 ccell = cell + vec2(float(ox), float(oy));
            float currentSlot = floor(time * rate);

            for (int hi = 0; hi < MAX_HISTORY; hi++)
            {
                if (float(hi) > historyNeeded) break;

                float slot = currentSlot - float(hi);

                // Event existence
                float chance = hash21(ccell + vec2(slot * 0.73 + 19.13, slot * 1.91 + 7.17));
                if (chance > SPAWN_PROB) continue;

                // Jittered spawn time inside time slot
                float tJitter = hash21(ccell + vec2(slot * 1.37 + 3.1, slot * 2.11 + 8.7));
                float spawnTime = (slot + tJitter) / rate;
                float age = time - spawnTime;

                if (age < 0.0 || age > life) continue;

                // Jittered position inside cell
                vec2 rnd = hash22(ccell + vec2(slot * 0.91 + 11.3, slot * 1.27 + 17.9));
                vec2 center = (ccell + rnd) / grid;

                vec2 dp = (uv - center) * aspect;
                float d = length(dp) + 1e-6;

                // Normalized life progress:
                // high Longevity = slower over real seconds
                // low Longevity = faster over real seconds
                float t = clamp(age / life, 0.0, 1.0);

                // Radius progresses through life, not raw seconds.
                // So Longevity controls drizzle speed,
                // while Spreading controls final size only.
                float radius = maxRadius * growthCurve(t);
                float x = d - radius;

                // Gradual temporal envelope
                float attack = smoothstep(0.0, 0.05, t);
                float decay  = 1.0 - smoothstep(0.45, 0.92, t);
                float lifeFade = attack * decay;

                // Inner repeating bands, restrained to avoid overdoing it.
                float waveFreq = (6.2831853 * bandCount) / max(ringWidth * 14.0, 1e-4);

                // Thin ring centered on the moving front
                float front = ringProfile(x, ringWidth);

                // A subtle oscillation on top of the front
                float phase = x * waveFreq;
                float osc = 0.65 + 0.35 * sin(phase);

                // The actual ripple height field
                float ripple = front * osc * lifeFade;

                // Derivative approximation for normal/displacement
                float dx = ringWidth * 0.35;
                float frontP = ringProfile(x + dx, ringWidth);
                float frontM = ringProfile(x - dx, ringWidth);

                float oscP = 0.65 + 0.35 * sin((x + dx) * waveFreq);
                float oscM = 0.65 + 0.35 * sin((x - dx) * waveFreq);

                float rippleP = frontP * oscP * lifeFade;
                float rippleM = frontM * oscM * lifeFade;

                float dhdx = (rippleP - rippleM) / (2.0 * dx);

                float amp = heightAmp;

                h += ripple * amp;
                grad += (dp / d) * dhdx * amp;
            }
        }
    }

    // --------------------------------------------------------
    // Displacement: subtle AE-like distortion
    // --------------------------------------------------------
    vec2 uvOffset = vec2(grad.x / aspect.x, grad.y);

    // Much gentler than earlier versions.
    uvOffset *= (Displacement / max(resolution.y, 1.0)) * 0.95;

    vec2 sampleUV = clamp(uv + uvOffset, vec2(0.0), vec2(1.0));
    vec4 base = texture2D(tDiffuse, toBufferUV(sampleUV));

    // --------------------------------------------------------
    // AE-like crescent highlight/shading
    // --------------------------------------------------------
    vec3 N = normalize(vec3(-grad.x * (0.22 + 0.0018 * Ripple_Height),
                            -grad.y * (0.22 + 0.0018 * Ripple_Height),
                             1.0));

    // Fixed light direction similar to a soft upper-left highlight
    vec3 L = normalize(vec3(-0.42, 0.52, 0.74));
    vec3 V = vec3(0.0, 0.0, 1.0);
    vec3 R = reflect(-L, N);

    float diffuse = max(dot(N, L), 0.0);
    float spec = pow(max(dot(R, V), 0.0), 34.0);

    // Ring mask: stronger only where ring geometry exists
    float ringMask = clamp(h * 16.0, 0.0, 1.0);

    // Crescent bias:
    // Emphasize one side of the ring rather than full uniform glow.
    vec2 light2D = normalize(vec2(L.x, L.y));
    vec2 g = vec2(-grad.x, -grad.y);
    float gLen = max(length(g), 1e-6);
    float crescent = clamp(dot(g / gLen, light2D) * 0.5 + 0.5, 0.0, 1.0);

    float shade =
          (diffuse - 0.52) * 0.045 * ringMask
        + spec * 0.060 * ringMask * crescent;

    // Very subtle dark trough to help ring definition without looking embossed
    float trough = clamp(-h * 10.0, 0.0, 1.0) * 0.020;

    vec3 color = base.rgb + vec3(shade - trough);

    gl_FragColor = vec4(clamp(color, 0.0, 1.0), base.a);
}

text./plugins/alipfx/shaders/az-glass.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

uniform float Property;
uniform float Softness;
uniform float Height;
uniform float Displacement;

varying vec2 vUvScaled;

/* ===============================
   Channel selector (AE-style)
================================ */
float pickProperty(vec4 c)
{
    int p = int(Property + 0.5);

    if (p == 1) return c.r;
    if (p == 2) return c.g;
    if (p == 3) return c.b;
    if (p == 4) return c.a;
    if (p == 5) return dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));

    float mx = max(max(c.r, c.g), c.b);
    float mn = min(min(c.r, c.g), c.b);
    return (mx + mn) * 0.5;
}

/* ===============================
   Height field with blur/sharpen
================================ */
float heightField(vec2 uv)
{
    float s = Softness;
    float center = pickProperty(texture2D(tDiffuse, uv));

    float hL = pickProperty(texture2D(tDiffuse, uv - vec2(1.0/resolution.x, 0.0)));
    float hR = pickProperty(texture2D(tDiffuse, uv + vec2(1.0/resolution.x, 0.0)));
    float hU = pickProperty(texture2D(tDiffuse, uv + vec2(0.0, 1.0/resolution.y)));
    float hD = pickProperty(texture2D(tDiffuse, uv - vec2(0.0, 1.0/resolution.y)));

    float blur = (hL + hR + hU + hD) * 0.25;

    if (s > 0.0) {
        return mix(center, blur, clamp(s, 0.0, 1.0));
    } else if (s < 0.0) {
        return mix(center, center + (center - blur), clamp(-s, 0.0, 1.0));
    } else {
        return center;
    }
}

/* ===============================
   Surface normal (HQ)
================================ */
vec3 surfaceNormal(vec2 uv)
{
    vec2 px = 1.0 / resolution;

    float hL = heightField(uv - vec2(px.x, 0.0));
    float hR = heightField(uv + vec2(px.x, 0.0));
    float hD = heightField(uv - vec2(0.0, px.y));
    float hU = heightField(uv + vec2(0.0, px.y));

    vec2 grad = vec2(hR - hL, hU - hD) * 0.5;

    return normalize(vec3(-grad * Height * 0.1, 1.0));
}

/* ===============================
   Main
================================ */
void main()
{
    vec2 uv = vUvScaled;
    vec3 n = surfaceNormal(uv);

    // --- Distortion (refraction-like) ---
    vec2 offset = vec2(0.0);
    if (Displacement != 0.0) {
        offset = n.xy * (Displacement / resolution.y);
    }
    vec4 base = texture2D(tDiffuse, uv + offset);

    // --- Edge gating ---
    float edge = length(n.xy);
    edge = smoothstep(0.015, 0.12, edge);

    // --- Lighting ---
    vec3 lightDir = normalize(vec3(-0.4, -0.6, 1.0));
    vec3 viewDir  = vec3(0.0, 0.0, 1.0);

    float diff = max(dot(n, lightDir), 0.0) * edge;

    vec3 halfDir = normalize(lightDir + viewDir);
    float spec = pow(max(dot(n, halfDir), 0.0), 64.0) * edge; // sharper specular

    // --- Fresnel reflection ---
    float fresnel = pow(1.0 - max(dot(n, viewDir), 0.0), 3.0);

    // --- Final shading ---
    vec3 result =
        base.rgb * 0.9 +              // slightly darkened base
        diff * 0.35 +                 // diffuse shading
        spec * 1.2 +                  // specular highlight
        fresnel * 0.4;                // reflective sheen

    gl_FragColor = vec4(result, base.a);
}

text./plugins/alipfx/shaders/az-grid-wipe.gls:
precision highp float;
precision highp int;

// Core Panzoid Uniforms
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

// Custom User Parameters
uniform float Completion;        // Range: 0 to 100
uniform vec2 Center;             // Type: Position (Pixels)
uniform float Rotation;          // Range: 0 to 360
uniform float Borders;           // Range: 0 to 200
uniform float Tiles;             // Range: 1 to 100
uniform float Shape;             // Type: Selector (0=Doors, 1=Radial, 2=Rectangular)
uniform bool Reverse_Transition; // Type: Checkbox

// Constants
#define SHAPE_DOORS 0
#define SHAPE_RADIAL 1
#define SHAPE_RECT  2

void main() {
    // 1. Setup & Coordinates
    vec2 uv = vUvScaled;
    float aspect = resolution.x / resolution.y;

    // Normalize Parameters
    float comp = clamp(Completion / 100.0, 0.0, 1.0);
    float nTiles = max(1.0, Tiles);
    int shapeType = int(Shape + 0.5);

    // Convert Pixel Center to UV Space
    vec2 centerUV = Center / resolution;
    if (Center.x == 0.0 && Center.y == 0.0) centerUV = vec2(0.5, 0.5);

    // 2. Aspect Corrected Space
    vec2 p = uv;
    p.x *= aspect;
    vec2 c = centerUV;
    c.x *= aspect;

    // 3. Global Rotation
    float ang = radians(Rotation);
    float s = sin(ang);
    float cA = cos(ang);

    vec2 delta = p - c;
    vec2 pRot = vec2(
        delta.x * cA - delta.y * s,
        delta.x * s + delta.y * cA
    ) + c;

    // 4. Grid Logic
    vec2 gridPos = pRot * nTiles;
    vec2 tileId = floor(gridPos);
    vec2 tileUv = fract(gridPos) - 0.5; // Local UV (-0.5 to 0.5)

    // 5. Calculate Distance for the Wipe
    vec2 tileCenterPos = (tileId + 0.5) / nTiles;

    // Max distance calculation
    float d1 = distance(vec2(0.0, 0.0), c);
    float d2 = distance(vec2(aspect, 0.0), c);
    float d3 = distance(vec2(0.0, 1.0), c);
    float d4 = distance(vec2(aspect, 1.0), c);
    float maxDist = max(max(d1, d2), max(d3, d4));

    float dist = distance(tileCenterPos, c);

    if (Reverse_Transition) {
        dist = maxDist - dist;
    }

    // 6. Transition Progress & Scaling
    float borderW = max(0.001, Borders * 0.015);
    float startCut = -borderW;
    float endCut = maxDist;
    float cutPos = mix(startCut, endCut, comp);

    // Scale goes from 1.0 (Solid) to 0.0 (Transparent)
    float scale = smoothstep(cutPos, cutPos + borderW, dist);

    // 7. Shape Drawing (Fixed Sizes)
    float sdf = 0.0;
    float maxRadius = 0.5; 

    // Overlap Buffer:
    // We add extra size (0.1) to ensure shapes merge perfectly at Scale 1.0
    // This removes the "Grid Lines" visible at 0% completion.
    float overlap = 0.05; 

    if (shapeType == SHAPE_DOORS) {
        // Diamond
        sdf = abs(tileUv.x) + abs(tileUv.y);
        maxRadius = 1.0 + overlap; 
    } else if (shapeType == SHAPE_RADIAL) {
        // Circle
        sdf = length(tileUv);
        // Circle needs radius ~0.71 to hit corners. We use 0.75 for safety.
        maxRadius = 0.75 + overlap; 
    } else {
        // Rectangular
        sdf = max(abs(tileUv.x), abs(tileUv.y));
        maxRadius = 0.5 + overlap;
    }

    float currentSize = scale * maxRadius;

    // 8. Output
    float aa = 0.01;
    float alpha = 1.0 - smoothstep(currentSize - aa, currentSize, sdf);

    // Hard clamp for 0% completion to strictly prevent any transparency lines
    if (comp <= 0.0) alpha = 1.0;

    vec4 texel = texture2D(tDiffuse, vUvScaled);
    gl_FragColor = texel * alpha;
}

text./plugins/alipfx/shaders/az-griddler.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

uniform float Horizontal_Scale; // percent, 100 = unchanged
uniform float Vertical_Scale;   // percent, 100 = unchanged
uniform float Tile_Size;        // tile size in pixels
uniform float Rotation;         // degrees
uniform float Cut_Tiles;        // 0 = off, 1 = on

const float PI = 3.1415926535897932384626433832795;

vec2 rotate2D(vec2 p, float a)
{
    float s = sin(a);
    float c = cos(a);
    return vec2(
        c * p.x - s * p.y,
        s * p.x + c * p.y
    );
}

vec2 pmod(vec2 x, vec2 y)
{
    return mod(mod(x, y) + y, y);
}

void main()
{
    // Current pixel position in layer pixel space
    vec2 fragPx = vUv * resolution;

    // Prevent invalid values
    float tileSize = max(Tile_Size, 0.0001);

    // Tile index + tile origin in pixel space
    vec2 tileIndex  = floor(fragPx / tileSize);
    vec2 tileOrigin = tileIndex * tileSize;

    // Handle partial tiles at frame edges
    vec2 cellSize = min(vec2(tileSize), resolution - tileOrigin);
    cellSize = max(cellSize, vec2(0.0001));

    // Local pixel coords inside tile
    vec2 localPx = fragPx - tileOrigin;
    vec2 center  = cellSize * 0.5;
    vec2 d       = localPx - center;

    // Convert user controls
    vec2 scalePct = vec2(
        max(Horizontal_Scale, 0.0001),
        max(Vertical_Scale,   0.0001)
    ) / 100.0;

    float ang = radians(Rotation);

    // Inverse transform:
    // output pixel -> source pixel inside the same tile
    // transform order = scale first, then rotate around tile center
    vec2 q = rotate2D(d, -ang);
    q /= scalePct;

    vec2 sampleLocal;
    bool outside = false;

    if (Cut_Tiles >= 0.5)
    {
        // Clip anything that would sample outside the tile
        sampleLocal = q + center;

        if (sampleLocal.x < 0.0 || sampleLocal.x > cellSize.x ||
            sampleLocal.y < 0.0 || sampleLocal.y > cellSize.y)
        {
            outside = true;
        }
    }
    else
    {
        // Wrap/repeat inside each tile instead of cutting
        sampleLocal = pmod(q + center, cellSize);
    }

    if (outside)
    {
        gl_FragColor = vec4(0.0);
        return;
    }

    // Back to full-layer pixel space
    vec2 samplePx = tileOrigin + sampleLocal;

    // Convert to texture UV
    vec2 sampleUv = samplePx / resolution;

    // Panzoid requires uvScale mapping for texture lookup
    vec4 texel = texture2D(tDiffuse, sampleUv * uvScale);

    gl_FragColor = texel;
}

text./plugins/alipfx/shaders/az-hextile.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// ---- Panzoid properties ----
uniform float Render;            // 0 Tile, 1 Fold Aligned, 2 Fold Seamlessly
uniform float Radius;            // pixels
uniform vec2  Center;            // pixels
uniform float Lock_Center_Tile;  // 0/1
uniform float Rotate;            // degrees
uniform float Smearing;          // 0..100 suggested

const float PI = 3.14159265358979323846;

vec2 rot2(vec2 p, float a) {
  float s = sin(a), c = cos(a);
  return vec2(c*p.x - s*p.y, s*p.x + c*p.y);
}
vec2 rotateAround(vec2 p, vec2 pivot, float a) {
  return pivot + rot2(p - pivot, a);
}

float roundN(float x) { return (x < 0.0) ? ceil(x - 0.5) : floor(x + 0.5); }

vec3 axialToCube(vec2 h) {
  float x = h.x;
  float z = h.y;
  float y = -x - z;
  return vec3(x, y, z);
}
vec2 cubeToAxial(vec3 c) { return vec2(c.x, c.z); }

vec3 cubeRound(vec3 c) {
  float rx = roundN(c.x);
  float ry = roundN(c.y);
  float rz = roundN(c.z);

  float x_diff = abs(rx - c.x);
  float y_diff = abs(ry - c.y);
  float z_diff = abs(rz - c.z);

  if (x_diff > y_diff && x_diff > z_diff) rx = -ry - rz;
  else if (y_diff > z_diff) ry = -rx - rz;
  else rz = -rx - ry;

  return vec3(rx, ry, rz);
}

// Flat-top hex pixel<->axial (Radius is circumradius in pixels)
vec2 pixelToAxial(vec2 p, float size) {
  float q = (2.0/3.0) * (p.x / size);
  float r = (-1.0/3.0) * (p.x / size) + (0.5773502691896258) * (p.y / size);
  return vec2(q, r);
}
vec2 axialToPixel(vec2 h, float size) {
  float q = h.x;
  float r = h.y;
  float x = size * 1.5 * q;
  float y = size * 1.7320508075688772 * (r + 0.5*q);
  return vec2(x, y);
}

// Hex SDF for seams (flat-top)
float sdHexFlat(vec2 p, float r) {
  p = abs(p);
  return max(p.y, dot(p, vec2(0.8660254037844386, 0.5))) - r;
}

// Fold Aligned: 6-way fold
vec2 foldAligned(vec2 p) {
  float r = length(p);
  float ang = atan(p.y, p.x);

  float wedge = PI / 3.0;
  float k = floor((ang + wedge*0.5) / wedge);
  float a = ang - k * wedge;     // [-30..+30]
  a = abs(a);                    // [0..30]

  return vec2(cos(a), sin(a)) * r;
}

// Fold Seamlessly (approx): parity phase
vec2 foldSeamless(vec2 p, float parity) {
  float r = length(p);
  float ang = atan(p.y, p.x);

  ang += parity * (PI / 6.0);
  float wedge = PI / 3.0;
  float k = floor((ang + wedge*0.5) / wedge);
  float a = ang - k * wedge;
  a = abs(a);

  return vec2(cos(a), sin(a)) * r;
}

// Smearing: directional drag/stretch across all modes
vec2 perp(vec2 v) { return vec2(-v.y, v.x); }

vec2 applySmear(vec2 warped, vec2 tileCenter, vec2 CenterPx, float size, float sm01)
{
  vec2 d = tileCenter - CenterPx;
  float dist = length(d);
  vec2 dir = (dist > 1e-5) ? (d / dist) : vec2(1.0, 0.0);
  vec2 tanDir = perp(dir);

  float distN = dist / (size * 6.0 + 1e-5);
  float t = sm01 * clamp(distN, 0.0, 1.5);

  float par = dot(warped, dir);
  float per = dot(warped, tanDir);

  float drag = t * dist * 0.40;
  float stretch = 1.0 + t * (1.35 + 0.85 * clamp(distN, 0.0, 1.0));
  float squeeze = 1.0 - t * 0.22;

  par = par * stretch - drag;
  per = per * squeeze;

  return dir * par + tanDir * per;
}

// Neighbor directions in axial coords (flat-top axial)
vec2 axialDir(int i) {
  if (i == 0) return vec2( 1.0,  0.0);
  if (i == 1) return vec2( 1.0, -1.0);
  if (i == 2) return vec2( 0.0, -1.0);
  if (i == 3) return vec2(-1.0,  0.0);
  if (i == 4) return vec2(-1.0,  1.0);
  return vec2( 0.0,  1.0);
}

// Pick nearest neighbor direction by comparing dot to the 6 neighbor vectors in pixel space
int nearestNeighborDir(vec2 localGrid) {
  vec2 u = normalize(localGrid + vec2(1e-6, 0.0));
  float best = -1e9;
  int bestI = 0;
  for (int i = 0; i < 6; i++) {
    vec2 dp = normalize(axialToPixel(axialDir(i), 1.0));
    float s = dot(u, dp);
    if (s > best) { best = s; bestI = i; }
  }
  return bestI;
}

vec2 wrap01(vec2 uv) { return fract(uv); }

vec4 sampleRepeat(vec2 samplePosPx) {
  vec2 uv = samplePosPx / resolution;
  uv = wrap01(uv);
  vec2 uvBuf = uv * uvScale;
  return texture2D(tDiffuse, uvBuf);
}

void main() {
  vec2 pos = vUv * resolution;

  float size = max(Radius, 0.0001);
  int mode = int(floor(Render + 0.5));
  float lockC = step(0.5, Lock_Center_Tile);
  float theta = radians(Rotate);

  vec2 compCenter = resolution * 0.5;

  // AE behavior notes:
  // Rotate is around Center; when Lock Center Tile is enabled, rotation behaves as comp-centered. [1](https://www.youtube.com/watch?v=OeXte_Q19oQ)[2](https://www.youtube.com/watch?v=sIu3fHVzfwA)
  vec2 gridOrigin  = mix(Center, compCenter, lockC);
  vec2 rotatePivot = mix(Center, compCenter, lockC);

  // ✅ Rotate affects entire honeycomb arrangement: rotate coordinates for quantization
  vec2 posGrid = rotateAround(pos, rotatePivot, -theta);
  vec2 gridOriginGrid = rotateAround(gridOrigin, rotatePivot, -theta);

  vec2 rel = posGrid - gridOriginGrid;

  // nearest hex cell
  vec2 axialF = pixelToAxial(rel, size);
  vec3 cube  = axialToCube(axialF);
  vec3 cubeI = cubeRound(cube);
  vec2 cell  = cubeToAxial(cubeI);

  vec2 tileCenterRel  = axialToPixel(cell, size);
  vec2 tileCenterGrid = gridOriginGrid + tileCenterRel;

  // local in rotated GRID space (for seams + neighbor selection)
  vec2 localGrid = posGrid - tileCenterGrid;

  // tile center back in unrotated space
  vec2 tileCenter = rotateAround(tileCenterGrid, rotatePivot, theta);

  float sm01 = clamp(Smearing / 100.0, 0.0, 1.0);

  // ----------------------------
  // Build "warped" sampling vector
  // ----------------------------
  vec2 warped;

  if (mode == 0) {
    // Tile: repeat around Center
    warped = pos - tileCenter;
  } else {
    // Fold modes should rotate with the honeycomb:
    // fold in GRID space, then rotate back
    vec2 baseGrid = posGrid - tileCenterGrid;

    vec2 foldedGrid;
    if (mode == 1) {
      foldedGrid = foldAligned(baseGrid);
    } else {
      float parity = mod(cell.x + cell.y, 2.0);
      foldedGrid = foldSeamless(baseGrid, parity);
    }

    warped = rot2(foldedGrid, theta);
  }

  // Smearing: directional drag/stretch across all modes (AE-like character) [1](https://www.youtube.com/watch?v=OeXte_Q19oQ)[2](https://www.youtube.com/watch?v=sIu3fHVzfwA)
  warped = applySmear(warped, tileCenter, Center, size, sm01);

  // Current sample
  vec2 samplePos = Center + warped;
  vec4 col = sampleRepeat(samplePos);

  // ----------------------------
  // ✅ Fold Seamlessly: remove seams regardless of rotation
  // - no alpha cutting
  // - blend with neighbor near the closest edge to hide coordinate discontinuities
  // ----------------------------
  if (mode == 2) {
    // distance to hex boundary (negative inside)
    float dEdge = sdHexFlat(localGrid, size);

    // Blend width in pixels (bigger tile => slightly wider blend)
    float seamW = max(1.5, size * 0.08);

    // w = 1 inside, 0 near edge
    float w = smoothstep(0.0, seamW, -dEdge);

    // near the edge, sample the neighbor cell across the nearest edge
    int di = nearestNeighborDir(localGrid);
    vec2 nCell = cell + axialDir(di);

    vec2 nCenterRel  = axialToPixel(nCell, size);
    vec2 nCenterGrid = gridOriginGrid + nCenterRel;
    vec2 nCenter     = rotateAround(nCenterGrid, rotatePivot, theta);

    // neighbor fold in grid space, then rotate back
    vec2 nBaseGrid = posGrid - nCenterGrid;
    float nParity = mod(nCell.x + nCell.y, 2.0);
    vec2 nFoldedGrid = foldSeamless(nBaseGrid, nParity);
    vec2 nWarped = rot2(nFoldedGrid, theta);
    nWarped = applySmear(nWarped, nCenter, Center, size, sm01);

    vec4 colN = sampleRepeat(Center + nWarped);

    // Blend neighbor at boundary to hide seams (rotation-safe)
    col = mix(colN, col, w);

    // No alpha seam in Fold Seamlessly, like AE mode intent [2](https://www.youtube.com/watch?v=sIu3fHVzfwA)[1](https://www.youtube.com/watch?v=OeXte_Q19oQ)
    gl_FragColor = col;
    return;
  }

  // ----------------------------
  // Tile / Fold Aligned: allow visible hex edges via alpha (like AE can show seams) [2](https://www.youtube.com/watch?v=sIu3fHVzfwA)[1](https://www.youtube.com/watch?v=OeXte_Q19oQ)
  // ----------------------------
  float alpha = 1.0;
  {
    float d = sdHexFlat(localGrid, size);
    float aa = 1.25; // constant px smoothing (no derivatives)
    alpha = smoothstep(0.0, -aa, d);
  }

  gl_FragColor = vec4(col.rgb, col.a * alpha);
}

text./plugins/alipfx/shaders/az-jaws.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// ---- Panzoid custom properties (dynamic) ----
uniform float Completion; // 0..100
uniform vec2  Center;     // 0..1 (or pixels, auto-detect)
uniform float Direction;  // degrees
uniform float Height;     // 0..100
uniform float Width;      // 2..25 recommended
uniform float Shape;      // 0..3 (0 Spikes, 1 RoboJaw, 2 Block, 3 Waves)

const float PI = 3.14159265358979323846;

// Anti-alias without derivatives
const float AA_MULT = 1.6;

// Bevel tuning (subtle)
const float BEVEL_PIXELS    = 2.0;
const float BEVEL_HIGHLIGHT = 0.08;
const float BEVEL_SHADOW    = 0.10;

// Triangle wave 0..1
float tri01(float x) {
  float f = fract(x);
  return 1.0 - abs(f - 0.5) * 2.0;
}

void main() {
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // --- Center supports normalized OR AE pixels ---
  vec2 centerUV = Center;
  if (centerUV.x > 1.5 || centerUV.y > 1.5) {
    centerUV = centerUV / max(resolution, vec2(1.0));
  }

  // --- Clamp Completion like AE ---
  float comp = clamp(Completion, 0.0, 100.0);
  float prog = comp / 100.0;

  // --- Aspect correction so Direction behaves consistently ---
  float aspect = resolution.x / max(1.0, resolution.y);
  vec2 asp = vec2(aspect, 1.0);

  // Position in aspect-corrected space
  vec2 p = (vUv - centerUV) * asp;

  // Direction: 0° = horizontal band, 90° = vertical band
  float ang = radians(Direction);
  vec2 tAxis = normalize(vec2(cos(ang), sin(ang))); // along teeth repetition
  vec2 nAxis = vec2(-tAxis.y, tAxis.x);             // opening axis (perpendicular)

  float t = dot(p, tAxis);
  float n = dot(p, nAxis);

  // --- AA without derivatives ---
  float px = (1.0 / max(1.0, min(resolution.x, resolution.y))) * max(asp.x, asp.y);
  float aa = max(px * AA_MULT, 0.00025);

  // --- Tooth amplitude from Height (CONSTANT, not scaled by Completion) ---
  float h = clamp(Height / 100.0, 0.0, 1.0);
  float compScale = length(asp);
  float amp = h * compScale * 0.35;

  // --- Width density ---
  float w = clamp(Width, 2.0, 25.0);
  float x = (t / (2.0 * compScale)) * w;

  // --- Shape selection ---
  int sh = int(floor(Shape + 0.5));

  // pat in [0..1]
  float pat = 0.0;

  if (sh == 0) {
    // Spikes
    pat = tri01(x);

  } 
else if (sh == 1) {
  // ✅ RoboJaw (stable thickness) — AE-like chunky trapezoids
  // This produces flat TOP + flat BOTTOM (like your AE screenshot),
  // not pointy triangle peaks.

  float flatness = 0.25;   // higher = more blocky (try 0.60..0.90)
  float phase    = 0.00;   // try 0.0 or 0.25 if alignment looks off

  // Triangle wave 0..1
  float tri = tri01(x + phase);

  // Convert flatness into symmetric clipping near 0 and 1
  // flatness=0 -> pure triangle
  // flatness=1 -> almost square wave
  float edge = (1.0 - clamp(flatness, 0.0, 1.0)) * 0.5;

  // Double-clip triangle into trapezoid (flat bottom + flat top)
  pat = clamp((tri - edge) / max(1e-6, (1.0 - 2.0 * edge)), 0.0, 1.0);

  } else if (sh == 2) {
    // Block (AE-style): square-wave steps (no diagonal stairs)
    float f = fract(x + 0.25);
    pat = step(0.5, f);

  } else {
    // Waves
    pat = 0.5 + 0.5 * sin(2.0 * PI * x);
  }

  // --- Convert pat to centered offset [-1..1] ---
  // IMPORTANT: using same offset on BOTH edges keeps thickness constant.
  float patC = (pat - 0.5) * 2.0; // -1..1

  // --- Compute distance to corners so Completion=100 always finishes ---
  vec2 c0 = (vec2(0.0, 0.0) - centerUV) * asp;
  vec2 c1 = (vec2(1.0, 0.0) - centerUV) * asp;
  vec2 c2 = (vec2(0.0, 1.0) - centerUV) * asp;
  vec2 c3 = (vec2(1.0, 1.0) - centerUV) * asp;

  float maxN = max(
    max(abs(dot(c0, nAxis)), abs(dot(c1, nAxis))),
    max(abs(dot(c2, nAxis)), abs(dot(c3, nAxis)))
  );

  // Opening depends ONLY on completion (not on tooth shape)
  float halfGap = prog * (maxN + amp + aa * 2.0 + 1e-4);

  // Stable thickness edges
  float offset = amp * patC;
  float topEdge =  halfGap + offset;
  float botEdge = -halfGap + offset;

  // Mask: inside band becomes transparent
  float inTop = smoothstep(topEdge + aa, topEdge - aa, n);
  float inBot = smoothstep(botEdge - aa, botEdge + aa, n);
  float bandMask = clamp(inTop * inBot, 0.0, 1.0);

  float outA = texel.a * (1.0 - bandMask);

  // --- Subtle bevel on opaque side only ---
  float bevelW = px * BEVEL_PIXELS;

  float topOpaque = step(0.0, n - topEdge);
  float topBevel  = topOpaque * (1.0 - smoothstep(0.0, bevelW, n - topEdge));

  float botOpaque = step(0.0, botEdge - n);
  float botBevel  = botOpaque * (1.0 - smoothstep(0.0, bevelW, botEdge - n));

  vec3 col = texel.rgb;
  col *= (1.0 + BEVEL_HIGHLIGHT * topBevel);
  col *= (1.0 - BEVEL_SHADOW    * botBevel);

  // Perfect endpoints
  if (comp <= 0.0001) outA = texel.a;
  if (comp >= 99.9999) outA = 0.0;

  gl_FragColor = vec4(col, outA);
}

text./plugins/alipfx/shaders/az-kaleida.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

// Panzoid properties
uniform vec2 Center;            // pixels (AE-style: origin top-left, Y down)
uniform float Size;             // pixels
uniform float Mirroring;        // 0..8 (rounded to int)
uniform float Rotation;         // degrees
uniform float Floating_Center;  // 0 or 1

#define PI 3.14159265358979323846

// 2D rotation matrix
mat2 rot2(float a) {
  float s = sin(a), c = cos(a);
  return mat2(c, -s, s, c);
}

// Mirror-repeat (triangle wave): maps any x to [0..1] with mirrored tiling.
float tri(float x) {
  float f = fract(x);
  return 1.0 - abs(1.0 - 2.0 * f);
}
vec2 tri2(vec2 p) {
  return vec2(tri(p.x), tri(p.y));
}

// --- Mirroring mode helpers ---

// "Flower-ish" fold inside a tile (f in [0..1])
vec2 foldFlower(vec2 f) {
  vec2 s = abs(f - 0.5);     // [0..0.5]
  if (s.y > s.x) s = s.yx;   // fold over diagonal
  return 0.5 + s;
}

// "Wheel" look via quadrant-dependent axis swap
vec2 foldWheel(vec2 f) {
  vec2 s = f - 0.5;
  float qx = step(0.0, s.x);
  float qy = step(0.0, s.y);
  float doSwap = abs(qx - qy);
  s = abs(s);
  vec2 ss = mix(s, s.yx, doSwap);
  return 0.5 + ss;
}

// "Dia Cross" via folding in 45°-rotated space
vec2 foldDiaCross(vec2 f) {
  vec2 s = f - 0.5;
  s = rot2(PI * 0.25) * s;
  vec2 m = tri2(s + 0.5) - 0.5;
  m = rot2(-PI * 0.25) * m;
  return m + 0.5;
}

/*
  Fish-style polar fold:
  - We rotate the FINAL vector output for Can Meas (90° difference).
*/
vec2 foldFish(vec2 f, float outRot) {
  vec2 s = f - 0.5;
  float r = length(s) * 2.0;
  float a = atan(s.y, s.x);

  a = mod(a, PI * 0.5);
  a = abs(a - PI * 0.25);

  r = pow(clamp(r, 0.0, 1.5), 0.85);

  vec2 v = vec2(cos(a), sin(a)) * (0.5 * r);
  v = rot2(outRot) * v;

  return 0.5 + v;
}

// Flipper: rotate every other row 180°
vec2 foldFlipper(vec2 q) {
  vec2 tile = floor(q);
  vec2 f = fract(q);
  float oddRow = mod(tile.y, 2.0);
  if (oddRow > 0.5) f = 1.0 - f;
  return f;
}

// Flip Flop: flip all upside down, mirror alternating columns
vec2 foldFlipFlop(vec2 q) {
  vec2 tile = floor(q);
  vec2 f = fract(q);
  f.y = 1.0 - f.y;
  float oddCol = mod(tile.x, 2.0);
  if (oddCol > 0.5) f.x = 1.0 - f.x;
  return f;
}

// Starlish: denser folding
vec2 foldStarlish(vec2 f) {
  vec2 s = f - 0.5;
  s = rot2(PI / 8.0) * s;
  vec2 g = foldFlower(s + 0.5) - 0.5;
  g = rot2(-PI / 8.0) * g;
  return foldDiaCross(g + 0.5);
}

// Mirroring selector
vec2 mapMirroring(vec2 q, int mode) {
  vec2 f = fract(q);

  if (mode == 0) return tri2(q);                 // Unfold
  if (mode == 1) return foldWheel(f);            // Wheel
  if (mode == 2) return foldFish(f, 0.0);        // Fish Head
  if (mode == 3) return foldFish(f, PI * 0.5);   // Can Meas
  if (mode == 4) return foldFlipFlop(q);         // Flip Flop

  // ✅ FIX: Flower uses straight repeating tile space (AE-like)
  // This makes Size behave "straight" instead of alternating mirrored tiles.
  if (mode == 5) return foldFlower(f);           // Flower (FIXED)

  if (mode == 6) return foldDiaCross(f);         // Dia Cross
  if (mode == 7) return foldFlipper(q);          // Flipper
  if (mode == 8) {                               // Starlish
    vec2 m = tri2(q);
    return foldStarlish(m);
  }

  return f;
}

void main() {
  // Panzoid UV rule: vUvScaled is vUv * uvScale, so undo it for 0..1 UV. [1](https://www.shadertoy.com/)
  vec2 uv = vUvScaled / uvScale;

  float sz = max(Size, 0.0001);

  // Center fix (AE pixels Y-down -> Panzoid UV Y-up)
  vec2 sourceCenterUV = vec2(
    Center.x / resolution.x,
    1.0 - (Center.y / resolution.y)
  );

  // Pivot behavior
  vec2 pivotUV = vec2(0.5);
  if (Floating_Center > 0.5) {
    pivotUV = sourceCenterUV;
  }

  // Pixel offset from pivot
  vec2 p = (uv - pivotUV) * resolution;

  // Tile coordinates (tile center at 0.5)
  vec2 q = (p / sz) + 0.5;

  // Mirroring mode (rounded)
  int mode = int(floor(Mirroring + 0.5));
  mode = int(clamp(float(mode), 0.0, 8.0));

  // Local coordinate in [0..1]
  vec2 local = mapMirroring(q, mode);

  // Convert back into pixel offset inside the tile
  vec2 sampleOffset = (local - 0.5) * sz;

  // Rotate sampled area (degrees → radians)
  sampleOffset = rot2(radians(Rotation)) * sampleOffset;

  // Sample around source center
  vec2 sampleUV = sourceCenterUV + (sampleOffset / resolution);

  // Mirror-repeat outside 0..1
  sampleUV = tri2(sampleUV);

  // Panzoid sampling rule: scale UV back into buffer space using uvScale. [1](https://www.shadertoy.com/)
  vec2 sampleUVScaled = sampleUV * uvScale;

  gl_FragColor = texture2D(tDiffuse, sampleUVScaled);
}

text./plugins/alipfx/shaders/az-lens.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;

// ---- Custom properties (Panzoid UI) ----
uniform vec2 Center;        // AE PIXELS ONLY (0,0)=TOP-LEFT like AE
uniform float Size;         // 0..500
uniform float Convergence;  // ~ -200..100

#define CUTOUT_OUTSIDE 1
#define USE_INPUT_ALPHA_AS_MASK 0

float saturate(float x) { return clamp(x, 0.0, 1.0); }

// GLSL ES safe tanh approximation (soft clamp)
float tanh_approx(float x)
{
    x = clamp(x, -6.0, 6.0);
    float e2x = exp(2.0 * x);
    return (e2x - 1.0) / (e2x + 1.0);
}

// AE pixels -> Panzoid UV (bottom-left)
vec2 getCenterUV()
{
    vec2 c01 = vec2(Center.x / resolution.x, Center.y / resolution.y);
    return vec2(c01.x, 1.0 - c01.y);
}

// Out-of-bounds returns transparent/black (good for cutouts)
vec4 sampleWithTransparentBorders(vec2 uv01)
{
    if (uv01.x < 0.0 || uv01.x > 1.0 || uv01.y < 0.0 || uv01.y > 1.0)
        return vec4(0.0);
    return texture2D(tDiffuse, uv01 * uvScale);
}

// Clamp UV only (used inside the lens so refraction doesn't "die" early)
vec4 sampleClamped(vec2 uv01)
{
    uv01 = clamp(uv01, vec2(0.0), vec2(1.0));
    return texture2D(tDiffuse, uv01 * uvScale);
}

vec2 ccLensWarp(vec2 uv01, float Rpx, float k, float edge, float sizeAtten)
{
    vec2 centerUV = getCenterUV();

    vec2 p = uv01 * resolution;
    vec2 c = centerUV * resolution;
    vec2 d = p - c;

    float r = length(d);
    if (r < 1e-6) return uv01;

    // NEGATIVE convergence (pinch)
    if (k < 0.0)
    {
        float rn = r / max(Rpx, 1e-4);
        float negStrength = tanh_approx(abs(k) * 1.20);
        rn = clamp(rn, 0.0, 2.5);
        float radial = rn * rn;

        float scale = 1.0 + (negStrength * radial * 0.85) * sizeAtten;
        vec2 warpedPx = c + d * scale;
        return warpedPx / resolution;
    }

    // POSITIVE convergence: stable radial refraction (no flip)
    vec2 nd = d / max(Rpx, 1e-4);
    float rr = dot(nd, nd);
    float z = sqrt(max(0.0, 1.0 - rr));

    float strength = tanh_approx(abs(k) * 0.75);
    float ior = mix(1.0, 1.75, strength);

    vec3 I = vec3(0.0, 0.0, -1.0);
    vec3 N = normalize(vec3(nd.x, nd.y, z));

    float eta = 1.0 / ior;
    vec3 T = refract(I, N, eta);

    float s = (1.10 * strength) * edge * sizeAtten;

    float u = clamp(r / max(Rpx, 1e-4), 0.0, 1.0);
    float rim = smoothstep(0.75, 1.0, u);

    float denom = abs(T.z) + mix(0.06, 0.28, rim);
    vec2 proj = T.xy / denom;

    // Radial-only component (prevents twist/flip)
    vec2 radialDir = d / r;
    float radialScalar = dot(proj, radialDir);

    // Soft clamp scalar (keeps response but prevents spikes)
    float maxDisp = mix(2.2, 1.2, rim);
    radialScalar = tanh_approx(radialScalar / maxDisp) * maxDisp;

    // Convert to pixel displacement and clamp inside lens radius (prevents "dies at size=4")
    float dispPx = radialScalar * (Rpx * s);
    dispPx = clamp(dispPx, -0.95 * Rpx, 0.95 * Rpx);

    vec2 offsetPx = radialDir * dispPx;

    // If bulge direction feels inverted vs AE, switch + to -
    vec2 warpedPx = p + offsetPx;

    return warpedPx / resolution;
}

void main()
{
    vec2 uv = vUv;

    // Size=0 => OPAQUE BLACK (your expectation)
    if (Size <= 0.0001)
    {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    vec2 centerUV = getCenterUV();
    float minDim = min(resolution.x, resolution.y);

    // ==========================================================
    // ✅ NEW SIZE MAPPING:
    // Size=10 -> ~150px radius on 1080p
    // Size=50 -> minDim/2 (touch comp top/bottom when centered)
    // ==========================================================
    const float SIZE_EXP = 0.79588895;  // solved from the two anchors (10->150px, 50->minDim/2)
    float sizeNorm = max(Size, 0.0001) / 50.0;
    float R = (minDim * 0.5) * pow(sizeNorm, SIZE_EXP);
    R = max(R, 1e-4);

    // Distortion scaling (kept)
    float sizeAtten = inversesqrt(max(Size / 50.0, 1e-4));
    float k = (Convergence / 100.0) * sizeAtten;

    // Distance from center
    vec2 p = uv * resolution;
    vec2 c = centerUV * resolution;
    float distPx = length(p - c);
    float t = distPx / R;

    // Thin crisp rim (AE-like)
    float featherPx = 1.25;
    float feather = clamp(featherPx / max(R, 1.0), 0.0008, 0.02);

    float lensMask = 1.0 - smoothstep(1.0 - feather, 1.0, t);
    float edge = lensMask;

    vec4 base = texture2D(tDiffuse, uv * uvScale);

    // If convergence ~0 => no effect
    if (abs(k) < 1e-6)
    {
        gl_FragColor = base;
        return;
    }

    // Outside lens
    if (t >= 1.0)
    {
        #if CUTOUT_OUTSIDE
            gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
        #else
            gl_FragColor = base;
        #endif
        return;
    }

    // Warp + sample (INSIDE lens we clamp UV so it doesn't die early)
    vec2 warpedUV = ccLensWarp(uv, R, k, edge, sizeAtten);
    vec4 warpedTex = sampleClamped(warpedUV);

    float a = lensMask;
    #if USE_INPUT_ALPHA_AS_MASK
        a *= warpedTex.a;
    #endif

    // Premultiply so edges behave cleanly
    gl_FragColor = vec4(warpedTex.rgb * a, a);
}

text./plugins/alipfx/shaders/az-light-burst-2:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

/* ---- Custom properties ---- */
uniform vec2 Center;        // pixels (AE-style: origin top-left, Y down)
uniform float Intensity;    // 100 = default-ish
uniform float Ray_Length;   // pixels
uniform float Burst;        // 0 Straight, 1 Fade, 2 Center
uniform float Halo_Alpha;   // 0/1
uniform float Set_Color;    // 0/1
uniform vec3 Color;         // tint color

float luma(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

vec4 texAt(vec2 uv01) {
  return texture2D(tDiffuse, uv01 * uvScale);
}

float alphaEdge(vec2 uv01) {
  vec2 px = 1.0 / resolution;

  float ax = texAt(uv01 + vec2(px.x, 0.0)).a;
  float bx = texAt(uv01 - vec2(px.x, 0.0)).a;
  float ay = texAt(uv01 + vec2(0.0, px.y)).a;
  float by = texAt(uv01 - vec2(0.0, px.y)).a;

  float gx = abs(ax - bx);
  float gy = abs(ay - by);

  return clamp((gx + gy) * 0.75, 0.0, 1.0);
}

float sourceStrength(vec4 s, vec2 uv01) {
  if (Halo_Alpha >= 0.5) {
    return alphaEdge(uv01);
  } else {
    return clamp(luma(s.rgb) * s.a, 0.0, 1.0);
  }
}

void main() {
  vec2 uv = vUv;
  vec4 base = texture2D(tDiffuse, vUvScaled);

  // AE-style pixel center -> Panzoid UV (flip Y)
  vec2 cUv = vec2(
    Center.x / resolution.x,
    1.0 - (Center.y / resolution.y)
  );

  vec2 d = uv - cUv;
  float dist = length(d);
  vec2 dir = d / max(dist, 1e-6);

  // Ray length in pixels -> UV (use min dimension for consistent feel)
  float denom = max(min(resolution.x, resolution.y), 1.0);
  float rayLenUv = abs(Ray_Length) / denom;

  const int MAX_SAMPLES = 96;

  float lenPx = abs(Ray_Length);

  // sample count scales with length (smooth like AE)
  float sCount = clamp(10.0 + sqrt(lenPx) * 6.0, 12.0, float(MAX_SAMPLES));
  int samples = int(sCount);

  // ✅ avoid max(int,int) : make safeSamples as float
  int safeSamplesInt = (samples > 0) ? samples : 1;
  float safeSamples = float(safeSamplesInt);

  float stepUv = rayLenUv / safeSamples;

  vec3 accumRGB = vec3(0.0);
  float accumA = 0.0;
  float wsum = 0.0;

  float inten = max(Intensity, 0.0) / 100.0;
  int mode = int(floor(Burst + 0.5)); // 0/1/2

  for (int i = 0; i < MAX_SAMPLES; i++) {
    if (i >= samples) break;

    float t = float(i) * stepUv;

    // sample toward center (gives outward streaks)
    vec2 suv1 = clamp(uv - dir * t, vec2(0.0), vec2(1.0));
    vec4 s1 = texAt(suv1);
    float src1 = sourceStrength(s1, suv1);

    float w1 = 1.0;

    // Fade mode falloff
    if (mode == 1) {
      float f = 1.0 - (t / max(rayLenUv, 1e-6));
      w1 = clamp(f * f, 0.0, 1.0);
    }

    vec3 rayColor1 = (Set_Color >= 0.5) ? Color : s1.rgb;

    accumRGB += rayColor1 * (src1 * w1);
    accumA   += src1 * w1;
    wsum     += w1;

    // Center mode: blur both directions
    if (mode == 2) {
      vec2 suv2 = clamp(uv + dir * t, vec2(0.0), vec2(1.0));
      vec4 s2 = texAt(suv2);
      float src2 = sourceStrength(s2, suv2);

      vec3 rayColor2 = (Set_Color >= 0.5) ? Color : s2.rgb;

      accumRGB += rayColor2 * (src2 * w1);
      accumA   += src2 * w1;
      wsum     += w1;
    }
  }

  vec3 burstRGB = (wsum > 0.0) ? (accumRGB / wsum) : vec3(0.0);
  float burstA  = (wsum > 0.0) ? (accumA   / wsum) : 0.0;

  // Intensity response (AE-ish additive light)
  burstA   = clamp(burstA * inten, 0.0, 8.0);
  burstRGB = burstRGB * burstA;

  vec3 outRGB = base.rgb + burstRGB;
  float outA  = clamp(max(base.a, base.a + burstA * 0.25), 0.0, 1.0);

  gl_FragColor = vec4(outRGB, outA);
}

text./plugins/alipfx/shaders/az-light-rays.gl:
precision highp float;
precision highp int;

// Core Panzoid Uniforms
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// --- User Parameters (Create these 10 properties in Panzoid) ---
uniform float Intensity;          // 1. Intensity
uniform vec2 Center;              // 2. Center (pixels)
uniform float Radius;             // 3. Radius
uniform float Warp_Softness;      // 4. Warp Softness
uniform int Shape;                // 5. Shape (0 Round, 1 Square)
uniform float Direction;          // 6. Direction
uniform int Color_from_Source;    // 7. Color from Source (0/1)
uniform int Allow_Brightening;    // 8. Allow Brightening (0/1)
uniform vec3 Color;               // 9. Color
uniform int Transfer_Mode;        // 10. Transfer Mode (0..3)

#define SAMPLES 64

// Helper function to calculate the shape mask (your original, with safe softness clamp)
float getShapeMask(vec2 samplePosPx, vec2 centerPx, float r, float softness, int shapeType, float angle) {
    vec2 p = samplePosPx - centerPx;
    float dist = 0.0;

    if (shapeType == 0) {
        dist = length(p);
    } else {
        float rad = radians(angle);
        float s = sin(rad);
        float c = cos(rad);
        vec2 pRot = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
        dist = max(abs(pRot.x), abs(pRot.y));
    }

    // Clamp softness so smoothstep range is valid
    float soft = clamp(softness, 0.0, max(r, 0.0));
    return 1.0 - smoothstep(r - soft, r, dist);
}

// NEW: distance-to-shape (Round/Square) in pixels
float getShapeDist(vec2 posPx, vec2 centerPx, int shapeType, float angle) {
    vec2 p = posPx - centerPx;

    if (shapeType == 0) {
        return length(p);
    } else {
        float rad = radians(angle);
        float s = sin(rad);
        float c = cos(rad);
        vec2 pRot = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
        return max(abs(pRot.x), abs(pRot.y));
    }
}

void main() {
    // Current pixel coordinate in UV (0-1) (your original approach)
    vec2 uv = vUvScaled;

    // Convert Center from Pixel coordinates to UV space for direction calculation
    vec2 centerUV = Center / resolution;

    // Calculate vector from current pixel TO the center
    vec2 dir = centerUV - uv;

    // Step size for the loop
    vec2 delta = dir / float(SAMPLES);

    // Ray accumulation
    vec3 accColor = vec3(0.0);
    vec2 sampleUV = uv;

    // Loop to trace the light path
    for(int i = 0; i < SAMPLES; i++) {
        sampleUV += delta;

        vec4 sampleTex = texture2D(tDiffuse, sampleUV);
        vec3 sampleLight = sampleTex.rgb;

        // Apply "Color from Source" Logic
        if (Color_from_Source == 0) {
            float luma = dot(sampleLight, vec3(0.299, 0.587, 0.114));
            sampleLight = Color * luma;
        }

        // Mask in pixel space
        vec2 samplePx = sampleUV * resolution;
        float mask = getShapeMask(samplePx, Center, Radius, Warp_Softness, Shape, Direction);

        // Accumulate
        accColor += sampleLight * mask;
    }

    // Normalize and Intensity Application (your original scaling)
    vec3 rayColor = (accColor / float(SAMPLES)) * (Intensity * 0.05);

    // --- Compositing (Transfer Mode) ---
    vec4 original = texture2D(tDiffuse, uv);
    vec3 finalColor = original.rgb;

    if (Transfer_Mode == 0) {
        finalColor = rayColor; // None: rays only
    } else if (Transfer_Mode == 1) {
        finalColor += rayColor; // Add
    } else if (Transfer_Mode == 2) {
        finalColor = max(finalColor, rayColor); // Lighten
    } else if (Transfer_Mode == 3) {
        finalColor = 1.0 - (1.0 - finalColor) * (1.0 - rayColor); // Screen
    }

    // ✅ AE-TIGHTER "Allow Brightening" behavior:
    // In AE, this toggle mainly affects whether the SOURCE/EMITTER region is allowed to brighten,
    // and it's most relevant when "Color from Source" is ON. [1](https://blog.csdn.net/qq_41176800/article/details/132644702)
    //
    // When OFF: keep the emitter CORE unaltered, but allow feather/rays outside.
    // Core = (Radius - WarpSoftness), matching your smoothstep feather model. [1](https://blog.csdn.net/qq_41176800/article/details/132644702)
    if (Allow_Brightening == 0 && Color_from_Source == 1 && Transfer_Mode != 0) {

        vec2 thisPx = uv * resolution;

        float d = getShapeDist(thisPx, Center, Shape, Direction);

        float soft = clamp(Warp_Softness, 0.0, max(Radius, 0.0));
        float coreR = max(Radius - soft, 0.0);

        // Small smoothing band to avoid jagged edges (≈1px)
        float edge = 1.0;

        // coreMask = 1 inside core, 0 outside
        float coreMask = 1.0 - smoothstep(coreR - edge, coreR + edge, d);

        // Restore original ONLY in the core (prevents source brightening)
        finalColor = mix(finalColor, original.rgb, coreMask);
    }

    // Optional clamp if you still want it (AE doesn't just clamp; it prevents core brightening)
    // Keep your old clamp behavior only if you want extra safety:
    // if (Allow_Brightening == 0) rayColor = clamp(rayColor, 0.0, 1.0);

    gl_FragColor = vec4(finalColor, original.a);
}

text./plugins/alipfx/shaders/az-light-sweep.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

/*
  === 9 PARAMETERS ===
  Center            : vec2  (NOW IN AE PIXELS!)
  Direction         : float (degrees)
  Shapes            : float (0 Linear, 1 Smooth, 2 Sharp)
  Width             : float (pixels)
  Sweep_Intensity   : float (percent-like)
  Edge_Intensity    : float (percent-like)
  Edge_Thickness    : float (pixels)
  Light_Color       : vec3
  Light_Reception   : float (0 Add, 1 Composite, 2 Cutout)
*/

uniform vec2  Center;
uniform float Direction;
uniform float Shapes;
uniform float Width;
uniform float Sweep_Intensity;
uniform float Edge_Intensity;
uniform float Edge_Thickness;
uniform vec3  Light_Color;
uniform float Light_Reception;

float saturate(float x) { return clamp(x, 0.0, 1.0); }

vec4 sampleLayer(vec2 uv01)
{
  return texture2D(tDiffuse, uv01 * uvScale);
}

float bandFalloff(float d, float halfW, float shapeMode)
{
  float t = saturate(1.0 - d / max(halfW, 1e-6));

  if (shapeMode < 0.5)        return t;                               // Linear
  else if (shapeMode < 1.5)   return t * t * (3.0 - 2.0 * t);         // Smooth
  else                       return pow(t, 8.0);                      // Sharp
}

float edgeMask(vec2 uv01, float thicknessPx)
{
  float minRes = min(resolution.x, resolution.y);
  float px = 1.0 / max(minRes, 1.0);

  float r1 = px;
  float r2 = max(thicknessPx / max(minRes, 1.0), px);

  float a0 = sampleLayer(uv01).a;
  if (a0 <= 0.0) return 0.0;

  float ax1 = sampleLayer(uv01 + vec2( r1, 0.0)).a;
  float ax2 = sampleLayer(uv01 + vec2(-r1, 0.0)).a;
  float ay1 = sampleLayer(uv01 + vec2(0.0,  r1)).a;
  float ay2 = sampleLayer(uv01 + vec2(0.0, -r1)).a;

  float bx1 = sampleLayer(uv01 + vec2( r2, 0.0)).a;
  float bx2 = sampleLayer(uv01 + vec2(-r2, 0.0)).a;
  float by1 = sampleLayer(uv01 + vec2(0.0,  r2)).a;
  float by2 = sampleLayer(uv01 + vec2(0.0, -r2)).a;

  float g1 = (abs(a0 - ax1) + abs(a0 - ax2) + abs(a0 - ay1) + abs(a0 - ay2)) * 0.25;
  float g2 = (abs(a0 - bx1) + abs(a0 - bx2) + abs(a0 - by1) + abs(a0 - by2)) * 0.25;

  float g = max(g1, g2);
  float edge = saturate(g * 6.0);

  return edge * a0;
}

void main()
{
  vec4 base = texture2D(tDiffuse, vUvScaled);

  vec2 uv = vUv;

  // === 1) Center (AE PIXELS -> UV) ===
  // AE pixel origin = top-left (y down). Panzoid vUv origin = bottom-left (y up).
  // Convert pixels to normalized UV and flip Y.
  vec2 c = vec2(
    Center.x / max(resolution.x, 1.0),
    1.0 - (Center.y / max(resolution.y, 1.0))
  );

  // === 2) Direction ===
  float rad = radians(Direction);
  vec2 axis = normalize(vec2(sin(rad), cos(rad))); // 0° vertical, 90° horizontal
  vec2 nrm  = vec2(axis.y, -axis.x);

  float dist = dot(uv - c, nrm);
  float ad   = abs(dist);

  // === 4) Width (px -> normalized) ===
  float minRes = min(resolution.x, resolution.y);
  float halfW = (max(Width, 0.0) / max(minRes, 1.0));

  // === 3) Shapes ===
  float sweepMask = bandFalloff(ad, halfW, Shapes);
  sweepMask = saturate(sweepMask + pow(sweepMask, 6.0) * 0.25); // subtle hot core

  // === 7) Edge Thickness ===
  float eMask = edgeMask(uv, Edge_Thickness);
  float edgeSweep = eMask * sweepMask;

  // === 5/6) Intensities ===
  float sweepI = Sweep_Intensity / 100.0;
  float edgeI  = Edge_Intensity  / 100.0;

  float lightAmount = (sweepMask * sweepI + edgeSweep * edgeI) * base.a;

  // === 8) Light Color ===
  vec3 lightRGB = Light_Color * lightAmount;

  // === 9) Light Reception ===
  vec3 outRGB = base.rgb;
  float outA  = base.a;

  if (Light_Reception < 0.5)             // Add
  {
    outRGB = base.rgb + lightRGB;
  }
  else if (Light_Reception < 1.5)        // Composite (screen-like)
  {
    outRGB = 1.0 - (1.0 - base.rgb) * (1.0 - lightRGB);
  }
  else                                   // Cutout
  {
    outRGB = base.rgb * sweepMask + (Light_Color * (sweepMask * sweepI + edgeSweep * edgeI)) * base.a;
    outA   = base.a * sweepMask;
  }

  gl_FragColor = vec4(clamp(outRGB, 0.0, 1.0), saturate(outA));
}

text./plugins/alipfx/shaders/az-light-wipe.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// Panzoid properties (names must match your UI properties)
uniform float Completion;            // 0..100
uniform vec2  Center;                // 0..1
uniform float Intensity;             // 0..100
uniform float Shape;                 // 0=Doors, 1=Radial, 2=Square
uniform float Direction;             // degrees
uniform float Color_From_Source;     // 0/1
uniform vec3  Color;                 // tint
uniform float Reverse_Transition;    // 0/1

// Hash helpers
float hash1(float n) { return fract(sin(n) * 43758.5453123); }

// Screen blend (AE-like brightening)
vec3 screenBlend(vec3 a, vec3 b) { return 1.0 - (1.0 - a) * (1.0 - b); }

// Max distance to cover full frame (pixel space)
float maxDistanceForShape(int shapeId, vec2 centerPx, vec2 dirUnit, vec2 orthoUnit) {
  vec2 c0 = vec2(0.0, 0.0) - centerPx;
  vec2 c1 = vec2(resolution.x, 0.0) - centerPx;
  vec2 c2 = vec2(0.0, resolution.y) - centerPx;
  vec2 c3 = vec2(resolution.x, resolution.y) - centerPx;

  float m = 0.0;

  if (shapeId == 1) {
    m = max(m, length(c0));
    m = max(m, length(c1));
    m = max(m, length(c2));
    m = max(m, length(c3));
  } else {
    // helper: evaluate
    float x0 = dot(c0, dirUnit), y0 = dot(c0, orthoUnit);
    float x1 = dot(c1, dirUnit), y1 = dot(c1, orthoUnit);
    float x2 = dot(c2, dirUnit), y2 = dot(c2, orthoUnit);
    float x3 = dot(c3, dirUnit), y3 = dot(c3, orthoUnit);

    if (shapeId == 2) {
      m = max(m, max(abs(x0), abs(y0)));
      m = max(m, max(abs(x1), abs(y1)));
      m = max(m, max(abs(x2), abs(y2)));
      m = max(m, max(abs(x3), abs(y3)));
    } else {
      m = max(m, abs(y0));
      m = max(m, abs(y1));
      m = max(m, abs(y2));
      m = max(m, abs(y3));
    }
  }

  return max(m, 1.0);
}

void main() {
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // Normalize parameters
  float c = clamp(Completion / 100.0, 0.0, 1.0);
  float inten = clamp(Intensity / 100.0, 0.0, 1.0);
  // Make intensity feel more AE-like (stronger at higher values)
  float intenPow = pow(inten, 0.65);

  int shapeId = int(floor(Shape + 0.5)); // 0,1,2

  // Direction disabled for radial in AE
  float ang = radians(Direction);
  if (shapeId == 1) ang = 0.0;

  vec2 centerUv = Center;
  vec2 centerPx = centerUv * resolution;

  // Pixel space from center
  vec2 pPx = (vUv - centerUv) * resolution;

  // Direction basis
  vec2 dirUnit   = vec2(cos(ang), sin(ang));
  vec2 orthoUnit = vec2(-dirUnit.y, dirUnit.x);

  // Distance field per shape (pixels)
  float d;
  vec2 normalUnit;

  if (shapeId == 1) {
    float lenp = max(length(pPx), 1e-6);
    d = lenp;
    normalUnit = pPx / lenp;
  } else {
    float x = dot(pPx, dirUnit);
    float y = dot(pPx, orthoUnit);

    if (shapeId == 2) {
      float ax = abs(x), ay = abs(y);
      d = max(ax, ay);

      if (ax > ay) normalUnit = dirUnit * sign(x);
      else         normalUnit = orthoUnit * sign(y);

      if (length(normalUnit) < 1e-6) normalUnit = dirUnit;
    } else {
      d = abs(y);
      normalUnit = orthoUnit * (y >= 0.0 ? 1.0 : -1.0);
    }
  }

  float maxD = maxDistanceForShape(shapeId, centerPx, dirUnit, orthoUnit);

  // Boundary based on completion & reverse
  float boundary = (Reverse_Transition >= 0.5)
    ? (1.0 - c) * maxD
    : c * maxD;

  // Signed distance relative to boundary (pixels)
  float s = d - boundary;

  // Anti-alias width (no derivatives available)
  float aa = 1.25;

  // Opaque mask: 100% completion => transparent (transition finished)
  float opaque;
  if (Reverse_Transition >= 0.5) {
    // Opaque INSIDE the shrinking region
    opaque = smoothstep(-aa, aa, -s);
  } else {
    // Opaque OUTSIDE the expanding wiped region
    opaque = smoothstep(-aa, aa,  s);
  }

  // ---------------------------
  // AE-LIKE HALO: core + glow
  // ---------------------------

  float distToEdge = abs(s);

  // Thin bright core line (~1-2px)
  float coreWidth = mix(2.2, 1.2, intenPow);
  float core = exp(-distToEdge / max(coreWidth, 1e-3));

  // Wide bloom/glow (bigger like AE)
  float glowSigma = mix(18.0, 45.0, intenPow);     // px
  float glow = exp(-(distToEdge * distToEdge) / (2.0 * glowSigma * glowSigma));

  // Gate glow so it mostly appears near the edge but still spreads
  float edgeGate = smoothstep(160.0, 0.0, distToEdge); // fade far away
  glow *= edgeGate;

  // ---------------------------
  // RAYS (streaks outward)
  // ---------------------------
  // Rays in CC Light Wipe feel like they radiate from the CENTER.
  float r = length(pPx);
  float angle = atan(pPx.y, pPx.x); // -pi..pi
  float a01 = (angle + 3.14159265) / (6.2831853); // 0..1

  // Ray count & randomness
  float rayCount = 80.0;
  float id = floor(a01 * rayCount);
  float h = hash1(id * 19.73 + 3.1);
  // Create sharp spikes
  float spike = pow(h, 5.0);
  // Add a little periodic structure for “Cycore-ish” look
  float wav = 0.5 + 0.5 * sin(a01 * rayCount * 6.2831853 + h * 6.0);
  float rayMask = clamp(mix(spike, wav, 0.35), 0.0, 1.0);
  rayMask = smoothstep(0.55, 1.0, rayMask); // keep only stronger streaks

  // Ray length falloff (longer = more AE)
  float rayDecay = mix(110.0, 320.0, intenPow); // px
  float rayFall = exp(-r / rayDecay);

  // Rays should be strongest where the edge is
  float rayEdge = exp(-distToEdge / 14.0);

  float rays = rayMask * rayFall * rayEdge;

  // Combine halo components
  float haloStrength =
      (core * (1.4 + 3.2 * intenPow) +
       glow * (0.6 + 2.4 * intenPow) +
       rays * (0.8 + 3.8 * intenPow));

  // Optional: fade at very start/end (AE looks cleaner)
  float fadeIn  = smoothstep(0.00, 0.03, c);
  float fadeOut = 1.0 - smoothstep(0.97, 1.00, c);
  haloStrength *= (fadeIn * fadeOut);

  // ---------------------------
  // HALO COLOR
  // ---------------------------
  vec3 haloColor = Color;

  if (Color_From_Source >= 0.5) {
    // Sample the source color AT the boundary along normal direction
    vec2 boundaryPx = centerPx + normalUnit * boundary;
    vec2 boundaryUv = clamp(boundaryPx / resolution, vec2(0.0), vec2(1.0));
    vec4 edgeSample = texture2D(tDiffuse, boundaryUv * uvScale);

    // CC Light Wipe often “pops” brighter than source, so boost toward white a bit
    vec3 src = edgeSample.rgb;
    float lum = dot(src, vec3(0.2126, 0.7152, 0.0722));
    // If source is dark, push glow toward white so it’s still visible like AE
    vec3 boosted = mix(src, vec3(1.0), clamp(0.55 - lum, 0.0, 0.55));
    haloColor = mix(src, boosted, 0.65);
  }

  // ---------------------------
  // COMPOSITE
  // ---------------------------
  vec4 base = vec4(texel.rgb, texel.a) * opaque;

  // Make halo look “overexposed”: screen blend + add
  vec3 haloRgb = haloColor * clamp(haloStrength, 0.0, 1.0);
  vec3 outRgb = screenBlend(base.rgb, haloRgb);
  outRgb = clamp(outRgb + haloRgb * 0.55, 0.0, 1.0);

  // Alpha: ensure halo still draws even where base is transparent
  float haloA = clamp(haloStrength * 0.85, 0.0, 1.0);
  float outA = max(base.a, haloA);

  gl_FragColor = vec4(outRgb, outA);
}

text./plugins/alipfx/shaders/az-line-sweep.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// --- Custom properties ---
uniform float Completion;      // 0..100
uniform float Direction;       // degrees
uniform float Thickness;       // pixels (>=1)
uniform float Slant;           // 0..100  (we’ll remap this)
uniform float Flip_Direction;  // 0 or 1

// AE-like direction mapping (as in your code)
vec2 aeDirVec(float deg)
{
  float a = radians(deg);
  return normalize(vec2(sin(a), -cos(a)));
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // AE-like UV (Y down)
  vec2 uvAE = vec2(vUv.x, 1.0 - vUv.y);

  vec2 pix = uvAE * resolution;
  vec2 center = 0.5 * resolution;
  vec2 p = pix - center;

  float comp = clamp(Completion / 100.0, 0.0, 1.0);

  // Flip = reverse completion
  if (Flip_Direction >= 0.5) comp = 1.0 - comp;

  float thick = max(1.0, Thickness);

  // Motion & perpendicular axes
  vec2 m = aeDirVec(Direction);
  vec2 t = vec2(-m.y, m.x);

  // Corners (centered)
  vec2 c0 = vec2(-center.x, -center.y);
  vec2 c1 = vec2( center.x, -center.y);
  vec2 c2 = vec2(-center.x,  center.y);
  vec2 c3 = vec2( center.x,  center.y);

  // Spans along m and t (used to scale slant properly)
  float vm0 = dot(c0, m), vm1 = dot(c1, m), vm2 = dot(c2, m), vm3 = dot(c3, m);
  float vt0 = dot(c0, t), vt1 = dot(c1, t), vt2 = dot(c2, t), vt3 = dot(c3, t);

  float vMinBase = min(min(vm0, vm1), min(vm2, vm3));
  float vMaxBase = max(max(vm0, vm1), max(vm2, vm3));
  float uMinBase = min(min(vt0, vt1), min(vt2, vt3));
  float uMaxBase = max(max(vt0, vt1), max(vt2, vt3));

  float vSpanBase = max(1.0, (vMaxBase - vMinBase));
  float uSpanBase = max(1.0, (uMaxBase - uMinBase));

  // --- Thickness = stair/step size ---
  float stepSize = thick;
  float u = dot(p, t);
  float uQ = floor(u / stepSize + 0.5) * stepSize;

  // ✅ NEW: Slant remap so Slant=50 feels “long” like AE
  // Slant=0   -> slope = 0
  // Slant=50  -> slope = vSpan/uSpan  (strong diagonal)
  // Slant=100 -> slope = 2*(vSpan/uSpan)
  float slope = (Slant / 50.0) * (vSpanBase / uSpanBase);

  // Optional safety clamp (prevents insane values on extreme aspect ratios)
  slope = clamp(slope, 0.0, 6.0);

  // Position along sweep (slant + quantized steps)
  float proj = dot(p, m) + slope * uQ;

  // Compute min/max proj over corners for normalization (use same slope & quantization)
  float p0 = dot(c0, m) + slope * (floor(dot(c0, t)/stepSize + 0.5) * stepSize);
  float p1 = dot(c1, m) + slope * (floor(dot(c1, t)/stepSize + 0.5) * stepSize);
  float p2 = dot(c2, m) + slope * (floor(dot(c2, t)/stepSize + 0.5) * stepSize);
  float p3 = dot(c3, m) + slope * (floor(dot(c3, t)/stepSize + 0.5) * stepSize);

  float minP = min(min(p0, p1), min(p2, p3));
  float maxP = max(max(p0, p1), max(p2, p3));

  float normPos = (proj - minP) / max(1.0, (maxP - minP));

  // HARD EDGE (no blur)
  float alpha = step(comp, normPos);

  texel.rgb *= alpha;
  texel.a   *= alpha;

  gl_FragColor = texel;
}

text./plugins/alipfx/shaders/az-plastic.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform sampler2D envMap;
uniform vec2 resolution;
varying vec2 vUvScaled;

uniform float Property;
uniform float Softness;   // Controls Expansion/Contraction
uniform float Height;     // Positive = Outward, Negative = Inward
uniform float Cut_Min;
uniform float Cut_Max;

float getProperty(vec4 texel) {
    float val;
    if (Property < 1.5) val = texel.r;
    else if (Property < 2.5) val = texel.g;
    else if (Property < 3.5) val = texel.b;
    else if (Property < 4.5) val = texel.a;
    else if (Property < 5.5) val = dot(texel.rgb, vec3(0.2126, 0.7152, 0.0722));
    else val = 0.5 * (max(max(texel.r, texel.g), texel.b) + min(min(texel.r, texel.g), texel.b));

    // Mirrored logic for full-logo coverage
    return abs(val - 0.5) * 2.0; 
}

float normalizeSlider(float v) {
    return v / 100.0;
}

void main() {
    // Edge Fade to prevent cropping artifacts
    vec2 uv = vUvScaled;
    float edgeFade = smoothstep(0.0, 0.01, uv.x) * smoothstep(1.0, 0.99, uv.x) *
                     smoothstep(0.0, 0.01, uv.y) * smoothstep(1.0, 0.99, uv.y);

    vec4 texel = texture2D(tDiffuse, uv);
    float rawProp = getProperty(texel);

    // ---------------------------------------------------------
    // 1. SOFTNESS = EXPANSION/CONTRACTION
    // We use Softness to shift the threshold of the matte.
    // ---------------------------------------------------------
    float expansion = normalizeSlider(Softness) * 0.5;
    float cutMinNorm = clamp(normalizeSlider(Cut_Min) - expansion, 0.0, 1.0);
    float cutMaxNorm = clamp(normalizeSlider(Cut_Max) - expansion, 0.0, 1.0);

    float matte = smoothstep(cutMinNorm, cutMaxNorm, rawProp) * edgeFade;

    if (matte <= 0.0) {
        gl_FragColor = texel;
        return;
    }

    // 2. SURFACE SAMPLING
    vec2 texelSize = 1.0 / resolution;
    // We use a small fixed blur for the internal surface smoothness
    float h = rawProp;
    float h_r = getProperty(texture2D(tDiffuse, uv + vec2(texelSize.x, 0.0)));
    float h_u = getProperty(texture2D(tDiffuse, uv + vec2(0.0, texelSize.y)));

    // ---------------------------------------------------------
    // 3. HEIGHT = INWARD/OUTWARD
    // Multiplying the XY of the normal by the height value 
    // flips the lighting direction when negative.
    // ---------------------------------------------------------
    float hNorm = normalizeSlider(Height);
    // 0.1 is the 'flatness' constant. Smaller = steeper plastic.
    vec3 N = normalize(vec3((h - h_r) * hNorm, (h - h_u) * hNorm, 0.1));

    // 4. LIGHTING
    vec3 L = normalize(vec3(-0.5, -0.7, 1.0));
    vec3 V = vec3(0.0, 0.0, 1.0);
    vec3 H = normalize(L + V);

    float diff = max(dot(N, L), 0.0);
    float spec = pow(max(dot(N, H), 0.0), 64.0);

    // Distorted reflection for the liquid look
    vec2 reflectUV = uv + N.xy * 0.05;
    vec3 reflection = texture2D(envMap, vec2(reflectUV.x, 1.0 - reflectUV.y)).rgb;

    vec3 plasticColor = (texel.rgb * (0.3 + 0.7 * diff)) + (reflection * 0.5) + vec3(spec * 0.8);

    gl_FragColor = vec4(mix(texel.rgb, plasticColor, matte), texel.a);
}

text./plugins/alipfx/shaders/az-radial-blur.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

// ---- Custom properties ----
uniform float Type;     // 0..5
uniform float Amount;   // -100..100 (AE default)
uniform float Quality;  // 0..100
uniform vec2 Center;    // pixels, AE-style: (x from left, y from top)

// ---------- Helpers ----------
vec2 clamp01(vec2 uv) { return clamp(uv, vec2(0.0), vec2(1.0)); }

// Convert unscaled UV -> correctly scaled buffer UV (Panzoid mapping)
vec4 sampleTex(vec2 uvUnscaled) {
  vec2 uvScaled = clamp01(uvUnscaled) * uvScale;
  return texture2D(tDiffuse, uvScaled);
}

vec2 rot(vec2 v, float a) {
  float s = sin(a), c = cos(a);
  return vec2(c * v.x - s * v.y, s * v.x + c * v.y);
}

// Tiny deterministic jitter to reduce banding at low Quality
float hash12(vec2 p) {
  // p in pixels for stability
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453123);
}

void main() {
  // Recover unscaled UV (0..1) from Panzoid's scaled varying. [2](https://panzoid.com/community/official/37192?c=3)
  vec2 uv = vUvScaled / uvScale;

  vec4 base = sampleTex(uv);

  // If no blur
  if (abs(Amount) <= 0.00001 || Quality <= 0.0) {
    gl_FragColor = base;
    return;
  }

  // AE-style center: pixels with origin at top-left.
  // Convert to bottom-left origin used by UV math.
  vec2 cPx = vec2(Center.x, resolution.y - Center.y);

  // Current pixel position
  vec2 pPx = uv * resolution;

  vec2 d = pPx - cPx;
  float r = length(d);
  vec2 dir = (r > 1e-6) ? (d / r) : vec2(0.0);

  // Normalized radius for fade styles
  float maxR = length(resolution); // diagonal
  float rNorm = clamp(r / maxR, 0.0, 1.0);

  // Quality -> sample count:
  // Cycore describes Quality as smoothness/steps (higher = fewer visible steps). [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)
  // Map 0..100 => 1..64 samples (practical + close to AE feel).
  int q = int(clamp(1.0 + Quality * 0.63, 1.0, 64.0));

  // Interpreting Amount:
  // Zoom strength in [-1..1]
  float zoomK = clamp(Amount / 100.0, -1.0, 1.0);

  // Rotate amount treated as degrees (Cycore: Amount controls degree & direction). [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)
  float angMax = radians(Amount);

  int t = int(floor(Type + 0.5));

  vec4 acc = vec4(0.0);
  float wSum = 0.0;

  float j = hash12(pPx); // stable per-pixel jitter

  // Fixed loop bound for WebGL shader compilers
  const int MAX_SAMPLES = 64;
  for (int i = 0; i < MAX_SAMPLES; i++) {
    if (i >= q) break;

    // stratified sample in (0..1), jittered to reduce banding
    float ft = (float(i) + 0.5 + (j - 0.5)) / float(q); // ~0..1

    // Default weight
    float w = 1.0;

    // ---------------- ZOOM TYPES ----------------
    if (t == 0) {
      // 0 Straight Zoom:
      // "Radiates out from the center point with constant length." [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)[4](https://www.163.com/dy/article/JPIDOT1V0536FE6V.html)
      // Sample along the line from the pixel toward/away from center.
      // At Amount=+100, ft=1 -> sample reaches center (strong AE-like max).
      vec2 srcPx = pPx - d * (zoomK * ft);
      acc += sampleTex(srcPx / resolution);
      wSum += 1.0;
    }
    else if (t == 1) {
      // 1 Fading Zoom:
      // Like Straight Zoom, but fades out toward the edges. [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)[4](https://www.163.com/dy/article/JPIDOT1V0536FE6V.html)
      float edgeFade = 1.0 - rNorm;        // strongest near center
      w = edgeFade;
      vec2 srcPx = pPx - d * (zoomK * ft);
      acc += sampleTex(srcPx / resolution) * w;
      wSum += w;
    }
    else if (t == 2) {
      // 2 Centered Zoom:
      // "Radiates in and out equally" and feels like zooming without moving the layer. [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)[4](https://www.163.com/dy/article/JPIDOT1V0536FE6V.html)
      // Symmetric samples around the current pixel along radial direction.
      vec2 off = d * (zoomK * ft);
      vec2 srcA = (pPx - off) / resolution;
      vec2 srcB = (pPx + off) / resolution;

      acc += sampleTex(srcA) * 0.5;
      acc += sampleTex(srcB) * 0.5;
      wSum += 1.0;
    }

    // ---------------- ROTATION TYPES ----------------
    else if (t == 3) {
      // 3 Rotate:
      // Positive = clockwise in AE per Cycore docs; math positive is CCW, so invert. [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)[4](https://www.163.com/dy/article/JPIDOT1V0536FE6V.html)
      float a = -angMax * ft;
      vec2 srcPx = cPx + rot(d, a);
      acc += sampleTex(srcPx / resolution);
      wSum += 1.0;
    }
    else if (t == 4) {
      // 4 Scratch:
      // "Back and forth evenly in both directions." [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)[4](https://www.163.com/dy/article/JPIDOT1V0536FE6V.html)
      float a = abs(angMax) * ft;

      vec2 src1 = (cPx + rot(d,  a)) / resolution;
      vec2 src2 = (cPx + rot(d, -a)) / resolution;

      acc += sampleTex(src1) * 0.5;
      acc += sampleTex(src2) * 0.5;
      wSum += 1.0;
    }
    else if (t == 5) {
      // 5 Rotate Fading:
      // Rotate, but "fading circles" (fades toward edges / along trail). [1](http://www.cycorefx.com/downloads/cfx_hd_std/CycoreFX%20HD%201.7.1%20Manual.pdf)[4](https://www.163.com/dy/article/JPIDOT1V0536FE6V.html)
      float edgeFade = 1.0 - rNorm;
      float trailFade = 1.0 - ft;
      w = edgeFade * trailFade;

      float a = -angMax * ft;
      vec2 srcPx = cPx + rot(d, a);

      acc += sampleTex(srcPx / resolution) * w;
      wSum += w;
    }
    else {
      // Unknown type -> just output base
      acc += base;
      wSum += 1.0;
    }
  }

  vec4 outCol = acc / max(wSum, 1e-6);
  gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/az-radial-fast-b:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform vec2 resolution;
uniform vec2 uvScale;

uniform vec2 Center;    // AE PIXELS center (e.g. 960,540 on 1920x1080)
uniform float Amount;   // blur strength
uniform float Zoom;     // 0=Standard, 1=Brightest, 2=Darkest (use float for Panzoid compatibility)

void main() {
    vec2 uv = vUvScaled;

    // Optimization: Skip calculation if Amount is effectively zero
    if (Amount <= 0.0) {
        gl_FragColor = texture2D(tDiffuse, uv);
        return;
    }

    // Convert AE pixel center -> normalized UV -> scaled UV (same space as vUvScaled)
    vec2 centerScaled = (Center / resolution) * uvScale;

    vec2 dir = uv - centerScaled;

    // Safety: clamp sample count; loop hard-limited to 100
    int samples = int(clamp(ceil(Amount * 20.0), 1.0, 100.0));

    vec4 color = vec4(0.0);
    float weightSum = 0.0;

    for (int i = 0; i < 100; i++) {
        if (i >= samples) break;

        float t = float(i) / max(float(samples - 1), 1.0); // avoid division by zero

        // Samples pixels closer to the center, creating an outward "Forward Zoom" trail
        vec2 sampleUV = uv - dir * t * Amount * 0.02;

        vec4 texel = texture2D(tDiffuse, sampleUV);

        // Linear fade for smoother trails
        float weight = 1.0 - t;

        color += texel * weight;
        weightSum += weight;
    }

    color /= max(weightSum, 1e-6);

    // Apply Blend Modes (Standard / Brightest / Darkest)
    int mode = int(floor(Zoom + 0.5));
    vec3 original = texture2D(tDiffuse, uv).rgb;

    if (mode == 1) {
        color.rgb = max(color.rgb, original);
    } else if (mode == 2) {
        color.rgb = min(color.rgb, original);
    }

    gl_FragColor = color;
}

text./plugins/alipfx/shaders/az-radial-scalew:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

// Panzoid shader properties
uniform float Completion;         // 0..100
uniform vec2  Center;             // normalized (0..1) OR pixels (auto-detect)
uniform float Reverse_Transition; // 0 or 1

// Clamp sampling to edge pixels (prevents black wedges)
vec4 sampleClamp(vec2 uv01)
{
    vec2 u = clamp(uv01, vec2(0.0), vec2(1.0));
    return texture2D(tDiffuse, u * uvScale);
}

void main()
{
    // Convert Panzoid scaled UV -> normal UV (0..1)
    vec2 uv = vUvScaled / uvScale;

    // Completion normalized
    float p = clamp(Completion / 100.0, 0.0, 1.0);

    // ✅ 0% => absolutely no effect (no wipe, no distortion)
    if (p <= 1e-6)
    {
        gl_FragColor = sampleClamp(uv);
        return;
    }

    float rev = step(0.5, Reverse_Transition);

    // Center: normalized (0..1) OR pixels
    vec2 cPix = (max(Center.x, Center.y) > 2.0) ? Center : (Center * resolution);

    // Pixel space
    vec2 pPix = uv * resolution;

    // Aspect-correct radial space (so circles stay circles)
    vec2 dNorm = (pPix - cPix) / resolution.y;
    float r = length(dNorm);

    // Max radius to farthest corner (same normalized-by-height units)
    vec2 c0 = (vec2(0.0, 0.0) - cPix) / resolution.y;
    vec2 c1 = (vec2(resolution.x, 0.0) - cPix) / resolution.y;
    vec2 c2 = (vec2(0.0, resolution.y) - cPix) / resolution.y;
    vec2 c3 = (vec2(resolution.x, resolution.y) - cPix) / resolution.y;

    float maxR = max(max(length(c0), length(c1)), max(length(c2), length(c3)));
    maxR = max(maxR, 1e-6);

    // Boundary radius:
    // rev=0: hole grows outward from center (default)
    // rev=1: hole collapses inward from edges (reverse)
    float b = mix(p * maxR, (1.0 - p) * maxR, rev);

    // ✅ 100% => fully transparent (end of transition)
    if (p >= 0.999)
    {
        vec4 base = sampleClamp(uv);
        gl_FragColor = vec4(base.rgb, 0.0);
        return;
    }

    // Unit direction (avoid NaN at center)
    vec2 udir = (r > 1e-8) ? (dNorm / r) : vec2(1.0, 0.0);

    // ------------------------------------------------------------
    // 1) HARD WIPE (no dissolve)
    // ------------------------------------------------------------
    float aa = 1.0 / resolution.y;

    // rev=0 visible outside (r >= b)
    // rev=1 visible inside  (r <= b)
    float alphaVis = mix(
        smoothstep(b - aa, b + aa, r),
        1.0 - smoothstep(b - aa, b + aa, r),
        rev
    );

    // ------------------------------------------------------------
    // 2) BULGE RING around the boundary (reverse fixed)
    // ------------------------------------------------------------
    float ring  = 0.250;   // ring thickness
    float bulge = 2.60;    // bulge strength

    // Bulge = 0 at p=0, quickly ramps on after 0
    float bulgeOn = smoothstep(0.0, 0.02, p);

    // Distance from boundary on the VISIBLE side only
    // rev=0: visible outside => dist = max(r - b, 0)
    // rev=1: visible inside  => dist = max(b - r, 0)
    float dist = mix(max(r - b, 0.0), max(b - r, 0.0), rev);

    // Ring falloff: 1 at boundary, 0 after ring distance
    float w = 1.0 - smoothstep(0.0, ring, dist);

    // Apply bulge only near boundary
    float rSrc = r;
    if (w > 0.0)
    {
        float pull = bulge * ring * w * bulgeOn;

        // ✅ IMPORTANT FIX:
        // rev=0: pull samples inward (toward boundary) from outside
        // rev=1: pull samples outward (toward boundary) from inside
        // BUT we LIMIT how far past the boundary we sample in reverse mode,
        // to avoid the "flat band" clamp artifacts you got in Panzoid.
if (rev < 0.5) {
    // Normal: outside region gets pulled inward (good)
    rSrc = r - pull;
} else {
    // Reverse: DO NOT pull outward (causes outer-edge bulge / edge sampling)
    // Pull inward instead so bulge hugs the boundary from the inside.
    // Also limit how far inward we pull so the distortion stays as a ring near the boundary.
    rSrc = max(r - pull, b - ring * 0.95);
}

    }

    // Keep sampling radius sane
    rSrc = clamp(rSrc, 0.0, maxR);

    // Sample warped UV
    vec2 dSrcNorm = udir * rSrc;
    vec2 pSrcPix  = cPix + dSrcNorm * resolution.y;
    vec2 uv2      = pSrcPix / resolution;

    vec4 col = sampleClamp(uv2);

    // Keep RGB straight so ring stays visible; alpha controls wipe
    gl_FragColor = vec4(col.rgb, col.a * alphaVis);
}

text./plugins/alipfx/shaders/az-rainfall.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Built-in Panzoid uniforms
uniform vec2 resolution;

// Custom properties (dynamic)
uniform float Drops;          // Number of raindrops
uniform float Size;           // Raindrop size
uniform float Scene_Depth;    // Z-axis spread
uniform float Speed;          // Fall speed
uniform float Wind;           // Wind angle in degrees
uniform float Wind_Variation; // Wind variation %
uniform float Spread;         // Global chaos
uniform vec3 Color;           // Rain color
uniform float Opacity;        // Rain opacity
uniform float Time;           // Animation time

// Random generator
float rand(float n) {
    return fract(sin(n) * 43758.5453123);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    vec2 uv = vUvScaled; // normalized UV (0.0 to 1.0)
    float rainAlpha = 0.0;

    // Loop through raindrops (limited for performance)
    for (int i = 0; i < 200; i++) {
        if (float(i) >= Drops) break;

        float seed = float(i);
        float x = rand(seed * 12.9898);
        float y = rand(seed * 78.233);
        float z = rand(seed * 45.164) * Scene_Depth;

        // Depth factor for perspective scaling
        float depthFactor = 1.0 / (1.0 + z * 0.01);
        float dropSize = (Size / resolution.x) * depthFactor;
        float dropLength = (Size * 0.02) * depthFactor;
        float dropSpeed = Speed * depthFactor;

        // Depth-based opacity: farther drops fade out
        float depthOpacity = mix(1.0, 0.2, z / Scene_Depth);

        // Compute wind angle with variation
        float baseAngle = radians(Wind);
        float angleOffset = radians((rand(seed * 99.9) - 0.5) * 2.0 * Wind_Variation);
        float finalAngle = baseAngle + angleOffset;

        // Fall direction based on varied angle
        vec2 fallDir = vec2(sin(finalAngle), -cos(finalAngle));

        // Apply motion along varied direction
        x += fallDir.x * dropSpeed * Time / resolution.x;
        y += fallDir.y * dropSpeed * Time / resolution.y;

        // Apply global chaos (Spread) independent of wind
        float spreadAngle = radians((rand(seed * 77.7) - 0.5) * 360.0);
        vec2 spreadDir = vec2(cos(spreadAngle), sin(spreadAngle));
        x += spreadDir.x * Spread * Time / resolution.x;
        y += spreadDir.y * Spread * Time / resolution.y;

        // Wrap around
        x = mod(x, 1.0);
        y = mod(y, 1.0);

        // Rotate streak based on varied angle
        mat2 rotation = mat2(cos(finalAngle), -sin(finalAngle),
                              sin(finalAngle),  cos(finalAngle));
        vec2 diff = rotation * (uv - vec2(x, y));

        // Compute streak intensity with depth-based blur
        float blurFactor = mix(0.0, 0.003, z / Scene_Depth); // farther = blurrier
        float streak = smoothstep(dropSize + blurFactor, 0.0, abs(diff.x)) *
                       smoothstep(dropLength + blurFactor, 0.0, abs(diff.y));

        // Apply depth opacity
        rainAlpha += streak * depthOpacity;
    }

    // Clamp and apply Opacity as intensity multiplier
    rainAlpha = clamp(rainAlpha * Opacity, 0.0, 1.0);

    vec4 rainColor = vec4(Color, rainAlpha);
    gl_FragColor = mix(texel, rainColor, rainAlpha);
}

text./plugins/alipfx/shaders/az-scale-wipe.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

// Panzoid shader properties
uniform float Stretch;    // AE-like units (0..100+)
uniform vec2  Center;     // normalized (0..1) OR pixels (auto-detect)
uniform float Direction;  // degrees, AE mapping: 0=up, 90=right

// Clamp sampling to edge pixels (prevents black wedges)
vec4 sampleClamp(vec2 uv01)
{
    vec2 u = clamp(uv01, vec2(0.0), vec2(1.0));
    return texture2D(tDiffuse, u * uvScale);
}

void main()
{
    // Convert Panzoid scaled UV -> normal UV (0..1)
    vec2 uv = vUvScaled / uvScale;

    // Center: allow BOTH normalized and pixel input
    vec2 cPix = (max(Center.x, Center.y) > 2.0) ? Center : (Center * resolution);

    // Work in pixel space
    vec2 pPix = uv * resolution;
    vec2 r = pPix - cPix;

    // AE direction mapping: 0°=up, 90°=right
    float a = radians(Direction);
    vec2 dir  = normalize(vec2(sin(a), cos(a)));
    vec2 perp = vec2(-dir.y, dir.x);

    float s = dot(r, dir);
    float t = dot(r, perp);

    // -------------------------------
    // ✅ Progressive + smear stretch
    // -------------------------------

    // Find the maximum extent along 'dir' from the center to the comp corners
    float s0 = dot((vec2(0.0,          0.0)          - cPix), dir);
    float s1 = dot((vec2(resolution.x, 0.0)          - cPix), dir);
    float s2 = dot((vec2(0.0,          resolution.y) - cPix), dir);
    float s3 = dot((vec2(resolution.x, resolution.y) - cPix), dir);

    float sMax = max(max(s0, s1), max(s2, s3)); // furthest in + direction
    float sMin = min(min(s0, s1), min(s2, s3)); // furthest in - direction

    float posExtent = max(sMax, 1e-5);
    float negExtent = max(-sMin, 1e-5);

    // Which side to affect (AE: Stretch sign flips direction)
    float side = (Stretch >= 0.0) ? 1.0 : -1.0;

    // Normalize distance on the affected side to 0..1
    // u = 0 at center line, u = 1 near the far edge (in that direction)
    float u;
    if (side > 0.0) u = clamp(s / posExtent, 0.0, 1.0);
    else            u = clamp((-s) / negExtent, 0.0, 1.0);

    // Curve controls how "progressive" it is:
    // - lower = more linear
    // - higher = keeps near-center cleaner and smears far-out more (AE-ish)
    float curve = 1.6;
    float uCurve = pow(u, curve);

    // AE-like strength: Stretch=100 should be very strong
    // This creates the "smear band" by collapsing far distances toward the center line.
    float amt = abs(Stretch);
    float factor = 1.0 + amt * uCurve;

    float sWarp = s;

    // Apply on only one side (like AE)
    if (Stretch > 0.0) {
        if (s > 0.0) sWarp = s / factor;
    } else if (Stretch < 0.0) {
        if (s < 0.0) sWarp = s / factor;
    }

    // ✅ Fix the "X seam": blend original→warped within a tiny band around the center line
    // This adds interpolation so crossing shapes don’t look chopped.
    float softPx = 1.5; // 1–2 pixels is usually enough
    float blend = smoothstep(0.0, softPx, s * side); // ramps only on affected side

    float sFinal = mix(s, sWarp, blend);

    // Back to pixel position -> UV
    vec2 p2Pix = cPix + dir * sFinal + perp * t;
    vec2 uv2   = p2Pix / resolution;

    gl_FragColor = sampleClamp(uv2);
}

text./plugins/alipfx/shaders/az-scatterize.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale; // Required by Panzoid for correct UV mapping

uniform float Scatter;        // -10000 to 10000
uniform float Right_Twist;    // degrees
uniform float Left_Twist;     // degrees
uniform float Transfer_Mode;  // 0..3

varying vec2 vUv; // Base UV coordinates (0.0 to 1.0)
varying vec2 vUvScaled; 

/* ===== Hash for Scatter ===== */
float hash(vec2 p) {
    p = fract(p * vec2(127.1, 311.7));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

void main() {
    // ALWAYS use vUv for math involving the center
    vec2 uv = vUv;
    vec2 pos = uv - 0.5; // Center coordinates around (0,0)

    /* ---------- 1. Calculate Continuous 3D Helix Twist ---------- */
    float twistDeg = 0.0;
    if (pos.x >= 0.0) {
        twistDeg = Right_Twist * (pos.x * 2.0);
    } else {
        // Natural negative angle for the left side to create a continuous helix
        twistDeg = Left_Twist * (pos.x * 2.0); 
    }

    float angle = radians(twistDeg);
    float s = sin(angle);
    float c = cos(angle);

    /* ---------- 2. Inverse 3D Perspective Mapping ---------- */
    float D = 1.5; // Camera depth (Controls the perspective distortion)
    float denom = D * c - pos.y * s;

    vec2 originalUV = uv;
    float outOfBounds = 0.0;

    // Prevent division by zero (horizon line artifacts)
    if (abs(denom) > 0.0001) {

        // Find the original Y coordinate before 3D projection
        float v = (pos.y * D) / denom;

        // Reconstruct Z depth to find the perspective projection factor (P)
        float z = v * s;

        // Hide pixels that rotate behind the camera lens
        if (D + z <= 0.0) {
            outOfBounds = 1.0;
        } else {
            float P = D / (D + z);

            // Find the original X coordinate before projection
            float u = pos.x / P;

            originalUV = vec2(u, v) + 0.5;

            // Discard pixels that are pulled in from outside the texture's original boundaries
            if (originalUV.x < 0.0 || originalUV.x > 1.0 || originalUV.y < 0.0 || originalUV.y > 1.0) {
                outOfBounds = 1.0;
            }
        }
    } else {
        outOfBounds = 1.0; 
    }

    /* ---------- 3. Infinite Scatter ---------- */
    // Apply noise in the original UV space so the scatter correctly follows the 3D twist
    vec2 seed = originalUV * resolution;
    vec2 noise = vec2(hash(seed), hash(seed + 41.0)) - 0.5;

    // Scale down the massive -10000 to 10000 range so it maps cleanly to UV space.
    // 10000 * 0.0001 = 1.0 (Full screen maximum offset)
    vec2 scatterOffset = noise * (Scatter * 0.0001); 

    vec2 finalUV = originalUV + scatterOffset;

    /* ---------- 4. Output Mapping ---------- */
    // Apply uvScale exactly when sampling to satisfy Panzoid layer rules
    vec4 col = texture2D(tDiffuse, finalUV * uvScale);

    // Mask out pixels beyond the 3D rotation edges
    if (outOfBounds > 0.5) {
        col = vec4(0.0); 
    }

    /* ---------- 5. Transfer Modes ---------- */
    vec4 outCol;
    int mode = int(Transfer_Mode + 0.5);

    // Fetch the original un-scattered/un-twisted pixel to blend against
    vec4 baseCol = texture2D(tDiffuse, uv * uvScale);

    if (mode == 1) { // 1 = Screen
        outCol.rgb = 1.0 - (1.0 - baseCol.rgb) * (1.0 - col.rgb);
        outCol.a = max(baseCol.a, col.a);
    } else if (mode == 2) { // 2 = Add
        outCol.rgb = baseCol.rgb + col.rgb;
        outCol.a = max(baseCol.a, col.a);
    } else if (mode == 3) { // 3 = Alpha Add
        outCol.rgb = baseCol.rgb + col.rgb;
        outCol.a = clamp(baseCol.a + col.a, 0.0, 1.0); // Adds the alphas together
    } else { // 0 = Composite (Normal replacement)
        outCol = col;
    }

    gl_FragColor = clamp(outCol, 0.0, 1.0);
}

text./plugins/alipfx/shaders/az-slant.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// ===== Custom properties =====
uniform float Slant;       // degrees, +right / -left
uniform float Stretching;  // 0 = off, 1 = on
uniform float Height;      // percent, 100 = normal, 0 = flat, negative = flip
uniform vec2 Floor;        // pixel position, AE-style: x from left, y from top
uniform float Set_Color;   // 0 = off, 1 = on
uniform vec3 Color;        // solid color fill when Set Color = 1

float safeSign(float v) {
  return (v < 0.0) ? -1.0 : 1.0;
}

bool inside01(vec2 uv) {
  return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0;
}

void main() {
  // Current output UV in normal layer space (0..1, bottom-left origin)
  vec2 uv = vUv;

  // Convert AE-style Floor pixels (top-left origin) to GLSL UV (bottom-left origin)
  vec2 floorUv = vec2(
    Floor.x / resolution.x,
    1.0 - (Floor.y / resolution.y)
  );

  // Parameters
  float angle = radians(Slant);
  float s = sin(angle);
  float c = cos(angle);

  // Height is percent
  float h = Height / 100.0;

  // Numerical protection
  float eps = 0.0001;
  float safeC = (abs(c) < eps) ? (eps * safeSign(c)) : c;
  float safeH = (abs(h) < eps) ? (eps * safeSign(h)) : h;
  float safeTan = s / safeC;

  // Destination point relative to Floor
  vec2 d = uv - floorUv;

  // Inverse-map destination -> source
  vec2 srcRel;

  if (Stretching >= 0.5) {
    // STRETCHING ON:
    // Keeps the top edge on a fixed horizontal line -> shear-like
    //
    // Forward model:
    //   x' = x + y * h * tan(angle)
    //   y' = y * h
    //
    // Inverse:
    //   y  = y' / h
    //   x  = x' - y' * tan(angle)
    srcRel = vec2(
      d.x - d.y * safeTan,
      d.y / safeH
    );
  } else {
    // STRETCHING OFF:
    // "Falls backward/forward" -> tilt/projection-like
    //
    // Forward model:
    //   x' = x + y * h * sin(angle)
    //   y' = y * h * cos(angle)
    //
    // Inverse:
    //   y  = y' / (h * cos(angle))
    //   x  = x' - y' * tan(angle)
    srcRel = vec2(
      d.x - d.y * safeTan,
      d.y / (safeH * safeC)
    );
  }

  vec2 srcUv = floorUv + srcRel;

  vec4 outColor = vec4(0.0);

  // Transparent outside source bounds (like a normal effect buffer crop)
  if (inside01(srcUv)) {
    vec4 texel = texture2D(tDiffuse, srcUv * uvScale);

    if (Set_Color >= 0.5) {
      outColor = vec4(Color, texel.a);
    } else {
      outColor = texel;
    }
  }

  gl_FragColor = outColor;
}

text./plugins/alipfx/shaders/az-snowfall.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Built-in Panzoid uniforms
uniform vec2 resolution;

// Custom properties (dynamic)
uniform float Flakes;            // Number of snowflakes
uniform float Size;              // Base size
uniform float Size_Variation;    // Variation % (Size)
uniform float Scene_Depth;       // Z-axis spread
uniform float Speed;             // Fall speed
uniform float Speed_Variation;   // Variation % (Speed)
uniform float Wind;              // Wind angle in degrees
uniform float Wind_Variation;    // Variation % (Wind)
uniform float Spread;            // Global chaos
uniform float Wiggle_Amount;     // Wiggle amplitude
uniform float Wiggle_Variation;  // Variation % (Amount)
uniform float Wiggle_Frequency;  // Base wiggle frequency
uniform float Frequency_Variation; // Variation % (Frequency)
uniform float Stochastic_Wiggle; // 0 = off, 1 = on
uniform float Flake_Flatness;    // Flatness %
uniform vec3 Color;              // Snow color
uniform float Opacity;           // Snow opacity
uniform float Time;              // Animation time

// Random generator
float rand(float n) {
    return fract(sin(n) * 43758.5453123);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec2 uv = vUvScaled;
    float snowAlpha = 0.0;

    for (int i = 0; i < 300; i++) {
        if (float(i) >= Flakes) break;

        float seed = float(i);
        float x = rand(seed * 12.9898);
        float y = rand(seed * 78.233);
        float z = rand(seed * 45.164) * Scene_Depth;

        // Depth factor
        float depthFactor = 1.0 / (1.0 + z * 0.01);
        float sizeVariation = 1.0 + (rand(seed * 55.5) - 0.5) * (Size_Variation / 100.0);
        float flakeSize = (Size / resolution.x) * depthFactor * sizeVariation;
        float flakeLength = flakeSize * (Flake_Flatness / 100.0);
        float speedVariation = 1.0 + (rand(seed * 66.6) - 0.5) * (Speed_Variation / 100.0);
        float flakeSpeed = Speed * depthFactor * speedVariation;

        // Depth-based opacity
        float depthOpacity = mix(1.0, 0.3, z / Scene_Depth);

        // ✅ Wind fix: full directional control + chaotic variation
        float baseAngle = radians(Wind);
        float angleOffset = radians((rand(seed * 99.9) - 0.5) * 2.0 * Wind_Variation);
        float finalAngle = baseAngle + angleOffset;
        vec2 fallDir = vec2(sin(finalAngle), -cos(finalAngle));

        // Apply motion along wind direction
        x += fallDir.x * flakeSpeed * Time / resolution.x;
        y += fallDir.y * flakeSpeed * Time / resolution.y;

        // Spread chaos (independent of wind)
        float spreadAngle = radians((rand(seed * 77.7) - 0.5) * 360.0);
        vec2 spreadDir = vec2(cos(spreadAngle), sin(spreadAngle));
        x += spreadDir.x * Spread * Time / resolution.x;
        y += spreadDir.y * Spread * Time / resolution.y;

        // Realistic wiggle drift (horizontal sway + slight vertical jitter)
        float wiggleAmp = Wiggle_Amount * (1.0 + (rand(seed * 88.8) - 0.5) * (Wiggle_Variation / 100.0));
        float freqVariation = 1.0 + (rand(seed * 101.1) - 0.5) * (Frequency_Variation / 100.0);
        float wigglePhase = Time * Wiggle_Frequency * freqVariation + seed;

        // Horizontal sway
        x += sin(wigglePhase) * wiggleAmp / resolution.x;

        // Slight vertical jitter for realism
        if (Stochastic_Wiggle > 0.5) {
            y += (rand(seed * 222.2) - 0.5) * wiggleAmp * 0.2 / resolution.y;
        }

        // Wrap around
        x = mod(x, 1.0);
        y = mod(y, 1.0);

        // Rotate flake based on wind angle
        mat2 rotation = mat2(cos(finalAngle), -sin(finalAngle),
                              sin(finalAngle),  cos(finalAngle));
        vec2 diff = rotation * (uv - vec2(x, y));

        // ✅ Depth-based blur: farther flakes appear softer
        float blurFactor = mix(0.0, 0.004, z / Scene_Depth);

        // Compute flake intensity with blur
        float flake = smoothstep(flakeSize + blurFactor, 0.0, abs(diff.x)) *
                      smoothstep(flakeLength + blurFactor, 0.0, abs(diff.y));

        snowAlpha += flake * depthOpacity;
    }

    snowAlpha = clamp(snowAlpha * Opacity, 0.0, 1.0);
    vec4 snowColor = vec4(Color, snowAlpha);
    gl_FragColor = mix(texel, snowColor, snowAlpha);
}

text./plugins/alipfx/shaders/az-sphere.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

uniform float RotX;
uniform float RotY;
uniform float RotZ;
uniform float RotOrder;   // use float in Panzoid
uniform float Radius;
uniform vec2 Offset;
uniform float RenderMode; // 0 Both, 1 Outside, 2 Inside

#define PI 3.141592653589793

mat3 rotationMatrix(float x, float y, float z, int order) {
    float cx = cos(radians(x)), sx = sin(radians(x));
    float cy = cos(radians(y)), sy = sin(radians(y));
    float cz = cos(radians(z)), sz = sin(radians(z));

    mat3 Rx = mat3(
        1.0, 0.0, 0.0,
        0.0,  cx, -sx,
        0.0,  sx,  cx
    );

    mat3 Ry = mat3(
         cy, 0.0,  sy,
        0.0, 1.0, 0.0,
        -sy, 0.0,  cy
    );

    mat3 Rz = mat3(
         cz, -sz, 0.0,
         sz,  cz, 0.0,
        0.0, 0.0, 1.0
    );

    if(order==0) return Rz * Ry * Rx; // XYZ
    if(order==1) return Ry * Rz * Rx; // XZY
    if(order==2) return Rz * Rx * Ry; // YXZ
    if(order==3) return Rx * Rz * Ry; // YZX
    if(order==4) return Ry * Rx * Rz; // ZXY
    return Rx * Ry * Rz;              // ZYX
}

vec2 sphereToUV(vec3 p) {
    float theta = atan(p.x, p.z);                 // [-pi..pi]
    float phi   = acos(clamp(p.y, -1.0, 1.0));    // [0..pi]
    return vec2(theta / (2.0 * PI) + 0.5, phi / PI);
}

void main() {
    // Convert fragment position into sphere-plane coords
    vec2 uv = (vUvScaled * resolution - Offset) / max(Radius, 1e-6);

    float r2 = dot(uv, uv);
    if (r2 > 1.0) {
        gl_FragColor = vec4(0.0);
        return;
    }

    float z = sqrt(max(1.0 - r2, 0.0));

    // Front and back intersections on unit sphere
    vec3 pFront = vec3(uv.x, uv.y,  z);
    vec3 pBack  = vec3(uv.x, uv.y, -z);

    int order = int(floor(RotOrder + 0.5));
    mat3 rot = rotationMatrix(RotX, RotY, RotZ, order);

    pFront = rot * pFront;
    pBack  = rot * pBack;

    int mode = int(floor(RenderMode + 0.5)); // 0,1,2

    // UVs
    vec2 uvFront = sphereToUV(pFront);
    vec2 uvBack  = sphereToUV(pBack);

    // ✅ KEY FIX: prevent mirrored text on the back/inside surface
    // Flip U for the back face so it reads the same direction
    uvBack.x = fract(1.0 - uvBack.x);

    vec4 colFront = texture2D(tDiffuse, uvFront);
    vec4 colBack  = texture2D(tDiffuse, uvBack);

    // Outside only
    if (mode == 1) {
        gl_FragColor = colFront;
        return;
    }

    // Inside only
    if (mode == 2) {
        gl_FragColor = colBack;
        return;
    }

    // Both (front over back)
    gl_FragColor = colFront + (1.0 - colFront.a) * colBack;
}

text./plugins/alipfx/shaders/az-split-2.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// Panzoid properties (spaces -> underscores)
uniform vec2 Point_A;     // pixels
uniform vec2 Point_B;     // pixels
uniform float Split_1;    // pixels
uniform float Split_2;    // pixels
uniform float Presets;    // 0=Bump 1=Sharp 2=Robotic

// Sample with proper uvScale mapping; transparent outside
vec4 sampleLayer(vec2 uv)
{
  if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return vec4(0.0);
  return texture2D(tDiffuse, uv * uvScale);
}

// Profile preset along the segment (s in 0..1)
float profilePreset(float s, int preset)
{
  float sc = clamp(s, 0.0, 1.0);

  // Triangle: 0 at ends, 1 at center (for Sharp)
  float tri = 1.0 - abs(2.0 * sc - 1.0);
  tri = max(tri, 0.0);

  if (preset == 0) {
    // Bump: smooth rounded hill
    float base = sin(3.14159265 * sc);
    base = max(base, 0.0);
    return pow(base, 2.0);
  }
  else if (preset == 1) {
    // Sharp: pure triangle
    return tri;
  }
  else {
    // Robotic: MORE TRAPEZOID (wider flat top)
    // rampFrac controls ramp width near ends:
    // smaller rampFrac = WIDER flat top (more trapezoid)
    float rampFrac = 0.12;  // <-- was ~0.22, now much more trapezoid

    // Optional robotic stepping along A->B (quantize X)
    float xSteps = 9999.0;    // keep decent resolution so ramps stay straight-ish
    float qx = floor(sc * xSteps + 0.5) / xSteps;

    // Trapezoid: ramp up -> flat -> ramp down
    float leftRamp  = clamp(qx / rampFrac, 0.0, 1.0);
    float rightRamp = clamp((1.0 - qx) / rampFrac, 0.0, 1.0);
    float trap = min(leftRamp, rightRamp); // flat top when qx in [rampFrac .. 1-rampFrac]

    // Optional robotic stepping in height (quantize Y)
    float ySteps = 9999.0;
    trap = floor(trap * ySteps + 0.5) / ySteps;
    trap = min(1.0, trap); // ensure plateau can reach 1.0 cleanly

    return trap;
  }
}

void main()
{
  // --- HARD BYPASS when both splits are effectively zero (prevents seam/strips) ---
  float maxSplit = max(abs(Split_1), abs(Split_2));
  if (maxSplit < 1e-4) {
    gl_FragColor = texture2D(tDiffuse, vUvScaled);
    return;
  }

  vec2 A = Point_A;
  vec2 B = Point_B;

  vec2 d = B - A;
  float L = length(d);

  // Degenerate: A == B
  if (L < 1e-5) {
    gl_FragColor = texture2D(tDiffuse, vUvScaled);
    return;
  }

  // Pixel position
  vec2 p = vUv * resolution;

  // Tangent and normal
  vec2 t = d / L;
  vec2 n = normalize(vec2(-t.y, t.x));

  // Along-segment coordinate
  float u = dot(p - A, t); // 0..L
  float s = u / L;         // 0..1

  // Signed distance to split line
  float distN = dot(p - A, n);
  float absDistN = abs(distN);

  // Clamp presets safely (GLSL ES friendly)
  float pr = clamp(Presets, 0.0, 2.0);
  int preset = int(floor(pr + 0.5)); // 0,1,2

  // Segment mask (inside A..B)
  float segMask = step(0.0, u) * step(u, L);

  // For Bump only: soften ends slightly
  // For Sharp & Robotic: keep crisp ends (helps triangle/trapezoid look)
  if (preset == 0) {
    float taperPx = clamp(0.12 * L, 18.0, 90.0);
    float endMask = smoothstep(0.0, taperPx, u) * smoothstep(0.0, taperPx, (L - u));
    segMask *= endMask;
  }

  // Profile along the segment
  float prof = profilePreset(s, preset) * segMask;

  // CC Split 2: independent split per side of the line
  // distN < 0 uses Split_1, distN > 0 uses Split_2
  float half1 = 0.5 * Split_1 * prof; // negative side
  float half2 = 0.5 * Split_2 * prof; // positive side

  // Local influence away from the split (keeps distortion localized)
  float sigma = max(1.0, maxSplit * 0.65);
  float influence = exp(-absDistN / sigma);

  // Side selection
  float sideSign = (distN >= 0.0) ? 1.0 : -1.0;
  float halfGapSigned = (distN >= 0.0) ? half2 : half1;

  // Inverse warp sample
  float disp = halfGapSigned * influence;
  vec2 sampleUv = (p - n * disp * sideSign) / resolution;

  vec4 col = sampleLayer(sampleUv);

  // --- Asymmetric gap cutout (transparent inside) ---
  // Gap bounds: distN in [-|half1|, +|half2|]
  float g1 = abs(half1);
  float g2 = abs(half2);

  // Anti-alias width (pixels)
  float aa = 1.15;

  float bottomEdge = smoothstep(-g1 - aa, -g1 + aa, distN);
  float topEdge    = smoothstep( g2 - aa,  g2 + aa, distN);

  float insideGap = bottomEdge * (1.0 - topEdge);
  float gapMask = 1.0 - insideGap;

  // Only apply gap within A..B
  gapMask = mix(1.0, gapMask, segMask);

  gl_FragColor = col * gapMask;
}

text./plugins/alipfx/shaders/az-split.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// Custom properties (spaces -> underscores)
uniform vec2 Point_A;
uniform vec2 Point_B;
uniform float Split;

vec4 sampleLayer(vec2 uv)
{
  if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return vec4(0.0);
  return texture2D(tDiffuse, uv * uvScale);
}

void main()
{
  // --- HARD BYPASS WHEN SPLIT IS (NEAR) ZERO ---
  // This removes the residual AA mask line entirely.
  float splitAbs = abs(Split);
  if (splitAbs < 1e-4) {
    gl_FragColor = texture2D(tDiffuse, vUvScaled);
    return;
  }

  vec2 A = Point_A;
  vec2 B = Point_B;

  vec2 d = B - A;
  float L = length(d);

  if (L < 1e-5) {
    gl_FragColor = texture2D(tDiffuse, vUvScaled);
    return;
  }

  vec2 p = vUv * resolution;

  // Tangent and normal
  vec2 t = d / L;
  vec2 n = normalize(vec2(-t.y, t.x));

  // Position along the AB segment in pixels
  float u = dot(p - A, t);   // 0..L
  float s = u / L;           // 0..1

  // Signed distance to the AB line
  float distN = dot(p - A, n);
  float absDistN = abs(distN);
  float sgn = (distN >= 0.0) ? 1.0 : -1.0;

  // Segment mask with pixel-based taper
  float taperPx = clamp(0.12 * L, 18.0, 90.0);
  float segMask = step(0.0, u) * step(u, L);
  float endMask = smoothstep(0.0, taperPx, u) * smoothstep(0.0, taperPx, (L - u));
  segMask *= endMask;

  // AE-like mouth profile along AB
  float sc = clamp(s, 0.0, 1.0);
  float profile = sin(3.14159265 * sc);
  profile = pow(max(profile, 0.0), 2.6);
  profile *= segMask;

  // Half-gap at this 's'
  float gapHalf = 0.5 * Split * profile;

  // Smooth influence away from the split line
  float sigma = max(1.0, splitAbs * 0.65);
  float influence = exp(-absDistN / sigma);

  // Inverse warp sample
  float disp = gapHalf * influence;
  vec2 sampleUv = (p - n * disp * sgn) / resolution;

  vec4 col = sampleLayer(sampleUv);

  // True cutout gap (AA)
  float aa = 1.25;
  float outsideGap = smoothstep(gapHalf - aa, gapHalf + aa, absDistN);

  // Only cut inside segment region
  float gapMask = mix(1.0, outsideGap, segMask);

  gl_FragColor = col * gapMask;
}

text./plugins/alipfx/shaders/az-threads.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUvScaled;

// === Properties ===
uniform float Width;      // pixels
uniform float Height;     // pixels
uniform float Overlaps;   // AE-like small values recommended (0..10)
uniform float Direction;  // degrees
uniform vec2  Center;     // AE PIXELS (e.g. 960,540)
uniform float Coverage;   // 0..100
uniform float Shadowing;  // 0..100
uniform float Texture;    // 0..100 (adds fiber/irregularity)

// --- helpers ---
mat2 rot2(float a){
  float s = sin(a), c = cos(a);
  return mat2(c, -s, s, c);
}

// stable hash/noise (no derivatives)
float hash12(vec2 p){
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise2(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Band mask with manual AA in tile space
float bandMask(float x, float h, float aa){
  return 1.0 - smoothstep(h, h + aa, abs(x));
}

// Cloth-like bevel shading without derivatives
float bevelShade(float coord, float halfT, float sh){
  float ht = max(halfT, 1e-4);
  float d = clamp(abs(coord) / ht, 0.0, 1.0);     // 0 center -> 1 edge
  float profile = 1.0 - smoothstep(0.0, 1.0, d);  // bright center, darker edge

  // fake light from upper-left
  float dir = 0.5 + 0.5 * (-coord / ht);
  float light = mix(0.88, 1.18, dir);

  return mix(1.0, profile * light, sh);
}

void main(){
  // Sample input mainly to preserve alpha and allow tinting from layer color
  vec4 src = texture2D(tDiffuse, vUvScaled);

  // Current pixel position in AE pixel space
  vec2 p = vUvScaled * resolution;

  // Rotate around AE pixel Center
  float ang = radians(Direction);
  vec2 pr = rot2(ang) * (p - Center) + Center;

  // Tile size
  vec2 tile = vec2(max(Width, 0.001), max(Height, 0.001));

  // Manual AA estimate: approx one pixel in tile space
  float aax = 1.25 / tile.x;
  float aay = 1.25 / tile.y;

  // Tile coordinates anchored at Center
  vec2 g = (pr - Center) / tile;
  vec2 cell = floor(g);
  vec2 f = fract(g) - 0.5; // -0.5..0.5 in each tile

  float cov = clamp(Coverage / 100.0, 0.0, 1.0);
  float sh  = clamp(Shadowing / 100.0, 0.0, 1.0);
  float texAmt = clamp(Texture / 100.0, 0.0, 1.0);

  // Texture -> organic thickness variation (fabric roughness)
  float n1 = noise2(pr * 0.035);   // broad
  float n2 = noise2(pr * 0.160);   // fine
  float rough = mix(n1, n2, 0.55); // 0..1
  float thickJitter = (rough - 0.5) * 0.28 * texAmt;

  // Coverage -> thickness within tile
  float halfT = mix(0.03, 0.50, cov);
  halfT *= (1.0 + thickJitter);
  halfT = clamp(halfT, 0.01, 0.50);

  // Two thread sets
  float horiz = bandMask(f.y, halfT, aay);
  float vert  = bandMask(f.x, halfT, aax);

  // Basket-weave alternation
  float parity = mod(cell.x + cell.y, 2.0);
  float topIsHoriz = 1.0 - step(0.5, parity);

  float topMask    = mix(vert,  horiz, topIsHoriz);
  float bottomMask = mix(horiz, vert,  topIsHoriz);

  // Crossings
  float cross = horiz * vert;

  // Overlaps: AE-like small values (0..10 recommended)
  float ov = clamp(Overlaps / 10.0, 0.0, 1.0);

  // Suppress bottom at crossings based on overlap
  bottomMask *= (1.0 - cross * ov);

  float thread = max(topMask, bottomMask);
  float gap = 1.0 - thread;

  // Shading (no derivatives)
  float shadeH = bevelShade(f.y, halfT, sh);
  float shadeV = bevelShade(f.x, halfT, sh);

  float topShade = mix(shadeV, shadeH, topIsHoriz);
  float botShade = mix(shadeH, shadeV, topIsHoriz);

  float shade = 1.0;
  shade *= mix(1.0, topShade, topMask);
  shade *= mix(1.0, botShade, bottomMask);

  // Gap AO + overlap shadow
  shade *= (1.0 - gap * 0.62 * sh);
  shade *= (1.0 - cross * ov * 0.22 * sh);

  // Micro fiber contrast from Texture
  float micro = (noise2(pr * 0.9) - 0.5) * 0.10 * texAmt;
  shade *= (1.0 + micro);

  // Generated pattern luminance
  float bg = mix(0.72, 0.46, sh);
  float th = mix(0.94, 0.80, sh) * shade;
  float patternLum = mix(bg, th, thread);

  // Tinting:
  // Best AE-like workflow: apply shader to a colored solid.
  // Here we use input RGB as the fabric tint; if transparent, default to white.
  vec3 tint = (src.a > 0.0) ? src.rgb : vec3(1.0);
  vec3 outRgb = tint * patternLum;

  // Preserve alpha so it can be used on text/logos too
  gl_FragColor = vec4(outRgb, src.a);
}

text./plugins/alipfx/shaders/az-threshold-rgb:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Threshold sliders (0..255)
uniform float Red_Threshold;
uniform float Green_Threshold;
uniform float Blue_Threshold;

// Invert toggles (0 or 1 in UI, but we treat >0.5 as ON)
uniform float Invert_Red_Channel;
uniform float Invert_Green_Channel;
uniform float Invert_Blue_Channel;

// Blend (0..100)
uniform float Blend_With_Original;

float asToggle(float v)
{
  // <= 0.5 => 0 (OFF), > 0.5 => 1 (ON)
  return step(0.5, v);
}

// Matches AE: invert happens BEFORE thresholding
float thresholdChannel(float c, float thresh255, float invFlag)
{
  float inv = asToggle(invFlag);

  // invert channel pre-threshold
  c = mix(c, 1.0 - c, inv);

  // normalize threshold
  float t = clamp(thresh255 / 255.0, 0.0, 1.0);

  // hard threshold: value >= t => 1 else 0
  return step(t, c);
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  float r = thresholdChannel(texel.r, Red_Threshold, Invert_Red_Channel);
  float g = thresholdChannel(texel.g, Green_Threshold, Invert_Green_Channel);
  float b = thresholdChannel(texel.b, Blue_Threshold, Invert_Blue_Channel);

  vec4 threshRGB = vec4(r, g, b, texel.a);

  // Blend With Original: 0% = threshold only, 100% = original
  float blend = clamp(Blend_With_Original / 100.0, 0.0, 1.0);
  gl_FragColor = mix(threshRGB, texel, blend);
}

text./plugins/alipfx/shaders/az-threshold.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/*
Create these Panzoid properties:

Threshold            (dynamic number) 0..255   default 127.5
Channel              (dynamic number) 0..3     default 0
  0 = Luminance
  1 = RGB
  2 = Saturation
  3 = Alpha
Invert               (dynamic number) 0..1     default 0
Blend_w_Original     (dynamic number) 0..100   default 0
*/

uniform float Threshold;
uniform float Channel;
uniform float Invert;
uniform float Blend_w_Original;

// Rec.709 relative luminance weights (common “true luminance” approximation)
float luminance709(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));  // Rec.709 [3](https://stackoverflow.com/questions/596216/formula-to-determine-perceived-brightness-of-rgb-color)[4](https://contrastchecker.online/color-relative-luminance-calculator)
}

// HSV-style saturation: (max-min)/max, 0 when max==0
float saturationHSV(vec3 c) {
  float mx = max(max(c.r, c.g), c.b);
  float mn = min(min(c.r, c.g), c.b);
  return (mx <= 0.0) ? 0.0 : (mx - mn) / mx;
}

void main() {
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // AE Threshold is 0..255 with default 127.5 [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
  float thr = clamp(Threshold, 0.0, 255.0) / 255.0;

  // Invert toggle (treat >0.5 as ON) [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
  float inv = (Invert > 0.5) ? 1.0 : 0.0;

  // Mix back to original: 0% = full effect, 100% = original [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
  float blend = clamp(Blend_w_Original, 0.0, 100.0) / 100.0;

  int ch = int(floor(Channel + 0.5));

  vec4 effected = texel;

  if (ch == 0) {
    // Luminance → black/white, keep alpha
    float v = luminance709(texel.rgb);
    float m = step(thr, v);              // v >= thr → 1 [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
    m = mix(m, 1.0 - m, inv);
    effected = vec4(vec3(m), texel.a);

  } else if (ch == 1) {
    // RGB → per-channel threshold (8 possible colors), keep alpha [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
    vec3 m = step(vec3(thr), texel.rgb);
    m = mix(m, vec3(1.0) - m, inv);
    effected = vec4(m, texel.a);

  } else if (ch == 2) {
    // Saturation → black/white based on saturation, keep alpha [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
    float s = saturationHSV(texel.rgb);
    float m = step(thr, s);
    m = mix(m, 1.0 - m, inv);
    effected = vec4(vec3(m), texel.a);

  } else {
    // Alpha → threshold alpha only (mostly irrelevant for opaque footage), RGB preserved [1](https://blog.csdn.net/qq_41176800/article/details/147867093)
    float m = step(thr, texel.a);
    m = mix(m, 1.0 - m, inv);
    effected = vec4(texel.rgb, m);
  }

  gl_FragColor = mix(effected, texel, blend);
}

text./plugins/alipfx/shaders/az-tiler.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 resolution;   // built-in
uniform vec2 uvScale;      // built-in

varying vec2 vUv;
varying vec2 vUvScaled;

// === Panzoid custom properties ===
// Create these properties in the effect UI with the exact names:
uniform float Scale;                 // Number (dynamic)   default: 100.0
uniform vec2 Center;                 // 2D Vector          default: (resolution.x/2, resolution.y/2) -> set manually
uniform float Blend_With_Original;   // Number (dynamic)   default: 0.0

// Wrap UV manually (works even if sampler is clamped)
vec2 wrap01(vec2 uv) {
  return fract(uv); // fract handles negatives correctly (x - floor(x))
}

void main()
{
  // Original (untouched) sample
  vec4 original = texture2D(tDiffuse, vUvScaled);

  // Convert Center from pixel space (AE-like) to UV space (0..1)
  vec2 centerUv = Center / resolution;

  // AE CC Tiler scale logic:
  // 100% => factor 1.0 (no change)
  // 25%  => factor 4.0 (more repetition)
  // 200% => factor 0.5 (bigger tiles / zoom-in)
  float s = max(Scale, 0.0001);          // prevent divide-by-zero
  float factor = 100.0 / s;

  // Scale around Center pivot
  vec2 uv = vUv;
  vec2 tiledUv = (uv - centerUv) * factor + centerUv;

  // Repeat infinitely
  tiledUv = wrap01(tiledUv);

  // Sample tiled version (remember to map into buffer UV space)
  vec4 tiled = texture2D(tDiffuse, tiledUv * uvScale);

  // Blend With Original (AE meaning):
  // 0%   => show 100% tiled
  // 100% => show 100% original (effect visually off)
  float blend = clamp(Blend_With_Original / 100.0, 0.0, 1.0);
  gl_FragColor = mix(tiled, original, blend);
}

text./plugins/alipfx/shaders/az-toner.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/* ---- Panzoid custom properties ---- */
uniform float Tones;                 // 0=Duotone, 1=Tritone, 2=Pentone, 3=Solid
uniform vec3 Highlights;
uniform vec3 Brights;
uniform vec3 Midtones;
uniform vec3 Darktones;
uniform vec3 Shadows;
uniform float Blend_With_Original;   // 0..100 (0 = full effect, 100 = original)

/* Luma weights (Rec.601-like; closest to many AE/Cycore legacy behaviors) */
float luma601(vec3 c)
{
  return dot(c, vec3(0.299, 0.587, 0.114));
}

/* Toggle interpolation space:
   1 = mix in linear light (often closer to AE with linearized workflows)
   0 = mix in sRGB (often closer to AE legacy/non-linear look)
*/
#define USE_LINEAR_MIX 1

vec3 toLinear(vec3 c)
{
#if USE_LINEAR_MIX
  return pow(max(c, 0.0), vec3(2.2));
#else
  return c;
#endif
}

vec3 toSRGB(vec3 c)
{
#if USE_LINEAR_MIX
  return pow(max(c, 0.0), vec3(1.0 / 2.2));
#else
  return c;
#endif
}

/* Tone mapping */
vec3 mapTones(float y, int mode)
{
  y = clamp(y, 0.0, 1.0);

  vec3 cH = toLinear(Highlights);
  vec3 cB = toLinear(Brights);
  vec3 cM = toLinear(Midtones);
  vec3 cD = toLinear(Darktones);
  vec3 cS = toLinear(Shadows);

  vec3 outC = cM;

  if (mode == 3)
  {
    // SOLID: use Midtones as single swatch
    outC = cM;
  }
  else if (mode == 0)
  {
    // DUOTONE: Shadows -> Highlights
    outC = mix(cS, cH, y);
  }
  else if (mode == 1)
  {
    // TRITONE: Shadows -> Midtones -> Highlights (mid at 0.5)
    if (y < 0.5)
    {
      float t = y / 0.5;
      outC = mix(cS, cM, t);
    }
    else
    {
      float t = (y - 0.5) / 0.5;
      outC = mix(cM, cH, t);
    }
  }
  else
  {
    // PENTONE: 0.00,0.25,0.50,0.75,1.00
    if (y < 0.25)
    {
      float t = y / 0.25;
      outC = mix(cS, cD, t);
    }
    else if (y < 0.50)
    {
      float t = (y - 0.25) / 0.25;
      outC = mix(cD, cM, t);
    }
    else if (y < 0.75)
    {
      float t = (y - 0.50) / 0.25;
      outC = mix(cM, cB, t);
    }
    else
    {
      float t = (y - 0.75) / 0.25;
      outC = mix(cB, cH, t);
    }
  }

  return toSRGB(outC);
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  float y = luma601(texel.rgb);

  // Round float to nearest int mode safely (NO int clamp()!)
  int mode = int(floor(Tones + 0.5));
  if (mode < 0) mode = 0;
  if (mode > 3) mode = 3;

  vec3 toned = mapTones(y, mode);

  // 0 = full effect, 100 = original
  float blend = clamp(Blend_With_Original / 100.0, 0.0, 1.0);
  vec3 finalRGB = mix(toned, texel.rgb, blend);

  gl_FragColor = vec4(finalRGB, texel.a);
}

text./plugins/alipfx/shaders/az-vector-blur.g:
precision highp float;
precision highp int;

// Built‑ins
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// Custom properties
uniform int Type;                 // 0:Natural, 1:Constant Length, 2:Perpendicular, 3:Direction Center, 4:Direction Fading
uniform float Amount;
uniform float Angle_Offset;
uniform float Ridge_Smoothness;
uniform float Revolutions;
uniform int Property;             // 0:Red,1:Green,2:Blue,3:Alpha,4:Luminance,5:Lightness,6:Hue,7:Saturation
uniform float Map_Softness;

// ------------------------------------------------------------
// Utility: convert RGB to HSV (hue in 0..1)
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y)/(6.0*d + e)), d/(q.x + e), q.x);
}

// ------------------------------------------------------------
// Get scalar map value from the source texel according to Property
float getMapValue(vec4 texel) {
    if (Property == 0) return texel.r;                     // Red
    if (Property == 1) return texel.g;                     // Green
    if (Property == 2) return texel.b;                     // Blue
    if (Property == 3) return texel.a;                     // Alpha
    if (Property == 4) {                                    // Luminance (Rec.709)
        return dot(texel.rgb, vec3(0.2126, 0.7152, 0.0722));
    }
    if (Property == 5) {                                    // Lightness (HSL)
        float mx = max(texel.r, max(texel.g, texel.b));
        float mn = min(texel.r, min(texel.g, texel.b));
        return (mx + mn) * 0.5;
    }
    if (Property == 6) {                                    // Hue
        return rgb2hsv(texel.rgb).x;
    }
    if (Property == 7) {                                    // Saturation
        return rgb2hsv(texel.rgb).y;
    }
    return 0.0;
}

// ------------------------------------------------------------
// 3x3 Gaussian blur with kernel radius = Map_Softness (pixels)
// Also returns Sobel gradients (smoothed) for types 0–2.
void sampleMapWithBlur(vec2 uv, out float smoothVal, out vec2 grad) {
    vec2 px = 1.0 / resolution;
    float scale = max(0.0, Map_Softness);
    vec2 stepUV = px * scale;

    vec2 off[9];
    off[0] = vec2(-1.0, -1.0) * stepUV;
    off[1] = vec2( 0.0, -1.0) * stepUV;
    off[2] = vec2( 1.0, -1.0) * stepUV;
    off[3] = vec2(-1.0,  0.0) * stepUV;
    off[4] = vec2( 0.0,  0.0) * stepUV;
    off[5] = vec2( 1.0,  0.0) * stepUV;
    off[6] = vec2(-1.0,  1.0) * stepUV;
    off[7] = vec2( 0.0,  1.0) * stepUV;
    off[8] = vec2( 1.0,  1.0) * stepUV;

    float s[9];
    for (int i = 0; i < 9; i++) {
        vec4 texel = texture2D(tDiffuse, uv + off[i]);
        s[i] = getMapValue(texel);
    }

    float w[9];
    w[0] = 1.0; w[1] = 2.0; w[2] = 1.0;
    w[3] = 2.0; w[4] = 4.0; w[5] = 2.0;
    w[6] = 1.0; w[7] = 2.0; w[8] = 1.0;
    float sumW = 16.0;

    smoothVal = 0.0;
    for (int i = 0; i < 9; i++) {
        smoothVal += w[i] * s[i];
    }
    smoothVal /= sumW;

    float gx = 0.0, gy = 0.0;
    gx += -1.0 * s[0] + 0.0 * s[1] + 1.0 * s[2];
    gy += -1.0 * s[0] + -2.0 * s[1] + -1.0 * s[2];
    gx += -2.0 * s[3] + 0.0 * s[4] + 2.0 * s[5];
    gy +=  0.0 * s[3] + 0.0 * s[4] + 0.0 * s[5];
    gx += -1.0 * s[6] + 0.0 * s[7] + 1.0 * s[8];
    gy +=  1.0 * s[6] + 2.0 * s[7] + 1.0 * s[8];

    grad = vec2(gx, gy) / 8.0;
    if (Ridge_Smoothness > 0.0) {
        grad *= Ridge_Smoothness;
    }
}

// ------------------------------------------------------------
// Directional blur accumulation – 64 samples for ultra‑smooth fading
vec4 directionalBlur(vec2 uv, vec2 dir, float lenPixels, bool symmetric, bool fading) {
    if (lenPixels < 0.5) return texture2D(tDiffuse, uv);

    vec2 px = 1.0 / resolution;
    const int SAMPLES = 64;                     // increased for maximum smoothness
    vec4 accum = vec4(0.0);
    float totalWeight = 0.0;

    if (symmetric) {
        for (int i = 0; i < SAMPLES; i++) {
            float t = float(i) / float(SAMPLES - 1) * 2.0 - 1.0;  // -1..1
            vec2 offset = dir * (t * lenPixels) * px;
            vec2 sampleUV = uv + offset;
            vec4 c = texture2D(tDiffuse, sampleUV);
            float w = 1.0;
            accum += c * w;
            totalWeight += w;
        }
    } else if (fading) {
        for (int i = 0; i < SAMPLES; i++) {
            float t = float(i) / float(SAMPLES - 1);              // 0..1
            vec2 offset = dir * (t * lenPixels) * px;
            vec2 sampleUV = uv + offset;
            vec4 c = texture2D(tDiffuse, sampleUV);
            // Smoothstep‑based weight: perfectly smooth fade‑out
            float w = 1.0 - smoothstep(0.0, 1.0, t);
            accum += c * w;
            totalWeight += w;
        }
    }

    return accum / totalWeight;
}

// ------------------------------------------------------------
void main() {
    float mapVal;
    vec2 grad;
    sampleMapWithBlur(vUvScaled, mapVal, grad);

    vec4 result = texture2D(tDiffuse, vUvScaled);

    vec2 dir = vec2(0.0);
    float len = 0.0;
    bool symmetric = false;
    bool fading = false;

    if (Type == 0) {        // Natural
        float gradLen = length(grad);
        if (gradLen > 0.0) {
            dir = normalize(grad);
            len = Amount * gradLen;
        }
        symmetric = true;
    }
    else if (Type == 1) {   // Constant Length
        float gradLen = length(grad);
        if (gradLen > 0.0) {
            dir = normalize(grad);
            len = Amount;
        }
        symmetric = true;
    }
    else if (Type == 2) {   // Perpendicular
        float gradLen = length(grad);
        if (gradLen > 0.0) {
            dir = normalize(vec2(-grad.y, grad.x));
            len = Amount * gradLen;
        }
        symmetric = true;
    }
    else if (Type == 3) {   // Direction Center
        float angle = mapVal * 2.0 * 3.14159265 * Revolutions + radians(Angle_Offset);
        dir = vec2(cos(angle), sin(angle));
        len = Amount;
        symmetric = true;
    }
    else if (Type == 4) {   // Direction Fading
        float angle = mapVal * 2.0 * 3.14159265 * Revolutions + radians(Angle_Offset);
        dir = vec2(cos(angle), sin(angle));
        len = Amount;
        fading = true;      // one‑sided with ultra‑smooth fade
    }

    if (len > 0.5) {
        result = directionalBlur(vUvScaled, dir, len, symmetric, fading);
    }

    gl_FragColor = result;
}

text./plugins/alipfx/shaders/bcc-ripple-disso:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// --- User properties ---
uniform float Animation;               // 0 = Auto, 1 = Pct. Done
uniform float Percent_Done;            // 0..100
uniform float Radius_Peak;             // pixels
uniform vec2  Center;                  // pixels
uniform float Height;                  // pixels
uniform float Perpendicular_Height;    // pixels
uniform float Wave_Width;              // pixels
uniform float Width_Percent_Increase;  // percent
uniform float Speed;                   // arbitrary units
uniform float Speed_Deceleration;      // percent-ish control
uniform float Phase;                   // degrees
uniform float Inside_Radius;           // pixels
uniform float Fall_Off;                // pixels
uniform float Light_Level;             // typical 0..200+
uniform vec3  Light_Color;             // RGB
uniform float Pin_Width;               // pixels
uniform float time;                    // for Auto mode

const float PI  = 3.14159265358979323846;
const float TAU = 6.28318530717958647692;

float saturate(float x) {
  return clamp(x, 0.0, 1.0);
}

vec2 bufferUV(vec2 uv) {
  return uv * uvScale;
}

vec4 sampleCurrent(vec2 uv) {
  return texture2D(tDiffuse, bufferUV(clamp(uv, 0.0, 1.0)));
}

// Best if time is animated 0..1 across the transition
float getProgress() {
  float autoP = saturate(time);
  autoP = autoP * autoP * (3.0 - 2.0 * autoP);

  float manualP = saturate(Percent_Done / 100.0);

  return mix(autoP, manualP, step(0.5, Animation));
}

// Reduces tearing near the edges
float getPinMask(vec2 uv) {
  float edgeDistX = min(uv.x * resolution.x, (1.0 - uv.x) * resolution.x);
  float edgeDistY = min(uv.y * resolution.y, (1.0 - uv.y) * resolution.y);
  float edgeDist  = min(edgeDistX, edgeDistY);

  if (Pin_Width <= 0.0) return 1.0;
  return smoothstep(0.0, Pin_Width, edgeDist);
}

void main() {
  vec2 uv = vUv;

  // Center uses pixel coordinates
  vec2 centerUV = Center / resolution;

  // Pixel-space delta from center
  vec2 dp = (uv - centerUV) * resolution;
  float r = length(dp);

  vec2 dir = (r > 0.0001) ? (dp / r) : vec2(1.0, 0.0);
  vec2 tangent = vec2(-dir.y, dir.x);

  float progress = getProgress();

  // Peaks mid-transition and returns to zero at end
  float envelope = sin(progress * PI);

  // Expanding ripple radius
  float outerRadius = Radius_Peak * progress;

  // Wave width expands over time
  float widthNow = max(
    0.001,
    Wave_Width * (1.0 + (Width_Percent_Increase / 100.0) * progress)
  );

  // Speed with deceleration
  float decel = max(0.0, Speed_Deceleration / 100.0);
  float travelT = progress - 0.5 * decel * progress * progress;
  travelT = max(0.0, travelT);

  float phaseRad = radians(Phase);

  // Active ripple zone
  float innerMask = smoothstep(
    Inside_Radius,
    Inside_Radius + max(Fall_Off, 0.001),
    r
  );

  float outerMask = 1.0 - smoothstep(
    outerRadius,
    outerRadius + max(Fall_Off, 0.001),
    r
  );

  float bandMask = innerMask * outerMask;

  // Ripple waveform
  float motion = Speed * travelT;
  float waveArg = TAU * ((r - motion) / widthNow) + phaseRad;
  float wave = sin(waveArg);

  float strength = bandMask * envelope;

  // Distortion
  float radialDispPx     = Height * wave * strength;
  float tangentialDispPx = Perpendicular_Height * wave * strength;

  // Slight outer boost
  float radialBoost = mix(0.75, 1.15, saturate(r / max(Radius_Peak, 1.0)));
  tangentialDispPx *= radialBoost;

  // Pinning
  float pinMask = getPinMask(uv);
  radialDispPx     *= pinMask;
  tangentialDispPx *= pinMask;

  vec2 dispUV = (dir * radialDispPx + tangent * tangentialDispPx) / resolution;
  vec2 warpedUV = uv + dispUV;

  // Base + warped sample of the same current layer
  vec4 baseCol   = sampleCurrent(uv);
  vec4 warpedCol = sampleCurrent(warpedUV);

  // Distortion only: no alpha blackout at progress 0
  float distortionMix = saturate(strength);
  vec4 outCol = mix(baseCol, warpedCol, distortionMix);

  // Crest lighting
  float crest = max(wave, 0.0);
  crest = crest * crest * strength;

  float lightAmt = Light_Level / 100.0;
  outCol.rgb += Light_Color * crest * lightAmt;

  // Preserve original alpha
  outCol.a = baseCol.a;

  gl_FragColor = vec4(clamp(outCol.rgb, 0.0, 1.0), clamp(outCol.a, 0.0, 1.0));
}

text./plugins/alipfx/shaders/better-ramp-v2.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

// --- CUSTOM PROPERTIES ---
// 1. Gradient Type
uniform float Type; // 0 for Linear, 1 for Radial

// 2-9. Gradient Colors
uniform vec3 Color_1;
uniform vec3 Color_2;
uniform vec3 Color_3;
uniform vec3 Color_4;
uniform vec3 Color_5;
uniform vec3 Color_6;
uniform vec3 Color_7;
uniform vec3 Color_8;

// 10. Amount of active colors
uniform float Gradient_Colors; // Range: 2 to 8

// 11-12. Position mapping
uniform vec2 Start_Point;
uniform vec2 End_Point;

// 13-16. Value modifiers
uniform float Reverse;
uniform float Offset; // Angle in degrees
uniform float Warp_Blend; 
uniform float Scatter;

// 17-18. Blending
uniform float Blend_Mode; // 0 to 15
uniform float Blend_Opacity; // 0.0 to 100.0

// 19-20. Radial specific settings
uniform float Radial_Highlight_Angle;
uniform float Radial_Highlight_Length;

// -- GRADIENT SAMPLER --
vec3 getGradient(float t) {
    // Clamp to ensure we don't break the interpolator
    int count = int(clamp(Gradient_Colors, 2.0, 8.0));
    float pos = t * float(count - 1);
    int index = int(floor(pos));
    float frac = fract(pos);

    vec3 c0 = Color_1; 
    vec3 c1 = Color_2;

    // Dynamic array lookups via if-statements (Safe for all WebGL environments)
    if (index == 0) { c0 = Color_1; c1 = Color_2; }
    else if (index == 1) { c0 = Color_2; c1 = Color_3; }
    else if (index == 2) { c0 = Color_3; c1 = Color_4; }
    else if (index == 3) { c0 = Color_4; c1 = Color_5; }
    else if (index == 4) { c0 = Color_5; c1 = Color_6; }
    else if (index == 5) { c0 = Color_6; c1 = Color_7; }
    else if (index >= 6) { c0 = Color_7; c1 = Color_8; }

    return mix(c0, c1, frac);
}

void main() {
    // Fetch input layer
    vec4 baseTexel = texture2D(tDiffuse, vUvScaled);
    vec3 base = baseTexel.rgb;
    float alpha = baseTexel.a;

    // Convert UVs to precise pixel space mapping (Matches After Effects format)
    vec2 P = vUv * resolution;
    vec2 A = Start_Point;
    vec2 B = End_Point;

    // Apply Offset Rotation mapping
    float rad = radians(Offset);
    float s = sin(rad);
    float c = cos(rad);
    vec2 mid = (A + B) * 0.5;
    A = vec2(c * (A.x - mid.x) - s * (A.y - mid.y), s * (A.x - mid.x) + c * (A.y - mid.y)) + mid;
    B = vec2(c * (B.x - mid.x) - s * (B.y - mid.y), s * (B.x - mid.x) + c * (B.y - mid.y)) + mid;

    float t = 0.0;

    if (Type < 0.5) {
        // --- LINEAR MAPPING ---
        vec2 dir = B - A;
        float len2 = dot(dir, dir);
        t = (len2 > 0.0) ? dot(P - A, dir) / len2 : 0.0;
    } else {
        // --- RADIAL MAPPING WITH FOCAL OFFSET ---
        float R = length(B - A);
        vec2 F = A;

        // Push the focal highlight out
        if (Radial_Highlight_Length > 0.0) {
            float hRad = radians(Radial_Highlight_Angle);
            F = A + vec2(cos(hRad), sin(hRad)) * (Radial_Highlight_Length * R);
        }

        // Intersect ray with circle equation for precise focal gradient mapping
        vec2 D = P - F;
        vec2 F_rel = F - A;
        float a_val = dot(D, D);
        float b_val = 2.0 * dot(F_rel, D);
        float c_val = dot(F_rel, F_rel) - R * R;

        if (a_val > 0.0001) {
            float disc = b_val * b_val - 4.0 * a_val * c_val;
            if (disc >= 0.0) {
                float s_val = (-b_val + sqrt(disc)) / (2.0 * a_val);
                if (s_val > 0.0) {
                    t = 1.0 / s_val;
                }
            }
        } else {
            // Fallback safety if pixel precisely hits the focal point
            t = (R > 0.0) ? length(P - A) / R : 0.0;
        }
    }

    // Apply Scatter (Organic value-noise dithering)
    if (Scatter > 0.0) {
        float noise = fract(sin(dot(vUv, vec2(12.9898, 78.233))) * 43758.5453);
        t += (noise - 0.5) * Scatter;
    }

    // Apply Reverse
    if (Reverse > 0.5) {
        t = 1.0 - t;
    }

    // Apply Warp Blend
    if (Warp_Blend > 0.0) {
        float wrapT = fract(t);
        t = mix(wrapT, smoothstep(0.0, 1.0, wrapT), Warp_Blend);
    } else {
        t = clamp(t, 0.0, 1.0); // Default Hard Clamp
    }

    // Pull final gradient color
    vec3 gradColor = getGradient(t);
    vec3 blended = gradColor;
    float op = clamp(Blend_Opacity / 100.0, 0.0, 1.0);

    int bm = int(Blend_Mode);

    // --- BLEND MODES (0 - 15) ---
    if (bm == 0) { blended = mix(base, gradColor, op); } // 0: None
    else if (bm == 1) { blended = mix(base, gradColor, op); } // 1: Normal
    else if (bm == 2) { blended = 1.0 - (1.0 - base) * (1.0 - gradColor); } // 2: Screen
    else if (bm == 3) { blended = base + gradColor; } // 3: Add
    else if (bm == 4) { blended = base * gradColor; } // 4: Multiply
    else if (bm == 5) { // 5: Overlay
        vec3 check = step(0.5, base);
        blended = mix(2.0 * base * gradColor, 1.0 - 2.0 * (1.0 - base) * (1.0 - gradColor), check);
    }
    else if (bm == 6) { // 6: Soft Light
        vec3 check = step(0.5, gradColor);
        blended = mix(base - (1.0 - 2.0 * gradColor) * base * (1.0 - base), base + (2.0 * gradColor - 1.0) * (sqrt(base) - base), check);
    }
    else if (bm == 7) { blended = abs(base - gradColor); } // 7: Difference
    else if (bm == 8) { blended = base / max(1.0 - gradColor, vec3(0.001)); } // 8: Color Dodge
    else if (bm == 9) { blended = 1.0 - (1.0 - base) / max(gradColor, vec3(0.001)); } // 9: Color Burn
    else if (bm == 10) { blended = min(base, gradColor); } // 10: Darken
    else if (bm == 11) { blended = max(base, gradColor); } // 11: Lighten
    else if (bm == 12) { alpha = alpha * (1.0 - length(gradColor) * op); blended = base; } // 12: Silhouette Alpha
    else if (bm == 13) { alpha = alpha * (1.0 - dot(gradColor, vec3(0.299, 0.587, 0.114)) * op); blended = base; } // 13: Silhouette Luma
    else if (bm == 14) { alpha = alpha * mix(1.0, length(gradColor), op); blended = base; } // 14: Stencil Alpha
    else if (bm == 15) { alpha = alpha * mix(1.0, dot(gradColor, vec3(0.299, 0.587, 0.114)), op); blended = base; } // 15: Stencil Luma

    // Apply Blend Opacity slider over final composite (applies to RGB composite modes 2-11)
    if (bm >= 2 && bm <= 11) {
        blended = mix(base, clamp(blended, 0.0, 1.0), op);
    }

    gl_FragColor = vec4(blended, alpha);
}

text./plugins/alipfx/shaders/better-ramp.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;
varying vec2 vUv;

// --- Better Ramp Uniforms ---
uniform vec2 Start_Point;
uniform vec3 Start_Color;
uniform float Start_Opacity;
uniform vec2 End_Point;
uniform vec3 End_Color;
uniform float End_Opacity;

uniform float Type; // 0: Linear, 1: Radial
uniform float Swap_Colors; // 0: Disabled, 1: Enabled

uniform float Radial_Highlight_Angle;
uniform float Radial_Highlight_Length;

uniform float Blend;
uniform float Bias;
uniform float Scatter;
uniform float Perceptual_Mix;
uniform float Blend_Mode;

// --- Oklab Perceptual Color Space Functions ---
float srgb_to_linear(float c) {
    return c <= 0.04045 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4);
}
vec3 srgb_to_linear(vec3 c) {
    return vec3(srgb_to_linear(c.r), srgb_to_linear(c.g), srgb_to_linear(c.b));
}
float linear_to_srgb(float c) {
    return c <= 0.0031308 ? 12.92 * c : 1.055 * pow(c, 1.0 / 2.4) - 0.055;
}
vec3 linear_to_srgb(vec3 c) {
    return vec3(linear_to_srgb(c.r), linear_to_srgb(c.g), linear_to_srgb(c.b));
}

vec3 linear_srgb_to_oklab(vec3 c) {
    float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
    float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
    float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
    float l_ = pow(max(l, 0.0), 1.0/3.0);
    float m_ = pow(max(m, 0.0), 1.0/3.0);
    float s_ = pow(max(s, 0.0), 1.0/3.0);
    return vec3(
        0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_,
        1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_,
        0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_
    );
}

vec3 oklab_to_linear_srgb(vec3 c) {
    float l_ = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
    float m_ = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
    float s_ = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
    float l = l_*l_*l_;
    float m = m_*m_*m_;
    float s = s_*s_*s_;
    return vec3(
        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
       -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
       -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
    );
}

// --- High-Frequency Pseudo-Random Noise ---
float rand(vec2 co){
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

// --- Blend Mode Functions ---
float blendOverlay(float b, float f) { return (b < 0.5) ? (2.0 * b * f) : (1.0 - 2.0 * (1.0 - b) * (1.0 - f)); }
vec3 blendOverlay(vec3 b, vec3 f) { return vec3(blendOverlay(b.r, f.r), blendOverlay(b.g, f.g), blendOverlay(b.b, f.b)); }
float blendSoftLight(float b, float f) { return (f < 0.5) ? (b - (1.0 - 2.0 * f) * b * (1.0 - b)) : (b + (2.0 * f - 1.0) * (sqrt(b) - b)); }
vec3 blendSoftLight(vec3 b, vec3 f) { return vec3(blendSoftLight(b.r, f.r), blendSoftLight(b.g, f.g), blendSoftLight(b.b, f.b)); }

void main() {
    vec2 aspect = vec2(resolution.x / resolution.y, 1.0);
    vec2 uv = vUv * aspect;
    vec2 p1 = Start_Point * aspect;
    vec2 p2 = End_Point * aspect;

    float t = 0.0;

    if (Type < 0.5) {
        // Linear Mode
        vec2 dir = p2 - p1;
        float lenSq = dot(dir, dir);
        t = lenSq > 0.00001 ? dot(uv - p1, dir) / lenSq : 0.0;
    } else {
        // Radial Mode
        float r = distance(p1, p2);
        float angleRad = radians(Radial_Highlight_Angle);
        float shiftAmt = clamp(Radial_Highlight_Length / 100.0, 0.0, 0.999) * r;

        vec2 F = p1 + vec2(cos(angleRad), sin(angleRad)) * shiftAmt;
        vec2 C = p1;

        vec2 V = uv - F;
        vec2 D = C - F;

        float A = dot(D, D) - r * r;
        float B = -2.0 * dot(V, D);
        float C_val = dot(V, V);

        float disc = B * B - 4.0 * A * C_val;
        if (disc >= 0.0 && abs(A) > 0.00001) {
            float t_rad = (-B - sqrt(disc)) / (2.0 * A);
            if (t_rad < 0.0) t_rad = (-B + sqrt(disc)) / (2.0 * A);
            t = clamp(t_rad, 0.0, 1.0);
        } else {
            t = r > 0.00001 ? distance(uv, p1) / r : 0.0;
        }
    }

    t = clamp(t, 0.0, 1.0);

    // Normalize Opacities & Base Color assignments
    float actualStartOpacity = Start_Opacity > 1.0 ? Start_Opacity / 100.0 : Start_Opacity;
    float actualEndOpacity = End_Opacity > 1.0 ? End_Opacity / 100.0 : End_Opacity;
    vec3 colStart = Start_Color;
    vec3 colEnd = End_Color;

    // --- FIXED SWAP COLORS LOGIC ---
    // Swapping color definitions directly without modifying 't' removes the cancellation bug.
    if (Swap_Colors > 0.5) {
        float tempOp = actualStartOpacity;
        actualStartOpacity = actualEndOpacity;
        actualEndOpacity = tempOp;
        colStart = End_Color;
        colEnd = Start_Color;
    }

    // Smooth Contrast (Blend) and Distribution (Bias)
    float blendVal = max(Blend / 100.0, 0.0001);
    t = clamp((t - 0.5) / blendVal + 0.5, 0.0, 1.0);

    float biasVal = clamp(Bias / 100.0, 0.001, 0.999);
    t = pow(t, log(0.5) / log(biasVal));

    // Scatter Engine (restricts noise to boundaries properly)
    if (Scatter > 0.0) {
        float noise = (rand(vUv) - 0.5) * (Scatter / 100.0);
        t = clamp(t + noise, 0.0, 1.0);
    }

    // Color Mixing Matrix mapping
    vec3 linStart = srgb_to_linear(colStart);
    vec3 linEnd = srgb_to_linear(colEnd);

    vec3 okStart = linear_srgb_to_oklab(linStart);
    vec3 okEnd = linear_srgb_to_oklab(linEnd);
    vec3 okMix = oklab_to_linear_srgb(mix(okStart, okEnd, t));

    vec3 rgbMix = mix(linStart, linEnd, t);
    vec3 finalGradCol = linear_to_srgb(mix(rgbMix, okMix, Perceptual_Mix / 100.0));

    float finalGradAlpha = mix(actualStartOpacity, actualEndOpacity, t);

    // Final Compositing & Blend Modes
    vec4 baseTexel = texture2D(tDiffuse, vUvScaled);
    vec3 base = baseTexel.rgb;
    vec3 result = finalGradCol;
    float outAlpha = finalGradAlpha;

    if (Blend_Mode > 0.5 && Blend_Mode < 11.5) {
        vec3 blendedCol = finalGradCol;
        if (Blend_Mode == 1.0) { blendedCol = finalGradCol; }
        else if (Blend_Mode == 2.0) { blendedCol = 1.0 - (1.0 - base) * (1.0 - finalGradCol); }
        else if (Blend_Mode == 3.0) { blendedCol = min(base + finalGradCol, 1.0); }
        else if (Blend_Mode == 4.0) { blendedCol = base * finalGradCol; }
        else if (Blend_Mode == 5.0) { blendedCol = blendOverlay(base, finalGradCol); }
        else if (Blend_Mode == 6.0) { blendedCol = blendSoftLight(base, finalGradCol); }
        else if (Blend_Mode == 7.0) { blendedCol = abs(base - finalGradCol); }

        result = mix(base, blendedCol, finalGradAlpha);
        outAlpha = finalGradAlpha + baseTexel.a * (1.0 - finalGradAlpha);
    } 
    else if (Blend_Mode >= 12.0) {
        float luma = dot(finalGradCol, vec3(0.299, 0.587, 0.114));
        result = base;
        if (Blend_Mode == 12.0) { outAlpha = baseTexel.a * (1.0 - finalGradAlpha); }
        else if (Blend_Mode == 14.0) { outAlpha = baseTexel.a * finalGradAlpha; }
    }

    gl_FragColor = vec4(result, outAlpha);
}

text./plugins/alipfx/shaders/bevel-alpha.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

// ---- Custom properties (Panzoid: spaces become underscores) ----
uniform float Edge_Thickness;   // pixels
uniform float Light_Angle;      // degrees
uniform vec3  Light_Color;      // 0..1
uniform float Light_Intensity;  // 0..1 (can exceed)

// Fixed shadow color (AE-like: shadow is essentially black)
const vec3 SHADOW_COLOR = vec3(0.0);

// Samples for the soft bevel (AE Bevel Alpha is softer than Bevel Edges)
const int SAMPLES = 12;

// Helper: alpha sample
float alphaAt(vec2 uv) {
  return texture2D(tDiffuse, uv).a;
}

void main() {
  vec2 uv = vUvScaled;
  vec4 texel = texture2D(tDiffuse, uv);

  // Early out
  float thicknessPx = max(0.0, Edge_Thickness);
  if (thicknessPx <= 0.0001) {
    gl_FragColor = texel;
    return;
  }

  // Pixel step in scaled-UV space (Panzoid mapping)
  vec2 px = uvScale / resolution;

  // -------------------------------
  // AE-ish light angle mapping
  // AE default Light Angle is often -60°; we bias so -60 tends to look like AE's default direction.
  // If your highlight/shadow feel rotated vs AE, change ANGLE_OFFSET slightly.
  // -------------------------------
  const float ANGLE_OFFSET = 195.0; // tweakable constant for "AE feel"
  float rad = radians(Light_Angle + ANGLE_OFFSET);
  vec2 lightDir = normalize(vec2(cos(rad), sin(rad)));

  // -----------------------------------------
  // 1) Bevel from ALPHA edges (main AE mode)
  // -----------------------------------------
  float accum = 0.0;
  float wsum  = 0.0;

  for (int i = 1; i <= SAMPLES; i++) {
    float t = float(i) / float(SAMPLES); // 0..1
    float w = 1.0 - t;                   // stronger near edge
    vec2 off = lightDir * (t * thicknessPx) * px;

    float ap = alphaAt(uv + off);
    float am = alphaAt(uv - off);

    accum += (ap - am) * w;
    wsum  += w;
  }

  float bevelAlpha = (wsum > 0.0) ? (accum / wsum) : 0.0;

  // Mask the bevel to the edge area (keeps interior flatter)
  float edgeMask = clamp(abs(bevelAlpha) * 2.0, 0.0, 1.0);
  edgeMask *= smoothstep(0.0, 0.01, texel.a); // avoid affecting fully transparent pixels

  // ---------------------------------------------------------
  // 2) AE behavior: if layer is fully opaque, bevel the BBOX
  // (AE manual: fully opaque → bevel applies to bounding box)
  // We detect "locally opaque everywhere" using neighborhood samples.
  // ---------------------------------------------------------
  float opaqueTest = texel.a;
  // quick neighborhood check (small)
  opaqueTest = min(opaqueTest, alphaAt(uv + vec2( 1.0, 0.0) * px));
  opaqueTest = min(opaqueTest, alphaAt(uv + vec2(-1.0, 0.0) * px));
  opaqueTest = min(opaqueTest, alphaAt(uv + vec2(0.0,  1.0) * px));
  opaqueTest = min(opaqueTest, alphaAt(uv + vec2(0.0, -1.0) * px));

  bool fullyOpaqueLocal = (opaqueTest > 0.999);

  // Bounding-box bevel mask + direction signal (only if fully opaque)
  float bevelBBox = 0.0;
  float bboxMask  = 0.0;

  if (fullyOpaqueLocal) {
    // distance to nearest box edge in UV units (vUvScaled ranges 0..uvScale)
    float dL = uv.x;
    float dR = uvScale.x - uv.x;
    float dB = uv.y;
    float dT = uvScale.y - uv.y;

    float dMin = min(min(dL, dR), min(dB, dT)); // nearest distance to box edge (UV)
    float distPx = dMin / max(px.x, px.y);      // approx pixels

    bboxMask = 1.0 - clamp(distPx / thicknessPx, 0.0, 1.0);

    // Determine approximate outward normal of nearest edge
    vec2 n = vec2(0.0);
    if (dMin == dL) n = vec2(-1.0, 0.0);
    else if (dMin == dR) n = vec2( 1.0, 0.0);
    else if (dMin == dB) n = vec2(0.0, -1.0);
    else                 n = vec2(0.0,  1.0);

    bevelBBox = dot(n, lightDir) * bboxMask;
  }

  // Choose alpha-bevel normally; if fully opaque, prefer bbox bevel
  float bevel = fullyOpaqueLocal ? bevelBBox : bevelAlpha;
  float mask  = fullyOpaqueLocal ? bboxMask  : edgeMask;

  // -------------------------------
  // Lighting application (AE-like)
  // Highlights tinted by Light Color
  // Shadows go toward black (fixed)
  // Both driven by Light Intensity
  // -------------------------------
  float intensity = max(0.0, Light_Intensity);

  float hi = max(bevel, 0.0) * intensity;
  float sh = max(-bevel, 0.0) * intensity;

  vec3 col = texel.rgb;

  // Highlight: mix toward Light_Color
  col = mix(col, Light_Color, clamp(mask * hi, 0.0, 1.0));

  // Shadow: mix toward black
  col = mix(col, SHADOW_COLOR, clamp(mask * sh, 0.0, 1.0));

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), texel.a);
}

text./plugins/alipfx/shaders/block-dissolve.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

// Panzoid Custom Properties
uniform float Transition_Completion;
uniform float Block_Width;
uniform float Block_Height;
uniform float Feather;
uniform float Soft_Edges;

varying vec2 vUvScaled;
varying vec2 vUv;

// High-precision hash function (Fixes the horizontal dash/stretching artifacts)
float rand(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

void main() {
    // Read the input layer
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // Ensure resolution isn't 0 to avoid division by zero scaling artifacts
    vec2 res = max(resolution, vec2(1.0));
    vec2 fragCoord = vUv * res;

    // Prevent division by zero and enforce minimum 1px block sizes
    float bWidth = max(Block_Width, 1.0);
    float bHeight = max(Block_Height, 1.0);
    vec2 blockSize = vec2(bWidth, bHeight);

    // Calculate grid and block data
    vec2 gridPos = fragCoord / blockSize;
    vec2 blockId = floor(gridPos);
    vec2 blockFract = fract(gridPos);

    // Base random value for the current block
    float noiseVal = rand(blockId);

    // Normalize parameter ranges
    float completion = clamp(Transition_Completion / 100.0, 0.0, 1.0);
    float featherNorm = clamp(Feather / 100.0, 0.0, 1.0);

    // --------------------------------------------------------
    // 1. FEATHER & SOFT EDGES (Spatial Blurring)
    // --------------------------------------------------------
    if (Soft_Edges > 0.5 || featherNorm > 0.0) {
        // Bilinear interpolation of noise to create a gradient-based "cloudy" blend
        float n00 = noiseVal;
        float n10 = rand(blockId + vec2(1.0, 0.0));
        float n01 = rand(blockId + vec2(0.0, 1.0));
        float n11 = rand(blockId + vec2(1.0, 1.0));

        vec2 u = blockFract;
        if (Soft_Edges > 0.5) {
            // Subpixel smoothing for edges (smoothstep curve)
            u = u * u * (3.0 - 2.0 * u);
        }

        float interpolatedNoise = mix(
            mix(n00, n10, u.x),
            mix(n01, n11, u.x),
            u.y
        );

        // Blend between hard pixel blocks and soft interpolated noise based on Feather
        float mixFactor = clamp(featherNorm * 2.0, 0.0, 1.0); 

        // If Feather is 0 but Soft Edges is ON, apply a tiny micro-blend to act as Anti-Aliasing
        if (featherNorm == 0.0 && Soft_Edges > 0.5) {
            mixFactor = 0.05; 
        }

        noiseVal = mix(noiseVal, interpolatedNoise, mixFactor);
    }

    // --------------------------------------------------------
    // 2. ALPHA CUTOFF & TRANSITION LOGIC
    // --------------------------------------------------------
    float alpha = 1.0;

    // Determine the transition "spread" based on Feather and Soft Edges
    float spread = featherNorm;
    if (Soft_Edges > 0.5 && spread < 0.01) {
        spread = 0.01; // Minimum spread to provide anti-aliased edges
    }

    if (spread > 0.0) {
        // Soft Transition: Uses smoothstep to fade blocks in/out gradually
        // Map the completion threshold so 0% is completely visible and 100% is completely gone
        float c = completion * (1.0 + 2.0 * spread) - spread;
        alpha = smoothstep(c - spread, c + spread, noiseVal);
    } else {
        // Hard Transition: Pure crisp, jagged blocks (Soft Edges = 0, Feather = 0)
        alpha = step(completion, noiseVal);

        // Strict boundary fixes
        if (completion <= 0.0) {
            alpha = 1.0;
        } else if (completion >= 1.0) {
            alpha = 0.0;
        }
    }

    // Output final color with modified alpha applied
    gl_FragColor = vec4(texel.rgb, texel.a * alpha);
}

text./plugins/alipfx/shaders/brush-strokes.gl:
precision highp float;
precision highp int;

// Built-in Panzoid Uniforms & Varyings
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;
uniform vec2 uvScale;

// Custom Effect Uniforms
uniform float Stroke_Angle;
uniform float Brush_Size;
uniform float Stroke_Length;
uniform float Stroke_Density;
uniform float Stroke_Randomness;
uniform float Paint_Surface;
uniform float Blend_With_Original;

// Pseudo-random noise functions for scattering
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec2 hash2(vec2 p) {
    return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}

void main() {
    // 1. Sample the original unmodified layer
    vec4 originalColor = texture2D(tDiffuse, vUvScaled);

    // Bypass effect if brush is too small to render
    if (Brush_Size <= 0.5 || Stroke_Length <= 0.01) {
        gl_FragColor = mix(originalColor, originalColor, clamp(Blend_With_Original / 100.0, 0.0, 1.0));
        return;
    }

    // 2. Set Background based on Paint_Surface (0=Original, 1=Transparent, 2=White, 3=Black)
    int surfaceMode = int(Paint_Surface + 0.5);
    vec4 bgColor = originalColor; 
    if (surfaceMode == 1) bgColor = vec4(0.0); 
    else if (surfaceMode == 2) bgColor = vec4(1.0); 
    else if (surfaceMode == 3) bgColor = vec4(0.0, 0.0, 0.0, 1.0);

    // 3. Prepare Stroke Angle Matrix (Convert to radians)
    float angle = radians(Stroke_Angle);
    float s = sin(angle);
    float c = cos(angle);
    mat2 rot = mat2(c, -s, s, c);
    mat2 invRot = mat2(c, s, -s, c);

    // 4. Calculate Pixel Space and Grid 
    vec2 pos = vUv * resolution;
    vec2 rotatedPos = rot * pos;

    // Density controls grid spacing (higher density = tighter grid/more dabs)
    float densityFactor = max(0.1, Stroke_Density);
    float spacing = max(1.0, Brush_Size / densityFactor);

    float halfWidth = max(1.0, Brush_Size * 0.5);
    float halfLength = max(1.0, halfWidth * Stroke_Length);

    vec4 paintedColor = vec4(0.0);
    float highestZ = -1.0;

    // Calculate maximum required search bounds dynamically to skip useless loop iterations
    // This allows the stroke to reach length 40 without burning out the GPU
    float maxSearchY = ceil((halfLength / spacing) + 1.0);
    float maxSearchX = ceil((halfWidth / spacing) + 1.0);

    // 5. Asymmetric Grid Search (Expanded Y-axis to accommodate stroke lengths up to ~40+)
    for (float y = -20.0; y <= 20.0; y++) {
        // GPU optimization: Early exit if the grid cell is too far up/down the stroke length
        if (abs(y) > maxSearchY) continue;

        for (float x = -3.0; x <= 3.0; x++) {
            // GPU optimization: Early exit if the grid cell is too far beside the stroke width
            if (abs(x) > maxSearchX) continue;

            // Identify current grid cell
            vec2 gridPos = floor(rotatedPos / spacing) + vec2(x, y);
            vec2 cellCenter = (gridPos + 0.5) * spacing;

            // Apply Stroke Randomness
            vec2 randomOffset = (hash2(gridPos) - 0.5) * spacing * Stroke_Randomness * 1.5;
            vec2 strokeCenter = cellCenter + randomOffset;

            // Distance from fragment to stroke dab center
            vec2 delta = rotatedPos - strokeCenter;

            // Oval distance check (creates the directional "dab" shape)
            float distSq = (delta.x * delta.x) / (halfWidth * halfWidth) +
                           (delta.y * delta.y) / (halfLength * halfLength);

            if (distSq <= 1.0) {
                // Soften stroke edges for a natural paint texture
                float alpha = smoothstep(1.0, 0.7, distSq);

                // Sample the color from the center of the stroke to mimic AE's color pulling
                vec2 samplePos = invRot * strokeCenter;
                vec2 sampleUv = samplePos / resolution;

                // Clamp UVs to avoid edge bleeding
                if (sampleUv.x >= 0.0 && sampleUv.x <= 1.0 && sampleUv.y >= 0.0 && sampleUv.y <= 1.0) {

                    // Z-Ordering using hash so random dabs render "on top"
                    float zOrder = hash(gridPos + 12.34);
                    if (zOrder > highestZ) {
                        highestZ = zOrder;

                        // Scale UVs accurately for Panzoid's buffer system
                        vec2 sampleUvScaled = sampleUv * uvScale;
                        vec3 sampledTex = texture2D(tDiffuse, sampleUvScaled).rgb;
                        paintedColor = vec4(sampledTex, alpha);
                    }
                }
            }
        }
    }

    // 6. Apply Paint Surface Logic
    vec4 finalEffectColor = bgColor;
    if (paintedColor.a > 0.0) {
        // Blend stroke over background
        finalEffectColor = vec4(mix(bgColor.rgb, paintedColor.rgb, paintedColor.a), max(bgColor.a, paintedColor.a));
    }

    // 7. Blend With Original (0% = Full Paint, 100% = Original Image)
    float blendFactor = clamp(Blend_With_Original / 100.0, 0.0, 1.0);
    gl_FragColor = mix(finalEffectColor, originalColor, blendFactor);
}

text./plugins/alipfx/shaders/cartoon.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// Panzoid custom properties
uniform float Render;               // 0 Fill, 1 Edges, 2 Fill & Edges
uniform float Detail_Radius;        // pixels
uniform float Detail_Threshold;     // 0..100
uniform float Shading_Steps;        // 1..32
uniform float Shading_Smoothness;   // 0..100
uniform float Threshold;            // 0..10
uniform float Width;                // pixels
uniform float Softness;             // 0..100
uniform float Opacity;              // 0..100
uniform float Edge_Enhancement;     // -5..5
uniform float Edge_Black_Level;     // 0..5
uniform float Edge_Contrast;        // 0..2

float saturate(float x) {
    return clamp(x, 0.0, 1.0);
}

vec3 src(vec2 uv) {
    return texture2D(tDiffuse, uv).rgb;
}

float luma(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

// ----------------------------------------------------
// Lightweight edge-preserving smoothing for fill
// 9 taps total
// ----------------------------------------------------
vec3 fastSmooth(vec2 uv) {
    vec3 c0 = src(uv);

    float r = max(Detail_Radius, 0.0);
    if (r < 0.5) return c0;

    vec2 px = 1.0 / resolution;
    float rr = max(1.0, r);
    vec2 ox = vec2(rr * px.x, 0.0);
    vec2 oy = vec2(0.0, rr * px.y);
    vec2 od = vec2(rr * 0.70710678 * px.x, rr * 0.70710678 * px.y);

    float sigma = mix(0.015, 0.25, saturate(Detail_Threshold / 100.0));
    float sig2 = max(sigma * sigma, 1e-5);

    vec3 acc = c0;
    float wsum = 1.0;

    vec3 s;
    float w;

    s = src(uv + ox); w = exp(-dot(s - c0, s - c0) / sig2) * 0.90; acc += s * w; wsum += w;
    s = src(uv - ox); w = exp(-dot(s - c0, s - c0) / sig2) * 0.90; acc += s * w; wsum += w;
    s = src(uv + oy); w = exp(-dot(s - c0, s - c0) / sig2) * 0.90; acc += s * w; wsum += w;
    s = src(uv - oy); w = exp(-dot(s - c0, s - c0) / sig2) * 0.90; acc += s * w; wsum += w;

    s = src(uv + od); w = exp(-dot(s - c0, s - c0) / sig2) * 0.65; acc += s * w; wsum += w;
    s = src(uv - od); w = exp(-dot(s - c0, s - c0) / sig2) * 0.65; acc += s * w; wsum += w;
    s = src(uv + vec2( od.x, -od.y)); w = exp(-dot(s - c0, s - c0) / sig2) * 0.65; acc += s * w; wsum += w;
    s = src(uv + vec2(-od.x,  od.y)); w = exp(-dot(s - c0, s - c0) / sig2) * 0.65; acc += s * w; wsum += w;

    return acc / max(wsum, 1e-5);
}

// ----------------------------------------------------
// Cartoon fill / cel shading
// ----------------------------------------------------
vec3 cartoonFill(vec3 color) {
    float lum = luma(color);
    float steps = max(1.0, floor(Shading_Steps + 0.5));

    float scaled = lum * steps;
    float baseBand = floor(scaled);
    float fracBand = fract(scaled);

    float lo = baseBand / steps;
    float hi = min(baseBand + 1.0, steps) / steps;

    float smoothAmt = saturate(Shading_Smoothness / 100.0);
    float bandSoft = mix(0.001, 0.35, smoothAmt);
    float t = smoothstep(0.5 - bandSoft, 0.5 + bandSoft, fracBand);

    float targetLum = mix(lo, hi, t);
    float safeLum = max(lum, 1e-4);

    vec3 outCol = color * (targetLum / safeLum);

    float rgbSteps = max(2.0, steps * 0.8);
    vec3 poster = floor(outCol * rgbSteps + 0.5) / rgbSteps;
    outCol = mix(outCol, poster, 0.28);

    return clamp(outCol, 0.0, 1.0);
}

// ----------------------------------------------------
// Cheap edge detector (5 taps)
// ----------------------------------------------------
float edgeBase(vec2 uv) {
    vec2 px = 1.0 / resolution;

    float edgeDist = max(1.0, 1.0 + Detail_Radius * 0.18 + max(Edge_Enhancement, 0.0) * 0.35);
    vec2 dx = vec2(edgeDist * px.x, 0.0);
    vec2 dy = vec2(0.0, edgeDist * px.y);

    float lc = luma(src(uv));
    float ll = luma(src(uv - dx));
    float lr = luma(src(uv + dx));
    float lt = luma(src(uv + dy));
    float lb = luma(src(uv - dy));

    float gx = lr - ll;
    float gy = lt - lb;
    float g = length(vec2(gx, gy));

    float detailBias = mix(0.85, 1.75, saturate(Detail_Threshold / 100.0));
    float th = max(0.0001, Threshold * detailBias);

    float widthGain = 1.0 + Width * 0.7;

    float enh = Edge_Enhancement;
    float enhGain = 1.0 + max(enh, 0.0) * 0.25;
    float spread = 1.0 + max(-enh, 0.0) * 0.35;

    float e = g * widthGain * enhGain / spread;

    e = max(e - th * 0.08, 0.0) / (th * 0.55 + 0.06);

    float contrast = max(0.05, 1.0 + Edge_Contrast * 2.5);
    e = pow(max(e, 0.0), contrast);

    e *= mix(0.92, 1.08, saturate(abs(lc - 0.5) * 2.0));

    return saturate(e);
}

// ----------------------------------------------------
// Edge width + softness + black level
// Small 5-sample dilation
// ----------------------------------------------------
float finalEdge(vec2 uv) {
    vec2 px = 1.0 / resolution;

    float wpx = max(0.0, Width);
    vec2 ox = vec2(wpx * px.x, 0.0);
    vec2 oy = vec2(0.0, wpx * px.y);

    float e0 = edgeBase(uv);
    float e1 = edgeBase(uv + ox);
    float e2 = edgeBase(uv - ox);
    float e3 = edgeBase(uv + oy);
    float e4 = edgeBase(uv - oy);

    float eMax = max(e0, max(e1, max(e2, max(e3, e4))));
    float eAvg = (e0 + e1 + e2 + e3 + e4) / 5.0;

    float soft = saturate(Softness / 100.0);
    float edge = mix(eMax, eAvg, soft);

    edge += Edge_Black_Level * 0.18;
    edge = saturate(edge);

    return edge;
}

void main() {
    vec2 uv = vUvScaled;

    vec3 smoothed = fastSmooth(uv);
    vec3 fillColor = cartoonFill(smoothed);

    float edgeMask = finalEdge(uv);
    float edgeOpacity = saturate(Opacity / 100.0);

    vec3 edgesOnly = vec3(1.0 - edgeMask * edgeOpacity);
    vec3 fillAndEdges = mix(fillColor, vec3(0.0), edgeMask * edgeOpacity);

    float mode = floor(Render + 0.5);

    vec3 outCol;
    if (mode < 0.5) {
        outCol = fillColor;
    } else if (mode < 1.5) {
        outCol = edgesOnly;
    } else {
        outCol = fillAndEdges;
    }

    gl_FragColor = vec4(outCol, 1.0);
}

text./plugins/alipfx/shaders/change-color.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/*
Panzoid custom properties required:

1. View                     -> Number (dynamic)
2. Hue Transform            -> Number (dynamic)
3. Saturation Transform     -> Number (dynamic)
4. Lightness Transform      -> Number (dynamic)
5. Color To Change          -> Color
6. Matching Tolerance       -> Number (dynamic)
7. Matching Softness        -> Number (dynamic)
8. Match Colors             -> Number (dynamic)
9. Invert Color Correction  -> Number (dynamic)

Panzoid converts spaces to underscores in GLSL:
View -> View
Hue Transform -> Hue_Transform
Saturation Transform -> Saturation_Transform
Lightness Transform -> Lightness_Transform
Color To Change -> Color_To_Change
Matching Tolerance -> Matching_Tolerance
Matching Softness -> Matching_Softness
Match Colors -> Match_Colors
Invert Color Correction -> Invert_Color_Correction
*/

uniform float View;
uniform float Hue_Transform;
uniform float Saturation_Transform;
uniform float Lightness_Transform;
uniform vec3  Color_To_Change;
uniform float Matching_Tolerance;
uniform float Matching_Softness;
uniform float Match_Colors;
uniform float Invert_Color_Correction;

const float PI  = 3.14159265358979323846;
const float TAU = 6.28318530717958647692;
const float EPS = 1e-6;

// --------------------------------------------------
// Utility
// --------------------------------------------------

float saturate(float x) {
    return clamp(x, 0.0, 1.0);
}

float hueDist(float a, float b) {
    float d = abs(a - b);
    return min(d, 1.0 - d); // 0..0.5
}

// --------------------------------------------------
// RGB <-> HSL
// --------------------------------------------------

vec3 rgb2hsl(vec3 c) {
    float maxc = max(c.r, max(c.g, c.b));
    float minc = min(c.r, min(c.g, c.b));
    float delta = maxc - minc;

    float h = 0.0;
    float s = 0.0;
    float l = 0.5 * (maxc + minc);

    if (delta > EPS) {
        s = delta / (1.0 - abs(2.0 * l - 1.0));

        if (maxc == c.r) {
            h = mod((c.g - c.b) / delta, 6.0);
        } else if (maxc == c.g) {
            h = ((c.b - c.r) / delta) + 2.0;
        } else {
            h = ((c.r - c.g) / delta) + 4.0;
        }

        h /= 6.0;
        if (h < 0.0) h += 1.0;
    }

    return vec3(h, s, l);
}

float hue2rgb(float p, float q, float t) {
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;
    if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
    if (t < 1.0/2.0) return q;
    if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
    return p;
}

vec3 hsl2rgb(vec3 hsl) {
    float h = hsl.x;
    float s = hsl.y;
    float l = hsl.z;

    if (s <= EPS) {
        return vec3(l);
    }

    float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
    float p = 2.0 * l - q;

    return vec3(
        hue2rgb(p, q, h + 1.0/3.0),
        hue2rgb(p, q, h),
        hue2rgb(p, q, h - 1.0/3.0)
    );
}

// --------------------------------------------------
// Matching spaces
// --------------------------------------------------

// Chroma vector in polar hue/saturation space.
// This ignores lightness and keeps hue+sat only.
vec2 chromaVec(vec3 rgb) {
    vec3 hsl = rgb2hsl(rgb);
    float a = hsl.x * TAU;
    return vec2(cos(a), sin(a)) * hsl.y;
}

// RGB match: precise RGB triplet comparison.
float rgbDistance01(vec3 a, vec3 b) {
    // normalized to approximately 0..1
    return length(a - b) / 1.73205080757;
}

// Hue-only match: compare hue, reduce false hits on near-gray pixels.
float hueDistance01(vec3 a, vec3 b) {
    vec3 ahsl = rgb2hsl(a);
    vec3 bhsl = rgb2hsl(b);

    // If source/target is nearly grayscale, hue is weakly defined.
    float d = hueDist(ahsl.x, bhsl.x) * 2.0; // 0..1
    float satGate = max(ahsl.y, bhsl.y);
    // For very low saturation, make match weaker / less aggressive.
    d = mix(1.0, d, smoothstep(0.02, 0.10, satGate));
    return d;
}

// Chroma match: compare hue+saturation, ignore lightness.
float chromaDistance01(vec3 a, vec3 b) {
    vec2 ca = chromaVec(a);
    vec2 cb = chromaVec(b);
    return length(ca - cb) * 0.5; // roughly normalize to 0..1
}

// --------------------------------------------------
// AE-like soft mask
// --------------------------------------------------

float selectionMask(vec3 src, vec3 target, float mode, float tolPct, float softPct) {
    float d;

    if (mode < 0.5) {
        // 0 = Using RGB
        d = rgbDistance01(src, target);
    } else if (mode < 1.5) {
        // 1 = Using Hue
        d = hueDistance01(src, target);
    } else {
        // 2 = Using Chroma
        d = chromaDistance01(src, target);
    }

    float tol  = clamp(tolPct  / 100.0, 0.0, 1.0);
    float soft = clamp(softPct / 100.0, 0.0, 1.0);

    // AE-like idea:
    // - tolerance defines the fully selected core
    // - softness feathers outward from the tolerance edge
    float edge0 = tol;
    float edge1 = min(1.0, tol + max(soft, 0.00001));

    float m;
    if (soft <= 0.00001) {
        m = (d <= tol) ? 1.0 : 0.0;
    } else {
        m = 1.0 - smoothstep(edge0, edge1, d);
    }

    return saturate(m);
}

// --------------------------------------------------
// Color transform
// --------------------------------------------------

// This version is tuned to feel like AE's Change Color UI/screenshots:
// - Hue Transform: degrees, additive
// - Saturation Transform: signed percentage, additive in HSL saturation
// - Lightness Transform: signed percentage, additive in HSL lightness
//
// Neutral values:
// - Hue Transform = 0
// - Saturation Transform = 0
// - Lightness Transform = 0
vec3 applyChangeColor(vec3 rgb) {
    vec3 hsl = rgb2hsl(rgb);

    hsl.x = fract(hsl.x + Hue_Transform / 360.0);
    hsl.y = clamp(hsl.y + Saturation_Transform / 100.0, 0.0, 1.0);
    hsl.z = clamp(hsl.z + Lightness_Transform / 100.0, 0.0, 1.0);

    return hsl2rgb(hsl);
}

// --------------------------------------------------
// Main
// --------------------------------------------------

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 src = texel.rgb;

    float mask = selectionMask(
        src,
        Color_To_Change,
        Match_Colors,
        Matching_Tolerance,
        Matching_Softness
    );

    if (Invert_Color_Correction >= 0.5) {
        mask = 1.0 - mask;
    }

    vec3 changed = applyChangeColor(src);
    vec3 result  = mix(src, changed, mask);

    // View:
    // 0 = Corrected Layer (final processed result)
    // 1 = Color Correction Mask (diagnostic matte)
    if (View < 0.5) {
        gl_FragColor = vec4(result, texel.a);
    } else {
        gl_FragColor = vec4(vec3(mask), texel.a);
    }
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform vec3 From;
uniform vec3 To;

uniform float Change;
uniform float Change_By;
uniform float Hue;
uniform float Lightness;
uniform float Saturation;
uniform float Softness;
uniform float View_Correction_Matte;

float sat1(float x)
{
  return clamp(x, 0.0, 1.0);
}

vec3 sat3(vec3 x)
{
  return clamp(x, 0.0, 1.0);
}

float max3(float a, float b, float c)
{
  return max(a, max(b, c));
}

float colorDiffMax(vec3 a, vec3 b)
{
  vec3 d = abs(a - b);
  return max3(d.r, d.g, d.b);
}

float luma709(vec3 c)
{
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

float hueWrap(float h)
{
  return fract(h + 1.0);
}

float shortestHueDelta(float a, float b)
{
  float d = b - a;
  if (d > 0.5) d -= 1.0;
  if (d < -0.5) d += 1.0;
  return d;
}

float hueDistance01(float a, float b)
{
  float d = abs(a - b);
  d = min(d, 1.0 - d);
  return d * 2.0;
}

vec3 rgb2hsl(vec3 c)
{
  float maxc = max(c.r, max(c.g, c.b));
  float minc = min(c.r, min(c.g, c.b));
  float h = 0.0;
  float s = 0.0;
  float l = 0.5 * (maxc + minc);
  float d = maxc - minc;

  if (d > 1e-6)
  {
    s = d / (1.0 - abs(2.0 * l - 1.0));

    if (maxc == c.r)
    {
      h = mod((c.g - c.b) / d, 6.0);
    }
    else if (maxc == c.g)
    {
      h = ((c.b - c.r) / d) + 2.0;
    }
    else
    {
      h = ((c.r - c.g) / d) + 4.0;
    }

    h /= 6.0;
    if (h < 0.0) h += 1.0;
  }

  return vec3(h, s, l);
}

float hue2rgb(float p, float q, float t)
{
  if (t < 0.0) t += 1.0;
  if (t > 1.0) t -= 1.0;
  if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
  if (t < 1.0 / 2.0) return q;
  if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
  return p;
}

vec3 hsl2rgb(vec3 hsl)
{
  float h = hsl.x;
  float s = hsl.y;
  float l = hsl.z;

  if (s <= 1e-6)
  {
    return vec3(l);
  }

  float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
  float p = 2.0 * l - q;

  return vec3(
    hue2rgb(p, q, h + 1.0 / 3.0),
    hue2rgb(p, q, h),
    hue2rgb(p, q, h - 1.0 / 3.0)
  );
}

float featherMask(float dist, float tol, float softness)
{
  tol = sat1(tol);
  softness = sat1(softness);

  // Percent-based softness:
  // 0%  = almost hard edge
  // 100% = very wide feather
  float feather = max(0.0001, softness);

  if (dist <= tol) return 1.0;
  if (dist >= tol + feather) return 0.0;

  return 1.0 - smoothstep(tol, tol + feather, dist);
}

float computeHueMask(vec3 pxHSL, vec3 fromHSL, float hueTol, float softness)
{
  float d = hueDistance01(pxHSL.x, fromHSL.x);
  float base = featherMask(d, hueTol, softness);

  // Hue is unreliable for very low saturation colors.
  // Instead of forcing full match, softly reduce its authority.
  float reliability = smoothstep(0.02, 0.15, max(pxHSL.y, fromHSL.y));
  return mix(0.5 + 0.5 * base, base, reliability);
}

float computeLightMask(vec3 pxHSL, vec3 fromHSL, float lightTol, float softness)
{
  float d = abs(pxHSL.z - fromHSL.z);
  return featherMask(d, lightTol, softness);
}

float computeSatMask(vec3 pxHSL, vec3 fromHSL, float satTol, float softness)
{
  float d = abs(pxHSL.y - fromHSL.y);
  return featherMask(d, satTol, softness);
}

vec3 preserveLuma(vec3 srcRGB, vec3 dstRGB)
{
  float srcL = luma709(srcRGB);
  float dstL = luma709(dstRGB);

  if (dstL < 1e-5)
  {
    return dstRGB;
  }

  vec3 scaled = dstRGB * (srcL / dstL);
  return sat3(mix(dstRGB, scaled, 0.85));
}

bool effectIsNoOp(vec3 fromHSL, vec3 toHSL, int changeMode, int changeByMode)
{
  // If RGB colors are nearly identical, effect should do nothing.
  if (colorDiffMax(From, To) < 0.001)
  {
    return true;
  }

  float hueDelta = abs(shortestHueDelta(fromHSL.x, toHSL.x));
  float satDelta = abs(fromHSL.y - toHSL.y);
  float ligDelta = abs(fromHSL.z - toHSL.z);

  // Hue-only with achromatic destination should not invent hue.
  if (changeByMode == 0 && changeMode == 0 && toHSL.y < 0.001)
  {
    return true;
  }

  // General mode-based no-op detection
  if (changeMode == 0)
  {
    return hueDelta < 0.0005;
  }
  else if (changeMode == 1)
  {
    return hueDelta < 0.0005 && ligDelta < 0.0005;
  }
  else if (changeMode == 2)
  {
    return hueDelta < 0.0005 && satDelta < 0.0005;
  }
  else
  {
    return hueDelta < 0.0005 && satDelta < 0.0005 && ligDelta < 0.0005;
  }
}

vec3 applySetToColor(vec3 pxHSL, vec3 toHSL, int changeMode)
{
  vec3 outHSL = pxHSL;

  if (changeMode == 0)
  {
    // Hue
    // If target is achromatic, hue should not be forced.
    if (toHSL.y > 0.001)
    {
      outHSL.x = toHSL.x;
    }
  }
  else if (changeMode == 1)
  {
    // Hue & Lightness
    if (toHSL.y > 0.001)
    {
      outHSL.x = toHSL.x;
    }
    outHSL.z = toHSL.z;
  }
  else if (changeMode == 2)
  {
    // Hue & Saturation
    if (toHSL.y > 0.001)
    {
      outHSL.x = toHSL.x;
    }
    outHSL.y = toHSL.y;
  }
  else
  {
    // Hue, Lightness & Saturation
    // Full replacement is allowed here
    outHSL = toHSL;
  }

  outHSL.x = hueWrap(outHSL.x);
  outHSL.y = sat1(outHSL.y);
  outHSL.z = sat1(outHSL.z);

  return outHSL;
}

vec3 applyTransformToColor(vec3 pxHSL, vec3 fromHSL, vec3 toHSL, int changeMode)
{
  vec3 outHSL = pxHSL;

  float dHue = shortestHueDelta(fromHSL.x, toHSL.x);
  float dSat = toHSL.y - fromHSL.y;
  float dLig = toHSL.z - fromHSL.z;

  if (changeMode == 0)
  {
    if (fromHSL.y > 0.001 && toHSL.y > 0.001)
    {
      outHSL.x = hueWrap(pxHSL.x + dHue);
    }
  }
  else if (changeMode == 1)
  {
    if (fromHSL.y > 0.001 && toHSL.y > 0.001)
    {
      outHSL.x = hueWrap(pxHSL.x + dHue);
    }
    outHSL.z = sat1(pxHSL.z + dLig);
  }
  else if (changeMode == 2)
  {
    if (fromHSL.y > 0.001 && toHSL.y > 0.001)
    {
      outHSL.x = hueWrap(pxHSL.x + dHue);
    }
    outHSL.y = sat1(pxHSL.y + dSat);
  }
  else
  {
    if (fromHSL.y > 0.001 && toHSL.y > 0.001)
    {
      outHSL.x = hueWrap(pxHSL.x + dHue);
    }
    outHSL.y = sat1(pxHSL.y + dSat);
    outHSL.z = sat1(pxHSL.z + dLig);
  }

  return outHSL;
}

void main()
{
  vec4 src = texture2D(tDiffuse, vUvScaled);

  vec3 pxRGB = src.rgb;
  vec3 pxHSL = rgb2hsl(pxRGB);
  vec3 fromHSL = rgb2hsl(From);
  vec3 toHSL = rgb2hsl(To);

  int changeMode = int(floor(Change + 0.5));
  int changeByMode = int(floor(Change_By + 0.5));

  // HARD SAFETY: true no-op on default / identical colors
  if (effectIsNoOp(fromHSL, toHSL, changeMode, changeByMode))
  {
    if (View_Correction_Matte >= 0.5)
    {
      gl_FragColor = vec4(0.0, 0.0, 0.0, src.a);
    }
    else
    {
      gl_FragColor = src;
    }
    return;
  }

  // 0..100% controls
  float hueTol  = sat1(Hue / 100.0);
  float ligTol  = sat1(Lightness / 100.0);
  float satTol  = sat1(Saturation / 100.0);
  float softAmt = sat1(Softness / 100.0);

  float mHue = computeHueMask(pxHSL, fromHSL, hueTol, softAmt);
  float mLig = computeLightMask(pxHSL, fromHSL, ligTol, softAmt);
  float mSat = computeSatMask(pxHSL, fromHSL, satTol, softAmt);

  float matte = pow(sat1(mHue * mLig * mSat), mix(1.25, 0.75, softAmt));
  matte = sat1(matte);

  vec3 outHSL;

  if (changeByMode == 0)
  {
    outHSL = applySetToColor(pxHSL, toHSL, changeMode);
  }
  else
  {
    outHSL = applyTransformToColor(pxHSL, fromHSL, toHSL, changeMode);
  }

  vec3 changedRGB = hsl2rgb(outHSL);

  if (changeMode == 0 || changeMode == 2)
  {
    changedRGB = preserveLuma(pxRGB, changedRGB);
  }

  vec3 finalRGB = mix(pxRGB, changedRGB, matte);

  if (View_Correction_Matte >= 0.5)
  {
    gl_FragColor = vec4(vec3(matte), src.a);
  }
  else
  {
    gl_FragColor = vec4(sat3(finalRGB), src.a);
  }
}

text./plugins/alipfx/shaders/channel-mixer.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// =====================================================
// AE-style Channel Mixer controls (dynamic Number props)
// =====================================================
// Recommended Panzoid property names exactly as below:
//
// Red_Red
// Red_Green
// Red_Blue
// Red_Const
//
// Green_Red
// Green_Green
// Green_Blue
// Green_Const
//
// Blue_Red
// Blue_Green
// Blue_Blue
// Blue_Const
//
// Monochrome
//
// Use Number (dynamic) for all.
// Percent-style values: usually range -200 to 200.
// Monochrome: 0 = off, 1 = on.
// =====================================================

uniform float Red_Red;
uniform float Red_Green;
uniform float Red_Blue;
uniform float Red_Const;

uniform float Green_Red;
uniform float Green_Green;
uniform float Green_Blue;
uniform float Green_Const;

uniform float Blue_Red;
uniform float Blue_Green;
uniform float Blue_Blue;
uniform float Blue_Const;

uniform float Monochrome;

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);
  vec3 src = texel.rgb;

  // Convert AE-style percentage sliders to normalized multipliers
  float rr = Red_Red      / 100.0;
  float rg = Red_Green    / 100.0;
  float rb = Red_Blue     / 100.0;
  float rc = Red_Const    / 100.0;

  float gr = Green_Red    / 100.0;
  float gg = Green_Green  / 100.0;
  float gb = Green_Blue   / 100.0;
  float gc = Green_Const  / 100.0;

  float br = Blue_Red     / 100.0;
  float bg = Blue_Green   / 100.0;
  float bb = Blue_Blue    / 100.0;
  float bc = Blue_Const   / 100.0;

  vec3 outRGB;

  // AE-style Monochrome:
  // Uses the RED output row as the grayscale mixer and replicates it to RGB.
  if (Monochrome >= 0.5)
  {
    float mono = src.r * rr + src.g * rg + src.b * rb + rc;
    mono = clamp(mono, 0.0, 1.0);
    outRGB = vec3(mono);
  }
  else
  {
    float outR = src.r * rr + src.g * rg + src.b * rb + rc;
    float outG = src.r * gr + src.g * gg + src.b * gb + gc;
    float outB = src.r * br + src.g * bg + src.b * bb + bc;

    outRGB = clamp(vec3(outR, outG, outB), 0.0, 1.0);
  }

  gl_FragColor = vec4(outRGB, texel.a);
}

text./plugins/alipfx/shaders/checkerboard.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

uniform vec2 Anchor;
uniform int Size_from;
uniform vec2 Corner_Point;
uniform float Width;
uniform float Height;
uniform float Feather_Width;
uniform float Feather_Height;
uniform vec3 Color;
uniform float Opacity;
uniform int Blending_mode;

varying vec2 vUvScaled;

// Convert RGB to HSL
vec3 rgbToHsl(vec3 color) {
    float maxC = max(max(color.r, color.g), color.b);
    float minC = min(min(color.r, color.g), color.b);
    float delta = maxC - minC;

    float h = 0.0;
    if (delta > 0.0) {
        if (maxC == color.r) {
            h = mod((color.g - color.b) / delta, 6.0);
        } else if (maxC == color.g) {
            h = (color.b - color.r) / delta + 2.0;
        } else {
            h = (color.r - color.g) / delta + 4.0;
        }
        h /= 6.0;
    }
    float l = (maxC + minC) * 0.5;
    float s = (delta == 0.0) ? 0.0 : delta / (1.0 - abs(2.0 * l - 1.0));
    return vec3(h, s, l);
}

// Convert HSL to RGB
vec3 hslToRgb(vec3 hsl) {
    float h = hsl.x;
    float s = hsl.y;
    float l = hsl.z;

    float c = (1.0 - abs(2.0 * l - 1.0)) * s;
    float x = c * (1.0 - abs(mod(h * 6.0, 2.0) - 1.0));
    float m = l - c / 2.0;

    vec3 rgb;
    if (h < 1.0/6.0) rgb = vec3(c, x, 0.0);
    else if (h < 2.0/6.0) rgb = vec3(x, c, 0.0);
    else if (h < 3.0/6.0) rgb = vec3(0.0, c, x);
    else if (h < 4.0/6.0) rgb = vec3(0.0, x, c);
    else if (h < 5.0/6.0) rgb = vec3(x, 0.0, c);
    else rgb = vec3(c, 0.0, x);

    return rgb + m;
}

// Blending modes
vec4 blendModes(vec4 base, vec4 blend, int mode) {
    if (mode == 0) return blend; // None
    if (mode == 1) return mix(base, blend, blend.a); // Normal
    if (mode == 2) return vec4(blend.rgb * base.a, base.a); // Stencil Alpha
    if (mode == 3) return base + blend; // Add
    if (mode == 4) return base * blend; // Multiply
    if (mode == 5) return 1.0 - (1.0 - base) * (1.0 - blend); // Screen
    if (mode == 6) return mix(2.0 * base * blend, 1.0 - 2.0 * (1.0 - base) * (1.0 - blend), step(0.5, base.r)); // Overlay
    if (mode == 7) return mix(2.0 * blend * base, base + blend - 2.0 * base * blend, step(0.5, blend.r)); // Soft Light
    if (mode == 8) return mix(2.0 * base * blend, base + blend - 2.0 * base * blend, step(0.5, base.r)); // Hard Light
    if (mode == 9) return base / (1.0 - blend); // Color Dodge
    if (mode == 10) return 1.0 - (1.0 - base) / blend; // Color Burn
    if (mode == 11) return min(base, blend); // Darken
    if (mode == 12) return max(base, blend); // Lighten
    if (mode == 13) return abs(base - blend); // Difference
    if (mode == 14) return base + blend - 2.0 * base * blend; // Exclusion

    // Advanced HSL-based modes
    vec3 baseHSL = rgbToHsl(base.rgb);
    vec3 blendHSL = rgbToHsl(blend.rgb);

    if (mode == 15) return vec4(hslToRgb(vec3(blendHSL.x, baseHSL.y, baseHSL.z)), base.a); // Hue
    if (mode == 16) return vec4(hslToRgb(vec3(baseHSL.x, blendHSL.y, baseHSL.z)), base.a); // Saturation
    if (mode == 17) return vec4(hslToRgb(vec3(blendHSL.x, blendHSL.y, baseHSL.z)), base.a); // Color
    if (mode == 18) return vec4(hslToRgb(vec3(baseHSL.x, baseHSL.y, blendHSL.z)), base.a); // Luminosity

    return blend;
}

void main() {
    vec2 uv = vUvScaled;

    float cellWidth = max(Width, 1.0);
    float cellHeight = (Size_from == 2) ? max(Height, 1.0) : cellWidth;

    if (Size_from == 0) {
        cellWidth = max(abs(Corner_Point.x - Anchor.x), 1.0);
        cellHeight = max(abs(Corner_Point.y - Anchor.y), 1.0);
    }

    float xIndex = floor((uv.x * resolution.x - Anchor.x) / cellWidth);
    float yIndex = floor((uv.y * resolution.y - Anchor.y) / cellHeight);
    float checker = mod(xIndex + yIndex, 2.0);

    // Correct feather logic (soften edges without shrinking)
    float edgeX = abs(fract((uv.x * resolution.x - Anchor.x) / cellWidth) - 0.5);
    float edgeY = abs(fract((uv.y * resolution.y - Anchor.y) / cellHeight) - 0.5);

    float fx = 1.0 - smoothstep(0.5 - 0.01 * Feather_Width, 0.5, edgeX);
    float fy = 1.0 - smoothstep(0.5 - 0.01 * Feather_Height, 0.5, edgeY);
    float feather = fx * fy;

    vec4 baseTexel = texture2D(tDiffuse, uv);
    vec4 checkerColor = vec4(Color, Opacity) * (checker < 1.0 ? 1.0 : 0.0);

    if (Feather_Width > 0.0 || Feather_Height > 0.0) {
        checkerColor *= feather; // Apply softness without shrinking
    }

    if (Blending_mode == 0) {
        gl_FragColor = checkerColor;
        return;
    }

    gl_FragColor = blendModes(baseTexel, checkerColor, Blending_mode);
}

text./plugins/alipfx/shaders/chromabba.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// IMPORTANT: Ensure your UI properties perfectly match these names!
uniform float Samples;
uniform float Strength;
uniform float Separation;
uniform float Edge_Attraction_Power;
uniform float Direction;
uniform float Edge_Mode;

const int MAX_SAMPLES = 64;
const float EPS = 1e-5;

// ------------------------------------------------------------
// Edge handling
// ------------------------------------------------------------
float mirrorCoord(float x)
{
    float m = mod(x, 2.0);
    if (m < 0.0) m += 2.0;
    return 1.0 - abs(m - 1.0);
}

vec2 applyEdgeMode(vec2 uv, out float valid)
{
    valid = 1.0;

    if (Edge_Mode < 0.5)
    {
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)
        {
            valid = 0.0;
        }
        return clamp(uv, 0.0, 1.0); 
    }
    else if (Edge_Mode < 1.5)
    {
        return vec2(mirrorCoord(uv.x), mirrorCoord(uv.y));
    }
    else if (Edge_Mode < 2.5)
    {
        return clamp(uv, 0.0, 1.0);
    }
    else
    {
        return fract(uv);
    }
}

vec4 sampleSource(vec2 uv)
{
    float valid;
    vec2 eUv = applyEdgeMode(uv, valid);

    vec4 c = texture2D(tDiffuse, eUv * uvScale);

    if (Edge_Mode < 0.5)
    {
        c *= valid;
    }

    return c;
}

// ------------------------------------------------------------
// Edge-attraction curve
// ------------------------------------------------------------
float edgeCurveFromRadius(float radius01)
{
    // A pure power function.
    // At 1.0, it is a linear slope (giving that fisheye/tunnel feel).
    // At higher values, it keeps the center untouched and curves up violently at the edges.
    return pow(radius01, max(Edge_Attraction_Power, 0.001));
}

// ------------------------------------------------------------
// Vector computation
// ------------------------------------------------------------
// Replaces the old 'getChromaticOffsets' to handle both blur distance AND color separation
void getVectors(
    vec2 uv, 
    out vec2 blurVec, 
    out vec2 redVec, 
    out vec2 blueVec
) {
    vec2 center = vec2(0.5, 0.5);
    vec2 deltaPx = (uv - center) * resolution;
    float distPx = length(deltaPx);
    vec2 dirPx = (distPx > EPS) ? (deltaPx / distPx) : vec2(1.0, 0.0);

    float maxDistPx = length(0.5 * resolution);
    float radius01 = (maxDistPx > EPS) ? clamp(distPx / maxDistPx, 0.0, 1.0) : 0.0;

    float edgeCurve = edgeCurveFromRadius(radius01);

    // STRENGTH: Controls the total span/length of the radial displacement
    float basePx = Strength * edgeCurve;

    // SEPARATION: Controls how far the color channels split apart.
    // We scale it by Strength so they work together exactly as you requested.
    float sepPx = (Separation / 100.0) * Strength * edgeCurve;

    vec2 baseUv = (dirPx * basePx) / resolution;
    vec2 sepUv = (dirPx * sepPx) / resolution;

    float mode = floor(Direction + 0.5);

    // Apply directional vectors
    if (mode < 0.5) // Inward
    {
        blurVec = baseUv; 
        redVec = sepUv * 0.5;
        blueVec = -sepUv * 0.5;
    }
    else if (mode < 1.5) // Outward
    {
        blurVec = -baseUv; 
        redVec = -sepUv * 0.5;
        blueVec = sepUv * 0.5;
    }
    else // Both
    {
        blurVec = baseUv; 
        redVec = sepUv * 0.5;
        blueVec = -sepUv * 0.5;
    }
}

// ------------------------------------------------------------
// Main
// ------------------------------------------------------------
void main()
{
    vec2 uv = vUv;
    vec4 base = sampleSource(uv);

    float sCount = clamp(floor(Samples + 0.5), 1.0, float(MAX_SAMPLES));

    // If there is no effect to apply, return base pixel
    if (Strength <= 0.0 && Separation <= 0.0)
    {
        gl_FragColor = base;
        return;
    }

    vec2 blurVec;
    vec2 redVec;
    vec2 blueVec;
    getVectors(uv, blurVec, redVec, blueVec);

    float sumR = 0.0;
    float sumG = 0.0;
    float sumB = 0.0;
    float sumA = 0.0;
    float sumW = 0.0;

    float mode = floor(Direction + 0.5);

    // THE FIX: Direct color channel sampling. 
    // The loop iterates exactly "Samples" times along the displacement vector.
    for (int i = 0; i < MAX_SAMPLES; i++)
    {
        if (float(i) >= sCount) break;

        float t = 0.0;
        if (sCount > 1.0) {
            t = float(i) / (sCount - 1.0); // Progress from 0.0 to 1.0
        }

        float shift = 0.0;
        float w = 1.0;

        if (mode < 0.5) {
            shift = t; // Inward
        } else if (mode < 1.5) {
            shift = t; // Outward (vector was already inverted in getVectors)
        } else {
            shift = (t * 2.0) - 1.0; // Both (from -1.0 to 1.0)
            w = 1.0 - abs(shift); // Center weighted fading
            w = max(w, 0.001);
        }

        // 1. Find the position along the overall Strength streak
        vec2 samplePos = uv + blurVec * shift;

        // 2. Apply the specific color channel Separation relative to that point
        vec2 rPos = samplePos + redVec;
        vec2 gPos = samplePos; 
        vec2 bPos = samplePos + blueVec;

        // 3. Sample the channels
        vec4 cR = sampleSource(rPos);
        vec4 cG = sampleSource(gPos);
        vec4 cB = sampleSource(bPos);

        sumR += cR.r * w;
        sumG += cG.g * w;
        sumB += cB.b * w;
        sumA += max(max(cR.a, cG.a), cB.a) * w;
        sumW += w;
    }

    vec4 outCol = vec4(sumR, sumG, sumB, sumA) / sumW;

    if (Edge_Mode >= 0.5)
    {
        outCol.a = max(outCol.a, base.a);
    }

    gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/circle.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

// ----- Custom properties -----
uniform vec2 Center;                 // pixels, AE-style (0,0) top-left
uniform float Radius;                // pixels
uniform float Edge;                  // 0..4
uniform float Edge_Radius;           // pixels (USED ONLY IN EDGE MODE 1)
uniform float Thickness;             // pixels (mode 2), ratio (modes 3/4)
uniform float Feather_Outer_Edge;    // pixels (modes 0..3), ratio (mode 4)
uniform float Feather_Inner_Edge;    // pixels (modes 0..3), ratio (mode 4)
uniform float Invert_Circle;         // 0/1
uniform vec3 Color;                  // 0..1
uniform float Opacity;               // 0..100
uniform float Blending_Mode;         // 0..18

// ---------------- Utility ----------------
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec3  sat3(vec3 v) { return clamp(v, 0.0, 1.0); }

// Convert vUvScaled -> normalized 0..1 UV
vec2 unscaledUv()
{
  return vUvScaled / uvScale;
}

// AE uses top-left origin; GLSL UV uses bottom-left.
// Convert AE pixel center to GLSL pixel space.
vec2 aeCenterToGL(vec2 cPx)
{
  return vec2(cPx.x, resolution.y - cPx.y);
}

// Derivative-free antialias width in pixel-distance space.
float aaPx()
{
  return 1.0;
}

// Ring/fill mask with independent inner/outer feathering (derivative-free)
float ringMask(float distPx, float innerR, float outerR, float featherInnerPx, float featherOuterPx)
{
  float aa = aaPx();

  float fi = max(featherInnerPx, 0.0);
  float fo = max(featherOuterPx, 0.0);

  // Outer edge: 1 inside, fades to 0 outside
  float mOuter = 1.0 - smoothstep(outerR - aa, outerR + fo + aa, distPx);

  // Inner edge:
  // IMPORTANT FIX: if innerR <= 0, treat as solid fill (AE behavior).
  float mInner = 1.0;
  if (innerR > 0.0)
  {
    mInner = smoothstep(innerR - fi - aa, innerR + aa, distPx);
  }

  return sat(mOuter * mInner);
}

// ---------------- HSL for Hue/Sat/Color/Luminosity ----------------
vec3 rgb2hsl(vec3 c)
{
  float maxc = max(max(c.r, c.g), c.b);
  float minc = min(min(c.r, c.g), c.b);
  float l = (maxc + minc) * 0.5;
  float s = 0.0;
  float h = 0.0;

  float d = maxc - minc;
  if (d > 1e-6)
  {
    s = (l > 0.5) ? d / (2.0 - maxc - minc) : d / (maxc + minc);

    if (maxc == c.r)      h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0);
    else if (maxc == c.g) h = (c.b - c.r) / d + 2.0;
    else                  h = (c.r - c.g) / d + 4.0;

    h /= 6.0;
  }
  return vec3(h, s, l);
}

float hue2rgb(float p, float q, float t)
{
  if (t < 0.0) t += 1.0;
  if (t > 1.0) t -= 1.0;
  if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
  if (t < 1.0/2.0) return q;
  if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
  return p;
}

vec3 hsl2rgb(vec3 hsl)
{
  float h = hsl.x;
  float s = hsl.y;
  float l = hsl.z;

  float r, g, b;

  if (s < 1e-6)
  {
    r = g = b = l;
  }
  else
  {
    float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
    float p = 2.0 * l - q;
    r = hue2rgb(p, q, h + 1.0/3.0);
    g = hue2rgb(p, q, h);
    b = hue2rgb(p, q, h - 1.0/3.0);
  }
  return vec3(r, g, b);
}

// ---------------- Blend functions ----------------
vec3 blendOverlay(vec3 b, vec3 s)
{
  return mix(2.0*b*s, 1.0 - 2.0*(1.0-b)*(1.0-s), step(0.5, b));
}

vec3 blendHardLight(vec3 b, vec3 s)
{
  return mix(2.0*b*s, 1.0 - 2.0*(1.0-b)*(1.0-s), step(0.5, s));
}

vec3 blendSoftLight(vec3 b, vec3 s)
{
  return (1.0 - 2.0*s) * b*b + 2.0*s*b;
}

vec3 blendColorDodge(vec3 b, vec3 s)
{
  vec3 denom = max(vec3(1.0) - s, vec3(1e-6));
  return sat3(b / denom);
}

vec3 blendColorBurn(vec3 b, vec3 s)
{
  vec3 denom = max(s, vec3(1e-6));
  return sat3(1.0 - (1.0 - b) / denom);
}

vec3 applyBlendMode(vec3 base, vec3 src, int mode)
{
  if (mode == 0 || mode == 1) return src;                         // None/Normal
  if (mode == 3)  return sat3(base + src);                        // Add
  if (mode == 4)  return base * src;                              // Multiply
  if (mode == 5)  return 1.0 - (1.0-base)*(1.0-src);              // Screen
  if (mode == 6)  return blendOverlay(base, src);                 // Overlay
  if (mode == 7)  return blendSoftLight(base, src);               // Soft Light
  if (mode == 8)  return blendHardLight(base, src);               // Hard Light
  if (mode == 9)  return blendColorDodge(base, src);              // Color Dodge
  if (mode == 10) return blendColorBurn(base, src);               // Color Burn
  if (mode == 11) return min(base, src);                          // Darken
  if (mode == 12) return max(base, src);                          // Lighten
  if (mode == 13) return abs(base - src);                         // Difference
  if (mode == 14) return base + src - 2.0*base*src;               // Exclusion

  vec3 hb = rgb2hsl(base);
  vec3 hs = rgb2hsl(src);

  if (mode == 15) return hsl2rgb(vec3(hs.x, hb.y, hb.z));         // Hue
  if (mode == 16) return hsl2rgb(vec3(hb.x, hs.y, hb.z));         // Saturation
  if (mode == 17) return hsl2rgb(vec3(hs.x, hs.y, hb.z));         // Color
  if (mode == 18) return hsl2rgb(vec3(hb.x, hb.y, hs.z));         // Luminosity

  return src;
}

void main()
{
  vec4 base = texture2D(tDiffuse, vUvScaled);

  vec2 uv = unscaledUv();
  vec2 pPx = uv * resolution;

  vec2 cPx = aeCenterToGL(Center);
  float distPx = length(pPx - cPx);

  float R = max(Radius, 0.0);
  int edgeMode = int(floor(Edge + 0.5));
  int blendMode = int(floor(Blending_Mode + 0.5));
  float inv = step(0.5, Invert_Circle);

  // Feather values
  float fOuterPx = max(Feather_Outer_Edge, 0.0);
  float fInnerPx = max(Feather_Inner_Edge, 0.0);

  // Thickness used only in modes 2/3/4
  float tPx = max(Thickness, 0.0);

  if (edgeMode == 3 || edgeMode == 4)
    tPx = max(Thickness * R, 0.0);

  if (edgeMode == 4)
  {
    fOuterPx = max(Feather_Outer_Edge * R, 0.0);
    fInnerPx = max(Feather_Inner_Edge * R, 0.0);
  }

  // --- Requested disabling rules ---
  // Mode 0: ignore Thickness and Edge_Radius
  if (edgeMode == 0)
  {
    tPx = 0.0;
  }

  // Mode 1: ignore Thickness, use Edge_Radius only
  float edgeRadiusWidthPx = max(Edge_Radius, 0.0);
  if (edgeMode == 1)
  {
    tPx = 0.0;
  }

  // Compute inner/outer radii
  float innerR = 0.0;
  float outerR = R;

  if (edgeMode == 0)
  {
    // Filled circle only
    innerR = 0.0;
    outerR = R;
  }
else if (edgeMode == 1)
{
  // ✅ INVERTED Edge Radius:
  // Edge_Radius becomes the INNER radius directly.
  // Increasing Edge_Radius makes the ring thinner until it overlaps (inner == outer).
  innerR = min(edgeRadiusWidthPx, R);
  outerR = R;
}
  else
  {
    // Thickness-based ring: centered at R (stroke centered)
    innerR = max(R - 0.5*tPx, 0.0);
    outerR = R + 0.5*tPx;
  }

  float a = ringMask(distPx, innerR, outerR, fInnerPx, fOuterPx);

  // Invert
  a = mix(a, 1.0 - a, inv);

  // Apply Opacity (0..100 like AE)
  float op = clamp(Opacity / 100.0, 0.0, 1.0);
  a *= op;

  vec3 srcRGB = Color;

  // Stencil Alpha (Panzoid limitation: only masks this layer output)
  if (blendMode == 2)
  {
    vec4 outc = vec4(base.rgb * a, base.a * a);
    gl_FragColor = outc;
    return;
  }

  vec3 blendedRGB = applyBlendMode(base.rgb, srcRGB, blendMode);

  // Composite only where the circle exists
  vec3 outRGB = base.rgb * (1.0 - a) + blendedRGB * a;
  float outA = base.a + a - base.a * a;

  gl_FragColor = vec4(outRGB, outA);
}

text./plugins/alipfx/shaders/clay.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// Custom Panzoid properties (declare these in your effect settings)
uniform float Color_Steps;      // Controls color flattening (Lower = more chunk clay look)
uniform float Clay_Depth;       // Strength of the 3D matte emboss/shading
uniform float Texture_Scale;    // Scale of the fingerprint/clay mold wrinkles
uniform float Texture_Strength; // Intensity of the physical surface displacement

// Procedural wave function to mimic thumbprints and molded clay ridges
float clayTexture(vec2 p) {
    float n = sin(p.x * 0.4) * cos(p.y * 0.4);
    n += 0.5 * sin(p.x * 1.2 + p.y * 0.8);
    n += 0.25 * cos(p.x * 2.5 - p.y * 1.3);
    return n * 0.5 + 0.5;
}

void main()
{
    vec2 uv = vUvScaled;

    // 1. Organic UV Distortion (Creates the hand-molded, imperfect edges)
    vec2 texCoord = uv * Texture_Scale;
    float surfaceNoise = clayTexture(texCoord);

    // Displace texture coordinates slightly based on the clay texture layout
    vec2 distortedUV = uv + vec2(cos(surfaceNoise * 6.2831), sin(surfaceNoise * 6.2831)) * Texture_Strength * 0.02;

    // 2. Sample the original frame color
    vec4 color = texture2D(tDiffuse, distortedUV);

    // 3. Posterization (Quantize colors into flat blocks of clay)
    if (Color_Steps > 1.0) {
        color.rgb = floor(color.rgb * Color_Steps) / Color_Steps;
    }

    // 4. Pseudo-3D Shading & Edge Highlights
    // Look at adjacent pixels to calculate a luminance gradient (edge detection)
    vec2 pixelOffset = vec2(1.0) / resolution;
    float centerLuma = dot(color.rgb, vec3(0.299, 0.587, 0.114));

    float rightLuma = dot(texture2D(tDiffuse, distortedUV + vec2(pixelOffset.x, 0.0)).rgb, vec3(0.299, 0.587, 0.114));
    float topLuma   = dot(texture2D(tDiffuse, distortedUV + vec2(0.0, pixelOffset.y)).rgb, vec3(0.299, 0.587, 0.114));

    float deltaX = centerLuma - rightLuma;
    float deltaY = centerLuma - topLuma;

    // Derive surface variations from the texture to mix with edge shadows
    float gradX = clayTexture(texCoord + vec2(0.1, 0.0)) - surfaceNoise;
    float gradY = clayTexture(texCoord + vec2(0.0, 0.1)) - surfaceNoise;

    // Combine edges and texture irregularities for the final bump map
    float finalEdgeX = deltaX + gradX * 0.15;
    float finalEdgeY = deltaY + gradY * 0.15;

    // Create an directional light source coming from the top-left
    float lightEmboss = (finalEdgeX + finalEdgeY) * Clay_Depth;

    // Apply the lighting overlay to the flat clay colors
    color.rgb += vec3(lightEmboss);

    // Ensure colors stay within bounds
    color.rgb = clamp(color.rgb, 0.0, 1.0);

    gl_FragColor = color;
}

text./plugins/alipfx/shaders/color-balance-hs:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform float Hue;
uniform float Lightness;
uniform float Saturation;

float hue2rgb(float p, float q, float t)
{
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;

    if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
    if (t < 1.0 / 2.0) return q;
    if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;

    return p;
}

vec3 rgb2hsl(vec3 c)
{
    float maxc = max(max(c.r, c.g), c.b);
    float minc = min(min(c.r, c.g), c.b);
    float h = 0.0;
    float s = 0.0;
    float l = (maxc + minc) * 0.5;

    float d = maxc - minc;

    if (d > 0.000001)
    {
        s = d / (1.0 - abs(2.0 * l - 1.0));

        if (maxc == c.r)
        {
            h = mod((c.g - c.b) / d, 6.0);
        }
        else if (maxc == c.g)
        {
            h = ((c.b - c.r) / d) + 2.0;
        }
        else
        {
            h = ((c.r - c.g) / d) + 4.0;
        }

        h /= 6.0;

        if (h < 0.0) h += 1.0;
    }

    return vec3(h, l, s);
}

vec3 hsl2rgb(vec3 hsl)
{
    float h = hsl.x;
    float l = hsl.y;
    float s = hsl.z;

    float r, g, b;

    if (s <= 0.000001)
    {
        r = l;
        g = l;
        b = l;
    }
    else
    {
        float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
        float p = 2.0 * l - q;

        r = hue2rgb(p, q, h + 1.0 / 3.0);
        g = hue2rgb(p, q, h);
        b = hue2rgb(p, q, h - 1.0 / 3.0);
    }

    return clamp(vec3(r, g, b), 0.0, 1.0);
}

void main()
{
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 rgb = clamp(texel.rgb, 0.0, 1.0);

    // Convert to HSL
    vec3 hsl = rgb2hsl(rgb);

    // 1) Hue: rotate around 360-degree wheel
    hsl.x = mod(hsl.x + Hue / 360.0, 1.0);
    if (hsl.x < 0.0) hsl.x += 1.0;

    // 2) Lightness: AE-style legacy HLS behavior is best approximated
    //    by directly offsetting HSL lightness in the range [-100, +100]
    hsl.y = clamp(hsl.y + Lightness / 100.0, 0.0, 1.0);

    // 3) Saturation: directly offset HSL saturation in the range [-100, +100]
    hsl.z = clamp(hsl.z + Saturation / 100.0, 0.0, 1.0);

    vec3 outRgb = hsl2rgb(hsl);

    gl_FragColor = vec4(outRgb, texel.a);
}

text./plugins/alipfx/shaders/color-balance.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Panzoid custom properties (spaces become underscores)
uniform float Shadow_Red_Balance;
uniform float Shadow_Green_Balance;
uniform float Shadow_Blue_Balance;

uniform float Midtone_Red_Balance;
uniform float Midtone_Green_Balance;
uniform float Midtone_Blue_Balance;

uniform float Highlight_Red_Balance;
uniform float Highlight_Green_Balance;
uniform float Highlight_Blue_Balance;

uniform float Preserve_Luminosity;

// ------------------------------------------------------------
// AE-style / Adobe-style practical approximation controls
// ------------------------------------------------------------

// Slider scale:
// AE sliders feel like "amount" values, not full 0..1 channel writes.
// If you want the effect stronger/weaker globally, only change this.
const float RANGE_SCALE = 0.50;

// Luma weights for perceptual brightness preservation.
// 0.30 / 0.59 / 0.11 is a classic Adobe/Photoshop-style choice.
const vec3 LUMA = vec3(0.30, 0.59, 0.11);

float lum(vec3 c) {
    return dot(c, LUMA);
}

// ------------------------------------------------------------
// Photoshop/Adobe-style luminance preservation helpers
// These preserve perceived brightness while keeping hue shift.
// ------------------------------------------------------------

vec3 clipColor(vec3 c) {
    float l = lum(c);
    float n = min(min(c.r, c.g), c.b);
    float x = max(max(c.r, c.g), c.b);

    if (n < 0.0) {
        float denom = max(l - n, 1e-5);
        c = vec3(l) + ((c - vec3(l)) * l) / denom;
    }

    if (x > 1.0) {
        float denom = max(x - l, 1e-5);
        c = vec3(l) + ((c - vec3(l)) * (1.0 - l)) / denom;
    }

    return clamp(c, 0.0, 1.0);
}

vec3 setLum(vec3 c, float targetLum) {
    float d = targetLum - lum(c);
    c += vec3(d);
    return clipColor(c);
}

// ------------------------------------------------------------
// Tonal masks
// Overlapping masks approximate AE/Adobe-style three-way balance
// without hard splits.
// ------------------------------------------------------------
void getToneWeights(float y, out float shadows, out float midtones, out float highlights) {
    // These values are chosen to create soft overlapping ranges:
    // shadows dominate darks, highlights dominate brights,
    // midtones dominate the middle and overlap naturally.
    const float a = 0.25;
    const float b = 0.333;
    const float s = 0.70;

    shadows =
        clamp((y - b) / (-a) + 0.5, 0.0, 1.0) * s;

    midtones =
        clamp((y - b) / a + 0.5, 0.0, 1.0) *
        clamp((y + b - 1.0) / (-a) + 0.5, 0.0, 1.0) * s;

    highlights =
        clamp((y + b - 1.0) / a + 0.5, 0.0, 1.0) * s;

    // Normalize so the sum remains stable and predictable
    float sumW = shadows + midtones + highlights;
    if (sumW > 1e-5) {
        shadows /= sumW;
        midtones /= sumW;
        highlights /= sumW;
    }
}

// Convert AE-like slider range (-100..100) to RGB delta
vec3 sliderToDelta(vec3 slider) {
    return slider * (RANGE_SCALE / 100.0);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 src = texel.rgb;

    // Luma used to decide whether a pixel is shadow / midtone / highlight
    float y = lum(src);

    float wShadows;
    float wMidtones;
    float wHighlights;
    getToneWeights(y, wShadows, wMidtones, wHighlights);

    // Per-range slider vectors
    vec3 sh = sliderToDelta(vec3(
        Shadow_Red_Balance,
        Shadow_Green_Balance,
        Shadow_Blue_Balance
    ));

    vec3 mi = sliderToDelta(vec3(
        Midtone_Red_Balance,
        Midtone_Green_Balance,
        Midtone_Blue_Balance
    ));

    vec3 hi = sliderToDelta(vec3(
        Highlight_Red_Balance,
        Highlight_Green_Balance,
        Highlight_Blue_Balance
    ));

    // Weighted RGB adjustment
    vec3 delta = sh * wShadows + mi * wMidtones + hi * wHighlights;

    // Apply color balance directly in RGB
    vec3 balanced = src + delta;

    // Clamp before/after preserve-luma path for stability
    balanced = clamp(balanced, 0.0, 1.0);

    // Preserve Luminosity:
    // 0 = disabled
    // 1 = enabled
    if (Preserve_Luminosity > 0.5) {
        balanced = setLum(balanced, lum(src));
    }

    gl_FragColor = vec4(clamp(balanced, 0.0, 1.0), texel.a);
}

text./plugins/alipfx/shaders/colorama.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/* ---- User properties ---- */
uniform float Get_Phase_From;        // 0..9
uniform float Add_Mode;              // 0 Wrap, 1 Clamp, 2 Average, 3 Screen
uniform float Add_Amount;            // 0..1  <-- NEW
uniform float Phase_Shift;           // 0..1
uniform float Cycle_Repetitions;     // >= 1
uniform float Interpolate_Palette;   // 0/1
uniform float Modify;                // 0..13
uniform float Modify_Alpha;          // 0/1
uniform float Change_Empty_Pixels;   // 0/1

uniform vec3  Matching_Colors;       // vec3
uniform float Matching_Mode;         // 0 Off, 1 RGB, 2 Hue, 3 Chroma
uniform float Matching_Tolerance;    // 0..1
uniform float Matching_Softness;     // 0..1

uniform float Masking_Mode;          // 0..4
uniform float Composite_Over_Layer;  // 0/1
uniform float Blend_With_Original;   // 0..1

uniform vec3 Color_1;
uniform vec3 Color_2;
uniform vec3 Color_3;
uniform vec3 Color_4;
uniform vec3 Color_5;
uniform vec3 Color_6;

/* ---- Helpers ---- */
float saturate(float x) { return clamp(x, 0.0, 1.0); }
vec3  saturate(vec3 x)  { return clamp(x, vec3(0.0), vec3(1.0)); }

float luma(vec3 c){
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

float chromaRGB(vec3 c){
  float mx = max(max(c.r, c.g), c.b);
  float mn = min(min(c.r, c.g), c.b);
  return mx - mn;
}

/* RGB <-> HSV */
vec3 rgb2hsv(vec3 c){
  vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0*d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c){
  vec3 p = abs(fract(c.xxx + vec3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0);
  return c.z * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), c.y);
}

/* HSV circular interpolation (shortest hue path) */
vec3 mixHSV(vec3 aRgb, vec3 bRgb, float t){
  vec3 a = rgb2hsv(aRgb);
  vec3 b = rgb2hsv(bRgb);

  float dh = b.x - a.x;
  if(dh >  0.5) dh -= 1.0;
  if(dh < -0.5) dh += 1.0;

  float h = fract(a.x + dh * t);
  float s = mix(a.y, b.y, t);
  float v = mix(a.z, b.z, t);

  return hsv2rgb(vec3(h, s, v));
}

/* Phase extraction (0..1) */
float getPhase(vec4 src){
  float mode = floor(Get_Phase_From + 0.5);

  vec3 rgb = src.rgb;
  float a = src.a;
  vec3 hsv = rgb2hsv(rgb);

  // HSL Lightness isn't strictly needed for the ramp demo;
  // keeping your earlier mapping behavior (Lightness from luma-like HSL would be similar on grayscale).
  // For accuracy, Lightness here is approximated as (max+min)/2.
  float maxc = max(max(rgb.r, rgb.g), rgb.b);
  float minc = min(min(rgb.r, rgb.g), rgb.b);
  float lightness = (maxc + minc) * 0.5;

  if(mode == 0.0) return luma(rgb);      // Intensity
  if(mode == 1.0) return rgb.r;          // Red
  if(mode == 2.0) return rgb.g;          // Green
  if(mode == 3.0) return rgb.b;          // Blue
  if(mode == 4.0) return hsv.x;          // Hue
  if(mode == 5.0) return lightness;      // Lightness
  if(mode == 6.0) return hsv.y;          // Saturation
  if(mode == 7.0) return hsv.z;          // Value
  if(mode == 8.0) return a;              // Alpha
  return 0.0;                            // Zero
}

/* Output Cycle color fetch */
vec3 getCycleColor(int idx){
  if(idx == 0) return Color_1;
  if(idx == 1) return Color_2;
  if(idx == 2) return Color_3;
  if(idx == 3) return Color_4;
  if(idx == 4) return Color_5;
  return Color_6;
}

/* Output Cycle sampling (6-stop circular cycle) */
vec3 sampleCycle6(float t, float interpEnabled){
  float x = fract(t) * 6.0;
  float i0f = floor(x);
  float f = fract(x);

  int i0 = int(i0f);
  int i1 = int(mod(i0f + 1.0, 6.0));

  vec3 c0 = getCycleColor(i0);
  vec3 c1 = getCycleColor(i1);

  if(interpEnabled < 0.5){
    return c0; // hard steps
  }else{
    // HSV interpolation keeps rainbow vivid & smooth
    return mixHSV(c0, c1, f);
  }
}

/* Add Mode = literal combine mapped over source */
vec3 addCombine(vec3 srcRgb, vec3 mappedRgb){
  float m = floor(Add_Mode + 0.5);

  if(m == 0.0){
    return fract(srcRgb + mappedRgb);                 // Wrap
  }else if(m == 1.0){
    return saturate(srcRgb + mappedRgb);              // Clamp
  }else if(m == 2.0){
    return (srcRgb + mappedRgb) * 0.5;                // Average
  }else{
    return 1.0 - (1.0 - srcRgb) * (1.0 - mappedRgb);  // Screen
  }
}

/* Modify integration */
vec4 applyModify(vec4 orig, vec4 fx){
  float m = floor(Modify + 0.5);

  if(m == 13.0) return orig; // None
  if(m == 0.0)  return fx;   // All

  vec4 outc = fx;

  if(m == 1.0){ outc.rgb = vec3(fx.r, orig.g, orig.b); return outc; } // R
  if(m == 2.0){ outc.rgb = vec3(orig.r, fx.g, orig.b); return outc; } // G
  if(m == 3.0){ outc.rgb = vec3(orig.r, orig.g, fx.b); return outc; } // B
  if(m == 4.0){ outc.rgb = vec3(fx.r, fx.g, orig.b); return outc; }   // RG
  if(m == 5.0){ outc.rgb = vec3(orig.r, fx.g, fx.b); return outc; }   // GB
  if(m == 6.0){ outc.rgb = vec3(fx.r, orig.g, fx.b); return outc; }   // RB

  // Attribute modes (Hue/Sat/Lightness-ish)
  vec3 oHSV = rgb2hsv(orig.rgb);
  vec3 fHSV = rgb2hsv(fx.rgb);

  float maxo = max(max(orig.r, orig.g), orig.b);
  float mino = min(min(orig.r, orig.g), orig.b);
  float oL = (maxo + mino) * 0.5;

  float maxf = max(max(fx.r, fx.g), fx.b);
  float minf = min(min(fx.r, fx.g), fx.b);
  float fL = (maxf + minf) * 0.5;

  if(m == 7.0){ // Hue
    outc.rgb = hsv2rgb(vec3(fHSV.x, oHSV.y, oHSV.z));
    return outc;
  }
  if(m == 8.0){ // Lightness (approx)
    // Keep hue/sat from original but set value by matching lightness (approx)
    // (close visually on most content; exact HSL needs full conversion)
    vec3 hsv = oHSV;
    hsv.z = mix(oHSV.z, fHSV.z, 0.5); // pragmatic approximation
    outc.rgb = hsv2rgb(hsv);
    return outc;
  }
  if(m == 9.0){ // Saturation
    outc.rgb = hsv2rgb(vec3(oHSV.x, fHSV.y, oHSV.z));
    return outc;
  }
  if(m == 10.0){ // HL (approx)
    outc.rgb = hsv2rgb(vec3(fHSV.x, oHSV.y, mix(oHSV.z, fHSV.z, 0.5)));
    return outc;
  }
  if(m == 11.0){ // LS (approx)
    outc.rgb = hsv2rgb(vec3(oHSV.x, fHSV.y, mix(oHSV.z, fHSV.z, 0.5)));
    return outc;
  }
  if(m == 12.0){ // HS
    outc.rgb = hsv2rgb(vec3(fHSV.x, fHSV.y, oHSV.z));
    return outc;
  }

  return outc;
}

/* Matching mask controlled by Matching_Mode */
float matchingMask(vec3 srcRgb){
  float mode = floor(Matching_Mode + 0.5);

  if(mode == 0.0) return 1.0; // Off

  float tol  = saturate(Matching_Tolerance);
  float soft = max(1e-6, Matching_Softness);

  float d = 0.0;

  if(mode == 1.0){
    d = length(srcRgb - Matching_Colors); // RGB
  }
  else if(mode == 2.0){
    vec3 a = rgb2hsv(srcRgb);
    vec3 b = rgb2hsv(Matching_Colors);
    float dh = abs(a.x - b.x);
    dh = min(dh, 1.0 - dh);
    float satGuard = max(a.y, 0.001);
    d = dh / satGuard; // Hue becomes stricter when low saturation
  }
  else {
    float cA = chromaRGB(srcRgb);
    float cB = chromaRGB(Matching_Colors);
    d = abs(cA - cB); // Chroma
  }

  float w = 1.0 - smoothstep(tol, tol + soft, d);
  return saturate(w);
}

/* Masking mode based on intensity/alpha */
float maskingModeMask(vec4 src){
  float mode = floor(Masking_Mode + 0.5);
  float inten = luma(src.rgb);
  float a = src.a;

  if(mode == 0.0) return 1.0;
  if(mode == 1.0) return inten;
  if(mode == 2.0) return a;
  if(mode == 3.0) return 1.0 - inten;
  return 1.0 - a;
}

/* Porter-Duff "over" */
vec4 over(vec4 fg, vec4 bg){
  float outA = fg.a + bg.a * (1.0 - fg.a);
  vec3 outRGB = (fg.rgb * fg.a + bg.rgb * bg.a * (1.0 - fg.a)) / max(outA, 1e-10);
  return vec4(outRGB, outA);
}

void main(){
  vec4 src = texture2D(tDiffuse, vUvScaled);

  if(Change_Empty_Pixels < 0.5 && src.a <= 0.0){
    gl_FragColor = src;
    return;
  }

  // Phase
  float phase = getPhase(src);

  // Reps + shift
  float reps = max(1.0, Cycle_Repetitions);
  float p = fract(phase * reps + Phase_Shift);

  // Palette map
  vec3 mappedRgb = sampleCycle6(p, Interpolate_Palette);

  // Add stage: either pure mapped (Add_Amount=0) or combined (Add_Amount=1)
  vec3 combinedRgb = addCombine(src.rgb, mappedRgb);
  vec3 fxRgb = mix(mappedRgb, combinedRgb, saturate(Add_Amount));

  // Alpha
  float fxA = (Modify_Alpha > 0.5) ? p : src.a;
  vec4 fx = vec4(fxRgb, fxA);

  // Modify
  vec4 modified = applyModify(src, fx);

  if(Modify_Alpha < 0.5){
    modified.a = src.a;
  }

  // Matching + Masking
  float matchW = matchingMask(src.rgb);
  float maskW  = maskingModeMask(src);
  float effectW = saturate(matchW * maskW);

  // Blend with original (AE-like: 0=full effect, 1=original)
  float effectAmt = saturate(1.0 - Blend_With_Original);

  // Composite Over Layer
  if(Composite_Over_Layer > 0.5){
    vec4 fg = modified;
    fg.a *= (effectW * effectAmt);
    gl_FragColor = over(fg, src);
  }else{
    gl_FragColor = mix(src, modified, effectW * effectAmt);
  }
}

text./plugins/alipfx/shaders/colorvsn.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
varying vec2 vUv;
varying vec2 vUvScaled;

// ALL properties as dynamic float uniforms
uniform float Colormaps;         // 0.0-21.0
uniform float Colormap_Strength; // 0.0-100.0
uniform float Contrast;          // 0.0-200.0
uniform float Brightness;        // -100.0 to 100.0
uniform float Blend_Mode;        // 0.0-4.0

vec3 lerp3(vec3 a, vec3 b, float t) {
    return a + (b - a) * t;
}

float clamp01(float x) {
    return clamp(x, 0.0, 1.0);
}

// ========== 22 COLORMAP FUNCTIONS ==========

vec3 colormap_autumn(float t) {
    t = clamp01(t);
    return vec3(1.0, t, 0.0);
}

vec3 colormap_bone(float t) {
    t = clamp01(t);
    vec3 c0 = vec3(0.0, 0.0, 0.0);
    vec3 c1 = vec3(0.3, 0.3, 0.5);
    vec3 c2 = vec3(0.7, 0.7, 0.9);
    vec3 c3 = vec3(1.0, 1.0, 1.0);
    if (t < 0.25) return lerp3(c0, c1, t / 0.25);
    else if (t < 0.5) return lerp3(c1, c2, (t - 0.25) / 0.25);
    else if (t < 0.75) return lerp3(c2, c3, (t - 0.5) / 0.25);
    else return c3;
}

vec3 colormap_jet(float t) {
    t = clamp01(t);
    vec3 c0 = vec3(0.0, 0.0, 0.5);
    vec3 c1 = vec3(0.0, 0.0, 1.0);
    vec3 c2 = vec3(0.0, 1.0, 1.0);
    vec3 c3 = vec3(1.0, 1.0, 0.0);
    vec3 c4 = vec3(1.0, 0.0, 0.0);
    vec3 c5 = vec3(0.5, 0.0, 0.0);
    if (t < 0.125) return lerp3(c0, c1, t / 0.125);
    else if (t < 0.375) return lerp3(c1, c2, (t - 0.125) / 0.25);
    else if (t < 0.625) return lerp3(c2, c3, (t - 0.375) / 0.25);
    else if (t < 0.875) return lerp3(c3, c4, (t - 0.625) / 0.25);
    else return lerp3(c4, c5, (t - 0.875) / 0.125);
}

vec3 colormap_winter(float t) {
    t = clamp01(t);
    return vec3(0.0, t, 0.5 + 0.5 * t);
}

vec3 colormap_rainbow(float t) {
    t = clamp01(t);
    float r = abs(t * 6.0 - 3.0) - 1.0;
    float g = 2.0 - abs(t * 6.0 - 2.0);
    float b = 2.0 - abs(t * 6.0 - 4.0);
    return clamp(vec3(r, g, b), 0.0, 1.0);
}

vec3 colormap_ocean(float t) {
    t = clamp01(t);
    vec3 c0 = vec3(0.0, 0.0, 0.0);
    vec3 c1 = vec3(0.0, 0.1, 0.3);
    vec3 c2 = vec3(0.0, 0.3, 0.6);
    vec3 c3 = vec3(0.0, 0.5, 0.8);
    vec3 c4 = vec3(0.0, 0.7, 0.9);
    vec3 c5 = vec3(0.5, 0.9, 1.0);
    if (t < 0.2) return lerp3(c0, c1, t / 0.2);
    else if (t < 0.4) return lerp3(c1, c2, (t - 0.2) / 0.2);
    else if (t < 0.6) return lerp3(c2, c3, (t - 0.4) / 0.2);
    else if (t < 0.8) return lerp3(c3, c4, (t - 0.6) / 0.2);
