precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution; // Fetches the layer's pixel dimensions
varying vec2 vUv;
varying vec2 vUvScaled;

// Custom Properties
uniform vec2 Upper_Left;
uniform vec2 Upper_Right;
uniform vec2 Lower_Left;
uniform vec2 Lower_Right;

// Helper function: 2D Cross Product
float cross2d(vec2 a, vec2 b) {
    return a.x * b.y - a.y * b.x;
}

// Converts After Effects pixel coordinates (Top-Left origin)
// to Panzoid WebGL UV coordinates (Bottom-Left origin)
vec2 pixelToUV(vec2 pixelCoords) {
    return vec2(pixelCoords.x / resolution.x, 1.0 - (pixelCoords.y / resolution.y));
}

// Inverse Bilinear Interpolation
vec2 invBilinear(vec2 p, vec2 a, vec2 b, vec2 c, vec2 d) {
    vec2 e = b - a;
    vec2 f = c - a;
    vec2 g = a - b + d - c;
    vec2 h = p - a;

    float k2 = cross2d(g, f);
    float k1 = cross2d(e, f) + cross2d(h, g);
    float k0 = cross2d(h, e);

    if (abs(k2) < 0.0001) {
        float v = -k0 / k1;
        float denomX = e.x + g.x * v;
        float denomY = e.y + g.y * v;
        float u = (abs(denomX) > abs(denomY)) ? (h.x - f.x * v) / denomX : (h.y - f.y * v) / denomY;
        return vec2(u, v);
    }

    float w = k1 * k1 - 4.0 * k0 * k2;
    if (w < 0.0) return vec2(-1.0); 

    w = sqrt(w);

    float v1 = (-k1 - w) / (2.0 * k2);
    float v2 = (-k1 + w) / (2.0 * k2);

    float denomX1 = e.x + g.x * v1;
    float denomY1 = e.y + g.y * v1;
    float u1 = (abs(denomX1) > abs(denomY1)) ? (h.x - f.x * v1) / denomX1 : (h.y - f.y * v1) / denomY1;

    float denomX2 = e.x + g.x * v2;
    float denomY2 = e.y + g.y * v2;
    float u2 = (abs(denomX2) > abs(denomY2)) ? (h.x - f.x * v2) / denomX2 : (h.y - f.y * v2) / denomY2;

    bool b1 = (v1 >= 0.0 && v1 <= 1.0 && u1 >= 0.0 && u1 <= 1.0);
    bool b2 = (v2 >= 0.0 && v2 <= 1.0 && u2 >= 0.0 && u2 <= 1.0);

    vec2 res = vec2(-1.0);
    if (b1) res = vec2(u1, v1);
    else if (b2) res = vec2(u2, v2);

    return res;
}

void main() {
    // Convert AE pixel coordinates to Panzoid UV mapping
    // a = Bottom Left, b = Bottom Right, c = Top Left, d = Top Right
    vec2 p0 = pixelToUV(Lower_Left);
    vec2 p1 = pixelToUV(Lower_Right);
    vec2 p2 = pixelToUV(Upper_Left);
    vec2 p3 = pixelToUV(Upper_Right);

    vec2 uvMap = invBilinear(vUv, p0, p1, p2, p3);

    // Render transparent if outside the mapped quadrilateral 
    if (uvMap.x < 0.0 || uvMap.y < 0.0 || uvMap.x > 1.0 || uvMap.y > 1.0) {
        gl_FragColor = vec4(0.0);
    } else {
        vec4 texel = texture2D(tDiffuse, uvMap * uvScale);
        gl_FragColor = texel;
    }
}

text./plugins/alipfx/shaders/cr-lumaramp.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom Properties mapped from Panzoid UI
uniform vec3 Color_1; uniform vec3 Color_2; uniform vec3 Color_3; uniform vec3 Color_4;
uniform vec3 Color_5; uniform vec3 Color_6; uniform vec3 Color_7; uniform vec3 Color_8;
uniform float Gradient_Colors;
uniform float Preset;
uniform float Interpolation;
uniform float Invert;
uniform float Repeats;

#define PI 3.14159265359

// --- Color Space Conversion Functions ---

// HSV
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// LAB & XYZ (D65 Illuminant)
vec3 rgb2xyz(vec3 rgb) {
    rgb = mix(rgb / 12.92, pow((rgb + 0.055) / 1.055, vec3(2.4)), step(0.04045, rgb));
    return vec3(
        rgb.r * 0.4124 + rgb.g * 0.3576 + rgb.b * 0.1805,
        rgb.r * 0.2126 + rgb.g * 0.7152 + rgb.b * 0.0722,
        rgb.r * 0.0193 + rgb.g * 0.1192 + rgb.b * 0.9505
    );
}
vec3 xyz2lab(vec3 xyz) {
    vec3 n = xyz / vec3(0.95047, 1.0, 1.08883);
    vec3 v = mix(vec3(7.787) * n + vec3(16.0 / 116.0), pow(n, vec3(1.0 / 3.0)), step(vec3(0.008856), n));
    return vec3(116.0 * v.y - 16.0, 500.0 * (v.x - v.y), 200.0 * (v.y - v.z));
}
vec3 lab2xyz(vec3 lab) {
    float y = (lab.x + 16.0) / 116.0;
    float x = lab.y / 500.0 + y;
    float z = y - lab.z / 200.0;
    vec3 v = vec3(x, y, z);
    vec3 v3 = v * v * v;
    vec3 n = mix((v - vec3(16.0 / 116.0)) / 7.787, v3, step(vec3(0.206893), v));
    return n * vec3(0.95047, 1.0, 1.08883);
}
vec3 xyz2rgb(vec3 xyz) {
    vec3 rgb = vec3(
        xyz.x * 3.2406 + xyz.y * -1.5372 + xyz.z * -0.4986,
        xyz.x * -0.9689 + xyz.y * 1.8758 + xyz.z * 0.0415,
        xyz.x * 0.0557 + xyz.y * -0.2040 + xyz.z * 1.0570
    );
    return mix(12.92 * rgb, 1.055 * pow(clamp(rgb, 0.0, 1.0), vec3(1.0 / 2.4)) - 0.055, step(0.0031308, rgb));
}
vec3 rgb2lab(vec3 c) { return xyz2lab(rgb2xyz(c)); }
vec3 lab2rgb(vec3 c) { return xyz2rgb(lab2xyz(c)); }

// HCL (derived from LAB)
vec3 lab2hcl(vec3 lab) {
    return vec3(atan(lab.z, lab.y), length(lab.yz), lab.x);
}
vec3 hcl2lab(vec3 hcl) {
    return vec3(hcl.z, hcl.y * cos(hcl.x), hcl.y * sin(hcl.x));
}

// --- Presets Data ---

int getPresetColorCount(int p) {
    if(p == 0) return int(clamp(Gradient_Colors, 2.0, 8.0));
    if(p == 1) return 6; if(p == 2) return 2; if(p == 3) return 7;
    if(p == 4) return 5; if(p == 5) return 4; if(p == 6) return 4;
    if(p == 7) return 3; if(p == 8) return 5; if(p == 9) return 4;
    if(p == 10) return 7;
    return 2;
}

vec3 getPresetColor(int p, int i) {
    if (p == 0) { // Custom
        if(i == 0) return Color_1; if(i == 1) return Color_2; if(i == 2) return Color_3; if(i == 3) return Color_4;
        if(i == 4) return Color_5; if(i == 5) return Color_6; if(i == 6) return Color_7; return Color_8;
    }
    if (p == 1) { // Vivid
        if(i == 0) return vec3(1.0, 0.0, 0.0); if(i == 1) return vec3(1.0, 1.0, 0.0); if(i == 2) return vec3(0.0, 1.0, 0.0);
        if(i == 3) return vec3(0.0, 1.0, 1.0); if(i == 4) return vec3(0.0, 0.0, 1.0); return vec3(1.0, 0.0, 1.0);
    }
    if (p == 2) { // White to Black
        if(i == 0) return vec3(1.0); return vec3(0.0);
    }
    if (p == 3) { // Rainbow
        if(i == 0) return vec3(1.0, 0.0, 0.0); if(i == 1) return vec3(1.0, 0.5, 0.0); if(i == 2) return vec3(1.0, 1.0, 0.0);
        if(i == 3) return vec3(0.0, 1.0, 0.0); if(i == 4) return vec3(0.0, 0.0, 1.0); if(i == 5) return vec3(0.29, 0.0, 0.51); return vec3(0.56, 0.0, 1.0);
    }
    if (p == 4) { // Fire
        if(i == 0) return vec3(0.0); if(i == 1) return vec3(1.0, 0.0, 0.0); if(i == 2) return vec3(1.0, 0.5, 0.0);
        if(i == 3) return vec3(1.0, 1.0, 0.0); return vec3(1.0);
    }
    if (p == 5) { // Blue Fire
        if(i == 0) return vec3(0.0); if(i == 1) return vec3(0.0, 0.0, 0.5); if(i == 2) return vec3(0.0, 0.5, 1.0); return vec3(1.0);
    }
    if (p == 6) { // Smoke
        if(i == 0) return vec3(0.1); if(i == 1) return vec3(0.3); if(i == 2) return vec3(0.6); return vec3(0.8);
    }
    if (p == 7) { // Wood Rings
        if(i == 0) return vec3(0.3, 0.15, 0.05); if(i == 1) return vec3(0.6, 0.4, 0.2); return vec3(0.8, 0.6, 0.3);
    }
    if (p == 8) { // Electric
        if(i == 0) return vec3(0.0); if(i == 1) return vec3(0.5, 0.0, 1.0); if(i == 2) return vec3(0.0, 0.5, 1.0);
        if(i == 3) return vec3(0.0, 1.0, 1.0); return vec3(1.0);
    }
    if (p == 9) { // Aqualight
        if(i == 0) return vec3(0.0, 0.1, 0.3); if(i == 1) return vec3(0.0, 0.5, 0.6); if(i == 2) return vec3(0.5, 0.9, 0.9); return vec3(1.0);
    }
    if (p == 10) { // Heat Map
        if(i == 0) return vec3(0.0); if(i == 1) return vec3(0.0, 0.0, 1.0); if(i == 2) return vec3(0.0, 1.0, 1.0);
        if(i == 3) return vec3(0.0, 1.0, 0.0); if(i == 4) return vec3(1.0, 1.0, 0.0); if(i == 5) return vec3(1.0, 0.0, 0.0); return vec3(1.0);
    }
    return vec3(0.0);
}

// --- Interpolation Logic ---

vec3 interpolateColors(vec3 c1, vec3 c2, float t, int mode) {
    if (mode == 4) { // Step
        return t < 0.5 ? c1 : c2;
    }
    if (mode == 3) { // RGB
        return mix(c1, c2, t);
    }
    if (mode == 2) { // HSV
        vec3 hsv1 = rgb2hsv(c1);
        vec3 hsv2 = rgb2hsv(c2);
        float dh = hsv2.x - hsv1.x;
        if (dh > 0.5) hsv2.x -= 1.0;
        else if (dh < -0.5) hsv2.x += 1.0;
        vec3 hsv = mix(hsv1, hsv2, t);
        hsv.x = fract(hsv.x);
        return hsv2rgb(hsv);
    }
    if (mode == 1) { // LAB
        return lab2rgb(mix(rgb2lab(c1), rgb2lab(c2), t));
    }
    // Mode 0: HCL (Default)
    vec3 hcl1 = lab2hcl(rgb2lab(c1));
    vec3 hcl2 = lab2hcl(rgb2lab(c2));
    float dh = hcl2.x - hcl1.x;
    if (dh > PI) hcl2.x -= 2.0 * PI;
    else if (dh < -PI) hcl2.x += 2.0 * PI;
    vec3 hcl = mix(hcl1, hcl2, t);
    return lab2rgb(hcl2lab(hcl));
}

// --- Main Program ---

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // 1. Calculate Base Luma
    float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114));

    // 2. Apply Invert
    float t = Invert > 0.5 ? 1.0 - luma : luma;

    // 3. Apply Repeats
    float reps = max(1.0, Repeats);
    t = fract(t * reps);

    // 4. Setup Gradient Logic
    int p = int(Preset + 0.5);
    int interp = int(Interpolation + 0.5);
    int colorCount = getPresetColorCount(p);

    // 5. Calculate Color Stops
    float scaledT = t * float(colorCount - 1);
    int idx = int(floor(scaledT));
    float fractT = fract(scaledT);

    // Prevent out-of-bounds mapping at t=1.0
    if (idx >= colorCount - 1) {
        idx = colorCount - 2;
        fractT = 1.0;
    }

    vec3 colorA = getPresetColor(p, idx);
    vec3 colorB = getPresetColor(p, idx + 1);

    // 6. Output Mapped Color
    vec3 finalColor = interpolateColors(colorA, colorB, fractT, interp);

    gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), texel.a);
}

text./plugins/alipfx/shaders/crtx-lite.glsl:
precision highp float;
precision highp int;

// Panzoid Default Uniforms & Varyings
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;

// Required Animation Uniform (Create a dynamic property called "Time" in Panzoid and animate it)
uniform float Time;

// All Mode/Dropdown Properties converted to floats to prevent Panzoid binding flicker
uniform float Preset;
uniform float Look_Strength;
uniform float Brightness;
uniform float Contrast;
uniform float Color_Temperature;
uniform vec3 Tint;
uniform float Curvature;
uniform float Screen_Type;
uniform float Screen_Texture;
uniform float Scanlines;
uniform float Glow;
uniform float Edge_Brightness;
uniform float Phosphor_Trail; 
uniform float Vignette;
uniform float Color_Bleed;
uniform float Analog_Noise;
uniform float Signal_Damage;
uniform float Warp;
uniform float Sync_Drift;
uniform float Blanking;
uniform float Shutter_Strength;
uniform float Shutter_Readout;
uniform float Render_Quality;
uniform float GPU_Rendering;

// --- Helper Functions ---

// Pseudo-random noise
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

// CRT Curvature Distortion
vec2 applyCurvature(vec2 uv, float curveAmount) {
    vec2 cc = uv - 0.5;
    float dist = dot(cc, cc);
    return uv + cc * (dist * curveAmount);
}

// Color Temperature adjustments (Using internal integer casting)
vec3 applyColorTemp(vec3 col, int temp) {
    if (temp == 0) {
        // Warm 5000K 
        return col * vec3(1.1, 1.05, 0.9);
    } else if (temp == 2) {
        // Cool 9300K 
        return col * vec3(0.9, 0.95, 1.15);
    }
    // Neutral 6500K
    return col;
}

// Subpixel Mask Patterns (Screen Type)
vec3 getScreenMask(vec2 uv, int type, float textureStrength) {
    vec2 fragCoord = uv * resolution;
    vec3 mask = vec3(1.0);

    if (type == 0) { // Dot Triad
        float pos = mod(fragCoord.x + mod(fragCoord.y, 2.0), 3.0);
        if (pos < 1.0) mask = vec3(1.0, 0.5, 0.5);
        else if (pos < 2.0) mask = vec3(0.5, 1.0, 0.5);
        else mask = vec3(0.5, 0.5, 1.0);
    } 
    else if (type == 1) { // Aperture Grille
        float pos = mod(fragCoord.x, 3.0);
        if (pos < 1.0) mask = vec3(1.0, 0.3, 0.3);
        else if (pos < 2.0) mask = vec3(0.3, 1.0, 0.3);
        else mask = vec3(0.3, 0.3, 1.0);
    } 
    else if (type == 2) { // Slot Mask
        float posx = mod(fragCoord.x, 3.0);
        float posy = mod(fragCoord.y, 3.0);
        mask = vec3(0.8) + 0.2 * sin(posx * 3.14) * sin(posy * 3.14);
    }

    return mix(vec3(1.0), mask, textureStrength * Look_Strength);
}

void main() {
    // Locally convert floats to safe integers using rounding (+0.5) to stop flickering
    int int_Preset = int(Preset + 0.5);
    int act_Mask = int(Screen_Type + 0.5);
    int act_Temp = int(Color_Temperature + 0.5);
    int int_Quality = int(Render_Quality + 0.5);

    // Default variable copies for presets
    float act_Curvature = Curvature;
    float act_Scanlines = Scanlines;
    float act_Damage = Signal_Damage;
    float act_Noise = Analog_Noise;
    float act_Glow = Glow;
    float act_Bleed = Color_Bleed;

    // --- PRESET SELECTION OVERRIDES ---
    if (int_Preset == 1) { // Clean Monitor
        act_Curvature = 0.05; act_Scanlines = 0.3; act_Noise = 0.05; act_Damage = 0.0; act_Mask = 1;
    } else if (int_Preset == 2) { // Consumer TV
        act_Curvature = 0.15; act_Scanlines = 0.5; act_Temp = 2; act_Bleed = 0.4; act_Mask = 2;
    } else if (int_Preset == 3) { // Arcade 240p
        act_Curvature = 0.2; act_Scanlines = 1.0; act_Glow = 0.8; act_Mask = 0;
    } else if (int_Preset == 4) { // Trinitron Crisp
        act_Curvature = 0.02; act_Scanlines = 0.6; act_Glow = 0.3; act_Mask = 1;
    } else if (int_Preset == 5) { // Vintage Tube
        act_Curvature = 0.3; act_Temp = 0; act_Glow = 1.0; act_Bleed = 0.7;
    } else if (int_Preset == 6) { // Broadcast Fail
        act_Damage = 1.0; act_Noise = 0.5; act_Bleed = 0.8; act_Curvature = 0.1;
    } else if (int_Preset == 7) { // RF Damage
        act_Noise = 1.0; act_Damage = 0.8; act_Bleed = 1.0; act_Curvature = 0.15;
    }

    // --- UV SETUP & WARP ---
    vec2 uv = vUvScaled;

    // Sync Drift (Vertical rolling)
    float drift = act_Damage * Sync_Drift * Time * 0.5;
    uv.y = fract(uv.y + drift);

    // Warp and Geometry Instability
    uv.x += sin(uv.y * 10.0 + Time) * Warp * 0.02 * Look_Strength;

    // Apply Curvature
    vec2 curvedUV = applyCurvature(uv, act_Curvature * Look_Strength);

    // Cutoff for screen edges (Blanking)
    if (curvedUV.x < (0.0 + Blanking * 0.1) || curvedUV.x > (1.0 - Blanking * 0.1) || 
        curvedUV.y < (0.0 + Blanking * 0.1) || curvedUV.y > (1.0 - Blanking * 0.1)) {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // --- SIGNAL SAMPLING (With Color Bleed) ---
    float bleedOffset = act_Bleed * 0.005 * Look_Strength;

    // Simulated Glitch/Damage displacement
    float glitchOffset = (hash(vec2(curvedUV.y, Time)) - 0.5) * act_Damage * 0.1 * step(0.95, hash(vec2(Time, 1.0)));

    vec4 texR = texture2D(tDiffuse, curvedUV + vec2(bleedOffset + glitchOffset, 0.0));
    vec4 texG = texture2D(tDiffuse, curvedUV + vec2(glitchOffset, 0.0));
    vec4 texB = texture2D(tDiffuse, curvedUV + vec2(-bleedOffset + glitchOffset, 0.0));

    vec3 col = vec3(texR.r, texG.g, texB.b);
// --- PHOSPHOR TRAIL ---
// Bright pixels leave a horizontal persistence trail.

if (Phosphor_Trail > 0.001)
{
    vec2 px = vec2(1.0 / resolution.x, 0.0);

    vec3 trail1 = texture2D(tDiffuse,
        curvedUV - px * 1.5).rgb;

    vec3 trail2 = texture2D(tDiffuse,
        curvedUV - px * 3.5).rgb;

    vec3 trail3 = texture2D(tDiffuse,
        curvedUV - px * 6.0).rgb;

    vec3 trail4 = texture2D(tDiffuse,
        curvedUV - px * 10.0).rgb;

    vec3 persistence =
        trail1 * 0.45 +
        trail2 * 0.30 +
        trail3 * 0.18 +
        trail4 * 0.07;

    float lum =
        dot(col,
        vec3(0.2126,0.7152,0.0722));

    persistence *= lum;

    col += persistence *
           Phosphor_Trail *
           Look_Strength *
           0.65;
}
    // --- FAKE GLOW / HALATION ---
    if (act_Glow > 0.0 && int_Quality > 0) {
        float g_off = 0.005 * act_Glow;
        vec3 glowCol = texture2D(tDiffuse, curvedUV + vec2(g_off, g_off)).rgb;
        glowCol += texture2D(tDiffuse, curvedUV + vec2(-g_off, g_off)).rgb;
        glowCol += texture2D(tDiffuse, curvedUV + vec2(g_off, -g_off)).rgb;
        glowCol += texture2D(tDiffuse, curvedUV + vec2(-g_off, -g_off)).rgb;
        float highlight =
    max(col.r,
    max(col.g,col.b));

float bloomMask =
    smoothstep(
        0.55,
        1.0,
        highlight
    );

col +=
    (glowCol / 4.0)
    * bloomMask
    * act_Glow
    * Look_Strength
    * 0.6;
    }

    // --- COLOR CORRECTION ---
    col = applyColorTemp(col, act_Temp);
    col *= Tint; 
    col = (col - 0.5) * (Contrast + 1.0) + 0.5; 
    col *= (Brightness + 1.0); 

    // --- SCREEN TEXTURE & SCANLINES ---
    vec3 mask = getScreenMask(curvedUV, act_Mask, Screen_Texture);
    col *= mask;

    float scanline = sin(curvedUV.y * resolution.y * 3.1415);
    scanline = smoothstep(0.0, 1.0, scanline * 0.5 + 0.5);
    col = mix(col, col * scanline, act_Scanlines * Look_Strength);

    // --- NOISE & SHUTTER BANDING ---
    float noiseAmount = hash(curvedUV * Time) * act_Noise * 0.2 * Look_Strength;
    col += vec3(noiseAmount);

    float shutterBanding = sin(curvedUV.y * 20.0 - Time * Shutter_Readout * 10.0);
    col += shutterBanding * Shutter_Strength * 0.1 * Look_Strength;

    // --- VIGNETTE & EDGE BRIGHTNESS ---
    vec2 cc = curvedUV - 0.5;
    float dist = dot(cc, cc);
// --- VIGNETTE & EDGE BRIGHTNESS ---

vec2 crtVignetteUV = curvedUV - 0.5;
float crtVignetteDist = dot(crtVignetteUV, crtVignetteUV);

// soft CRT vignette
float crtVignetteMask = 1.0 - smoothstep(0.15, 0.55, crtVignetteDist) * Vignette;
col *= crtVignetteMask;

// subtle center focus
float crtCenterFocus = 1.0 - smoothstep(0.10, 0.40, crtVignetteDist);

float crtEdgeLift = crtCenterFocus * Edge_Brightness * Look_Strength;
col += col * crtEdgeLift * 0.25;
// CRT beam focus loss near edges

float centerWeight =
    1.0 -
    smoothstep(
        0.15,
        0.45,
        dist
    );

float edgeBoost =
    centerWeight *
    Edge_Brightness *
    Look_Strength;

col += col * edgeBoost * 0.25;

    gl_FragColor = vec4(col, 1.0);
}

text./plugins/alipfx/shaders/curl-noise.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;
uniform float time; // Panzoid's built-in time uniform for Speed and Turbulence

// --- 1. Input Noise ---
uniform float Source;
uniform float Mirror_at_Edge;
uniform float Speed;
uniform float Direction;
uniform float Softness;

// --- 2. Transform ---
uniform float Uniform_Scaling;
uniform float Scale;
uniform float Scale_Width;
uniform float Scale_Height;
uniform vec2 Offset;
uniform float Rotation;

// --- 3. Curl Generation ---
uniform float Evolution;
uniform float Turbulence_Speed;
uniform float Swirl;
uniform float Density;
uniform float Smoothness;
uniform float Vertical_Bias;

// --- 4. Flow Options ---
uniform float Sample_Count;
uniform float Sample_Radius;
uniform float Flow_Softness;
uniform float Edge_Definition;
uniform float Flow_Falloff;

// --- 5. Output ---
uniform float View;
uniform float Contrast;
uniform float Brightness;
uniform float Clip_HDR_Results;
uniform float Channel;

// ==========================================
// 3D Simplex Noise Function (Ashima Arts)
// ==========================================
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 permute(vec4 x) { return mod289(((x*34.0)+10.0)*x); }
vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

float snoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i  = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod289(i);
    vec4 p = permute(permute(permute(
                i.z + vec4(0.0, i1.z, i2.z, 1.0))
              + i.y + vec4(0.0, i1.y, i2.y, 1.0))
              + i.x + vec4(0.0, i1.x, i2.x, 1.0));
    float n_ = 0.142857142857;
    vec3 ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);
    vec4 x = x_ * ns.x + ns.yyyy;
    vec4 y = y_ * ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);
    vec4 s0 = floor(b0) * 2.0 + 1.0;
    vec4 s1 = floor(b1) * 2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m * m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
}

// ==========================================
// Sampling & Generation Logic
// ==========================================
float getInternalNoise(vec2 uv) {
    // 1. Spatial drifting (Driven ONLY by Speed and Direction)
    float driftTime = time * Speed * 0.01;
    float dirRad = Direction * 3.14159265 / 180.0;
    vec2 flowVel = vec2(cos(dirRad), sin(dirRad)) * driftTime;

    // 2. Temporal morphing (Driven by Turbulence Speed and Evolution)
    float evoOffset = Evolution * 0.01;
    float turb = time * Turbulence_Speed * 0.01 + evoOffset;

    // Density pulls/pushes complexity
    vec2 pos = uv * (Density * 0.05 + 1.5) + flowVel;
    return snoise(vec3(pos, turb)) * 0.5 + 0.5;
}

vec4 sampleInputMap(vec2 uv) {
    if (Source < 0.5) { // Internal
        float n = getInternalNoise(uv);
        return vec4(vec3(n), 1.0);
    } else { // This Layer
        if (Mirror_at_Edge > 0.5) {
            uv = abs(mod(uv - 1.0, 2.0) - 1.0);
        } else {
            if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return vec4(0.0);
        }

        if (Softness > 0.0) {
            vec4 col = vec4(0.0);
            float r = Softness * 0.001;
            // 5-tap cross blur
            col += texture2D(tDiffuse, (uv) * uvScale);
            col += texture2D(tDiffuse, (uv + vec2(r, 0.0)) * uvScale);
            col += texture2D(tDiffuse, (uv + vec2(-r, 0.0)) * uvScale);
            col += texture2D(tDiffuse, (uv + vec2(0.0, r)) * uvScale);
            col += texture2D(tDiffuse, (uv + vec2(0.0, -r)) * uvScale);
            return col / 5.0;
        }
        return texture2D(tDiffuse, uv * uvScale);
    }
}

float getLuminance(vec2 uv) {
    vec4 c = sampleInputMap(uv);
    return dot(c.rgb, vec3(0.299, 0.587, 0.114));
}

vec2 generateCurl(vec2 uv) {
    // 1. Lock a fixed base epsilon to preserve mathematically stable vector power
    float baseEps = 0.002;

    // 2. Smoothness pushes the sampling footprint outward to ignore high-frequency details
    float reach = baseEps + (Smoothness * 0.0005);

    float n0 = getLuminance(uv + vec2(0.0, reach));
    float n1 = getLuminance(uv - vec2(0.0, reach));
    float n2 = getLuminance(uv + vec2(reach, 0.0));
    float n3 = getLuminance(uv - vec2(reach, 0.0));

    // FIX: Divide by the fixed baseEps instead of the variable reach!
    float dx = (n2 - n3) / (2.0 * baseEps);
    float dy = (n0 - n1) / (2.0 * baseEps);

    vec2 curl = vec2(dy, -dx);

    // Gently dampen the overall strength as Smoothness scales up so it doesn't spiral out of control
    float dampening = 1.0 / (1.0 + Smoothness * 0.015);
    curl *= dampening;

    // Vertical Bias
    float vb = Vertical_Bias / 100.0;
    curl.x *= (1.0 - vb);
    curl.y *= (1.0 + vb);

    // Swirl
    return curl * (Swirl / 100.0);
}

// ==========================================
// Main Function
// ==========================================
void main() {
    vec2 uv = vUv;

    // Transform Pass
    uv -= 0.5;
    float rad = Rotation * 3.14159265 / 180.0;
    float s = sin(rad), c = cos(rad);
    uv = vec2(uv.x * c - uv.y * s, uv.x * s + uv.y * c);

    vec2 scaleVec = (Uniform_Scaling > 0.5) ? vec2(Scale) : vec2(Scale_Width, Scale_Height);
    scaleVec = max(scaleVec, vec2(0.001)) / 100.0;
    uv /= scaleVec;
    uv += 0.5;
    uv -= Offset;

    vec4 finalColor = vec4(0.0);

    // View Routing
    if (View < 0.5) { // 0 = Input Noise
        finalColor = sampleInputMap(uv);

    } else if (View < 1.5) { // 1 = Curl Generation
        vec2 curlMap = generateCurl(uv);
        finalColor = vec4(curlMap.x * 0.5 + 0.5, curlMap.y * 0.5 + 0.5, 0.5, 1.0);

    } else { // 2 = Final Render (LIC)
        vec2 p = uv;
        float stepSize = Sample_Radius / 1000.0;
        float iters = clamp(Sample_Count, 3.0, 24.0);

        vec4 accColor = vec4(0.0);
        float totalWeight = 0.0;

        for (int i = 0; i < 24; i++) {
            if (float(i) >= iters) break;

            vec2 flowVec = generateCurl(p);
            p += flowVec * stepSize;

            vec4 sampledNode = sampleInputMap(p);

            // Edge Definition (Sharpening the samples dynamically)
            if (Edge_Definition > 0.0) {
                float lum = dot(sampledNode.rgb, vec3(0.299, 0.587, 0.114));
                float contrastAmt = Edge_Definition / 50.0;
                sampledNode.rgb = mix(sampledNode.rgb, vec3(smoothstep(0.5 - 0.1, 0.5 + 0.1, lum)), contrastAmt);
            }

            // Flow Falloff
            float weight = 1.0 - (float(i) / iters) * (Flow_Falloff / 100.0);
            accColor += sampledNode * weight;
            totalWeight += weight;
        }

        finalColor = accColor / totalWeight;

        // Flow Softness
        if (Flow_Softness > 0.0) {
            vec4 rawTex = texture2D(tDiffuse, vUvScaled);
            finalColor = mix(finalColor, rawTex, Flow_Softness / 200.0); 
        }
    }

    // Output Adjustments
    float cont = Contrast / 100.0;
    finalColor.rgb = (finalColor.rgb - 0.5) * max(1.0 + cont, 0.0) + 0.5;
    finalColor.rgb += Brightness / 100.0;

    if (Clip_HDR_Results > 0.5) {
        finalColor.rgb = clamp(finalColor.rgb, 0.0, 1.0);
    }

    if (Channel > 0.5) { // Output Alpha visually
        finalColor = vec4(finalColor.a, finalColor.a, finalColor.a, 1.0);
    } else {
        finalColor.a = 1.0; 
    }

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/curves.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- Panzoid custom properties (Dynamic Numbers) ---
uniform float Channel;     // 0=RGB, 1=R, 2=G, 3=B, 4=A
uniform float Highlights;  // -1..1
uniform float Midtones;    // -1..1
uniform float Shadows;     // -1..1

float clamp01(float x) { return clamp(x, 0.0, 1.0); }

// Cubic Hermite interpolation between yA and yB with slopes mA,mB (dy/dx).
float hermite(float yA, float yB, float mA, float mB, float t, float dx)
{
  float t2 = t * t;
  float t3 = t2 * t;

  float h00 =  2.0*t3 - 3.0*t2 + 1.0;
  float h10 =      t3 - 2.0*t2 + t;
  float h01 = -2.0*t3 + 3.0*t2;
  float h11 =      t3 -     t2;

  return h00*yA + h10*dx*mA + h01*yB + h11*dx*mB;
}

// AE-like 3-point curve (Shadows/Midtones/Highlights) with fixed endpoints.
float curvesAE3(float x, float sh, float mid, float hi)
{
  x = clamp01(x);

  // Control point positions
  const float x0 = 0.00;
  const float x1 = 0.25;
  const float x2 = 0.50;
  const float x3 = 0.75;
  const float x4 = 1.00;

  // Scale user controls: -1..1 -> -0.25..0.25 vertical movement
  // This keeps curve behavior stable and "AE-like" (pulling curve handle).
  float s = 0.25;

  // Control point values (y)
  float y0 = 0.0;
  float y1 = clamp01(x1 + s * sh);
  float y2 = clamp01(x2 + s * mid);
  float y3 = clamp01(x3 + s * hi);
  float y4 = 1.0;

  // Tangents (slopes dy/dx). Catmull-Rom style across uniform spacing.
  // Endpoints use one-sided differences.
  float m0 = (y1 - y0) / (x1 - x0);      // /0.25
  float m1 = (y2 - y0) / (x2 - x0);      // /0.50
  float m2 = (y3 - y1) / (x3 - x1);      // /0.50
  float m3 = (y4 - y2) / (x4 - x2);      // /0.50
  float m4 = (y4 - y3) / (x4 - x3);      // /0.25

  // Evaluate correct segment
  if (x < x1)
  {
    float t = (x - x0) / (x1 - x0);
    return clamp01(hermite(y0, y1, m0, m1, t, (x1 - x0)));
  }
  else if (x < x2)
  {
    float t = (x - x1) / (x2 - x1);
    return clamp01(hermite(y1, y2, m1, m2, t, (x2 - x1)));
  }
  else if (x < x3)
  {
    float t = (x - x2) / (x3 - x2);
    return clamp01(hermite(y2, y3, m2, m3, t, (x3 - x2)));
  }
  else
  {
    float t = (x - x3) / (x4 - x3);
    return clamp01(hermite(y3, y4, m3, m4, t, (x4 - x3)));
  }
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // Round to nearest int (Panzoid uses float uniforms)
  int ch = int(floor(Channel + 0.5));

  // Apply curve depending on channel selection
  if (ch == 0)
  {
    // RGB master: apply same curve to each color channel
    texel.r = curvesAE3(texel.r, Shadows, Midtones, Highlights);
    texel.g = curvesAE3(texel.g, Shadows, Midtones, Highlights);
    texel.b = curvesAE3(texel.b, Shadows, Midtones, Highlights);
  }
  else if (ch == 1)
  {
    texel.r = curvesAE3(texel.r, Shadows, Midtones, Highlights);
  }
  else if (ch == 2)
  {
    texel.g = curvesAE3(texel.g, Shadows, Midtones, Highlights);
  }
  else if (ch == 3)
  {
    texel.b = curvesAE3(texel.b, Shadows, Midtones, Highlights);
  }
  else // ch == 4 (Alpha)
  {
    texel.a = curvesAE3(texel.a, Shadows, Midtones, Highlights);
  }

  gl_FragColor = texel;
}

text./plugins/alipfx/shaders/cyanotype.glsl:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms & Varyings
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom Properties (Dynamic Parameters)
uniform float Chemistry;            // 0: Classic Prussian, 1: Vibrant Wash, 2: Deep Sea, 3: Antique Botanical
uniform float Effect_Strength;     // 0.0 to 1.0
uniform float Exposure;            // 0.0 to 1.0
uniform float Chemical_Contrast;   // 0.0 to 1.0
uniform float Dye_Density;         // 0.0 to 1.0
uniform float Paper_Aging;         // 0.0 to 1.0
uniform float Water_Stains_Fibers; // 0.0 to 1.0
uniform float Pulp_Clumping;       // 0.0 to 1.0

// Pseudo-random hash function for noise generation
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// 2D Value Noise function
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0,0.0)), hash(i + vec2(1.0,0.0)), u.x),
               mix(hash(i + vec2(0.0,1.0)), hash(i + vec2(1.0,1.0)), u.x), u.y);
}

// Fractal Brownian Motion for organic texturing
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    // Rotation matrix to eliminate grid line artifacts
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for (int i = 0; i < 4; ++i) {
        v += a * noise(p);
        p = rot * p * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}

// Generates high-frequency thin organic lines mimicking paper fibers
float getFibers(vec2 uv) {
    float n1 = noise(uv * 380.0);
    float n2 = noise(uv * vec2(8.0, 480.0) + vec2(42.1));
    return smoothstep(0.78, 0.96, n1 * n2);
}

// FIXED: Generates organic chemical water stains instead of artificial blob rings
float getWaterStains(vec2 uv) {
    // Using FBM domain warping for distressed, natural paper staining
    float n = fbm(uv * 15.0);
    float stains = fbm(uv * 35.0 + n * 2.0); 
    return (stains - 0.5) * 0.35;
}

// Multi-stage gradient mapping to recreate the 4 distinct chemical compounds
vec3 applyChemistry(float luma, int mode) {
    vec3 shadowColor;
    vec3 midColor;
    vec3 highlightColor;

    if (mode == 0) { 
        // Classic Prussian
        shadowColor    = vec3(0.02, 0.07, 0.24);
        midColor       = vec3(0.12, 0.36, 0.70);
        highlightColor = vec3(0.93, 0.96, 0.99);
    } else if (mode == 1) { 
        // Vibrant Wash
        shadowColor    = vec3(0.00, 0.10, 0.50);
        midColor       = vec3(0.04, 0.50, 0.98);
        highlightColor = vec3(1.00, 1.00, 1.00);
    } else if (mode == 2) { 
        // Deep Sea
        shadowColor    = vec3(0.005, 0.015, 0.12);
        midColor       = vec3(0.03, 0.15, 0.40);
        highlightColor = vec3(0.85, 0.90, 0.95);
    } else { 
        // Antique Botanical (Mode 3)
        shadowColor    = vec3(0.01, 0.10, 0.20);
        midColor       = vec3(0.15, 0.42, 0.50);
        highlightColor = vec3(0.95, 0.88, 0.76);
    }

    // Smooth dual-zone linear interpolation
    if (luma < 0.5) {
        return mix(shadowColor, midColor, luma * 2.0);
    } else {
        return mix(midColor, highlightColor, (luma - 0.5) * 2.0);
    }
}

void main() {
    // 1. Fetch input texture fragment
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 color = texel.rgb;

    // 2. Exposure Control Slider
    float expFactor = Exposure < 0.5 ? (Exposure * 2.0) : (1.0 + (Exposure - 0.5) * 5.0);
    color *= expFactor;

    // 3. Convert to perceptual grayscale luminance
    float luma = dot(color, vec3(0.299, 0.587, 0.114));

    // 4. Chemical Contrast Control Slider
    float contrastFactor = Chemical_Contrast * 2.0;
    luma = clamp((luma - 0.5) * contrastFactor + 0.5, 0.0, 1.0);

    // 5. Apply selected Chemistry compound
    int chemMode = int(floor(Chemistry + 0.5));
    vec3 cyanotypeColor = applyChemistry(luma, chemMode);

    // 6. Dye Density Slider
    float cyanLuma = dot(cyanotypeColor, vec3(0.299, 0.587, 0.114));
    float densityFactor = Dye_Density * 2.0; 
    cyanotypeColor = mix(vec3(cyanLuma), cyanotypeColor, densityFactor);

    // 7. Paper Aging Slider
    vec3 agedPaperTint = vec3(0.97, 0.92, 0.81);
    float highlightMask = smoothstep(0.25, 1.0, luma);
    cyanotypeColor = mix(cyanotypeColor, cyanotypeColor * agedPaperTint, Paper_Aging * highlightMask);

    // FIXED: 8. Pulp Clumping Slider
    // Increased scale from 9.0 to 120.0 to create fine paper grit rather than massive clouds
    float clumps = fbm(vUvScaled * 120.0);
    float clumpMod = (clumps - 0.5) * 0.15 * Pulp_Clumping;
    cyanotypeColor += clumpMod;

    // FIXED: 9. Water Stains & Fibers Slider
    // Cleaned up the blending math to layer the grit correctly
    float organicFibers = getFibers(vUvScaled);
    float waterStains   = getWaterStains(vUvScaled);
    float textureMix    = (organicFibers * 0.30 + waterStains) * Water_Stains_Fibers;
    cyanotypeColor      = clamp(cyanotypeColor + textureMix, 0.0, 1.0);

    // 10. Blend output with original frame via Effect Strength
    vec3 finalOutput = mix(texel.rgb, cyanotypeColor, Effect_Strength);

    gl_FragColor = vec4(finalOutput, texel.a);
}

text./plugins/alipfx/shaders/deep-glow.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

uniform float Intensity;
uniform float Threshold;
uniform float SoftKnee;
uniform float Streaks;
uniform float Chromatic;
uniform float Saturation;
uniform float Vignette;

uniform float Gamma_Correction;
uniform float Scene_Gamma;

uniform float Aspect_Ratio;
uniform float Aspect_Angle;

uniform vec3 Color_Inner;
uniform vec3 Color_Outer;
uniform float Tint_Mode;
uniform float Tint_Blend_Mode;

float luma(vec3 c)
{
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

float satf(float x)
{
    return clamp(x, 0.0, 1.0);
}

vec3 toLinear(vec3 c)
{
    float g = max(Scene_Gamma, 0.0001);
    return pow(max(c, 0.0), vec3(g));
}

vec3 toGamma(vec3 c)
{
    float g = max(Scene_Gamma, 0.0001);
    return pow(max(c, 0.0), vec3(1.0 / g));
}

vec3 sampleLinear(vec2 uv)
{
    vec3 c = texture2D(tDiffuse, uv).rgb;
    float gc = satf(Gamma_Correction / 100.0);
    return mix(c, toLinear(c), gc);
}

vec3 brightPass(vec3 c)
{
    float y = luma(c);
    float knee = max(SoftKnee, 0.0001);
    float m = smoothstep(Threshold - knee, Threshold + knee, y);
    return max(c - vec3(Threshold), 0.0) * m;
}

vec3 saturateColor(vec3 c, float s)
{
    float y = luma(c);
    return mix(vec3(y), c, s);
}

vec3 blendMultiply(vec3 base, vec3 blend)
{
    return base * blend;
}

vec3 blendOverlay(vec3 base, vec3 blend)
{
    vec3 low = 2.0 * base * blend;
    vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
    return mix(low, high, step(vec3(0.5), base));
}

vec3 blendSoftLight(vec3 base, vec3 blend)
{
    vec3 d = step(vec3(0.5), blend);
    vec3 low = base - (1.0 - 2.0 * blend) * base * (1.0 - base);
    vec3 high = base + (2.0 * blend - 1.0) * (sqrt(max(base, 0.0)) - base);
    return mix(low, high, d);
}

vec3 applyTintBlend(vec3 glow, vec3 tint)
{
    if (Tint_Blend_Mode < 0.5)
    {
        return blendMultiply(glow, tint);
    }
    else if (Tint_Blend_Mode < 1.5)
    {
        return blendOverlay(glow, tint);
    }
    return blendSoftLight(glow, tint);
}

vec3 getTintColor(float distNorm)
{
    if (Tint_Mode < 0.5)
    {
        return vec3(1.0);
    }
    else if (Tint_Mode < 1.5)
    {
        return clamp((Color_Inner + Color_Outer) * 0.5, 0.0, 1.0);
    }
    return mix(clamp(Color_Inner, 0.0, 1.0), clamp(Color_Outer, 0.0, 1.0), satf(distNorm));
}

vec2 rotateVec(vec2 d, float angleRad)
{
    float s = sin(angleRad);
    float c = cos(angleRad);
    return vec2(
        c * d.x - s * d.y,
        s * d.x + c * d.y
    );
}

// Stretch in local kernel space, then rotate in 2D (Z-style rotation)
vec2 orientOffset(vec2 d)
{
    float a = radians(Aspect_Angle);
    float ar = max(Aspect_Ratio, 0.0001);

    d.x *= ar;
    return rotateVec(d, a);
}

vec2 perp(vec2 v)
{
    return vec2(-v.y, v.x);
}

vec3 tintedGlow(vec3 glow, float distNorm)
{
    if (Tint_Mode < 0.5)
    {
        return glow;
    }

    vec3 tint = getTintColor(distNorm);
    return applyTintBlend(glow, tint);
}

vec2 safeDir(vec2 v)
{
    float lenV = length(v);
    if (lenV < 0.0001)
    {
        return vec2(1.0, 0.0);
    }
    return v / lenV;
}

vec3 chromaticBrightPass(vec2 uv, vec2 ca)
{
    vec3 normal = brightPass(sampleLinear(uv));

    float c = satf(Chromatic);
    if (c <= 0.0001)
    {
        return normal;
    }

    vec3 split;
    split.r = brightPass(sampleLinear(uv + ca)).r;
    split.g = normal.g;
    split.b = brightPass(sampleLinear(uv - ca)).b;

    return mix(normal, split, c);
}

void main()
{
    vec2 uv = vUvScaled;
    vec2 px = 1.0 / max(resolution, vec2(1.0));

    vec4 centerTex = texture2D(tDiffuse, uv);
    float gc = satf(Gamma_Correction / 100.0);
    vec3 center = mix(centerTex.rgb, toLinear(centerTex.rgb), gc);

    float spread = 2.5;

    vec2 o1 = orientOffset(px * spread * 1.0);
    vec2 o2 = orientOffset(px * spread * 2.0);
    vec2 o3 = orientOffset(px * spread * 3.5);

    vec2 p1 = perp(o1);
    vec2 p2 = perp(o2);
    vec2 p3 = perp(o3);

    vec3 bloom = vec3(0.0);
    vec3 streak = vec3(0.0);

    vec2 caDir = safeDir(uv - vec2(0.5));
    vec2 caBase = orientOffset(caDir * px * (2.0 + spread) * 2.5);

    // Rotated 4-direction bloom kernel
    bloom += chromaticBrightPass(uv + o1, caBase * 0.6) * 0.18;
    bloom += chromaticBrightPass(uv - o1, caBase * 0.6) * 0.18;
    bloom += chromaticBrightPass(uv + p1, caBase * 0.6) * 0.18;
    bloom += chromaticBrightPass(uv - p1, caBase * 0.6) * 0.18;

    bloom += chromaticBrightPass(uv + o2, caBase * 1.0) * 0.13;
    bloom += chromaticBrightPass(uv - o2, caBase * 1.0) * 0.13;
    bloom += chromaticBrightPass(uv + p2, caBase * 1.0) * 0.13;
    bloom += chromaticBrightPass(uv - p2, caBase * 1.0) * 0.13;

    bloom += chromaticBrightPass(uv + o3, caBase * 1.4) * 0.08;
    bloom += chromaticBrightPass(uv - o3, caBase * 1.4) * 0.08;
    bloom += chromaticBrightPass(uv + p3, caBase * 1.4) * 0.08;
    bloom += chromaticBrightPass(uv - p3, caBase * 1.4) * 0.08;

    float streakAmt = max(Streaks, 0.0);
    if (streakAmt > 0.0)
    {
        vec2 sx = orientOffset(px * spread * 6.0);
        vec2 sy = orientOffset(px * spread * 4.0);
        vec2 psx = perp(sx);
        vec2 psy = perp(sy);

        streak += chromaticBrightPass(uv + sx, caBase * 2.0) * 0.20;
        streak += chromaticBrightPass(uv - sx, caBase * 2.0) * 0.20;
        streak += chromaticBrightPass(uv + psx, caBase * 2.0) * 0.20;
        streak += chromaticBrightPass(uv - psx, caBase * 2.0) * 0.20;

        streak += chromaticBrightPass(uv + sy, caBase * 2.0) * 0.12;
        streak += chromaticBrightPass(uv - sy, caBase * 2.0) * 0.12;
        streak += chromaticBrightPass(uv + psy, caBase * 2.0) * 0.12;
        streak += chromaticBrightPass(uv - psy, caBase * 2.0) * 0.12;
    }

    vec3 glow = bloom + streak * streakAmt;
    glow = glow * max(Intensity, 0.0);

    float distNorm = 0.65;
    vec3 tinted = tintedGlow(glow, distNorm);

    tinted = tinted / (1.0 + tinted);

    vec3 outCol = center + tinted * 1.8;

    outCol = saturateColor(outCol, max(Saturation, 0.0));

    vec2 p = vUv - 0.5;
    float vig = 1.0 - max(Vignette, 0.0) * smoothstep(0.08, 0.80, dot(p, p));
    outCol *= vig;

    outCol = mix(outCol, toGamma(outCol), gc);
    outCol = clamp(outCol, 0.0, 1.0);

    gl_FragColor = vec4(outCol, centerTex.a);
}

text./plugins/alipfx/shaders/dot-pixel.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
varying vec2 vUv;
varying vec2 vUvScaled;

// Custom properties from Panzoid
uniform vec2 Image_Center;
uniform float Dimension_Factor;
uniform float Outer_Roundness;
uniform float Inner_Radius;
uniform float Shading;
uniform float Shading_Type;  // 0 = Sphere, 1 = Ring
uniform float Fill_Background;  // 0 = Disabled, 1 = Enabled
uniform vec3 BG_Color;

// Helper function to convert UV to pixel coordinates
vec2 uvToPixel(vec2 uv) {
    return uv * resolution;
}

// Helper function to convert pixel coordinates to UV
vec2 pixelToUv(vec2 pixel) {
    return pixel / resolution;
}

void main()
{
    // Get the current pixel position in screen space
    vec2 pixelPos = uvToPixel(vUvScaled);

    // The center point in pixel coordinates
    vec2 centerPixel = Image_Center;

    // Calculate the relative position from the center
    vec2 relPos = pixelPos - centerPixel;

    // Dimension Factor determines the size of each pixel block
    // Higher Dimension Factor = larger blocks
    float blockSize = max(Dimension_Factor, 1.0);

    // Calculate which block this pixel belongs to
    // Using floor to create the pixelation effect
    vec2 blockIndex = floor(relPos / blockSize);
    vec2 blockCenter = (blockIndex + 0.5) * blockSize + centerPixel;

    // Calculate the position within the block (0 to 1 range within block)
    vec2 withinBlock = (relPos - blockIndex * blockSize) / blockSize;
    vec2 centeredWithinBlock = withinBlock - 0.5;

    // Distance from center of block (0 to ~0.707 at corners)
    float distFromBlockCenter = length(centeredWithinBlock);

    // Sample the original image at the block center to get the color
    vec2 blockCenterUv = pixelToUv(blockCenter);
    vec4 texel = texture2D(tDiffuse, blockCenterUv);

    // Calculate outer radius threshold
    // Outer Roundness: higher value = smaller circles
    // When Outer Roundness is 0, circles fill the entire block (touching neighbors)
    // When Outer Roundness increases, circles get smaller
    // The default in AE was 16 with block size 12, giving rings

    // Map Outer Roundness to an actual radius
    // At 0, radius is 0.5 (fills block, touching neighbors)
    // As Outer Roundness increases, radius decreases
    float outerRadius = max(0.5 - Outer_Roundness / (2.0 * blockSize), 0.0);

    // Alternative interpretation: Outer Roundness directly controls the gap
    // Let's match the video behavior:
    // At Outer_Roundness = 16, blockSize = 12: we see distinct circles with gaps
    // At Outer_Roundness = 0, blockSize = 6: circles are larger, almost touching

    // The outer radius in block-space (0 to 0.5)
    // When blockSize is small, same Outer_Roundness should give same visual gap
    float outerRadiusBlock = max(0.5 - Outer_Roundness / (2.0 * max(blockSize, 1.0)), 0.0);

    // Inner radius in block-space
    // Inner Radius controls the hole in the ring
    // Higher Inner Radius = larger hole = thinner ring
    float innerRadiusBlock = min(Inner_Radius / (2.0 * max(blockSize, 1.0)), outerRadiusBlock);

    // Determine if this pixel is inside the circle/ring
    float inCircle = step(distFromBlockCenter, outerRadiusBlock);
    float inHole = step(distFromBlockCenter, innerRadiusBlock);
    float inRing = inCircle * (1.0 - inHole);

    // Calculate shading
    float shadingValue = 0.0;
    if (Shading > 0.0) {
        if (Shading_Type < 0.5) {
            // Sphere shading - creates 3D sphere look
            // Based on distance from center, creating a gradient
            float normalizedDist = distFromBlockCenter / max(outerRadiusBlock, 0.001);
            // Sphere shading: brighter in center, darker at edges
            // Using sqrt(1 - r^2) for hemisphere projection
            if (normalizedDist < 1.0) {
                shadingValue = sqrt(1.0 - normalizedDist * normalizedDist) * Shading;
            }
        } else {
            // Ring shading - shading only on the ring itself
            // Creates a 3D tube/ring appearance
            float normalizedDist = distFromBlockCenter / max(outerRadiusBlock, 0.001);
            float ringCenter = (outerRadiusBlock + innerRadiusBlock) / (2.0 * max(outerRadiusBlock, 0.001));
            float ringWidth = (outerRadiusBlock - innerRadiusBlock) / max(outerRadiusBlock, 0.001);

            if (normalizedDist > innerRadiusBlock / max(outerRadiusBlock, 0.001) && 
                normalizedDist < 1.0) {
                // Cross-section of a tube
                float tubeDist = abs(normalizedDist - (outerRadiusBlock + innerRadiusBlock) / (2.0 * outerRadiusBlock));
                tubeDist = tubeDist / max((outerRadiusBlock - innerRadiusBlock) / (2.0 * outerRadiusBlock), 0.001);
                if (tubeDist < 1.0) {
                    shadingValue = sqrt(1.0 - tubeDist * tubeDist) * Shading;
                }
            }
        }
    }

    // Apply shading to color
    vec3 finalColor = texel.rgb;
    if (Shading > 0.0) {
        if (Shading_Type < 0.5) {
            // Sphere: multiply by shading (darker at edges)
            finalColor = finalColor * (0.5 + 0.5 * shadingValue);
        } else {
            // Ring: add shading highlight
            finalColor = finalColor + vec3(shadingValue * 0.5);
        }
    }

    // Output color
    vec4 outputColor;
    if (inRing > 0.5) {
        outputColor = vec4(finalColor, texel.a);
    } else {
        // Outside the ring
        if (Fill_Background > 0.5) {
            outputColor = vec4(BG_Color, 1.0);
        } else {
            outputColor = vec4(0.0, 0.0, 0.0, 0.0);
        }
    }

    gl_FragColor = outputColor;
}

text./plugins/alipfx/shaders/drop-shadow.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform vec3 Shadow_Color;   // Color
uniform float Opacity;       // 0..100 (%)
uniform float Direction;     // degrees
uniform float Distance;      // pixels
uniform float Softness;      // blur amount
uniform float Shadow_Only;   // 0 or 1

varying vec2 vUvScaled;

// ------------------------------------------------------------
// Safe sampling: outside bounds -> 0 (prevents edge smearing)
// ------------------------------------------------------------
float inBounds(vec2 uv) {
  float inX = step(0.0, uv.x) * step(uv.x, uvScale.x);
  float inY = step(0.0, uv.y) * step(uv.y, uvScale.y);
  return inX * inY;
}

vec4 sampleSafe(vec2 uv) {
  float m = inBounds(uv);
  vec2 uvc = clamp(uv, vec2(0.0), uvScale);
  return texture2D(tDiffuse, uvc) * m;
}

float sampleAlphaSafe(vec2 uv) {
  return sampleSafe(uv).a;
}

// ------------------------------------------------------------
// Hash for stable per-pixel rotation/jitter
// ------------------------------------------------------------
float hash12(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453123);
}

// ------------------------------------------------------------
// Linear-light compositing helpers (approx sRGB)
// AE linearized workflow removes gamma in working space, which
// affects blending/resampling and edge falloff. [1](https://support.emerson.edu/hc/en-us/articles/21709271104539-Color-Management-in-After-Effects)[2](https://helpx.adobe.com/after-effects/using/blending-modes-layer-styles.html)
// ------------------------------------------------------------
vec3 srgbToLinear(vec3 c) {
  // Simple approximation (fast): gamma 2.2
  return pow(max(c, vec3(0.0)), vec3(2.2));
}

vec3 linearToSrgb(vec3 c) {
  return pow(max(c, vec3(0.0)), vec3(1.0 / 2.2));
}

void main()
{
  vec4 src = texture2D(tDiffuse, vUvScaled);

  // AE-like direction: 0=right, 90=down
  float ang = radians(Direction);
  vec2 dir = vec2(cos(ang), -sin(ang));

  // UV size of 1 pixel in scaled buffer
  vec2 px = uvScale / resolution;

  // Shadow offset in UV
  vec2 shadowOffset = dir * Distance * px;

  // Shadow is source alpha shifted by +offset => sample at uv - offset
  vec2 baseUV = vUvScaled - shadowOffset;

  // ------------------------------------------------------------
  // Softness mapping tuned for AE (linearized)
  // Your earlier curve made 50 too strong and 100~200 too close.
  // AE blur behaves like increasing sample radius/area. [3](blob:https://www.microsoft365.com/a6593026-59af-47b3-9486-bb62cdc03421)[4](blob:https://www.microsoft365.com/a4ae5a20-e366-478c-9bdd-3c1ffe7abea5)
  // ------------------------------------------------------------
  const float AE_SOFTNESS_SCALE = 0.60; // start point for AE linearized match
  float blurPx = max(Softness, 0.0) * AE_SOFTNESS_SCALE;

  float shadowA = 0.0;

  if (blurPx <= 0.001) {
    shadowA = sampleAlphaSafe(baseUV);
  } else {
    // Per-pixel rotation reduces patterning
    vec2 pix = (vUvScaled / uvScale) * resolution;
    float rnd = hash12(floor(pix));
    float rotAng = rnd * 6.28318530718;

    // 32 taps total = 1 center + 31 spiral taps
    const float GOLDEN_ANGLE = 2.399963229728653; // pi*(3 - sqrt(5))
    const float INV_N = 1.0 / 31.0;

    // Sigma controls falloff "creaminess".
    // In linear blending, edges look different than gamma blending. [1](https://support.emerson.edu/hc/en-us/articles/21709271104539-Color-Management-in-After-Effects)[2](https://helpx.adobe.com/after-effects/using/blending-modes-layer-styles.html)
    float sigma = max(blurPx * 0.55, 0.0001);
    float invTwoSigma2 = 1.0 / (2.0 * sigma * sigma);

    // Small radius jitter hides subtle rings
    float jitter = 0.92 + 0.16 * hash12(floor(pix) + vec2(19.19, 73.73));

    float wsum = 1.0;
    shadowA = sampleAlphaSafe(baseUV); // center

    for (int i = 0; i < 31; i++) {
      float fi = float(i);

      // even disk coverage: r ~ sqrt(t)
      float t = (fi + 0.5) * INV_N;
      float r = blurPx * sqrt(t) * jitter;

      float a = rotAng + fi * GOLDEN_ANGLE;
      vec2 d = vec2(cos(a), sin(a));

      vec2 o = d * r * px;

      float w = exp(-(r * r) * invTwoSigma2);
      shadowA += sampleAlphaSafe(baseUV + o) * w;
      wsum += w;
    }

    shadowA /= max(wsum, 1e-6);
  }

  // Opacity (% like AE)
  shadowA *= clamp(Opacity * 0.01, 0.0, 1.0);

  // Shadow color in linear
  vec3 shLin = srgbToLinear(Shadow_Color);

  // Source in linear (for AE-linear-like blending)
  vec3 srcLin = srgbToLinear(src.rgb);

  // Premult in linear
  vec3 shPM  = shLin * shadowA;
  vec3 srcPM = srcLin * src.a;

  // AE order: SOURCE over SHADOW (shadow behind)
  float outA  = src.a + shadowA * (1.0 - src.a);
  vec3  outPM = srcPM + shPM * (1.0 - src.a);

  // Shadow Only
  if (Shadow_Only >= 0.5) {
    float a = shadowA;
    vec3 pm = shPM;
    vec3 rgbLin = (a > 1e-6) ? (pm / a) : vec3(0.0);
    gl_FragColor = vec4(linearToSrgb(rgbLin), a);
    return;
  }

  // Back to straight alpha + convert back to sRGB
  vec3 outLin = (outA > 1e-6) ? (outPM / outA) : vec3(0.0);
  gl_FragColor = vec4(linearToSrgb(outLin), outA);
}

text./plugins/alipfx/shaders/echo-2.glsl:
precision highp float;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUv;

// Echo parameters
uniform float echoTime;        // Time offset per echo (negative = behind, positive = front)
uniform int numEchoes;         // Number of echoes
uniform float startIntensity;  // Starting opacity
uniform float decay;           // Opacity decay per echo
uniform int echoOperator;      // Blend mode

// Object position (animated)
uniform vec2 objectPosition;   // Current position in pixels

vec4 blendColors(vec4 base, vec4 newColor, int mode) {
    if (mode == 0) return base + newColor; // Add
    if (mode == 1) return max(base, newColor); // Maximum
    if (mode == 2) return min(base, newColor); // Minimum
    if (mode == 3) return 1.0 - (1.0 - base) * (1.0 - newColor); // Screen
    if (mode == 4) return newColor; // Composite In Back
    if (mode == 5) return base; // Composite In Front
    if (mode == 6) return mix(base, newColor, newColor.a); // Blend
    return base;
}

void main() {
    vec4 finalColor = vec4(0.0);
    float intensity = startIntensity;

    // Normalize object position to UV space
    vec2 normalizedPos = objectPosition / resolution;

    for (int i = 0; i < 100; i++) {
        if (i >= numEchoes) break;

        // Compute offset based on object position and echo index
        vec2 offsetDir = normalizedPos * sign(echoTime); // Direction depends on echoTime sign
        vec2 uvOffset = vUv - offsetDir * abs(echoTime) * float(i) * 0.1;

        vec4 sampleColor = texture2D(tDiffuse, uvOffset) * intensity;

        finalColor = (i == 0) ? sampleColor : blendColors(finalColor, sampleColor, echoOperator);

        intensity *= decay; // Fade out each subsequent echo
    }

    gl_FragColor = finalColor;
}

