text./plugins/alipfx/shaders/element-glow.gls:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms & Varyings
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

// --- 18 Custom Parameters (Mapped to Panzoid Uniforms) ---
// Glow Selection
uniform float Solid_Inner;      // Controls the hard selected range threshold
uniform float Filled_Band;      // Mask strength multiplier / boost
uniform float Outer_Soft;       // Controls the feathering range
uniform float Range_Mode;       // 0:Luminance, 1:Lightness, 2:Hue, 3:Saturation, 4:R, 5:G, 6:B, 7:A
uniform float Invert_Range;     // 0: Disabled, 1: Enabled

// Glow Engine Settings
uniform float Radius;           // Spread/size of the bloom
uniform float Intensity;        // Brightness/overdrive multiplier
uniform float Blend;            // 0: Add, 1: Screen, 2: Normal, 3: Under

// Tint Gradient Controls
uniform float Tint;             // 0: Disabled (Original Colors), 1: Enabled (Gradient Colors)
uniform vec3 Color_1;
uniform vec3 Color_2;
uniform vec3 Color_3;
uniform vec3 Color_4;
uniform vec3 Color_5;
uniform vec3 Color_6;
uniform vec3 Color_7;
uniform vec3 Color_8;
uniform float Gradient_Colors;  // Number of active gradient colors (1.0 to 8.0)

// Helper: Convert RGB to HSV for Hue/Saturation selection tracking
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

// Evaluates the pixel's target attribute based on the selected Range Mode
float getSelectionValue(vec4 texel) {
    float val = 0.0;
    int mode = int(Range_Mode + 0.5);

    if (mode == 0) {
        val = dot(texel.rgb, vec3(0.2126, 0.7152, 0.0722)); // Luminance
    } else if (mode == 1) {
        val = (texel.r + texel.g + texel.b) / 3.0; // Lightness
    } else if (mode == 2) {
        val = rgb2hsv(texel.rgb).x; // Hue
    } else if (mode == 3) {
        val = rgb2hsv(texel.rgb).y; // Saturation
    } else if (mode == 4) {
        val = texel.r; // Red
    } else if (mode == 5) {
        val = texel.g; // Green
    } else if (mode == 6) {
        val = texel.b; // Blue
    } else if (mode == 7) {
        val = texel.a; // Alpha
    }

    // Generate soft threshold mask using Solid Inner and Outer Soft properties
    float soft = max(Outer_Soft, 0.001);
    float mask = smoothstep(Solid_Inner - soft, Solid_Inner, val);

    // Scale by Filled Band mask strength control
    mask *= Filled_Band;

    // Handle Invert Range switch
    if (Invert_Range > 0.5) {
        mask = 1.0 - mask;
    }

    return clamp(mask, 0.0, 1.0);
}

// Multi-stop color gradient ramp evaluator (Handles up to 8 stops safely)
vec3 getGradientColor(float t) {
    int numColors = int(clamp(Gradient_Colors, 1.0, 8.0) + 0.5);
    if (numColors <= 1) return Color_1;

    float scaledT = t * float(numColors - 1);
    int index = int(floor(scaledT));
    float fraction = fract(scaledT);

    vec3 c1 = Color_1;
    vec3 c2 = Color_2;

    if (index == 0) { c1 = Color_1; c2 = Color_2; }
    else if (index == 1) { c1 = Color_2; c2 = Color_3; }
    else if (index == 2) { c1 = Color_3; c2 = Color_4; }
    else if (index == 3) { c1 = Color_4; c2 = Color_5; }
    else if (index == 4) { c1 = Color_5; c2 = Color_6; }
    else if (index == 5) { c1 = Color_6; c2 = Color_7; }
    else if (index == 6) { c1 = Color_7; c2 = Color_8; }
    else { c1 = Color_8; c2 = Color_8; }

    return mix(c1, c2, fraction);
}

// Samples and builds isolated glow source data before blurring
vec4 sampleGlowSource(vec2 uv) {
    vec4 texel = texture2D(tDiffuse, uv);
    float mask = getSelectionValue(texel);

    // Decide between original source colors or the custom gradient ramp based on Tint parameter
    vec3 glowColor = texel.rgb;
    if (Tint > 0.5) {
        glowColor = getGradientColor(mask);
    }

    // Output weighted color energy along with isolation alpha
    return vec4(glowColor * mask * (Intensity / 100.0), mask);
}

void main() {
    vec4 sourceTexel = texture2D(tDiffuse, vUvScaled);

    // --- Silky Bloom High-End Single Pass Blur Loop ---
    vec4 accumulatedGlow = vec4(0.0);
    float totalWeight = 0.0;

    const int STEPS = 4;
    const int DIRS = 4;

    // Center sample anchor weight
    accumulatedGlow += sampleGlowSource(vUvScaled) * 2.0;
    totalWeight += 2.0;

    for (int d = 0; d < DIRS; d++) {
        float angle = float(d) * (6.2831853 / float(DIRS));
        vec2 direction = vec2(cos(angle), sin(angle));

        for (int s = 1; s <= STEPS; s++) {
            float progress = float(s) / float(STEPS);
            float weight = 1.0 - progress; // Linear-Gaussian decay falloff distribution

            vec2 offset = direction * (progress * Radius) / resolution;

            accumulatedGlow += sampleGlowSource(vUvScaled + offset) * weight;
            accumulatedGlow += sampleGlowSource(vUvScaled - offset) * weight;
            totalWeight += weight * 2.0;
        }
    }

    vec4 finalGlow = accumulatedGlow / totalWeight;
    vec3 outputColor = sourceTexel.rgb;
    int blendMode = int(Blend + 0.5);

    // --- Element Glow Compositing Modes Execution ---
    if (blendMode == 0) { 
        outputColor = sourceTexel.rgb + finalGlow.rgb; // Add
    } 
    else if (blendMode == 1) { 
        outputColor = sourceTexel.rgb + finalGlow.rgb - (sourceTexel.rgb * finalGlow.rgb); // Screen
    } 
    else if (blendMode == 2) { 
        float glowAlpha = clamp(length(finalGlow.rgb), 0.0, 1.0); // Normal
        outputColor = mix(sourceTexel.rgb, finalGlow.rgb, glowAlpha);
    } 
    else if (blendMode == 3) { 
        float originalMask = getSelectionValue(sourceTexel); // Under
        outputColor = mix(finalGlow.rgb, sourceTexel.rgb, originalMask);
    }

    gl_FragColor = vec4(outputColor, sourceTexel.a);
}

text./plugins/alipfx/shaders/ellipse.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// ---- Custom properties (spaces become underscores) ----
uniform vec2 Center;                 // pixels, AE-style (top-left origin, Y down)
uniform float Width;                 // pixels
uniform float Height;                // pixels
uniform float Thickness;             // pixels (stroke width centered on ellipse boundary)
uniform float Softness;              // percent 0..100
uniform vec3 Inside_Color;           // inner edge color of ring / fill color
uniform vec3 Outside_Color;          // OUTER edge (outline) color of ring
uniform float Composite_On_Original; // 0 or 1

float sdEllipseImplicit(vec2 p, vec2 r)
{
    r = max(r, vec2(1e-4));
    float a2 = r.x * r.x;
    float b2 = r.y * r.y;

    float F = (p.x * p.x) / a2 + (p.y * p.y) / b2 - 1.0;
    vec2 g = vec2(2.0 * p.x / a2, 2.0 * p.y / b2);

    return F / max(length(g), 1e-6);
}

float aaPx() { return 1.0; }

float maskRing(float sd, float halfThicknessPx, float featherPx)
{
    float f = max(featherPx, aaPx());
    float d = abs(sd);
    return 1.0 - smoothstep(halfThicknessPx, halfThicknessPx + f, d);
}

float maskFill(float sd, float featherPx)
{
    float f = max(featherPx, aaPx());
    return 1.0 - smoothstep(0.0, f, sd);
}

void main()
{
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    vec2 pixelPos = vUv * resolution;
    vec2 centerPx = vec2(Center.x, resolution.y - Center.y);

    vec2 radii = 0.5 * vec2(Width, Height);
    vec2 p = pixelPos - centerPx;

    float sd = sdEllipseImplicit(p, radii);

    float t = max(Thickness, 0.0);
    float halfT = 0.5 * t;

    // --- Softness as % of Thickness (0..100) ---
    float s01 = clamp(Softness * 0.01, 0.0, 1.0);
    float featherRingPx = s01 * Thickness; // <-- % of Thickness (A)

    // Fill softness can remain size-based (your original behavior)
    float featherFillPx = s01 * max(min(radii.x, radii.y), 1.0);

    vec3 shapeRGB = vec3(0.0);
    float shapeA = 0.0;

    if (t > 0.0)
    {
        shapeA = maskRing(sd, halfT, featherRingPx);

        float u = clamp((sd + halfT) / max(t, 1e-6), 0.0, 1.0);

        const float OUTLINE_BIAS = 3.0;
        float ub = pow(u, OUTLINE_BIAS);

        shapeRGB = mix(Inside_Color, Outside_Color, ub);
    }
    else
    {
        shapeA = maskFill(sd, featherFillPx);
        shapeRGB = Inside_Color;
    }

    vec3 outRGB;
    float outA;

    if (Composite_On_Original >= 0.5)
    {
        outRGB = mix(texel.rgb, shapeRGB, shapeA);
        outA = max(texel.a, shapeA);
    }
    else
    {
        outRGB = shapeRGB;
        outA = shapeA;
    }

    gl_FragColor = vec4(outRGB, outA);
}

text./plugins/alipfx/shaders/engraving.glsl:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// Custom Properties
uniform float Preset;
uniform vec3 Ink_Color;
uniform vec3 Paper_Color;
uniform float Pre_Exposure;
uniform float Tone_Contrast;
uniform float Line_Density;
uniform float Contour_Flow;
uniform float Edge_Etching;
uniform float Wear_Tear;

// Pseudo-random noise generator for Wear & Tear
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

void main()
{
    // 1. Fetch Source Pixel
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // 2. Base Luminance (Grayscale conversion)
    float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114));

    // 3. Pre-Exposure Control
    luma = clamp(luma * (Pre_Exposure * 2.0), 0.0, 1.0);

    // 4. Tone Contrast Control
    float contrastFactor = Tone_Contrast * 2.5;
    luma = clamp((luma - 0.5) * contrastFactor + 0.5, 0.0, 1.0);

    // 5. Edge Etching Analysis (Sobel Filter approximation)
    vec2 texelSize = 1.0 / resolution;
    float lLeft  = dot(texture2D(tDiffuse, vUvScaled + vec2(-texelSize.x, 0.0)).rgb, vec3(0.299, 0.587, 0.114));
    float lRight = dot(texture2D(tDiffuse, vUvScaled + vec2(texelSize.x, 0.0)).rgb, vec3(0.299, 0.587, 0.114));
    float lTop   = dot(texture2D(tDiffuse, vUvScaled + vec2(0.0, texelSize.y)).rgb, vec3(0.299, 0.587, 0.114));
    float lBot   = dot(texture2D(tDiffuse, vUvScaled + vec2(0.0, -texelSize.y)).rgb, vec3(0.299, 0.587, 0.114));
    float edgeVal = sqrt((lRight - lLeft) * (lRight - lLeft) + (lTop - lBot) * (lTop - lBot));

    // 6. Contour Flow & Diagonal Line Generation
    float frequency = Line_Density * 350.0; 
    float waveOffset = luma * Contour_Flow * 35.0;

    // Calculate diagonal coordinates (45-degree angle rotation)
    float diagonalCoord = (vUvScaled.x + vUvScaled.y) * 0.7071;

    // Generate the base line pattern
    float linePattern = sin((diagonalCoord * frequency) + waveOffset);
    // Normalize sine pattern range from [-1, 1] to [0, 1]
    linePattern = (linePattern + 1.0) * 0.5;

    // Inversion Fix: Modulate thickness so dark luma generates thick ink lines
    float sharpness = 0.15;
    float finalLine = smoothstep(linePattern - sharpness, linePattern + sharpness, luma);

    // Apply Edge Etching boundaries (burns dark lines into high contrast seams)
    finalLine = mix(finalLine, 0.0, clamp(edgeVal * Edge_Etching * 5.0, 0.0, 1.0));

    // 7. Wear & Tear (Simulates distressed paper / ink flecks)
    float noise = rand(vUvScaled * resolution.xy);
    if (Wear_Tear > 0.01) {
        float thresholdInk = Wear_Tear * 0.12;
        float thresholdPaper = 1.0 - (Wear_Tear * 0.12);
        if (noise < thresholdInk) {
            finalLine = 0.0; // Ink flecks (Dark)
        } else if (noise > thresholdPaper) {
            finalLine = 1.0; // Paper chips (Light)
        }
    }

    // 8. Preset Setup & Color Logic
    vec3 activeInk = Ink_Color;
    vec3 activePaper = Paper_Color;

    if (Preset > 0.5 && Preset < 1.5) { 
        // 1: Banknote Green
        activeInk = vec3(0.0392, 0.2275, 0.1569);   
        activePaper = vec3(0.9490, 0.9608, 0.9294); 
    } 
    else if (Preset > 1.5 && Preset < 2.5) { 
        // 2: Copperplate
        activeInk = vec3(0.1490, 0.0824, 0.0510);   
        activePaper = vec3(0.9686, 0.9490, 0.9098); 
    } 
    else if (Preset > 2.5 && Preset < 3.5) { 
        // 3: Steel Etching
        activeInk = vec3(0.0706, 0.0941, 0.1412);   
        activePaper = vec3(0.9098, 0.9176, 0.9020); 
    } 
    else if (Preset > 3.5 && Preset < 4.5) { 
        // 4: Carmine Stamp
        activeInk = vec3(0.3490, 0.0431, 0.0902);   
        activePaper = vec3(1.0000, 0.9608, 0.9608); 
    }

    // 9. Output Composite Layer
    vec3 composition = mix(activeInk, activePaper, finalLine);
    gl_FragColor = vec4(composition, texel.a);
}

text./plugins/alipfx/shaders/exposure.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// 1) Channels
// 0.0 = Master
// 1.0 = Individual Channels
uniform float Channels;

// 2-4) Master controls
uniform float Exposure;
uniform float Offset;
uniform float Gamma_Correction;

// 5-7) Red controls
uniform float Red_Exposure;
uniform float Red_Offset;
uniform float Red_Gamma_Correction;

// 8-10) Green controls
uniform float Green_Exposure;
uniform float Green_Offset;
uniform float Green_Gamma_Correction;

// 11-13) Blue controls
uniform float Blue_Exposure;
uniform float Blue_Offset;
uniform float Blue_Gamma_Correction;

// 14) Bypass Linear Light Conversion
// 0.0 = Disabled  (convert to linear -> process -> convert back)
// 1.0 = Enabled   (process raw/gamma-encoded pixels directly)
uniform float Bypass_Linear_Light_Conversion;

const float EPSILON = 1e-6;

// sRGB -> Linear
float srgbToLinear1(float x)
{
    if (x <= 0.04045) return x / 12.92;
    return pow((x + 0.055) / 1.055, 2.4);
}

vec3 srgbToLinear(vec3 c)
{
    return vec3(
        srgbToLinear1(c.r),
        srgbToLinear1(c.g),
        srgbToLinear1(c.b)
    );
}

// Linear -> sRGB
float linearToSrgb1(float x)
{
    if (x <= 0.0031308) return 12.92 * x;
    return 1.055 * pow(x, 1.0 / 2.4) - 0.055;
}

vec3 linearToSrgb(vec3 c)
{
    return vec3(
        linearToSrgb1(c.r),
        linearToSrgb1(c.g),
        linearToSrgb1(c.b)
    );
}

// AE/PS-style float exposure model approximation:
// out = pow(max(in * 2^Exposure + Offset, 0), 1/Gamma)
float aeExposure(float x, float exposureStops, float offsetValue, float gammaValue)
{
    float g = max(gammaValue, EPSILON);
    float y = x * exp2(exposureStops) + offsetValue;
    y = max(y, 0.0);
    return pow(y, 1.0 / g);
}

vec3 applyMaster(vec3 c)
{
    return vec3(
        aeExposure(c.r, Exposure, Offset, Gamma_Correction),
        aeExposure(c.g, Exposure, Offset, Gamma_Correction),
        aeExposure(c.b, Exposure, Offset, Gamma_Correction)
    );
}

vec3 applyIndividual(vec3 c)
{
    return vec3(
        aeExposure(c.r, Red_Exposure,   Red_Offset,   Red_Gamma_Correction),
        aeExposure(c.g, Green_Exposure, Green_Offset, Green_Gamma_Correction),
        aeExposure(c.b, Blue_Exposure,  Blue_Offset,  Blue_Gamma_Correction)
    );
}

void main()
{
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 src = texel.rgb;
    vec3 work;
    vec3 dst;

    // Non-bypassed mode:
    // approximate AE linear-light processing using sRGB <-> linear conversion
    if (Bypass_Linear_Light_Conversion < 0.5)
    {
        // sRGB transfer functions are defined for non-negative SDR values,
        // so clamp before conversion for stable Panzoid behavior.
        work = srgbToLinear(max(src, 0.0));

        if (Channels < 0.5)
        {
            dst = applyMaster(work);
        }
        else
        {
            dst = applyIndividual(work);
        }

        dst = linearToSrgb(max(dst, 0.0));
    }
    else
    {
        // Bypassed mode:
        // apply directly to incoming/gamma-encoded pixels
        if (Channels < 0.5)
        {
            dst = applyMaster(src);
        }
        else
        {
            dst = applyIndividual(src);
        }
    }

    gl_FragColor = vec4(dst, texel.a);
}

text./plugins/alipfx/shaders/fast-box-blur.gl:
precision highp float;
precision highp int;

// Panzoid-provided
uniform sampler2D tDiffuse;
uniform vec2      resolution;
varying vec2      vUvScaled;

// Custom properties (dynamic Numbers)
uniform float Blur_Radius;         // in pixels
uniform float Iterations;          // 1..10+
uniform float Blur_Dimensions;     // 0=Both, 1=Horizontal, 2=Vertical
uniform float Repeat_Edge_Pixels;  // 0/1

// Compile-time caps
#define MAX_RADIUS 512
#define LOOP_MAX   64   // max taps per side considered by the loop

// ----------------------- Utilities -----------------------
int  toInt(float x) { return int(floor(x + 0.5)); }
bool repeatEdges()  { return Repeat_Edge_Pixels > 0.5; }

// GLSL ES 1.00 lacks min/max/clamp for int
int imin(int a, int b) { return (a < b) ? a : b; }
int imax(int a, int b) { return (a > b) ? a : b; }
int iclamp(int x, int lo, int hi) { return imin(imax(x, lo), hi); }

// Safe sampler that emulates AE's "Repeat Edge Pixels"
vec4 sampleSafe(vec2 uv) {
    if (repeatEdges()) {
        uv = clamp(uv, 0.0, 1.0);
        return texture2D(tDiffuse, uv);
    } else {
        if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
            return vec4(0.0);
        }
        return texture2D(tDiffuse, uv);
    }
}

// Premultiply helpers
vec4 premul(vec4 c)   { return vec4(c.rgb * c.a, c.a); }
vec4 unpremul(vec4 c) { float a = max(c.a, 1e-6); return vec4(c.rgb / a, c.a); }

// --------------------- Box 1D (Iterations = 1) -------------------
vec4 boxBlur1D(vec2 uv, vec2 dir, float radiusPx) {
    float r = max(radiusPx, 0.0);
    if (r < 0.5) return sampleSafe(uv);

    int  R     = imin(int(floor(r)), MAX_RADIUS);
    int  L     = imin(R, LOOP_MAX);
    vec2 texel = dir / resolution;

    vec4 accum = premul(sampleSafe(uv));
    float count = 1.0;

    for (int i = 1; i <= LOOP_MAX; ++i) {
        if (i > L) break;
        vec2 o = texel * float(i);
        vec4 c1 = premul(sampleSafe(uv + o));
        vec4 c2 = premul(sampleSafe(uv - o));
        accum += c1 + c2;
        count += 2.0;
    }

    return unpremul(accum / count);
}

// --------------- Gaussian 1D (Iterations >= 2) -------------------
// Optimized using a recurrence to avoid per-iteration exp():
//   w(i)      = exp(-i^2 * k), k = 0.5/(sigma^2)
//   w1        = exp(-1 * k)
//   ratio(1)  = exp(-3 * k)                  // takes w1 -> w2
//   rStep     = exp(-2 * k)                  // ratio(i+1) = ratio(i) * rStep
vec4 gaussianBlur1D(vec2 uv, vec2 dir, float sigma) {
    if (sigma < 0.5) return sampleSafe(uv);

    float support = max(1.0, floor(3.0 * sigma));        // 3σ support
    int   R       = imin(int(support), MAX_RADIUS);
    int   L       = imin(R, LOOP_MAX);
    vec2  texel   = dir / resolution;

    float k       = 0.5 / (sigma * sigma);
    float w0      = 1.0;                 // center
    float w       = exp(-k);             // weight at i = 1
    float ratio   = exp(-3.0 * k);       // multiplier to go w1 -> w2
    float rStep   = exp(-2.0 * k);       // update for ratio each step

    vec4 accum = premul(sampleSafe(uv)) * w0;
    float wsum = w0;

    for (int i = 1; i <= LOOP_MAX; ++i) {
        if (i > L) break;
        vec2 o = texel * float(i);
        vec4 c1 = premul(sampleSafe(uv + o));
        vec4 c2 = premul(sampleSafe(uv - o));
        accum += (c1 + c2) * w;
        wsum  += 2.0 * w;

        // advance to next i
        w     *= ratio;
        ratio *= rStep;
    }

    return unpremul(accum / max(wsum, 1e-6));
}

// Decide Box vs Gaussian from Iterations
vec4 blur1D(vec2 uv, vec2 dir, float radiusPx, int iters) {
    if (iters <= 1) {
        return boxBlur1D(uv, dir, radiusPx);
    } else {
        // n box passes ≈ Gaussian with sigma = r * sqrt(n/3)
        float sigma = max(0.0, radiusPx) * sqrt(float(iters) / 3.0);
        return gaussianBlur1D(uv, dir, sigma);
    }
}

// ------------------------------ main -----------------------------
void main() {
    int   iters = imax(1, toInt(Iterations));
    int   dims  = iclamp(toInt(Blur_Dimensions), 0, 2);
    float r     = max(0.0, Blur_Radius);

    // Early out
    if (r < 0.5) {
        gl_FragColor = sampleSafe(vUvScaled);
        return;
    }

    vec2 dirH = vec2(1.0, 0.0);
    vec2 dirV = vec2(0.0, 1.0);

    if (dims == 1) {
        gl_FragColor = blur1D(vUvScaled, dirH, r, iters); // Horizontal
    } else if (dims == 2) {
        gl_FragColor = blur1D(vUvScaled, dirV, r, iters); // Vertical
    } else {
        // Single-pass approximation of Both:
        // for exact AE separable H->V, stack two instances of this effect.
        vec4 h = blur1D(vUvScaled, dirH, r, iters);
        vec4 v = blur1D(vUvScaled, dirV, r, iters);
        gl_FragColor = 0.5 * (h + v);
    }
}

text./plugins/alipfx/shaders/fill.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom properties (Panzoid)
uniform vec3 Color;     // Color picker
uniform float Opacity;  // 0..100

void main()
{
  vec4 src = texture2D(tDiffuse, vUvScaled);

  // Convert 0..100 to 0..1
  float op = clamp(Opacity / 100.0, 0.0, 1.0);

  // Mix fill color over the original RGB
  vec3 outRgb = mix(src.rgb, Color, op);

  // Keep original alpha (recommended for AE-like "Fill" on most layers)
  gl_FragColor = vec4(outRgb, src.a);
}

text./plugins/alipfx/shaders/find-edges.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2      resolution;
varying vec2      vUvScaled;

/* --- AE-style properties (create as Dynamic Number properties in Panzoid) --- */
uniform float Invert;               // 0.0 = Disabled, 1.0 = Enabled (matches AE)
uniform float Blend_With_Original;  // 0..100 (%) --> 0% full effect, 100% original only

/* --- Tunables (leave as-is for AE-like behavior) --- */
const float EDGE_NORM  = 1.05;       // Sobel max magnitude for a unit step (normalizes to 0..1)
const float GAMMA      = 0.75;       // Work in linear; display in sRGB

// sRGB <-> Linear helpers for more AE-like tonality
vec3 toLinear(vec3 c) { return pow(c, vec3(GAMMA)); }
vec3 toSRGB  (vec3 c) { return pow(c, vec3(1.0 / GAMMA)); }

void main()
{
    vec4 src = texture2D(tDiffuse, vUvScaled); // source in display space (sRGB)

    // Pixel step in buffer UVs (Panzoid supplies resolution in pixels)
    vec2 px = 1.0 / resolution;

    // Sample a 3x3 neighborhood (converted to linear for correct gradient math)
    vec3 tl = toLinear(texture2D(tDiffuse, vUvScaled + vec2(-px.x, -px.y)).rgb);
    vec3 tc = toLinear(texture2D(tDiffuse, vUvScaled + vec2( 0.0 , -px.y)).rgb);
    vec3 tr = toLinear(texture2D(tDiffuse, vUvScaled + vec2( px.x , -px.y)).rgb);
    vec3 ml = toLinear(texture2D(tDiffuse, vUvScaled + vec2(-px.x,  0.0 )).rgb);
    vec3 mr = toLinear(texture2D(tDiffuse, vUvScaled + vec2( px.x ,  0.0 )).rgb);
    vec3 bl = toLinear(texture2D(tDiffuse, vUvScaled + vec2(-px.x,  px.y)).rgb);
    vec3 bc = toLinear(texture2D(tDiffuse, vUvScaled + vec2( 0.0 ,  px.y)).rgb);
    vec3 br = toLinear(texture2D(tDiffuse, vUvScaled + vec2( px.x ,  px.y)).rgb);

    // Sobel per channel (RGB) — classic 3x3 kernels
    // Gx = [-1 0 +1; -2 0 +2; -1 0 +1]
    // Gy = [-1 -2 -1; 0 0 0; +1 +2 +1]
    vec3 gx = (-1.0*tl) + ( 1.0*tr) +
              (-2.0*ml) + ( 2.0*mr) +
              (-1.0*bl) + ( 1.0*br);

    vec3 gy = (-1.0*tl) + (-2.0*tc) + (-1.0*tr) +
               (1.0*bl) + ( 2.0*bc) + ( 1.0*br);

    // Gradient magnitude (normalize to 0..1 for a unit step edge), clamp for safety
    vec3 edgeLin = clamp(sqrt(gx*gx + gy*gy) / EDGE_NORM, 0.0, 1.0);

    // AE behavior:
    // - Invert OFF  (0): dark lines on white background  ->  1 - edge
    // - Invert ON   (1): bright/colored lines on black   ->  edge
    vec3 effectLin = mix(vec3(1.0) - edgeLin, edgeLin, step(0.5, Invert));

    // Convert back to sRGB for display/mixing
    vec3 effectSRGB = toSRGB(effectLin);

    // AE "Blend With Original": 0..100% (0% full effect, 100% original only)
    float bwo = clamp(Blend_With_Original, 0.0, 100.0) * 0.01;
    vec3 outRGB = mix(effectSRGB, src.rgb, bwo);

    gl_FragColor = vec4(outRGB, src.a); // preserve source alpha (AE layers keep alpha)
}

text./plugins/alipfx/shaders/fractal-noise.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// ====== Panzoid Properties (spaces become underscores) ======
uniform float Fractal_Type;       // 0..16
uniform float Noise_Type;         // 0..3
uniform float Invert;             // 0..1
uniform float Contrast;           // -200..200
uniform float Brightness;         // -100..100
uniform float Overflow;           // 0..3
uniform float Rotation;           // degrees
uniform float Uniform_Scaling;    // 0..1
uniform float Scale;              // percent
uniform float Scale_Width;        // percent
uniform float Scale_Height;       // percent
uniform vec2  Offset_Turbulence;  // pixels recommended
uniform float Perspective_Offset; // 0..1 checkbox
uniform float Complexity;         // 1..12 (fractional ok)
uniform float Sub_Influence;      // 0..100
uniform float Sub_Scaling;        // 0..200 (% size of sub layers)
uniform float Sub_Rotation;       // degrees
uniform vec2  Sub_Offset;         // pixels recommended
uniform float Center_Subscale;    // 0..1 checkbox
uniform float Evolution;          // degrees
uniform float Cycle_Evolution;    // 0..1
uniform float Cycle;              // revolutions
uniform float Random_Seed;        // any
uniform float Opacity;            // 0..100
uniform float Blending_Mode;      // 0..16

// ===================== Helpers =====================
float sat(float x){ return clamp(x, 0.0, 1.0); }

mat2 rot2(float a){
  float s = sin(a), c = cos(a);
  return mat2(c, -s, s, c);
}

// Seedable hash (3D)
float hash13(vec3 p){
  p = fract(p * 0.1031);
  p += dot(p, p.yzx + 33.33);
  return fract((p.x + p.y) * p.z);
}

vec3 hash33(vec3 p){
  return vec3(
    hash13(p + vec3(0.0, 0.0, 0.0)),
    hash13(p + vec3(19.19, 7.77, 3.33)),
    hash13(p + vec3(2.71, 11.11, 5.55))
  );
}

float fadeSoft(float t){ return t*t*(3.0-2.0*t); }
float fadeSpline(float t){ return t*t*t*(t*(t*6.0-15.0)+10.0); }

// ===================== Base noises =====================

// 3D value noise with selectable interpolation
float valueNoise3(vec3 p, float seed, int interpMode){
  vec3 i = floor(p);
  vec3 f = fract(p);

  vec3 u = f;
  if(interpMode == 1) u = vec3(fadeSoft(f.x), fadeSoft(f.y), fadeSoft(f.z));
  if(interpMode == 2) u = vec3(fadeSpline(f.x), fadeSpline(f.y), fadeSpline(f.z));

  float v000 = hash13(i + vec3(0,0,0) + seed);
  float v100 = hash13(i + vec3(1,0,0) + seed);
  float v010 = hash13(i + vec3(0,1,0) + seed);
  float v110 = hash13(i + vec3(1,1,0) + seed);
  float v001 = hash13(i + vec3(0,0,1) + seed);
  float v101 = hash13(i + vec3(1,0,1) + seed);
  float v011 = hash13(i + vec3(0,1,1) + seed);
  float v111 = hash13(i + vec3(1,1,1) + seed);

  float x00 = mix(v000, v100, u.x);
  float x10 = mix(v010, v110, u.x);
  float x01 = mix(v001, v101, u.x);
  float x11 = mix(v011, v111, u.x);

  float y0 = mix(x00, x10, u.y);
  float y1 = mix(x01, x11, u.y);

  return mix(y0, y1, u.z);
}

// 3D gradient noise (Perlin-ish) for Spline
float gradNoise3(vec3 p, float seed){
  vec3 i = floor(p);
  vec3 f = fract(p);

  vec3 g000 = normalize(hash33(i + vec3(0,0,0) + seed) * 2.0 - 1.0);
  vec3 g100 = normalize(hash33(i + vec3(1,0,0) + seed) * 2.0 - 1.0);
  vec3 g010 = normalize(hash33(i + vec3(0,1,0) + seed) * 2.0 - 1.0);
  vec3 g110 = normalize(hash33(i + vec3(1,1,0) + seed) * 2.0 - 1.0);
  vec3 g001 = normalize(hash33(i + vec3(0,0,1) + seed) * 2.0 - 1.0);
  vec3 g101 = normalize(hash33(i + vec3(1,0,1) + seed) * 2.0 - 1.0);
  vec3 g011 = normalize(hash33(i + vec3(0,1,1) + seed) * 2.0 - 1.0);
  vec3 g111 = normalize(hash33(i + vec3(1,1,1) + seed) * 2.0 - 1.0);

  float n000 = dot(g000, f - vec3(0,0,0));
  float n100 = dot(g100, f - vec3(1,0,0));
  float n010 = dot(g010, f - vec3(0,1,0));
  float n110 = dot(g110, f - vec3(1,1,0));
  float n001 = dot(g001, f - vec3(0,0,1));
  float n101 = dot(g101, f - vec3(1,0,1));
  float n011 = dot(g011, f - vec3(0,1,1));
  float n111 = dot(g111, f - vec3(1,1,1));

  vec3 u = vec3(fadeSpline(f.x), fadeSpline(f.y), fadeSpline(f.z));

  float x00 = mix(n000, n100, u.x);
  float x10 = mix(n010, n110, u.x);
  float x01 = mix(n001, n101, u.x);
  float x11 = mix(n011, n111, u.x);

  float y0 = mix(x00, x10, u.y);
  float y1 = mix(x01, x11, u.y);

  float n = mix(y0, y1, u.z);
  return n * 0.5 + 0.5; // [-1..1] -> [0..1]
}

float blockNoise3(vec3 p, float seed){
  return hash13(floor(p) + seed);
}

// Noise Type selector: 0 Block, 1 Linear, 2 Soft Linear, 3 Spline
float baseNoise(vec3 p, float seed){
  int nt = int(floor(Noise_Type + 0.5));
  if(nt == 0) return blockNoise3(p, seed);
  if(nt == 1) return valueNoise3(p, seed, 0);
  if(nt == 2) return valueNoise3(p, seed, 1);
  return gradNoise3(p, seed);
}

// ===================== AE-ish Tone Controls =====================
float applyCB(float x){
  float c = Contrast / 100.0;
  float b = Brightness / 100.0;
  x += b;
  float gain = 1.0 + c * 0.6; // tuned
  return (x - 0.5) * gain + 0.5;
}

float applyOverflow(float x){
  int of = int(floor(Overflow + 0.5));
  if(of == 0) return clamp(x, 0.0, 1.0); // Clip
  if(of == 1){
    float y = x;
    if(y < 0.0) y = - (1.0 - exp(y));
    if(y > 1.0) y = 1.0 + (1.0 - exp(1.0-y));
    return clamp(y, 0.0, 1.0);
  }
  if(of == 2){
    float t = fract(x);
    return 1.0 - abs(t * 2.0 - 1.0);
  }
  return x; // Allow HDR
}

// ===================== Blend modes (0..16) =====================
vec3 rgb2hsv(vec3 c){
  vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0*d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c){
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz)*6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

vec3 blend(vec3 base, vec3 fx, int mode){
  if(mode == 0) return fx; // None (replace)
  if(mode == 1) return fx; // Normal
  if(mode == 2) return base + fx;
  if(mode == 3) return base * fx;
  if(mode == 4) return 1.0 - (1.0-base)*(1.0-fx);
  if(mode == 5) return mix(2.0*base*fx, 1.0-2.0*(1.0-base)*(1.0-fx), step(0.5, base)); // Overlay
  if(mode == 6) return (1.0 - 2.0*fx)*base*base + 2.0*fx*base; // Soft Light approx
  if(mode == 7) return mix(2.0*base*fx, 1.0-2.0*(1.0-base)*(1.0-fx), step(0.5, fx));  // Hard Light
  if(mode == 8) return base / max(1.0 - fx, 1e-5); // Color Dodge
  if(mode == 9) return 1.0 - (1.0-base) / max(fx, 1e-5); // Color Burn
  if(mode == 10) return min(base, fx); // Darken
  if(mode == 11) return max(base, fx); // Lighten
  if(mode == 12) return abs(base - fx); // Difference
  if(mode == 13) return base + fx - 2.0*base*fx; // Exclusion
  if(mode == 14){
    vec3 hb = rgb2hsv(base), hs = rgb2hsv(fx);
    return hsv2rgb(vec3(hs.x, hb.y, hb.z));
  }
  if(mode == 15){
    vec3 hb = rgb2hsv(base), hs = rgb2hsv(fx);
    return hsv2rgb(vec3(hb.x, hs.y, hb.z));
  }
  vec3 hb = rgb2hsv(base), hs = rgb2hsv(fx);
  return hsv2rgb(vec3(hb.x, hb.y, hs.z)); // 16 Luminosity
}

// ===================== Fractal Type shaping =====================
float turbulence(float n){ return 1.0 - abs(n * 2.0 - 1.0); }
float ridged(float n){ float t = turbulence(n); return t*t; }

vec3 domainWarp(vec3 p, float seed, float amount){
  float a = baseNoise(p * 0.75 + vec3(12.3, 4.56, 1.11), seed + 101.0);
  float b = baseNoise(p * 0.75 + vec3(7.89, 1.23, 9.99), seed + 202.0);
  float c = baseNoise(p * 0.75 + vec3(5.55, 6.66, 2.22), seed + 303.0);
  vec3 w = (vec3(a,b,c) - 0.5) * 2.0;
  return p + w * amount;
}

float applyFractalTypeSample(int ft, float n, vec3 pp, float seed, float evoPhase, int octave){
  // 0 Basic
  if(ft == 0) return n;

  // 1..3 turbulence variants
  if(ft == 1){ float t = turbulence(n); return smoothstep(0.0, 1.0, t); } // Turbulent Smooth
  if(ft == 2) return turbulence(n);                                       // Turbulent Basic
  if(ft == 3) return pow(sat(turbulence(n)), 2.2);                        // Turbulent Sharp

  // 4..6 dynamic family
  if(ft == 4){
    float m = baseNoise(pp + vec3(1.7, -2.1, evoPhase*1.1), seed + 777.0);
    return mix(n, m, 0.35);
  }
  if(ft == 5){
    vec3 q = pp + vec3(float(octave) * 0.35, float(octave) * -0.25, evoPhase*1.6);
    float m = baseNoise(q, seed + 888.0 + float(octave)*13.0);
    return mix(n, m, 0.45);
  }
  if(ft == 6){
    float ang = (baseNoise(pp*0.35 + vec3(0.0,0.0,evoPhase), seed+505.0) - 0.5) * 2.2;
    vec2 xy = rot2(ang) * pp.xy;
    float m = baseNoise(vec3(xy, pp.z), seed + 606.0);
    return mix(n, m, 0.55);
  }

  // 7 Max
  if(ft == 7) return ridged(n);

  // 8..9 smeary/swirly (mostly warp handled outside)
  if(ft == 8) return mix(n, turbulence(n), 0.35);
  if(ft == 9) return mix(n, ridged(n), 0.25);

  // 10 Rocky
  if(ft == 10) return pow(sat(ridged(n)), 1.6);

  // 11 Cloudy
  if(ft == 11){ float t = turbulence(n); return smoothstep(0.15, 0.95, t); }

  // 12 Terrain
  if(ft == 12){ float r = ridged(n); return mix(n, r, 0.65); }

  // 13 Subscale
  if(ft == 13) return mix(n, turbulence(n), 0.5);

  // 14 Small Bumps
  if(ft == 14){
    float x = (n - 0.5) * 1.6 + 0.5;
    return sat(mix(n, x, 0.65));
  }

  // 15 Strings / 16 Threads
  if(ft == 15){ float t = turbulence(n); return smoothstep(0.62, 0.90, t); }
  float t = turbulence(n);
  return smoothstep(0.78, 0.93, t);
}

// ===================== Fractal core (Center Subscale FIXED) =====================
float fractalNoise(vec3 p, float evoPhase, vec2 scalePx){
  const int MAX_OCT = 12;

  float comp = clamp(Complexity, 1.0, float(MAX_OCT));
  int oct = int(floor(comp));
  float fracOct = comp - float(oct);

  float seed = Random_Seed * 10.0;

  float subSize = max(Sub_Scaling, 0.001);
  float lacunarity = 100.0 / subSize;            // 50% => 2.0
  float gain = clamp(Sub_Influence / 100.0, 0.0, 0.999);

  float sum = 0.0;
  float amp = 1.0;
  float ampSum = 0.0;
  float freq = 1.0;

  float subRot = radians(Sub_Rotation);
  vec2 subOff = Sub_Offset / max(scalePx, vec2(1.0));

  // Pivot controls where octave scaling originates
  vec2 pivot = (Center_Subscale > 0.5)
    ? vec2(0.0)
    : (-0.5 * resolution) / max(scalePx, vec2(1.0));

  int ft = int(floor(Fractal_Type + 0.5));

  // Coordinate warps for some types
  if(ft == 8){
    p = domainWarp(p, seed, 0.9);
  }else if(ft == 9){
    float a = (baseNoise(p*0.30, seed+404.0) - 0.5) * 6.2831853;
    p.xy = rot2(a) * p.xy;
    p = domainWarp(p, seed, 0.65);
  }else if(ft == 6){
    p = domainWarp(p, seed, 0.25);
  }

  for(int i = 0; i < MAX_OCT; i++){
    if(i > oct) break;

    vec3 pp = p;

    if(i > 0){
      // sub-rotation + sub-offset around pivot
      vec2 pxy = pp.xy - pivot;
      pxy = rot2(subRot * float(i)) * pxy;
      pxy += pivot;
      pxy += subOff * float(i);
      pp.xy = pxy;

      freq *= lacunarity;
      amp *= gain;
    }

    // Scale each octave about pivot (this is Center Subscale)
    vec3 coord = pp;
    coord.xy = (pp.xy - pivot) * freq + pivot;
    coord.z  = pp.z * freq;

    float n = baseNoise(coord, seed + float(i) * 37.0);
    n = applyFractalTypeSample(ft, n, coord, seed, evoPhase, i);

    float w = 1.0;
    if(ft == 13 && i > 0){
      w = 1.0 + 0.75 * gain;
    }

    sum += n * amp * w;
    ampSum += amp * w;

    // fractional complexity blend
    if(i == oct && fracOct > 0.0){
      sum = mix(sum - n*amp*w, sum, fracOct);
      ampSum = mix(ampSum - amp*w, ampSum, fracOct);
    }
  }

  return (ampSum > 0.0) ? (sum / ampSum) : 0.5;
}

// ===================== Main =====================
void main(){
  vec4 texel = texture2D(tDiffuse, vUvScaled);
  vec2 uv = vUv;

  // Centered pixel space (AE-ish)
  vec2 pPx = (uv - 0.5) * resolution;

  // Rotate in pixel space like Transform Rotation
  pPx = rot2(radians(Rotation)) * pPx;

  // Scale mapping: % of comp min dimension
  float minDim = max(min(resolution.x, resolution.y), 1.0);

  float sU  = max(Scale, 0.001) / 100.0;
  float sxP = (Uniform_Scaling > 0.5) ? sU : max(Scale_Width, 0.001) / 100.0;
  float syP = (Uniform_Scaling > 0.5) ? sU : max(Scale_Height, 0.001) / 100.0;

  vec2 scalePx = vec2(sxP * minDim, syP * minDim);
  scalePx = max(scalePx, vec2(1.0));

  // Convert to noise space
  pPx /= scalePx;

  // Evolution (phase + Z)
  float evoTurns = Evolution / 360.0;
  float evoPhase;
  float z;

  if(Cycle_Evolution > 0.5){
    float cyc = max(Cycle, 0.001);
    float phase = evoTurns * (6.2831853 / cyc);
    z = cos(phase) * 2.0 + sin(phase) * 2.0;
    evoPhase = phase;
  }else{
    z = evoTurns * 4.0;
    evoPhase = evoTurns * 6.2831853;
  }

  // Base translation (Offset Turbulence) — always applied normally
  vec2 off = Offset_Turbulence / scalePx;
  pPx += off;

  // ===================== Perspective Offset (AE-like depth, NO net shift, vertical-only, reacts to X/Y equally) =====================
  if(Perspective_Offset > 0.5)
  {
    // TOP is near
    float depth = pow(uv.y, 1.35);
    float depthMid = pow(0.5, 1.35);
    float d = depth - depthMid; // centered depth (zero at midline)

    // React equally to X and Y movement
    float move = length(off);

    // Smooth saturating mapping (so big offsets don't explode)
    float moveAmt = 1.0 - exp(-move * 0.60);

    // Vertical stretch only (no X changes => no smear)
    const float V_STRETCH = 2.20;
    const float STAB_Y    = 0.55;

    float sy = 1.0 + d * (V_STRETCH * moveAmt);
    pPx.y *= sy;

    // stabilize Y so small Scale doesn't blow up
    pPx.y /= (1.0 + abs(d) * (STAB_Y * moveAmt));
  }

  vec3 p3 = vec3(pPx, z);

  // Fractal noise (Center Subscale uses scalePx internally)
  float n = fractalNoise(p3, evoPhase, scalePx);

  // Invert
  if(Invert > 0.5) n = 1.0 - n;

  // Contrast/Brightness + Overflow
  n = applyCB(n);
  n = applyOverflow(n);

  // Grayscale output
  vec3 noiseRGB = vec3(n);

  // Opacity
  float a = clamp(Opacity / 100.0, 0.0, 1.0);

  // Blend
  int bm = int(floor(Blending_Mode + 0.5));
  vec3 outBlend = blend(texel.rgb, noiseRGB, bm);

  vec3 outRGB;
  if(bm == 0 || bm == 1){
    outRGB = mix(texel.rgb, noiseRGB, a);
  }else{
    outRGB = mix(texel.rgb, outBlend, a);
  }

  gl_FragColor = vec4(outRGB, texel.a);
}

text./plugins/alipfx/shaders/gamma-pedestal-g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Panzoid custom properties (spaces become underscores)
uniform float Black_Stretch;

uniform float Red_Gamma;
uniform float Red_Pedestal;
uniform float Red_Gain;

uniform float Green_Gamma;
uniform float Green_Pedestal;
uniform float Green_Gain;

uniform float Blue_Gamma;
uniform float Blue_Pedestal;
uniform float Blue_Gain;

const float EPS = 0.00001;
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

// Safe gamma so the shader never explodes at 0
float safeGamma(float g) {
    return max(g, EPS);
}

// Black Stretch curve:
// - no change at 1.0
// - > 1.0 lifts/expands shadows
// - < 1.0 compresses/crushes shadows a bit
// The shadow mask makes it affect dark values much more than highlights.
float blackStretchCurve(float x, float stretch) {
    x = clamp(x, 0.0, 1.0);
    stretch = max(stretch, EPS);

    // Base lift curve that preserves 0 and 1
    float lifted = 1.0 - pow(1.0 - x, stretch);

    // Fade the effect out toward highlights
    float shadowMask = pow(1.0 - x, 2.0);

    return mix(x, lifted, shadowMask);
}

// AE-like channel mapping:
// pedestal = output floor
// gain     = output ceiling
// gamma    = curve bend in the middle
float applyChannelGPG(float x, float gammaVal, float pedestal, float gainVal) {
    x = clamp(x, 0.0, 1.0);

    // Gamma > 1.0 brightens mids, Gamma < 1.0 darkens mids
    float curved = pow(x, 1.0 / safeGamma(gammaVal));

    // Pedestal/Gain define min/max output
    float y = pedestal + (gainVal - pedestal) * curved;

    return clamp(y, 0.0, 1.0);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 c = clamp(texel.rgb, 0.0, 1.0);

    // -------------------------------------------------
    // 1) BLACK STRETCH (global, hue-preserving)
    // -------------------------------------------------
    // Do black stretch on luminance, then rescale RGB.
    // This keeps neutrals neutral and avoids color shifts in shadows.
    float y  = dot(c, LUMA);
    float y2 = blackStretchCurve(y, Black_Stretch);

    float scale = y2 / max(y, EPS);
    c *= scale;
    c = clamp(c, 0.0, 1.0);

    // -------------------------------------------------
    // 2) PER-CHANNEL GAMMA / PEDESTAL / GAIN
    // -------------------------------------------------
    c.r = applyChannelGPG(c.r, Red_Gamma,   Red_Pedestal,   Red_Gain);
    c.g = applyChannelGPG(c.g, Green_Gamma, Green_Pedestal, Green_Gain);
    c.b = applyChannelGPG(c.b, Blue_Gamma,  Blue_Pedestal,  Blue_Gain);

    // Optional: uncomment this line if you want a more "legacy 8-bpc" feel
    // c = floor(c * 255.0 + 0.5) / 255.0;

    gl_FragColor = vec4(c, texel.a);
}

text./plugins/alipfx/shaders/gaussian-blur.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2      uvScale;
uniform vec2      resolution;
varying vec2      vUvScaled;

// ===== Dynamic properties =====
uniform float Blurriness;           // σ in pixels (AE-style)
uniform float Blur_Dimensions;      // 0=Both, 1=Horizontal, 2=Vertical
uniform float Repeat_Edge_Pixels;   // 0=Off, 1=On

// ===== Performance caps (tune to taste) =====
#define MAX_RADIUS_1D   128   // Max ±radius for 1D
#define MAX_RADIUS_BOTH  24   // Max ±radius for 2D (heavy)

// ---- int helpers ----
int imin_int(int a, int b) { return (a < b) ? a : b; }
int iabs_int(int x) { return (x < 0) ? -x : x; }

const float EPS = 1e-6;

// ---- robust decoder for Blur_Dimensions ----
int decodeDim(float v) {
    // [0, 0.5) => 0 (Both), [0.5, 1.5) => 1 (Horizontal), else 2 (Vertical)
    if (v < 0.5) return 0;
    else if (v < 1.5) return 1;
    else return 2;
}

// ============================ Sampling helpers ============================
vec4 sample_clamped(vec2 uv) {
    return texture2D(tDiffuse, clamp(uv, vec2(0.0), vec2(1.0)));
}

bool inside01(vec2 uv) {
    return !(any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0))));
}
vec4 sample_if_inside(vec2 uv) {
    return inside01(uv) ? texture2D(tDiffuse, uv) : vec4(0.0);
}

// ============================ FULL 1D (H or V) ============================
// Uses **Gaussian recurrence** so we do only 2 exponentials total per fragment.
// w0 = 1
// r1 = exp(-(2*1-1)/(2σ^2)) = exp(-1/(2σ^2))
// step = exp(-1/σ^2)
// w_i = w_{i-1} * r_i ; r_{i+1} = r_i * step
vec4 blur1D_full(vec2 uv, vec2 stepUV, float sigma, bool repeatEdges) {
    int r = int(ceil(3.0 * sigma));
    r = imin_int(r, MAX_RADIUS_1D);

    // Precompute recurrence constants
    float invSigma2 = 1.0 / max(sigma * sigma, 1e-12);
    float r_i   = exp(-0.5 * invSigma2); // ratio for i=1
    float rStep = exp(-1.0 * invSigma2); // growth per step
    float w_i   = 1.0;                   // w_0

    // Center
    vec4  c0 = repeatEdges ? sample_clamped(uv) : sample_if_inside(uv);
    vec3  accPremul = c0.rgb * c0.a; // * w0 (w0=1)
    float accAlpha  = c0.a;          // * w0
    float wSum      = 1.0;

    // Symmetric pairs (±i)
    for (int i = 1; i <= MAX_RADIUS_1D; ++i) {
        if (i > r) break;

        // advance recurrence
        w_i *= r_i;     // now w_i = exp(-i^2/(2σ^2))
        r_i *= rStep;   // prepare ratio for next i (i+1)

        vec2 o = float(i) * stepUV;

        if (repeatEdges) {
            vec4 p = sample_clamped(uv + o);
            vec4 n = sample_clamped(uv - o);
            accPremul += (p.rgb * p.a + n.rgb * n.a) * w_i;
            accAlpha  += (p.a + n.a) * w_i;
        } else {
            vec2 up = uv + o, un = uv - o;
            if (inside01(up)) {
                vec4 p = texture2D(tDiffuse, up);
                accPremul += (p.rgb * p.a) * w_i;
                accAlpha  += p.a * w_i;
            }
            if (inside01(un)) {
                vec4 n = texture2D(tDiffuse, un);
                accPremul += (n.rgb * n.a) * w_i;
                accAlpha  += n.a * w_i;
            }
        }

        // IMPORTANT: keep kernel sum even if samples are OOB (AE darkening)
        wSum += 2.0 * w_i;
    }

    vec3 premul = accPremul / max(wSum, EPS);
    float a     = accAlpha  / max(wSum, EPS);
    vec3 rgb    = premul / max(a, EPS);
    return vec4(rgb, a);
}

// ============================ BOTH (H & V) ============================
// Exact 2D; still heavy. Uses symmetry + recurrence to reduce ALU work.
// NOTE: For speed, prefer two 1D passes with this same shader.
vec4 blurBoth_full(vec2 uv, vec2 texelSize, float sigma, bool repeatEdges) {
    int r = int(ceil(3.0 * sigma));
    r = imin_int(r, MAX_RADIUS_BOTH);

    float invSigma2 = 1.0 / max(sigma * sigma, 1e-12);

    // 1D sum for exact normalization in 2D: (sum1D)^2
    // Use recurrence to build sum1D fast.
    float sum1D = 1.0;
    float r_i   = exp(-0.5 * invSigma2); // ratio for i=1
    float rStep = exp(-1.0 * invSigma2);
    float w_i   = 1.0;
    for (int i = 1; i <= MAX_RADIUS_BOTH; ++i) {
        if (i > r) break;
        w_i *= r_i;
        r_i *= rStep;
        sum1D += 2.0 * w_i;
    }
    float norm2D = max(sum1D * sum1D, EPS);

    vec3 accPremul = vec3(0.0);
    float accAlpha = 0.0;

    // Y-direction recurrence
    float ry  = exp(-0.5 * invSigma2); // ratio for j=1
    float rys = rStep;
    float wy  = 1.0;

    // Row j = 0 (center row)
    {
        // X recurrence fresh for each row
        float rx  = exp(-0.5 * invSigma2);
        float rxs = rStep;
        float wx  = 1.0;

        // center
        vec4 c = repeatEdges ? sample_clamped(uv) : sample_if_inside(uv);
        float w0 = 1.0;
        accPremul += (c.rgb * c.a) * (w0 * wy); // wy=1
        accAlpha  += c.a * (w0 * wy);

        // ±x
        for (int ix = 1; ix <= MAX_RADIUS_BOTH; ++ix) {
            if (ix > r) break;
            wx *= rx; rx *= rxs;

            vec2 o = vec2(float(ix), 0.0) * texelSize;
            if (repeatEdges) {
                vec4 p = sample_clamped(uv + o);
                vec4 n = sample_clamped(uv - o);
                float w = wx * wy;
                accPremul += (p.rgb*p.a + n.rgb*n.a) * w;
                accAlpha  += (p.a + n.a) * w;
            } else {
                vec2 up = uv + o, un = uv - o;
                float w = wx * wy;
                if (inside01(up)) { vec4 s = texture2D(tDiffuse, up); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
                if (inside01(un)) { vec4 s = texture2D(tDiffuse, un); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
            }
        }
    }

    // Rows j = 1..r (handle ±j symmetrically)
    for (int jy = 1; jy <= MAX_RADIUS_BOTH; ++jy) {
        if (jy > r) break;
        wy *= ry; ry *= rys;

        vec2 oy = vec2(0.0, float(jy)) * texelSize;

        // X recurrence per row
        float rx  = exp(-0.5 * invSigma2);
        float rxs = rStep;
        float wx  = 1.0;

        // Axis points (ix = 0): (0, +j) and (0, -j)
        {
            float w = wx * wy; // wx=1
            if (repeatEdges) {
                vec4 p = sample_clamped(uv + oy);
                vec4 n = sample_clamped(uv - oy);
                accPremul += (p.rgb*p.a + n.rgb*n.a) * w;
                accAlpha  += (p.a + n.a) * w;
            } else {
                vec2 up = uv + oy, un = uv - oy;
                if (inside01(up)) { vec4 s = texture2D(tDiffuse, up); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
                if (inside01(un)) { vec4 s = texture2D(tDiffuse, un); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
            }
        }

        // Quadrants (±ix, ±jy), ix = 1..r
        for (int ix = 1; ix <= MAX_RADIUS_BOTH; ++ix) {
            if (ix > r) break;
            wx *= rx; rx *= rxs;

            float w = wx * wy;
            vec2 ox = vec2(float(ix), 0.0) * texelSize;

            // (+x, +y), (+x, -y), (-x, +y), (-x, -y)
            if (repeatEdges) {
                vec4 s1 = sample_clamped(uv + ox + oy);
                vec4 s2 = sample_clamped(uv + ox - oy);
                vec4 s3 = sample_clamped(uv - ox + oy);
                vec4 s4 = sample_clamped(uv - ox - oy);
                accPremul += (s1.rgb*s1.a + s2.rgb*s2.a + s3.rgb*s3.a + s4.rgb*s4.a) * w;
                accAlpha  += (s1.a + s2.a + s3.a + s4.a) * w;
            } else {
                vec2 u1 = uv + ox + oy, u2 = uv + ox - oy, u3 = uv - ox + oy, u4 = uv - ox - oy;
                if (inside01(u1)) { vec4 s = texture2D(tDiffuse, u1); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
                if (inside01(u2)) { vec4 s = texture2D(tDiffuse, u2); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
                if (inside01(u3)) { vec4 s = texture2D(tDiffuse, u3); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
                if (inside01(u4)) { vec4 s = texture2D(tDiffuse, u4); accPremul += (s.rgb*s.a) * w; accAlpha += s.a * w; }
            }
        }
    }

    vec3 premul = accPremul / norm2D;
    float a     = accAlpha  / norm2D;
    vec3 rgb    = premul / max(a, EPS);
    return vec4(rgb, a);
}

void main() {
    vec2 texelSize = 1.0 / max(resolution, vec2(1.0));
    vec2 uv        = vUvScaled;

    float sigma = max(Blurriness, 0.0);
    if (sigma <= 0.0) {
        gl_FragColor = texture2D(tDiffuse, uv);
        return;
    }

    int  dim = decodeDim(Blur_Dimensions);
    bool rep = (Repeat_Edge_Pixels >= 0.5);

    // 1D step per pixel
    vec2 stepH = vec2(texelSize.x, 0.0);
    vec2 stepV = vec2(0.0, texelSize.y);

    vec4 color;
    if (dim == 1) {
        // Horizontal
        color = blur1D_full(uv, stepH, sigma, rep);
    } else if (dim == 2) {
        // Vertical
        color = blur1D_full(uv, stepV, sigma, rep);
    } else {
        // Both (still heavy; prefer two passes for speed)
        color = blurBoth_full(uv, texelSize, sigma, rep);
    }

    gl_FragColor = color;
}

text./plugins/alipfx/shaders/glasswork.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
varying vec2 vUv;
varying vec2 vUvScaled;

// ============================================================
// GLASSWORK for Panzoid CM3 - v4.2
// ALL Patterns Fixed (Strips, ZigZag, Rhombuses, Waves)
// Compliant with Panzoid shader rules
// ============================================================

uniform float Pattern_Type;      // 0=Strips, 1=ZigZag, 2=Rhombuses, 3=Waves
uniform float Show_Pattern;      // 0=Disabled, 1=Enabled
uniform float X_Displacement;    // Horizontal distortion
uniform float Y_Displacement;    // Vertical distortion
uniform float Pattern_Smoothness;// Edge softness
uniform float Pattern_Size;      // Pattern scale
uniform float Pattern_Angle;     // Rotation (degrees)
uniform vec2  Pattern_Position;  // 2D offset
uniform float Blur_Samples;      // Blur quality
uniform float Bluriness;         // Blur amount
uniform float Frostiness;        // Frost intensity
uniform float Frost_Scale;       // Frost grain size

// ============================================================
// NOISE FUNCTIONS
// ============================================================

float hash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
        mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
        f.y
    );
}

// Multi-octave noise for frost
float frostNoise(vec2 p) {
    float n = vnoise(p);
    n += vnoise(p * 2.03) * 0.5;
    n += vnoise(p * 4.01) * 0.25;
    n += vnoise(p * 8.07) * 0.125;
    return n / 1.875;
}

// ============================================================
// UTILITIES
// ============================================================

mat2 rot2(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// ============================================================
// PATTERNS
// ============================================================

// 0. Strips - Sawtooth wave for flat, tilted glass panes
float patStrips(vec2 uv, float sz) {
    return fract(uv.x * sz);
}

// 1. ZigZag - CHEVRON pattern matching AE Glasswork
float patZigZag(vec2 uv, float sz) {
    vec2 p = uv * sz;
    float col = floor(p.x);
    float dir = mod(col, 2.0) * 2.0 - 1.0;
    float localX = fract(p.x);
    float v = fract(p.y + (dir * localX));
    return abs(v - 0.5) * 2.0;
}

// 2. Rhombuses - Faceted diamond pyramids
float patRhombuses(vec2 uv, float sz) {
    vec2 p = uv * sz;

    // Rotate grid 45 degrees to turn squares into diamonds
    vec2 r = vec2(p.x - p.y, p.x + p.y) * 0.70710678;

    // Max generates pyramid blocks instead of soft gradients
    float d = max(abs(fract(r.x) - 0.5), abs(fract(r.y) - 0.5));

    // Scale to a clean 0.0 to 1.0 range
    return d * 2.0;
}

// 3. Waves - sine wave displacement pattern
float patWaves(vec2 uv, float sz) {
    vec2 p = uv * sz;
    float waveOffset = sin(p.x * 3.14159265359) * 0.5;
    float v = fract(p.y + waveOffset);
    return abs(v - 0.5) * 2.0;
}

float samplePattern(vec2 uv, int type, float sz, float sm) {
    float v;
    if (type == 0) v = patStrips(uv, sz);
    else if (type == 1) v = patZigZag(uv, sz);
    else if (type == 2) v = patRhombuses(uv, sz);
    else if (type == 3) v = patWaves(uv, sz);
    else v = patStrips(uv, sz);

    float e = sm / 100.0;
    if (e > 0.001) {
        v = smoothstep(0.0, e, v);
    }
    return v;
}

// ============================================================
// BLUR
// ============================================================

vec4 doBlur(sampler2D tex, vec2 uv, float amt, float samples) {
    if (amt <= 0.0 || samples <= 1.0) return texture2D(tex, uv);

    vec4 c = vec4(0.0);
    float w = 0.0;
    int n = int(clamp(samples, 2.0, 24.0));

    for (int i = 0; i < 24; i++) {
        if (i >= n) break;
        for (int j = 0; j < 24; j++) {
            if (j >= n) break;
            float fi = (float(i) / float(n - 1) - 0.5) * 2.0;
            float fj = (float(j) / float(n - 1) - 0.5) * 2.0;
            float gw = exp(-(fi * fi + fj * fj) * 1.5);
            c += texture2D(tex, uv + vec2(fi, fj) * amt) * gw;
            w += gw;
        }
    }
    return c / max(w, 0.0001);
}

// ============================================================
// MAIN
// ============================================================

void main() {
    // Use vUvScaled as per Panzoid rules for proper buffer mapping
    vec2 uv = vUvScaled;

    // ---- Pattern space ----
    vec2 pUV = uv;
    pUV -= Pattern_Position / resolution;
    pUV = rot2(radians(Pattern_Angle)) * (pUV - 0.5) + 0.5;

    int pType = int(floor(Pattern_Type + 0.5));
    float pSize = max(Pattern_Size, 0.01);
    float pSmooth = max(Pattern_Smoothness, 0.0);

    // ---- Sample pattern ----
    float pat = samplePattern(pUV, pType, pSize, pSmooth);

    // ---- Displacement ----
    // Pattern drives displacement; 0.5 is neutral
    float d = (pat - 0.5) * 2.0;

    float dx = (X_Displacement / 100.0) * d;
    float dy = (Y_Displacement / 100.0) * d;

    // ---- FROST ----
    vec2 frostJitter = vec2(0.0);

    if (Frostiness > 0.0 && Frost_Scale > 0.0) {
        // Calculate frequency based on scale setting
        float frostFreq = 100.0 / max(Frost_Scale, 0.01);
        vec2 fuv = uv * frostFreq;

        // Generate independent noise for X and Y for a multi-directional scatter
        float nx = frostNoise(fuv);
        float ny = frostNoise(fuv + vec2(12.9898, 78.233)); // Offset Y sample

        // Map noise from [0, 1] to [-1, 1] bounds
        vec2 scatter = vec2(nx, ny) * 2.0 - 1.0;

        // Apply Intensity (0.05 is the max scatter distance in UV space)
        frostJitter = scatter * (Frostiness / 100.0) * 0.05; 
    }

    // ---- Final UV ----
    vec2 dUV = uv + vec2(dx, dy) + frostJitter;
    dUV = clamp(dUV, vec2(0.0), vec2(1.0)); // Prevent sampling out of bounds

    // ---- Blur ----
    float bAmt = Bluriness / 100.0 * 0.04;
    vec4 col = doBlur(tDiffuse, dUV, bAmt, Blur_Samples);

    // ---- Show Pattern Debug ----
    if (Show_Pattern > 0.5) {
        col = mix(col, vec4(vec3(pat), 1.0), 0.3);
    }

    gl_FragColor = col;
}

text./plugins/alipfx/shaders/glow.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

/* =========================
   14 USER PARAMETERS
   =========================
   Panzoid property name -> GLSL uniform

   1. Glow Based On      -> Glow_Based_On        (0=Alpha, 1=Color)
   2. Glow Threshold     -> Glow_Threshold       (0..100)
   3. Glow Radius        -> Glow_Radius          (pixels)
   4. Glow Intensity     -> Glow_Intensity       (0+)
   5. Composite Original -> Composite_Original   (0=On Top, 1=Behind, 2=None)
   6. Glow Operation     -> Glow_Operation       (0..24)
   7. Glow Colors        -> Glow_Colors          (0=Original Colors, 1=A & B Colors)
   8. Color Looping      -> Color_Looping        (0..3)
   9. Color Loops        -> Color_Loops          (>= 1)
   10. Color Phase       -> Color_Phase          (degrees; recommended 0..360)
   11. A & B Midpoint    -> A_B_Midpoint         (0..100)
   12. Color A           -> Color_A              (vec3)
   13. Color B           -> Color_B              (vec3)
   14. Glow Dimensions   -> Glow_Dimensions      (0=H+V, 1=H, 2=V)
*/

uniform float Glow_Based_On;
uniform float Glow_Threshold;
uniform float Glow_Radius;
uniform float Glow_Intensity;
uniform float Composite_Original;
uniform float Glow_Operation;
uniform float Glow_Colors;
uniform float Color_Looping;
uniform float Color_Loops;
uniform float Color_Phase;
uniform float A_B_Midpoint;
uniform vec3 Color_A;
uniform vec3 Color_B;
uniform float Glow_Dimensions;

const float PI = 3.1415926535897932384626433832795;

/* =========================
   Helpers
   ========================= */

float saturate1(float x) {
  return clamp(x, 0.0, 1.0);
}

vec3 saturate3(vec3 x) {
  return clamp(x, 0.0, 1.0);
}

float luma(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec4 overComposite(vec4 top, vec4 bottom) {
  float outA = top.a + bottom.a * (1.0 - top.a);
  vec3 outRGB = top.rgb + bottom.rgb * (1.0 - top.a);
  return vec4(outRGB, outA);
}

/* =========================
   RGB <-> HSL helpers
   Used for Hue / Saturation / Color / Luminosity
   ========================= */

vec3 rgb2hsl(vec3 c) {
  float maxc = max(max(c.r, c.g), c.b);
  float minc = min(min(c.r, c.g), c.b);
  float h = 0.0;
  float s = 0.0;
  float l = (maxc + minc) * 0.5;
  float d = maxc - minc;

  if (d > 1e-6) {
    s = d / (1.0 - abs(2.0 * l - 1.0));
    if (maxc == c.r) {
      h = mod((c.g - c.b) / d, 6.0);
    } else if (maxc == c.g) {
      h = ((c.b - c.r) / d) + 2.0;
    } else {
      h = ((c.r - c.g) / d) + 4.0;
    }
    h /= 6.0;
  }

  return vec3(h, s, l);
}

float hue2rgb(float p, float q, float t) {
  if (t < 0.0) t += 1.0;
  if (t > 1.0) t -= 1.0;
  if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
  if (t < 1.0 / 2.0) return q;
  if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
  return p;
}

vec3 hsl2rgb(vec3 hsl) {
  float h = hsl.x;
  float s = hsl.y;
  float l = hsl.z;

  float r, g, b;

  if (s < 1e-6) {
    r = g = b = l;
  } else {
    float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
    float p = 2.0 * l - q;
    r = hue2rgb(p, q, h + 1.0 / 3.0);
    g = hue2rgb(p, q, h);
    b = hue2rgb(p, q, h - 1.0 / 3.0);
  }

  return vec3(r, g, b);
}

/* =========================
   Blend modes
   These approximate AE/Ps-style blending
   ========================= */

vec3 blendNormal(vec3 base, vec3 blend) {
  return blend;
}

vec3 blendAdd(vec3 base, vec3 blend) {
  return base + blend;
}

vec3 blendMultiply(vec3 base, vec3 blend) {
  return base * blend;
}

vec3 blendScreen(vec3 base, vec3 blend) {
  return 1.0 - (1.0 - base) * (1.0 - blend);
}

vec3 blendOverlay(vec3 base, vec3 blend) {
  vec3 low  = 2.0 * base * blend;
  vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
  return mix(low, high, step(0.5, base));
}

vec3 blendSoftLight(vec3 base, vec3 blend) {
  return (1.0 - 2.0 * blend) * base * base + 2.0 * blend * base;
}

vec3 blendHardLight(vec3 base, vec3 blend) {
  vec3 low  = 2.0 * base * blend;
  vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
  return mix(low, high, step(0.5, blend));
}

vec3 blendDarken(vec3 base, vec3 blend) {
  return min(base, blend);
}

vec3 blendLighten(vec3 base, vec3 blend) {
  return max(base, blend);
}

vec3 blendDifference(vec3 base, vec3 blend) {
  return abs(base - blend);
}

vec3 blendExclusion(vec3 base, vec3 blend) {
  return base + blend - 2.0 * base * blend;
}

vec3 blendColorDodge(vec3 base, vec3 blend) {
  return base / max(vec3(1e-5), (1.0 - blend));
}

vec3 blendColorBurn(vec3 base, vec3 blend) {
  return 1.0 - ((1.0 - base) / max(vec3(1e-5), blend));
}

vec3 blendHue(vec3 base, vec3 blend) {
  vec3 hb = rgb2hsl(base);
  vec3 hs = rgb2hsl(blend);
  return hsl2rgb(vec3(hs.x, hb.y, hb.z));
}

vec3 blendSaturation(vec3 base, vec3 blend) {
  vec3 hb = rgb2hsl(base);
  vec3 hs = rgb2hsl(blend);
  return hsl2rgb(vec3(hb.x, hs.y, hb.z));
}

vec3 blendColorMode(vec3 base, vec3 blend) {
  vec3 hb = rgb2hsl(base);
  vec3 hs = rgb2hsl(blend);
  return hsl2rgb(vec3(hs.x, hs.y, hb.z));
}

vec3 blendLuminosity(vec3 base, vec3 blend) {
  vec3 hb = rgb2hsl(base);
  vec3 hs = rgb2hsl(blend);
  return hsl2rgb(vec3(hb.x, hb.y, hs.z));
}

/* =========================
   A/B color looping
   ========================= */

float midpointRemap(float x, float m) {
  // m in [0,1], shifts where A<->B transition occurs
  m = clamp(m, 0.001, 0.999);
  if (x < m) {
    return 0.5 * (x / m);
  } else {
    return 0.5 + 0.5 * ((x - m) / (1.0 - m));
  }
}

float waveSawAB(float t) {
  return fract(t);
}

float waveSawBA(float t) {
  return 1.0 - fract(t);
}

float waveTriABA(float t) {
  float x = fract(t);
  return 1.0 - abs(x * 2.0 - 1.0);
}

float waveTriBAB(float t) {
  float x = fract(t);
  return abs(x * 2.0 - 1.0);
}

vec3 evalABColor(float dist01) {
  float loops = max(1.0, Color_Loops);
  float phase = Color_Phase / 360.0;
  float t = dist01 * loops + phase;

  float mode = floor(Color_Looping + 0.5);
  float w;

  if (mode < 0.5) {
    w = waveSawAB(t);      // 0 = Sawtooth A>B
  } else if (mode < 1.5) {
    w = waveSawBA(t);      // 1 = Sawtooth B>A
  } else if (mode < 2.5) {
    w = waveTriABA(t);     // 2 = Triangle A>B>A
  } else {
    w = waveTriBAB(t);     // 3 = Triangle B>A>B
  }

  w = midpointRemap(w, A_B_Midpoint / 100.0);
  return mix(Color_A, Color_B, w);
}

/* =========================
   Source extraction
   ========================= */

vec4 sampleSource(vec2 uv, float dist01) {
  vec4 s = texture2D(tDiffuse, uv);

  float threshold = Glow_Threshold / 100.0;
  float basis;

  // 0 = Alpha Channel, 1 = Color Channels
  if (Glow_Based_On < 0.5) {
    basis = s.a;
  } else {
    basis = luma(s.rgb);
  }

  // small softness around threshold to avoid harsh clipping
  float mask = smoothstep(threshold - 0.02, threshold + 0.02, basis);

  // AE-like behavior:
  // Alpha mode = any opaque pixel can glow regardless of RGB brightness
  // Color mode = brightness drives glow
  if (Glow_Based_On < 0.5) {
    // alpha-based
    if (Glow_Colors < 0.5) {
      // original colors
      return vec4(s.rgb * mask, mask);
    } else {
      // A & B colors
      vec3 ab = evalABColor(dist01);
      return vec4(ab * mask, mask);
    }
  } else {
    // color-based
    if (Glow_Colors < 0.5) {
      // original colors
      return vec4(s.rgb * mask, mask);
    } else {
      // A & B colors
      vec3 ab = evalABColor(dist01);
      float strength = mask * basis;
      return vec4(ab * strength, strength);
    }
  }
}

/* =========================
   Glow blur accumulation
   ========================= */

vec4 buildGlow(vec2 uv) {
  float radiusPx = max(0.0, Glow_Radius);
  if (radiusPx < 0.001) {
    return vec4(0.0);
  }

  vec2 px = 1.0 / resolution;
  vec2 radiusUV = px * radiusPx;

  vec4 accum = vec4(0.0);
  float totalW = 0.0;

  float dims = floor(Glow_Dimensions + 0.5);

  // center contribution
  {
    vec4 c0 = sampleSource(uv, 0.0);
    float w0 = 1.0;
    accum += c0 * w0;
    totalW += w0;
  }

  if (dims < 0.5) {
    // 0 = Horizontal and Vertical (full 2D glow)
    const int DIRS = 8;
    const int STEPS = 6;

    for (int d = 0; d < DIRS; d++) {
      float ang = float(d) * (2.0 * PI / float(DIRS));
      vec2 dir = vec2(cos(ang), sin(ang));

      for (int i = 1; i <= STEPS; i++) {
        float t = float(i) / float(STEPS);
        vec2 off = dir * radiusUV * t;

        float w = exp(-4.0 * t * t); // gaussian-ish
        vec4 c = sampleSource(uv + off, t);
        accum += c * w;
        totalW += w;
      }
    }
  } else if (dims < 1.5) {
    // 1 = Horizontal
    const int STEPS = 10;
    for (int i = 1; i <= STEPS; i++) {
      float t = float(i) / float(STEPS);
      vec2 off = vec2(radiusUV.x * t, 0.0);
      float w = exp(-4.0 * t * t);

      vec4 c1 = sampleSource(uv + off, t);
      vec4 c2 = sampleSource(uv - off, t);

      accum += (c1 + c2) * w;
      totalW += 2.0 * w;
    }
  } else {
    // 2 = Vertical
    const int STEPS = 10;
    for (int i = 1; i <= STEPS; i++) {
      float t = float(i) / float(STEPS);
      vec2 off = vec2(0.0, radiusUV.y * t);
      float w = exp(-4.0 * t * t);

      vec4 c1 = sampleSource(uv + off, t);
      vec4 c2 = sampleSource(uv - off, t);

      accum += (c1 + c2) * w;
      totalW += 2.0 * w;
    }
  }

  vec4 glow = accum / max(totalW, 1e-5);
  glow.rgb *= Glow_Intensity;
  glow.a = saturate1(glow.a * Glow_Intensity);

  return glow;
}

/* =========================
   Glow Operation compositing
   ========================= */

vec4 applyGlowOperation(vec4 base, vec4 glow, vec2 uv) {
  int op = int(floor(Glow_Operation + 0.5));
  vec3 resultRGB = base.rgb;

  // Use glow alpha as blend amount
  float a = saturate1(glow.a);

  if (op == 0) {
    // None
    return glow;
  } else if (op == 1) {
    // Normal
    resultRGB = mix(base.rgb, blendNormal(base.rgb, glow.rgb), a);
  } else if (op == 2) {
    // Add
    resultRGB = base.rgb + glow.rgb;
  } else if (op == 3) {
    // Multiply
    resultRGB = mix(base.rgb, blendMultiply(base.rgb, glow.rgb), a);
  } else if (op == 4) {
    // Dissolve
    float n = hash12(floor(uv * resolution));
    float m = step(n, a);
    resultRGB = mix(base.rgb, glow.rgb, m);
  } else if (op == 5) {
    // Screen
    resultRGB = mix(base.rgb, blendScreen(base.rgb, glow.rgb), a);
  } else if (op == 6) {
    // Overlay
    resultRGB = mix(base.rgb, blendOverlay(base.rgb, glow.rgb), a);
  } else if (op == 7) {
    // Soft Light
    resultRGB = mix(base.rgb, blendSoftLight(base.rgb, glow.rgb), a);
  } else if (op == 8) {
    // Hard Light
    resultRGB = mix(base.rgb, blendHardLight(base.rgb, glow.rgb), a);
  } else if (op == 9) {
    // Darken
    resultRGB = mix(base.rgb, blendDarken(base.rgb, glow.rgb), a);
  } else if (op == 10) {
    // Lighten
    resultRGB = mix(base.rgb, blendLighten(base.rgb, glow.rgb), a);
  } else if (op == 11) {
    // Difference
    resultRGB = mix(base.rgb, blendDifference(base.rgb, glow.rgb), a);
  } else if (op == 12) {
    // Hue
    resultRGB = mix(base.rgb, blendHue(base.rgb, glow.rgb), a);
  } else if (op == 13) {
    // Saturation
    resultRGB = mix(base.rgb, blendSaturation(base.rgb, glow.rgb), a);
  } else if (op == 14) {
    // Color
    resultRGB = mix(base.rgb, blendColorMode(base.rgb, glow.rgb), a);
  } else if (op == 15) {
    // Luminosity
    resultRGB = mix(base.rgb, blendLuminosity(base.rgb, glow.rgb), a);
  } else if (op == 16) {
    // Color Dodge
    resultRGB = mix(base.rgb, blendColorDodge(base.rgb, glow.rgb), a);
  } else if (op == 17) {
    // Color Burn
    resultRGB = mix(base.rgb, blendColorBurn(base.rgb, glow.rgb), a);
  } else if (op == 18) {
    // Exclusion
    resultRGB = mix(base.rgb, blendExclusion(base.rgb, glow.rgb), a);
  } else if (op == 19) {
    // Stencil Alpha
    return vec4(glow.rgb * base.a, glow.a * base.a);
  } else if (op == 20) {
    // Stencil Luma
    float lm = luma(glow.rgb);
    return vec4(glow.rgb * lm, glow.a * lm);
  } else if (op == 21) {
    // Silhouette Alpha
    float cutA = base.a * (1.0 - glow.a);
    return vec4(base.rgb * cutA, cutA);
  } else if (op == 22) {
    // Silhouette Luma
    float cutL = 1.0 - saturate1(luma(glow.rgb));
    float outA = base.a * cutL;
    return vec4(base.rgb * outA, outA);
  } else if (op == 23) {
    // Luminescent Premultiply
    // Tries to avoid dark premult halos on transparency
    vec3 premulSafe = base.rgb + glow.rgb * (1.0 - base.a + glow.a);
    float outA = max(base.a, glow.a);
    return vec4(premulSafe, outA);
  } else if (op == 24) {
    // Alpha Add
    vec3 rgb = base.rgb + glow.rgb * glow.a;
    float outA = saturate1(base.a + glow.a);
    return vec4(rgb, outA);
  }

  float outA = 1.0 - (1.0 - base.a) * (1.0 - glow.a);
  return vec4(resultRGB, outA);
}

void main() {
  vec2 uv = vUvScaled;

  vec4 original = texture2D(tDiffuse, uv);
  vec4 glow = buildGlow(uv);

  // Composite Original:
  // 0 = On Top
  // 1 = Behind
  // 2 = None

  int comp = int(floor(Composite_Original + 0.5));
  vec4 finalColor;

  if (comp == 2) {
    // None = show only glow
    finalColor = glow;
  } else if (comp == 0) {
    // On Top = original over glow
    finalColor = overComposite(original, glow);
  } else {
    // Behind = glow blended onto original using Glow Operation
    finalColor = applyGlowOperation(original, glow, uv);
  }

  gl_FragColor = vec4(saturate3(finalColor.rgb), saturate1(finalColor.a));
}

text./plugins/alipfx/shaders/gradient-ramp.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// AE-like properties
uniform vec2 Start_of_Ramp;       // Default: vec2(0.5, 0.5)
uniform vec3 Start_Color;         // Default: vec3(1.0, 1.0, 1.0) (white)
uniform vec2 End_of_Ramp;         // Default: vec2(0.5, 1.0)
uniform vec3 End_Color;           // Default: vec3(0.0, 0.0, 0.0) (black)
uniform int Ramp_Shape;           // 0 = Linear, 1 = Radial
uniform float Ramp_Scatter;       // Default: 0.0
uniform float Blend_With_Original;// Default: 0.0 (gradient fully visible)
uniform int Swap_Colors;          // 0 = No, 1 = Yes

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
    vec4 original = texture2D(tDiffuse, vUvScaled);

    // Swap colors if enabled
    vec3 colorA = (Swap_Colors == 1) ? End_Color : Start_Color;
    vec3 colorB = (Swap_Colors == 1) ? Start_Color : End_Color;

    // Compute gradient factor
    float t;
    if (Ramp_Shape == 0) {
        // Linear gradient
        vec2 dir = End_of_Ramp - Start_of_Ramp;
        float len = length(dir);
        t = dot(vUvScaled - Start_of_Ramp, normalize(dir)) / len;
    } else {
        // Radial gradient
        float distStart = distance(vUvScaled, Start_of_Ramp);
        float distEnd = distance(End_of_Ramp, Start_of_Ramp);
        t = distStart / distEnd;
    }

    // Clamp and apply scatter
    t = clamp(t, 0.0, 1.0);
    t += (hash(vUvScaled * 100.0) - 0.5) * Ramp_Scatter;
    t = clamp(t, 0.0, 1.0);

    // Interpolate colors
    vec3 gradientColor = mix(colorA, colorB, t);

    // Blend logic fixed: gradient shows at Blend_With_Original = 0
    vec3 finalColor = mix(gradientColor, original.rgb, Blend_With_Original);

    gl_FragColor = vec4(finalColor, original.a);
}

text./plugins/alipfx/shaders/grid.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;

// Parameters
uniform vec2 Anchor;                // Anchor position
uniform int Size_from;              // 0 = Corner Point, 1 = Width, 2 = Width & Height
uniform vec2 Corner_Point;          // Used if Size_from = 0
uniform float Width;                // Used if Size_from = 1 or 2
uniform float Height;               // Used if Size_from = 2
uniform float Border;               // Thickness of grid lines
uniform float Feather_Width;        // Horizontal feather softness
uniform float Feather_Height;       // Vertical feather softness
uniform int Invert_grid;            // 0 = normal, 1 = inverted
uniform vec3 Color;                 // Grid color
uniform float Opacity;              // Opacity
uniform int Blending_mode;          // 0–18 blending modes

varying vec2 vUvScaled;

// Convert RGB to HSL
vec3 rgbToHsl(vec3 color) {
    float maxC = max(max(color.r, color.g), color.b);
    float minC = min(min(color.r, color.g), color.b);
    float delta = maxC - minC;

    float h = 0.0;
    if (delta > 0.0) {
        if (maxC == color.r) {
            h = mod((color.g - color.b) / delta, 6.0);
        } else if (maxC == color.g) {
            h = (color.b - color.r) / delta + 2.0;
        } else {
            h = (color.r - color.g) / delta + 4.0;
        }
        h /= 6.0;
    }
    float l = (maxC + minC) * 0.5;
    float s = (delta == 0.0) ? 0.0 : delta / (1.0 - abs(2.0 * l - 1.0));
    return vec3(h, s, l);
}

// Convert HSL to RGB
vec3 hslToRgb(vec3 hsl) {
    float h = hsl.x;
    float s = hsl.y;
    float l = hsl.z;

    float c = (1.0 - abs(2.0 * l - 1.0)) * s;
    float x = c * (1.0 - abs(mod(h * 6.0, 2.0) - 1.0));
    float m = l - c / 2.0;

    vec3 rgb;
    if (h < 1.0/6.0) rgb = vec3(c, x, 0.0);
    else if (h < 2.0/6.0) rgb = vec3(x, c, 0.0);
    else if (h < 3.0/6.0) rgb = vec3(0.0, c, x);
    else if (h < 4.0/6.0) rgb = vec3(0.0, x, c);
    else if (h < 5.0/6.0) rgb = vec3(x, 0.0, c);
    else rgb = vec3(c, 0.0, x);

    return rgb + m;
}

// Blending modes
vec4 blendModes(vec4 base, vec4 blend, int mode) {
    if (mode == 0) return blend; // None
    if (mode == 1) return mix(base, blend, blend.a); // Normal
    if (mode == 2) return vec4(blend.rgb * base.a, base.a); // Stencil Alpha
    if (mode == 3) return base + blend; // Add
    if (mode == 4) return base * blend; // Multiply
    if (mode == 5) return 1.0 - (1.0 - base) * (1.0 - blend); // Screen
    if (mode == 6) return mix(2.0 * base * blend, 1.0 - 2.0 * (1.0 - base) * (1.0 - blend), step(0.5, base.r)); // Overlay
    if (mode == 7) return mix(2.0 * blend * base, base + blend - 2.0 * base * blend, step(0.5, blend.r)); // Soft Light
    if (mode == 8) return mix(2.0 * base * blend, base + blend - 2.0 * base * blend, step(0.5, base.r)); // Hard Light
    if (mode == 9) return base / (1.0 - blend); // Color Dodge
    if (mode == 10) return 1.0 - (1.0 - base) / blend; // Color Burn
    if (mode == 11) return min(base, blend); // Darken
    if (mode == 12) return max(base, blend); // Lighten
    if (mode == 13) return abs(base - blend); // Difference
    if (mode == 14) return base + blend - 2.0 * base * blend; // Exclusion

    // Advanced HSL-based modes
    vec3 baseHSL = rgbToHsl(base.rgb);
    vec3 blendHSL = rgbToHsl(blend.rgb);

    if (mode == 15) return vec4(hslToRgb(vec3(blendHSL.x, baseHSL.y, baseHSL.z)), base.a); // Hue
    if (mode == 16) return vec4(hslToRgb(vec3(baseHSL.x, blendHSL.y, baseHSL.z)), base.a); // Saturation
    if (mode == 17) return vec4(hslToRgb(vec3(blendHSL.x, blendHSL.y, baseHSL.z)), base.a); // Color
    if (mode == 18) return vec4(hslToRgb(vec3(baseHSL.x, baseHSL.y, blendHSL.z)), base.a); // Luminosity

    return blend;
}

void main() {
    vec2 uv = vUvScaled;

    // Determine cell size
    float cellWidth = max(Width, 1.0);
    float cellHeight = (Size_from == 2) ? max(Height, 1.0) : cellWidth;

    if (Size_from == 0) {
        cellWidth = max(abs(Corner_Point.x - Anchor.x), 1.0);
        cellHeight = max(abs(Corner_Point.y - Anchor.y), 1.0);
    }

    // Compute grid lines
    float posX = (uv.x * resolution.x - Anchor.x);
    float posY = (uv.y * resolution.y - Anchor.y);

    float distX = abs(fract(posX / cellWidth) - 0.5) * cellWidth;
    float distY = abs(fract(posY / cellHeight) - 0.5) * cellHeight;

    float lineX = step(distX, Border);
    float lineY = step(distY, Border);
    float grid = (Invert_grid == 1) ? (1.0 - max(lineX, lineY)) : max(lineX, lineY);

    // Feather softness
    float fx = smoothstep(0.0, Feather_Width, distX - Border);
    float fy = smoothstep(0.0, Feather_Height, distY - Border);
    float feather = 1.0 - (fx * fy);
    feather = clamp(feather, 0.3, 1.0); // Prevent full fade for visibility

    vec4 baseTexel = texture2D(tDiffuse, uv);
    vec4 gridColor = vec4(Color, Opacity) * grid * feather;

    if (Blending_mode == 0) {
        gl_FragColor = gridColor;
        return;
    }

    gl_FragColor = blendModes(baseTexel, gridColor, Blending_mode);
}

text./plugins/alipfx/shaders/heisei-vhs.glsl:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms
uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
uniform float time;

// ==========================================
// CUSTOM PARAMETERS (30 Uniforms)
// ==========================================

// - Digital Layer
uniform float Apply_JPEG_Block_Noise;   
uniform float JPEG_Quality;             
uniform float Crush_Blacks;             
uniform float Blow_out_Whites;          

// - Hardware Layer
uniform float Apply_Thick_Ringing;      
uniform float Sharpen_Intensity;        
uniform float Sharpen_Width;            
uniform float Apply_Color_Cast;         
uniform float Red_Tint_Shift;           
uniform float Green_Tint_Shift;         
uniform float Blue_Tint_Shift;          

// - Analog Layer
uniform float Luminance_Bandwidth;      
uniform float Chroma_I_Bandwidth;       
uniform float Chroma_Q_Bandwidth;       
uniform float Chroma_Crosstalk;         
uniform float Chroma_Shift_X;           
uniform float Luma_Noise;               
uniform float Chroma_Noise;             

// - Mechanical Error
uniform float Jitter_Frequency;         
uniform float Jitter_Amplitude;         
uniform float Independent_Jitter;       
uniform float Jitter_Roughness;         
uniform float Head_Switch_Height;       
uniform float Bottom_Distortion;        
uniform float Bottom_Static_Density;    
uniform float Dropout_Count;            
uniform float Scratch_Max_Length;       
uniform float Scratch_Intensity;        
uniform float Apply_Scanlines;          
uniform float Scanline_Brightness;      

varying vec2 vUv;
varying vec2 vUvScaled;

// ==========================================
// MATH & SIGNAL HELPERS
// ==========================================

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0,0.0)), hash(i + vec2(1.0,0.0)), u.x),
               mix(hash(i + vec2(0.0,1.0)), hash(i + vec2(1.0,1.0)), u.x), u.y);
}

// RGB to YIQ Color Space
vec3 rgb2yiq(vec3 c) {
    return vec3(
        0.299 * c.r + 0.587 * c.g + 0.114 * c.b,
        0.596 * c.r - 0.274 * c.g - 0.322 * c.b,
        0.211 * c.r - 0.523 * c.g + 0.312 * c.b
    );
}

vec3 yiq2rgb(vec3 c) {
    return vec3(
        c.x + 0.956 * c.y + 0.621 * c.z,
        c.x - 0.272 * c.y - 0.647 * c.z,
        c.x - 1.106 * c.y + 1.703 * c.z
    );
}

void main() {
    vec2 baseUv = vUv;

    // ==========================================
    // 1. MECHANICAL ERROR (UV DISTORTION)
    // ==========================================

    float normHeight = Head_Switch_Height / 100.0;
    float bottomDistortionZone = step(baseUv.y, normHeight) * (1.0 - (baseUv.y / max(normHeight, 0.001)));

    if (baseUv.y < normHeight) {
        float wave = sin(baseUv.y * 150.0 + time * 20.0) * (Bottom_Distortion / resolution.x);
        baseUv.x += wave * bottomDistortionZone;
    }

    float jitterMask = step(hash(vec2(time * Jitter_Frequency * 10.0, 42.0)), 0.3);
    float jitterWave = (noise(vec2(baseUv.y * Jitter_Roughness * 10.0, time * 5.0)) - 0.5);
    float finalJitter = jitterWave * (Jitter_Amplitude / resolution.x) * jitterMask;

    vec2 uvR = baseUv;
    vec2 uvG = baseUv;
    vec2 uvB = baseUv;

    if (Independent_Jitter > 0.5) {
        uvR.x += finalJitter * 1.2;
        uvG.x -= finalJitter * 0.5;
        uvB.x += finalJitter * 0.8;
    } else {
        uvR.x += finalJitter;
        uvG.x += finalJitter;
        uvB.x += finalJitter;
    }

    // FIXED: Swapped baseUv.x and baseUv.y to make the dropouts horizontal instead of vertical
    float scratchTime = floor(time * 16.0); 
    float scratchIndex = floor(baseUv.y * (400.0 - Scratch_Max_Length)); // Y-axis row indexing
    float scratchCheck = step(hash(vec2(scratchIndex, scratchTime + 11.0)), 0.002 * Dropout_Count);
    float scratchLine = step(abs(hash(vec2(scratchIndex, scratchTime + 7.0)) - baseUv.x), 0.1 * Scratch_Intensity) * scratchCheck; // X-axis length check

    if (Apply_JPEG_Block_Noise > 0.5) {
        float blocks = max(1.0, JPEG_Quality);
        vec2 blockFactor = resolution / (blocks * 0.16);
        uvR = floor(uvR * blockFactor) / blockFactor;
        uvG = floor(uvG * blockFactor) / blockFactor;
        uvB = floor(uvB * blockFactor) / blockFactor;
    }

    vec4 texR = texture2D(tDiffuse, uvR * uvScale);
    vec4 texG = texture2D(tDiffuse, uvG * uvScale);
    vec4 texB = texture2D(tDiffuse, uvB * uvScale);

    vec3 color = vec3(texR.r, texG.g, texB.b);

    // ==========================================
    // 2. HARDWARE SIGNAL PROCESSING
    // ==========================================

    if (Apply_Thick_Ringing > 0.5) {
        vec2 shiftX = vec2(Sharpen_Width / resolution.x, 0.0);
        vec3 leftTex = texture2D(tDiffuse, (uvG - shiftX) * uvScale).rgb;
        vec3 rightTex = texture2D(tDiffuse, (uvG + shiftX) * uvScale).rgb;

        vec3 edgeHighPass = color - (leftTex + rightTex) * 0.5;
        color += edgeHighPass * Sharpen_Intensity;
    }

    if (Apply_Color_Cast > 0.5) {
        color.r *= Red_Tint_Shift;
        color.g *= Green_Tint_Shift;
        color.b *= Blue_Tint_Shift;
    }

    // ==========================================
    // 3. ANALOG SIGNAL & COMPOSITE BLURRING
    // ==========================================

    vec3 yiq = rgb2yiq(color);

    float chromaOffset = (Chroma_Shift_X / resolution.x);
    vec3 shiftedChroma = rgb2yiq(texture2D(tDiffuse, (uvG + vec2(chromaOffset, 0.0)) * uvScale).rgb);
    yiq.y = mix(yiq.y, shiftedChroma.y, 0.5);
    yiq.z = mix(yiq.z, shiftedChroma.z, 0.5);

    float lumaSpread = (1.0 - Luminance_Bandwidth) * (8.0 / resolution.x);
    float chromaI_Spread = (1.0 - Chroma_I_Bandwidth) * (16.0 / resolution.x);
    float chromaQ_Spread = (1.0 - Chroma_Q_Bandwidth) * (24.0 / resolution.x);

    float lumaBlur = rgb2yiq(texture2D(tDiffuse, (uvG + vec2(lumaSpread, 0.0)) * uvScale).rgb).x;
    float chromaI_Blur = rgb2yiq(texture2D(tDiffuse, (uvG + vec2(chromaI_Spread, 0.0)) * uvScale).rgb).y;
    float chromaQ_Blur = rgb2yiq(texture2D(tDiffuse, (uvG + vec2(chromaQ_Spread, 0.0)) * uvScale).rgb).z;

    yiq.x = mix(yiq.x, lumaBlur, 0.5);
    yiq.y = mix(yiq.y, chromaI_Blur, 0.7);
    yiq.z = mix(yiq.z, chromaQ_Blur, 0.7);

    yiq.y += yiq.x * Chroma_Crosstalk * 0.15;

    color = yiq2rgb(yiq);

    float baseNoise = hash(baseUv + vec2(time * 13.37, time * 37.13));
    color += (baseNoise - 0.5) * Luma_Noise * 0.18;

    vec3 chromaNoiseLayer = vec3(hash(baseUv + time), hash(baseUv * 1.5 - time), hash(baseUv * 0.7 + time)) - 0.5;
    color += chromaNoiseLayer * Chroma_Noise * 0.25;

    if (baseUv.y < normHeight) {
        float bottomStatic = hash(vec2(baseUv.x * 20.0, time * 30.0));
        if (bottomStatic < Bottom_Static_Density) {
            color = mix(color, vec3(bottomStatic), bottomStatic * bottomDistortionZone);
        }
    }

    // Scratch execution overlay (now properly horizontal)
    color = mix(color, vec3(0.95), scratchLine * Scratch_Intensity);

    // ==========================================
    // 4. DIGITAL LAYER LEVEL ADJUSTMENTS
    // ==========================================

    color = max(color - vec3(Crush_Blacks * 0.15), vec3(0.0));

    float whiteThreshold = Blow_out_Whites / 255.0;
    color = min(color / max(whiteThreshold, 0.001), vec3(1.0));

    if (Apply_Scanlines > 0.5) {
        float scanlinePattern = sin(vUv.y * resolution.y * 1.8) * 0.5 + 0.5;
        color = mix(color, color * scanlinePattern, (1.0 - Scanline_Brightness) * 0.65);
    }

    gl_FragColor = vec4(color, 1.0);
}

text./plugins/alipfx/shaders/hotwave.glsl:
precision highp float;
precision highp int;

// ============================================================
// HOTWAVE SHADER FOR PANZOID CM3
// 1:1 Match to After Effects Hotwave by BthJon on BOOTH
// ============================================================

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 uvScale;
uniform vec2 resolution;
uniform float time;

// --- DISTORTION (1-4) ---
uniform float Amount;
uniform float X_Bias;
uniform float Y_Bias;
uniform float Flow_Direction;

// --- NOISE (5-10) ---
uniform float Type;
uniform float Scale;
uniform float Octaves;
uniform float Persistence;
uniform float Lacunarity;
uniform float Random_Seed;

// --- ANIMATION (11-14) ---
uniform float Speed;
uniform float Wind_Direction;
uniform float Wind_Speed;
uniform float Evolution;

// --- HAZE/BLUR (15-16) ---
uniform float Blur_Strength;
uniform float Blur_Radius;

// --- GRADIENT MASK (17-20) ---
uniform float Enable_Mask;
uniform float Top;
uniform float Bottom;
uniform float Softness;

// --- CHROMATIC ABERRATION (21-24) ---
uniform float Direction;
uniform float Red_Offset;
uniform float Green_Offset;
uniform float Blue_Offset;

// --- SECONDARY TURBULENCE (25-27) ---
uniform float Enable_Turb;
uniform float Sec_Scale;
uniform float Sec_Speed;

// --- STEAM/VAPOR (28-33) ---
uniform float Enable_Steam;
uniform float Steam_Dir;
uniform float Steam_Scale;
uniform float Steam_Density;
uniform float Steam_Opacity;
uniform float Steam_Speed;

// ============================================================
// NOISE FUNCTIONS
// ============================================================

vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                       -0.577350269189626, 0.024390243902439);
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod289(i);
    vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
                     + i.x + vec3(0.0, i1.x, 1.0));
    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
                            dot(x12.zw,x12.zw)), 0.0);
    m = m*m; m = m*m;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
    vec3 g;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

float billowed(vec2 p) { return abs(snoise(p)); }
float ridged(vec2 p) { return 1.0 - abs(snoise(p)); }
float standard(vec2 p) { return snoise(p) * 0.5 + 0.5; }

float fbm(vec2 p, float oct, float persist, float lacun, float ntype) {
    float total = 0.0, amp = 1.0, freq = 1.0, maxv = 0.0;
    float pn = persist / 100.0;
    float ln = lacun / 1000.0;
    int o = int(floor(oct));

    for (int i = 0; i < 8; i++) {
        if (i >= o) break;
        vec2 sp = p * freq;
        float n;
        if (ntype < 0.5) n = billowed(sp);
        else if (ntype < 1.5) n = ridged(sp);
        else n = standard(sp);
        total += n * amp;
        maxv += amp;
        amp *= pn;
        freq *= ln;
    }

    float fo = fract(oct);
    if (fo > 0.0 && o < 8) {
        vec2 sp = p * freq;
        float n;
        if (ntype < 0.5) n = billowed(sp);
        else if (ntype < 1.5) n = ridged(sp);
        else n = standard(sp);
        total += n * amp * fo;
        maxv += amp * fo;
    }
    return total / maxv;
}

// ============================================================
// UTILITIES
// ============================================================

float deg2rad(float d) { return d * 0.01745329252; }

vec4 gblur(sampler2D t, vec2 uv, float r) {
    float px = r / resolution.x;
    float py = r / resolution.y;
    vec4 c = texture2D(t, uv) * 0.227027;
    c += texture2D(t, uv + vec2(px*1.0, 0.0)) * 0.1945946;
    c += texture2D(t, uv - vec2(px*1.0, 0.0)) * 0.1945946;
    c += texture2D(t, uv + vec2(px*2.0, 0.0)) * 0.1216216;
    c += texture2D(t, uv - vec2(px*2.0, 0.0)) * 0.1216216;
    c += texture2D(t, uv + vec2(px*3.0, 0.0)) * 0.054054;
    c += texture2D(t, uv - vec2(px*3.0, 0.0)) * 0.054054;
    c += texture2D(t, uv + vec2(px*4.0, 0.0)) * 0.016216;
    c += texture2D(t, uv - vec2(px*4.0, 0.0)) * 0.016216;

    vec4 c2 = texture2D(t, uv) * 0.227027;
    c2 += texture2D(t, uv + vec2(0.0, py*1.0)) * 0.1945946;
    c2 += texture2D(t, uv - vec2(0.0, py*1.0)) * 0.1945946;
    c2 += texture2D(t, uv + vec2(0.0, py*2.0)) * 0.1216216;
    c2 += texture2D(t, uv - vec2(0.0, py*2.0)) * 0.1216216;
    c2 += texture2D(t, uv + vec2(0.0, py*3.0)) * 0.054054;
    c2 += texture2D(t, uv - vec2(0.0, py*3.0)) * 0.054054;
    c2 += texture2D(t, uv + vec2(0.0, py*4.0)) * 0.016216;
    c2 += texture2D(t, uv - vec2(0.0, py*4.0)) * 0.016216;
    return (c + c2) * 0.5;
}

// ============================================================
// MAIN
// ============================================================

void main() {
    vec2 uv = vUvScaled;
    float seed = Random_Seed * 100.0;
    float t = time;

    // Animation
    float animT = t * Speed * 0.001 + deg2rad(Evolution);
    float windT = t * Wind_Speed * 0.01;

    // Directions
    float fRad = deg2rad(Flow_Direction);
    vec2 fDir = vec2(sin(fRad), cos(fRad));
    float wRad = deg2rad(Wind_Direction);
    vec2 wDir = vec2(sin(wRad), cos(wRad));

    // --- GRADIENT MASK ---
    float mask = 1.0;
    if (Enable_Mask > 0.5) {
        float topN = Top / 100.0;
        float botN = Bottom / 100.0;
        float soft = max(Softness / 100.0, 0.001);
        float gp = 1.0 - uv.y;
        float mv = smoothstep(topN - soft, topN + soft, gp);
        mv *= smoothstep(botN + soft, botN - soft, gp);
        mask = mix(topN, botN, mv);
        mask = clamp(mask, 0.0, 1.0);
    }

    // --- MAIN NOISE ---
    float nScale = Scale * 0.0001;
    vec2 nPos = uv * nScale + seed;
    nPos += wDir * windT * 0.1;
    nPos += fDir * animT * 0.1;
    float mainN = fbm(nPos, Octaves, Persistence, Lacunarity, Type);

    // --- SECONDARY TURBULENCE ---
    float secN = 0.0;
    if (Enable_Turb > 0.5) {
        float ss = Sec_Scale * 0.0001;
        float st = t * Sec_Speed * 0.001;
        vec2 sp = uv * ss + seed + 50.0;
        sp += fDir * st * 0.1;
        secN = fbm(sp, Octaves, Persistence, Lacunarity, Type);
    }

    float cNoise = Enable_Turb > 0.5 ? mix(mainN, secN, 0.5) : mainN;

    // --- DISTORTION ---
    float xBias = (X_Bias - 50.0) / 50.0;
    float yBias = (Y_Bias - 50.0) / 50.0;
    float amt = Amount / 100.0;

    vec2 distOff = fDir * cNoise * amt * 0.05;
    distOff += vec2(xBias, yBias) * amt * 0.02;
    distOff *= mask;

    // --- STEAM/VAPOR ---
    float steamM = 0.0;
    if (Enable_Steam > 0.5) {
        float ssc = Steam_Scale * 0.0001;
        float sst = t * Steam_Speed * 0.001;
        float sRad = deg2rad(Steam_Dir);
        vec2 sDir = vec2(sin(sRad), cos(sRad));
        vec2 sp = uv * ssc + seed + 100.0;
        sp += sDir * sst * 0.2;
        float sn = fbm(sp, max(Octaves * 0.5, 1.0), Persistence, Lacunarity, 0.0);
        float dens = Steam_Density / 100.0;
        float opa = Steam_Opacity / 100.0;
        steamM = smoothstep(1.0 - dens, 1.0, sn) * opa;
        steamM *= mask;
    }

    // --- BLUR / HAZE ---
    float blurAmt = Blur_Strength / 100.0;
    vec4 col;
    if (Blur_Radius > 0.5 && blurAmt > 0.01) {
        vec4 blurC = gblur(tDiffuse, uv + distOff, Blur_Radius);
        vec4 sharpC = texture2D(tDiffuse, uv + distOff);
        col = mix(sharpC, blurC, blurAmt * mask);
    } else {
        col = texture2D(tDiffuse, uv + distOff);
    }

    // --- CHROMATIC ABERRATION ---
    if (abs(Red_Offset) > 0.1 || abs(Green_Offset) > 0.1 || abs(Blue_Offset) > 0.1) {
        float caRad = deg2rad(Direction);
        vec2 caDir = vec2(sin(caRad), cos(caRad));
        vec2 rOff = caDir * Red_Offset / resolution + distOff * 0.5;
        vec2 gOff = caDir * Green_Offset / resolution + distOff * 0.5;
        vec2 bOff = caDir * Blue_Offset / resolution + distOff * 0.5;
        col.r = texture2D(tDiffuse, uv + rOff).r;
        col.g = texture2D(tDiffuse, uv + gOff).g;
        col.b = texture2D(tDiffuse, uv + bOff).b;
    }

    // --- APPLY STEAM ---
    if (Enable_Steam > 0.5 && steamM > 0.001) {
        vec3 steamCol = vec3(0.95, 0.93, 0.90);
        col.rgb = mix(col.rgb, steamCol, steamM);
    }

    gl_FragColor = col;
}

text./plugins/alipfx/shaders/hsl-noise-auto.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform float time;

uniform float Noise;        // 0 = Uniform, 1 = Squared, 2 = Grain
uniform float Hue;          // intensity of hue noise
uniform float Saturation;   // intensity of saturation noise
uniform float Lightness;    // intensity of lightness noise
uniform float GrainSize;    // only used when Noise == 2
uniform float NoiseSpeed;   // frames per second

varying vec2 vUvScaled;

/* ===============================
   High-Precision Random Generator
   (Replaced sin() to permanently fix diagonal banding)
================================ */
float rand(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

/* ===============================
   RGB ↔ HSL Conversion
================================ */
vec3 rgb2hsl(vec3 color) {
    float maxC = max(color.r, max(color.g, color.b));
    float minC = min(color.r, min(color.g, color.b));
    float L = (maxC + minC) * 0.5;
    float H = 0.0;
    float S = 0.0;

    if(maxC != minC) {
        float d = maxC - minC;
        S = L > 0.5 ? d / (2.0 - maxC - minC) : d / (maxC + minC);
        if(maxC == color.r) H = (color.g - color.b) / d + (color.g < color.b ? 6.0 : 0.0);
        else if(maxC == color.g) H = (color.b - color.r) / d + 2.0;
        else H = (color.r - color.g) / d + 4.0;
        H /= 6.0;
    }
    return vec3(H, S, L);
}

float hue2rgb(float p, float q, float t) {
    if(t < 0.0) t += 1.0;
    if(t > 1.0) t -= 1.0;
    if(t < 1.0/6.0) return p + (q - p) * 6.0 * t;
    if(t < 1.0/2.0) return q;
    if(t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
    return p;
}

vec3 hsl2rgb(vec3 hsl) {
    float H = hsl.x;
    float S = hsl.y;
    float L = hsl.z;
    float r, g, b;

    if(S == 0.0) {
        r = g = b = L;
    } else {
        float q = L < 0.5 ? L * (1.0 + S) : L + S - L * S;
        float p = 2.0 * L - q;
        r = hue2rgb(p, q, H + 1.0/3.0);
        g = hue2rgb(p, q, H);
        b = hue2rgb(p, q, H - 1.0/3.0);
    }
    return vec3(r, g, b);
}

/* ===============================
   Main
================================ */
void main() {
    vec4 base = texture2D(tDiffuse, vUvScaled);
    vec3 hsl = rgb2hsl(base.rgb);

    // Calculate animation seed based on time and desired FPS.
    // Wrapped with mod() to prevent precision failure if the composition is very long.
    float seed = mod(floor(time * NoiseSpeed), 10000.0);

    // Determine grain scaling
    float actualGrainSize = (Noise >= 1.5) ? max(GrainSize, 1.0) : 1.0;

    // Use exact screen coordinates to ensure pure, crisp static
    vec2 pixelCoord = floor(gl_FragCoord.xy / actualGrainSize);

    // Generate independent noise for H, S, and L using the new hash function.
    float n_h = rand(pixelCoord + vec2(seed * 13.0, seed * 17.0));
    float n_s = rand(pixelCoord + vec2(seed * 23.0 + 123.4, seed * 29.0 + 567.8));
    float n_l = rand(pixelCoord + vec2(seed * 31.0 + 890.1, seed * 37.0 + 234.5));

    // Apply the "Squared" mode correctly if selected (Noise == 1)
    if (Noise > 0.5 && Noise < 1.5) {
        n_h = n_h * n_h * (3.0 - 2.0 * n_h);
        n_s = n_s * n_s * (3.0 - 2.0 * n_s);
        n_l = n_l * n_l * (3.0 - 2.0 * n_l);
    }

    // Apply noise directly to the HSL channels divided by 100
    hsl.x += (Hue / 100.0) * (n_h - 0.5);
    hsl.y += (Saturation / 100.0) * (n_s - 0.5);
    hsl.z += (Lightness / 100.0) * (n_l - 0.5);

    // Wrap hue, clamp saturation and lightness
    hsl.x = fract(hsl.x);
    hsl.y = clamp(hsl.y, 0.0, 1.0);
    hsl.z = clamp(hsl.z, 0.0, 1.0);

    vec3 finalColor = hsl2rgb(hsl);
    gl_FragColor = vec4(finalColor, base.a);
}

text./plugins/alipfx/shaders/hsl-noise.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom properties
uniform float Noise;        // 0=Uniform, 1=Squared, 2=Grain
uniform float Hue;          // Hue noise intensity
uniform float Saturation;   // Saturation noise intensity
uniform float Lightness;    // Lightness noise intensity
uniform float Grain_Size;   // Grain size when Noise=2
uniform float Noise_Phase;  // Phase for animated noise

// Helper: Random generator
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898,78.233))) * 43758.5453);
}

// Convert RGB to HSL
vec3 rgb2hsl(vec3 color) {
    float maxC = max(max(color.r, color.g), color.b);
    float minC = min(min(color.r, color.g), color.b);
    float l = (maxC + minC) * 0.5;
    float s = 0.0;
    float h = 0.0;
    if(maxC != minC){
        float d = maxC - minC;
        s = l > 0.5 ? d / (2.0 - maxC - minC) : d / (maxC + minC);
        if(maxC == color.r) h = (color.g - color.b) / d + (color.g < color.b ? 6.0 : 0.0);
        else if(maxC == color.g) h = (color.b - color.r) / d + 2.0;
        else h = (color.r - color.g) / d + 4.0;
        h /= 6.0;
    }
    return vec3(h, s, l);
}

// Convert HSL back to RGB
vec3 hsl2rgb(vec3 hsl) {
    float h = hsl.x, s = hsl.y, l = hsl.z;
    float r, g, b;
    if(s == 0.0){ r = g = b = l; }
    else {
        float q = l < 0.5 ? l * (1.0 + s) : l + s - l * s;
        float p = 2.0 * l - q;
        float hk = h;
        float t[3];
        t[0] = hk + 1.0/3.0;
        t[1] = hk;
        t[2] = hk - 1.0/3.0;
        for(int i=0;i<3;i++){
            if(t[i] < 0.0) t[i] += 1.0;
            if(t[i] > 1.0) t[i] -= 1.0;
            if(t[i] < 1.0/6.0) t[i] = p + (q - p) * 6.0 * t[i];
            else if(t[i] < 1.0/2.0) t[i] = q;
            else if(t[i] < 2.0/3.0) t[i] = p + (q - p) * (2.0/3.0 - t[i]) * 6.0;
            else t[i] = p;
        }
        r = t[0]; g = t[1]; b = t[2];
    }
    return vec3(r,g,b);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 hsl = rgb2hsl(texel.rgb);

    // FIX 1: Use gl_FragCoord for exact screen pixels. 
    // This removes the "glitch" (diagonal lines) but keeps the noise.
    float safeGrainSize = max(Grain_Size, 1.0);
    vec2 pixelCoord = floor(gl_FragCoord.xy / safeGrainSize);

    // FIX 2: Generate INDEPENDENT random noise for H, S, and L.
    // If you use the exact same random number for all three channels, 
    // it won't look like After Effects. We offset the coordinates slightly for each.
    float n_h = rand(pixelCoord + Noise_Phase + vec2(0.0, 0.0));
    float n_s = rand(pixelCoord + Noise_Phase + vec2(12.34, 56.78));
    float n_l = rand(pixelCoord + Noise_Phase + vec2(87.65, 43.21));

    if(Noise == 1.0) {
        // Squared noise (adjusted so it doesn't artificially darken the whole image)
        n_h = n_h * n_h * (3.0 - 2.0 * n_h);
        n_s = n_s * n_s * (3.0 - 2.0 * n_s);
        n_l = n_l * n_l * (3.0 - 2.0 * n_l);
    }

    // Apply HLS noise
    hsl.x += Hue * (n_h - 0.5);
    hsl.y += Saturation * (n_s - 0.5);
    hsl.z += Lightness * (n_l - 0.5);

    // Wrap hue, clamp saturation and lightness
    hsl.x = fract(hsl.x); 
    hsl.y = clamp(hsl.y, 0.0, 1.0);
    hsl.z = clamp(hsl.z, 0.0, 1.0);

    vec3 rgb = hsl2rgb(hsl);
    gl_FragColor = vec4(rgb, texel.a);
}

text./plugins/alipfx/shaders/hydrochrome.glsl:
precision highp float;
precision highp int;

// Panzoid Built-ins
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

// Built-in project clock
uniform float time; 

// Parameters
uniform float Iterations;       
uniform float Seed;             
uniform float Follow_Comp_Time; // 1.0 = Auto, 0.0 = Manual
uniform float Time_Offset;      
uniform float UniformDisplace;  
uniform float X_Displace;       
uniform float Y_Displace;       
uniform float Displace_Angle;   
uniform float Hue_Shift;        
uniform float Chromatic;        
uniform float Adding;           
uniform float Power;            
uniform float Multiplier;       

mat2 rotate2d(float angle){
    return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
}

vec3 applyHue(vec3 col, float h) {
    vec3 k = vec3(0.57735, 0.57735, 0.57735);
    float a = radians(h);
    float cosA = cos(a);
    return col * cosA + cross(k, col) * sin(a) + k * dot(k, col) * (1.0 - cosA);
}

void main()
{
    // Capture original texture for alpha preservation
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // Setup UVs centered for liquid math
    vec2 st = (vUvScaled / uvScale) * 2.0 - 1.0;
    st.x *= resolution.x / resolution.y;

    // Time Logic: Uses internal clock if Follow_Comp_Time > 0.5
    float t = (Follow_Comp_Time > 0.5) ? (time + Time_Offset) : Time_Offset; 

    // Seed Logic: Offsets coordinates to randomize the pattern
    vec2 p = st + vec2(Seed * 1.618, Seed * 0.707);

    float angle = radians(Displace_Angle);
    float yFactor = (UniformDisplace > 0.5) ? 0.0 : 1.0;
    vec2 amp = vec2(X_Displace, Y_Displace * yFactor) * 0.01;

    p *= rotate2d(angle);

    // Liquid Iterations (1-20)
    int iterLimit = int(clamp(Iterations, 1.0, 20.0));
    for(int i = 0; i < 20; i++) {
        if (i >= iterLimit) break;
        p += sin(p.yx * 2.2 + vec2(t * 1.1, t * 0.9)) * amp;
        p *= 1.05; 
        p *= rotate2d(0.5 + Seed * 0.001); 
    }

    // Color Generation with multi-phase offset for full hue spectrum
    float chrom = Chromatic * 0.05;
    vec3 color;
    color.r = sin(p.x + p.y - chrom) * 0.5 + 0.5;
    color.g = sin(p.x + p.y) * 0.5 + 0.5;
    color.b = sin(p.x + p.y + chrom) * 0.5 + 0.5;

    // Blending and Brightness
    color += vec3(Adding * 0.01);   
    color *= vec3(Multiplier * 0.01);  
    color = pow(max(color, 0.0001), vec3(max(0.1, Power * 0.01)));

    // Final Hue Shift
    vec3 finalRGB = applyHue(color, Hue_Shift);

    // Output final result using original texture alpha
    gl_FragColor = vec4(finalRGB, texel.a);
}

text./plugins/alipfx/shaders/impact-lines.gls:
