uniform float Depth_Curve;
uniform float FPS;

// ==================== ADVANCED EVOLUTION ====================
uniform float Evolution_Enable;        // 0=Disabled, 1=Enabled
uniform float Auto_Evolution;          // 0=Disabled, 1=Enabled
uniform float Auto_Evolution_Speed;
uniform float Evolution;
uniform float Evolution_Amount;
uniform float Evolution_Speed;
uniform float Evolution_Angle;
uniform float Evolution_Rotation;
uniform float Evolution_Rotation_Randomness;
uniform float Evolution_Length;
uniform float Evolution_Thickness;
uniform float Evolution_Opacity;

// ==================== OUTPUT ====================
uniform float Output_Mode;             // 0=Composite, 1=Lines Only
uniform float Blend_Mode;              // 0=Normal, 1=Add, 2=Multiply

// ============================================================
// HASH & NOISE FUNCTIONS
// ============================================================
float hash(float n) { return fract(sin(n) * 43758.5453123); }
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float hash(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }

// ============================================================
// SDF FOR ROUND-CAP SEGMENT
// ============================================================
float sdSegmentRound(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// ============================================================
// MAIN
// ============================================================
void main() {
    vec2 px = vUv * resolution;
    vec4 inputColor = texture2D(tDiffuse, vUvScaled);

    // FPS stepping for stop-motion feel
    float t = time;
    if (FPS > 1.0) {
        t = floor(time * FPS) / FPS;
    }

    // Evolution time
    float evoTime = Evolution;
    if (Evolution_Enable > 0.5 && Auto_Evolution > 0.5) {
        evoTime += t * Auto_Evolution_Speed;
    }
    float evoVal = evoTime * Evolution_Speed;
    float evoAmt = clamp(Evolution_Amount / 100.0, 0.0, 1.0);

    // Line accumulation buffer
    vec4 lineAccum = vec4(0.0);
    if (Blend_Mode > 1.5) lineAccum = vec4(1.0, 1.0, 1.0, 0.0);

    int lineCount = int(min(Lines, 300.0));
    float varNorm = clamp(Variation / 100.0, 0.0, 1.0);

    for (int i = 0; i < 300; i++) {
        if (i >= lineCount) break;

        float fi = float(i);
        float lineSeed = Seed + fi * 137.0 + floor(evoTime * 0.01) * 0.0; // prevent unroll issues

        // --------------------------------------------------------
        // 1. CALCULATE BASE GEOMETRY
        // --------------------------------------------------------
        vec2 p1, p2;
        float baseAngle = 0.0;
        vec2 lineDir = vec2(1.0, 0.0);
        vec2 linePerp = vec2(0.0, 1.0);
        float lineLenEst = 100.0;

        if (Mode < 0.5) {
            // ---- RADIAL LINES ----

            // Base angle distribution
            if (Lines > 1.5) {
                float tNorm = fi / (Lines - 1.0);
                baseAngle = (Angle_Offset + (tNorm - 0.5) * Angle_Range) * 0.01745329252;
            } else {
                baseAngle = Angle_Offset * 0.01745329252;
            }

            // Global rotation
            baseAngle += Rotation * 0.01745329252;

            // Variation (simplified all-in-one)
            baseAngle += (hash(lineSeed + 1.0) - 0.5) * varNorm * 1.0;

            // Advanced Variation - Angle
            baseAngle += (hash(lineSeed + 10.0) - 0.5) * (Angle_Randomness / 100.0) * 1.57079632679;

            // Rotation Randomness
            baseAngle += (hash(lineSeed + 11.0) - 0.5) * (Rotation_Randomness / 100.0) * 1.57079632679;

            // Evolution - Angle (wave from center)
            if (Evolution_Enable > 0.5) {
                baseAngle += sin(fi * 0.5 + evoVal) * (Evolution_Angle / 100.0) * evoAmt * 1.57079632679;
                baseAngle += evoVal * Evolution_Rotation * 0.01745329252;
                baseAngle += (hash(lineSeed + 100.0 + evoTime * 0.1) - 0.5) * (Evolution_Rotation_Randomness / 100.0) * 6.28318530718 * evoAmt;
            }

            lineDir = vec2(cos(baseAngle), sin(baseAngle));
            linePerp = vec2(-lineDir.y, lineDir.x);

            // Radial expansion (keeps inner/outer ratio)
            float ratio = Outer_Radius / max(Center_Gap, 0.001);
            float innerR = Center_Gap + Radial_Expansion;
            float outerR = innerR * ratio;

            // Apply Y-scale to create ellipse
            vec2 scaleVec = vec2(1.0, Radial_Y_Scale);

            // Length randomness
            float lenRand = hash(lineSeed + 20.0);
            outerR *= mix(1.0, 0.2 + lenRand * 1.8, Length_Randomness / 100.0);

            // Evolution length
            if (Evolution_Enable > 0.5) {
                outerR *= mix(1.0, 0.5 + 0.5 * sin(evoVal * 1.1 + fi * 0.7), (Evolution_Length / 100.0) * evoAmt);
            }

            p1 = Center + lineDir * innerR * scaleVec;
            p2 = Center + lineDir * outerR * scaleVec;

            // Start position randomness (along direction)
            float startPosRand = (hash(lineSeed + 30.0) - 0.5) * Start_Position_Randomness;
            p1 += lineDir * startPosRand * scaleVec;

            lineLenEst = length(p2 - p1);

        } else {
            // ---- SPEED LINES ----

            float speedAngle = (Rotation + Angle_Offset) * 0.01745329252;
            lineDir = vec2(cos(speedAngle), sin(speedAngle));
            linePerp = vec2(-lineDir.y, lineDir.x);

            // Distribute along perpendicular axis
            float perpPos = 0.0;
            if (Lines > 1.5) {
                perpPos = (fi / (Lines - 1.0) - 0.5) * max(resolution.x, resolution.y) * 1.5;
            }

            // Speed position randomness
            perpPos += (hash(lineSeed + 2.0) - 0.5) * Speed_Position_Randomness;

            // Speed spacing randomness
            perpPos += hash(lineSeed + 3.0) * Speed_Spacing_Randomness;

            // General variation
            perpPos += (hash(lineSeed + 4.0) - 0.5) * varNorm * 200.0;

            // Line length
            float sLen = Speed_Line_Length;
            if (sLen < 1.0) sLen = max(resolution.x, resolution.y) * 1.5;

            // Length randomness
            sLen *= mix(1.0, 0.3 + hash(lineSeed + 20.0) * 1.4, Length_Randomness / 100.0);

            // Evolution length
            if (Evolution_Enable > 0.5) {
                sLen *= mix(1.0, 0.5 + 0.5 * sin(evoVal * 1.1 + fi * 0.7), (Evolution_Length / 100.0) * evoAmt);
            }

            vec2 lineCenter = Center + linePerp * perpPos;

            // Infinite Speed Line / Flow offset
            float flowOffset = 0.0;
            if (abs(Animate - 3.0) < 0.5 || abs(Animate - 2.0) < 0.5) {
                float phase = Flow_Phase;
                if (Auto_Animation > 0.5) phase += t * Speed;

                float lineSpeed = Speed;
                if (Speed_Variation > 0.0) {
                    lineSpeed *= mix(1.0, 0.3 + hash(lineSeed + 800.0) * 1.4, Speed_Variation / 100.0);
                }

                float moveDist = phase * lineSpeed * 300.0;
                if (Direction > 0.5) moveDist = -moveDist;

                float wrapWidth = sLen * 3.0;
                flowOffset = mod(moveDist + fi * (wrapWidth / max(Lines, 1.0)) + hash(lineSeed + 5.0) * wrapWidth, wrapWidth) - wrapWidth * 0.5;
            }

            lineCenter += lineDir * flowOffset;
            p1 = lineCenter - lineDir * sLen * 0.5;
            p2 = lineCenter + lineDir * sLen * 0.5;
            lineLenEst = sLen;
        }

        // --------------------------------------------------------
        // 2. GROW ANIMATION
        // --------------------------------------------------------
        if (abs(Animate - 1.0) < 0.5) {
            float phase = clamp(Grow_Phase, 0.0, 1.0);
            if (Auto_Animation > 0.5) {
                phase = fract(t * Speed);
            }

            vec2 fullP1 = p1;
            vec2 fullP2 = p2;
            vec2 mid = (fullP1 + fullP2) * 0.5;
            vec2 halfVec = (fullP2 - fullP1) * 0.5;

            if (Direction < 0.5) {
                // Outward growth
                if (Length_Origin < 0.5) {
                    p2 = mix(fullP1, fullP2, phase);
                } else if (abs(Length_Origin - 1.0) < 0.5) {
                    p1 = mid - halfVec * phase;
                    p2 = mid + halfVec * phase;
                } else {
                    p1 = mix(fullP2, fullP1, 1.0 - phase);
                }
            } else {
                // Inward growth
                if (Length_Origin < 0.5) {
                    p1 = mix(fullP2, fullP1, 1.0 - phase);
                } else if (abs(Length_Origin - 1.0) < 0.5) {
                    p1 = mid + halfVec * phase;
                    p2 = mid - halfVec * phase;
                } else {
                    p2 = mix(fullP1, fullP2, 1.0 - phase);
                }
            }
        }

        // --------------------------------------------------------
        // 3. DISTANCE TO LINE SEGMENT
        // --------------------------------------------------------
        vec2 ba = p2 - p1;
        float segLen = length(ba);
        if (segLen < 0.001) continue;

        vec2 dirNorm = ba / segLen;
        vec2 perpNorm = vec2(-dirNorm.y, dirNorm.x);

        // Base projection for clean lines
        vec2 pa = px - p1;
        float tProj = clamp(dot(pa, dirNorm) / segLen, 0.0, 1.0);
        vec2 closest = p1 + dirNorm * segLen * tProj;
        float dist = length(px - closest);
        float bestT = tProj;

        // Styled lines: sample along path
        int samples = 1;
        if (abs(Line_Style - 1.0) < 0.5) samples = int(clamp(Style_Count * 3.0, 4.0, 40.0));
        else if (abs(Line_Style - 2.0) < 0.5) samples = 24;
        else if (Rough_Edge > 0.01) samples = 12;

        if (samples > 1) {
            float minD = dist;
            for (int s = 0; s < 40; s++) {
                if (s >= samples) break;
                float ts = float(s) / max(float(samples - 1), 1.0);
                vec2 pos = p1 + dirNorm * segLen * ts;

                if (abs(Line_Style - 1.0) < 0.5) {
                    // Zigzag
                   float phase = ts * max(Style_Count, 1.0) * 6.28318530718;
                   float wave = asin(sin(phase)) / 1.57079632679 * Style_Amount;
                    pos += perpNorm * wave;
                } else if (abs(Line_Style - 2.0) < 0.5) {
                    // Tilda (sine wave)
                    float wave = sin(ts * max(Style_Count, 1.0) * 6.28318530718) * Style_Amount;
                    pos += perpNorm * wave;
                }

                float d = length(px - pos);
                if (d < minD) {
                    minD = d;
                    bestT = ts;
                }
            }
            dist = minD;
        }

        // Rough edge noise
        if (Rough_Edge > 0.01) {
            float edgeNoise = (hash(vec2(bestT * 40.0, lineSeed + 200.0)) - 0.5) * Rough_Edge * Thickness * 3.0;
            dist += edgeNoise;
        }

        // --------------------------------------------------------
        // 4. THICKNESS PROFILE
        // --------------------------------------------------------
        float thick = Thickness;

        // General tip taper (both ends)
        thick *= mix(1.0, sin(bestT * 3.14159265), clamp(Taper, 0.0, 1.0));

        // Start taper (inner/center side)
        thick *= mix(1.0, smoothstep(0.0, 0.3, bestT), clamp(Start_Taper, 0.0, 1.0));

        // End taper (outer side)
        thick *= mix(1.0, smoothstep(1.0, 0.7, bestT), clamp(End_Taper, 0.0, 1.0));

        // Evolution thickness
        if (Evolution_Enable > 0.5) {
            thick *= mix(1.0, 0.5 + 0.5 * sin(evoVal * 1.1 + fi * 0.5), (Evolution_Thickness / 100.0) * evoAmt);
        }

        // Thickness randomness
        thick *= mix(1.0, 0.2 + hash(lineSeed + 400.0) * 1.8, Thickness_Randomness / 100.0);

        // Depth curve (tunnel effect for flow)
        if (Depth_Curve > 0.0 && Mode < 0.5) {
            float depth = mix(1.0, 1.0 - bestT * 0.7, Depth_Curve);
            thick *= depth;
        }

        // Butt cap: exclude beyond endpoints in perpendicular direction
        if (Cap_Style < 0.5) {
            float projT = dot(px - p1, dirNorm) / segLen;
            if (projT < 0.0 || projT > 1.0) {
                dist = 1e10;
            }
        }

        // Early reject
        if (dist > thick * 0.6) continue;

        // --------------------------------------------------------
        // 5. DASH PATTERN
        // --------------------------------------------------------
        float inDash = 1.0;
        if (Dash_Length > 0.5 && Dash_Gap > 0.5) {
            float dashCycle = Dash_Length + Dash_Gap;
            float dashRand = hash(lineSeed + 300.0) * Dash_Gap_Randomness;
            float dashPos = mod(bestT * segLen + dashRand, dashCycle);
            inDash = step(dashPos, Dash_Length);
        }
        if (inDash < 0.5) continue;

        // --------------------------------------------------------
        // 6. FLOW ANIMATION (Radial & Speed)
        // --------------------------------------------------------
        float flowAlpha = 1.0;
        if (abs(Animate - 2.0) < 0.5) {
            float phase = Flow_Phase;
            if (Auto_Animation > 0.5) phase += t * Speed;

            float lineSpeed = Speed;
            if (Speed_Variation > 0.0) {
                lineSpeed *= mix(1.0, 0.3 + hash(lineSeed + 800.0) * 1.4, Speed_Variation / 100.0);
            }

            float phaseRand = Phase_Randomness / 100.0;
            float linePhase = phase * lineSpeed + hash(lineSeed + 40.0) * phaseRand * 6.28318530718;

            float flowPos = bestT * segLen;
            // Inward direction for radial: reverse flow from outer to inner
            if (Mode < 0.5 && Direction > 0.5) {
            flowPos = segLen - flowPos;
            }
            float segLenFlow = max(Flow_Length, 5.0);
            float segSpacing = segLenFlow * 2.5;
            float localPos = mod(flowPos - linePhase * 80.0 + hash(lineSeed + 60.0) * segSpacing, segSpacing);

            // Segment shape: fade at head and tail
            float seg = smoothstep(segLenFlow, segLenFlow * 0.7, localPos) * smoothstep(0.0, segLenFlow * 0.15, localPos);

            // Flow Min Scale: shrink tail
            if (Flow_Min_Scale > 0.0) {
                seg *= mix(1.0, smoothstep(segLenFlow * Flow_Min_Scale, 0.0, localPos), clamp(Flow_Min_Scale, 0.0, 1.0));
            }

            // Flow life time
            if (Flow_Life_Time > 0.0) {
                float life = mod(linePhase, Flow_Life_Time * 3.0) / max(Flow_Life_Time * 3.0, 0.001);
                seg *= smoothstep(1.0, 0.3, life);
            }

            flowAlpha = seg;
        }

        // --------------------------------------------------------
        // 7. OPACITY
        // --------------------------------------------------------
        float alpha = Opacity;

        // Fade start (inner/center)
        alpha *= smoothstep(0.0, max(Fade_Start, 0.5), bestT * segLen);

        // Fade end (outer)
        alpha *= smoothstep(0.0, max(Fade_End, 0.5), (1.0 - bestT) * segLen);

        // Flow fade
        if (abs(Animate - 2.0) < 0.5 && Flow_Fade > 0.0) {
            alpha *= mix(1.0, smoothstep(1.0, 0.0, bestT), clamp(Flow_Fade, 0.0, 1.0));
        }

        // Evolution opacity
        if (Evolution_Enable > 0.5) {
            alpha *= mix(1.0, 0.5 + 0.5 * sin(evoVal * 1.3 + fi * 0.7), (Evolution_Opacity / 100.0) * evoAmt);
        }

        // Opacity randomness
        alpha *= mix(1.0, hash(lineSeed + 500.0), Opacity_Randomness / 100.0);

        // General variation opacity
        alpha *= mix(1.0, 0.3 + hash(lineSeed + 501.0) * 1.4, varNorm * 0.5);

        // Flow alpha modulation
        alpha *= flowAlpha;

        // Soft edge antialiasing
        float edgeSoft = smoothstep(thick * 0.5, thick * 0.25, dist);
        alpha *= edgeSoft;

        if (alpha < 0.001) continue;

        // --------------------------------------------------------
        // 8. COLOR
        // --------------------------------------------------------
        vec3 lineColor = Color;

        // Color randomness
        if (Color_Randomness > 0.0) {
            vec3 randCol = vec3(
                hash(lineSeed + 600.0),
                hash(lineSeed + 601.0),
                hash(lineSeed + 602.0)
            );
            lineColor = mix(lineColor, randCol, Color_Randomness / 100.0);
        }

        // --------------------------------------------------------
        // 9. ACCUMULATE
        // --------------------------------------------------------
        vec4 lc = vec4(lineColor * alpha, alpha);

        if (Blend_Mode < 0.5) {
            // Normal alpha blend
            lineAccum.rgb = mix(lineAccum.rgb, lc.rgb, lc.a);
            lineAccum.a = lineAccum.a + lc.a * (1.0 - lineAccum.a);
        } else if (Blend_Mode > 0.5) {
            // Add
            lineAccum += lc;
        } else {
            // Multiply
            lineAccum.rgb *= mix(vec3(1.0), lc.rgb, lc.a);
            lineAccum.a = max(lineAccum.a, lc.a);
        }
    }

    // Clamp
    lineAccum = clamp(lineAccum, 0.0, 1.0);

    // --------------------------------------------------------
    // 10. OUTPUT COMPOSITING
    // --------------------------------------------------------
    vec4 finalColor;

    if (Output_Mode < 0.5) {
        // Composite over input
        if (Blend_Mode > 0.5) {
            // Add blend over input
            finalColor = inputColor + lineAccum;
            finalColor.a = min(inputColor.a + lineAccum.a, 1.0);
        } else if (Blend_Mode > 1.5) {
            // Multiply blend over input
            finalColor.rgb = inputColor.rgb * mix(vec3(1.0), lineAccum.rgb, lineAccum.a);
            finalColor.a = inputColor.a;
        } else {
            // Normal blend over input
            finalColor = mix(inputColor, lineAccum, lineAccum.a);
        }
    } else {
        // Lines only
        finalColor = lineAccum;
    }

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/invert.glsl:
precision highp float;
precision highp int;

/* --- Panzoid built-ins --- */
uniform sampler2D tDiffuse;
uniform vec2      uvScale;
uniform vec2      resolution;
varying vec2      vUv;
varying vec2      vUvScaled;

/* --- Properties from the UI --- */
uniform float Channel;              // 0..12 (rounded to int)
uniform float Blend_With_Original;  // 0..100 (percent, AE-style)

/* ===========================
   HLS (HSL) helpers
   =========================== */
float hue2rgb(float p, float q, float t)
{
  t = fract(t);
  if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
  if (t < 1.0/2.0) return q;
  if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
  return p;
}

// Returns H,L,S
vec3 rgb2hls(vec3 c)
{
  float maxc = max(max(c.r, c.g), c.b);
  float minc = min(min(c.r, c.g), c.b);
  float l = 0.5 * (maxc + minc);
  float d = maxc - minc;

  float h = 0.0;
  float s = 0.0;

  if (d > 1e-6) {
    s = d / (1.0 - abs(2.0 * l - 1.0));
    if (maxc == c.r) {
      h = ( (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0) ) / 6.0;
    } else if (maxc == c.g) {
      h = ( (c.b - c.r) / d + 2.0 ) / 6.0;
    } else {
      h = ( (c.r - c.g) / d + 4.0 ) / 6.0;
    }
  }

  return vec3(h, l, s);
}

vec3 hls2rgb(vec3 hls)
{
  float h = hls.x;
  float l = hls.y;
  float s = hls.z;

  if (s <= 1e-6) {
    return vec3(l); // grayscale
  }

  float q = (l < 0.5) ? (l * (1.0 + s)) : (l + s - l * s);
  float p = 2.0 * l - q;

  float r = hue2rgb(p, q, h + 1.0/3.0);
  float g = hue2rgb(p, q, h);
  float b = hue2rgb(p, q, h - 1.0/3.0);
  return vec3(r, g, b);
}

/* ===========================
   YIQ helpers (NTSC)
   =========================== */
vec3 rgb2yiq(vec3 c)
{
  float Y = 0.299   * c.r + 0.587   * c.g + 0.114   * c.b;
  float I = 0.595716* c.r - 0.274453* c.g - 0.321263* c.b;
  float Q = 0.211456* c.r - 0.522591* c.g + 0.311135* c.b;
  return vec3(Y, I, Q);
}

vec3 yiq2rgb(vec3 yIQ)
{
  float Y = yIQ.x;
  float I = yIQ.y;
  float Q = yIQ.z;
  float r = Y + 0.9563 * I + 0.6210 * Q;
  float g = Y - 0.2721 * I - 0.6474 * Q;
  float b = Y - 1.1070 * I + 1.7046 * Q;
  return clamp(vec3(r, g, b), 0.0, 1.0);
}

/* ===========================
   Main
   =========================== */
void main()
{
  vec4 src = texture2D(tDiffuse, vUvScaled);
  vec3 rgb = src.rgb;
  float a  = src.a;

  // Round and clamp Channel (no int clamp in GLSL ES 1.0)
  int ch = int(floor(Channel + 0.5));
  if (ch < 0)  ch = 0;
  if (ch > 12) ch = 12;

  // AE-style percent: strictly 0..100
  float bw = Blend_With_Original;
  if (bw < 0.0)   bw = 0.0;
  if (bw > 100.0) bw = 100.0;
  float bw01 = bw * 0.01; // convert to 0..1 for mix()

  vec3 outRGB = rgb;
  float outA  = a;

  if (ch == 0) {
    // RGB
    outRGB = 1.0 - rgb;
  } else if (ch == 1) {
    // Red
    outRGB = rgb; outRGB.r = 1.0 - rgb.r;
  } else if (ch == 2) {
    // Green
    outRGB = rgb; outRGB.g = 1.0 - rgb.g;
  } else if (ch == 3) {
    // Blue
    outRGB = rgb; outRGB.b = 1.0 - rgb.b;
  } else if (ch == 4 || ch == 5 || ch == 6 || ch == 7) {
    // HLS variants
    vec3 hls = rgb2hls(rgb);
    if (ch == 4) {
      hls.x = fract(hls.x + 0.5);
      hls.y = 1.0 - hls.y;
      hls.z = 1.0 - hls.z;
    } else if (ch == 5) {
      hls.x = fract(hls.x + 0.5);
    } else if (ch == 6) {
      hls.y = 1.0 - hls.y;
    } else { // 7
      hls.z = 1.0 - hls.z;
    }
    outRGB = hls2rgb(hls);
  } else if (ch == 8 || ch == 9 || ch == 10 || ch == 11) {
    // YIQ variants
    vec3 yiq = rgb2yiq(rgb);
    if (ch == 8) {
      yiq.x = 1.0 - yiq.x;
      yiq.y = -yiq.y;
      yiq.z = -yiq.z;
    } else if (ch == 9) {
      yiq.x = 1.0 - yiq.x;
    } else if (ch == 10) {
      yiq.y = -yiq.y;
    } else { // 11
      yiq.z = -yiq.z;
    }
    outRGB = yiq2rgb(yiq);
  } else {
    // 12: Alpha
    outA = 1.0 - a;
  }

  // Blend With Original: 0% = fully inverted, 100% = original
  vec4 inverted = vec4(outRGB, outA);
  gl_FragColor = mix(inverted, src, bw01);
}

text./plugins/alipfx/shaders/iris-wipe-2.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform vec2 Iris_Center;
uniform float Iris_Points;
uniform float Outer_Radius;
uniform int Use_Inner_Radius;
uniform float Inner_Radius;
uniform float Rotation;
uniform float Feather;

uniform vec2 resolution;

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    float angleOffset = radians(Rotation);
    vec2 uv = vUvScaled;
    vec2 center = Iris_Center;

    vec2 diff = uv - center;
    float dist = length(diff);
    float angle = atan(diff.y, diff.x) + angleOffset;

    float sides = max(Iris_Points, 3.0);

    // Sharp star distortion using sine wave
    float starFactor = 1.0;
    if (Use_Inner_Radius == 1) {
        starFactor = 1.0 - Inner_Radius * abs(sin(angle * sides));
    }

    // Apply star factor to polygon radius
    float polygonRadius = (cos(3.14159265359 / sides) /
                          cos(mod(angle, 2.0 * 3.14159265359 / sides) - 3.14159265359 / sides)) * starFactor;

    float normalizedDist = dist / polygonRadius;

    float featherNorm = Feather / max(resolution.x, resolution.y);

    // Inverse logic: fully visible at Outer_Radius = 0
    float alpha = smoothstep(Outer_Radius, Outer_Radius + featherNorm, normalizedDist);

    gl_FragColor = texel * alpha;
}

text./plugins/alipfx/shaders/iris-wipe.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Properties
uniform vec2 Iris_Center;       // Position (0.0 - 1.0)
uniform float Iris_Points;      // Number of spikes/polygon sides
uniform float Outer_Radius;     // Size of the iris opening
uniform int Use_Inner_Radius;   // 0 = Disabled, 1 = Enabled
uniform float Inner_Radius;     // Star depth (spike length)
uniform float Rotation;         // Rotation in degrees
uniform float Feather;          // Soft edge

uniform vec2 resolution;

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    float angleOffset = radians(Rotation);
    vec2 uv = vUvScaled;
    vec2 center = Iris_Center;

    // Compute distance and angle
    vec2 diff = uv - center;
    float dist = length(diff);
    float angle = atan(diff.y, diff.x) + angleOffset;

    // Polygon/star effect
    float sides = max(Iris_Points, 3.0);
    float starFactor = 1.0;
    if (Use_Inner_Radius == 1) {
        starFactor += Inner_Radius * cos(angle * sides);
    }

    float polygonRadius = (cos(3.14159265359 / sides) /
                          cos(mod(angle, 2.0 * 3.14159265359 / sides) - 3.14159265359 / sides)) * starFactor;

    float normalizedDist = dist / polygonRadius;

    // Feather normalization
    float featherNorm = Feather / max(resolution.x, resolution.y);

    // Inverse logic: fully visible when Outer_Radius = 0, hide outside as radius grows
    float alpha = smoothstep(Outer_Radius, Outer_Radius + featherNorm, normalizedDist);

    gl_FragColor = texel * alpha;
}

text./plugins/alipfx/shaders/leave-color.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Panzoid custom properties:
// Number (dynamic): Amount to Decolor
// Color: Color To Leave
// Number (dynamic): Tolerance
// Number (dynamic): Edge Softness
// Number (dynamic): Match Colors
uniform float Amount_to_Decolor; // 0..100
uniform vec3  Color_To_Leave;    // 0..1 RGB
uniform float Tolerance;         // 0..100
uniform float Edge_Softness;     // 0..100
uniform float Match_Colors;      // 0 = RGB, 1 = Hue

const float SQRT3 = 1.73205080757;
const float EPS   = 1e-6;

// Rec.709 / AE-like grayscale weighting
float luminance709(vec3 c)
{
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

// RGB -> HSV
vec3 rgb2hsv(vec3 c)
{
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(
    abs(q.z + (q.w - q.y) / (6.0 * d + e)),
    d / (q.x + e),
    q.x
  );
}

// Circular hue distance normalized to 0..1
// 0 = exact same hue, 1 = opposite hue
float hueDistance01(float h1, float h2)
{
  float d = abs(h1 - h2);
  d = min(d, 1.0 - d);
  return d / 0.5;
}

// RGB matching distance normalized to 0..1
float rgbDistance01(vec3 a, vec3 b)
{
  return length(a - b) / SQRT3;
}

// AE-like selection mask from distance
// dist = 0 means exact match
// tol = keep range
// soft = feather outside tol
float selectionMask(float dist, float tol, float soft)
{
  tol  = clamp(tol,  0.0, 1.0);
  soft = clamp(soft, 0.0, 1.0);

  if (soft <= EPS)
  {
    return (dist <= tol) ? 1.0 : 0.0;
  }

  float outer = min(1.0, tol + soft);
  return 1.0 - smoothstep(tol, outer, dist);
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);
  vec3 src   = texel.rgb;

  // AE-style percent controls
  float amount = clamp(Amount_to_Decolor / 100.0, 0.0, 1.0);
  float tol    = clamp(Tolerance         / 100.0, 0.0, 1.0);
  float soft   = clamp(Edge_Softness     / 100.0, 0.0, 1.0);

  float dist = 0.0;

  // Match Colors:
  // 0 = RGB
  // 1 = Hue
  if (Match_Colors < 0.5)
  {
    // Using RGB:
    // strict, brightness-sensitive, exact shade-sensitive
    dist = rgbDistance01(src, Color_To_Leave);
  }
  else
  {
    // Using Hue:
    // preserves the chosen hue regardless of brightness more effectively
    vec3 hsvSrc    = rgb2hsv(src);
    vec3 hsvTarget = rgb2hsv(Color_To_Leave);

    // If target color has almost no saturation, hue is unreliable.
    // Fall back to RGB matching in that case.
    if (hsvTarget.y < 0.0001)
    {
      dist = rgbDistance01(src, Color_To_Leave);
    }
    else
    {
      float hDist = hueDistance01(hsvSrc.x, hsvTarget.x);

      // Hue becomes unstable on near-gray pixels.
      // This suppresses accidental color retention in low-sat areas.
      float satGate = smoothstep(0.02, 0.10, hsvSrc.y);

      // Unsaturated pixels behave as "non-matching"
      dist = mix(1.0, hDist, satGate);
    }
  }

  // 1.0 = keep original color
  // 0.0 = fully subject to decolor
  float keep = selectionMask(dist, tol, soft);

  // Desaturated version
  float luma = luminance709(src);
  vec3 gray = vec3(luma);

  // At 100% Amount_to_Decolor:
  // matching colors stay color, non-matching colors go grayscale
  vec3 leaveColorResult = mix(gray, src, keep);

  // At 0% Amount_to_Decolor: no change
  // At intermediate values: partial decolor
  vec3 finalColor = mix(src, leaveColorResult, amount);

  gl_FragColor = vec4(finalColor, texel.a);
}

text./plugins/alipfx/shaders/lens-flare.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom properties
uniform vec2 Flare_Center;        // Position in pixels
uniform float Flare_Brightness;   // Intensity
uniform int Lens_Type;            // 0=Zoom, 1=35mm, 2=105mm
uniform float Blend_With_Original;// Inverted opacity (0 = full flare, 1 = no flare)

uniform vec2 resolution;

void main() {
    vec4 baseColor = texture2D(tDiffuse, vUvScaled);

    // Normalize center for resolution
    vec2 uv = vUvScaled;
    vec2 center = Flare_Center / resolution;

    // Distance from flare center
    vec2 diff = uv - center;
    float dist = length(diff);

    // Base glow (gentle falloff)
    float glow = Flare_Brightness / (dist * 1.5 + 0.05);

    // Lens type streak variation
    float streak = 0.0;
    if (Lens_Type == 0) streak = exp(-dist * 6.0);
    else if (Lens_Type == 1) streak = exp(-dist * 3.0);
    else if (Lens_Type == 2) streak = exp(-dist * 4.5);

    // Combine flare components
    vec3 flareColor = vec3(glow + streak);

    // Invert Blend_With_Original for flare opacity
    float flareOpacity = 1.0 - Blend_With_Original;

    // Apply inverted opacity
    flareColor *= flareOpacity;

    // Final blend: original + flare
    vec3 combinedColor = baseColor.rgb + flareColor;

    gl_FragColor = vec4(combinedColor, 1.0);
}

text./plugins/alipfx/shaders/levels-individua:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/*
  AE Levels (Individual Controls) + Channel routing (active)
  - All black/white sliders expect 0..255 exactly
  - All gamma sliders expect 0..5 (AE-like UI range per request)
  - Gamma behavior matches your description:
      Gamma > 1.0 => brighter midtones
      Gamma < 1.0 => darker midtones
    Implemented as exponent = 1/gamma
  - Clip toggles clamp to output endpoints when enabled
  - If clipping is Off, negative/superwhite values can pass (HDR-like)

  Changed:
  - Channel mode is forced to 4 (Alpha)
  - Alpha controls affect transparency / opacity
  - Alpha also drives an internal blur effect
*/

uniform float Channel; // kept for compatibility, but forced to 4 in main()

uniform float RGB_Input_Black;
uniform float RGB_Input_White;
uniform float RGB_Gamma;        // 0..5
uniform float RGB_Output_Black;
uniform float RGB_Output_White;

uniform float Red_Input_Black;
uniform float Red_Input_White;
uniform float Red_Gamma;        // 0..5
uniform float Red_Output_Black;
uniform float Red_Output_White;

uniform float Green_Input_Black;
uniform float Green_Input_White;
uniform float Green_Gamma;      // 0..5
uniform float Green_Output_Black;
uniform float Green_Output_White;

uniform float Blue_Input_Black;
uniform float Blue_Input_White;
uniform float Blue_Gamma;       // 0..5
uniform float Blue_Output_Black;
uniform float Blue_Output_White;

uniform float Alpha_Input_Black;
uniform float Alpha_Input_White;
uniform float Alpha_Gamma;      // 0..5
uniform float Alpha_Output_Black;
uniform float Alpha_Output_White;

// 0 = On (clip), 1 = Off, 2 = Off for 32bpc (treated like Off here)
uniform float Clip_To_Output_Black;
uniform float Clip_To_Output_White;

// Needed for blur sampling (1.0 / texture width, 1.0 / texture height)
uniform vec2 uTexelSize;

float clamp255(float v) { return clamp(v, 0.0, 255.0); }

// Gamma safety: user range is 0..5, but 0 would be invalid.
// We clamp internally to a tiny minimum, and also cap at 5.0.
float gammaSafe(float g) {
  return clamp(g, 1e-4, 5.0);
}

// Sign-preserving power so Off-clipping can support negatives (32bpc-like)
float signedPow(float x, float p) {
  float ax = abs(x);
  float sx = sign(x);
  return sx * pow(max(ax, 0.0), p);
}

float applyLevels1(
  float x,
  float inB, float inW,
  float gammaV,
  float outB, float outW,
  bool clipB, bool clipW
){
  // Convert AE 0..255 UI values to 0..1
  float iB = clamp255(inB) / 255.0;
  float iW = clamp255(inW) / 255.0;
  float oB = clamp255(outB) / 255.0;
  float oW = clamp255(outW) / 255.0;

  // Allow crossing (AE allows input white < input black)
  float denom = iW - iB;
  if (abs(denom) < 1e-6) denom = (denom < 0.0) ? -1e-6 : 1e-6;

  float t = (x - iB) / denom;

  // AE gamma direction per your spec: gamma>1 brightens => exponent = 1/gamma
  float g = gammaSafe(gammaV);
  float p = 1.0 / g;
  t = signedPow(t, p);

  // Map to output
  float y = mix(oB, oW, t);

  // Clip to output endpoints if enabled
  float mn = min(oB, oW);
  float mx = max(oB, oW);
  if (clipB) y = max(y, mn);
  if (clipW) y = min(y, mx);

  return y;
}

// Small Gaussian-like 9-tap blur
vec3 blur9(vec2 uv, float radiusPx) {
  vec2 r = uTexelSize * radiusPx;

  vec3 c = vec3(0.0);
  float w = 0.0;

  // center
  c += texture2D(tDiffuse, uv).rgb * 4.0;
  w += 4.0;

  // cross
  c += texture2D(tDiffuse, uv + vec2( r.x, 0.0)).rgb * 2.0;
  c += texture2D(tDiffuse, uv + vec2(-r.x, 0.0)).rgb * 2.0;
  c += texture2D(tDiffuse, uv + vec2(0.0,  r.y)).rgb * 2.0;
  c += texture2D(tDiffuse, uv + vec2(0.0, -r.y)).rgb * 2.0;
  w += 8.0;

  // diagonals
  c += texture2D(tDiffuse, uv + vec2( r.x,  r.y)).rgb;
  c += texture2D(tDiffuse, uv + vec2(-r.x,  r.y)).rgb;
  c += texture2D(tDiffuse, uv + vec2( r.x, -r.y)).rgb;
  c += texture2D(tDiffuse, uv + vec2(-r.x, -r.y)).rgb;
  w += 4.0;

  return c / max(w, 1e-6);
}

void main() {
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // Keep original RGB for blur source
  vec3 originalRGB = texel.rgb;

  // Toggle interpretation: 0 = On (clip), 1/2 = Off
  bool clipB = (int(floor(Clip_To_Output_Black + 0.5)) == 0);
  bool clipW = (int(floor(Clip_To_Output_White + 0.5)) == 0);

  // Force Channel mode = 4 (Alpha)
  int ch = 4;

  // --- 1) Channel decides where the MASTER RGB_* controls apply
  if (ch == 0) {
    // RGB master affects R,G,B
    texel.r = applyLevels1(texel.r, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
    texel.g = applyLevels1(texel.g, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
    texel.b = applyLevels1(texel.b, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
  } else if (ch == 1) {
    texel.r = applyLevels1(texel.r, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
  } else if (ch == 2) {
    texel.g = applyLevels1(texel.g, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
  } else if (ch == 3) {
    texel.b = applyLevels1(texel.b, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
  } else if (ch == 4) {
    texel.a = applyLevels1(texel.a, RGB_Input_Black, RGB_Input_White, RGB_Gamma, RGB_Output_Black, RGB_Output_White, clipB, clipW);
  }

  // --- 2) Individual Controls always apply (AE Individual Controls behavior)
  texel.r = applyLevels1(texel.r, Red_Input_Black,   Red_Input_White,   Red_Gamma,   Red_Output_Black,   Red_Output_White,   clipB, clipW);
  texel.g = applyLevels1(texel.g, Green_Input_Black, Green_Input_White, Green_Gamma, Green_Output_Black, Green_Output_White, clipB, clipW);
  texel.b = applyLevels1(texel.b, Blue_Input_Black,  Blue_Input_White,  Blue_Gamma,  Blue_Output_Black,  Blue_Output_White,  clipB, clipW);
  texel.a = applyLevels1(texel.a, Alpha_Input_Black, Alpha_Input_White, Alpha_Gamma, Alpha_Output_Black, Alpha_Output_White, clipB, clipW);

  // Alpha affects transparency / opacity
  float a = clamp(texel.a, 0.0, 1.0);

  // Lower alpha = more blur
  float blurAmount = 1.0 - a;

  // Internal blur radius in pixels (adjust 6.0 if you want stronger/weaker blur)
  vec3 blurredRGB = blur9(vUvScaled, 6.0 * blurAmount);

  // Mix original/current color with blurred color
  texel.rgb = mix(texel.rgb, blurredRGB, blurAmount);

  // Final output alpha
  texel.a = a;

  gl_FragColor = texel;
}

text./plugins/alipfx/shaders/levels.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Panzoid properties (Dynamic Numbers)
uniform float Channel;               // 0=RGB, 1=R, 2=G, 3=B, 4=Alpha
uniform float Input_Black;           // 0..255
uniform float Input_White;           // 0..255
uniform float Gamma;                 // 0..5 (AE-style)
uniform float Output_Black;          // 0..255
uniform float Output_White;          // 0..255
uniform float Clip_To_Output_Black;  // 0=On, 1=Off, 2=Off for 32bpc
uniform float Clip_To_Output_White;  // 0=On, 1=Off, 2=Off for 32bpc

float safeDiv(float a, float b)
{
  // Preserve sign; avoid division by 0
  float s  = (b < 0.0) ? -1.0 : 1.0;
  float ab = max(abs(b), 1e-6);
  return a / (s * ab);
}

// AE-like Levels mapping with Gamma.
// Workflow:
// 1) Normalize: t = (x - inB) / (inW - inB)
// 2) Apply gamma curve only inside 0..1
// 3) Map to output: y = t*(outW - outB) + outB
float levels1(float x, float inB, float inW, float gammaVal, float outB, float outW)
{
  float t = safeDiv((x - inB), (inW - inB));

  // Gamma safety
  float g = max(gammaVal, 1e-4);

  // Apply gamma only in 0..1 region
  float tMid = clamp(t, 0.0, 1.0);
  float tShaped = pow(tMid, g);

  float tFinal = (t < 0.0) ? t : ((t > 1.0) ? t : tShaped);

  return tFinal * (outW - outB) + outB;
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // Convert 0..255 UI into 0..1 working range
  float inB  = Input_Black  / 255.0;
  float inW  = Input_White  / 255.0;
  float outB = Output_Black / 255.0;
  float outW = Output_White / 255.0;

  int ch = int(floor(Channel + 0.5));

  vec4 outCol = texel;

  if (ch == 0)
  {
    // RGB master = apply same mapping to each channel independently
    outCol.r = levels1(texel.r, inB, inW, Gamma, outB, outW);
    outCol.g = levels1(texel.g, inB, inW, Gamma, outB, outW);
    outCol.b = levels1(texel.b, inB, inW, Gamma, outB, outW);
    // Alpha unchanged in RGB mode
  }
  else if (ch == 1)
  {
    outCol.r = levels1(texel.r, inB, inW, Gamma, outB, outW);
  }
  else if (ch == 2)
  {
    outCol.g = levels1(texel.g, inB, inW, Gamma, outB, outW);
  }
  else if (ch == 3)
  {
    outCol.b = levels1(texel.b, inB, inW, Gamma, outB, outW);
  }
  else // ch == 4 (Alpha)
  {
    float oldA = texel.a;
    float newA = levels1(texel.a, inB, inW, Gamma, outB, outW);

    outCol.a = newA;

    // Make Alpha mode affect visible opacity/transparency in the comp
    // and behave better with downstream blur by scaling RGB with alpha change.
    float alphaScale = (oldA > 1e-6) ? (newA / oldA) : 0.0;
    outCol.rgb *= alphaScale;
  }

  // Clip toggles:
  // 0 = On => clamp to display range
  // 1/2 = Off => allow values outside 0..1
  bool clipBlack = (int(floor(Clip_To_Output_Black + 0.5)) == 0);
  bool clipWhite = (int(floor(Clip_To_Output_White + 0.5)) == 0);

  if (clipBlack)
  {
    outCol = max(outCol, vec4(0.0));
  }
  if (clipWhite)
  {
    outCol = min(outCol, vec4(1.0));
  }

  gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/linear-wipe.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom properties from Panzoid
uniform float Transition_Completion; // 0.0 to 100.0 (%)
uniform float Wipe_Angle;            // in degrees
uniform float Feather;               // in pixels

uniform vec2 resolution;

void main() {
    // Read the original texture
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // Normalize transition completion to 0.0 - 1.0
    float completion = clamp(Transition_Completion / 100.0, 0.0, 1.0);

    // Convert angle to radians
    float angle = radians(Wipe_Angle);

    // Compute direction vector for wipe line
    vec2 dir = vec2(cos(angle), sin(angle));

    // Center UV coordinates
    vec2 uv = vUvScaled;

    // Project UV onto wipe direction
    float proj = dot(uv - 0.5, dir);

    // Compute threshold for transition
    float threshold = mix(-0.5, 0.5, completion);

    // Feather in normalized UV space
    float featherNorm = Feather / max(resolution.x, resolution.y);

    // Compute alpha based on feather
    float alpha = smoothstep(threshold - featherNorm, threshold + featherNorm, proj);

    // Output: reveal based on alpha
    gl_FragColor = texel * alpha;
}

text./plugins/alipfx/shaders/liquid-glass.gls:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms
uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

// Custom Properties Uniforms
uniform sampler2D Source_Layer;
uniform float Quality;
uniform float Strength;
uniform float Scale;
uniform float IOR;
uniform float Thickness;
uniform vec3 Tint_Color;
uniform float Tint_Opacity;
uniform float Opacity;
uniform float Intensity;
uniform float Softness;
uniform float Edge_Width;
uniform float Light_Angle;
uniform vec3 Light_Color;
uniform float Highlight_Distance;
uniform float Amount;
uniform float Feather;
uniform float Edge_Blur;
uniform float Enable;
uniform float Shadow_Opacity;
uniform float Shadow_Distance;
uniform float Shadow_Softness;

// Panzoid Built-in Varyings
varying vec2 vUv;
varying vec2 vUvScaled;

// Helper to safely sample mask alpha with correct scaling layout
float getMaskAlpha(vec2 uvOffset) {
    vec2 targetUv = (vUv + uvOffset) * uvScale;
    if(targetUv.x < 0.0 || targetUv.x > uvScale.x || targetUv.y < 0.0 || targetUv.y > uvScale.y) {
        return 0.0;
    }
    return texture2D(tDiffuse, targetUv).a;
}

void main() {
    vec2 texel = 1.0 / resolution;

    // 1. Determine Sample Steps based on Quality Parameter
    int iterations = 8;
    if (Quality < 0.5) { iterations = 4; }       // Draft
    else if (Quality < 1.5) { iterations = 8; }  // Standard
    else if (Quality < 2.5) { iterations = 16; } // High
    else { iterations = 28; }                    // Ultra (Supersampled)

    // 2. Compute Normal Vectors (Handles Edge Bending & Ball Lens Look via Scale)
    vec2 grad = vec2(0.0);
    float normStep = (Scale * 0.05) / max(resolution.x, resolution.y);
    float weightSum = 0.0;

    for (int i = 1; i <= 28; i++) {
        if (i > iterations) break;
        float fi = float(i);
        float w = 1.0 / fi;

        float stepDist = normStep * fi;
        float aR = getMaskAlpha(vec2(stepDist, 0.0));
        float aL = getMaskAlpha(vec2(-stepDist, 0.0));
        float aT = getMaskAlpha(vec2(0.0, stepDist));
        float aB = getMaskAlpha(vec2(0.0, -stepDist));

        grad.x += (aL - aR) * w;
        grad.y += (aB - aT) * w;
        weightSum += w;
    }
    if (weightSum > 0.0) grad /= weightSum;

    // Build the 3D surface normal
    float aspectMod = resolution.x / resolution.y;
    vec3 normal = normalize(vec3(grad.x * (Strength * 0.1), grad.y * (Strength * 0.1) * aspectMod, 1.0));

    // Current base alpha of the glass shape
    float currentAlpha = texture2D(tDiffuse, vUvScaled).a;

    // Local Edge Detection for Localized Edge Blur & Edge Feathering
    float edgeAlpha = smoothstep(0.0, max(0.001, Feather * 0.01), currentAlpha);

    // 3. Chromatic Aberration & Refraction Calculation
    float caShift = Amount * 0.001;
    // Bending logic scaling with Index of Refraction (IOR)
    vec2 refractDir = normal.xy * (IOR - 1.0) * (Strength * 0.002);

    vec2 uvR = vUv + refractDir * (1.0 + caShift);
    vec2 uvG = vUv + refractDir;
    vec2 uvB = vUv + refractDir * (1.0 - caShift);

    // 4. Glass Frosted Body (Thickness Blur Processing)
    vec3 refractedCol = vec3(0.0);
    float blurRadius = Thickness * 0.002;

    if (blurRadius > 0.0) {
        // Jittered multi-tap sample loop for clean frosted glass look
        vec2 blurOffsets[4];
        blurOffsets[0] = vec2(blurRadius, blurRadius);
        blurOffsets[1] = vec2(-blurRadius, -blurRadius);
        blurOffsets[2] = vec2(blurRadius, -blurRadius);
        blurOffsets[3] = vec2(-blurRadius, blurRadius);

        for(int j = 0; j < 4; j++) {
            refractedCol.r += texture2D(Source_Layer, clamp(uvR + blurOffsets[j], 0.0, 1.0)).r * 0.25;
            refractedCol.g += texture2D(Source_Layer, clamp(uvG + blurOffsets[j], 0.0, 1.0)).g * 0.25;
            refractedCol.b += texture2D(Source_Layer, clamp(uvB + blurOffsets[j], 0.0, 1.0)).b * 0.25;
        }
    } else {
        refractedCol.r = texture2D(Source_Layer, clamp(uvR, 0.0, 1.0)).r;
        refractedCol.g = texture2D(Source_Layer, clamp(uvG, 0.0, 1.0)).g;
        refractedCol.b = texture2D(Source_Layer, clamp(uvB, 0.0, 1.0)).b;
    }

    // Apply Tint Color Configuration
    vec3 glassBody = mix(refractedCol, Tint_Color, Tint_Opacity * 0.01);

    // 5. Specular Highlights Modeling (Rim Lights & Global Illumination Angle)
    float angleRad = Light_Angle * 3.14159265 / 180.0;
    vec3 lightDir = normalize(vec3(cos(angleRad), sin(angleRad), 2.0 - (Highlight_Distance * 0.02)));
    vec3 viewDir = vec3(0.0, 0.0, 1.0);
    vec3 halfVec = normalize(lightDir + viewDir);

    // Polish Control: Lower Softness = tight gloss peak, High Softness = wide matte accent
    float shinyExponent = mix(128.0, 2.0, Softness * 0.01);
    float specularIntensity = pow(max(dot(normal, halfVec), 0.0), shinyExponent) * (Intensity * 0.02);

    // Rim Edge Highlight Generation
    float rimWeight = 1.0 - normal.z;
    float edgeHighlight = smoothstep(1.0 - (Edge_Width * 0.01), 1.0, rimWeight) * (Intensity * 0.01);

    vec3 finalHighlights = Light_Color * (specularIntensity + edgeHighlight);
    vec3 dynamicGlassOutput = glassBody + finalHighlights;

    // 6. Refractive Shadow Layout Configuration
    float shadowMask = 0.0;
    vec2 shadowOffset = vec2(0.0);

    if (Enable > 0.5) {
        float shadowAngleRad = angleRad + 3.14159265; // Shadow casts downstream from light source
        shadowOffset = vec2(cos(shadowAngleRad), sin(shadowAngleRad)) * (Shadow_Distance * 0.002);

        // Multi-sampled soft Gaussian approximation for shadow blur
        float sBlur = Shadow_Softness * 0.001;
        shadowMask += getMaskAlpha(-shadowOffset) * 0.4;
        shadowMask += getMaskAlpha(-shadowOffset + vec2(sBlur, sBlur)) * 0.15;
        shadowMask += getMaskAlpha(-shadowOffset + vec2(-sBlur, -sBlur)) * 0.15;
        shadowMask += getMaskAlpha(-shadowOffset + vec2(sBlur, -sBlur)) * 0.15;
        shadowMask += getMaskAlpha(-shadowOffset + vec2(-sBlur, sBlur)) * 0.15;
    }

    // 7. Composite Pass Construction
    vec4 sceneBackground = texture2D(Source_Layer, vUv);

    // Overlay shadow onto background scenery
    vec3 compositeBackground = mix(sceneBackground.rgb, vec3(0.0), shadowMask * (Shadow_Opacity * 0.01));

    // Merge background canvas and simulated glass structure cleanly
    vec3 outputColor = mix(compositeBackground, dynamicGlassOutput, edgeAlpha * (Opacity * 0.01));
    float outputAlpha = max(sceneBackground.a, edgeAlpha * (Opacity * 0.01));

    // Optional Localized Rim Edge Blur Processing
    if (Edge_Blur > 0.0) {
        float edgeRegion = smoothstep(0.1, 0.9, rimWeight);
        outputColor = mix(outputColor, glassBody, edgeRegion * (Edge_Blur * 0.01));
    }

    gl_FragColor = vec4(outputColor, outputAlpha);
}

text./plugins/alipfx/shaders/lumetri-color.gl:
precision highp float;
precision highp int;

// =====================================================================
//  Panzoid CM3 – Lumetri-style GLSL Shader
//  NOTE: Parameter/uniform names preserved EXACTLY as provided.
// =====================================================================

// ---------------------------------------------------------------------
// Panzoid built-ins
// ---------------------------------------------------------------------
uniform sampler2D tDiffuse;
uniform vec2      resolution;
uniform vec2      uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// ---------------------------------------------------------------------
// Utility helpers
// ---------------------------------------------------------------------
const float PI = 3.14159265358979323846;

float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722)); // Rec.709
}

vec3 clamp01(vec3 c) { return clamp(c, 0.0, 1.0); }

// --- sRGB-ish gamma helpers (Panzoid footage is typically gamma-encoded) ---
vec3 toLinear(vec3 c) { return pow(max(c, vec3(0.0)), vec3(2.2)); }
vec3 toGamma(vec3 c)  { return pow(max(c, vec3(0.0)), vec3(1.0 / 2.2)); }

// RGB <-> HSV
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    float h = abs(q.z + (q.w - q.y) / (6.0 * d + e));
    float s = d / (q.x + e);
    float v = q.x;
    return vec3(h, s, v);
}

vec3 hsv2rgb(vec3 c) {
    vec3 p = abs(fract(c.xxx + vec3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0);
    vec3 rgb = c.z * mix(vec3(1.0), clamp01(p - 1.0), c.y);
    return rgb;
}

// Hue distance 0..0.5 (0..180°)
float hueDist(float h1, float h2) {
    float d = abs(h1 - h2);
    return min(d, 1.0 - d);
}

// Convert Lumetri-style % slider (0..200, 100 = neutral) to −1..1
float pctToSigned(float v) {
    return (v - 100.0) / 100.0;
}

// ---------------------------------------------------------------------
// SECTION 1 – BASIC CORRECTION
// ---------------------------------------------------------------------
uniform vec3  WB_Selector;
uniform float Temperature;
uniform float Tint;
uniform float Exposure;
uniform float Contrast;
uniform float Highlights;
uniform float Shadows;
uniform float Whites;
uniform float Blacks;
uniform float Saturation_Basic;

vec3 applyWBSelector(vec3 c, vec3 sampleColor) {
    float g = (sampleColor.r + sampleColor.g + sampleColor.b) / 3.0;
    vec3 denom = max(sampleColor, vec3(1e-4));
    vec3 gain  = vec3(g) / denom;
    return c * gain;
}

vec3 applyTempTint(vec3 c, float temp, float tint) {
    float t  = clamp(temp / 100.0, -1.0, 1.0) * 0.5;
    float ti = clamp(tint / 100.0, -1.0, 1.0) * 0.5;

    vec3 wb = vec3(1.0 + t, 1.0, 1.0 - t);
    wb.g += ti;
    wb.r -= ti * 0.5;
    wb.b -= ti * 0.5;

    return c * wb;
}

vec3 applyExposure(vec3 c, float exposure) {
    float m = pow(2.0, exposure);
    return c * m;
}

vec3 applyContrast01(vec3 c, float contrastPct) {
    float k = clamp(contrastPct / 100.0, -1.0, 1.0);
    float pivot = 0.5;
    return clamp01((c - pivot) * (1.0 + k) + pivot);
}

vec3 applyBasicTonal(vec3 c, float hlPct, float shPct, float whPct, float blPct) {
    float Y = luma(c);

    float shadowMask    = 1.0 - smoothstep(0.25, 0.55, Y);
    float highlightMask = smoothstep(0.45, 0.85, Y);
    float whiteMask     = smoothstep(0.75, 1.0, Y);
    float blackMask     = 1.0 - smoothstep(0.0, 0.25, Y);

    float sh = clamp(shPct / 100.0, -1.0, 1.0) * 0.5;
    float hl = clamp(hlPct / 100.0, -1.0, 1.0) * 0.5;
    float wh = clamp(whPct / 100.0, -1.0, 1.0) * 0.7;
    float bl = clamp(blPct / 100.0, -1.0, 1.0) * 0.7;

    float Ysh = Y + sh * shadowMask;
    float Yhl = Ysh + hl * highlightMask;
    float Ywh = Yhl + wh * whiteMask;
    float Ybl = Ywh + bl * blackMask;

    float ratio = (Y > 0.0) ? (Ybl / Y) : 1.0;
    return clamp01(c * ratio);
}

vec3 applySaturationSigned(vec3 c, float satSigned) {
    float Y = luma(c);
    return clamp01(mix(vec3(Y), c, 1.0 + satSigned));
}

// ---------------------------------------------------------------------
// SECTION 2 – CREATIVE
// ---------------------------------------------------------------------
uniform float Faded_Film;
uniform float Sharpen;
uniform float Vibrance;
uniform float Saturation_Creative;
uniform vec3  Highlight_Tint;
uniform vec3  Shadow_Tint;
uniform float Tint_Balance;

vec3 applyFadedFilm(vec3 c, float amountPct) {
    float amount = clamp(amountPct / 100.0, 0.0, 1.0);
    float lift = amount * 0.25;
    c = max(c, vec3(lift));
    c = mix(c, vec3(0.5), amount * 0.3);
    return clamp01(c);
}

// ---------------------------------------------------------------------
// CREATIVE SHARPEN (FIXED) + MICROCONTRAST ABOVE 70
// - Uses true pixel step 1/resolution (doesn't "do nothing")
// - Resolution-independent radius (1080p baseline)
// - Classic unsharp mask (feels like real sharpen)
// - Microcontrast/clarity only above 70
// - Edge masked + halo limited
// ---------------------------------------------------------------------
vec3 applySharpen(vec2 uv, vec3 c, float amountPct) {

    // Slider remap:
    //  - 0..35  : very subtle
    //  - 35..70 : softer ramp
    //  - 70..100: stronger ramp
    float t = clamp((amountPct - 35.0) / 35.0, 0.0, 1.0);
    t = smoothstep(0.0, 1.0, t);

    float tSoft = pow(t, 1.65);
    float amount = 0.08 + 0.65 * tSoft;     // softer 35–70

    float u = clamp((amountPct - 70.0) / 30.0, 0.0, 1.0);
    u = smoothstep(0.0, 1.0, u);
    amount += 1.10 * pow(u, 0.80);          // stronger above 70

    if (amountPct < 5.0) return c;

    // IMPORTANT: true pixel step in UV space
    vec2 texel = 1.0 / resolution;

    // Resolution-independent radius (baseline 1080p)
    float radiusPx = clamp(resolution.y / 1080.0, 0.75, 2.75);

    // Slight growth with strength
    float aNorm = clamp(amount / 1.8, 0.0, 1.0);
    radiusPx *= mix(0.95, 1.25, aNorm);

    vec2 stepUV = texel * radiusPx;

    // Sample neighbors from the source texture
    vec3 n  = texture2D(tDiffuse, uv + vec2(0.0,      stepUV.y)).rgb;
    vec3 s  = texture2D(tDiffuse, uv - vec2(0.0,      stepUV.y)).rgb;
    vec3 e  = texture2D(tDiffuse, uv + vec2(stepUV.x,  0.0)).rgb;
    vec3 w  = texture2D(tDiffuse, uv - vec2(stepUV.x,  0.0)).rgb;

    vec3 ne = texture2D(tDiffuse, uv + vec2(stepUV.x,  stepUV.y)).rgb;
    vec3 nw = texture2D(tDiffuse, uv + vec2(-stepUV.x, stepUV.y)).rgb;
    vec3 se = texture2D(tDiffuse, uv + vec2(stepUV.x, -stepUV.y)).rgb;
    vec3 sw = texture2D(tDiffuse, uv + vec2(-stepUV.x,-stepUV.y)).rgb;

    // Center uses CURRENT color (so we don't destroy earlier grading)
    vec3 C  = toLinear(clamp01(c));
    vec3 N  = toLinear(clamp01(n));
    vec3 S  = toLinear(clamp01(s));
    vec3 E  = toLinear(clamp01(e));
    vec3 W  = toLinear(clamp01(w));
    vec3 NE = toLinear(clamp01(ne));
    vec3 NW = toLinear(clamp01(nw));
    vec3 SE = toLinear(clamp01(se));
    vec3 SW = toLinear(clamp01(sw));

    // 3x3 Gaussian blur
    vec3 blur =
        (NW + NE + SW + SE) * 1.0 +
        (N  + S  + E  + W ) * 2.0 +
        C * 4.0;
    blur *= (1.0 / 16.0);

    // High-pass detail
    vec3 highPass = C - blur;

    // Edge mask (avoid sharpening flat/noisy areas)
    float hp = abs(luma(highPass));
    float t0 = 0.006 / max(radiusPx, 1e-3);
    float t1 = 0.040 / max(radiusPx, 1e-3);
    float edgeMask = smoothstep(t0, t1, hp);

    // Halo limiting
    float limit = mix(0.03, 0.08, clamp(amount, 0.0, 1.0));
    highPass = clamp(highPass, vec3(-limit), vec3(limit));

    // Classic unsharp mask (this is the "real sharpen" feeling)
    float gain = (4.0 * amount) / max(radiusPx, 1e-3);
    vec3 outLin = C + highPass * gain * edgeMask;

    // ------------------------------------------------------------
    // MICROCONTRAST / CLARITY — ONLY ABOVE 70
    // ------------------------------------------------------------
    if (amountPct > 70.0) {

        float mcRadius = radiusPx * 2.4;
        vec2 stepUV2 = texel * mcRadius;

        vec3 n2  = texture2D(tDiffuse, uv + vec2(0.0,       stepUV2.y)).rgb;
        vec3 s2  = texture2D(tDiffuse, uv - vec2(0.0,       stepUV2.y)).rgb;
        vec3 e2  = texture2D(tDiffuse, uv + vec2(stepUV2.x,  0.0)).rgb;
        vec3 w2  = texture2D(tDiffuse, uv - vec2(stepUV2.x,  0.0)).rgb;

        vec3 ne2 = texture2D(tDiffuse, uv + vec2(stepUV2.x,  stepUV2.y)).rgb;
        vec3 nw2 = texture2D(tDiffuse, uv + vec2(-stepUV2.x, stepUV2.y)).rgb;
        vec3 se2 = texture2D(tDiffuse, uv + vec2(stepUV2.x, -stepUV2.y)).rgb;
        vec3 sw2 = texture2D(tDiffuse, uv + vec2(-stepUV2.x,-stepUV2.y)).rgb;

        vec3 N2  = toLinear(clamp01(n2));
        vec3 S2  = toLinear(clamp01(s2));
        vec3 E2  = toLinear(clamp01(e2));
        vec3 W2  = toLinear(clamp01(w2));
        vec3 NE2 = toLinear(clamp01(ne2));
        vec3 NW2 = toLinear(clamp01(nw2));
        vec3 SE2 = toLinear(clamp01(se2));
        vec3 SW2 = toLinear(clamp01(sw2));

        vec3 blur2 =
            (NW2 + NE2 + SW2 + SE2) * 1.0 +
            (N2  + S2  + E2  + W2 ) * 2.0 +
            C * 4.0;
        blur2 *= (1.0 / 16.0);

        float mcDetail = luma(C - blur2);

        float mcAbs  = abs(mcDetail);
        float mcMask = smoothstep(0.003 / max(mcRadius, 1e-3),
                                  0.020 / max(mcRadius, 1e-3),
                                  mcAbs);

        float mcStrength = 0.55 * pow(u, 0.85);  // 0..~0.55
        mcStrength /= max(mcRadius, 1e-3);

        float Yout = luma(outLin);
        float Ymc  = clamp(Yout + mcDetail * mcStrength * mcMask, 0.0, 1.0);
        float ratio = (Yout > 1e-6) ? (Ymc / Yout) : 1.0;

        outLin *= ratio;
    }

    return clamp01(toGamma(outLin));
}

vec3 applyVibrance(vec3 c, float amountSigned) {
    if (amountSigned == 0.0) return c;
    vec3 hsv = rgb2hsv(c);
    float s = hsv.y;
    float boost = amountSigned * (1.0 - s);
    hsv.y = clamp(s + boost, 0.0, 1.0);
    return clamp01(hsv2rgb(hsv));
}

vec3 applySplitTone(vec3 c, vec3 shadowTint, vec3 highlightTint, float balancePct) {
    float Y = luma(c);
    float balance = clamp(balancePct / 100.0, -1.0, 1.0);
    float pivot = 0.5 + balance * 0.25;

    float shadowMask    = 1.0 - smoothstep(pivot - 0.2, pivot + 0.05, Y);
    float highlightMask = smoothstep(pivot - 0.05, pivot + 0.2, Y);

    vec3 col = c;
    col = mix(col, col * shadowTint, shadowMask);
    col = mix(col, col * highlightTint, highlightMask);
    return clamp01(col);
}

// ---------------------------------------------------------------------
// SECTION 3 – CURVES
// ---------------------------------------------------------------------
uniform float RGBW_Modes;      // 0=W,1=R,2=G,3=B (Panzoid float slider)
uniform float Curve_Shadow;    // -100..100
uniform float Curve_Highlight; // -100..100

uniform vec3  Hue_Selector;
uniform vec3  Saturation_Selector;
uniform vec3  Luma_Selector;

uniform float Curve_Hue;
uniform float Curve_Sat;       // (kept name)
uniform float Curve_Luma;

// RGBW curves: linear light + stronger response
float curveShadowHighlightGamma(float x, float shSigned, float hlSigned) {
    float t = clamp(x, 0.0, 1.0);

    const float SH_END   = 0.40;
    const float HI_START = 0.60;

    float shadowMask    = 1.0 - smoothstep(0.00, SH_END, t);
    float highlightMask = smoothstep(HI_START, 1.00, t);

    shadowMask    = pow(shadowMask, 1.45);
    highlightMask = pow(highlightMask, 1.45);

    float wS = shadowMask * (1.0 - highlightMask);
    float wH = highlightMask * (1.0 - shadowMask);
    float wM = 1.0 - wS - wH;

    shSigned = clamp(shSigned, -2.0, 2.0);
    hlSigned = clamp(hlSigned, -2.0, 2.0);

    float gammaS = pow(2.0,  shSigned);
    float gammaH = pow(2.0, -hlSigned);

    float yShadow = pow(t, gammaS);
    float yHigh   = 1.0 - pow(1.0 - t, gammaH);

    float y = t * wM + yShadow * wS + yHigh * wH;
    return clamp(y, 0.0, 1.0);
}

vec3 applyRGBWCurves(vec3 c, int mode, float shPct, float hlPct) {
    float sh = clamp(shPct / 100.0, -2.0, 2.0);
    float hl = clamp(hlPct / 100.0, -2.0, 2.0);

    vec3 lin = toLinear(c);

    if (mode == 0) {
        float Y  = luma(lin);
        float Y2 = curveShadowHighlightGamma(Y, sh, hl);
        float ratio = (Y > 1e-6) ? (Y2 / Y) : 1.0;
        lin *= ratio;
    } else if (mode == 1) {
        lin.r = curveShadowHighlightGamma(lin.r, sh, hl);
    } else if (mode == 2) {
        lin.g = curveShadowHighlightGamma(lin.g, sh, hl);
    } else if (mode == 3) {
        lin.b = curveShadowHighlightGamma(lin.b, sh, hl);
    }

    return clamp01(toGamma(lin));
}

// Curve_Sat fix: boosts picked hue reliably
vec3 applyHueSatLumaCurves(vec3 c,
                           vec3 hueSelColor,
                           vec3 satSelColor,
                           vec3 lumaSelColor,
                           float hueShiftParam,
                           float satDeltaSigned,
                           float lumaDeltaPct) {

    vec3 hsv = rgb2hsv(c);

    float targetHue = rgb2hsv(hueSelColor).x;

    float hueWidth = 0.12;
    float dHue = hueDist(hsv.x, targetHue);
    float hueMask = smoothstep(hueWidth, 0.0, dHue);

    float Y = luma(c);
    float lumGate = smoothstep(0.02, 0.10, Y) * (1.0 - smoothstep(0.90, 0.99, Y));
    float maskSat = clamp(hueMask * lumGate, 0.0, 1.0);

    float targetSat = rgb2hsv(satSelColor).y;
    float targetLum = luma(lumaSelColor);

    float satWidth = 0.55;
    float lumWidth = 0.55;

    float dSat = abs(hsv.y - targetSat);
    float dLum = abs(luma(c) - targetLum);

    float satMask = smoothstep(satWidth, 0.0, dSat);
    float lumMask = smoothstep(lumWidth, 0.0, dLum);

    float maskHSL = clamp(hueMask * mix(1.0, satMask, 0.5) * mix(1.0, lumMask, 0.5), 0.0, 1.0);

    float hueShiftHueUnits;
    if (abs(hueShiftParam) > 1.5) {
        hueShiftHueUnits = clamp(hueShiftParam, -180.0, 180.0) / 360.0;
    } else {
        hueShiftHueUnits = clamp(hueShiftParam, -1.0, 1.0) * 0.5;
    }
    hsv.x = fract(hsv.x + hueShiftHueUnits * maskHSL);

    float satMul = pow(2.0, clamp(satDeltaSigned, -2.0, 2.0) * maskSat);
    hsv.y = clamp(hsv.y * satMul, 0.0, 1.0);

    vec3 rgbHS = hsv2rgb(hsv);

    float Y2 = luma(rgbHS);
    float dL = clamp(lumaDeltaPct / 100.0, -1.0, 1.0) * 0.5;
    float Y3 = clamp(Y2 + dL * maskHSL, 0.0, 1.0);
    float ratio = (Y2 > 1e-6) ? (Y3 / Y2) : 1.0;

    return clamp01(rgbHS * ratio);
}

// ---------------------------------------------------------------------
// SECTION 4 – COLOR WHEELS (PRIMARY)
// ---------------------------------------------------------------------
uniform vec3 CW_Highlights;
uniform vec3 CW_Midtones;
uniform vec3 CW_Shadows;

vec3 applyColorWheels(vec3 c, vec3 shCol, vec3 midCol, vec3 hiCol) {
    float Y = luma(c);

    float shadowMask    = 1.0 - smoothstep(0.3, 0.55, Y);
    float midMask       = smoothstep(0.2, 0.6, Y) * (1.0 - smoothstep(0.4, 0.8, Y));
    float highlightMask = smoothstep(0.5, 0.9, Y);

    vec3 col = c;
    col = mix(col, col * shCol, shadowMask);
    col = mix(col, col * midCol, midMask);
    col = mix(col, col * hiCol, highlightMask);
    return clamp01(col);
}

// ---------------------------------------------------------------------
// SECTION 5 – HSL SECONDARY (kept as you provided)
// ---------------------------------------------------------------------
uniform vec3  Secondary_Set_Color;
uniform vec3  Secondary_Add_Color;
uniform vec3  Secondary_Remove_Color;

uniform float Secondary_Denoise;
uniform float Secondary_Blur;

uniform vec3  Secondary_Color_Wheels;
uniform float Secondary_Temperature;
uniform float Secondary_Tint;
uniform float Secondary_Contrast;
uniform float Secondary_Sharpen;
uniform float Secondary_Saturation;

uniform float Secondary_Hue_Range;
uniform float Secondary_Hue_Feather;
uniform float Secondary_Sat_Range;
uniform float Secondary_Sat_Feather;
uniform float Secondary_Lum_Range;
uniform float Secondary_Lum_Feather;

uniform float Secondary_Show_Mask;
uniform float Secondary_Mask_View;
uniform float Secondary_Invert_Mask;

vec3 rgb2hsl(vec3 c) {
    float maxc = max(max(c.r, c.g), c.b);
    float minc = min(min(c.r, c.g), c.b);
    float l = (maxc + minc) * 0.5;

    float s = 0.0;
    float h = 0.0;

    float d = maxc - minc;
    if (d > 1e-6) {
        s = d / (1.0 - abs(2.0 * l - 1.0));

        if (maxc == c.r) {
            h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0);
        } else if (maxc == c.g) {
            h = (c.b - c.r) / d + 2.0;
        } else {
            h = (c.r - c.g) / d + 4.0;
        }
        h /= 6.0;
    }
    return vec3(fract(h), clamp(s, 0.0, 1.0), clamp(l, 0.0, 1.0));
}

float rangeFeatherMask(float dist, float range, float feather) {
    float r0 = max(range, 1e-6);
    float r1 = max(range + feather, r0 + 1e-6);
    return 1.0 - smoothstep(r0, r1, dist);
}

float secondaryKeyMaskHSL(vec3 rgb, vec3 sampleRgb) {
    vec3 hslC = rgb2hsl(rgb);
    vec3 hslS = rgb2hsl(sampleRgb);

    float dh = hueDist(hslC.x, hslS.x);
    float ds = abs(hslC.y - hslS.y);
    float dl = abs(hslC.z - hslS.z);

    float hueRange   = mix(0.005, 0.25, clamp(Secondary_Hue_Range / 100.0, 0.0, 1.0));
    float hueFeather = mix(0.000, 0.25, clamp(Secondary_Hue_Feather / 100.0, 0.0, 1.0));

    float satRange   = mix(0.01,  1.00, clamp(Secondary_Sat_Range / 100.0, 0.0, 1.0));
    float satFeather = mix(0.00,  1.00, clamp(Secondary_Sat_Feather / 100.0, 0.0, 1.0));

    float lumRange   = mix(0.01,  1.00, clamp(Secondary_Lum_Range / 100.0, 0.0, 1.0));
    float lumFeather = mix(0.00,  1.00, clamp(Secondary_Lum_Feather / 100.0, 0.0, 1.0));

    float mh = rangeFeatherMask(dh, hueRange, hueFeather);
    float ms = rangeFeatherMask(ds, satRange, satFeather);
    float ml = rangeFeatherMask(dl, lumRange, lumFeather);

    float m = mh * ms * ml;

    float denoise = clamp(Secondary_Denoise / 100.0, 0.0, 1.0);
    m = pow(clamp(m, 0.0, 1.0), 1.0 + denoise * 2.0);

    return clamp(m, 0.0, 1.0);
}

float softenMask(float m) {
    float blur = clamp(Secondary_Blur / 100.0, 0.0, 1.0);
    float softness = mix(1.0, 0.55, blur);
    return pow(clamp(m, 0.0, 1.0), softness);
}

vec3 visualizeSecondaryMask(vec3 origColor, float m, int viewMode) {
    if (viewMode == 2) {
        return vec3(m);
    } else if (viewMode == 1) {
        return mix(vec3(0.0), origColor, m);
    } else {
        return mix(vec3(luma(origColor)), origColor, m);
    }
}

float buildSecondaryMatte(vec3 origColor) {
    if (length(Secondary_Set_Color) <= 0.001) return 0.0;

    float mSet = secondaryKeyMaskHSL(origColor, Secondary_Set_Color);

    float mAdd = 0.0;
    if (length(Secondary_Add_Color) > 0.001) {
        mAdd = secondaryKeyMaskHSL(origColor, Secondary_Add_Color);
    }

    float m = max(mSet, mAdd);

    float mRem = 0.0;
    if (length(Secondary_Remove_Color) > 0.001) {
        mRem = secondaryKeyMaskHSL(origColor, Secondary_Remove_Color);
    }

    m = clamp(m - mRem, 0.0, 1.0);

    int inv = int(clamp(floor(Secondary_Invert_Mask + 0.5), 0.0, 1.0));
    if (inv == 1) m = 1.0 - m;

    m = softenMask(m);
    return clamp(m, 0.0, 1.0);
}

vec3 applySecondary(vec2 uv, vec3 baseColor, vec3 origColor) {
    float m = buildSecondaryMatte(origColor);

    int showMask = int(clamp(floor(Secondary_Show_Mask + 0.5), 0.0, 1.0));
    int viewMode = int(clamp(floor(Secondary_Mask_View + 0.5), 0.0, 2.0));

    if (showMask == 1) {
        return visualizeSecondaryMask(origColor, m, viewMode);
    }

    if (m <= 0.001) return baseColor;

    vec3 c = baseColor;

    c = mix(c, c * Secondary_Color_Wheels, m);

    vec3 tempTinted = applyTempTint(c, Secondary_Temperature, Secondary_Tint);
    c = mix(c, tempTinted, m);

    vec3 contrastC = applyContrast01(c, Secondary_Contrast);
    c = mix(c, contrastC, m);

    if (Secondary_Sharpen > 0.0) {
        vec3 sharp = applySharpen(uv, c, Secondary_Sharpen);
        c = mix(c, sharp, m);
    }

    float secSatSigned = pctToSigned(Secondary_Saturation);
    vec3 satC = applySaturationSigned(c, secSatSigned);
    c = mix(c, satC, m);

    return c;
}

// ---------------------------------------------------------------------
// SECTION 6 – VIGNETTE
// ---------------------------------------------------------------------
uniform float Vignette_Amount;
uniform float Vignette_Midpoint;
uniform float Vignette_Roundness;
uniform float Vignette_Feather;

float vignetteMask(vec2 uv) {
    vec2 p = uv - 0.5;
    float aspect = resolution.x / resolution.y;
    p.x *= aspect;

    float r = length(p);

    float round = clamp(Vignette_Roundness / 100.0, -1.0, 1.0);
    float roundAdj = mix(1.2, 0.8, (round * 0.5 + 0.5));
    r *= roundAdj;

    float mid = mix(0.2, 0.8, clamp(Vignette_Midpoint / 100.0, 0.0, 1.0));
    float feather = mix(0.01, 0.5, clamp(Vignette_Feather / 100.0, 0.0, 1.0));

    float m = smoothstep(mid, mid + feather, r);
    return clamp(m, 0.0, 1.0);
}

vec3 applyVignette(vec2 uv, vec3 c) {
    if (Vignette_Amount == 0.0) return c;

    float m = vignetteMask(uv);
    float amt = clamp(Vignette_Amount / 100.0, -1.0, 1.0);

    vec3 vignetteColor;
    if (amt > 0.0) vignetteColor = c * (1.0 - amt);
    else           vignetteColor = mix(c, vec3(1.0), -amt);

    return mix(c, vignetteColor, m);
}

// ---------------------------------------------------------------------
// MAIN – pipeline order (similar to Lumetri)
// ---------------------------------------------------------------------
void main() {
    vec2 uv = vUvScaled;
    vec4 texel = texture2D(tDiffuse, uv);
    vec3 col = clamp01(texel.rgb);

    // 1. BASIC
    if (length(WB_Selector) > 0.001) col = applyWBSelector(col, WB_Selector);

    col = applyTempTint(col, Temperature, Tint);
    col = applyExposure(col, Exposure);
    col = applyContrast01(col, Contrast);
    col = applyBasicTonal(col, Highlights, Shadows, Whites, Blacks);

    float satBasicSigned = pctToSigned(Saturation_Basic);
    col = applySaturationSigned(col, satBasicSigned);

    // 2. CREATIVE
    col = applyFadedFilm(col, Faded_Film);
    col = applySharpen(uv, col, Sharpen);

    float vibrSigned = clamp(Vibrance / 100.0, -1.0, 1.0);
    col = applyVibrance(col, vibrSigned);

    float satCreativeSigned = pctToSigned(Saturation_Creative);
    col = applySaturationSigned(col, satCreativeSigned);

    col = applySplitTone(col, Shadow_Tint, Highlight_Tint, Tint_Balance);

    // 3. CURVES
    int mode = int(clamp(floor(RGBW_Modes + 0.5), 0.0, 3.0));
    col = applyRGBWCurves(col, mode, Curve_Shadow, Curve_Highlight);

    float curveSatSigned = clamp(Curve_Sat / 100.0, -1.0, 1.0);
    col = applyHueSatLumaCurves(col,
                               Hue_Selector,
                               Saturation_Selector,
                               Luma_Selector,
                               Curve_Hue,
                               curveSatSigned,
                               Curve_Luma);

    // 4. WHEELS
    col = applyColorWheels(col, CW_Shadows, CW_Midtones, CW_Highlights);

    // 5. HSL SECONDARY
    vec3 secOut = applySecondary(uv, col, texel.rgb);

    // IMPORTANT: if Show Mask is ON, output it directly (Lumetri behavior)
    int showMask = int(clamp(floor(Secondary_Show_Mask + 0.5), 0.0, 1.0));
    if (showMask == 1) {
        gl_FragColor = vec4(clamp01(secOut), texel.a);
        return;
    }
    col = secOut;

    // 6. VIGNETTE
    col = applyVignette(vUv, col);

    gl_FragColor = vec4(clamp01(col), texel.a);
}

text./plugins/alipfx/shaders/mangatone.glsl:
precision highp float;
precision highp int;

// Uniforms provided by Panzoid
uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

// Variables passed from Panzoid Vertex Shader
varying vec2 vUvScaled;
varying vec2 vUv;

// === Custom Parameters ===
// Input Adjustment
uniform float Contrast;
uniform float Tone_Curve_Gamma;

// Outline
uniform int Outline_Enable;
uniform float Outline_Threshold;
uniform float Outline_Strength;
uniform float Outline_Fill_Radius;
uniform float Lines_Dark_Fill_Threshold;

// Tone General
uniform int Pattern_Type;
uniform float Tone_Levels;
uniform int Solid_Black_Enable;
uniform float Solid_Black_Threshold;
uniform int Solid_White_Enable;
uniform float Solid_White_Threshold;
uniform int Gradient_Boundaries;
uniform float Gradient_Smoothness;
uniform float Pattern_Size;
uniform float Tone_Rotation;
uniform int Background_Alpha;
uniform float Background_Opacity;
uniform int Alpha_Ink_Color;

// --- INVERTED DOT PARAMETERS ---
// 1.0 = Enable inverted dots in dark areas, 0.0 = Disable
uniform float Invert_Pattern_Enable; 
// Luminance threshold below which the pattern inverts (e.g., 0.3)
uniform float Invert_Pattern_Threshold; 

// Stages
uniform float Tone_Coeff_1;
uniform float Upper_Boundary_1;
uniform float Tone_Coeff_2;
uniform float Upper_Boundary_2;
uniform float Tone_Coeff_3;
uniform float Upper_Boundary_3;
uniform float Tone_Coeff_4;

// Helper: Calculate Luminance
float luminance(vec3 color) {
    return dot(color, vec3(0.299, 0.587, 0.114));
}

// Helper: 2D Rotation Matrix
mat2 rotate2d(float _angle) {
    return mat2(cos(_angle), -sin(_angle),
                sin(_angle), cos(_angle));
}

// Helper: Sobel Edge Detection
float sobelEdge(sampler2D tex, vec2 uv, vec2 res, float radius) {
    vec2 step = radius / res;

    // Kernel
    float tL = luminance(texture2D(tex, uv + vec2(-step.x, step.y)).rgb);
    float tC = luminance(texture2D(tex, uv + vec2(0.0, step.y)).rgb);
    float tR = luminance(texture2D(tex, uv + vec2(step.x, step.y)).rgb);

    float mL = luminance(texture2D(tex, uv + vec2(-step.x, 0.0)).rgb);
    float mR = luminance(texture2D(tex, uv + vec2(step.x, 0.0)).rgb);

    float bL = luminance(texture2D(tex, uv + vec2(-step.x, -step.y)).rgb);
    float bC = luminance(texture2D(tex, uv + vec2(0.0, -step.y)).rgb);
    float bR = luminance(texture2D(tex, uv + vec2(step.x, -step.y)).rgb);

    // Sobel Masks
    float x = tL + 2.0*mL + bL - tR - 2.0*mR - bR;
    float y = tL + 2.0*tC + tR - bL - 2.0*bC - bR;

    return sqrt(x*x + y*y);
}

// Helper: Generate Halftone Pattern
float getPattern(vec2 uv, int type, float size, float angle) {
    vec2 st = uv;
    // Normalize coordinates based on screen aspect ratio
    float aspect = resolution.x / resolution.y;
    st.x *= aspect;

    // Apply Rotation
    st -= vec2(0.5 * aspect, 0.5);
    st *= rotate2d(radians(angle));
    st += vec2(0.5 * aspect, 0.5);

    // Scale for pattern size
    st *= size;

    if (type == 0) {
        // Dot Pattern
        vec2 grid = fract(st) - 0.5;
        float dist = length(grid);
        // Returns a value between 0 and 1, where 1 is the center of the dot
        return 1.0 - (dist * 2.0); 
    } else {
        // Line Pattern
        float line = fract(st.y);
        return 1.0 - abs((line - 0.5) * 2.0);
    }
}

void main() {
    // 1. Fetch Original Texel
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec3 color = texel.rgb;
    float alpha = texel.a;

    // 2. Input Adjustment
    // Apply Contrast
    color = (color - 0.5) * max(Contrast, 0.0) + 0.5;
    // Apply Gamma
    color = pow(abs(color), vec3(1.0 / max(Tone_Curve_Gamma, 0.01)));

    // Get Base Luminance
    float lum = luminance(color);

    // 3. Outline Processing
    float edge = 0.0;
    if (Outline_Enable == 1) {
        edge = sobelEdge(tDiffuse, vUvScaled, resolution, max(Outline_Fill_Radius, 1.0));
        edge *= Outline_Strength;
        // Apply threshold - hard cutoff if threshold is reached
        edge = step(Outline_Threshold, edge);

        // Add dark areas to outline if enabled by threshold
        if (lum < Lines_Dark_Fill_Threshold) {
            edge = 1.0; 
        }
    }

    // 4. Tone Processing
    float finalTone = 1.0; // Start white

    if (edge < 1.0) { // If not an edge pixel, calculate tone
        // Map luminance to discrete stages based on user boundaries
        float stageValue = 0.0;
        float targetTone = 1.0;

        // Determine which stage the luminance falls into
        if (lum <= Upper_Boundary_1) {
            targetTone = Tone_Coeff_1;
        } else if (lum <= Upper_Boundary_2) {
            targetTone = Tone_Coeff_2;
        } else if (lum <= Upper_Boundary_3) {
            targetTone = Tone_Coeff_3;
        } else {
            targetTone = Tone_Coeff_4;
        }

        // Handle Gradient Smoothness between boundaries
        if (Gradient_Boundaries == 1 && Gradient_Smoothness > 0.0) {
             float smoothRange = Gradient_Smoothness * 0.1; // Scale smoothness

             // Smoothstep between stages to blend the Tone Coefficients
             if (abs(lum - Upper_Boundary_1) < smoothRange) {
                 float t = smoothstep(Upper_Boundary_1 - smoothRange, Upper_Boundary_1 + smoothRange, lum);
                 targetTone = mix(Tone_Coeff_1, Tone_Coeff_2, t);
             } else if (abs(lum - Upper_Boundary_2) < smoothRange) {
                 float t = smoothstep(Upper_Boundary_2 - smoothRange, Upper_Boundary_2 + smoothRange, lum);
                 targetTone = mix(Tone_Coeff_2, Tone_Coeff_3, t);
             } else if (abs(lum - Upper_Boundary_3) < smoothRange) {
                 float t = smoothstep(Upper_Boundary_3 - smoothRange, Upper_Boundary_3 + smoothRange, lum);
                 targetTone = mix(Tone_Coeff_3, Tone_Coeff_4, t);
             }
        }

        // Generate the spatial pattern
        float patternVal = getPattern(vUv, Pattern_Type, Pattern_Size, Tone_Rotation);

        // Apply Tone Levels (quantize the pattern)
        if (Tone_Levels > 0.0) {
            patternVal = floor(patternVal * Tone_Levels) / Tone_Levels;
        }

        // Determine if we should invert the pattern based on luminance threshold
        // Modified to use a float for Enable (> 0.5 acts as true)
        bool invertPattern = (Invert_Pattern_Enable > 0.5 && lum < Invert_Pattern_Threshold);

        if (invertPattern) {
            // Inverted Logic: Background is black (0.0), dots are white (1.0)
            if (patternVal > (1.0 - targetTone)) {
                finalTone = 1.0; // White dots
            } else {
                finalTone = 0.0; // Black background
            }
        } else {
            // Standard Logic: Background is white (1.0), dots are black (0.0)
            if (patternVal > targetTone) {
                finalTone = 0.0; // Black dots
            } else {
                finalTone = 1.0; // White background
            }
        }

        // Solid Overrides
        if (Solid_Black_Enable == 1 && lum <= Solid_Black_Threshold) {
            finalTone = 0.0;
        }
        if (Solid_White_Enable == 1 && lum >= Solid_White_Threshold) {
            finalTone = 1.0;
        }
    } else {
        // It's an edge
        finalTone = 0.0; 
    }

    // 5. Output Formatting
    vec4 outputColor = vec4(vec3(finalTone), 1.0);

    // Alpha Handling
    if (alpha < 1.0) { // If there's transparency in the source
        if (Background_Alpha == 1) {
            // Blend with background opacity
            outputColor.a = Background_Opacity;
        } else {
            // Determine Alpha Ink Color
            if (Alpha_Ink_Color == 0) {
                // Keep Original Alpha
                outputColor.a = alpha;
            } else if (Alpha_Ink_Color == 1) {
                 // Force Black
                 outputColor = vec4(0.0, 0.0, 0.0, 1.0);
            } else if (Alpha_Ink_Color == 2) {
                 // Force White
                 outputColor = vec4(1.0, 1.0, 1.0, 1.0);
            }
        }
    }

    gl_FragColor = outputColor;
}

text./plugins/alipfx/shaders/median.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

uniform float Radius;
uniform float Operate_On_Alpha_Channel;

float getChannel(vec4 c, int channel)
{
    if (channel == 0) return c.r;
    if (channel == 1) return c.g;
    if (channel == 2) return c.b;
    return c.a;
}

void sort2(inout float a, inout float b)
{
    if (a > b)
    {
        float t = a;
        a = b;
        b = t;
    }
}

float median9vals(
    float a0, float a1, float a2,
    float a3, float a4, float a5,
    float a6, float a7, float a8
)
{
    sort2(a1, a2);
    sort2(a4, a5);
    sort2(a7, a8);

    sort2(a0, a1);
    sort2(a3, a4);
    sort2(a6, a7);

    sort2(a1, a2);
    sort2(a4, a5);
    sort2(a7, a8);

    sort2(a0, a3);
    sort2(a5, a8);
    sort2(a4, a7);

    sort2(a3, a6);
    sort2(a1, a4);
    sort2(a2, a5);

    sort2(a4, a7);
    sort2(a4, a2);
    sort2(a6, a4);
    sort2(a4, a2);

    return a4;
}

float exactMedian9(vec2 uv, vec2 pixel, vec2 maxUv, int channel)
{
    float v[9];

    for (int i = 0; i < 9; i++)
    {
        int y = i / 3;
        int x = i - y * 3;
        x = x - 1;
        y = y - 1;

        vec2 suv = uv + vec2(float(x), float(y)) * pixel;
        suv = clamp(suv, vec2(0.0), maxUv);

        vec4 s = texture2D(tDiffuse, suv);
        v[i] = getChannel(s, channel);
    }

    for (int a = 0; a < 8; a++)
    {
        for (int b = 0; b < 8; b++)
        {
            if (b < 8 - a)
            {
                if (v[b] > v[b + 1])
                {
                    float t = v[b];
                    v[b] = v[b + 1];
                    v[b + 1] = t;
                }
            }
        }
    }

    return v[4];
}

float exactMedian25(vec2 uv, vec2 pixel, vec2 maxUv, int channel)
{
    float v[25];

    for (int i = 0; i < 25; i++)
    {
        int y = i / 5;
        int x = i - y * 5;
        x = x - 2;
        y = y - 2;

        vec2 suv = uv + vec2(float(x), float(y)) * pixel;
        suv = clamp(suv, vec2(0.0), maxUv);

        vec4 s = texture2D(tDiffuse, suv);
        v[i] = getChannel(s, channel);
    }

    for (int a = 0; a < 24; a++)
    {
        for (int b = 0; b < 24; b++)
        {
            if (b < 24 - a)
            {
                if (v[b] > v[b + 1])
                {
                    float t = v[b];
                    v[b] = v[b + 1];
                    v[b + 1] = t;
                }
            }
        }
    }

    return v[12];
}

float regionValueSoft(vec2 uv, vec2 pixel, vec2 maxUv, vec2 offsetPx, float innerRadiusPx, int channel)
{
    vec2 base = uv + offsetPx * pixel;

    vec2 dx = vec2(innerRadiusPx, 0.0) * pixel;
    vec2 dy = vec2(0.0, innerRadiusPx) * pixel;

    vec2 uv0 = clamp(base,      vec2(0.0), maxUv);
    vec2 uv1 = clamp(base - dx, vec2(0.0), maxUv);
    vec2 uv2 = clamp(base + dx, vec2(0.0), maxUv);
    vec2 uv3 = clamp(base - dy, vec2(0.0), maxUv);
    vec2 uv4 = clamp(base + dy, vec2(0.0), maxUv);

    float v0 = getChannel(texture2D(tDiffuse, uv0), channel);
    float v1 = getChannel(texture2D(tDiffuse, uv1), channel);
    float v2 = getChannel(texture2D(tDiffuse, uv2), channel);
    float v3 = getChannel(texture2D(tDiffuse, uv3), channel);
    float v4 = getChannel(texture2D(tDiffuse, uv4), channel);

    return (v0 + v1 + v2 + v3 + v4) * 0.20;
}

float approxMedianChannel(vec2 uv, vec2 pixel, vec2 maxUv, float radiusPx, int channel)
{
    float r = max(radiusPx, 1.0);
    float innerR = max(floor(r * 0.70 + 0.5), 1.0);

    float s0 = regionValueSoft(uv, pixel, maxUv, vec2(-r, -r), innerR, channel);
    float s1 = regionValueSoft(uv, pixel, maxUv, vec2( 0.0, -r), innerR, channel);
    float s2 = regionValueSoft(uv, pixel, maxUv, vec2( r, -r), innerR, channel);

    float s3 = regionValueSoft(uv, pixel, maxUv, vec2(-r,  0.0), innerR, channel);
    float s4 = regionValueSoft(uv, pixel, maxUv, vec2( 0.0,  0.0), innerR, channel);
    float s5 = regionValueSoft(uv, pixel, maxUv, vec2( r,  0.0), innerR, channel);

    float s6 = regionValueSoft(uv, pixel, maxUv, vec2(-r,  r), innerR, channel);
    float s7 = regionValueSoft(uv, pixel, maxUv, vec2( 0.0,  r), innerR, channel);
    float s8 = regionValueSoft(uv, pixel, maxUv, vec2( r,  r), innerR, channel);

    float med = median9vals(s0, s1, s2, s3, s4, s5, s6, s7, s8);
    float avg9 = (s0 + s1 + s2 + s3 + s4 + s5 + s6 + s7 + s8) / 9.0;
    float softness = 0.10 + 0.20 * smoothstep(4.0, 18.0, r);

    return mix(med, avg9, softness);
}

float hybridMedianChannel(vec2 uv, vec2 pixel, vec2 maxUv, float radiusPx, int channel)
{
    if (radiusPx <= 1.0)
    {
        return exactMedian9(uv, pixel, maxUv, channel);
    }
    else if (radiusPx <= 2.0)
    {
        return exactMedian25(uv, pixel, maxUv, channel);
    }
    else
    {
        return approxMedianChannel(uv, pixel, maxUv, radiusPx, channel);
    }
}

void main()
{
    vec4 center = texture2D(tDiffuse, vUvScaled);
    vec2 pixel = uvScale / resolution;
    vec2 maxUv = max(uvScale - pixel * 0.5, vec2(0.0));

    float radiusPx = floor(max(Radius, 0.0) + 0.5);

    if (radiusPx <= 0.0)
    {
        gl_FragColor = center;
        return;
    }

    float r = hybridMedianChannel(vUvScaled, pixel, maxUv, radiusPx, 0);
    float g = hybridMedianChannel(vUvScaled, pixel, maxUv, radiusPx, 1);
    float b = hybridMedianChannel(vUvScaled, pixel, maxUv, radiusPx, 2);

    float a = center.a;
    if (Operate_On_Alpha_Channel >= 0.5)
    {
        a = hybridMedianChannel(vUvScaled, pixel, maxUv, radiusPx, 3);
    }

    gl_FragColor = vec4(r, g, b, a);
}

text./plugins/alipfx/shaders/minimax-2.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

// ---- 5 parameters (Dynamic Number) ----
uniform float Operation;           // 0=Maximum, 1=Minimum, 2=Opening, 3=Closing
uniform float Radius;              // 0..127 px
uniform float Channel;             // 0=Color, 1=Alpha+Color, 2=R, 3=G, 4=B, 5=Alpha
uniform float Direction;           // ANGLE in degrees (0..360)
uniform float Dont_Shrink_Edges;   // 0/1

// ---- Pass (Static Number) ----
#ifndef Pass
  #define Pass 1
#endif

// 0 = sample only along the rotated direction
// 1 = sample along rotated direction AND its perpendicular, combined like H&V
#define ROTATED_CROSS 0

#define MAX_RADIUS 127

int iabs(int x) { return (x < 0) ? -x : x; }

vec2 pxSizeScaled() { return uvScale / resolution; }

vec4 tex(vec2 uv)
{
  vec2 px = pxSizeScaled();
  vec2 lo = vec2(0.0);
  vec2 hi = uvScale - px * 0.5;
  return texture2D(tDiffuse, clamp(uv, lo, hi));
}

float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

float keyForChannel(vec4 s, int ch)
{
  if (ch == 0) return luma(s.rgb);
  if (ch == 1) return s.a;
  if (ch == 2) return s.r;
  if (ch == 3) return s.g;
  if (ch == 4) return s.b;
  return s.a;
}

// dirPix = direction in pixel space (already scaled by px size)
void morphLinePickPix(
  bool doMax,
  int r,
  int ch,
  vec2 dirPix,
  out vec4 bestS,
  out float bestK
){
  bestS = tex(vUvScaled);
  bestK = keyForChannel(bestS, ch);

  for (int ii = 0; ii <= 2*MAX_RADIUS; ii++)
  {
    int i = ii - MAX_RADIUS;
    if (iabs(i) > r) continue;

    vec4 s = tex(vUvScaled + dirPix * float(i));
    float k = keyForChannel(s, ch);

    if (doMax) { if (k > bestK) { bestK = k; bestS = s; } }
    else       { if (k < bestK) { bestK = k; bestS = s; } }
  }
}

void combinePick(
  bool doMax,
  vec4 aS, float aK,
  vec4 bS, float bK,
  out vec4 outS,
  out float outK
){
  if (doMax)
  {
    if (bK > aK) { outS = bS; outK = bK; }
    else        { outS = aS; outK = aK; }
  }
  else
  {
    if (bK < aK) { outS = bS; outK = bK; }
    else        { outS = aS; outK = aK; }
  }
}

void main()
{
  vec4 center = tex(vUvScaled);

  int op  = int(floor(Operation + 0.5));
  int ch  = int(floor(Channel + 0.5));

  int r = int(floor(Radius + 0.5));
  r = int(clamp(float(r), 0.0, float(MAX_RADIUS)));

  if (r == 0) { gl_FragColor = center; return; }

  // ---- Two-pass stage selection ----
  bool bypass = false;
  bool stageIsMax = true;

#if Pass == 1
  stageIsMax = (op == 0 || op == 3);
  if (op == 1 || op == 2) stageIsMax = false;
#else
  if (op == 0 || op == 1) bypass = true;
  else stageIsMax = (op == 2);
#endif

  if (bypass) { gl_FragColor = center; return; }

  // ---- Build rotated direction in pixel UV space ----
  // Direction is degrees
  float ang = radians(Direction);
  vec2 u = vec2(cos(ang), sin(ang));          // unit direction
  vec2 px = pxSizeScaled();
  vec2 dirPix = vec2(u.x * px.x, u.y * px.y); // scale by pixel size

  vec4 s1 = center; float k1 = keyForChannel(center, ch);
  morphLinePickPix(stageIsMax, r, ch, dirPix, s1, k1);

#if ROTATED_CROSS == 1
  // also sample perpendicular axis and combine like H&V
  vec2 v = vec2(-u.y, u.x);
  vec2 dirPix2 = vec2(v.x * px.x, v.y * px.y);
  vec4 s2 = center; float k2 = keyForChannel(center, ch);
  morphLinePickPix(stageIsMax, r, ch, dirPix2, s2, k2);

  vec4 pickedS; float pickedK;
  combinePick(stageIsMax, s1, k1, s2, k2, pickedS, pickedK);
#else
  vec4 pickedS = s1;
#endif

  // ---- Channel output rules ----
  vec4 outc = center;

  if (ch == 0) { outc.rgb = pickedS.rgb; outc.a = center.a; }
  else if (ch == 1) { outc = pickedS; }
  else if (ch == 2) { outc.r = pickedS.r; }
  else if (ch == 3) { outc.g = pickedS.g; }
  else if (ch == 4) { outc.b = pickedS.b; }
  else              { outc.a = pickedS.a; }

  // ---- Don't Shrink Edges ----
  if (Dont_Shrink_Edges > 0.5)
  {
    bool alphaAffected = (ch == 1 || ch == 5);
    if (alphaAffected && !stageIsMax)
      outc.a = max(outc.a, center.a);
  }

  gl_FragColor = outc;
}

text./plugins/alipfx/shaders/minimax.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUvScaled;

// ---- 5 user parameters (Dynamic Number) ----
uniform float Operation;           // 0=Maximum, 1=Minimum, 2=Opening, 3=Closing
uniform float Radius;              // 0..127 px
uniform float Channel;             // 0=Color, 1=Alpha+Color, 2=R, 3=G, 4=B, 5=Alpha
uniform float Direction;           // 0=H&V, 1=H only, 2=V only
uniform float Dont_Shrink_Edges;   // 0/1

// ---- EXTRA: Pass (Static Number property in Panzoid) ----
#ifndef Pass
  #define Pass 1
#endif

#define MAX_RADIUS 127

int iabs(int x) { return (x < 0) ? -x : x; }

vec2 pxSizeScaled() { return uvScale / resolution; }

vec4 tex(vec2 uv)
{
  vec2 px = pxSizeScaled();
  vec2 lo = vec2(0.0);
  vec2 hi = uvScale - px * 0.5;
  return texture2D(tDiffuse, clamp(uv, lo, hi));
}

// Luma metric for "Color" channel behavior (gives natural "bright bleeds outward")
float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

// Return the scalar key used to choose best neighbor sample depending on Channel mode.
float keyForChannel(vec4 s, int ch)
{
  // 0: Color -> use luminance
  if (ch == 0) return luma(s.rgb);

  // 1: Alpha and Color -> use alpha so alpha expands AND color follows
  if (ch == 1) return s.a;

  // 2/3/4: R/G/B -> use that channel
  if (ch == 2) return s.r;
  if (ch == 3) return s.g;
  if (ch == 4) return s.b;

  // 5: Alpha -> alpha key
  return s.a;
}

// Pick best sample along a 1D line neighborhood (horizontal or vertical),
// using a scalar key so full colors can "bleed" by copying the best neighbor sample.
void morphLinePick(
  bool doMax,
  int r,
  int ch,
  vec2 dirVec,
  out vec4 bestS,
  out float bestK
){
  vec2 px = pxSizeScaled();

  // Initialize with center
  bestS = tex(vUvScaled);
  bestK = keyForChannel(bestS, ch);

  for (int ii = 0; ii <= 2*MAX_RADIUS; ii++)
  {
    int i = ii - MAX_RADIUS;
    if (iabs(i) > r) continue;

    vec4 s = tex(vUvScaled + dirVec * float(i) * px);
    float k = keyForChannel(s, ch);

    if (doMax)
    {
      if (k > bestK) { bestK = k; bestS = s; }
    }
    else
    {
      if (k < bestK) { bestK = k; bestS = s; }
    }
  }
}

// Combine H and V results for Direction=0 by comparing their keys
void combineHVPick(
  bool doMax,
  vec4 hS, float hK,
  vec4 vS, float vK,
  out vec4 outS,
  out float outK
){
  if (doMax)
  {
    if (vK > hK) { outS = vS; outK = vK; }
    else        { outS = hS; outK = hK; }
  }
  else
  {
    if (vK < hK) { outS = vS; outK = vK; }
    else        { outS = hS; outK = hK; }
  }
}

void main()
{
  vec4 center = tex(vUvScaled);

  int op  = int(floor(Operation + 0.5));
  int ch  = int(floor(Channel + 0.5));
  int dir = int(floor(Direction + 0.5));

  int r = int(floor(Radius + 0.5));
  r = int(clamp(float(r), 0.0, float(MAX_RADIUS)));

  if (r == 0)
  {
    gl_FragColor = center;
    return;
  }

  // ---- Decide which stage this pass runs (true 2-pass for op 2/3) ----
  bool bypass = false;
  bool stageIsMax = true; // true = Maximum stage, false = Minimum stage

#if Pass == 1
  // Pass 1:
  // 0 Max, 1 Min, 2 Opening -> Min first, 3 Closing -> Max first
  stageIsMax = (op == 0 || op == 3);
  if (op == 1 || op == 2) stageIsMax = false;
#else
  // Pass 2:
  // For op 0/1, bypass completely.
  // For op 2 (Opening), do Max second.
  // For op 3 (Closing), do Min second.
  if (op == 0 || op == 1)
  {
    bypass = true;
  }
  else
  {
    stageIsMax = (op == 2); // Opening: Max second, Closing: Min second
  }
#endif

  if (bypass)
  {
    gl_FragColor = center;
    return;
  }

  // ---- Run morphology selection (pick best neighbor sample) ----
  vec4 hS = center; float hK = keyForChannel(center, ch);
  vec4 vS = center; float vK = keyForChannel(center, ch);

  if (dir == 1 || dir == 0)
    morphLinePick(stageIsMax, r, ch, vec2(1.0, 0.0), hS, hK);

  if (dir == 2 || dir == 0)
    morphLinePick(stageIsMax, r, ch, vec2(0.0, 1.0), vS, vK);

  vec4 pickedS = hS;
  float pickedK = hK;

  if (dir == 0)
    combineHVPick(stageIsMax, hS, hK, vS, vK, pickedS, pickedK);
  else if (dir == 2)
  { pickedS = vS; pickedK = vK; }

  // ---- Apply Channel output rules ----
  // These rules are what makes Color "bleed", and Alpha+Color expand alpha properly.
  vec4 outc = center;

  if (ch == 0)
  {
    // Color: copy RGB from picked sample, keep original alpha
    outc.rgb = pickedS.rgb;
    outc.a   = center.a;
  }
  else if (ch == 1)
  {
    // Alpha and Color: copy full RGBA from picked sample
    // (this makes alpha expand/shrink outward and color follows)
    outc = pickedS;
  }
  else if (ch == 2)
  {
    // Red only: modify red channel based on picked sample, keep others
    outc.r = pickedS.r;
  }
  else if (ch == 3)
  {
    // Green only
    outc.g = pickedS.g;
  }
  else if (ch == 4)
  {
    // Blue only
    outc.b = pickedS.b;
  }
  else // ch == 5
  {
    // Alpha only: modify alpha, keep RGB
    outc.a = pickedS.a;
  }

  // ---- Don't Shrink Edges (alpha protection on Minimum stage) ----
  // Only applies when alpha is being modified (Channel 1 or 5) AND this stage is Minimum.
  if (Dont_Shrink_Edges > 0.5)
  {
    bool alphaAffected = (ch == 1 || ch == 5);
    if (alphaAffected && !stageIsMax)
    {
      // prevent alpha from going below original alpha
      outc.a = max(outc.a, center.a);
    }
  }

  gl_FragColor = outc;
}

text./plugins/alipfx/shaders/mosaic.glsl:
precision highp float;
precision highp int;

// Enable LOD/Grad if available (WebGL1 uses EXT variants)
#ifdef GL_EXT_shader_texture_lod
#extension GL_EXT_shader_texture_lod : enable
#endif

uniform sampler2D tDiffuse;

uniform vec2 uvScale;      // Panzoid buffer mapping scale
uniform vec2 resolution;   // current layer buffer resolution (pixels)

varying vec2 vUvScaled;

// ---- Custom properties (Dynamic Number in Panzoid) ----
uniform float Horizontal_Blocks;
uniform float Vertical_Blocks;
uniform float Sharp_Colors;

// Fallback averaging quality when EXT LOD isn't available
// 4 = 16 taps (fast, close). 6 = 36 taps (closer). 8 = 64 taps (closest, heavier).
#define AVG_GRID 4

// Optional: if you want averaging in linear light (closer to AE projects set to linear)
// Set to 1 if your AE project blends in linear and you want closer matching.
#define USE_LINEAR_LIGHT 0

vec3 toLinear(vec3 c)  { return pow(c, vec3(2.2)); }
vec3 toGamma(vec3 c)   { return pow(c, vec3(1.0 / 2.2)); }

// Convert layer-space UV (0..1) to buffer UV and sample
vec4 sampleBuffer(vec2 layerUV)
{
  return texture2D(tDiffuse, layerUV * uvScale);
}

// Snap buffer UV to the center of the nearest texel.
// This makes results far less sensitive to Nearest/Linear differences and downsampling.
vec2 snapToTexelCenter(vec2 bufferUV)
{
  vec2 px = bufferUV * resolution;  // pixel coords in current buffer
  px = floor(px) + 0.5;             // center of pixel
  return px / resolution;
}

void main()
{
  // Work in layer UV (0..1), not buffer UV, so the grid is stable under buffer resizing.
  vec2 uv = vUvScaled / uvScale;
  uv = clamp(uv, 0.0, 0.999999);

  // AE-style minimum 1 block
  vec2 blocks = vec2(max(1.0, Horizontal_Blocks), max(1.0, Vertical_Blocks));
  vec2 cellSize = 1.0 / blocks;

  // Which mosaic block is this pixel in?
  vec2 cell = floor(uv * blocks);

  // Center of the block in layer UV
  vec2 centerUV = (cell + 0.5) * cellSize;
  centerUV = clamp(centerUV, 0.0, 0.999999);

  // ---- Sharp Colors (AE: center sample, solid tile) ----
  if (Sharp_Colors >= 0.5)
  {
    // Snap to texel center in *buffer space* to avoid bilinear drift between preview modes.
    vec2 centerBuf = snapToTexelCenter(centerUV * uvScale);
    gl_FragColor = texture2D(tDiffuse, centerBuf);
    return;
  }

  // ---- Non-sharp (AE: blended/averaged tile color) ----
  // Best sampling invariance is using gradient-based sampling to match the block footprint.
  // This tends to keep appearance consistent across Full/Half/Quarter previews when mipmaps exist.
  #ifdef GL_EXT_shader_texture_lod
    // Provide gradients approximately equal to a block's size in buffer UV space.
    // This asks the GPU to filter over ~the whole block area (mip/anisotropic behavior).
    vec2 gradX = vec2(cellSize.x, 0.0) * uvScale;
    vec2 gradY = vec2(0.0, cellSize.y) * uvScale;

    vec2 centerBufUV = centerUV * uvScale;
    vec4 c = texture2DGradEXT(tDiffuse, centerBufUV, gradX, gradY);

    #if USE_LINEAR_LIGHT
      c.rgb = toGamma(toLinear(c.rgb)); // noop-ish structure; kept symmetrical with fallback
    #endif

    gl_FragColor = c;
    return;
  #endif

  // Fallback: multi-sample box average inside each block.
  // Every tap is snapped to texel centers -> reduces differences across filtering & preview scaling.
  vec2 baseUV = cell * cellSize;
  vec3 accRGB = vec3(0.0);
  float accA = 0.0;

  for (int y = 0; y < AVG_GRID; y++)
  {
    for (int x = 0; x < AVG_GRID; x++)
    {
      vec2 f = (vec2(float(x), float(y)) + 0.5) / float(AVG_GRID);
      vec2 suv = baseUV + f * cellSize;
      suv = clamp(suv, 0.0, 0.999999);

      vec2 bufUV = snapToTexelCenter(suv * uvScale);
      vec4 s = texture2D(tDiffuse, bufUV);

      #if USE_LINEAR_LIGHT
        accRGB += toLinear(s.rgb);
      #else
        accRGB += s.rgb;
      #endif

      accA += s.a;
    }
  }

  float invN = 1.0 / float(AVG_GRID * AVG_GRID);

  #if USE_LINEAR_LIGHT
    vec3 outRGB = toGamma(accRGB * invN);
  #else
    vec3 outRGB = accRGB * invN;
  #endif

  gl_FragColor = vec4(outRGB, accA * invN);
}

text./plugins/alipfx/shaders/motion-tile.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;

// ---- Panzoid custom properties ----
uniform vec2  Tile_Center;              // pixels, AE coords (0,0 top-left)
uniform float Tile_Width;               // percent
uniform float Tile_Height;              // percent
uniform float Output_Width;             // percent (bounds expansion)
uniform float Output_Height;            // percent (bounds expansion)
uniform float Mirror_Edges;             // 0/1
uniform float Phase;                    // pixels
uniform float Horizontal_Phase_Shift;   // 0/1

// Seams guard (avoid sampling exactly on tile borders)
vec2 safe01(vec2 uv) {
  vec2 eps = 0.5 / resolution;
  return clamp(uv, eps, 1.0 - eps);
}

float mirrorRepeat1D(float fracPart, float tileIndex) {
  float parity = mod(abs(tileIndex), 2.0);   // 0 or 1
  return mix(fracPart, 1.0 - fracPart, parity);
}

void main()
{
  // AE pixel center (top-left origin) -> UV (bottom-left origin)
  vec2 centerUV = vec2(
    Tile_Center.x / resolution.x,
    1.0 - (Tile_Center.y / resolution.y)
  );

  // Tile scaling: 100% = original
  vec2 tileScale = vec2(Tile_Width, Tile_Height) / 100.0;
  tileScale = max(tileScale, vec2(0.0001));

  // OUTPUT bounds: in AE these expand the output region without changing tile size.
  // 100% == layer size; >100% expands beyond; <100% crops.
  vec2 outHalfUV = 0.5 * vec2(Output_Width, Output_Height) / 100.0;

  // If outside output bounds, output transparent (like "outside expanded bounds")
  vec2 d = vUv - centerUV;
  if (abs(d.x) > outHalfUV.x || abs(d.y) > outHalfUV.y) {
    gl_FragColor = vec4(0.0);
    return;
  }

  // PHASE: offsets alternating columns/rows (common Motion Tile behavior)
  // Default: vertical phase between columns; with Horizontal Phase Shift: horizontal phase between rows. [2](https://www.youtube.com/watch?v=HvaxOys1a-o)[4](https://www.youtube.com/watch?v=JQ7f19mcyyI)
  vec2 localNoPhase = (vUv - centerUV) * tileScale + 0.5;
  float colIndex = floor(localNoPhase.x);
  float rowIndex = floor(localNoPhase.y);

  float colParity = mod(abs(colIndex), 2.0);
  float rowParity = mod(abs(rowIndex), 2.0);

  // Phase is pixels; AE +Y is down so invert vertical sign
  vec2 phaseUV = vec2(Phase / resolution.x, -Phase / resolution.y);

  float hps = step(0.5, Horizontal_Phase_Shift);

  vec2 uvPhased = vUv
    + (1.0 - hps) * vec2(0.0, phaseUV.y * colParity)   // vertical phase on odd columns
    +  hps         * vec2(phaseUV.x * rowParity, 0.0);  // horizontal phase on odd rows

  // Tiling space
  vec2 local = (uvPhased - centerUV) * tileScale + 0.5;
  vec2 tileIndex = floor(local);
  vec2 f = fract(local);

  // Mirror edges: mirror every other tile for seamless tiling. [1](https://www.youtube.com/watch?v=kYhsGHdkaNE)[2](https://www.youtube.com/watch?v=HvaxOys1a-o)
  float mirrorOn = step(0.5, Mirror_Edges);
  vec2 mirrored = vec2(
    mirrorRepeat1D(f.x, tileIndex.x),
    mirrorRepeat1D(f.y, tileIndex.y)
  );

  vec2 sampleUV = mix(f, mirrored, mirrorOn);
  sampleUV = safe01(sampleUV);

  // Map into Panzoid buffer UV
  vec2 bufferUV = sampleUV * uvScale;

  gl_FragColor = texture2D(tDiffuse, bufferUV);
}

text./plugins/alipfx/shaders/mt-s-pixelsorter:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 resolution;

// Panzoid Custom Properties mapped from UI
uniform float Mode;             // 0=Brightness, 1=Saturation, 2=Hue, 3=RGB
uniform float Direction;        // 0=Left->Right, 1=Right->Left, 2=Top->Bottom, 3=Bottom->Top
uniform float Threshold;        // 0 - 255
uniform float Conditional_Sort; // 0=Disabled (Displacement), 1=Enabled (True Sort)

// PERFORMANCE TWEAK: Max search distance for sorting. 
// 50 means it can stretch/sort streaks up to 101 pixels long. 
// Higher values = longer streaks but will drastically reduce frame rate.
const int MAX_SEARCH = 50; 

// Evaluates the pixel based on the chosen Mode
float getValue(vec3 color, float mode) {
    if (mode < 0.5) {
        // 0: Brightness (Luminance)
        return dot(color, vec3(0.299, 0.587, 0.114));
    } else if (mode < 1.5) {
        // 1: Saturation
        float cMax = max(max(color.r, color.g), color.b);
        float cMin = min(min(color.r, color.g), color.b);
        return (cMax > 0.0) ? (cMax - cMin) / cMax : 0.0;
    } else if (mode < 2.5) {
        // 2: Hue
        float cMax = max(max(color.r, color.g), color.b);
        float cMin = min(min(color.r, color.g), color.b);
        float delta = cMax - cMin;
        if (delta == 0.0) return 0.0;
        float h = 0.0;
        if (cMax == color.r) h = mod((color.g - color.b) / delta, 6.0);
        else if (cMax == color.g) h = (color.b - color.r) / delta + 2.0;
        else if (cMax == color.b) h = (color.r - color.g) / delta + 4.0;
        return h / 6.0;
    } else {
        // 3: RGB Intensity
        return (color.r + color.g + color.b) / 3.0;
    }
}

// Maps the UI integer to a 2D vector direction
vec2 getDir(float dir) {
    if (dir < 0.5) return vec2(1.0, 0.0);       // Left to Right
    else if (dir < 1.5) return vec2(-1.0, 0.0); // Right to Left
    else if (dir < 2.5) return vec2(0.0, -1.0); // Top to Bottom (Y is inverted in typical UV)
    else return vec2(0.0, 1.0);                 // Bottom to Top
}

void main() {
    vec2 dirVec = getDir(Direction) / resolution;
    float thresh = Threshold / 255.0;

    vec4 myCol = texture2D(tDiffuse, vUvScaled);
    float myVal = getValue(myCol.rgb, Mode);

    // If current pixel is below threshold, it doesn't get sorted.
    if (myVal < thresh) {
        gl_FragColor = myCol;
        return;
    }

    // 1. Find the bounds of the current continuous sortable segment
    int startIdx = 0;
    int endIdx = 0;

    for (int i = 1; i <= MAX_SEARCH; i++) {
        vec2 uv = vUvScaled - dirVec * float(i);
        if(uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) break;
        if(getValue(texture2D(tDiffuse, uv).rgb, Mode) < thresh) break;
        startIdx = i;
    }

    for (int i = 1; i <= MAX_SEARCH; i++) {
        vec2 uv = vUvScaled + dirVec * float(i);
        if(uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) break;
        if(getValue(texture2D(tDiffuse, uv).rgb, Mode) < thresh) break;
        endIdx = i;
    }

    vec4 resultCol = myCol;

    if (Conditional_Sort > 0.5) {
        // --- TRADITIONAL PIXEL SORT (O(N^2) Rank Sort) ---
        // We evaluate every pixel in the streak. If its sorted rank matches 
        // our current position (startIdx), that's the color we pull.
        for (int i = -MAX_SEARCH; i <= MAX_SEARCH; i++) {
            if (i < -startIdx || i > endIdx) continue;

            vec2 pUv = vUvScaled + dirVec * float(i);
            vec4 pCol = texture2D(tDiffuse, pUv);
            float pVal = getValue(pCol.rgb, Mode);

            int pRank = 0;
            for (int j = -MAX_SEARCH; j <= MAX_SEARCH; j++) {
                if (j < -startIdx || j > endIdx) continue;
                vec2 oUv = vUvScaled + dirVec * float(j);
                float oVal = getValue(texture2D(tDiffuse, oUv).rgb, Mode);

                // Sort descending (higher values pool at the start of the vector)
                if (oVal > pVal) pRank++;
                else if (oVal == pVal && j < i) pRank++; // tie-breaker
            }

            if (pRank == startIdx) {
                resultCol = pCol;
                break;
            }
        }
    } else {
        // --- MISTAKE MODE: DISPLACEMENT BY SORTING ---
        // This calculates the rank of the current pixel, but instead of outputting 
        // the color that belongs here, it accidentally uses the rank difference as an offset distance.
        int myRank = 0;
        for (int j = -MAX_SEARCH; j <= MAX_SEARCH; j++) {
            if (j < -startIdx || j > endIdx) continue;
            vec2 oUv = vUvScaled + dirVec * float(j);
            float oVal = getValue(texture2D(tDiffuse, oUv).rgb, Mode);

            if (oVal > myVal) myRank++;
            else if (oVal == myVal && j < 0) myRank++;
        }

        // The exact "mistake" logic: Translating rank delta into a UV displacement
        float offset = float(myRank - startIdx);
        vec2 displaceUv = clamp(vUvScaled + dirVec * offset, 0.0, 1.0);
        resultCol = texture2D(tDiffuse, displaceUv);
    }

    gl_FragColor = resultCol;
}

text./plugins/alipfx/shaders/multislicer.glsl:
precision highp float;
precision highp int;

// Panzoid Built-in Variables
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUv;
varying vec2 vUvScaled;

// Custom MultiSlicer Properties
uniform float Shift;
uniform float Width;
uniform float Number_of_Slices;
uniform vec2 Anchor_Point;
uniform float Angle;
uniform float Seed;

// Pseudo-random function based on slice index
float rand(float n) {
    return fract(sin(n) * 43758.5453123);
}

void main() {
    // 1. Get exact pixel coordinates
    vec2 pixelPos = vUv * resolution;

    // 2. Offset by Anchor Point
    vec2 pos = pixelPos - Anchor_Point;

    // 3. Rotation Math
    float rad = radians(Angle);
    float c = cos(rad);
    float s = sin(rad);

    mat2 rot = mat2(c, -s, s, c);
    vec2 rotatedPos = rot * pos;

    // 4. Slicing Math
    float maxDim = max(resolution.x, resolution.y) * 2.0;
    float safeSlices = max(Number_of_Slices, 1.0);
    float sliceThickness = maxDim / safeSlices;

    float sliceIndex = floor(rotatedPos.y / sliceThickness);

    // 5. Apply Random Shift per slice
    float randomVal = rand(sliceIndex + (Seed * 123.456));
    float currentShift = Shift * (randomVal * 2.0 - 1.0);
    rotatedPos.x -= currentShift;

    // 6. Calculate Width Masking (The Fix)
    // Find where the current pixel sits vertically inside its specific slice
    float localY = mod(rotatedPos.y, sliceThickness);

    // Treat Width as a percentage (e.g., 100.0 = full thickness, 50.0 = half thickness)
    float visibleThickness = sliceThickness * (Width / 100.0);

    // 7. Inverse Rotation
    mat2 invRot = mat2(c, s, -s, c);
    vec2 newPos = invRot * rotatedPos;
    newPos += Anchor_Point;

    // 8. Convert back to Normalized UVs
    vec2 finalUv = newPos / resolution;

    // 9. Mask and Render
    // If the pixel falls outside the canvas OR outside the "Width" of the slice, make it transparent
    if (finalUv.x < 0.0 || finalUv.x > 1.0 || finalUv.y < 0.0 || finalUv.y > 1.0 || localY > visibleThickness) {
        gl_FragColor = vec4(0.0);
    } else {
        gl_FragColor = texture2D(tDiffuse, finalUv * uvScale);
    }
}

text./plugins/alipfx/shaders/nesprite.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

// Custom Panzoid Properties (Spaces automatically converted to underscores)
uniform float Factor;
uniform float Saturation;
uniform float Dithering;
uniform float Dither_Level;
uniform float Alpha_from_Src;
uniform float CRT_Filter;
uniform float CRT_Horizontal_Alpha;
uniform float CRT_Vertical_Alpha;
uniform float CRT_Blur_Radius;
uniform float CRT_RGB_Shift_1;
uniform float CRT_RGB_Shift_2;
uniform float Brightness;
uniform float Brightness_Threshold;
uniform float Palette;

// Custom Palette Colors
uniform vec3 Color_1;
uniform vec3 Color_2;
uniform vec3 Color_3;
uniform vec3 Color_4;
uniform vec3 Color_5;
uniform vec3 Color_6;
uniform vec3 Color_7;
uniform vec3 Color_8;

varying vec2 vUvScaled;
varying vec2 vUv;

// --- Dithering Matrices (Mathematically unrolled for WebGL 1.0 compatibility) ---
float bayer4x4(vec2 p) {
    vec2 v = mod(p, 4.0);
    int idx = int(v.x) + int(v.y) * 4;
    if(idx==0) return 0.0/16.0 - 0.5;   if(idx==1) return 8.0/16.0 - 0.5;
    if(idx==2) return 2.0/16.0 - 0.5;   if(idx==3) return 10.0/16.0 - 0.5;
    if(idx==4) return 12.0/16.0 - 0.5;  if(idx==5) return 4.0/16.0 - 0.5;
    if(idx==6) return 14.0/16.0 - 0.5;  if(idx==7) return 6.0/16.0 - 0.5;
    if(idx==8) return 3.0/16.0 - 0.5;   if(idx==9) return 11.0/16.0 - 0.5;
    if(idx==10) return 1.0/16.0 - 0.5;  if(idx==11) return 9.0/16.0 - 0.5;
    if(idx==12) return 15.0/16.0 - 0.5; if(idx==13) return 7.0/16.0 - 0.5;
    if(idx==14) return 13.0/16.0 - 0.5; return 5.0/16.0 - 0.5;
}

float bayer8x8(vec2 p) {
    vec2 v1 = mod(p, 4.0);
    vec2 v2 = mod(floor(p / 4.0), 2.0);
    float b4 = bayer4x4(v1) + 0.5;
    int idx2 = int(v2.x) + int(v2.y) * 2;
    float b2 = 0.0;
    if(idx2==0) b2=0.0; else if(idx2==1) b2=2.0; else if(idx2==2) b2=3.0; else b2=1.0;
    return ((b4 + b2 * 16.0) / 64.0) - 0.5;
}

float bayer8x4(vec2 p) {
    return bayer8x8(vec2(p.x, p.y * 2.0));
}

// --- Palette Matching Logic ---
vec3 mapToPalette(vec3 col, int pal) {
    if (pal == 0) return col; // None

    vec3 best = vec3(0.0);
    float minD = 999.0;

    // Macro to check distance quickly
    #define CHK(c) { float d = dot(col-(c), col-(c)); if(d < minD) { minD = d; best = (c); } }

    if (pal == 1) { // Picker Mode
        CHK(Color_1); CHK(Color_2); CHK(Color_3); CHK(Color_4);
        CHK(Color_5); CHK(Color_6); CHK(Color_7); CHK(Color_8);
    } 
    else if (pal == 2) { // NES (Essential Subset)
        CHK(vec3(0.0)); CHK(vec3(1.0)); CHK(vec3(0.46,0.46,0.46)); CHK(vec3(0.0,0.0,0.98));
        CHK(vec3(0.0,0.45,0.85)); CHK(vec3(0.0,0.68,0.52)); CHK(vec3(0.0,0.65,0.0));
        CHK(vec3(0.22,0.56,0.0)); CHK(vec3(0.54,0.44,0.0)); CHK(vec3(0.79,0.33,0.0));
        CHK(vec3(0.89,0.11,0.0)); CHK(vec3(0.87,0.0,0.45)); CHK(vec3(0.68,0.0,0.8));
        CHK(vec3(0.39,0.0,0.98));
    } 
    else if (pal == 3) { // GBC
        CHK(vec3(0.05,0.22,0.05)); CHK(vec3(0.18,0.38,0.18));
        CHK(vec3(0.54,0.67,0.05)); CHK(vec3(0.60,0.73,0.05));
    } 
    else if (pal == 4) { // Commodore 64
        CHK(vec3(0.0)); CHK(vec3(1.0)); CHK(vec3(0.53,0.0,0.0)); CHK(vec3(0.66,1.0,0.93));
        CHK(vec3(0.8,0.26,0.8)); CHK(vec3(0.0,0.8,0.33)); CHK(vec3(0.0,0.0,0.66));
        CHK(vec3(0.93,0.93,0.46)); CHK(vec3(0.86,0.53,0.33)); CHK(vec3(0.4,0.26,0.0));
        CHK(vec3(1.0,0.46,0.46)); CHK(vec3(0.2)); CHK(vec3(0.46)); CHK(vec3(0.66,1.0,0.4));
        CHK(vec3(0.0,0.53,1.0)); CHK(vec3(0.73));
    }
    else if (pal == 5) { // Aqua
        CHK(vec3(0.0,0.2,0.4)); CHK(vec3(0.0,0.4,0.6)); CHK(vec3(0.0,0.6,0.8)); CHK(vec3(0.0,0.8,1.0)); CHK(vec3(0.2,1.0,1.0)); CHK(vec3(1.0));
    }
    else if (pal == 6) { // Retro
        CHK(vec3(0.1,0.0,0.2)); CHK(vec3(0.4,0.0,0.4)); CHK(vec3(0.8,0.0,0.4)); CHK(vec3(1.0,0.2,0.0)); CHK(vec3(1.0,0.8,0.0)); CHK(vec3(0.0,1.0,1.0));
    }
    else if (pal == 7) { // Pastel128
        CHK(vec3(1.0,0.7,0.7)); CHK(vec3(0.7,1.0,0.7)); CHK(vec3(0.7,0.7,1.0)); CHK(vec3(1.0,1.0,0.7)); CHK(vec3(0.7,1.0,1.0)); CHK(vec3(1.0,0.7,1.0)); CHK(vec3(0.9)); CHK(vec3(0.5));
    }
    else if (pal == 8) { // Fire_1
        CHK(vec3(0.0)); CHK(vec3(0.3,0.0,0.0)); CHK(vec3(0.6,0.1,0.0)); CHK(vec3(0.9,0.3,0.0)); CHK(vec3(1.0,0.6,0.0)); CHK(vec3(1.0,0.9,0.0)); CHK(vec3(1.0));
    }
    else if (pal == 9) { // Fire_2
        CHK(vec3(0.1,0.0,0.0)); CHK(vec3(0.4,0.0,0.1)); CHK(vec3(0.8,0.2,0.1)); CHK(vec3(1.0,0.5,0.2)); CHK(vec3(1.0,0.8,0.4)); CHK(vec3(1.0,1.0,0.8));
    }

    return best;
}

// --- Main Pixel Processing Function ---
vec4 getPixelatedSample(vec2 uv) {
    float f = max(1.0, floor(Factor));
    vec2 gridUv = floor(uv * resolution / f) * f / resolution;
    vec2 centerUv = gridUv + (f / 2.0) / resolution;
    vec2 texUv = centerUv * uvScale;

    vec4 baseCol = texture2D(tDiffuse, texUv);

    // 1. Handle Alpha Inheritance
    float alpha = baseCol.a;
    if (Alpha_from_Src < 0.5) {
        alpha = step(0.99, alpha);
    }

    // 2. Saturation Processing
    float lum = dot(baseCol.rgb, vec3(0.299, 0.587, 0.114));
    vec3 col = mix(vec3(lum), baseCol.rgb, 1.0 + Saturation);

    // 3. Dithering Processing
    vec2 ditherCoord = floor(gridUv * resolution / f);
    float ditherVal = 0.0;
    int dMode = int(Dithering);

    if (dMode == 1) ditherVal = bayer4x4(ditherCoord);
    else if (dMode == 2) ditherVal = bayer8x8(ditherCoord);
    else if (dMode == 3) ditherVal = bayer8x4(ditherCoord);

    col += ditherVal * Dither_Level;

    // 4. Quantize to Palette
    col = mapToPalette(clamp(col, 0.0, 1.0), int(Palette));

    return vec4(col, alpha);
}

void main() {
    vec4 finalOut;

    if (CRT_Filter < 0.5) {
        finalOut = getPixelatedSample(vUv);
    } else {
        // --- CRT Filter: Shift & Blur Logic ---
        float br = CRT_Blur_Radius;
        float s1 = CRT_RGB_Shift_1 / resolution.x;
        float s2 = CRT_RGB_Shift_2 / resolution.x;

        vec2 off[5];
        off[0] = vec2(0.0);
        off[1] = vec2(1.0, 0.0) * br / resolution;
        off[2] = vec2(-1.0, 0.0) * br / resolution;
        off[3] = vec2(0.0, 1.0) * br / resolution;
        off[4] = vec2(0.0, -1.0) * br / resolution;

        vec3 blurredCol = vec3(0.0);
        float alphaAccum = 0.0;

        // Combine Pre-blur shift (s1) and Post-blur chromatic shift (s2)
        for(int i = 0; i < 5; i++) {
            vec2 tapUv = vUv + off[i];
            vec4 rTap = getPixelatedSample(tapUv + vec2(s1 + s2, 0.0));
            vec4 gTap = getPixelatedSample(tapUv);
            vec4 bTap = getPixelatedSample(tapUv - vec2(s1 + s2, 0.0));

            blurredCol += vec3(rTap.r, gTap.g, bTap.b);
            alphaAccum += gTap.a; // Use green channel alpha as structural baseline
        }

        blurredCol *= 0.2;
        alphaAccum *= 0.2;

        // --- CRT Scanlines ---
        float scanH = sin(vUv.y * resolution.y * 3.14159) * 0.5 + 0.5;
        float scanV = sin(vUv.x * resolution.x * 3.14159) * 0.5 + 0.5;

        blurredCol *= (1.0 - (1.0 - scanH) * CRT_Horizontal_Alpha);
        blurredCol *= (1.0 - (1.0 - scanV) * CRT_Vertical_Alpha);

        finalOut = vec4(max(vec3(0.0), blurredCol), alphaAccum);
    }

    // --- Post-Processing Brightness (Recalculating darkened CRT screens) ---
    float outLum = dot(finalOut.rgb, vec3(0.299, 0.587, 0.114));
    if ((outLum * 255.0) <= Brightness_Threshold) {
        // Brightness scaled for standard 0-255 mapping
        finalOut.rgb += (Brightness / 255.0); 
    }

    gl_FragColor = finalOut;
}

text./plugins/alipfx/shaders/night-vision.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;

uniform vec2 resolution;
// Panzoid's built-in time uniform for animating the noise
uniform float time; 

// Custom Properties mapped from Panzoid
uniform float Phosphor;
uniform float Gain;
uniform float Bloom;
uniform float Sensor_Noise;
uniform float Scope_Overlay;

// Pseudo-random noise function
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

void main()
{
    // 1. Initial Input Sample
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // 2. Bloom / Light Glow
    vec3 bloom = vec3(0.0);
    if (Bloom > 0.0) {
        float blurSize = 4.0 / resolution.x;
        for(int i = -2; i <= 2; i++) {
            for(int j = -2; j <= 2; j++) {
                vec2 offset = vec2(float(i), float(j)) * blurSize;
                vec3 tap = texture2D(tDiffuse, vUvScaled + offset).rgb;
                float tapLum = dot(tap, vec3(0.299, 0.587, 0.114));
                bloom += tap * smoothstep(0.4, 1.0, tapLum);
            }
        }
        bloom /= 25.0; 
        texel.rgb += bloom * (Bloom * 3.0); 
    }

    // 3. Gain (Light Amplification & Contrast)
    float lum = dot(texel.rgb, vec3(0.299, 0.587, 0.114));
    lum = pow(lum, 1.0 - (Gain * 0.6)); 
    lum *= (1.0 + Gain * 2.5); 
    lum = clamp(lum, 0.0, 1.0);

    // 4. Phosphor Color Gradient Mapping
    vec3 colorShadow, colorMid, colorHigh;

    if (Phosphor < 0.5) { 
        // 0: Gen-3 Green
        colorShadow = vec3(0.0, 0.15, 0.0);
        colorMid    = vec3(0.1, 0.8, 0.2);
        colorHigh   = vec3(0.85, 1.0, 0.85);
    } else if (Phosphor < 1.5) { 
        // 1: White Phosphor (Adjusted to match the cold cyan/silver tint)
        colorShadow = vec3(0.02, 0.05, 0.08); 
        colorMid    = vec3(0.35, 0.45, 0.55); 
        colorHigh   = vec3(0.95, 0.98, 1.0);  
    } else if (Phosphor < 2.5) { 
        // 2: Amber
        colorShadow = vec3(0.2, 0.05, 0.0);
        colorMid    = vec3(0.8, 0.45, 0.05);
        colorHigh   = vec3(1.0, 0.9, 0.6);
    } else { 
        // 3: Blue Intensifier
        colorShadow = vec3(0.0, 0.05, 0.2);
        colorMid    = vec3(0.1, 0.4, 0.8);
        colorHigh   = vec3(0.8, 0.9, 1.0);
    }

    vec3 finalColor;
    // Map the luminance smoothly across the three colors
    if (lum < 0.5) {
        finalColor = mix(colorShadow, colorMid, lum * 2.0);
    } else {
        finalColor = mix(colorMid, colorHigh, (lum - 0.5) * 2.0);
    }

    // 5. Soft Vignette (Scanlines removed)
    vec2 centerDist = vUv - 0.5;
    float vig = dot(centerDist, centerDist);
    finalColor *= 1.0 - vig * 1.2;

    // 6. Sensor Noise (Scintillation)
    if (Sensor_Noise > 0.0) {
        float n = rand(vUv * (time * 10.0 + 1.0));
        float noiseIntensity = Sensor_Noise * (1.0 - lum * 0.6) * 0.4; 
        finalColor += (n - 0.5) * noiseIntensity;
    }

    // 7. Scope Overlay
    if (Scope_Overlay > 0.5) {
        vec2 centeredUv = vUv - 0.5;
        centeredUv.x *= resolution.x / resolution.y; 

        float dist = length(centeredUv);

        float scopeMask = 1.0 - smoothstep(0.40, 0.42, dist);

        // Scope Crosshairs
        float lineThickness = 0.0015;
        float crossX = 1.0 - smoothstep(0.0, lineThickness, abs(centeredUv.x));
        float crossY = 1.0 - smoothstep(0.0, lineThickness, abs(centeredUv.y));
        float crosshair = max(crossX, crossY) * step(dist, 0.40); 

        finalColor = (finalColor * scopeMask) + (crosshair * 0.2 * colorMid);
    }

    // Output final composition
    gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), texel.a);
}

text./plugins/alipfx/shaders/nimble-nimbus.gl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;
uniform vec2 uvScale;

// ==========================================
// 26 CUSTOM PARAMETER UNIFORMS
// ==========================================

// - Cloud Design
uniform float Cloud_Length;
uniform float Cloud_Scale;
uniform float Slant;
uniform float Vertical_Alignment;
uniform float End_Roundy;
uniform float Spacing;
uniform float Random_Seed;

// - Cloud Top Control
uniform float Top_Contrast;
uniform float Top_Variation;
uniform float Top_Correlation;
uniform float Taper_Left_Top;
uniform float Taper_Right_Top;

// - Cloud Bottom Control
uniform float Bottom_Scale;
uniform float Bottom_Contrast;
uniform float Bottom_Variation;
uniform float Bottom_Correlation;
uniform float Taper_Left_Bottom;
uniform float Taper_Right_Bottom;

// - Animation
uniform float Evolution;
uniform float Top_Evolution_Scale;
uniform float Reverse_Top_Direction;    // 0.0 for Disabled, 1.0 for Enabled
uniform float Bottom_Evolution_Scale;
uniform float Reverse_Bottom_Direction; // 0.0 for Disabled, 1.0 for Enabled

// - Secondary Animation
uniform float Secondary_Animation_Amount;
uniform float Secondary_Evolution;
uniform float Secondary_Evolution_Scale;

// ==========================================
// PROCEDURAL MATH & NOISE GENERATION
// ==========================================

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Single-octave noise with Quintic interpolation for perfectly round, smooth shapes
float smooth_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Quintic polynomial for ultra-smooth circular easing
    vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);

    return mix(mix(hash(i + vec2(0.0,0.0)), hash(i + vec2(1.0,0.0)), u.x),
               mix(hash(i + vec2(0.0,1.0)), hash(i + vec2(1.0,1.0)), u.x), u.y);
}

// ==========================================
// MAIN RENDER PASS
// ==========================================
void main()
{
    vec2 p = vUv - vec2(0.5);
    float aspect = resolution.x / resolution.y;
    p.x *= aspect;

    // Base Transformations
    p.x -= p.y * (Slant * 0.01);
    p.y -= Vertical_Alignment * 0.005;

    float L = (Cloud_Length / 100.0) * 0.5 * aspect;

    // Bounds Check Optimization
    if (p.x < -L || p.x > L) {
        gl_FragColor = texture2D(tDiffuse, vUvScaled);
        return;
    }

    // ------------------------------------------
    // EVOLUTION TIME MAPPING
    // ------------------------------------------
    float ev_cycles = Evolution / 360.0;
    float top_dir = (Reverse_Top_Direction > 0.5) ? -1.0 : 1.0;
    float bot_dir = (Reverse_Bottom_Direction > 0.5) ? -1.0 : 1.0;

    float top_roll = ev_cycles * Top_Evolution_Scale * top_dir * 6.0;
    float bot_roll = ev_cycles * Bottom_Evolution_Scale * bot_dir * 6.0;

    float sec_cycles = Secondary_Evolution / 360.0;
    float sec_morph = sec_cycles * Secondary_Evolution_Scale * 3.0;

    float cloud_thickness = (Cloud_Scale / 100.0) * 0.12;

    // ------------------------------------------
    // TOP EDGE PROFILE (Smooth Bubbly Circles)
    // ------------------------------------------
    float freq_top = 2.5 / (max(0.1, Top_Correlation) * 0.09);
    vec2 eval_pos_top = vec2(p.x * freq_top - top_roll + Random_Seed, sec_morph);

    // Use single-octave smooth noise to keep the shapes round and unified
    float n_top = smooth_noise(eval_pos_top) * 2.0 - 1.0;

    float contrast_top = Top_Contrast / 100.0;
    if (contrast_top > 0.0) {
        float p_pow = 1.0 + contrast_top * 4.0;
        n_top = sign(n_top) * pow(abs(n_top), 1.0 / p_pow);
    }

    // Using absolute value creates perfect, smooth rounded peaks and sharp crevices
    float hump_top = max(0.0, abs(n_top) - (Spacing / 100.0) * 0.4);
    float height_top = cloud_thickness * (1.0 + (Top_Variation / 100.0) * hump_top);

    // ------------------------------------------
    // BOTTOM EDGE PROFILE (Smooth Bubbly Circles)
    // ------------------------------------------
    float freq_bot = 2.5 / (max(0.1, Bottom_Correlation) * 0.09);
    vec2 eval_pos_bot = vec2(p.x * freq_bot - bot_roll + Random_Seed * 3.14, sec_morph);

    float n_bot = smooth_noise(eval_pos_bot) * 2.0 - 1.0;

    float contrast_bot = Bottom_Contrast / 100.0;
    if (contrast_bot > 0.0) {
        float p_pow_b = 1.0 + contrast_bot * 4.0;
        n_bot = sign(n_bot) * pow(abs(n_bot), 1.0 / p_pow_b);
    }
    float hump_bot = max(0.0, abs(n_bot) - (Spacing / 100.0) * 0.4);

    float base_bot_height = cloud_thickness * (Bottom_Scale / 100.0);
    float height_bottom = base_bot_height * (1.0 + (Bottom_Variation / 100.0) * hump_bot);

    // ------------------------------------------
    // SECONDARY EVOLUTION OVERLAYS
    // ------------------------------------------
    if (Secondary_Animation_Amount > 0.0) {
        float sec_amt = Secondary_Animation_Amount / 100.0;

        float n_sec_top = smooth_noise(vec2(p.x * freq_top * 1.5 - top_roll * 1.2, sec_morph + 10.0)) * 2.0 - 1.0;
        height_top += cloud_thickness * sec_amt * abs(n_sec_top) * 0.4;

        if (Bottom_Scale > 0.0) {
            float n_sec_bot = smooth_noise(vec2(p.x * freq_bot * 1.5 - bot_roll * 1.2, sec_morph + 10.0)) * 2.0 - 1.0;
            height_bottom += base_bot_height * sec_amt * abs(n_sec_bot) * 0.4;
        }
    }

    // ------------------------------------------
    // EDGE TAPERING
    // ------------------------------------------
    float t_l_t = clamp((p.x + L) / (L * max(0.01, Taper_Left_Top / 100.0)), 0.0, 1.0);
    float t_r_t = clamp((L - p.x) / (L * max(0.01, Taper_Right_Top / 100.0)), 0.0, 1.0);
    height_top *= pow(min(t_l_t, t_r_t), 1.0 / max(0.1, End_Roundy));

    float t_l_b = clamp((p.x + L) / (L * max(0.01, Taper_Left_Bottom / 100.0)), 0.0, 1.0);
    float t_r_b = clamp((L - p.x) / (L * max(0.01, Taper_Right_Bottom / 100.0)), 0.0, 1.0);
    height_bottom *= pow(min(t_l_b, t_r_b), 1.0 / max(0.1, End_Roundy));

    // ------------------------------------------
    // RENDER OUTPUT
    // ------------------------------------------
    float pixel_size = 1.5 / resolution.y;
    float mask_top = smoothstep(height_top + pixel_size, height_top - pixel_size, p.y);
    float mask_bottom = smoothstep(-height_bottom - pixel_size, -height_bottom + pixel_size, p.y);
    float cloud_mask = mask_top * mask_bottom;

    vec4 background = texture2D(tDiffuse, vUvScaled);
    vec4 cloud_color = vec4(1.0, 1.0, 1.0, 1.0); 

    gl_FragColor = mix(background, cloud_color, cloud_mask);
}

text./plugins/alipfx/shaders/nisai-stroke.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;

// Built-in Panzoid Uniforms
uniform vec2 resolution;
uniform vec2 uvScale;

// 1. General Settings
uniform vec3 Stroke_Color;
uniform float Stroke_Width;
uniform float Stroke_Only; // float mode
uniform float Placement;   // float mode
uniform float Shape_Style; // float mode
uniform float Color_Source; // float mode
uniform float Source_Opacity;
uniform float Stroke_Opacity;
uniform float Blend_Mode; // float mode

// 2. Glow Settings
uniform float Softness;
uniform float Falloff;

// 3. Halftone Settings
uniform float Cell_Size;
uniform float Screen_Angle;
uniform vec2 Grid_Offset;

// 4. Gradient Settings
uniform vec3 Start_Color;
uniform vec3 End_Color;
uniform float Blend_Start;
uniform float Blend_End;
uniform float Angle;
uniform float Transition; // float mode
uniform float Halftone_Cell_Size;
uniform float Gradient_Screen_Angle; 
uniform vec2 Gradient_Grid_Offset;   
uniform float Halftone_Invert; // float mode

void main() {
    // Read base source layer
    vec4 src = texture2D(tDiffuse, vUvScaled);
    float srcAlpha = src.a;

    float maxA = 0.0;
    float avgA = 0.0;
    float aspect = resolution.x / resolution.y;
    vec2 pxSize = 1.0 / resolution;

    // 128-Tap Golden Spiral for High-Quality Single-Pass Stroke
    int SAMPLES = 128;
    float fSAMPLES = float(SAMPLES);
    float goldenAngle = 2.39996323;

    // Skip heavy sampling if it's just a Fill placement
    if (Placement == 3.0) { 
         maxA = 1.0;
         avgA = 1.0;
    } else {
         float rawAvgA = 0.0; // Used to track pure density for "Both" mode
         for(int i = 1; i <= 128; i++) {
             float r = sqrt(float(i) / fSAMPLES);
             float theta = float(i) * goldenAngle;
             vec2 offset = vec2(cos(theta), sin(theta)) * r * Stroke_Width * pxSize;
             float a = texture2D(tDiffuse, vUvScaled + (offset * uvScale)).a;

             rawAvgA += a;

             // [FIX]: Invert for Inside mode
             if (Placement == 1.0) {
                 a = 1.0 - a; 
             }

             maxA = max(maxA, a);
             avgA += a;
         }
         avgA /= fSAMPLES;
         rawAvgA /= fSAMPLES;

         // [FIX]: Special handling for "Both" placement to grow inwards and outwards
         if (Placement == 2.0) {
             float edgeIntensity = 1.0 - (abs(rawAvgA - 0.5) * 2.0);
             avgA = clamp(edgeIntensity, 0.0, 1.0);
             maxA = step(0.01, avgA); 
         }
    }

    // Process Shape Style (Comparing as floats)
    float strokeBaseAlpha = 0.0;
    if (Shape_Style == 0.0) { // Solid
        strokeBaseAlpha = step(0.01, maxA);
    } else if (Shape_Style == 1.0) { // Glow
        float sft = max(0.1, Softness / 10.0);
        float glowBase = avgA * sft;
        strokeBaseAlpha = clamp(pow(glowBase, max(0.1, Falloff)), 0.0, 1.0);
    } else if (Shape_Style == 2.0) { // Halftone
        float rad = Screen_Angle * 3.14159 / 180.0;
        mat2 rot = mat2(cos(rad), -sin(rad), sin(rad), cos(rad));
        vec2 gridUv = rot * ((vUv * resolution) - Grid_Offset) / max(1.0, Cell_Size);
        vec2 local = fract(gridUv) - 0.5;
        float dist = length(local);

        float radius = clamp(avgA * 1.5, 0.0, 1.0); 

        strokeBaseAlpha = step(dist, radius) * step(0.01, maxA);
    }

    // Process Placement
    float finalStrokeAlpha = 0.0;
    if (Placement == 0.0) finalStrokeAlpha = clamp(strokeBaseAlpha - srcAlpha, 0.0, 1.0); // Outside
    else if (Placement == 1.0) {
        // [FIX]: We inverted the mask generation, so strokeBaseAlpha is the INNER border.
        // We just need to constrain it to the original shape to be safe.
        finalStrokeAlpha = clamp(strokeBaseAlpha * srcAlpha, 0.0, 1.0); 
    }
    else if (Placement == 2.0) finalStrokeAlpha = strokeBaseAlpha; // Both
    else if (Placement == 3.0) finalStrokeAlpha = srcAlpha; // Fill

    // Process Color Source (Comparing as float)
    vec3 strokeRGB = Stroke_Color;
    if (Color_Source == 1.0) { // Gradient
        float rad = Angle * 3.14159 / 180.0;
        vec2 dir = vec2(cos(rad), sin(rad));
        vec2 cUv = vUv - 0.5;
        cUv.x *= aspect; 
        float proj = dot(cUv, dir);
        float t = proj + 0.5;

        float bs = Blend_Start / 100.0;
        float be = max(Blend_End / 100.0, bs + 0.001); 
        float gMix = smoothstep(bs, be, t);

        if (Transition == 1.0) { 
            float hrad = Gradient_Screen_Angle * 3.14159 / 180.0;
            mat2 hrot = mat2(cos(hrad), -sin(hrad), sin(hrad), cos(hrad));
            vec2 hgrid = hrot * ((vUv * resolution) - Gradient_Grid_Offset) / max(1.0, Halftone_Cell_Size);
            vec2 hlocal = fract(hgrid) - 0.5;
            float hdist = length(hlocal);
            float hradius = gMix * 0.707;
            float ht = step(hdist, hradius);
            if (Halftone_Invert == 1.0) ht = 1.0 - ht;
            gMix = ht;
        }
        strokeRGB = mix(Start_Color, End_Color, gMix);
    }

    finalStrokeAlpha *= clamp(Stroke_Opacity / 100.0, 0.0, 1.0);
    float finalSrcAlpha = srcAlpha * clamp(Source_Opacity / 100.0, 0.0, 1.0);

    vec4 sCol = vec4(strokeRGB, finalStrokeAlpha);
    vec4 baseCol = vec4(src.rgb, finalSrcAlpha);
    vec4 outCol = vec4(0.0);

    if (Stroke_Only == 1.0) {
        outCol = vec4(sCol.rgb * sCol.a, sCol.a);
    } else {
        vec4 botLayer = (Placement == 0.0) ? sCol : baseCol;
        vec4 topLayer = (Placement == 0.0) ? baseCol : sCol;

        // Apply Blend Modes (Comparing as floats)
        vec3 bRGB = topLayer.rgb;
        if (Blend_Mode == 1.0) bRGB = botLayer.rgb + topLayer.rgb; 
        else if (Blend_Mode == 2.0) bRGB = 1.0 - (1.0 - botLayer.rgb) * (1.0 - topLayer.rgb); 
        else if (Blend_Mode == 3.0) bRGB = botLayer.rgb * topLayer.rgb; 

        float outA = topLayer.a + botLayer.a * (1.0 - topLayer.a);
        vec3 outRGB = (bRGB * topLayer.a + botLayer.rgb * botLayer.a * (1.0 - topLayer.a)) / max(outA, 0.00001);

        outCol = vec4(outRGB * outA, outA); 
    }

    gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/noise.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Panzoid custom properties
uniform float Amount_Of_Noise; // 0.0 - 100.0
uniform float Noise_Type;      // 0.0 = Mono, 1.0 = Color
uniform float Clipping;        // 0.0 = Off, 1.0 = On

// Built-in Panzoid uniform for animation
uniform float time; // Time in seconds

// Random generator with time-based seed
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233)) + time * 10.0) * 43758.5453);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    float noiseAmount = Amount_Of_Noise / 100.0;

    vec3 noiseColor;
    if (Noise_Type > 0.5) {
        noiseColor = vec3(
            rand(vUvScaled + vec2(0.123, 0.456)),
            rand(vUvScaled + vec2(0.789, 0.101)),
            rand(vUvScaled + vec2(0.112, 0.131))
        );
    } else {
        float n = rand(vUvScaled * 1000.0);
        noiseColor = vec3(n);
    }

    vec3 resultColor = texel.rgb + (noiseColor - 0.5) * noiseAmount;

    if (Clipping > 0.5) {
        resultColor = clamp(resultColor, 0.0, 1.0);
    }

    gl_FragColor = vec4(resultColor, texel.a);
}

text./plugins/alipfx/shaders/optics-compensat:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
varying vec2 vUv;
varying vec2 vUvScaled;

uniform float Field_Of_View;
uniform float Reverse_Lens_Distortion;
uniform float FOV_Orientation;
uniform vec2 View_Center;
uniform float Optimal_Pixels;
uniform float Resize;

#define M_PI 3.14159265359

void main()
{
    vec2 uv = vUvScaled;
    vec2 centerUV = (View_Center / resolution) * uvScale;

    // UV to pixel space
    vec2 deltaUV = uv - centerUV;
    vec2 deltaPixel = deltaUV / uvScale * resolution;

    // maxR based on FOV orientation ONLY (no aspect correction)
    float maxR;
    if (FOV_Orientation < 0.5) {
        maxR = resolution.x * 0.5;      // Horizontal: half width
    }
    else if (FOV_Orientation < 1.5) {
        maxR = resolution.y * 0.5;      // Vertical: half height
    }
    else {
        maxR = length(resolution) * 0.5; // Diagonal: half diagonal
    }

    // Raw pixel distance (NOT aspect-corrected)
    float r = length(deltaPixel);
    float rNorm = r / (maxR + 0.0001);
    rNorm = clamp(rNorm, 0.0, 5.0);

    // FOV calibration
    float k = Field_Of_View / 230.0;
    vec2 distortedPixel;

    if (Field_Of_View == 0.0) {
        distortedPixel = deltaPixel;
    }
    else if (Reverse_Lens_Distortion < 0.5) {
        // BARREL
        float r2 = rNorm * rNorm;
        float distortion = 1.0 + k * r2 + k * k * r2 * r2 * 0.5;
        distortedPixel = deltaPixel * distortion;
    }
    else {
        // REVERSE
        if (Optimal_Pixels < 0.5) {
            float r2 = rNorm * rNorm;
            float distortion = 1.0 / (1.0 + k * r2 + k * k * r2 * r2 * 0.5);
            distortedPixel = deltaPixel * distortion;
        }
        else {
            // SPHERE
            float fovRad = Field_Of_View * M_PI / 180.0;
            float angle = rNorm * fovRad * 0.5;
            angle = clamp(angle, 0.0, M_PI * 0.499);
            float sinA = sin(angle);
            float cosA = cos(angle);
            float sphereR = sinA / (cosA + 0.0001);
            float distortion = sphereR / (angle + 0.0001);
            float intensity = clamp(Field_Of_View / 180.0, 0.0, 1.0);
            distortion = mix(1.0, distortion, intensity);
            distortedPixel = deltaPixel * distortion;
        }
    }

    // RESIZE
    if (Reverse_Lens_Distortion > 0.5 && Resize > 0.5) {
        float maxScale = (Resize < 1.5) ? 2.0 : (Resize < 2.5) ? 4.0 : 100.0;
        float zoomFactor = 1.0 + k * 0.5;
        zoomFactor = min(zoomFactor, maxScale);
        distortedPixel = distortedPixel * zoomFactor;
    }

    // Back to UV and sample
    vec2 distortedUV = (distortedPixel / resolution) * uvScale;
    vec2 resultUV = centerUV + distortedUV;

    vec4 color;
    if (resultUV.x < 0.0 || resultUV.x > uvScale.x ||
        resultUV.y < 0.0 || resultUV.y > uvScale.y) {
        color = vec4(0.0, 0.0, 0.0, 0.0);
    } else {
        color = texture2D(tDiffuse, resultUV);
    }

    gl_FragColor = color;
}

text./plugins/alipfx/shaders/oscilloscope.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;
uniform float time;

// Custom Properties from Panzoid UI
uniform int Test_signal;
uniform float Picture_gain;
uniform float Picture_threshold;
uniform float Audio_gain;
uniform float Signal_resolution;
uniform float Steps_per_loop;
uniform float Beam_point_density;
uniform float Trace_frequency;
uniform float Phosphor_fade_time;
uniform float Beam_width;
uniform float Brightness;
uniform float Intensity_flicker;
uniform float Curvature_gain;
uniform int Transparent;

// Pseudo-random generator for the analog beam flicker
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

// Vintage CRT glass curvature distortion
vec2 applyCurvature(vec2 uv, float curve) {
    if (curve <= 0.0) return uv;
    uv = uv * 2.0 - 1.0;
    vec2 offset = abs(uv.yx) / (4.0 / curve);
    uv = uv + uv * offset * offset;
    uv = uv * 0.5 + 0.5;
    return uv;
}

void main() {
    // 1. Apply Screen Curvature
    vec2 uv = applyCurvature(vUvScaled, Curvature_gain);

    // Capture the original frame color for transparency overlay masking
    vec4 baseTexel = texture2D(tDiffuse, uv);

    // Handle out-of-bounds pixels from screen curvature distortion
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        gl_FragColor = (Transparent == 1) ? baseTexel : vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // 2. High-Frequency Analog Modulation (Simulating Audio Gain Ribbon Effect)
    // This creates the vertical zig-zag lines seen in the text contours
    float wavePhase = uv.x * Steps_per_loop * 0.1 + time * Trace_frequency;
    float analogJitter = sin(wavePhase) * (Audio_gain * 0.0015);
    vec2 sampleUv = uv + vec2(0.0, analogJitter);

    // 3. Edge Detection Signal Extraction
    vec2 texel = 1.0 / (resolution * max(Signal_resolution / 1000.0, 0.1));
    float bw = max(Beam_width, 0.1);

    vec4 t00 = texture2D(tDiffuse, sampleUv + vec2(-texel.x, -texel.y) * bw);
    vec4 t10 = texture2D(tDiffuse, sampleUv + vec2( 0.0,     -texel.y) * bw);
    vec4 t20 = texture2D(tDiffuse, sampleUv + vec2( texel.x, -texel.y) * bw);
    vec4 t01 = texture2D(tDiffuse, sampleUv + vec2(-texel.x,  0.0) * bw);
    vec4 t21 = texture2D(tDiffuse, sampleUv + vec2( texel.x,  0.0) * bw);
    vec4 t02 = texture2D(tDiffuse, sampleUv + vec2(-texel.x,  texel.y) * bw);
    vec4 t12 = texture2D(tDiffuse, sampleUv + vec2( 0.0,      texel.y) * bw);
    vec4 t22 = texture2D(tDiffuse, sampleUv + vec2( texel.x,  texel.y) * bw);

    vec4 sx = t00 + 2.0*t01 + t02 - (t20 + 2.0*t21 + t22);
    vec4 sy = t00 + 2.0*t10 + t20 - (t02 + 2.0*t12 + t22);
    float edge = length(sx) + length(sy);

    float signal = smoothstep(Picture_threshold, Picture_threshold + 0.2, edge) * Picture_gain;

    // 4. Test Signal Mode Override
    if (Test_signal == 1) {
        float testWave = sin(uv.x * Trace_frequency * 5.0 + time * 10.0) * 0.25 + 0.5;
        float dist = abs(uv.y - testWave + analogJitter);
        signal = smoothstep(Beam_width * 0.015, 0.0, dist) * Picture_gain;
    }

    // 5. Beam Density, Flicker & Sweep Decay Simulation
    float flicker = 1.0 - (Intensity_flicker * 0.05 * rand(vec2(time, uv.y)));
    float sweep = fract((uv.x + uv.y) * (Steps_per_loop * 0.001) - time * (Trace_frequency * 0.1));
    float fade = mix(1.0, sweep, clamp(Phosphor_fade_time / 100.0, 0.0, 1.0));

    // Create dotted/dashed vector structural properties via point density
    float densityPattern = abs(sin(uv.x * Beam_point_density));

    // Combine everything into a unified beam intensity value
    float intensity = signal * (Brightness * 0.1) * flicker * fade * densityPattern;
    intensity = clamp(intensity, 0.0, 1.0);

    // 6. Color Construction (White Core + Vibrant Green Phosphor Glow)
    vec3 phosphorGlow = vec3(0.2, 0.95, 0.55); // Rich mint green glow
    vec3 beamCore     = vec3(0.85, 1.0, 0.9);  // Hot white center core
    vec3 finalBeamColor = mix(phosphorGlow * intensity, beamCore, pow(intensity, 4.0)) * intensity;

    // 7. Output Layer Composite Routing
    if (Transparent == 1) {
        // Composites the oscilloscope lines directly on top of the original layer
        gl_FragColor = vec4(max(baseTexel.rgb, finalBeamColor), baseTexel.a);
    } else {
        // Keeps the background completely solid black
        gl_FragColor = vec4(finalBeamColor, 1.0);
    }
}

text./plugins/alipfx/shaders/photocopy-scan-l:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;

// Panzoid Custom Properties
uniform float Exposure;
uniform float Contrast;
uniform float Toner_Crush;
uniform float Line_Strength;
uniform float Line_Density;
uniform float Vertical_Streaks;
uniform float Dust_Paper_Noise;

// Helper: Pseudo-random number generator
float rand(vec2 co) {
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

// Helper: 2D Value Noise for the streaks
float valueNoise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    float a = rand(i);
    float b = rand(i + vec2(1.0, 0.0));
    float c = rand(i + vec2(0.0, 1.0));
    float d = rand(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a)* u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void main() {
    // 1. Sample the base image
    vec4 texColor = texture2D(tDiffuse, vUvScaled);

    // Convert to Grayscale
    float luma = dot(texColor.rgb, vec3(0.299, 0.587, 0.114));
    vec3 color = vec3(luma);

    // --- COLOR CORRECTION ---
    // Apply the warm "Photocopy Paper" tint instead of pure B&W
    vec3 paperTint = vec3(0.96, 0.93, 0.88); // Warm off-white
    vec3 inkTint = vec3(0.12, 0.12, 0.13);   // Slightly faded black
    color = mix(inkTint, paperTint, color);

    // --- TONE SECTION ---
    // Exposure
    color *= max(Exposure, 0.0);

    // Contrast
    color = (color - 0.5) * Contrast + 0.5;

    // Toner Crush (Thresholding midtones)
    float crushMin = Toner_Crush * 0.35;
    float crushMax = 1.0 - (Toner_Crush * 0.35);
    color = smoothstep(crushMin, crushMax, color);

    // --- SCAN TEXTURE SECTION ---

    // 5. Line Density & Strength (Thick Horizontal Bands)
    float lineFreq = Line_Density * 200.0;
    float linePattern = sin(vUv.y * lineFreq);
    // Using smoothstep creates thicker, TV-like bars instead of thin sharp lines
    float lines = smoothstep(-0.3, 0.7, linePattern);
    color -= (1.0 - lines) * Line_Strength * 0.7;

    // 6. Vertical Streaks (Scanner Drag)
    float streaks = valueNoise(vec2(vUv.x * 25.0, vUv.y * 1.5));
    color -= streaks * Vertical_Streaks * 0.4;

    // 7. Dust & Paper Noise (After Effects Style)
    // Base AE-style fine grain
    float aeNoise = rand(vUvScaled * 1000.0); 
    color += (aeNoise - 0.5) * Dust_Paper_Noise * 0.4;

    // Sparse dust specks (Dark and Light dots)
    float speckle = rand(vUv * 150.0);
    if (speckle < 0.015 * Dust_Paper_Noise) {
        color -= 0.8; // Dark dust
    } else if (speckle > 1.0 - 0.015 * Dust_Paper_Noise) {
        color += 0.8; // Light paper fibers
    }

    // Clamp to prevent visual artifacts
    color = clamp(color, 0.0, 1.0);

    // Output final composition
    gl_FragColor = vec4(color, texColor.a);
}

text./plugins/alipfx/shaders/pro-line-extract:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 resolution;

// === CUSTOM PROPERTIES (create these in the Shader Effect panel) ===
uniform float Method;            // 0.0 = XDoG Anime, 1.0 = XDoG Manga, 2.0 = Multiply Blur
uniform float Threshold;         // 0.0 - 1.0
uniform float Line_Thickness;    // 0.0 - 10.0 (scales sample radius)
uniform float Softness;          // 0.0 - 1.0
uniform float Noise_Reduction;   // 0.0 - 1.0 (threshold bias)
uniform float Sigma;             // 0.0 - 5.0 (detail/blur level)
uniform float Sigma_Ratio;       // 0.1 - 5.0
uniform float Sharpness;         // 0.0 - 100.0
uniform float Edge_Hardness;     // 0.0 - 100.0 (0=soft, 100=hard)
uniform float Detail_Boost;      // 0.0 - 5.0
uniform float Invert_Lines;      // 0.0 = off, 1.0 = on
uniform float Output_Mode;       // 0.0 = composite, 1.0 = lines only (alpha)
uniform vec3 Line_Color;         // RGB line tint
uniform float Use_Line_Color;    // 0.0 = default tones, 1.0 = use Line_Color
uniform vec3 Background_Color;   // RGB background
uniform float Background_Opacity; // 0.0 - 100.0

// ================================================================

float luminance(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

float sampleLum(vec2 uv) {
    return luminance(texture2D(tDiffuse, uv).rgb);
}

void main() {
    vec2 uv = vUvScaled;
    vec2 px = 1.0 / resolution;

    // Sigma handling: if Sigma=0, use near-original (0.01) for inner blur
    // and treat Sigma_Ratio as the absolute outer sigma
    float s1 = max(Sigma, 0.01);
    float s2 = (Sigma > 0.0) ? max(s1 * Sigma_Ratio, 0.01) : max(Sigma_Ratio, 0.01);

    // Add Line_Thickness as extra radius
    s1 += Line_Thickness;
    s2 += Line_Thickness;

    // 5x5 Difference-of-Gaussians kernel
    float sum1 = 0.0;
    float sum2 = 0.0;
    float w1 = 0.0;
    float w2 = 0.0;

    for (int x = -2; x <= 2; x++) {
        for (int y = -2; y <= 2; y++) {
            vec2 off = vec2(float(x), float(y));
            float distSq = dot(off, off);

            float g1 = exp(-distSq / (2.0 * s1 * s1));
            float g2 = exp(-distSq / (2.0 * s2 * s2));

            vec2 sampleUV = uv + off * px;
            float lum = sampleLum(sampleUV);

            sum1 += lum * g1;
            sum2 += lum * g2;
            w1 += g1;
            w2 += g2;
        }
    }

    float blur1 = sum1 / w1;
    float blur2 = sum2 / w2;
    float dog = abs(blur2 - blur1) * Sharpness;

    // Detail boost: add local high-frequency detail
    float centerLum = sampleLum(uv);
    dog += abs(centerLum - blur1) * Detail_Boost;

    // Noise reduction: slightly raise threshold
    float thresh = Threshold + Noise_Reduction * 0.05;
    float hard = clamp(Edge_Hardness / 100.0, 0.0, 1.0);

    float lineMask = 0.0;

    if (Method < 0.5) {
        // XDoG Anime: smooth anti-aliased sketch lines with gray tones
        float soft = mix(0.15, 0.001, hard) + Softness * 0.1;
        lineMask = smoothstep(thresh - soft, thresh + soft, dog);
    } 
    else if (Method < 1.5) {
        // XDoG Manga: hard threshold + FILL DARK REGIONS
        float edgeMask = step(thresh, dog);

        // NEW: Fill any original-image region darker than threshold with black
        float fillMask;
        if (Softness > 0.0) {
            float soft = Softness * 0.05;
            fillMask = 1.0 - smoothstep(thresh - soft, thresh + soft, centerLum);
        } else {
            fillMask = 1.0 - step(thresh, centerLum);
        }

        // Combine edges + dark region fill
        lineMask = max(edgeMask, fillMask);
    } 
    else {
        // Multiply Blur: high contrast edges (white on black default)
        float soft = mix(0.1, 0.001, hard) + Softness * 0.05;
        lineMask = smoothstep(thresh - soft, thresh + soft, dog);
    }

    // Invert switch
    if (Invert_Lines > 0.5) {
        lineMask = 1.0 - lineMask;
    }
    lineMask = clamp(lineMask, 0.0, 1.0);

    // Color logic
    vec3 lineCol;
    vec3 bgCol = mix(vec3(1.0), Background_Color, Background_Opacity / 100.0);

    if (Method > 1.5) {
        lineCol = (Use_Line_Color > 0.5) ? Line_Color : vec3(1.0);
        bgCol = vec3(0.0);
    } else {
        lineCol = (Use_Line_Color > 0.5) ? Line_Color : vec3(0.0);
    }

    // Output
    if (Output_Mode < 0.5) {
        vec3 final = mix(bgCol, lineCol, lineMask);
        gl_FragColor = vec4(final, 1.0);
    } else {
        gl_FragColor = vec4(lineCol, lineMask);
    }
}

