const float PI = 3.14159265;

float hash11(float p, float s) {
    return fract(sin(p * 12.9898 + s * 78.233) * 43758.5);
}

float hash21(vec2 p, float s) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(sin(dot(p, vec2(12.99, 78.23)) + s) * 43758.5);
}

vec3 rgb2ok(vec3 c) {
    float l = 0.4122 * c.r + 0.5363 * c.g + 0.0514 * c.b;
    float m = 0.2119 * c.r + 0.6807 * c.g + 0.1074 * c.b;
    float s = 0.0883 * c.r + 0.2817 * c.g + 0.63 * c.b;
    l = pow(l, 0.333);
    m = pow(m, 0.333);
    s = pow(s, 0.333);
    return vec3(0.2104 * l + 0.7936 * m - 0.00407 * s,
                  1.978 * l - 2.4286 * m + 0.4506 * s,
                  0.0259 * l + 0.7828 * m - 0.8087 * s);
}

vec3 ok2rgb(vec3 c) {
    float l = c.x + 0.3963 * c.y + 0.2158 * c.z;
    float m = c.x - 0.1056 * c.y - 0.06385 * c.z;
    float s = c.x - 0.0895 * c.y - 1.2915 * c.z;
    l = l * l * l;
    m = m * m * m;
    s = s * s * s;
    return vec3(4.0767 * l - 3.3077 * m + 0.231 * s,
                -1.2684 * l + 2.6098 * m - 0.3413 * s,
                -0.0042 * l - 0.7034 * m + 1.7076 * s);
}

vec3 toLch(vec3 l) {
    return vec3(l.x, length(l.yz), atan(l.z, l.y));
}

vec3 fromLch(vec3 l) {
    return vec3(l.x, l.y * cos(l.z), l.y * sin(l.z));
}

float hueDiff(float a, float b, float m) {
    float d = b - a;
    d = mod(d + PI, 6.28318) - PI;
    if (m < 0.5) return d;
    if (m < 1.5) return d - sign(d) * 6.28318;
    if (m < 2.5) return d > 0.0 ? d - 6.28318 : d;
    return d < 0.0 ? d + 6.28318 : d;
}

vec3 mixColor(vec3 a, vec3 b, float t, float s, float h) {
    if (s < 0.5) return mix(a, b, t);
    vec3 l1 = rgb2ok(a), l2 = rgb2ok(b);
    if (s < 1.5) return clamp(ok2rgb(mix(l1, l2, t)), 0.0, 1.0);
    vec3 c1 = toLch(l1), c2 = toLch(l2);
    float hh = c1.z + hueDiff(c1.z, c2.z, h) * t;
    return clamp(ok2rgb(fromLch(vec3(mix(c1.x, c2.x, t), mix(c1.y, c2.y, t), hh))), 0.0, 1.0);
}

vec3 getGradientColor(float t, float s, float h) {
    int n = int(Gradient_Colors + 0.5);
    if (n <= 2) return mixColor(Color_1, Color_2, t, s, h);
    if (n == 3) {
        if (t < 0.5) return mixColor(Color_1, Color_2, t * 2.0, s, h);
        return mixColor(Color_2, Color_3, (t - 0.5) * 2.0, s, h);
    }
    if (n == 4) {
        if (t < 0.33333) return mixColor(Color_1, Color_2, t * 3.0, s, h);
        if (t < 0.66666) return mixColor(Color_2, Color_3, (t - 0.33333) * 3.0, s, h);
        return mixColor(Color_3, Color_4, (t - 0.66666) * 3.0, s, h);
    }
    if (n == 5) {
        if (t < 0.25) return mixColor(Color_1, Color_2, t * 4.0, s, h);
        if (t < 0.5) return mixColor(Color_2, Color_3, (t - 0.25) * 4.0, s, h);
        if (t < 0.75) return mixColor(Color_3, Color_4, (t - 0.5) * 4.0, s, h);
        return mixColor(Color_4, Color_5, (t - 0.75) * 4.0, s, h);
    }
    if (n == 6) {
        if (t < 0.2) return mixColor(Color_1, Color_2, t * 5.0, s, h);
        if (t < 0.4) return mixColor(Color_2, Color_3, (t - 0.2) * 5.0, s, h);
        if (t < 0.6) return mixColor(Color_3, Color_4, (t - 0.4) * 5.0, s, h);
        if (t < 0.8) return mixColor(Color_4, Color_5, (t - 0.6) * 5.0, s, h);
        return mixColor(Color_5, Color_6, (t - 0.8) * 5.0, s, h);
    }
    if (n == 7) {
        if (t < 0.16666) return mixColor(Color_1, Color_2, t * 6.0, s, h);
        if (t < 0.33333) return mixColor(Color_2, Color_3, (t - 0.16666) * 6.0, s, h);
        if (t < 0.5) return mixColor(Color_3, Color_4, (t - 0.33333) * 6.0, s, h);
        if (t < 0.66666) return mixColor(Color_4, Color_5, (t - 0.5) * 6.0, s, h);
        if (t < 0.83333) return mixColor(Color_5, Color_6, (t - 0.66666) * 6.0, s, h);
        return mixColor(Color_6, Color_7, (t - 0.83333) * 6.0, s, h);
    }
    if (t < 0.14285) return mixColor(Color_1, Color_2, t * 7.0, s, h);
    if (t < 0.28571) return mixColor(Color_2, Color_3, (t - 0.14285) * 7.0, s, h);
    if (t < 0.42857) return mixColor(Color_3, Color_4, (t - 0.28571) * 7.0, s, h);
    if (t < 0.57142) return mixColor(Color_4, Color_5, (t - 0.42857) * 7.0, s, h);
    if (t < 0.71428) return mixColor(Color_5, Color_6, (t - 0.57142) * 7.0, s, h);
    if (t < 0.85714) return mixColor(Color_6, Color_7, (t - 0.71428) * 7.0, s, h);
    return mixColor(Color_7, Color_8, (t - 0.85714) * 7.0, s, h);
}

float loopRef(float t) {
    if (Gradient_Reflect > 0.5) t = 1.0 - abs(mod(t, 2.0) - 1.0);
    if (Gradient_Loop > 0.5) t = fract(t);
    return t;
}

float loopRefOp(float t) {
    if (Opacity_Loop > 0.5) t = fract(t);
    return t;
}

void getDef(out vec2 p1, out vec2 p2, out vec2 c, out float r) {
    if (Definition_Mode < 0.5) {
        p1 = Start;
        p2 = End;
        c = (p1 + p2) * 0.5;
        r = distance(p1, p2) * 0.5;
    } else {
        float a = radians(Angle);
        vec2 d = vec2(cos(a), sin(a));
        if (Orientation > 0.5) d = vec2(-d.y, d.x);
        p1 = 0.5 + d * (Start_Part - 0.5);
        p2 = 0.5 + d * (End_Part - 0.5);
        c = vec2(Center_X_Part, Center_Y_Part);
        r = Radius_Part;
    }
}

float gT(vec2 uv, out float forceTransparent) {
    vec2 p1, p2, c;
    float r;
    getDef(p1, p2, c, r);
    int gt = int(Gradient_Type + 0.5);
    forceTransparent = 0.0;

    // Compute base gradient value first
    float t = 0.0;
    if (gt == 0) {
        vec2 d = p2 - p1;
        t = dot(uv - p1, d) / max(dot(d, d), 1e-6);
    } else if (gt == 1) {
        t = distance(uv, c) / max(r, 1e-5);
    } else if (gt == 2) {
        t = fract((atan(uv.y - c.y, uv.x - c.x) - radians(Start_Angle)) / 6.28318);
    } else if (gt == 3) {
        vec2 a = uv - p1, b = uv - p2;
        if (Magnet_Perpendicular < 0.5) {
            float d = atan(a.y, a.x) - atan(b.y, b.x);
            d = mod(d + PI, 6.28318) - PI;
            t = d / 6.28318 + 0.5;
        } else {
            t = log(max(length(a), 1e-5) / max(length(b), 1e-5)) / 4.0 + 0.5;
        }
    } else {
        // =====================================================================
        // CONTOUR MODE: auto-detects alpha boundary vs full-layer UV border
        // =====================================================================
        float myAlpha = texture2D(tDiffuse, vUvScaled).a;
        vec2 px = 1.0 / resolution;
        float maxR = max(Max_Length * min(resolution.x, resolution.y) * 0.5, 1.0);
        float bestDist = maxR;
        bool foundEdge = false;

        if (myAlpha < 0.01) {
            bestDist = 0.0;
            foundEdge = true;
        } else {
            vec2 dirs[8];
            dirs[0] = vec2(1.0, 0.0);
            dirs[1] = vec2(-1.0, 0.0);
            dirs[2] = vec2(0.0, 1.0);
            dirs[3] = vec2(0.0, -1.0);
            dirs[4] = normalize(vec2(1.0, 1.0));
            dirs[5] = normalize(vec2(-1.0, 1.0));
            dirs[6] = normalize(vec2(1.0, -1.0));
            dirs[7] = normalize(vec2(-1.0, -1.0));

            for (int i = 0; i < 8; i++) {
                for (int j = 1; j <= 8; j++) {
                    float dist = float(j) * maxR / 8.0;
                    vec2 off = dirs[i] * dist * px;
                    float sa = texture2D(tDiffuse, vUvScaled + off).a;
                    if (sa < 0.5) {
                        bestDist = min(bestDist, dist);
                        foundEdge = true;
                        break;
                    }
                }
            }
        }

        if (foundEdge) {
            // Shape / text / mask mode: distance from alpha boundary
            t = 1.0 - clamp(bestDist / maxR, 0.0, 1.0);
            if (Transparent_After_Max_Length > 0.5 && bestDist >= maxR)
                forceTransparent = 1.0;
        } else {
            // Full layer / adjustment layer mode: distance from UV border
            float uvDist = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y)) * 2.0;
            t = 1.0 - clamp(uvDist / max(Max_Length, 1e-4), 0.0, 1.0);
            if (Transparent_After_Max_Length > 0.5 && uvDist > Max_Length)
                forceTransparent = 1.0;
        }
    }

    // --- STRIPES: slice into discrete stripes and offset along gradient direction ---
    if (Stripes_Enabled > 0.5 && gt != 4) {
        float px = 0.0;

        if (gt == 0) {
            vec2 dir = normalize(p2 - p1 + 1e-5);
            vec2 pr_px = normalize(vec2(-dir.y * resolution.y, dir.x * resolution.x));
            px = dot((uv - 0.5) * resolution, pr_px);
        } else if (gt == 1) {
            px = length((uv - c) * resolution);
        } else if (gt == 2) {
            px = length((uv - c) * resolution);
        } else if (gt == 3) {
            px = t * min(resolution.x, resolution.y);
        }

        px += Stripes_Perpendicular_Offset;
        float id = floor(px / max(Stripes_Width, 1.0));
        float so = (hash11(id, Stripes_Seed) - 0.5) * Stripes_Max_Offset;
        t += so;
    }

    t = (t - Gradient_Offset) / max(Gradient_Scale, 1e-4);

    if (Scattering_Value > 0.0) {
        float n = hash21(uv * 512.0, Scattering_Seed) - 0.5;
        if (Scattering_Fix_Loop_Edge > 0.5 && Gradient_Loop > 0.5)
            n *= smoothstep(0.0, 0.02, fract(t)) * smoothstep(0.0, 0.02, 1.0 - fract(t));
        t += n * Scattering_Value;
    }

    return loopRef(t) * (Gradient_Invert > 0.5 ? -1.0 : 1.0) + (Gradient_Invert > 0.5 ? 1.0 : 0.0);
}

void main() {
    vec2 uv = vUv;
    vec4 b = texture2D(tDiffuse, vUvScaled);
    float forceTransparent = 0.0;
    float t = gT(uv, forceTransparent);
    float tc = clamp(t, 0.0, 1.0);

    vec3 col = getGradientColor(tc, Gradient_Color_Space, Gradient_Hue_Interpolation);

    float ot = (t - Opacity_Offset) / max(Opacity_Scale, 1e-4);
    ot = loopRefOp(ot);
    float a = mix(Opacity_Left, Opacity_Right, clamp(ot, 0.0, 1.0));

    if (forceTransparent > 0.5) a = 0.0;

    vec3 o = col;
    if (Color_Mode > 0.5)
        o = (Color_Mode < 1.5) ? clamp(b.rgb + col * a, 0.0, 1.0) : b.rgb * mix(vec3(1.0), col, a);

    float oa = (Opacity_Mode < 0.5) ? a : b.a * a;
    if (Color_Mode < 0.5 && Opacity_Mode > 0.5) {
        o = mix(b.rgb, col, a);
        oa = mix(b.a, 1.0, a);
    }

    // Mask final output by input alpha so transparent pixels stay transparent
    gl_FragColor = vec4(o, oa * b.a);
}

text./plugins/alipfx/shaders/qc-color-analyze:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;
varying vec2 vUv;

// Custom Properties (User Parameters)
uniform vec2 Sample_Point;
uniform float Circle_Size;
uniform float Sample_Point_Radius;
uniform float Scale;
uniform float Offset_X;
uniform float Offset_Y;
uniform float BG_Opacity;
uniform float Lock_Color;
uniform float Show_Circle;
uniform float Show_Swatch;
uniform float Show_LCH;
uniform float Show_HSV;
uniform float Show_RGB;

// 3x5 Bitmap Font Unpacking Helper
int getBit(int val, int x, int y) {
    if (x < 0 || x > 2 || y < 0 || y > 4) return 0;
    int bitIndex = y * 3 + (2 - x);
    float power = floor(pow(2.0, float(bitIndex)) + 0.5);
    return int(mod(floor(float(val) / power), 2.0));
}

// Font Character Database (ASCII mapping to 3x5 bitmasks)
int getCharFontCode(int ascii) {
    if (ascii == 48) return 31599; // '0'
    if (ascii == 49) return 11415; // '1'
    if (ascii == 50) return 29671; // '2'
    if (ascii == 51) return 29647; // '3'
    if (ascii == 52) return 23497; // '4'
    if (ascii == 53) return 31183; // '5'
    if (ascii == 54) return 31215; // '6'
    if (ascii == 55) return 29330; // '7'
    if (ascii == 56) return 31727; // '8'
    if (ascii == 57) return 31695; // '9'
    if (ascii == 46) return 2;     // '.'
    if (ascii == 37) return 21157; // '%'
    if (ascii == 76) return 18727; // 'L'
    if (ascii == 67) return 31015; // 'C'
    if (ascii == 72) return 23533; // 'H'
    if (ascii == 83) return 31183; // 'S'
    if (ascii == 86) return 23402; // 'V'
    if (ascii == 82) return 31733; // 'R'
    if (ascii == 71) return 31087; // 'G'
    if (ascii == 66) return 27566; // 'B'
    if (ascii == 58) return 1040;  // ':'
    return 0;                      // ' '
}

// Numeric Place Digit Extractor
int getDigit(float val, int place) {
    float v = abs(val);
    float digit = 0.0;
    if (place == 100)       digit = mod(floor(v / 100.0), 10.0);
    else if (place == 10)   digit = mod(floor(v / 10.0), 10.0);
    else if (place == 1)    digit = mod(floor(v), 10.0);
    else if (place == -1)   digit = mod(floor(v * 10.0), 10.0);
    else if (place == -2)   digit = mod(floor(v * 100.0), 10.0);
    else if (place == -3)   digit = mod(floor(v * 1000.0), 10.0);
    return int(digit) + 48;
}

// Text Generation Engine
int getCharAt(int line, int col, float L, float C, float hLCH, float hHSV, float S, float V, float R, float G, float B) {
    if (line == 0) { // LCH Row 1: Lightness & Hue
        if (col == 0) return 76; // 'L'
        if (col == 1) return getDigit(L, 10);
        if (col == 2) return getDigit(L, 1);
        if (col == 3) return 46; // '.'
        if (col == 4) return getDigit(L, -1);
        if (col == 5) return getDigit(L, -2);
        if (col == 6) return 37; // '%'
        if (col == 7) return 32; // ' '
        if (col == 8) return 72; // 'H'
        if (col == 9) return (hLCH >= 100.0) ? getDigit(hLCH, 100) : 32;
        if (col == 10) return (hLCH >= 10.0) ? getDigit(hLCH, 10) : ((hLCH >= 100.0) ? 48 : 32);
        if (col == 11) return getDigit(hLCH, 1);
        if (col == 12) return 46; // '.'
        if (col == 13) return getDigit(hLCH, -1);
    }
    if (line == 1) { // LCH Row 2: Chroma & Saturation
        if (col == 0) return 67; // 'C'
        if (col == 1) return getDigit(C, 1);
        if (col == 2) return 46; // '.'
        if (col == 3) return getDigit(C, -1);
        if (col == 4) return getDigit(C, -2);
        if (col == 5) return getDigit(C, -3);
        if (col == 6) return 32; // ' '
        if (col == 7) return 32; // ' '
        if (col == 8) return 83; // 'S'
        if (col == 9) return (S >= 10.0) ? getDigit(S, 10) : 32;
        if (col == 10) return getDigit(S, 1);
        if (col == 11) return 46; // '.'
        if (col == 12) return getDigit(S, -1);
        if (col == 13) return 37; // '%'
    }
    if (line == 2) { // HSV Row 3: Hue & Value
        if (col == 0) return 72; // 'H'
        if (col == 1) return (hHSV >= 100.0) ? getDigit(hHSV, 100) : 32;
        if (col == 2) return (hHSV >= 10.0) ? getDigit(hHSV, 10) : ((hHSV >= 100.0) ? 48 : 32);
        if (col == 3) return getDigit(hHSV, 1);
        if (col == 4) return 46; // '.'
        if (col == 5) return getDigit(hHSV, -1);
        if (col == 6) return getDigit(hHSV, -2);
        if (col == 7) return 32; // ' '
        if (col == 8) return 86; // 'V'
        if (V >= 100.0) {
            if (col == 9) return 49;  // '1'
            if (col == 10) return 48; // '0'
            if (col == 11) return 48; // '0'
            if (col == 12) return 46; // '.'
            if (col == 13) return 48; // '0'
        } else {
            if (col == 9) return (V >= 10.0) ? getDigit(V, 10) : 32;
            if (col == 10) return getDigit(V, 1);
            if (col == 11) return 46; // '.'
            if (col == 12) return getDigit(V, -1);
            if (col == 13) return 37; // '%'
        }
    }
    if (line == 3) { // RGB Row 4
        if (col == 0) return 82; // 'R'
        if (col == 1) return (R >= 100.0) ? getDigit(R, 100) : 32;
        if (col == 2) return (R >= 10.0) ? getDigit(R, 10) : ((R >= 100.0) ? 48 : 32);
        if (col == 3) return getDigit(R, 1);
        if (col == 4) return 32; // ' '
        if (col == 5) return 71; // 'G'
        if (col == 6) return (G >= 100.0) ? getDigit(G, 100) : 32;
        if (col == 7) return (G >= 10.0) ? getDigit(G, 10) : ((G >= 100.0) ? 48 : 32);
        if (col == 8) return getDigit(G, 1);
        if (col == 9) return 32; // ' '
        if (col == 10) return 66; // 'B'
        if (col == 11) return (B >= 100.0) ? getDigit(B, 100) : 32;
        if (col == 12) return (B >= 10.0) ? getDigit(B, 10) : ((B >= 100.0) ? 48 : 32);
        if (col == 13) return getDigit(B, 1);
    }
    return 32;
}

// RGB to HSV Conversion Mathematical Block
vec3 rgbToHsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

// CIELCH Structural Color Convertors
vec3 rgbToXyz(vec3 rgb) {
    float r = (rgb.r > 0.04045) ? pow((rgb.r + 0.055) / 1.055, 2.4) : (rgb.r / 12.92);
    float g = (rgb.g > 0.04045) ? pow((rgb.g + 0.055) / 1.055, 2.4) : (rgb.g / 12.92);
    float b = (rgb.b > 0.04045) ? pow((rgb.b + 0.055) / 1.055, 2.4) : (rgb.b / 12.92);
    return vec3(
        r * 0.4124564 + g * 0.3575761 + b * 0.1804375,
        r * 0.2126729 + g * 0.7151522 + b * 0.0721750,
        r * 0.0193339 + g * 0.1191920 + b * 0.9503041
    );
}

vec3 xyzToLab(vec3 xyz) {
    vec3 n = xyz / vec3(0.95047, 1.00000, 1.08883);
    vec3 f = vec3(
        (n.x > 0.008856) ? pow(n.x, 1.0/3.0) : (7.787 * n.x + 16.0/116.0),
        (n.y > 0.008856) ? pow(n.y, 1.0/3.0) : (7.787 * n.y + 16.0/116.0),
        (n.z > 0.008856) ? pow(n.z, 1.0/3.0) : (7.787 * n.z + 16.0/116.0)
    );
    return vec3((116.0 * f.y) - 16.0, 500.0 * (f.x - f.y), 200.0 * (f.y - f.z));
}

void main() {
    vec4 finalColor = texture2D(tDiffuse, vUvScaled);

    // Spatial Box-Averaging over Sample Point Radius
    vec4 sampledTexel = vec4(0.0);
    float totalWeight = 0.0;
    int rad = int(clamp(Sample_Point_Radius, 0.0, 5.0));

    for (int x = -5; x <= 5; x++) {
        for (int y = -5; y <= 5; y++) {
            // FIXED: Removed abs() around integer coordinates
            if (x >= -rad && x <= rad && y >= -rad && y <= rad) {
                sampledTexel += texture2D(tDiffuse, Sample_Point + vec2(float(x), float(y)) / resolution);
                totalWeight += 1.0;
            }
        }
    }
    sampledTexel = (totalWeight > 0.0) ? (sampledTexel / totalWeight) : texture2D(tDiffuse, Sample_Point);
    vec3 rgb = sampledTexel.rgb;

    // Convert Spaces
    vec3 hsv = rgbToHsv(rgb);
    vec3 lab = xyzToLab(rgbToXyz(rgb));
    float hLch = atan(lab.z, lab.y) * 180.0 / 3.14159265;
    vec3 lch = vec3(lab.x, sqrt(lab.y*lab.y + lab.z*lab.z), (hLch < 0.0) ? hLch + 360.0 : hLch);

    // Active Layout Toggles
    bool vis0 = (Show_LCH > 0.5);
    bool vis1 = (Show_LCH > 0.5 || Show_HSV > 0.5);
    bool vis2 = (Show_HSV > 0.5);
    bool vis3 = (Show_RGB > 0.5);

    int numLines = 0;
    int pos0 = -1, pos1 = -1, pos2 = -1, pos3 = -1;
    if (vis0) { pos0 = numLines; numLines++; }
    if (vis1) { pos1 = numLines; numLines++; }
    if (vis2) { pos2 = numLines; numLines++; }
    if (vis3) { pos3 = numLines; numLines++; }

    // Dynamic Layout Dimensions
    float swatchSize = (Show_Swatch > 0.5 && numLines > 0) ? float(numLines * 8 - 3) : 0.0;
    float textStartX = (Show_Swatch > 0.5 && numLines > 0) ? (8.0 + swatchSize) : 4.0;
    float totalWidth = textStartX + 56.0 + 4.0;
    float totalHeight = (numLines > 0) ? float(numLines * 8 - 3) + 8.0 : 8.0;

    // Pixel Coordination Transform
    vec2 localPos = (vUv * resolution - (Sample_Point * resolution + vec2(Offset_X, Offset_Y))) / max(Scale, 0.001);

    // Overlay Circle Visualizer Execution
    if (Show_Circle > 0.5) {
        if (abs(distance(vUv * resolution, Sample_Point * resolution) - Circle_Size) < 1.2) {
            finalColor = vec4(1.0, 0.0, 0.0, 1.0); // Consistent Quality Target Circle
        }
    }

    // UI Panel Layer Assembly
    if (numLines > 0 && localPos.x >= 0.0 && localPos.x <= totalWidth && localPos.y >= 0.0 && localPos.y <= totalHeight) {
        vec4 overlayUi = vec4(0.0, 0.0, 0.0, BG_Opacity / 100.0);

        // Crisp Exterior Outline
        if (localPos.x < 1.0 || localPos.x > totalWidth - 1.0 || localPos.y < 1.0 || localPos.y > totalHeight - 1.0) {
            overlayUi = vec4(1.0, 1.0, 1.0, 1.0);
        }
        // Swatch Square Rendering
        else if (Show_Swatch > 0.5 && localPos.x >= 4.0 && localPos.x <= 4.0 + swatchSize && localPos.y >= 4.0 && localPos.y <= 4.0 + swatchSize) {
            if (abs(localPos.x - 4.0) < 1.0 || abs(localPos.x - (4.0 + swatchSize)) < 1.0 || 
                abs(localPos.y - 4.0) < 1.0 || abs(localPos.y - (4.0 + swatchSize)) < 1.0) {
                overlayUi = vec4(1.0, 1.0, 1.0, 1.0);
            } else {
                overlayUi = vec4(rgb, 1.0);
            }
        }
        // Dynamic Character Mapping Inside Grid Map
        else if (localPos.x >= textStartX && localPos.x <= textStartX + 56.0) {
            float relX = localPos.x - textStartX;
            int col = int(floor(relX / 4.0));
            float charLocalX = mod(relX, 4.0);

            float fromTop = totalHeight - 4.0 - localPos.y;
            int visualLine = int(floor(fromTop / 8.0));
            float charLocalY = 5.0 - mod(fromTop, 8.0);

            if (col >= 0 && col < 14 && charLocalX < 3.0 && visualLine >= 0 && visualLine < numLines && charLocalY >= 0.0 && charLocalY < 5.0) {
                int dataLine = -1;
                int currentVisual = 0;
                if (vis0) { if (currentVisual == visualLine) dataLine = 0; currentVisual++; }
                if (vis1) { if (currentVisual == visualLine) dataLine = 1; currentVisual++; }
                if (vis2) { if (currentVisual == visualLine) dataLine = 2; currentVisual++; }
                if (vis3) { if (currentVisual == visualLine) dataLine = 3; currentVisual++; }

                int ascii = getCharAt(dataLine, col, lch.x, lch.y / 100.0, lch.z, hsv.x * 360.0, hsv.y * 100.0, hsv.z * 100.0, rgb.r * 255.0, rgb.g * 255.0, rgb.b * 255.0);
                if (getBit(getCharFontCode(ascii), int(charLocalX), int(charLocalY)) == 1) {
                    overlayUi = vec4(1.0, 1.0, 1.0, 1.0);
                }
            }
        }
        finalColor = mix(finalColor, vec4(overlayUi.rgb, 1.0), overlayUi.a);
    }
    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/radial-blur.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;

// Custom Properties
uniform float Amount;          
uniform vec2 Center;           
uniform float Type;             // 0: Spin, 1: Zoom
uniform float Antialiasing;     // 0: Low (16), 1: High (64)
uniform float Random_Seed;      

// High-frequency noise function to randomize sampling patterns
float gold_noise(vec2 coord, float seed) {
    return fract(sin(dot(coord.xy + seed, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    vec2 center = Center;
    float aspect = resolution.x / resolution.y;

    // Determine sample count based on Antialiasing toggle
    int samples = (Antialiasing > 0.5) ? 64 : 16;

    // Amount normalization (Matches AE intensity feel)
    float strength = Amount * 0.01;

    vec4 accum = vec4(0.0);

    for (int i = 0; i < 64; i++) {
        if (i >= samples) break;

        // The Random Seed now creates a unique jitter per sample per pixel
        float noise = gold_noise(vUv + float(i), Random_Seed);
        float t = (float(i) + noise) / float(samples);

        vec2 sampleUv;

        if (Type > 0.5) {
            // --- ZOOM BLUR ---
            // Samples move inward/outward relative to center
            float scale = 1.0 - (strength * t);
            sampleUv = center + (vUv - center) * scale;
        } else {
            // --- SPIN BLUR ---
            // Rotation based on distance from center
            float angle = strength * t * 2.0;
            float s = sin(angle);
            float c = cos(angle);

            // Shift to origin, correct aspect, rotate, then shift back
            vec2 rel = vUv - center;
            rel.x *= aspect;

            vec2 rotated;
            rotated.x = rel.x * c - rel.y * s;
            rotated.y = rel.x * s + rel.y * c;

            rotated.x /= aspect;
            sampleUv = rotated + center;
        }

        accum += texture2D(tDiffuse, sampleUv);
    }

    gl_FragColor = accum / float(samples);
}

text./plugins/alipfx/shaders/radial-wipe.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform float Transition_Completion; // 0-100
uniform float Start_Angle;           // degrees
uniform vec2 Wipe_Center;            // normalized
uniform int Wipe;                    // 0=CW,1=CCW,2=Both
uniform float Feather;               // pixels
uniform vec2 resolution;

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    float completion = clamp(Transition_Completion / 100.0, 0.0, 1.0);
    float startAngle = radians(Start_Angle);
    vec2 uv = vUvScaled;
    vec2 center = Wipe_Center;

    vec2 diff = uv - center;
    float angle = atan(diff.y, diff.x);
    if (angle < 0.0) angle += 2.0 * 3.14159265359;

    float sweep = completion * 2.0 * 3.14159265359;

    // Compute angular difference from start
    float delta = angle - startAngle;
    if (delta < 0.0) delta += 2.0 * 3.14159265359;

    // Direction handling
    if (Wipe == 1) { // CCW
        delta = (startAngle - angle);
        if (delta < 0.0) delta += 2.0 * 3.14159265359;
    }

    // For Both directions
    if (Wipe == 2) {
        delta = abs(angle - startAngle);
        if (delta > 3.14159265359) delta = 2.0 * 3.14159265359 - delta;
        sweep *= 0.5;
    }

    // Feather
    float featherNorm = Feather / max(resolution.x, resolution.y);
    float alpha = smoothstep(sweep - featherNorm, sweep, delta);

    gl_FragColor = texel * alpha;
}

text./plugins/alipfx/shaders/reramp.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 resolution;
uniform vec2 uvScale;

// ============================================
// 24 PARAMETERS - ReRamp for Panzoid CM3
// ============================================

// 1. Color Blending: 0=OkLab, 1=OkLCH, 2=Kubelka-Munk, 3=Solid, 4=Linear
uniform float Color_Blending;

// 2. Smoothness
uniform float Smoothness;

// 3-10. Color_1 through Color_8 (8 gradient color stops)
uniform vec3 Color_1;
uniform vec3 Color_2;
uniform vec3 Color_3;
uniform vec3 Color_4;
uniform vec3 Color_5;
uniform vec3 Color_6;
uniform vec3 Color_7;
uniform vec3 Color_8;

// 11. Gradient_Colors - how many colors are active (1-8)
uniform float Gradient_Colors;

// 12. Stop Color - additional color stop for tinting
uniform vec3 Stop_Color;

// 13. Stop Alpha - alpha for stop color blending
uniform float Stop_Alpha;

// 14. Invert: 0=Off, 1=On
uniform float Invert;

// 15. Phase Offset
uniform float Phase_Offset;

// 16. Scale
uniform float Scale;

// 17. Tiling: 0=Repeat, 1=Mirror, 2=Clamp
uniform float Tiling;

// 18. Bias
uniform float Bias;

// 19. Dither
uniform float Dither;

// 20. Quantize: 0=Off, 1=On
uniform float Quantize;

// 21. Steps - number of quantization steps
uniform float Steps;

// 22. Mapping: 0=Lightness, 1=Hue, 2=Saturation, 3=Alpha
uniform float Mapping;

// 23. Source Start
uniform vec3 Source_Start;

// 24. Source End
uniform vec3 Source_End;

// ============================================
// COLOR SPACE CONVERSIONS
// ============================================

vec3 srgbToLinear(vec3 c) {
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}

vec3 linearToSrgb(vec3 c) {
    return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0/2.4)) - 0.055, step(vec3(0.0031308), c));
}

vec3 linearToOklab(vec3 c) {
    float l = 0.8189330101 * c.r + 0.3618667424 * c.g + 0.1288597137 * c.b;
    float m = 0.0329845436 * c.r + 0.9293118715 * c.g + 0.0361456387 * c.b;
    float s = 0.0482003018 * c.r + 0.2643662691 * c.g + 0.6338517070 * c.b;
    l = pow(max(l, 0.0), 1.0/3.0);
    m = pow(max(m, 0.0), 1.0/3.0);
    s = pow(max(s, 0.0), 1.0/3.0);
    return vec3(
        0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
        1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
        0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s
    );
}

vec3 oklabToLinear(vec3 c) {
    float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
    float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
    float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
    l = l * l * l;
    m = m * m * m;
    s = s * s * s;
    return vec3(
        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
    );
}

vec3 linearToOklch(vec3 c) {
    vec3 lab = linearToOklab(c);
    float C = sqrt(lab.y * lab.y + lab.z * lab.z);
    float h = atan(lab.z, lab.y);
    return vec3(lab.x, C, h);
}

vec3 oklchToLinear(vec3 c) {
    float a = c.y * cos(c.z);
    float b = c.y * sin(c.z);
    return oklabToLinear(vec3(c.x, a, b));
}

vec3 kubelkaMunkMix(vec3 c1, vec3 c2, float t) {
    vec3 k1 = (1.0 - c1) / max(c1, vec3(0.001));
    vec3 k2 = (1.0 - c2) / max(c2, vec3(0.001));
    vec3 k = mix(k1, k2, t);
    return 1.0 / (1.0 + k);
}

// ============================================
// COLOR BLENDING
// ============================================

vec3 blendColors(vec3 c1, vec3 c2, float t, int mode) {
    if (mode == 0) {
        vec3 lab1 = linearToOklab(srgbToLinear(c1));
        vec3 lab2 = linearToOklab(srgbToLinear(c2));
        vec3 lab = mix(lab1, lab2, t);
        return linearToSrgb(oklabToLinear(lab));
    }
    else if (mode == 1) {
        vec3 lch1 = linearToOklch(srgbToLinear(c1));
        vec3 lch2 = linearToOklch(srgbToLinear(c2));
        float dh = lch2.z - lch1.z;
        if (dh > 3.14159) dh -= 6.28318;
        if (dh < -3.14159) dh += 6.28318;
        vec3 lch;
        lch.x = mix(lch1.x, lch2.x, t);
        lch.y = mix(lch1.y, lch2.y, t);
        lch.z = lch1.z + dh * t;
        return linearToSrgb(oklchToLinear(lch));
    }
    else if (mode == 2) {
        return kubelkaMunkMix(c1, c2, t);
    }
    else if (mode == 3) {
        return t < 0.5 ? c1 : c2;
    }
    else {
        return mix(c1, c2, t);
    }
}

// ============================================
// SOURCE VALUE EXTRACTION
// ============================================

float getLightness(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

float getHue(vec3 c) {
    float mx = max(max(c.r, c.g), c.b);
    float mn = min(min(c.r, c.g), c.b);
    float d = mx - mn;
    if (d < 0.0001) return 0.0;
    float h;
    if (mx == c.r) {
        h = (c.g - c.b) / d;
        if (h < 0.0) h += 6.0;
    } else if (mx == c.g) {
        h = (c.b - c.r) / d + 2.0;
    } else {
        h = (c.r - c.g) / d + 4.0;
    }
    return h / 6.0;
}

float getSaturation(vec3 c) {
    float mx = max(max(c.r, c.g), c.b);
    float mn = min(min(c.r, c.g), c.b);
    float d = mx - mn;
    return mx > 0.0001 ? d / mx : 0.0;
}

float getSourceValue(vec4 texel, int mapping) {
    if (mapping == 0) return getLightness(texel.rgb);
    if (mapping == 1) return getHue(texel.rgb);
    if (mapping == 2) return getSaturation(texel.rgb);
    return texel.a;
}

// ============================================
// TILING
// ============================================

float applyTiling(float x, int mode) {
    if (mode == 0) {
        return fract(x);
    }
    else if (mode == 1) {
        float f = fract(x);
        float i = floor(x);
        return mod(i, 2.0) < 1.0 ? f : 1.0 - f;
    }
    else {
        return clamp(x, 0.0, 1.0);
    }
}

// ============================================
// BIAS
// ============================================

float applyBias(float x, float b) {
    b = clamp(b, 0.0001, 0.9999);
    return pow(x, log(0.5) / log(b));
}

// ============================================
// RANDOM
// ============================================

float hash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// ============================================
// RAMP EVALUATION
// ============================================

vec3 getColor(int idx) {
    if (idx == 0) return Color_1;
    if (idx == 1) return Color_2;
    if (idx == 2) return Color_3;
    if (idx == 3) return Color_4;
    if (idx == 4) return Color_5;
    if (idx == 5) return Color_6;
    if (idx == 6) return Color_7;
    return Color_8;
}

vec3 evaluateRamp(float t, int blendMode, float smoothness, int numColors) {
    if (numColors <= 1) {
        return Color_1;
    }

    float segments = float(numColors - 1);
    float scaledT = t * segments;
    float fidx = floor(scaledT);
    float localT = fract(scaledT);

    // Apply smoothness
    if (smoothness > 0.0 && blendMode != 3) {
        float smoothT = localT * localT * (3.0 - 2.0 * localT);
        localT = mix(localT, smoothT, smoothness);
    }

    int idx = int(fidx);
    int nextIdx = idx + 1;
    if (nextIdx >= numColors) nextIdx = numColors - 1;

    vec3 c1 = getColor(idx);
    vec3 c2 = getColor(nextIdx);

    return blendColors(c1, c2, localT, blendMode);
}

// ============================================
// MAIN
// ============================================

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    int mapMode = int(Mapping);
    if (mapMode < 0) mapMode = 0;
    if (mapMode > 3) mapMode = 3;

    float sourceVal = getSourceValue(texel, mapMode);

    float srcStart = getLightness(Source_Start);
    float srcEnd = getLightness(Source_End);
    float range = srcEnd - srcStart;
    if (range < 0.0001) range = 0.0001;

    float t = (sourceVal - srcStart) / range;

    if (Invert > 0.5) {
        t = 1.0 - t;
    }

    t += Phase_Offset;

    if (abs(Scale) > 0.001) {
        t *= Scale;
    }

    int tileMode = int(Tiling);
    if (tileMode < 0) tileMode = 0;
    if (tileMode > 2) tileMode = 2;
    t = applyTiling(t, tileMode);

    float biasVal = Bias;
    if (biasVal < 0.001) biasVal = 0.001;
    if (biasVal > 0.999) biasVal = 0.999;
    t = applyBias(clamp(t, 0.0, 1.0), biasVal);

    if (Dither > 0.0) {
        float noise = hash(vUvScaled * resolution + fract(gl_FragCoord.xy * 0.1)) - 0.5;
        t += noise * Dither;
    }

    t = clamp(t, 0.0, 1.0);

    if (Quantize > 0.5 && Steps >= 2.0) {
        float n = Steps;
        if (n < 2.0) n = 2.0;
        t = floor(t * n) / (n - 1.0);
        t = clamp(t, 0.0, 1.0);
    }

    int blendMode = int(Color_Blending);
    if (blendMode < 0) blendMode = 0;
    if (blendMode > 4) blendMode = 4;

    int numColors = int(Gradient_Colors);
    if (numColors < 1) numColors = 1;
    if (numColors > 8) numColors = 8;

    vec3 rampColor = evaluateRamp(t, blendMode, Smoothness, numColors);

    // --- FIXED STOP ALPHA & KEYMAPPER IMPLEMENTATION ---
    float stopA = clamp(Stop_Alpha, 0.0, 1.0);

    // Calculate the color distance match to target the specific color stop range smoothly
    float dist = distance(rampColor, Stop_Color);
    float match = smoothstep(0.15, 0.0, dist); 

    // Key out the targeted color stop by fading alpha and restoring original layer content based on stopA
    vec3 finalColor = mix(rampColor, texel.rgb, match * (1.0 - stopA));
    float finalAlpha = mix(texel.a, texel.a * stopA, match);

    gl_FragColor = vec4(finalColor, finalAlpha);
}

text./plugins/alipfx/shaders/ripple.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

/*
Panzoid custom properties you should create with THESE names:

1. Radius             -> Number (dynamic)
2. Center of Ripple   -> 2D Vector
3. Type of Conversion -> Number (dynamic)  // 0 = Asymmetric, 1 = Symmetric
4. Wave Speed         -> Number (dynamic)
5. Wave Width         -> Number (dynamic)
6. Wave Height        -> Number (dynamic)
7. Ripple Phase       -> Number (dynamic)  // degrees
8. time               -> Number (dynamic)  // seconds

Panzoid converts spaces to underscores in GLSL:
"Center of Ripple"   => Center_of_Ripple
"Type of Conversion" => Type_of_Conversion
"Wave Speed"         => Wave_Speed
"Wave Width"         => Wave_Width
"Wave Height"        => Wave_Height
"Ripple Phase"       => Ripple_Phase
*/

uniform float Radius;
uniform vec2 Center_of_Ripple;
uniform float Type_of_Conversion;
uniform float Wave_Speed;
uniform float Wave_Width;
uniform float Wave_Height;
uniform float Ripple_Phase;
uniform float time;

const float PI  = 3.1415926535897932384626433832795;
const float TAU = 6.2831853071795864769252867665590;

/*
AE-like radius behavior:
- full strength inside Radius
- fades smoothly from Radius to 2*Radius
- no effect beyond 2*Radius
*/
float radiusEnvelope(float distPx, float radiusPx) {
    if (radiusPx <= 0.0) return 0.0;
    return 1.0 - smoothstep(radiusPx, radiusPx * 2.0, distPx);
}

/*
Symmetric mode height field:
Balanced and even.
This creates the broad, uniform pulse-like behavior seen in your symmetric screenshot.
*/
float symmetricHeight(float phase) {
    return sin(phase);
}

/*
Asymmetric mode height field:
Skewed / liquid-like and intentionally not a pure sine.
The positive crest is narrower and stronger, while the negative trough is broader and softer.
This is tuned for the kind of choppy, watery behavior visible in your asymmetric screenshots.
*/
float asymmetricHeight(float phase) {
    float p = phase
            + 0.52 * sin(phase)
            + 0.10 * sin(2.0 * phase - 0.30);

    float s = sin(p);

    float crest  = 1.02 * pow(max(s, 0.0), 1.55);
    float trough = -0.70 * pow(max(-s, 0.0), 0.78);

    float detail = 0.045 * sin(2.0 * phase - 1.05);

    return clamp(crest + trough + detail, -1.0, 1.0);
}

/*
Derivative / slope via finite difference.
This is the key difference from v1:
we distort by the wave slope instead of the raw wave height,
which makes the result look much more like refractive ripple rings.
*/
float symmetricSlope(float phase) {
    return cos(phase);
}

float asymmetricSlope(float phase) {
    float eps = 0.03;
    float a = asymmetricHeight(phase - eps);
    float b = asymmetricHeight(phase + eps);
    return (b - a) / (2.0 * eps);
}

void main() {
    // Current fragment in pixel space
    vec2 fragPx = vUv * resolution;

    // AE-style top-left center coordinates
    vec2 centerPx = vec2(
        Center_of_Ripple.x,
        resolution.y - Center_of_Ripple.y
    );

    vec2 delta = fragPx - centerPx;
    float distPx = length(delta);

    // Safe radial direction
    vec2 dir = delta / max(distPx, 1e-6);

    // Envelope from Radius
    float env = radiusEnvelope(distPx, Radius);

    // Wave width in pixels
    float widthPx = max(Wave_Width, 1e-4);

    // Ripple Phase is treated like AE degrees
    float phaseCycles = Ripple_Phase / 360.0;

    // Traveling radial phase
    float phase = TAU * ((distPx / widthPx) - (Wave_Speed * time) + phaseCycles);

    // Height fields
    float hSym  = symmetricHeight(phase);
    float hAsym = asymmetricHeight(phase);

    // Slopes (refraction-like behavior)
    float sSym  = symmetricSlope(phase);
    float sAsym = asymmetricSlope(phase);

    // 0 = Asymmetric, 1 = Symmetric
    float useSym = step(0.5, Type_of_Conversion);

    // Blend height and slope based on conversion type
    float heightField = mix(hAsym, hSym, useSym);
    float slopeField  = mix(sAsym, sSym, useSym);

    /*
    V2 displacement model:
    - main motion comes from slopeField (refraction-like)
    - small contribution from heightField keeps the ripple from looking too "flat"
    - symmetric mode is intentionally smoother / broader
    - asymmetric mode is intentionally choppier / denser
    */

    float slopeGain  = mix(0.95, 0.72, useSym);
    float heightGain = mix(0.18, 0.10, useSym);

    float displacementPx =
        Wave_Height * env * (slopeField * slopeGain + heightField * heightGain);

    // Radial displacement
    vec2 displacedPx = fragPx + dir * displacementPx;

    // Convert back to buffer UV space for Panzoid sampling
    vec2 sampleUv = (displacedPx / resolution) * uvScale;

    // Clamp to avoid sampling outside the source buffer
    sampleUv = clamp(sampleUv, vec2(0.0), uvScale);

    gl_FragColor = texture2D(tDiffuse, sampleUv);
}

text./plugins/alipfx/shaders/risograph.glsl:
precision highp float;
precision highp int;

// Panzoid Built-in Uniforms
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// 9 Custom Properties (Configured as Floats / Colors)
uniform float Preset;
uniform vec3 Dark_Ink;
uniform vec3 Light_Ink;
uniform vec3 Paper;
uniform float Effect_Intensity;
uniform float Tone_Lift;
uniform float Halftone_Size;
uniform float Misregister;
uniform float Print_Roughness;

// Pseudo-random noise generator for organic print texture
float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

// Halftone screen generator function
float halftoneScreen(vec2 uv, float scale, float angle, float intensity) {
    float s = sin(angle);
    float c = cos(angle);
    vec2 rotUv = vec2(uv.x * c - uv.y * s, uv.x * s + uv.y * c);

    vec2 st = rotUv * scale;
    vec2 f = fract(st) - 0.5;
    float dist = length(f);

    // Smooth thresholding creates clean anti-aliased print dots
    float radius = intensity * 0.7071;
    return smoothstep(radius + 0.04, radius - 0.04, dist);
}

void main() {
    // Sample the source pixel
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // Initialize color channels with Custom parameter values
    vec3 darkColor = Dark_Ink;
    vec3 lightColor = Light_Ink;
    vec3 paperColor = Paper;

    // 1:1 Vayce.app Palette Presets Map
    float p = floor(Preset + 0.5);
    if (p == 1.0) {         // Fluoro Pink / Blue
        darkColor = vec3(0.137, 0.341, 1.0);
        lightColor = vec3(1.0, 0.282, 0.722);
        paperColor = vec3(0.973, 0.945, 0.890);
    } else if (p == 2.0) {  // Sunflower / Black
        darkColor = vec3(0.067, 0.067, 0.067);
        lightColor = vec3(1.0, 0.694, 0.0);
        paperColor = vec3(0.969, 0.937, 0.875);
    } else if (p == 3.0) {  // Aqua / Red
        darkColor = vec3(0.878, 0.294, 0.204);
        lightColor = vec3(0.157, 0.827, 0.761);
        paperColor = vec3(0.969, 0.945, 0.910);
    } else if (p == 4.0) {  // Purple / Kelly Green
        darkColor = vec3(0.353, 0.216, 1.0);
        lightColor = vec3(0.275, 0.780, 0.259);
        paperColor = vec3(0.965, 0.945, 0.906);
    } else if (p == 5.0) {  // Teal / Orange
        darkColor = vec3(0.063, 0.314, 0.341);
        lightColor = vec3(1.0, 0.416, 0.153);
        paperColor = vec3(0.973, 0.941, 0.878);
    } else if (p == 6.0) {  // Navy / Coral
        darkColor = vec3(0.094, 0.165, 0.341);
        lightColor = vec3(1.0, 0.420, 0.420);
        paperColor = vec3(0.984, 0.941, 0.902);
    } else if (p == 7.0) {  // Forest / Warm Red
        darkColor = vec3(0.078, 0.294, 0.208);
        lightColor = vec3(0.859, 0.294, 0.224);
        paperColor = vec3(0.961, 0.937, 0.890);
    } else if (p == 8.0) {  // Violet / Sun
        darkColor = vec3(0.325, 0.200, 0.843);
        lightColor = vec3(1.0, 0.788, 0.200);
        paperColor = vec3(0.984, 0.945, 0.898);
    }

    // Apply layer misregistration offsets
    vec2 misregVec = vec2(0.006, 0.004) * Misregister;
    vec2 uvDark = vUvScaled - misregVec;
    vec2 uvLight = vUvScaled + misregVec;

    // Separate ink layers and evaluate luminance
    vec4 texDark = texture2D(tDiffuse, clamp(uvDark, 0.0, 1.0));
    vec4 texLight = texture2D(tDiffuse, clamp(uvLight, 0.0, 1.0));

    float lumDark = dot(texDark.rgb, vec3(0.299, 0.587, 0.114));
    float lumLight = dot(texLight.rgb, vec3(0.299, 0.587, 0.114));

    // Generate high-frequency noise from Print Roughness
    float noise = rand(vUvScaled * resolution) * 2.0 - 1.0;
    float grain = noise * Print_Roughness * 0.25;

    // Calculate dynamic ink placement thresholds mapped to Tone Lift
    // Dark ink targets the shadows
    float inkDark = clamp((1.0 - lumDark) - Tone_Lift * 0.6 + grain * 0.4, 0.0, 1.0);

    // INVERTED FIX: Light ink targets the mid-to-bright areas, but preserves absolute whites as paper
    float rawInkLight = clamp(lumLight * 1.5 - 0.2 - Tone_Lift * 0.3, 0.0, 1.0);
    float whiteMask = smoothstep(0.85, 0.98, lumLight);
    float inkLight = clamp(mix(rawInkLight, 0.0, whiteMask) + grain * 0.4, 0.0, 1.0);

    // Dynamic dot scale mapping (higher value = chunkier, larger print screen dots)
    float aspect = resolution.x / resolution.y;
    vec2 aspectUv = vUvScaled * vec2(aspect, 1.0);
    float frequency = 160.0 / (0.02 + Halftone_Size * 4.5);

    // Compute angled screens (45° and 15°) to prevent modern moiré patterns
    float dotDark = halftoneScreen(aspectUv, frequency, 0.7854, inkDark);
    float dotLight = halftoneScreen(aspectUv, frequency, 0.2618, inkLight);

    // Layer ink distributions sequentially onto the textured paper stock background
    vec3 paperComposite = paperColor + vec3(grain * 0.03);
    vec3 mixedPass = mix(paperComposite, lightColor, dotLight);
    vec3 finalColor = mix(mixedPass, darkColor, dotDark);

    // Apply overall effect intensity slider overlay match
    gl_FragColor = vec4(mix(texel.rgb, finalColor, Effect_Intensity), texel.a);
}

text./plugins/alipfx/shaders/s-edgecolorize.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

// Panzoid properties
uniform float Edge_Smooth;       // sigma-like blur amount (in pixels)
uniform float Subpixel_Smooth;   // 0 or 1
uniform float Brightness;        // >= 0
uniform float Rotate_Colors;     // degrees

uniform vec3 Background;
uniform vec3 Top;
uniform vec3 Right;
uniform vec3 Bottom;
uniform vec3 Left;

// ---- color management helpers (important for Sapphire-like look) ----
vec3 toLinear(vec3 c) { return pow(max(c, 0.0), vec3(2.2)); }
vec3 toGamma(vec3 c)  { return pow(max(c, 0.0), vec3(1.0/2.2)); }

float lumaLin(vec3 lin) {
  return dot(lin, vec3(0.2126, 0.7152, 0.0722));
}

vec2 rot2(vec2 v, float deg) {
  float a = radians(deg);
  float s = sin(a), c = cos(a);
  return vec2(c*v.x - s*v.y, s*v.x + c*v.y);
}

// ---- Gaussian-ish 9-tap blur of luminance using sigma (Edge Smooth) ----
// Uses center + 4 taps at 1px + 4 taps at 2px (fast, stable, good “Sapphire-ish” smoothing)
float blurLuma(vec2 uv, float sigmaPx) {
  vec2 px = 1.0 / resolution;

  vec3 cLin = toLinear(texture2D(tDiffuse, uv).rgb);
  float c = lumaLin(cLin);

  if (sigmaPx <= 0.001) return c;

  float s = max(sigmaPx, 0.001);

  // Gaussian weights for radius 1 and 2 pixels
  float w0 = 1.0;
  float w1 = exp(-(1.0*1.0) / (2.0*s*s));
  float w2 = exp(-(2.0*2.0) / (2.0*s*s));

  float sum = c * w0;
  float wsum = w0;

  // radius 1
  vec2 o1 = px * 1.0;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2( o1.x, 0.0)).rgb)) * w1;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2(-o1.x, 0.0)).rgb)) * w1;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2(0.0,  o1.y)).rgb)) * w1;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2(0.0, -o1.y)).rgb)) * w1;
  wsum += 4.0 * w1;

  // radius 2
  vec2 o2 = px * 2.0;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2( o2.x, 0.0)).rgb)) * w2;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2(-o2.x, 0.0)).rgb)) * w2;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2(0.0,  o2.y)).rgb)) * w2;
  sum += lumaLin(toLinear(texture2D(tDiffuse, uv + vec2(0.0, -o2.y)).rgb)) * w2;
  wsum += 4.0 * w2;

  return sum / wsum;
}

// ---- signed derivatives of blurred luminance ----
// step grows a little with sigma so Edge Smooth also “thickens” edges like Sapphire
vec2 deriv(vec2 uv, float sigmaPx) {
  vec2 px = 1.0 / resolution;

  float stepPx = 1.0 + 0.35 * clamp(sigmaPx, 0.0, 50.0);
  vec2 st = px * stepPx;

  float Lp = blurLuma(uv + vec2(st.x, 0.0), sigmaPx);
  float Ln = blurLuma(uv - vec2(st.x, 0.0), sigmaPx);
  float Up = blurLuma(uv + vec2(0.0, st.y), sigmaPx);
  float Un = blurLuma(uv - vec2(0.0, st.y), sigmaPx);

  // central difference (signed)
  return vec2(Lp - Ln, Up - Un);
}

// ---- subpixel smoothing (reduces shimmer) ----
vec2 derivSubpixel(vec2 uv, float sigmaPx, float enabled) {
  if (enabled < 0.5 || sigmaPx <= 0.0) return deriv(uv, sigmaPx);

  vec2 px = 1.0 / resolution;
  vec2 j = px * 0.35;

  vec2 d0 = deriv(uv + vec2(-j.x, -j.y), sigmaPx);
  vec2 d1 = deriv(uv + vec2( j.x, -j.y), sigmaPx);
  vec2 d2 = deriv(uv + vec2(-j.x,  j.y), sigmaPx);
  vec2 d3 = deriv(uv + vec2( j.x,  j.y), sigmaPx);

  return 0.25 * (d0 + d1 + d2 + d3);
}

void main() {
  float sigma = clamp(Edge_Smooth, 0.0, 50.0);

  // blurred derivatives
  vec2 d = derivSubpixel(vUvScaled, sigma, Subpixel_Smooth);

  // rotate mapping (Rotate Colors)
  d = rot2(d, Rotate_Colors);

  // directional energies (Sapphire-like split)
  float eR = max( d.x, 0.0);
  float eL = max(-d.x, 0.0);
  float eT = max( d.y, 0.0);
  float eB = max(-d.y, 0.0);

  float eSum = eR + eL + eT + eB;

  // --- Sapphire-ish edge alpha curve ---
  // Auto-normalize: larger sigma reduces derivative magnitude; compensate.
  // Also suppress tiny texture edges by using a soft knee.
  float norm = (0.06 + 0.012 * sigma);   // tuned so sigma~5 behaves like Sapphire-ish thickness
  float x = eSum / max(norm, 1e-6);

  // Soft knee + exponential roll-in to get “rim” look (not thin white lines)
  float a = 1.0 - exp(-x);
  a = smoothstep(0.10, 0.95, a);

  // Directional color blend (diagonals blend smoothly)
  float n = max(eSum, 1e-6);
  vec3 dirCol =
      Right  * (eR / n) +
      Left   * (eL / n) +
      Top    * (eT / n) +
      Bottom * (eB / n);

  vec3 edgeCol = dirCol * max(Brightness, 0.0);

  // Composite edges over Background (matches AE look in your screenshot)
  vec3 outLin = toLinear(Background) + toLinear(edgeCol) * a;

  // Gentle highlight compression to avoid harsh clipping
  outLin = outLin / (1.0 + outLin);

  vec3 outRgb = toGamma(outLin);

  gl_FragColor = vec4(clamp(outRgb, 0.0, 1.0), 1.0);
}

text./plugins/alipfx/shaders/s-glint.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform float Brightness;
uniform float Hue_Shift;
uniform vec3 Scale_Colors;
uniform float Brightness_X;
uniform float Brightness_Y;
uniform float Brightness_Diag1;
uniform float Brightness_Diag2;
uniform float Threshold;
uniform vec3 Threshold_Add_Color;
uniform float Threshold_Blur;
uniform float Size;
uniform float Size_X;
uniform float Size_Y;
uniform float Size_Diag1;
uniform float Size_Diag2;
uniform float Size_Red;
uniform float Size_Green;
uniform float Size_Blue;
uniform float Blur_Glint;
uniform float Affect_Alpha;
uniform float Glint_From_Alpha;
uniform float Glint_Under_Source;
uniform float Source_Opacity;
uniform float Bg_Brightness;

// Helper: Convert RGB to HSV for Hue Shifting
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

// Helper: Convert HSV back to RGB
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Generates the highlight mask based on threshold
vec3 getHighlight(vec2 uv) {
    vec4 col = texture2D(tDiffuse, uv);

    // Simulate Threshold Blur via localized sampling
    if (Threshold_Blur > 0.0) {
        vec2 bOff = (Threshold_Blur / resolution) * uvScale * 1.5;
        col += texture2D(tDiffuse, uv + vec2(bOff.x, 0.0));
        col += texture2D(tDiffuse, uv - vec2(bOff.x, 0.0));
        col += texture2D(tDiffuse, uv + vec2(0.0, bOff.y));
        col += texture2D(tDiffuse, uv - vec2(0.0, bOff.y));
        col *= 0.2; 
    }

    vec3 highlight = col.rgb;

    if (Glint_From_Alpha > 0.5) {
        highlight = vec3(col.a);
    }

    // Apply Threshold & Add Color Penalty
    highlight.r = max(0.0, highlight.r - (Threshold + Threshold_Add_Color.r));
    highlight.g = max(0.0, highlight.g - (Threshold + Threshold_Add_Color.g));
    highlight.b = max(0.0, highlight.b - (Threshold + Threshold_Add_Color.b));

    return highlight;
}

// Core Raymarching Function
vec3 gatherRays(vec2 uv, vec2 dir, float szMul, float brMul) {
    vec3 acc = vec3(0.0);
    float baseSize = Size * szMul;

    if (baseSize <= 0.001 || brMul <= 0.001) return acc;

    // Increased steps so large size values (like 480) create smooth, solid rays
    const int STEPS = 48; 
    float fSteps = float(STEPS);
    vec2 px = 1.0 / resolution;

    // Treat Size exactly as it is (pixels/radius) without the artificial multiplier
    float maxDist = baseSize * 1.5; // Slight bump to match AE's screen-space scaling

    for(int i = 1; i <= STEPS; i++) {
        float t = float(i) / fSteps;

        vec2 offset = dir * (t * maxDist) * px * uvScale;
        vec2 perp = vec2(-dir.y, dir.x) * (Blur_Glint * t * 4.0) * px * uvScale;

        vec3 hP = getHighlight(uv + offset + perp);
        vec3 hM = getHighlight(uv - offset - perp);

        float wR = max(0.0, 1.0 - (t / max(0.001, Size_Red)));
        float wG = max(0.0, 1.0 - (t / max(0.001, Size_Green)));
        float wB = max(0.0, 1.0 - (t / max(0.001, Size_Blue)));

        float falloff = pow(1.0 - t, 2.0);

        acc.r += (hP.r + hM.r) * wR * falloff;
        acc.g += (hP.g + hM.g) * wG * falloff;
        acc.b += (hP.b + hM.b) * wB * falloff;
    }

    // Multiplier adjusted so the rays punch through nicely at high sample counts
    return (acc / fSteps) * brMul * 4.0; 
}

void main() {
    vec2 dirX  = vec2(1.0, 0.0);
    vec2 dirY  = vec2(0.0, 1.0);
    vec2 dirD1 = vec2(0.7071, -0.7071);
    vec2 dirD2 = vec2(0.7071, 0.7071); 

    vec3 glintColor = vec3(0.0);
    glintColor += gatherRays(vUvScaled, dirX, Size_X, Brightness_X);
    glintColor += gatherRays(vUvScaled, dirY, Size_Y, Brightness_Y);
    glintColor += gatherRays(vUvScaled, dirD1, Size_Diag1, Brightness_Diag1);
    glintColor += gatherRays(vUvScaled, dirD2, Size_Diag2, Brightness_Diag2);

    glintColor *= Brightness * Scale_Colors;

    if (abs(Hue_Shift) > 0.001) {
        vec3 hsv = rgb2hsv(glintColor);
        hsv.x = fract(hsv.x + Hue_Shift); 
        glintColor = hsv2rgb(hsv);
    }

    float maxColor = max(max(glintColor.r, glintColor.g), glintColor.b);
    float computedAlpha = clamp(maxColor * Affect_Alpha, 0.0, 1.0);
    vec4 finalGlint = vec4(glintColor, computedAlpha);

    vec4 src = texture2D(tDiffuse, vUvScaled);
    vec3 bgCol = src.rgb * Bg_Brightness;
    float sOpac = Source_Opacity;

    vec4 outColor = vec4(0.0);

    if (Glint_Under_Source > 0.5) {
        vec3 under = bgCol + finalGlint.rgb * (1.0 - src.a); 
        outColor.rgb = mix(under, src.rgb * Bg_Brightness, src.a * sOpac);
        outColor.a = max(src.a * sOpac, finalGlint.a);
    } else {
        outColor.rgb = (bgCol * sOpac) + finalGlint.rgb;
        outColor.a = clamp((src.a * sOpac) + finalGlint.a, 0.0, 1.0);
    }

    gl_FragColor = outColor;
}

text./plugins/alipfx/shaders/s-glow.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// ===== S_Glow-style controls =====
uniform float Brightness;
uniform vec3  Color;
uniform float Threshold;
uniform vec3  Threshold_Add_Color;
uniform float Glow_Width;
uniform float Width_X;
uniform float Width_Y;
uniform float Width_Red;
uniform float Width_Green;
uniform float Width_Blue;
uniform float Subpixel;
uniform float Show;              // 0=Result, 1=Threshold
uniform float Combine;           // 0=Mult, 1=Add, 2=Screen, 3=Difference, 4=Overlay
uniform float Edge_Mode;         // 0=Transparent, 1=Reflect
uniform float Affect_Alpha;
uniform float Glow_From_Alpha;
uniform float Glow_Under_Source;
uniform float Source_Opacity;

// ===== Atmosphere =====
uniform float Atmosphere_Amp;
uniform float Atmosphere_Freq;
uniform float Atmosphere_Detail;
uniform float Atmosphere_Seed;
uniform float Atmosphere_Speed;
uniform float time;

// ------------------------------------------------------------

float saturate(float x) {
    return clamp(x, 0.0, 1.0);
}

vec3 saturate3(vec3 x) {
    return clamp(x, 0.0, 1.0);
}

float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

bool outOfBounds(vec2 uv) {
    return (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0);
}

float mirrorCoord(float x) {
    x = mod(x, 2.0);
    return (x <= 1.0) ? x : (2.0 - x);
}

vec2 reflect01(vec2 uv) {
    return vec2(mirrorCoord(uv.x), mirrorCoord(uv.y));
}

vec4 sampleSource(vec2 uv) {
    if (Edge_Mode < 0.5) {
        if (outOfBounds(uv)) return vec4(0.0);
        return texture2D(tDiffuse, uv * uvScale);
    } else {
        vec2 ruv = reflect01(uv);
        return texture2D(tDiffuse, ruv * uvScale);
    }
}

// ------------------------------------------------------------
// Threshold seed generation
// ------------------------------------------------------------
vec3 glowSeedFromSource(vec4 src) {
    float gf = saturate(Glow_From_Alpha);

    vec3 thr = clamp(vec3(Threshold) + Threshold_Add_Color, 0.0, 0.999);
    vec3 rgbSeed = max(src.rgb - thr, 0.0) / max(vec3(1.0) - thr, vec3(1e-5));

    float aSeed = max(src.a - Threshold, 0.0) / max(1.0 - Threshold, 1e-5);
    vec3 alphaSeed = vec3(aSeed);

    return mix(rgbSeed, alphaSeed, gf);
}

float thresholdViewValue(vec4 src) {
    return saturate(luma(glowSeedFromSource(src)));
}

// ------------------------------------------------------------
// Atmosphere noise
// ------------------------------------------------------------
float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p, float detail) {
    float v = 0.0;
    float a = 0.5;
    float gain = mix(0.35, 0.6, saturate(detail));
    float lacunarity = mix(1.8, 2.5, saturate(detail));

    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p = p * lacunarity + vec2(17.13, 31.71);
        a *= gain;
    }

    return v;
}

float atmosphereFactor(vec2 uv) {
    if (Atmosphere_Amp <= 0.0) return 1.0;

    float t = time * Atmosphere_Speed * 0.15;
    vec2 seedOffset = vec2(Atmosphere_Seed * 37.17, Atmosphere_Seed * 91.73);

    vec2 p = uv * max(Atmosphere_Freq, 0.0001) * 3.0;
    p += seedOffset;
    p += vec2(t, -t * 0.77);

    float baseN = fbm(p, Atmosphere_Detail);
    float fineN = fbm(p * mix(1.6, 3.4, saturate(Atmosphere_Detail)) + 11.7, 1.0);
    float n = mix(baseN, fineN, saturate(Atmosphere_Detail));

    float f = 1.0 + Atmosphere_Amp * ((n - 0.5) * 2.0);
    return max(f, 0.0);
}

// ------------------------------------------------------------
// Blend / combine modes
// ------------------------------------------------------------
vec3 blendMult(vec3 base, vec3 glow) {
    return base * glow;
}

vec3 blendAdd(vec3 base, vec3 glow) {
    return base + glow;
}

vec3 blendScreen(vec3 base, vec3 glow) {
    return 1.0 - (1.0 - base) * (1.0 - glow);
}

vec3 blendDifference(vec3 base, vec3 glow) {
    return abs(base - glow);
}

vec3 blendOverlay(vec3 base, vec3 glow) {
    vec3 low  = 2.0 * base * glow;
    vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - glow);
    return mix(low, high, step(vec3(0.5), base));
}

vec3 applyCombine(vec3 base, vec3 glow) {
    if (Combine < 0.5) return blendMult(base, glow);
    if (Combine < 1.5) return blendAdd(base, glow);
    if (Combine < 2.5) return blendScreen(base, glow);
    if (Combine < 3.5) return blendDifference(base, glow);
    return blendOverlay(base, glow);
}

// ------------------------------------------------------------
// Multi-direction blur with per-channel width control
// ------------------------------------------------------------
vec3 computeGlow(vec2 uv) {
    vec2 px = 1.0 / max(resolution, vec2(1.0));
    float baseRadius = max(Glow_Width, 0.0);

    vec2 radR = px * baseRadius * vec2(max(Width_X * Width_Red,   0.0), max(Width_Y * Width_Red,   0.0));
    vec2 radG = px * baseRadius * vec2(max(Width_X * Width_Green, 0.0), max(Width_Y * Width_Green, 0.0));
    vec2 radB = px * baseRadius * vec2(max(Width_X * Width_Blue,  0.0), max(Width_Y * Width_Blue,  0.0));

    vec3 sum = vec3(0.0);
    vec3 wsum = vec3(0.0);

    vec3 seed0 = glowSeedFromSource(sampleSource(uv));
    sum += seed0;
    wsum += vec3(1.0);

    float radialOffset = mix(1.0, 0.5, saturate(Subpixel));

    const int DIRS = 12;
    const int STEPS = 4;

    for (int d = 0; d < DIRS; d++) {
        float ang = (6.28318530718 * float(d)) / float(DIRS);
        vec2 dir = vec2(cos(ang), sin(ang));

        for (int s = 0; s < STEPS; s++) {
            float t = (float(s) + radialOffset) / float(STEPS);
            float w = exp(-4.0 * t * t);

            vec3 seedR = glowSeedFromSource(sampleSource(uv + dir * radR * t));
            vec3 seedG = glowSeedFromSource(sampleSource(uv + dir * radG * t));
            vec3 seedB = glowSeedFromSource(sampleSource(uv + dir * radB * t));

            sum.r += seedR.r * w;
            sum.g += seedG.g * w;
            sum.b += seedB.b * w;

            wsum += vec3(w);
        }
    }

    vec3 blurred = sum / max(wsum, vec3(1e-5));
    vec3 glow = blurred * Color * Brightness;
    glow *= atmosphereFactor(uv);

    return glow;
}

// ------------------------------------------------------------

void main() {
    vec2 uv = vUv;
    vec4 src = sampleSource(uv);

    if (Show > 0.5) {
        float tv = thresholdViewValue(src);
        gl_FragColor = vec4(vec3(tv), 1.0);
        return;
    }

    vec3 glow = computeGlow(uv);

    float srcOpacity = saturate(Source_Opacity);
    float srcAlpha = src.a * srcOpacity;
    vec3 srcVisible = src.rgb * srcOpacity;

    vec3 resultOver = applyCombine(srcVisible, glow);
    vec3 resultUnder = mix(glow, srcVisible, srcAlpha);
    vec3 result = mix(resultOver, resultUnder, saturate(Glow_Under_Source));

    float glowAlpha = max(max(glow.r, glow.g), glow.b) * max(Affect_Alpha, 0.0);
    float outAlpha = max(srcAlpha, saturate(glowAlpha));

    gl_FragColor = vec4(result, outAlpha);
}

text./plugins/alipfx/shaders/s-halftone.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;

/* Panzoid properties (spaces become underscores) */
uniform float Dots;              // 0 = Black, 1 = White
uniform float Dots_Frequency;    // Sapphire-like "frequency", not dots-across-width
uniform float Dots_Angle;        // degrees CCW
uniform float Dots_Rel_Width;    // ellipse stretch
uniform float Dots_Sharpness;    // edge hardness
uniform float Dots_Lighten;      // -1..1
uniform float Smooth_Source;     // preblur amount
uniform vec3  Color1;            // bright
uniform vec3  Color0;            // dark
uniform float Dots_Shift_X;      // pixels
uniform float Dots_Shift_Y;      // pixels

/* --- Helpers --- */

float luma709(vec3 c) {
  // Sapphire docs don't specify exact luma formula; 709 is a close AE-style choice.
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

mat2 rot2(float a) {
  float s = sin(a), c = cos(a);
  return mat2(c, -s, s, c);
}

float safe(float x) { return max(x, 1e-6); }

vec4 blur9(vec2 uv, float radiusPx) {
  // Small 3x3 gaussian-ish blur (WebGL1 safe, no loops needed)
  vec2 px = radiusPx / resolution;
  vec4 c = vec4(0.0);

  c += texture2D(tDiffuse, uv + px * vec2(-1.0, -1.0)) * 1.0;
  c += texture2D(tDiffuse, uv + px * vec2( 0.0, -1.0)) * 2.0;
  c += texture2D(tDiffuse, uv + px * vec2( 1.0, -1.0)) * 1.0;

  c += texture2D(tDiffuse, uv + px * vec2(-1.0,  0.0)) * 2.0;
  c += texture2D(tDiffuse, uv + px * vec2( 0.0,  0.0)) * 4.0;
  c += texture2D(tDiffuse, uv + px * vec2( 1.0,  0.0)) * 2.0;

  c += texture2D(tDiffuse, uv + px * vec2(-1.0,  1.0)) * 1.0;
  c += texture2D(tDiffuse, uv + px * vec2( 0.0,  1.0)) * 2.0;
  c += texture2D(tDiffuse, uv + px * vec2( 1.0,  1.0)) * 1.0;

  return c / 16.0;
}

void main() {
  vec4 src = texture2D(tDiffuse, vUvScaled);

  float freq = max(Dots_Frequency, 0.0);
  if (freq < 0.0001) {
    gl_FragColor = src;
    return;
  }

  // --- Smooth Source (pre-blur before dot sizing) ---
  vec4 smp = src;
  float smoothPx = max(Smooth_Source, 0.0);
  if (smoothPx > 0.0001) {
    smp = blur9(vUvScaled, smoothPx);
  }

  float L = clamp(luma709(smp.rgb), 0.0, 1.0);

  // --- Frequency mapping (Sapphire-like behavior) ---
  // Sapphire docs say "frequency of dots pattern" (default 50), not dots across width. [1](https://borisfx.com/documentation/sapphire/ae/halftone/)[2](https://y-yamazaki.tv/Sapphire_docs/HalfTone.html)
  // Use min dimension so 1920x1080 with freq=50 gives ~89 dots across width (dense like Sapphire).
  float minDim  = min(resolution.x, resolution.y);
  float spacing = max(1.0, minDim / safe(freq));   // pixels per cell
  float halfCell = 0.5 * spacing;

  // Pixel position
  vec2 p = vUvScaled * resolution;

  // Rotate grid about center
  vec2 center = 0.5 * resolution;
  float ang = radians(Dots_Angle);
  vec2 pr = rot2(ang) * (p - center) + center;

  // Shift grid (in pixels, like AE “Dots Shift”) [2](https://y-yamazaki.tv/Sapphire_docs/HalfTone.html)
  pr += vec2(Dots_Shift_X, Dots_Shift_Y);

  // Cell center
  vec2 cell = (floor(pr / spacing) + 0.5) * spacing;

  // Ellipse control
  float rw = max(Dots_Rel_Width, 0.001);
  vec2 d = pr - cell;
  d.x /= rw;
  float dist = length(d); // pixels

  // Polarity: 0=Black, 1=White
  float mode = step(0.5, Dots);

  // Ink coverage: Black mode -> more ink in dark areas; White mode -> more ink in bright areas
  float ink = mix(1.0 - L, L, mode);

  // Lighten bias: increase to lighten result (docs: -1..1) [2](https://y-yamazaki.tv/Sapphire_docs/HalfTone.html)
  ink += mix(-Dots_Lighten, Dots_Lighten, mode);
  ink = clamp(ink, 0.0, 1.0);

  // Radius mapping: sqrt makes dot AREA respond more linearly to tone
  float radius = sqrt(ink) * halfCell;

  // Derivative-free edge softness
  float sharp = max(Dots_Sharpness, 0.001);
  float edgePx = max(1.0, halfCell / (1.0 + 2.0 * sharp));

  float mask = 1.0 - smoothstep(radius - edgePx, radius + edgePx, dist);

  // Duotone colors, swapped for White mode
  vec3 bg = mix(Color1, Color0, mode);
  vec3 fg = mix(Color0, Color1, mode);

  vec3 outRGB = mix(bg, fg, mask);

  gl_FragColor = vec4(outRGB, src.a);
}

text./plugins/alipfx/shaders/s-kaleido.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform float Pattern;
uniform vec2 Center_XY;
uniform float Z_Dist;
uniform float Rotate;
uniform float Inside_Shift_X;
uniform float Inside_Shift_Y;
uniform float Inside_Z_Dist;
uniform float Inside_Rotate;
uniform float Kaleido_Amount;
uniform float Wrap_X;
uniform float Wrap_Y;

varying vec2 vUv;
varying vec2 vUvScaled;

const float PI = 3.14159265358979323846;
const float SQRT3 = 1.7320508075688772;
const float EPS = 1e-5;

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------
vec2 rot2d(vec2 p, float deg)
{
    float a = radians(deg);
    float c = cos(a);
    float s = sin(a);
    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

float repeatTile(float x)
{
    x = fract(x);
    if (x < 0.0) x += 1.0;
    return x;
}

float repeatReflect(float x)
{
    float m = mod(x, 2.0);
    if (m < 0.0) m += 2.0;
    return 1.0 - abs(m - 1.0);
}

float mirrorCentered(float x)
{
    return repeatReflect(x + 0.5) - 0.5;
}

// ------------------------------------------------------------
// Coordinate conversion
// ------------------------------------------------------------
vec2 topLeftPxToUv01(vec2 px)
{
    return vec2(px.x / resolution.x, 1.0 - (px.y / resolution.y));
}

vec4 sampleWrapped01(vec2 uv01)
{
    float u = uv01.x;
    float v = uv01.y;
    bool valid = true;

    // Wrap X
    if (Wrap_X < 0.5)
    {
        if (u < 0.0 || u > 1.0) valid = false;
    }
    else if (Wrap_X < 1.5)
    {
        u = repeatTile(u);
    }
    else
    {
        u = repeatReflect(u);
    }

    // Wrap Y
    if (Wrap_Y < 0.5)
    {
        if (v < 0.0 || v > 1.0) valid = false;
    }
    else if (Wrap_Y < 1.5)
    {
        v = repeatTile(v);
    }
    else
    {
        v = repeatReflect(v);
    }

    if (!valid)
    {
        return vec4(0.0);
    }

    return texture2D(tDiffuse, vec2(u, v) * uvScale);
}

vec4 sampleWrappedTopLeftPx(vec2 px)
{
    return sampleWrapped01(topLeftPxToUv01(px));
}

// ------------------------------------------------------------
// MODE-BY-MODE CALIBRATION
//
// IMPORTANT:
// mirrorPeriod() controls how Z Dist changes repetition density.
// sourceSpan() controls source size inside the mirrors.
// This means Z Dist no longer zooms the source layer directly.
// ------------------------------------------------------------

// Larger mirrorPeriod = fewer repetitions at same Z Dist
float mirrorPeriod(float pattern)
{
    float m = min(resolution.x, resolution.y);

    // Calibrated closer to AE visual density
    if (pattern < 0.5) return m * 0.98; // Triangles
    if (pattern < 1.5) return m * 0.72; // Squares
    if (pattern < 2.5) return m * 0.90; // Diamonds
    return m * 0.68;                    // Oct
}

// Larger sourceSpan = source appears smaller inside tiles
float sourceSpan(float pattern)
{
    float m = min(resolution.x, resolution.y);

    // Decoupled from Z Dist; these are tuned by mode
    if (pattern < 0.5) return m * 1.55; // Triangles
    if (pattern < 1.5) return m * 1.18; // Squares
    if (pattern < 2.5) return m * 1.34; // Diamonds
    return m * 1.52;                    // Oct
}

// Hidden default placement / phase per mode
// This fixes the “origin placement” mismatch.
vec2 placementOffset(float pattern)
{
    if (pattern < 0.5) return vec2( 0.00, -0.08); // Triangles
    if (pattern < 1.5) return vec2( 0.00,  0.00); // Squares
    if (pattern < 2.5) return vec2( 0.00, -0.10); // Diamonds
    return vec2( 0.06,  0.02);                    // Oct
}

// ------------------------------------------------------------
// Fold functions
// ------------------------------------------------------------

// Triangles: equilateral triangle lattice
vec2 foldTriangles(vec2 q)
{
    vec2 uv = vec2(
        q.x - q.y / SQRT3,
        (2.0 * q.y) / SQRT3
    );

    vec2 f = vec2(
        repeatReflect(uv.x),
        repeatReflect(uv.y)
    );

    if (f.x + f.y > 1.0)
    {
        f = vec2(1.0 - f.y, 1.0 - f.x);
    }

    // canonical triangle centroid
    f -= vec2(1.0 / 3.0);

    return vec2(
        f.x + 0.5 * f.y,
        0.5 * SQRT3 * f.y
    );
}

// Squares
vec2 foldSquares(vec2 q)
{
    return vec2(
        mirrorCentered(q.x),
        mirrorCentered(q.y)
    );
}

// Diamonds
vec2 foldDiamonds(vec2 q)
{
    vec2 r = rot2d(q, -45.0);
    r = foldSquares(r);
    return rot2d(r, 45.0);
}

// Oct: square-lattice based right-triangle fold
vec2 foldOct(vec2 q)
{
    vec2 s = foldSquares(q);

    s = abs(s);

    if (s.y > s.x)
    {
        s = s.yx;
    }

    s -= vec2(0.25, 0.125);

    return s;
}

vec2 foldPattern(vec2 q, float pattern)
{
    if (pattern < 0.5) return foldTriangles(q);
    if (pattern < 1.5) return foldSquares(q);
    if (pattern < 2.5) return foldDiamonds(q);
    return foldOct(q);
}

// ------------------------------------------------------------
// Main
// ------------------------------------------------------------
void main()
{
    vec4 original = texture2D(tDiffuse, vUvScaled);

    // exact passthrough at amount = 0
    if (abs(Kaleido_Amount) < EPS)
    {
        gl_FragColor = original;
        return;
    }

    // Current fragment in top-left pixel coordinates
    vec2 fragTopLeftPx = vec2(
        vUv.x * resolution.x,
        (1.0 - vUv.y) * resolution.y
    );

    // Centered space: x right, y up
    vec2 p = vec2(
        fragTopLeftPx.x - Center_XY.x,
        Center_XY.y - fragTopLeftPx.y
    );

    float zMain = max(abs(Z_Dist), EPS);
    float zInside = max(abs(Inside_Z_Dist), EPS);

    float mirrorSize = mirrorPeriod(Pattern);
    float srcSize = sourceSpan(Pattern);

    // Rotate mirror system only
    vec2 mirrorSpace = rot2d(p, -Rotate);

    // --------------------------------------------------------
    // Z Dist affects mirror repetition ONLY
    // --------------------------------------------------------
    vec2 q = mirrorSpace * (zMain / mirrorSize);

    // Fold to mirror domain
    vec2 qFold = foldPattern(q, Pattern);

    // Hidden phase correction
    vec2 local = qFold + placementOffset(Pattern);

    // --------------------------------------------------------
    // Source mapping is DECOUPLED from Z Dist
    // --------------------------------------------------------
    vec2 srcRelK = local * srcSize;

    // Inside Z Dist affects source only
    srcRelK *= zInside;

    // Rotate source under mirrors only
    srcRelK = rot2d(srcRelK, -Inside_Rotate);

    // Shift source under mirrors only
    srcRelK -= vec2(Inside_Shift_X, -Inside_Shift_Y);

    // --------------------------------------------------------
    // Kaleido Amount
    // 0 = original
    // 1 = full effect
    // >1 = overdrive
    // --------------------------------------------------------
    float amt = max(Kaleido_Amount, 0.0);
    vec2 srcRel = p + (srcRelK - p) * amt;

    // Convert back to top-left pixel coordinates
    vec2 srcTopLeftPx = vec2(
        Center_XY.x + srcRel.x,
        Center_XY.y - srcRel.y
    );

    gl_FragColor = sampleWrappedTopLeftPx(srcTopLeftPx);
}

text./plugins/alipfx/shaders/s-kaleidopolar.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUvScaled;

// 8 properties:
uniform vec2  Center_XY;        // AE-style absolute pixels (top-left origin)
uniform float Z_Dist;           // zoom/depth (result scale)
uniform float Rotate;           // degrees
uniform float Stretch_X;        // result stretch
uniform float Stretch_Y;        // result stretch
uniform float Inside_Shift_Y;   // pixels, positive = outward (as you said)
uniform float Angle_Repeats;    // slices
uniform float Kaleido_Amount;   // strength, can be >1

const float PI  = 3.14159265358979323846;
const float TAU = 6.28318530717958647692;

float safeInv(float x) { return 1.0 / max(abs(x), 1e-6); }

void main()
{
  // Base UV in 0..1
  vec2 uv = vUvScaled / uvScale;

  // ---- Center XY (AE pixels, origin TOP-LEFT) -> GL UV origin bottom-left
  vec2 centerUV = vec2(
    Center_XY.x / resolution.x,
    1.0 - (Center_XY.y / resolution.y)
  );

  // Output-space pixel vector from center
  vec2 p = (uv - centerUV) * resolution;

  // ---- Stretch applies to RESULT (output)
  p.x *= safeInv(Stretch_X);
  p.y *= safeInv(Stretch_Y);

  // Polar coords of output
  float r   = length(p);
  float ang = atan(p.y, p.x);          // -PI..PI

  // Rotate the "mirror wheel"
  ang += radians(Rotate);
  ang = mod(ang + TAU, TAU);           // 0..TAU

  // ---- Kaleidoscope sector fold
  float reps = max(Angle_Repeats, 1.0);
  float sector = TAU / reps;
  float halfSector = 0.5 * sector;

  float a = mod(ang, sector);
  a = abs(a - halfSector);             // mirror fold into [0..halfSector]
  float uPolar = a / max(halfSector, 1e-6);  // 0..1

  // ---- Radius normalization base
  // (This is very close to how Sapphire "feels" on 1920x1080. If still off,
  // I’ll give you a 1-line toggle below.)
  float radiusBase = 0.5 * min(resolution.x, resolution.y);

  // ---- Z Dist: >1 = smaller pattern = more repeats (as per your description)
  // ---- Inside Shift Y: positive moves pattern OUTWARD
  // (Outward means increasing shift should push features to larger r, so subtract here.)
  float vPolar = (r * Z_Dist - Inside_Shift_Y) / max(radiusBase, 1e-6);

  // Polar UV that samples the source:
  vec2 uvPolar = vec2(uPolar, vPolar);

  // IMPORTANT: do NOT wrap yet if we want "amount" to extrapolate nicely.
  // We'll warp coords first, then apply wrapping.
  float amt = Kaleido_Amount;

  // ---- This is the key Sapphire-like behavior:
  // Amount blends/extrapolates the UV mapping, not the colors.
  vec2 uvFinal = uv + (uvPolar - uv) * amt;

  // Edge behavior: Sapphire-style tiling (prevents black borders)
  uvFinal = fract(uvFinal);

  // Sample
  gl_FragColor = texture2D(tDiffuse, uvFinal * uvScale);
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

/*
Panzoid custom properties:

uniform vec2 Center_XY;            // pixel coordinates
uniform float Z_Dist;              // 1.0 = neutral
uniform float Slices;              // recommended >= 1.0
uniform float Rotate;              // degrees
uniform float Rotate_Kaleido;      // degrees
uniform float Rotate_Inside;       // degrees
uniform float Rotate_Inside_Speed; // degrees per second
uniform vec2 Shift_Inside;         // pixel offset
uniform float Kaleido_Amount;      // 0 = original, 1 = full, >1 = exaggerated
uniform float Wrap;                // 0 = No, 1 = Tile, 2 = Reflect
uniform float time;                // seconds
*/

uniform vec2 Center_XY;
uniform float Z_Dist;
uniform float Slices;
uniform float Rotate;
uniform float Rotate_Kaleido;
uniform float Rotate_Inside;
uniform float Rotate_Inside_Speed;
uniform vec2 Shift_Inside;
uniform float Kaleido_Amount;
uniform float Wrap;
uniform float time;

const float PI  = 3.1415926535897932384626433832795;
const float TAU = 6.2831853071795864769252867665590;

vec2 rotate2D(vec2 p, float a)
{
    float s = sin(a);
    float c = cos(a);
    return vec2(
        c * p.x - s * p.y,
        s * p.x + c * p.y
    );
}

float degToRad(float d)
{
    return d * PI / 180.0;
}

// Safer reflect repeat over infinite plane
float reflectCoord(float x)
{
    float m = mod(x, 2.0);
    if (m < 0.0) m += 2.0;
    return (m <= 1.0) ? m : (2.0 - m);
}

// Safer tile repeat over infinite plane
float tileCoord(float x)
{
    float m = mod(x, 1.0);
    if (m < 0.0) m += 1.0;
    return m;
}

bool isOutside01(vec2 uv)
{
    return (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0);
}

// Better wrap feel:
// - avoids exact edge hits by clamping inward by half a pixel
// - reflect mode mirrors more cleanly
vec4 sampleSourceBetterWrap(vec2 uv, float wrapMode)
{
    vec2 texel = 0.5 / resolution;

    if (wrapMode < 0.5)
    {
        if (isOutside01(uv))
        {
            return vec4(0.0, 0.0, 0.0, 1.0);
        }

        vec2 clampedUV = clamp(uv, texel, 1.0 - texel);
        return texture2D(tDiffuse, clampedUV * uvScale);
    }
    else if (wrapMode < 1.5)
    {
        vec2 tiledUV = vec2(tileCoord(uv.x), tileCoord(uv.y));
        tiledUV = clamp(tiledUV, texel, 1.0 - texel);
        return texture2D(tDiffuse, tiledUV * uvScale);
    }
    else
    {
        vec2 reflectedUV = vec2(reflectCoord(uv.x), reflectCoord(uv.y));
        reflectedUV = clamp(reflectedUV, texel, 1.0 - texel);
        return texture2D(tDiffuse, reflectedUV * uvScale);
    }
}

// Centered kaleido fold:
// folds around the CENTER of each wedge instead of the wedge edge.
// This tends to produce a cleaner regular polygon center, especially at 6 slices.
float kaleidoFoldCentered(float angle, float slices, float rotateKaleidoRad)
{
    float s = max(slices, 1.0);
    float wedge = TAU / s;
    float halfWedge = wedge * 0.5;

    // rotate mirror layout
    float a = angle - rotateKaleidoRad;

    // center each wedge on 0
    a = mod(a + halfWedge, wedge) - halfWedge;

    // mirror around wedge center axis
    a = abs(a);

    // rotate back
    a += rotateKaleidoRad;

    return a;
}

void main()
{
    // Current output pixel position
    vec2 fragPx = vUv * resolution;

    float safeZ = max(Z_Dist, 0.0001);
    float slices = max(Slices, 1.0);

    float rotResult   = degToRad(Rotate);
    float rotKaleido  = degToRad(Rotate_Kaleido);
    float rotInside   = degToRad(Rotate_Inside + Rotate_Inside_Speed * time);

    // ------------------------------------------------------------
    // 1) Result-space transform
    // ------------------------------------------------------------
    vec2 p = fragPx - Center_XY;

    // Rotate whole result around center
    p = rotate2D(p, -rotResult);

    // Z Dist fix:
    // widen the neutral baseline so Z_Dist = 1.0 is less zoomed in
    p *= (safeZ * 2.0);

    // ------------------------------------------------------------
    // 2) Kaleido mirror folding
    // ------------------------------------------------------------
    float r = length(p);
    float a = atan(p.y, p.x);

    // centered folding improves the center polygon / hexagon look
    float foldedAngle = kaleidoFoldCentered(a, slices, rotKaleido);
    vec2 kaleidoPx = vec2(cos(foldedAngle), sin(foldedAngle)) * r;

    // ------------------------------------------------------------
    // 3) Inside transforms
    // ------------------------------------------------------------
    vec2 srcPx = kaleidoPx;

    // Rotate the source image under the mirrors
    srcPx = rotate2D(srcPx, -rotInside);

    // Keep original Shift Inside behavior unchanged
    srcPx -= Shift_Inside;

    // Back to image pixel space
    srcPx += Center_XY;

    // ------------------------------------------------------------
    // 4) Kaleido Amount
    // ------------------------------------------------------------
    vec2 mixedPx = mix(fragPx, srcPx, Kaleido_Amount);

    vec2 uvFinal = mixedPx / resolution;
    vec4 resultColor = sampleSourceBetterWrap(uvFinal, Wrap);

    gl_FragColor = resultColor;
}

text./plugins/alipfx/shaders/s-shake.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

/* --- Time (see notes above) --- */
uniform float time;

/* --- 42 Parameters --- */
uniform float Style;
uniform float Amplitude;
uniform float Frequency;
uniform float Phase;
uniform float Z_Dist;
uniform float Motion_Blur;
uniform float Mo_Blur_Length;
uniform float Seed;
uniform float Wrap_X;
uniform float Wrap_Y;

uniform float X_Rand_Amp;
uniform float X_Rand_Freq;
uniform float X_Wave_Amp;
uniform float X_Wave_Freq;
uniform float X_Phase;

uniform float Y_Rand_Amp;
uniform float Y_Rand_Freq;
uniform float Y_Wave_Amp;
uniform float Y_Wave_Freq;
uniform float Y_Phase;

uniform float Z_Rand_Amp;
uniform float Z_Rand_Freq;
uniform float Z_Wave_Amp;
uniform float Z_Wave_Freq;
uniform float Z_Phase;

uniform float Tilt_Rand_Amp;
uniform float Tilt_Rand_Freq;
uniform float Tilt_Wave_Amp;
uniform float Tilt_Wave_Freq;
uniform float Tilt_Phase;

uniform float Red_Amplitude;
uniform float Green_Amplitude;
uniform float Blue_Amplitude;
uniform float Red_Phase;
uniform float Green_Phase;
uniform float Blue_Phase;
uniform float RGB_Randomness;
uniform float RGB_Frequency;

uniform float Crop_Left;
uniform float Crop_Right;
uniform float Crop_Top;
uniform float Crop_Bottom;

/* --- Constants --- */
const float PI = 3.14159265358979323846264;

/* Sapphire extra style controls (hardcoded defaults) */
const float TWITCH_STILLNESS = 0.7;     // Sapphire default in Twitchy [1](https://borisfx.com/documentation/sapphire/ae/shake/)
const float TWITCH_FREQ     = 2.0;      // Sapphire default in Twitchy [1](https://borisfx.com/documentation/sapphire/ae/shake/)
const float JUMPY_DRIFT     = 0.3;      // Sapphire default in Jumpy   [1](https://borisfx.com/documentation/sapphire/ae/shake/)
const float JUMPY_CENTER_BIAS = 0.0;    // Sapphire default            [1](https://borisfx.com/documentation/sapphire/ae/shake/)

/* --- Hash / Noise (repeatable, smooth) --- */
float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float noise1(float x) {
  float i = floor(x);
  float f = fract(x);
  float u = f * f * (3.0 - 2.0 * f);
  float a = hash11(i);
  float b = hash11(i + 1.0);
  return mix(a, b, u) * 2.0 - 1.0; // [-1,1]
}

float stepNoise1(float x) {
  return hash11(floor(x)) * 2.0 - 1.0; // [-1,1], no smoothing
}

/* --- Rotation helper --- */
vec2 rot2(vec2 p, float a) {
  float s = sin(a);
  float c = cos(a);
  return vec2(c*p.x - s*p.y, s*p.x + c*p.y);
}

/* --- Wrap helpers (operate within [mn,mx] box) --- */
float wrap1(float x, float mn, float mx, float mode) {
  float r = mx - mn;
  if (r <= 0.0) return mn;

  // 0 = No
  if (mode < 0.5) return x;

  // Tile: 1
  if (mode < 1.5) {
    float t = (x - mn) / r;
    t = fract(t);
    return mn + t * r;
  }

  // Reflect: 2
  float t = (x - mn) / r;
  float m = mod(t, 2.0);
  float tri = 1.0 - abs(m - 1.0); // 0..1..0
  return mn + tri * r;
}

vec2 wrapUV(vec2 uv, vec2 mn, vec2 mx, float modeX, float modeY) {
  return vec2(
    wrap1(uv.x, mn.x, mx.x, modeX),
    wrap1(uv.y, mn.y, mx.y, modeY)
  );
}

bool outsideBox(vec2 uv, vec2 mn, vec2 mx) {
  return (uv.x < mn.x || uv.x > mx.x || uv.y < mn.y || uv.y > mx.y);
}

/* --- Core shake at time t:
      returns vec4(dx_pixels, dy_pixels, rot_radians, zoom_mult_delta)
      zoom_mult_delta is additive (e.g. 0.02 = +2%)
--- */
vec4 shakeBase(float t) {
  float T = t + Phase;

  float baseF = max(0.0, Frequency);

  // Build per-axis time arguments (Sapphire: “time shift” per axis) [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  float tx = T + X_Phase;
  float ty = T + Y_Phase;
  float tz = T + Z_Phase;
  float tt = T + Tilt_Phase;

  // Random “seed” offsets [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  float s = Seed * 19.19 + 7.13;

  // Total freqs: global Frequency scales overall speed; axis freqs shape it. [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  float fxr = baseF * X_Rand_Freq;
  float fyr = baseF * Y_Rand_Freq;
  float fzr = baseF * Z_Rand_Freq;
  float ftr = baseF * Tilt_Rand_Freq;

  float fxw = baseF * X_Wave_Freq;
  float fyw = baseF * Y_Wave_Freq;
  float fzw = baseF * Z_Wave_Freq;
  float ftw = baseF * Tilt_Wave_Freq;

  // Style handling [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  float style = floor(Style + 0.5);

  // NORMAL signals (smooth random + sine wave)
  float nx = noise1(tx * fxr + s + 10.0);
  float ny = noise1(ty * fyr + s + 20.0);
  float nz = noise1(tz * fzr + s + 30.0);
  float nt = noise1(tt * ftr + s + 40.0);

  // WAVES
  float wx = sin(2.0 * PI * (tx * fxw));
  float wy = sin(2.0 * PI * (ty * fyw));
  float wz = sin(2.0 * PI * (tz * fzw));
  float wt = sin(2.0 * PI * (tt * ftw));

  // Twitchy: intermittent bursts [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  if (style > 0.5 && style < 1.5) {
    float period = max(0.0001, TWITCH_FREQ);
    float k = floor(T * period);
    // TWITCH_STILLNESS interpreted as “probability of being active” (matches doc wording) [1](https://borisfx.com/documentation/sapphire/ae/shake/)
    float active = step(hash11(k + s + 99.0), TWITCH_STILLNESS);

    // when inactive -> no shake
    if (active < 0.5) {
      return vec4(0.0);
    }

    // when active -> boost the internal speed a bit (burst feel)
    float boost = 4.0;
    nx = noise1(tx * fxr * boost + s + 10.0);
    ny = noise1(ty * fyr * boost + s + 20.0);
    nz = noise1(tz * fzr * boost + s + 30.0);
    nt = noise1(tt * ftr * boost + s + 40.0);

    wx = sin(2.0 * PI * (tx * fxw * boost));
    wy = sin(2.0 * PI * (ty * fyw * boost));
    wz = sin(2.0 * PI * (tz * fzw * boost));
    wt = sin(2.0 * PI * (tt * ftw * boost));
  }

  // Jumpy: discrete jumps + drift between [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  if (style > 1.5) {
    float jf = max(0.0001, baseF);
    float u = fract(T * jf);
    float i = floor(T * jf);

    // step targets
    float nx0 = stepNoise1(i + s + 10.0);
    float ny0 = stepNoise1(i + s + 20.0);
    float nz0 = stepNoise1(i + s + 30.0);
    float nt0 = stepNoise1(i + s + 40.0);

    float nx1 = stepNoise1(i + 1.0 + s + 10.0);
    float ny1 = stepNoise1(i + 1.0 + s + 20.0);
    float nz1 = stepNoise1(i + 1.0 + s + 30.0);
    float nt1 = stepNoise1(i + 1.0 + s + 40.0);

    // drift controls how much of the interval is spent moving
    float drift = clamp(JUMPY_DRIFT, 0.0, 1.0);
    float w = (drift <= 0.0001) ? 0.0 : clamp(u / drift, 0.0, 1.0);

    nx = mix(nx0, nx1, w);
    ny = mix(ny0, ny1, w);
    nz = mix(nz0, nz1, w);
    nt = mix(nt0, nt1, w);

    // Optional: Center bias default 0 -> no forced recentering [1](https://borisfx.com/documentation/sapphire/ae/shake/)
    // (kept for fidelity, but bias=0 means ignore)
    if (JUMPY_CENTER_BIAS > 0.0001) {
      float b = clamp(JUMPY_CENTER_BIAS, 0.0, 1.0);
      float rec = step(hash11(i + s + 123.4), b);
      nx *= (1.0 - rec);
      ny *= (1.0 - rec);
      nz *= (1.0 - rec);
      nt *= (1.0 - rec);
    }

    // wave component still allowed in Jumpy, but typically minimal
  }

  // Compose displacement (pixels for XY; percent for Z; degrees for tilt)
  float dx = (X_Rand_Amp * nx + X_Wave_Amp * wx) * Amplitude;
  float dy = (Y_Rand_Amp * ny + Y_Wave_Amp * wy) * Amplitude;

  float zoomPct = (Z_Rand_Amp * nz + Z_Wave_Amp * wz) * Amplitude; // interpret as % points
  float rotDeg  = (Tilt_Rand_Amp * nt + Tilt_Wave_Amp * wt) * Amplitude;

  return vec4(dx, dy, radians(rotDeg), zoomPct * 0.01); // zoom as multiplier delta
}


vec2 applyTransform(vec2 uv, vec2 center, vec2 transPx, float rotRad, float scale) {
  // Inverse camera transform, but done in PIXEL SPACE to avoid aspect skew.
  // This makes Tilt match Sapphire much more closely on non-square resolutions. [1](https://panzoid.com/community/official/37192?c=3)[2](https://borisfx.com/documentation/sapphire/ae/shake/)

  // Convert to pixel coordinates around center
  vec2 p = (uv - center) * resolution;

  // Inverse translation (pixels)
  p -= transPx;

  // Inverse rotation (pixel space)
  p = rot2(p, -rotRad);

  // Inverse scale
  p /= max(0.0001, scale);

  // Back to normalized UV
  return (p / resolution) + center;
}

/* Sample with crop + wrap */
vec4 sampleLayer(vec2 uv, vec2 cropMin, vec2 cropMax, float modeX, float modeY) {
  // Wrap happens on crop bounds (matches Sapphire crop behavior) [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  vec2 u = uv;
  if (modeX >= 0.5 || modeY >= 0.5) {
    u = wrapUV(u, cropMin, cropMax, modeX, modeY);
  }

  // If wrap is No and outside -> black [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  if ((modeX < 0.5 || modeY < 0.5) && outsideBox(u, cropMin, cropMax)) {
    return vec4(0.0);
  }

  // Map to buffer UV using uvScale [2](https://panzoid.com/community/official/37192?c=3)
  vec2 bufUv = u * uvScale;
  return texture2D(tDiffuse, bufUv);
}

/* RGB channel shake (extra independent randomness) [1](https://borisfx.com/documentation/sapphire/ae/shake/) */
vec4 renderRGB(vec2 baseUv, vec2 cropMin, vec2 cropMax, vec2 center, vec4 baseShake) {
  // Base transform components
  vec2 trans = baseShake.xy;
  float rot = baseShake.z;

  // Base scale includes Z Dist semantics (distance) [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  float baseScale = 1.0 / max(0.001, Z_Dist);
  float scale = baseScale * (1.0 + baseShake.w);

  // RGB randomness: build per-channel extra shake using its own freq/phase
  float rf = max(0.0, Frequency) * max(0.0, RGB_Frequency);
  float s = Seed * 31.77 + 2.41;

  // Use the Rand amps as scaling basis (as Sapphire doc says) [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  float ax = X_Rand_Amp;
  float ay = Y_Rand_Amp;
  float az = Z_Rand_Amp;
  float at = Tilt_Rand_Amp;

  // Helper to build extra shake for a channel
  // (Different seeds so channels diverge)
  float tR = (time + Phase + Red_Phase)   * rf;
  float tG = (time + Phase + Green_Phase) * rf;
  float tB = (time + Phase + Blue_Phase)  * rf;

  // Extra random components (smooth)
  vec2 eR = vec2(noise1(tR + s + 101.0), noise1(tR + s + 201.0)) * vec2(ax, ay);
  vec2 eG = vec2(noise1(tG + s + 102.0), noise1(tG + s + 202.0)) * vec2(ax, ay);
  vec2 eB = vec2(noise1(tB + s + 103.0), noise1(tB + s + 203.0)) * vec2(ax, ay);

  float rRot = noise1(tR + s + 301.0) * radians(at);
  float gRot = noise1(tG + s + 302.0) * radians(at);
  float bRot = noise1(tB + s + 303.0) * radians(at);

  float rZoom = noise1(tR + s + 401.0) * (az * 0.01);
  float gZoom = noise1(tG + s + 402.0) * (az * 0.01);
  float bZoom = noise1(tB + s + 403.0) * (az * 0.01);

  float k = clamp(RGB_Randomness, 0.0, 1000.0);

  // Channel amplitudes [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  vec2 transR = trans + k * eR * Red_Amplitude;
  vec2 transG = trans + k * eG * Green_Amplitude;
  vec2 transB = trans + k * eB * Blue_Amplitude;

  float rotR = rot + k * rRot * Red_Amplitude;
  float rotG = rot + k * gRot * Green_Amplitude;
  float rotB = rot + k * bRot * Blue_Amplitude;

  float scaleR = scale * (1.0 + k * rZoom * Red_Amplitude);
  float scaleG = scale * (1.0 + k * gZoom * Green_Amplitude);
  float scaleB = scale * (1.0 + k * bZoom * Blue_Amplitude);

  vec2 uvR = applyTransform(baseUv, center, transR, rotR, scaleR);
  vec2 uvG = applyTransform(baseUv, center, transG, rotG, scaleG);
  vec2 uvB = applyTransform(baseUv, center, transB, rotB, scaleB);

  vec4 cR = sampleLayer(uvR, cropMin, cropMax, Wrap_X, Wrap_Y);
  vec4 cG = sampleLayer(uvG, cropMin, cropMax, Wrap_X, Wrap_Y);
  vec4 cB = sampleLayer(uvB, cropMin, cropMax, Wrap_X, Wrap_Y);

  // Recombine channels
  return vec4(cR.r, cG.g, cB.b, (cR.a + cG.a + cB.a) / 3.0);
}

/* Motion blur by multi-sampling along time (synthetic) [1](https://borisfx.com/documentation/sapphire/ae/shake/) */
vec4 renderWithMotionBlur(vec2 baseUv, vec2 cropMin, vec2 cropMax, vec2 center) {
  const int SAMPLES = 8;
  float on = step(0.5, Motion_Blur);
  if (on < 0.5) {
    vec4 sh = shakeBase(time);
    return renderRGB(baseUv, cropMin, cropMax, center, sh);
  }

  // Approx dt; host-independent. If you know your fps, you can tune this.
  float dt = 1.0 / 60.0;
  float len = max(0.0, Mo_Blur_Length);

  vec4 acc = vec4(0.0);
  for (int i = 0; i < SAMPLES; i++) {
    float fi = float(i) / float(SAMPLES - 1);
    float tt = time - fi * dt * len;
    vec4 sh = shakeBase(tt);
    acc += renderRGB(baseUv, cropMin, cropMax, center, sh);
  }
  return acc / float(SAMPLES);
}

void main() {
  // Crop box in normalized input UV space [1](https://borisfx.com/documentation/sapphire/ae/shake/)
  vec2 cropMin = vec2(Crop_Left, Crop_Bottom) / resolution;
  vec2 cropMax = vec2(1.0, 1.0) - vec2(Crop_Right, Crop_Top) / resolution;

  // Remap output uv (0..1) into cropped region
  vec2 uv = vUv;
  vec2 baseUv = mix(cropMin, cropMax, uv);

  // Center of crop region (transform about the visible box)
  vec2 center = (cropMin + cropMax) * 0.5;

  gl_FragColor = renderWithMotionBlur(baseUv, cropMin, cropMax, center);
}

text./plugins/alipfx/shaders/s-shape.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// ===== Custom Panzoid properties =====
uniform vec2 Center_XY;
uniform float Size;
uniform float Rel_Width;
uniform float Rel_Height;
uniform float Points;
uniform float Pointiness;
uniform float Roundness;
uniform float Swirl;
uniform float Rotate;
uniform float Rotate_Pre_Scale;
uniform float Blur;
uniform float Brightness1;
uniform vec3 Color1;
uniform vec3 Color0;
uniform float Offset0;
uniform float Bg_Brightness;
uniform float Combine;

// =====================================

const float PI = 3.1415926535897932384626433832795;
const float TAU = 6.2831853071795864769252867665590;

mat2 rot2(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

float saturate(float x) {
    return clamp(x, 0.0, 1.0);
}

vec3 overlayBlend(vec3 base, vec3 blend) {
    vec3 low  = 2.0 * base * blend;
    vec3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
    return mix(low, high, step(vec3(0.5), base));
}

// Regular polygon radial boundary (exact for pointiness = 1)
float cross2(vec2 a, vec2 b) {
    return a.x * b.y - a.y * b.x;
}

// Exact regular polygon with circumradius = 1
float regularPolygonRadius(float ang, float n) {
    float sector = TAU / n;
    float a = mod(ang + 0.5 * sector, sector) - 0.5 * sector;
    return cos(PI / n) / max(cos(a), 1e-6);
}

// Exact sharp alternating star polygon
float starPolygonRadius(float ang, float n, float innerR) {
    float m = n * 2.0;
    float stepA = TAU / m;

    float a = mod(ang, TAU);
    if (a < 0.0) a += TAU;

    float k = floor(a / stepA);
    float a0 = k * stepA;
    float a1 = (k + 1.0) * stepA;

    float r0 = (mod(k, 2.0) < 0.5) ? 1.0 : innerR;
    float r1 = (mod(k + 1.0, 2.0) < 0.5) ? 1.0 : innerR;

    vec2 v0 = vec2(cos(a0), sin(a0)) * r0;
    vec2 v1 = vec2(cos(a1), sin(a1)) * r1;

    vec2 d = vec2(cos(a), sin(a));
    vec2 e = v1 - v0;

    float denom = cross2(d, e);
    if (abs(denom) < 1e-6) denom = (denom < 0.0) ? -1e-6 : 1e-6;

    float t = cross2(v0, e) / denom;
    return abs(t);
}

// 0 at outer tip, 1 at inner valley
float tipToValleyPhase(float ang, float n) {
    float sector = TAU / n;
    float a = mod(ang + 0.5 * sector, sector) - 0.5 * sector;
    return abs(a) / (0.5 * sector);
}

// Rounded star profile:
// - keeps tip SHARP
// - rounds the inner valley
// - curves the side inward
float roundedStarRadius(float ang, float n, float innerR, float roundness) {
    float x = tipToValleyPhase(ang, n); // 0 tip, 1 valley

    // curve that preserves a sharp tip but softens the valley
    float k = mix(1.0, 3.2, clamp(roundness, 0.0, 1.0));
    float curved = 1.0 - pow(max(0.0, 1.0 - x), k);

    // extra shaping so it looks closer to Sapphire:
    // keep shoulders a bit straighter near the tip, more curvature near valley
    float shaped = mix(x, curved, roundness);

    return mix(1.0, innerR, shaped);
}

// Main S_Shape radial boundary
float shapeBoundaryRadius(float ang, float n, float pointiness, float roundness) {
    n = max(n, 3.0);
    roundness = clamp(roundness, 0.0, 1.0);

    // -----------------------------------
    // Negative pointiness = flower / lobes
    // -----------------------------------
    if (pointiness < 0.0) {
        float amt = -pointiness;
        float c = cos(n * ang);

        // More organic / floral lobe shaping
        float flowerSharp = sign(c) * pow(abs(c), mix(0.45, 1.0, roundness));
        float r = 1.0 + 0.22 * amt * flowerSharp;
        return max(r, 0.001);
    }

    // -----------------------------------
    // 0..1 = circle -> polygon
    // -----------------------------------
    if (pointiness <= 1.0) {
        float rp = regularPolygonRadius(ang, n);
        float p = clamp(pointiness, 0.0, 1.0);

        // Base morph: circle -> polygon
        float r = mix(1.0, rp, p);

        // Roundness only affects this regime when pointiness < 1
        // At pointiness = 1, roundness has no effect
        float softenAmt = (1.0 - p) * roundness;
        r = mix(r, 1.0, softenAmt);

        return r;
    }

    // -----------------------------------
    // >1 = star
    // -----------------------------------
    float starAmt = pointiness - 1.0;
    float innerPoly = cos(PI / n);

    // Controls valley depth; tweak 1.15 if needed
    float innerR = innerPoly / (1.0 + 1.15 * starAmt);
    innerR = clamp(innerR, 0.001, 1.0);

    // Sharp star
    float sharpStar = starPolygonRadius(ang, n, innerR);

    // Rounded Sapphire-like star:
    // sharp outer tip + curved sides + smoother inner valley
    float roundedStar = roundedStarRadius(ang, n, innerR, roundness);

    // Blend from exact star -> curved star by Roundness
    return mix(sharpStar, roundedStar, roundness);
}

// Convert center property into Panzoid screen-space.
// Supports BOTH:
// - Panzoid-style relative center: (0,0) = frame center, +-0.5 ≈ edges
// - AE-style pixel coordinates: if values are larger than ~2, treated as pixels
vec2 getCenterNorm() {
    vec2 c;
    if (max(abs(Center_XY.x), abs(Center_XY.y)) > 2.0) {
        // AE-like pixels from top-left
        c = (Center_XY / resolution - 0.5) * 2.0;
    } else {
        // Panzoid-relative: (0,0)=center, +-0.5 ≈ edges
        c = Center_XY * 2.0;
    }
    return c;
}

void main() {
    vec4 bgTex = texture2D(tDiffuse, vUvScaled);

    // Background brightness
    vec3 bg = bgTex.rgb * max(Bg_Brightness, 0.0);

    // Screen-centered coordinates using height as the reference dimension.
    // y range: [-1,1], x range: [-aspect, aspect]
    float aspect = resolution.x / resolution.y;
    vec2 p = (vUv - vec2(0.5)) * 2.0;

    vec2 center = getCenterNorm();
    p -= center;

    p.x *= aspect;

    // Size is treated like AE-ish pixel radius relative to shorter frame dimension
    float minRes = min(resolution.x, resolution.y);
    float sizeNorm = max(Size, 0.0001) * (2.0 / minRes);

    // Inverse transform pipeline:
    // final = translate(center) * rotate(post) * scale(rel) * rotate(pre) * canonical
    // so for point test:
    // canonical = rotate(-pre) * scale^-1 * rotate(-post) * (p)
    vec2 q = p;
    q = rot2(radians(-Rotate)) * q;
    q.x /= max(Rel_Width,  1e-5);
    q.y /= max(Rel_Height, 1e-5);
    q = rot2(radians(-Rotate_Pre_Scale)) * q;
    q /= sizeNorm;

    // Polar
    float r = length(q);
    float ang = atan(q.y, q.x);

    // Swirl: outer parts rotate more than center
    // Using radial amount in shape-local space
    ang -= Swirl * r;

    float n = clamp(Points, 3.0, 500.0);
    float boundary = shapeBoundaryRadius(ang, n, Pointiness, Roundness);

    // Positive inside
    float edge = boundary - r;

    // Blur in local shape units
    float blurLocal = max(Blur, 0.0) / max(Size, 1.0);
    float aaLocal = 1.25 / max(Size, 1.0);
    float feather = max(blurLocal, aaLocal);

    float shapeAlpha = smoothstep(-feather, feather, edge);

    vec3 fg = Color1 * Brightness1;
    vec3 genBg = Color0 + vec3(Offset0);

    // Generated image from S_Shape itself
    // Outside shape = Color0 + Offset0
    // Inside shape  = Color1 * Brightness1
    vec3 generated = mix(genBg, fg, shapeAlpha);

    int mode = int(floor(Combine + 0.5));

    vec3 outRgb;
    float outA;

    // 0 = Shape Only
    if (mode == 0) {
        outRgb = fg;
        outA = shapeAlpha;
    }
    // 1 = Mult
    else if (mode == 1) {
        outRgb = bg * generated;
        outA = 1.0;
    }
    // 2 = Add
    else if (mode == 2) {
        outRgb = bg + generated;
        outA = 1.0;
    }
    // 3 = Screen
    else if (mode == 3) {
        outRgb = 1.0 - (1.0 - bg) * (1.0 - generated);
        outA = 1.0;
    }
    // 4 = Difference
    else if (mode == 4) {
        outRgb = abs(bg - generated);
        outA = 1.0;
    }
    // 5 = Overlay
    else if (mode == 5) {
        outRgb = overlayBlend(bg, generated);
        outA = 1.0;
    }
    // 6 = Over
    else {
        // In Sapphire-style "render image over background",
        // generated image is treated as the rendered layer.
        // If you want transparent outside area, use Combine = 0.
        outRgb = generated;
        outA = 1.0;
    }

    gl_FragColor = vec4(outRgb, outA);
}

text./plugins/alipfx/shaders/s-wipeblobs.glsl:
precision highp float;
precision highp int;

// Built-in Panzoid Uniforms & Varyings
uniform sampler2D tDiffuse;
varying vec2 vUv;
varying vec2 vUvScaled;
uniform vec2 resolution;
uniform float time;

// Sapphire S_WipeBlobs Parameters (No Background Layer)
uniform float Transition_Dir;
uniform float Auto_Trans;
uniform float Wipe_Percent;
uniform float Edge_Softness;
uniform float Frequency;
uniform float Rel_Width;
uniform float Octaves;
uniform float Seed;
uniform vec2 Shift_XY;
uniform float Grad_Add;
uniform float Grad_Angle;
uniform float Border_Width;
uniform vec3 Border_Color;
uniform float Border_Opacity;
uniform float Border_Softness;
uniform float Border_Shift;

// Pseudo-random hash for noise generation
float hash(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// 2D Value Noise Function
float noise(vec2 x) {
    vec2 i = floor(x);
    vec2 f = fract(x);
    // Hermite interpolation for smooth edges
    f = f * f * (3.0 - 2.0 * f);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Fractal Brownian Motion (FBM) to handle "Octaves"
float fbm(vec2 p, int octaves) {
    float value = 0.0;
    float amplitude = 0.5;
    vec2 shift = vec2(100.0);
    // Rotation matrix to eliminate alignment artifacts between octaves
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));

    // WebGL 1.0 requires constant loop bounds
    for (int i = 0; i < 10; ++i) {
        if (i >= octaves) break;
        value += amplitude * noise(p);
        p = rot * p * 2.0 + shift;
        amplitude *= 0.5;
    }
    return value;
}

void main() {
    // 1. Calculate Transition Progress
    float progress = (Auto_Trans > 0.5) ? fract(time * 0.5) : clamp(Wipe_Percent / 100.0, 0.0, 1.0);

    // 2. Coordinate System & Aspect Ratio Setup
    vec2 uv = vUv;
    vec2 aspect = vec2(resolution.x / resolution.y, 1.0);

    // 3. Apply Noise Transforms (Shift, Rel Width, Frequency, Seed)
    vec2 baseUV = uv - (Shift_XY / resolution);
    vec2 noiseUV = baseUV * aspect;

    noiseUV.x /= max(Rel_Width, 0.0001); // Horizontal stretching
    noiseUV *= Frequency;                // Density scale
    noiseUV += vec2(Seed * 13.73, Seed * 43.19); // Randomize pattern based on Seed

    // 4. Generate Blob Noise Texture
    // FIX: Clamp as float first, then cast to int to avoid WebGL 1.0 errors
    int oct = int(clamp(Octaves, 1.0, 10.0));
    float n = fbm(noiseUV, oct); 

    // 5. Apply Grad Add & Grad Angle (Directional Wave)
    float angleRad = radians(Grad_Angle);
    vec2 gradDir = vec2(cos(angleRad), sin(angleRad));
    vec2 centeredUV = uv - 0.5;

    float gradValue = dot(centeredUV, gradDir);
    float gradInfluence = gradValue * Grad_Add;

    float testVal = n + gradInfluence;

    // 6. Dynamic Threshold Mapping
    float maxGrad = 0.707 * Grad_Add; 
    float valMin = 0.0 - abs(maxGrad);
    float valMax = 1.0 + abs(maxGrad);

    float threshold = mix(valMin - 0.05, valMax + 0.05, progress);

    // 7. Transition Direction Inversion
    if (Transition_Dir > 0.5) {
        testVal = (valMax + valMin) - testVal;
    }

    // 8. Base Mask Generation & Edge Softness
    float soft = max(Edge_Softness * 0.01, 0.0001); 
    float mask = smoothstep(threshold - soft, threshold + soft, testVal);

    // 9. Sample Input Layer (Foreground)
    vec4 fg = texture2D(tDiffuse, vUvScaled);

    // 10. Mix to Alpha Instead of a Background Layer
    vec4 transparentBg = vec4(0.0); // Pure transparency (0,0,0,0)
    vec4 finalColor = mix(transparentBg, fg, mask);

    // 11. Border Rendering 
    if (Border_Width > 0.0) {
        float bWidth = Border_Width * 0.01;
        float bShift = Border_Shift * 0.01;
        float bSoft = max(Border_Softness * 0.01, 0.0001);

        float bCenter = threshold - bShift;
        float dist = abs(testVal - bCenter);

        float borderAlpha = 1.0 - smoothstep(bWidth - bSoft, bWidth + bSoft, dist);
        borderAlpha *= Border_Opacity;

        // Composite the colored border over the transition
        finalColor.rgb = mix(finalColor.rgb, Border_Color, borderAlpha);
        finalColor.a = mix(finalColor.a, Border_Opacity, borderAlpha); 
    }

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/s-wipecells.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 resolution;
uniform vec2 uvScale;

varying vec2 vUv;
varying vec2 vUvScaled;

// ---- Controls ----
uniform float Transition_Dir;   // 0=Wipe Off to Bg, 1=Wipe On from Bg
uniform float Auto_Trans;       // 0=use Wipe%, 1=use time (0..1)
uniform float Wipe_Percent;     // 0..100

uniform float Cells;            // 0=Shrink, 1=Grow
uniform float Edge_Softness;    // pixels
uniform float Frequency;        // density
uniform float Rel_Width;        // horizontal stretch
uniform float Seed;             // pattern seed
uniform vec2  Shift_XY;         // pixels

uniform float Grad_Add;         // set 0 for “all at once across screen”
uniform float Grad_Angle;       // degrees

uniform float Border_Width;     // pixels
uniform vec3  Border_Color;     // rgb
uniform float Border_Opacity;   // 0..1
uniform float Border_Shift;     // pixels
uniform float Border_Softness;  // pixels

// Custom property (Dynamic Number) named "time"
uniform float time;

// ---- Helpers ----
float saturate(float x) { return clamp(x, 0.0, 1.0); }

float hash12(vec2 p, float seed) {
  vec3 p3 = fract(vec3(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33 + seed * 0.01);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p, float seed) {
  float n = hash12(p, seed);
  return vec2(n, hash12(p + 17.17, seed));
}

void voronoi(in vec2 x, out float d1, out float d2, out vec2 cellId) {
  vec2 n = floor(x);
  vec2 f = fract(x);

  float best1 = 1e9;
  float best2 = 1e9;
  vec2  bestId = vec2(0.0);

  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 id = n + g;

      vec2 o = hash22(id, Seed);
      vec2 r = g + o - f;
      float d = dot(r, r);

      if (d < best1) {
        best2 = best1;
        best1 = d;
        bestId = id;
      } else if (d < best2) {
        best2 = d;
      }
    }
  }

  d1 = sqrt(best1);
  d2 = sqrt(best2);
  cellId = bestId;
}

void main() {
  // Foreground input (Panzoid sampling uses vUvScaled) [1](https://docs.unity3d.com/6000.3/Documentation/Manual/SL-UnityShaderVariables.html)
  vec4 fg = texture2D(tDiffuse, vUvScaled);

  // Progress source: manual vs auto
  float manualP = saturate(Wipe_Percent / 100.0);
  float autoP   = saturate(time);                 // you drive 0..1
  float useAuto = step(0.5, Auto_Trans);
  float p = mix(manualP, autoP, useAuto);

  // Gradient timing
  // Gradient timing
  float ang = radians(Grad_Angle);
  vec2 gdir = vec2(cos(ang), sin(ang));
  float gcoord = dot((vUv - 0.5), gdir);

  // FIX 1: Remap the progress range to accommodate the gradient's maximum offset.
  // This ensures the wipe naturally starts completely off-screen at 0% 
  // and finishes completely off-screen at 100%, avoiding the abrupt snap.
  float maxOffset = 0.5 * abs(Grad_Add);
  float p_mapped = mix(-maxOffset, 1.0 + maxOffset, p);

  // FIX 2: Calculate prog using the mapped progress and REMOVE saturate(). 
  // Letting the value drop below 0.0 or exceed 1.0 allows the math further down 
  // (like edgeD) to correctly push the border boundaries entirely off the screen.
  float prog = p_mapped + Grad_Add * gcoord;

  // Pattern space
  vec2 shiftUV = Shift_XY / max(resolution, vec2(1.0));
  vec2 uvPat = vUv + shiftUV;
  uvPat.x *= max(Rel_Width, 1e-4);

  float freq = max(Frequency, 1e-4);
  vec2 x = uvPat * freq;

  // Voronoi
  float d1, d2;
  vec2 cid;
  voronoi(x, d1, d2, cid);

  // Cell interior factor
  float borderDist = 0.5 * (d2 - d1);
  float centerFactor = saturate(borderDist / (borderDist + d1 + 1e-6));

  // Grow/Shrink progression (SYNC across all cells)
  float grow = step(0.5, Cells);
  float shape = mix(centerFactor, 1.0 - centerFactor, grow);

  // Convert pixel softness to progress-domain softness
  float minRes = max(1.0, min(resolution.x, resolution.y));
  float soft = (Edge_Softness * freq) / minRes;

  // ---- Matte for the actual wipe ----
  float wipeSoft = max(soft, 1e-6);
  float m = smoothstep(shape - wipeSoft, shape + wipeSoft, prog);

  // Force endpoints so Wipe%=100 completes everywhere
  float eps = 1e-5;
  if (p <= eps) m = 0.0;
  if (p >= 1.0 - eps) m = 1.0;

  // ---- Separate matte just for "edge activity" (so border works when Edge_Softness=0) ----
  float onePx = (1.0 * freq) / minRes;          // ~1px in progress domain
  float lifeSoft = max(wipeSoft, onePx);

  float mLife = smoothstep(shape - lifeSoft, shape + lifeSoft, prog);
  if (p <= eps) mLife = 0.0;
  if (p >= 1.0 - eps) mLife = 1.0;

  // Transition Dir -> alpha wipe (Background=None)
  float dir = step(0.5, Transition_Dir);
  float wipeAlpha = mix(1.0 - m, m, dir);

  vec4 outCol = fg;
  outCol.a *= wipeAlpha;

  // ---- BORDER (like the previous code) ----
  // Uses a band around the edge location: (prog ~= shape), plus an "active" gate.
  float bw = (Border_Width * freq) / minRes;
  float bs = (Border_Softness * freq) / minRes;
  float bshift = (Border_Shift * freq) / minRes;

  float borderMask = 0.0;
  if (Border_Opacity > 0.0 && Border_Width > 0.0) {
    // Edge where the wipe boundary is
    float edgeD = abs((prog - shape) - bshift);

    float inner = max(bw - bs, 0.0);
    float outer = bw + bs;
    borderMask = 1.0 - smoothstep(inner, outer, edgeD);

    // "Active" gate (THIS is what made the previous border look right):
    // Keeps the border riding the transition band instead of showing everywhere.
    float active = 1.0 - smoothstep(0.5 + lifeSoft * 3.0,
                                    0.5 + lifeSoft * 6.0,
                                    abs(mLife - 0.5));
    borderMask *= active;
  }

  // Natural disappearance: as the transition finishes, mLife -> 1 everywhere, so active -> 0.
  float bA = saturate(Border_Opacity) * borderMask;

  outCol.rgb = mix(outCol.rgb, Border_Color, bA);
  outCol.a   = max(outCol.a, bA);

  gl_FragColor = outCol;
}

text./plugins/alipfx/shaders/s-wipedoublewedg:
precision highp float;
precision highp int;

// Panzoid Built-ins
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;
uniform float time;

// Custom Effect Properties
uniform float Transition_Dir;
uniform float Auto_Trans;
uniform float Wipe_Percent;
uniform float Wipe_Direction;
uniform float Edge_Softness;
uniform float Angle;
uniform float Pointiness;
uniform float Border_Width;
uniform vec3 Border_Color;
uniform float Border_Opacity;
uniform float Border_Softness;
uniform float Border_Shift;

void main() {
    // 1. Fetch current layer and define transparent background
    vec4 texColor = texture2D(tDiffuse, vUvScaled);
    vec4 bgColor = vec4(0.0); // Transparent/None as requested

    // 2. Setup Time/Progress
    float progress;
    if (Auto_Trans == 1.0) {
        // Changed from fract to clamp so it plays once and stops at 1.0
        // time * 0.5 means it takes 2 seconds to complete.
        progress = clamp(time * 0.5, 0.0, 1.0); 
    } else {
        progress = clamp(Wipe_Percent / 100.0, 0.0, 1.0);
    }

    // 3. Setup Aspect-Corrected Coordinates (centered at 0,0)
    float aspect = resolution.x / max(resolution.y, 1.0);
    vec2 p = vUv - 0.5;
    p.x *= aspect;

    // 4. Handle Rotation (Counter-Clockwise)
    float rad = -Angle * 3.14159265359 / 180.0;
    float c = cos(rad);
    float s = sin(rad);
    vec2 rp = vec2(p.x * c - p.y * s, p.x * s + p.y * c);

    // 5. Compute the Double Wedge Distance Field
    float pt = max(Pointiness, 0.001); // Avoid division by zero
    // INVERTED FIX: Multiply by pt instead of dividing. 
    // This makes higher values carve out sharper wedges.
    float F = abs(rp.x) - abs(rp.y) * pt;

    // 6. Calculate Screen Boundaries to ensure the wipe perfectly reaches the corners
    // We unroll the corner evaluations for WebGL 1.0 compatibility
    float maxF = -999.0;
    float minF = 999.0;
    vec2 tp, rtp; float tF;

    // Top Right
    tp = vec2(0.5 * aspect, 0.5); rtp = vec2(tp.x * c - tp.y * s, tp.x * s + tp.y * c); tF = abs(rtp.x) - abs(rtp.y) * pt; maxF = max(maxF, tF); minF = min(minF, tF);
    // Bottom Right
    tp = vec2(0.5 * aspect, -0.5); rtp = vec2(tp.x * c - tp.y * s, tp.x * s + tp.y * c); tF = abs(rtp.x) - abs(rtp.y) * pt; maxF = max(maxF, tF); minF = min(minF, tF);
    // Top Left
    tp = vec2(-0.5 * aspect, 0.5); rtp = vec2(tp.x * c - tp.y * s, tp.x * s + tp.y * c); tF = abs(rtp.x) - abs(rtp.y) * pt; maxF = max(maxF, tF); minF = min(minF, tF);
    // Bottom Left
    tp = vec2(-0.5 * aspect, -0.5); rtp = vec2(tp.x * c - tp.y * s, tp.x * s + tp.y * c); tF = abs(rtp.x) - abs(rtp.y) * pt; maxF = max(maxF, tF); minF = min(minF, tF);
    // Right Mid
    tp = vec2(0.5 * aspect, 0.0); rtp = vec2(tp.x * c - tp.y * s, tp.x * s + tp.y * c); tF = abs(rtp.x) - abs(rtp.y) * pt; maxF = max(maxF, tF); minF = min(minF, tF);
    // Top Mid
    tp = vec2(0.0, 0.5); rtp = vec2(tp.x * c - tp.y * s, tp.x * s + tp.y * c); tF = abs(rtp.x) - abs(rtp.y) * pt; maxF = max(maxF, tF); minF = min(minF, tF);

    // 7. Calculate the Transition Threshold 'd'
    // At exactly 50% (progress = 0.5), d is 0.0, forming a perfect X in the center.
    float d;
    if (Wipe_Direction == 0.0) { // Wedge In
        if (progress < 0.5) d = mix(maxF, 0.0, progress * 2.0);
        else d = mix(0.0, minF, (progress - 0.5) * 2.0);
    } else { // Wedge Out
        if (progress < 0.5) d = mix(minF, 0.0, progress * 2.0);
        else d = mix(0.0, maxF, (progress - 0.5) * 2.0);
    }

    // 8. Calculate Signed Distance
    float signed_dist = (Wipe_Direction == 0.0) ? (F - d) : (d - F);

    // Normalize distance by gradient magnitude to keep uniform thickness/softness
    // INVERTED FIX: Adjusted gradient magnitude math to match the new multiplier
    float grad_mag = sqrt(1.0 + (pt * pt));
    float true_dist = signed_dist / grad_mag;

    // 9. Edge Blending / Softness
    float e_soft = max(Edge_Softness * 0.001, 0.001); // Scaled for UV space
    float mixFactor = smoothstep(-e_soft, e_soft, true_dist);

    // Assign Outgoing/Incoming layers based on Transition Dir
    vec4 colOutgoing = (Transition_Dir == 0.0) ? texColor : bgColor;
    vec4 colIncoming = (Transition_Dir == 0.0) ? bgColor : texColor;
    vec4 baseColor = mix(colOutgoing, colIncoming, mixFactor);

    // 10. Border Calculations
    float border_dist = true_dist + (Border_Shift * 0.001); 
    float bw = Border_Width * 0.001; 
    float b_soft = max(Border_Softness * 0.001, 0.0001);

    float dist_from_center = abs(border_dist);
    float half_width = bw / 2.0;

    float border_alpha = 0.0;
    if (Border_Width > 0.0) {
        border_alpha = smoothstep(half_width + b_soft, half_width - b_soft, dist_from_center);
        border_alpha *= Border_Opacity;
    }

    // 11. Final Composite (Alpha Blending over the transition)
    vec4 finalColor;
    finalColor.rgb = mix(baseColor.rgb, Border_Color, border_alpha);
    finalColor.a = baseColor.a + border_alpha * (1.0 - baseColor.a);

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/s-wipefourwedges:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;

// Built-in Panzoid Uniforms
uniform vec2 resolution;
uniform float time;

// Custom Sapphire Properties
uniform float Transition_Dir;
uniform float Auto_Trans;
uniform float Wipe_Percent;
uniform float Wipe_Direction;
uniform float Edge_Softness;
uniform float Angle;
uniform float Aspect_Scale;
uniform float Border_Width;
uniform vec3 Border_Color;
uniform float Border_Opacity;
uniform float Border_Softness;
uniform float Border_Shift;

void main() {
    // 1. Center the UV coordinates and fix aspect ratio
    vec2 p = vUv - 0.5;
    p.x *= resolution.x / resolution.y;

    // 2. Apply Aspect Scale (Avoid division by zero)
    float asp = Aspect_Scale;
    if (asp == 0.0) asp = 0.001; 
    p.x /= asp;

    // 3. Apply Angle Rotation
    float rad = radians(Angle);
    float s = sin(rad);
    float c = cos(rad);
    mat2 rot = mat2(c, -s, s, c);
    p = rot * p;

    // 4. Calculate Distance Field for the "X" shape
    float d = min(abs(p.x - p.y), abs(p.x + p.y)) / 1.41421356;

    // 5. Calculate the maximum possible distance to ensure a clean 100% wipe
    float max_d = 0.0;
    for (int i = 0; i <= 2; i++) {
        for (int j = 0; j <= 2; j++) {
            vec2 test_p = vec2(float(i) * 0.5 - 0.5, float(j) * 0.5 - 0.5);
            test_p.x *= resolution.x / resolution.y;
            test_p.x /= asp;
            vec2 rt = rot * test_p;
            float d_test = min(abs(rt.x - rt.y), abs(rt.x + rt.y)) / 1.41421356;
            max_d = max(max_d, d_test);
        }
    }
    max_d += 0.01; // Add slight padding to clear the very corners

    // 6. Handle Timing and Auto Trans
    float t = clamp(Wipe_Percent / 100.0, 0.0, 1.0);
    if (Auto_Trans > 0.5) {
        // Loops a full 0 to 100% transition every 2 seconds for preview purposes
        t = fract(time * 0.5); 
    }

    // 7. Calculate Threshold based on Wedge In vs Wedge Out
    float soft = max(Edge_Softness / 200.0, 0.0001); // Softness moved up to pad thresholds

    // Declare the thresholds BEFORE the if statement
    float start_thresh = -soft - 0.002;
    float end_thresh = max_d + soft + 0.002;

    float Thresh;
    if (Wipe_Direction < 0.5) {
        Thresh = mix(end_thresh, start_thresh, t); // Wedge In
    } else {
        Thresh = mix(start_thresh, end_thresh, t); // Wedge Out
    }

    // 8. Determine inversion based on Transition Dir + Wipe Dir combo
    bool flip_shape = ((Transition_Dir < 0.5) == (Wipe_Direction < 0.5));

    float sd; // Signed distance to the transition boundary
    if (flip_shape) {
        sd = Thresh - d;
    } else {
        sd = d - Thresh;
    }

    // 9. Foreground Alpha with Edge Softness
    float fg_alpha = smoothstep(-soft, soft, sd);

    // 10. Border Calculation
    float bw = Border_Width / 200.0;
    float bs = max(Border_Softness / 200.0, 0.0001);
    float shift = Border_Shift / 100.0;

    float bd = abs(sd - shift); // Distance to the actual border line
    float border_alpha = 0.0;

    if (Border_Width > 0.0) {
        border_alpha = smoothstep(bw + bs, bw, bd) * Border_Opacity;
    }

    // 11. Composite the Result
    vec4 fg_color = texture2D(tDiffuse, vUvScaled);
    vec4 bg_color = vec4(0.0); // Transparent Background (None)

    // Mix Background with Foreground
    vec4 final_color = mix(bg_color, fg_color, fg_alpha);

    // Overlay the colored border
    if (border_alpha > 0.0) {
        final_color.rgb = mix(final_color.rgb, Border_Color, border_alpha);
        final_color.a = max(final_color.a, border_alpha);
    }

    gl_FragColor = final_color;
}

text./plugins/alipfx/shaders/s-wipemoire.glsl:
precision highp float;
precision highp int;

// --- Panzoid Built-ins ---
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform float time;
varying vec2 vUvScaled;

// --- Custom Parameters ---
uniform float Transition_Dir; // 0 = Wipe Off, 1 = Wipe On
uniform float Auto_Trans;     // 0 = Manual, 1 = Auto
uniform float Wipe_Percent;   // 0 to 100
uniform float Edge_Softness;  // 0 to 100

// Geometry
uniform vec2 A_Center_XY;
uniform vec2 B_Center_XY;
uniform float Frequency;
uniform float Phase_Start;
uniform float Phase_Speed;
uniform float Moire_Phase;
uniform float Moire_Speed;

// Relative Adjustments
uniform float A_Rel_Freq;
uniform float A_Rel_Width;
uniform float A_Rotate;
uniform float B_Rel_Freq;
uniform float B_Rel_Width;
uniform float B_Rotate;

// Gradient
uniform float Grad_Add;
uniform float Grad_Angle;

// Border
uniform float Border_Width;
uniform vec3 Border_Color;
uniform float Border_Opacity;
uniform float Border_Softness;
uniform float Border_Shift;

// --- Helpers ---
#define PI 3.14159265359

mat2 rotate2d(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

// Convert AE pixel coords -> UV
vec2 aePxToUv(vec2 px) {
    vec2 p = px + vec2(0.5, 0.5);
    vec2 uv = p / resolution;
    uv.y = 1.0 - uv.y;
    return uv;
}

// Generates a sine wave ring pattern (-1.0 to 1.0)
float getRingPattern(vec2 uv, vec2 centerPx, float relFreq, float relWidth, float rotDeg,
                     float globalPhase, float localPhase) {

    float aspect = resolution.x / resolution.y;
    vec2 effectiveCenterPx = (abs(centerPx.x) < 1e-6 && abs(centerPx.y) < 1e-6) ? (resolution * 0.5) : centerPx;
    vec2 centerUv = aePxToUv(effectiveCenterPx);

    vec2 p = uv - centerUv;
    p.x *= aspect;
    float rads = radians(rotDeg);
    p = rotate2d(rads) * p;
    p.x /= max(0.01, relWidth);

    float dist = length(p);
    return cos(dist * Frequency * relFreq * 20.0 + globalPhase + localPhase);
}

void main() {

    // 1. Progress (0.0 to 1.0)
    float progress;
    if (Auto_Trans > 0.5) {
        float autoSpeed = 0.5; 
        progress = clamp(time * autoSpeed, 0.0, 1.0);
    } else {
        progress = Wipe_Percent / 100.0;
    }
    progress = clamp(progress, 0.0, 1.0);

    // 2. Animation Phase
    float animTime = time;
    float globalPhase = Phase_Start + (Phase_Speed * animTime);
    float moireAnim  = Moire_Phase + (Moire_Speed * animTime);

    // 3. Generate Base Pattern
    float patA = getRingPattern(vUvScaled, A_Center_XY, A_Rel_Freq, A_Rel_Width, A_Rotate, globalPhase,  moireAnim);
    float patB = getRingPattern(vUvScaled, B_Center_XY, B_Rel_Freq, B_Rel_Width, B_Rotate, globalPhase, -moireAnim);

    float rawPattern = (patA + patB) * 0.5; // Natural bounds: [-1.0, 1.0]

    // 4. Gradient Slope Bounds Calculation
    float aspect = resolution.x / resolution.y;
    vec2 gUv = vUvScaled;
    gUv.x *= aspect;
    float gradRad = radians(Grad_Angle);
    vec2 gradDir = vec2(cos(gradRad), sin(gradRad));

    float minGrad = 0.0;
    float maxGrad = 0.0;
    float gradVal = 0.0;

    if (abs(Grad_Add) > 0.0) {
        gradVal = dot(gUv, gradDir) * (Grad_Add * 0.5);

        float d00 = 0.0;
        float d10 = gradDir.x * aspect;
        float d01 = gradDir.y;
        float d11 = gradDir.x * aspect + gradDir.y;

        float minDot = min(min(d00, d10), min(d01, d11));
        float maxDot = max(max(d00, d10), max(d01, d11));

        minGrad = minDot * (Grad_Add * 0.5);
        maxGrad = maxDot * (Grad_Add * 0.5);

        if (Grad_Add < 0.0) {
            float temp = minGrad;
            minGrad = maxGrad;
            maxGrad = temp;
        }
    }

    rawPattern += gradVal;

    // 5. Normalization
    float minRaw = -1.0 + minGrad;
    float maxRaw =  1.0 + maxGrad;
    float matte = (rawPattern - minRaw) / max(0.0001, (maxRaw - minRaw));

    // 6. Wipe & Softness Logic
    float softness = max(0.001, Edge_Softness * 0.01);
    float safeThreshold = mix(-softness, 1.0 + softness, progress);

    float alpha;
    if (Transition_Dir < 0.5) {
        alpha = smoothstep(safeThreshold - softness, safeThreshold + softness, matte);
    } else {
        alpha = 1.0 - smoothstep(safeThreshold - softness, safeThreshold + softness, matte);
    }

    // 7. Border Logic (Fixed Softness)
    vec4 borderFinal = vec4(0.0);
    if (Border_Width > 0.0) {
        float bSoft  = max(0.001, Border_Softness * 0.01);
        float bShift = Border_Shift * 0.1;
        float bWidth = Border_Width * 0.01;

        float distToEdge = abs(matte - (safeThreshold + bShift));

        // Symmetric smoothstep: expands the blur BOTH ways (inward and outward)
        float bMask = 1.0 - smoothstep(max(0.0, bWidth - bSoft), bWidth + bSoft, distToEdge);
        bMask *= Border_Opacity;

        borderFinal = vec4(Border_Color, bMask);
    }

    // 8. Final Composite
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec4 finalColor = texel;
    finalColor.a *= alpha;

    // Mix Border on top
    finalColor.rgb = mix(finalColor.rgb, borderFinal.rgb, borderFinal.a);
    finalColor.a   = max(finalColor.a, borderFinal.a);

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/s-wipepixelate.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;

uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;
varying vec2 vUvScaled;

// Panzoid properties
uniform float Transition_Dir;   // 0 = Wipe Off to Bg, 1 = Wipe On from Bg
uniform float Auto_Trans;       // 0 = use Wipe Percent, 1 = use time
uniform float Wipe_Percent;     // 0..100
uniform float Edge_Width;       // pixels
uniform float Angle;            // degrees
uniform float Pixel_Frequency;  // higher = smaller blocks
uniform float Pixel_Rel_Width;  // 1 = square-ish
uniform float Chunky;           // 0..1
uniform float Seed;             // any float
uniform float time;             // normalized 0..1 for Auto Trans

// ------------------------------------------------------------
// Hash / noise
// ------------------------------------------------------------
float hash21(vec2 p)
{
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Project UV onto wipe axis, normalized across frame
float projectedPos(vec2 uv, vec2 dir)
{
  vec2 c = uv - 0.5;
  float span = abs(dir.x) + abs(dir.y);
  span = max(span, 1e-5);
  return clamp(0.5 + dot(c, dir) / span, 0.0, 1.0);
}

// Cell size in UV space
vec2 getCellSize(float freq, float relWidth)
{
  float aspect = resolution.x / max(resolution.y, 1.0);

  // vertical density
  float cellH = 1.0 / max(freq, 1.0);

  // relative horizontal scaling
  float cellW = cellH * max(relWidth, 0.001) / aspect;

  // never smaller than one physical pixel
  cellW = max(cellW, 1.0 / max(resolution.x, 1.0));
  cellH = max(cellH, 1.0 / max(resolution.y, 1.0));

  return vec2(cellW, cellH);
}

// Per-cell order value with optional chunk grouping
float cellOrder(vec2 cellId, float chunky, float seed)
{
  vec2 s = vec2(seed * 71.13 + 19.7, seed * 131.97 + 7.31);

  float fine = hash21(cellId + s);

  float clusterSize = mix(1.0, 7.0, clamp(chunky, 0.0, 1.0));
  vec2 coarseId = floor(cellId / clusterSize);
  float coarse = hash21(coarseId + s * 1.618);

  // Chunky = more grouped blocks, but still keeps some local variation
  return mix(fine, mix(fine, coarse, 0.82), clamp(chunky, 0.0, 1.0));
}

void main()
{
  // ----------------------------------------------------------
  // Progress
  // ----------------------------------------------------------
  float progress = (Auto_Trans >= 0.5)
    ? clamp(time, 0.0, 1.0)
    : clamp(Wipe_Percent / 100.0, 0.0, 1.0);

  // ----------------------------------------------------------
  // Hard exact start/end states
  // ----------------------------------------------------------
  vec4 fgFull = texture2D(tDiffuse, vUvScaled);

  if (Transition_Dir < 0.5)
  {
    // Wipe Off to Bg
    if (progress <= 0.0)
    {
      gl_FragColor = fgFull;
      return;
    }
    if (progress >= 1.0)
    {
      gl_FragColor = vec4(0.0);
      return;
    }
  }
  else
  {
    // Wipe On from Bg
    if (progress <= 0.0)
    {
      gl_FragColor = vec4(0.0);
      return;
    }
    if (progress >= 1.0)
    {
      gl_FragColor = fgFull;
      return;
    }
  }

  // ----------------------------------------------------------
  // Wipe direction
  // 0° = left -> right
  // 90° = bottom -> top
  // ----------------------------------------------------------
  float ang = radians(Angle);
  vec2 dir = normalize(vec2(cos(ang), sin(ang)));

  // ----------------------------------------------------------
  // Cell grid
  // ----------------------------------------------------------
  vec2 cellSize = getCellSize(Pixel_Frequency, Pixel_Rel_Width);
  vec2 cellId = floor(vUv / cellSize);
  vec2 cellCenter = (cellId + 0.5) * cellSize;
  cellCenter = clamp(cellCenter, vec2(0.0), vec2(1.0));

  // ----------------------------------------------------------
  // Directional base position of this block
  // ----------------------------------------------------------
  float axisPos = projectedPos(cellCenter, dir);

  // Edge width -> normalized transition band size
  float axisPixels = abs(dir.x) * resolution.x + abs(dir.y) * resolution.y;
  axisPixels = max(axisPixels, 1.0);

  float band = max(Edge_Width, 0.0138) / axisPixels;

  // Keep band from becoming absurdly tiny compared to cell scale
  float minBand = 0.35 * max(cellSize.x, cellSize.y);
  band = max(band, minBand);

  // ----------------------------------------------------------
  // Randomized order inside the transition band
  // ----------------------------------------------------------
  float order = cellOrder(cellId, Chunky, Seed);

  // More Chunky = more grouped change, slightly less random spread
  float scatterAmount = mix(1.0, 0.7, clamp(Chunky, 0.0, 1.0));
  float offsetAmp = band * scatterAmount;

  // Final block threshold:
  // a directional wipe with random spread inside the edge zone
  float threshold = axisPos + (order - 0.5) * 2.0 * offsetAmp;

  // Frontier goes from before all possible thresholds
  // to after all possible thresholds
  float frontierStart = -offsetAmp - band;
  float frontierEnd   = 1.0 + offsetAmp + band;
  float frontier = mix(frontierStart, frontierEnd, progress);

  // ----------------------------------------------------------
  // BINARY block transition
  // No pixelation of image, no soft pixelated edge.
  // Each block is either already switched or not.
  // ----------------------------------------------------------
  float transitioned = step(threshold, frontier);

  // ----------------------------------------------------------
  // Transition Dir
  // 0 = Wipe Off to Bg  => FG disappears block-by-block
  // 1 = Wipe On from Bg => FG appears block-by-block
  // ----------------------------------------------------------
  float vis;
  if (Transition_Dir < 0.5)
  {
    vis = 1.0 - transitioned;
  }
  else
  {
    vis = transitioned;
  }

  // Preserve full-res foreground, only mask visibility by blocks
  gl_FragColor = vec4(fgFull.rgb * vis, fgFull.a * vis);
}

text./plugins/alipfx/shaders/s-wipeplasma.gls:
#extension GL_OES_standard_derivatives : enable

precision highp float;
precision highp int;

/* Panzoid built-ins */
uniform sampler2D tDiffuse;   
uniform vec2 resolution;      
uniform vec2 uvScale;         
varying vec2 vUvScaled;       
varying vec2 vUv;             

/* === User properties === */
uniform float Transition_Dir;      // 0 wipe off to bg/none, 1 wipe on from bg/none
uniform float Auto_Trans;          // 0 manual, 1 auto 
uniform float Wipe_Percent;        // 0..100

uniform float Edge_Softness;       // 0..100
uniform float Frequency;
uniform float Freq_Rel_X;
uniform float Octaves;
uniform float Seed;

uniform float Plasma_Grad;
uniform float Plasma_Grad_Angle;   // degrees
uniform float Layers;
uniform vec2  Shift_XY;            // pixels

uniform float Phase_Start;
uniform float Phase_Speed;

uniform float Grad_Add;
uniform float Grad_Angle;          // degrees

uniform float Border_Width;        // 0..100
uniform vec3  Border_Color;
uniform float Border_Opacity;
uniform float Border_Softness;     // 0..100
uniform float Border_Shift;        

uniform float time;

/* === Helpers === */
float saturate(float x) { return clamp(x, 0.0, 1.0); }

mat2 rot(float a) {
  float s = sin(a), c = cos(a);
  return mat2(c, -s, s, c);
}

float fastTanh(float x) {
  x = clamp(x, -6.0, 6.0);
  float e = exp(2.0 * x);
  return (e - 1.0) / (e + 1.0);
}

/* Hash / noise */
float hash12(vec2 p, float seed) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031 + seed);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float valueNoise(vec2 p, float seed) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f*f*(3.0-2.0*f);

  float a = hash12(i + vec2(0.0, 0.0), seed);
  float b = hash12(i + vec2(1.0, 0.0), seed);
  float c = hash12(i + vec2(0.0, 1.0), seed);
  float d = hash12(i + vec2(1.0, 1.0), seed);

  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p, float seed, float oct) {
  float sum = 0.0;
  float amp = 0.55;
  float f = 1.0;

  for (int i = 0; i < 10; i++) {
    if (float(i) >= oct) break;
    sum += amp * (valueNoise(p * f, seed + float(i) * 19.0) * 2.0 - 1.0);
    f *= 2.0;
    amp *= 0.5;
  }
  return sum; 
}

/* Sapphire-ish plasma */
float plasmaField(vec2 uv01, float phase) {
  vec2 p = uv01 - 0.5;
  p.x *= resolution.x / max(1.0, resolution.y);

  p += Shift_XY / max(vec2(1.0), resolution);

  float effFreq = max(0.001, Frequency) * 0.25;
  p.x *= max(0.001, Freq_Rel_X);
  p *= effFreq;

  float ga = radians(Grad_Angle + 180.0); 
  vec2 gdir = normalize(vec2(cos(ga), sin(ga)));
  float gradCoord = dot(uv01 - 0.5, gdir);
  p += gdir * gradCoord * Grad_Add * 0.55;

  vec2 t = vec2(phase, -phase * 0.73);

  float stripes = 0.0;
  if (Plasma_Grad > 0.0001) {
    float pa = radians(Plasma_Grad_Angle);
    vec2 pdir = normalize(vec2(cos(pa), sin(pa)));
    stripes = sin(dot(p, pdir) * 6.2831853 + phase * 1.25);
    stripes *= Plasma_Grad;
  }

  float lay = clamp(Layers, 1.0, 10.0);

  float w1 = fbm(p + t * 0.55, Seed * 31.7, clamp(Octaves, 1.0, 10.0));
  float w2 = fbm(p * 1.7 - t * 0.33, Seed * 57.3 + 9.1, clamp(Octaves, 1.0, 10.0));
  vec2 warp = vec2(w1, w2) * (0.55 + 0.06 * lay);

  float n = fbm(p + warp + t * 0.25, Seed * 97.13, clamp(Octaves, 1.0, 10.0));

  float marble = sin((n + 0.35 * w1 + 0.25 * w2 + stripes) * (3.5 + 0.35 * lay) * 3.1415926);
  float ridge = 1.0 - abs(n);
  ridge = pow(saturate(ridge), 1.25);

  float field = 0.55 * ridge + 0.45 * (0.5 + 0.5 * marble);
  field = 0.5 + 0.5 * fastTanh((field - 0.5) * 2.2);

  return saturate(field);
}

float filteredPlasmaField(vec2 uv, float phase) {
  vec2 texel = 1.0 / max(resolution, vec2(1.0));
  vec2 o = texel * 1.25;

  float c  = plasmaField(uv, phase);
  float x1 = plasmaField(uv + vec2(o.x, 0.0), phase);
  float x2 = plasmaField(uv - vec2(o.x, 0.0), phase);
  float y1 = plasmaField(uv + vec2(0.0, o.y), phase);
  float y2 = plasmaField(uv - vec2(0.0, o.y), phase);

  return (c * 0.40 + (x1 + x2 + y1 + y2) * 0.15);
}

void main() {
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  float manualProg = saturate(Wipe_Percent / 100.0);
  float useAuto = step(0.5, Auto_Trans);
  float autoProg = saturate(time);
  float prog = mix(manualProg, autoProg, useAuto);

  float phase = Phase_Start + Phase_Speed * mix(prog, time, useAuto);

  vec2 uv01 = vUv;
  float field = filteredPlasmaField(uv01, phase);

  float ga = radians(Grad_Angle + 180.0);
  vec2 gdir = normalize(vec2(cos(ga), sin(ga)));

  float g = dot(uv01 - 0.5, gdir);
  float g01 = g + 0.5;

  float amp = 0.60 + 0.10 * abs(Grad_Add);
  float wipeCoord = g01 + (field - 0.5) * amp;

  // Base AA to prevent jagged pixels when softness is 0
  float px = max(1e-6, fwidth(wipeCoord));

  // FIX: Unhooked Edge_Softness from fwidth so it blurs natively across the screen!
  float edgeSoft = max(1.25 * px, Edge_Softness * 0.01);

  float span = 0.5 * (abs(gdir.x) + abs(gdir.y));
  float gMin = 0.5 - span;
  float gMax = 0.5 + span;

  float wMin = gMin - 0.5 * amp;
  float wMax = gMax + 0.5 * amp;

  float margin = 0.01 + 3.0 * edgeSoft;
  float thr = mix(wMax + margin, wMin - margin, prog);

  float m = smoothstep(thr - edgeSoft, thr + edgeSoft, wipeCoord);

  float alphaOff = 1.0 - m;
  float alphaOn  = m;

  float dirIsOn = step(0.5, Transition_Dir);
  float alphaMask = mix(alphaOff, alphaOn, dirIsOn);

  // FIX: Unhooked Border Width/Softness from fwidth and applied symmetric blur
  float borderMask = 0.0;
  if (Border_Width > 0.0 && Border_Opacity > 0.0) {
    float shiftCoord = Border_Shift * 0.01;
    float d = abs((wipeCoord - thr) - shiftCoord);

    float bw = Border_Width * 0.01;
    float bs = max(0.001, Border_Softness * 0.01);

    borderMask = 1.0 - smoothstep(max(0.0, bw - bs), bw + bs, d);
    borderMask *= Border_Opacity;
  }

  vec3 rgb = mix(texel.rgb, Border_Color, saturate(borderMask));

  gl_FragColor = vec4(rgb, texel.a * alphaMask);
}

text./plugins/alipfx/shaders/s-wipetiles.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform float time;
varying vec2 vUvScaled;

uniform float Transition_Dir;
uniform float Auto_Trans;
uniform float Wipe_Percent;     // 0..100
uniform float Tile_Shapes;
uniform float Shapes_Dir;
uniform float Edge_Softness;
uniform float Angle;
uniform float Frequency;
uniform float Rel_Width;
uniform float Rel_Wid_Pre_Rot;
uniform vec2  Shift_XY;
uniform float Morph_Shapes;
uniform float Grad_Add;
uniform float Grad_Angle;
uniform float Border_Width;
uniform vec3  Border_Color;
uniform float Border_Opacity;
uniform float Border_Softness;
uniform float Border_Shift;

#define PI 3.14159265359
#define SQRT3 1.73205080757

vec2 rotate(vec2 v, float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c) * v;
}

float snapMenu(float x, float maxv) { return clamp(floor(x + 0.5), 0.0, maxv); }
float snapToggle(float x) { return step(0.5, floor(x + 0.5)); }

float norm01(float x) { return (x > 1.0) ? clamp(x / 100.0, 0.0, 1.0) : clamp(x, 0.0, 1.0); }

float edgeStep(float x, float soft) {
    if (soft <= 0.0) return 1.0 - step(0.0, x);
    return 1.0 - smoothstep(-soft, 0.0, x);
}

float ease01(float t) { return t * t * (3.0 - 2.0 * t); }

float expMix(float a, float b, float t){
    return exp(mix(log(max(a, 1e-12)), log(max(b, 1e-12)), t));
}

// snap 0..1 to N steps (50 steps requested)
float snap01Steps(float x, float steps) {
    x = clamp(x, 0.0, 1.0);
    return floor(x * steps + 0.5) / steps;   // nearest-step snapping
}

float sdTriangle(vec2 p, float r) {
    const float k = SQRT3;
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if (p.x + k*p.y > 0.0) p = vec2(p.x - k*p.y, -k*p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0*r, 0.0);
    return -length(p) * sign(p.y);
}

float sdHexagon(vec2 p, float r) {
    const vec3 k = vec3(-0.866025404, 0.5, 0.577350269);
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= vec2(clamp(p.x, -k.z*r, k.z*r), r);
    return length(p) * sign(p.y);
}

// true diamond (rotated square)
float sdDiamond(vec2 p, float r){
    return (abs(p.x) + abs(p.y)) - r;
}

vec4 hexGrid(vec2 uv) {
    vec2 r = vec2(1.0, 1.7320508);
    vec2 h = r * 0.5;
    vec2 a = mod(uv, r) - h;
    vec2 b = mod(uv - h, r) - h;

    vec2 gv, id;
    if (dot(a, a) < dot(b, b)) { gv = a; id = uv - a; }
    else { gv = b; id = uv - b; }

    return vec4(gv, id);
}

void lattice60(vec2 p, out vec2 gv, out vec2 id) {
    float vv = (2.0 / SQRT3) * p.y;
    float uu = p.x - p.y / SQRT3;
    vec2 uv = vec2(uu, vv);

    vec2 cell = floor(uv);
    vec2 f = fract(uv) - 0.5;

    vec2 b1 = vec2(1.0, 0.0);
    vec2 b2 = vec2(0.5, SQRT3 * 0.5);

    gv = f.x * b1 + f.y * b2;
    id = cell;
}

float sdTriMesh(vec2 gv, float r) {
    float vv = (2.0 / SQRT3) * gv.y;
    float uu = gv.x - gv.y / SQRT3;
    vec2 f = vec2(uu, vv) + 0.5;

    float upper = step(1.0, f.x + f.y);
    vec2 f2 = mix(f, vec2(1.0) - f, upper);

    vec2 a = vec2(1.0, 0.0);
    vec2 b = vec2(0.5, SQRT3 * 0.5);
    vec2 cart = f2.x * a + f2.y * b;

    vec2 centroid = (a + b) / 3.0;
    vec2 pp = (cart - centroid) * SQRT3;

    return sdTriangle(pp, r);
}

// nearest-center square grid (used by stars + diamonds)
void gridNearest(vec2 p, out vec2 gv, out vec2 id){
    vec2 c = floor(p + 0.5);
    gv = p - c; // [-0.5..0.5]
    id = c;
}

void main() {
    // timing:
    // - Manual uses Wipe_Percent (snapped to 50 steps)
    // - Auto uses time in seconds, lasts 1 second, then holds (snapped to 50 steps)
    float tManual = snap01Steps(clamp(Wipe_Percent / 100.0, 0.0, 1.0), 50.0);

    // 1 second auto duration (no new control, just a constant)
    float tAuto = snap01Steps(clamp(time / 1.0, 0.0, 1.0), 50.0);

    float prog = (Auto_Trans > 0.5) ? tAuto : tManual;

    float shapeIdx = snapMenu(Tile_Shapes, 3.0);
    float growDir  = snapToggle(Shapes_Dir);
    float transDir = snapToggle(Transition_Dir);

    // aspect-correct space
    vec2 p = vUvScaled * (resolution / resolution.y);
    p -= Shift_XY / resolution.y;

    vec2 center = vec2(0.5) * (resolution / resolution.y);
    p -= center;
    p = rotate(p, radians(-Angle));
    p.x /= max(0.01, Rel_Wid_Pre_Rot);
    p *= max(0.1, Frequency);
    p.x /= max(0.01, Rel_Width);

    vec2 gv = vec2(0.0);
    vec2 id = vec2(0.0);

    // grid selection: diamonds use square grid
    if (shapeIdx < 0.5) {
        vec4 hg = hexGrid(p);
        gv = hg.xy;
        id = hg.zw;
    }
    else if (shapeIdx < 1.5) {
        lattice60(p, gv, id);          // Triangles
    }
    else if (shapeIdx < 2.5) {
        gridNearest(p, gv, id);        // Diamonds
    }
    else {
        gridNearest(p * 0.92, gv, id); // Stars
    }

    // ✅ FIXED: Gradient timing boundary calculation
    vec2 gradVec = vec2(cos(radians(Grad_Angle)), sin(radians(Grad_Angle)));
    float gradPos = dot(id, gradVec);
    float gradLen = Grad_Add;

    // Calculate maximum possible grid distance to safely map the 0% and 100% bounds
    float aspect = resolution.x / resolution.y;
    float maxUVDist = length(vec2(aspect * 0.5, 0.5));
    float shiftDist = length(Shift_XY / resolution.y);
    float maxGridDist = (maxUVDist + shiftDist) * max(0.1, Frequency) 
                      * (1.0 / max(0.01, Rel_Wid_Pre_Rot)) 
                      * (1.0 / max(0.01, Rel_Width)) + 5.0; // +5.0 padding

    float maxOffset = maxGridDist * 0.05 * abs(gradLen);

    // Stretch the progress range beyond 0..1 to perfectly encapsulate the max offset
    float mappedProg = prog * (1.0 + 2.0 * maxOffset) - maxOffset;

    float localProgress = clamp(
        mappedProg - (gradPos * 0.05 * gradLen),
        0.0, 1.0
    );

    // morph rotation
    gv = rotate(gv, radians(Morph_Shapes));

    float soft = Edge_Softness * 0.02;

    float trans = 0.0;
    float bMask = 0.0;

    if (shapeIdx < 0.5) {
        // Hex
        float d = sdHexagon(gv, 0.40);
        float RMAX = 1.20;
        float currentR = mix(RMAX * (1.0 - localProgress), localProgress * RMAX, growDir);
        float x = d + (0.60 - currentR);
        float mask = edgeStep(x, soft);
        trans = mix(1.0 - mask, mask, growDir);

        if (Border_Width > 0.0) {
            float bw = Border_Width * 0.01;
            float bs = Border_Softness * 0.02;
            float shift = Border_Shift * 0.01;
            float bDist = abs(x - shift);
            bMask = (bs <= 0.0) ? (1.0 - step(bw, bDist))
                                : (1.0 - smoothstep(bw, bw + bs, bDist));
        }

    } else if (shapeIdx < 1.5) {
        // Triangles
        float d = sdTriMesh(gv, 0.45);
        float RMAX = 1.20;
        float currentR = mix(RMAX * (1.0 - localProgress), localProgress * RMAX, growDir);
        float x = d + (0.60 - currentR);
        float mask = edgeStep(x, soft);
        trans = mix(1.0 - mask, mask, growDir);

        if (Border_Width > 0.0) {
            float bw = Border_Width * 0.01;
            float bs = Border_Softness * 0.02;
            float shift = Border_Shift * 0.01;
            float bDist = abs(x - shift);
            bMask = (bs <= 0.0) ? (1.0 - step(bw, bDist))
                                : (1.0 - smoothstep(bw, bw + bs, bDist));
        }

    } else if (shapeIdx < 2.5) {
        // Diamonds
        float d = sdDiamond(gv, 0.45);
        float RMAX = 1.20;
        float currentR = mix(RMAX * (1.0 - localProgress), localProgress * RMAX, growDir);
        float x = d + (0.60 - currentR);
        float mask = edgeStep(x, soft);
        trans = mix(1.0 - mask, mask, growDir);

        if (Border_Width > 0.0) {
            float bw = Border_Width * 0.01;
            float bs = Border_Softness * 0.02;
            float shift = Border_Shift * 0.01;
            float bDist = abs(x - shift);
            bMask = (bs <= 0.0) ? (1.0 - step(bw, bDist))
                                : (1.0 - smoothstep(bw, bw + bs, bDist));
        }

    } else {
        // Stars
        float u = mix(1.0 - localProgress, localProgress, growDir);
        u = clamp(u, 0.0, 1.0);
        float e = ease01(u);

        float pix = max(1.0 / max(resolution.y, 1.0), 1e-6) * max(Frequency, 0.1);
        float minSize = max(pix * 0.02, 1e-6);
        float maxSize = 12.0;
        float size = expMix(minSize, maxSize, e);

        vec2 sgv = rotate((gv / size) * 2.85, PI/6.0);
        float dStar = min(
            sdTriangle(sgv, 0.55),
            sdTriangle(rotate(sgv, PI/3.0), 0.55)
        );

        float starInside = edgeStep(dStar, soft);
        trans = mix(1.0 - starInside, starInside, growDir);

        if (Border_Width > 0.0) {
            float bw = Border_Width * 0.01;
            float bs = Border_Softness * 0.02;
            float shift = Border_Shift * 0.01;
            float bDist = abs(dStar - shift);
            bMask = (bs <= 0.0) ? (1.0 - step(bw, bDist))
                                : (1.0 - smoothstep(bw, bw + bs, bDist));
        }
    }

    float fgAmt = mix(1.0 - trans, trans, transDir);
    vec4 fg = texture2D(tDiffuse, vUvScaled);
    vec4 color = mix(vec4(0.0), fg, fgAmt);

    color.rgb = mix(color.rgb, Border_Color, bMask * Border_Opacity);
    color.a = max(color.a, bMask * Border_Opacity);

    gl_FragColor = color;
}

text./plugins/alipfx/shaders/s-wipeweave.glsl:
precision highp float;
precision highp int;

// Panzoid Built-ins
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;
varying vec2 vUv;

// Custom Properties
uniform int Transition_Dir;   // 0: Wipe Off to Bg, 1: Wipe On from Bg
uniform int Auto_Trans;       // 0: No, 1: Yes
uniform float Wipe_Percent;   // 0 to 100
uniform int Strands;          // 0: Shrink, 1: Grow
uniform float Edge_Softness;  // 0.0 to 1.0+
uniform float Frequency;      // e.g. 20.0
uniform float Rel_Length;     // e.g. 10.0
uniform int Octaves;          // 1 to 10
uniform float Seed;           
uniform vec2 Shift_XY;        
uniform float H_Speed_X;      
uniform float V_Speed_Y;      
uniform float Grad_Add;       
uniform float Grad_Angle;     
uniform float Border_Width;   
uniform vec3 Border_Color;    
uniform float Border_Opacity; 
uniform float Border_Softness;
uniform float Border_Shift;   

uniform float time; 

// --- Helper Functions ---

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float res = mix(mix(hash(i + vec2(0.0, 0.0)), 
                        hash(i + vec2(1.0, 0.0)), f.x),
                    mix(hash(i + vec2(0.0, 1.0)), 
                        hash(i + vec2(1.0, 1.0)), f.x), f.y);
    return res;
}

float fbm(vec2 p, int octaves) {
    float value = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for (int i = 0; i < 10; i++) { 
        if (i >= octaves) break;
        value += amp * noise(p * freq);
        p += vec2(100.0 + Seed * 10.0); 
        freq *= 2.0;
        amp *= 0.5;
    }
    return value;
}

mat2 rotate2d(float angle) {
    return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
}

void main() {
    // 1. Setup Progress
    float progress = Wipe_Percent / 100.0;
    if (Auto_Trans == 1) {
        progress = fract(time * 0.5); 
    }

    // 2. Setup Coordinates & Motion
    vec2 p = vUv;
    p += Shift_XY * 0.001; 
    vec2 movement = vec2(H_Speed_X, V_Speed_Y) * time * 0.1;
    p += movement;

    // 3. Generate Weave Pattern
    vec2 pVert = p * Frequency;
    vec2 pHorz = p * Frequency;

    // Rel Length: stretches strands. 
    // Higher Rel Length = longer strands = lower noise frequency on that axis.
    pVert.y /= max(0.1, Rel_Length); 
    pHorz.x /= max(0.1, Rel_Length);

    float n1 = fbm(pVert + vec2(Seed), Octaves);
    float n2 = fbm(pHorz + vec2(Seed + 13.37), Octaves);

    float weavePattern = max(n1, n2);
    weavePattern = clamp(weavePattern, 0.0, 1.0);

    // 4. Gradient (Grad Add)
    if (Grad_Add > 0.0) {
        vec2 centeredUv = vUv - 0.5;
        float rad = radians(Grad_Angle);
        centeredUv = rotate2d(rad) * centeredUv;
        float grad = centeredUv.y + 0.5; 
        weavePattern = mix(weavePattern, grad, clamp(Grad_Add * 0.5, 0.0, 0.8));
    }

    // 5. Logic: Strands (Grow vs Shrink)
    if (Strands == 1) { 
       weavePattern = 1.0 - weavePattern;
    }

    // 6. Calculate Matte (Alpha)
    // As progress goes 0->1, threshold increases.
    // smoothstep(low, high, x): if x > high return 1. if x < low return 0.
    // As low/high increase past x, result goes 1 -> 0.
    // Therefore, default behavior is "Wipe Off" (Starts visible, ends invisible).

    float threshold = progress;
    float soft = max(0.001, Edge_Softness * 0.1);

    float p_min = threshold * (1.0 + 2.0 * soft) - soft;
    float p_max = p_min + soft;

    float alpha = smoothstep(p_min, p_max, weavePattern);

    // 7. Transition Direction Logic (FIXED)
    // 0 = Wipe Off to Bg (Default 1->0 behavior). Do nothing.
    // 1 = Wipe On from Bg (Inverse 0->1 behavior). Invert.
    if (Transition_Dir == 1) {
        alpha = 1.0 - alpha; 
    }

    // 8. Border Calculation
    vec4 borderColorOutput = vec4(0.0);
    if (Border_Width > 0.0) {
        float borderCenter = p_min; 
        float bSoft = max(0.001, Border_Softness * 0.1);
        float bWidth = Border_Width * 0.01; 
        float bShift = Border_Shift * 0.01;
        float bDist = abs(weavePattern - (borderCenter + bShift));

        float bAlpha = 1.0 - smoothstep(bWidth, bWidth + bSoft, bDist);
        bAlpha *= Border_Opacity;
        borderColorOutput = vec4(Border_Color, bAlpha);
    }

    // 9. Final Mix
    vec4 currentLayer = texture2D(tDiffuse, vUvScaled);
    vec4 backgroundColor = vec4(0.0); // Transparent

    // Apply Transition Alpha
    vec4 finalColor = mix(backgroundColor, currentLayer, alpha);

    // Apply Border
    // We add border on top, handling alpha composition
    finalColor = vec4(mix(finalColor.rgb, Border_Color, borderColorOutput.a), 
                      min(1.0, finalColor.a + borderColorOutput.a));

    gl_FragColor = finalColor;
}

text./plugins/alipfx/shaders/scl-film-strip.g:
precision highp float;
precision highp int;

// Built-in Panzoid variables
uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;
varying vec2 vUv;

// --- GLOBAL TRANSFORM ---
uniform vec2 Global_Position;

// --- BASE UNIFORMS (Now repeats the ENTIRE FILM STRIP) ---
uniform float Base_Scale_X;
uniform float Base_Scale_Y;
uniform float Base_Offset_Paths;
uniform vec3 Base_Color;
uniform float Base_Stroke;
uniform float Base_Stroke_Width;
uniform vec3 Base_Stroke_Color;
uniform float Base_Copies;
uniform vec2 Base_Position;

// --- MAIN UNIFORMS (Repeats the BIG HOLES horizontally) ---
uniform float Main_Scale_X;
uniform float Main_Scale_Y;
uniform float Main_Roundness;
uniform float Main_Offset_Paths;
uniform float Main_Copies;
uniform vec2 Main_Position;

// --- SUB UNIFORMS (Repeats the SMALL HOLES horizontally) ---
uniform float Sub_Scale_X;
uniform float Sub_Scale_Y;
uniform float Sub_Roundness;
uniform float Sub_Offset_Paths;
uniform float Sub_Copies;
uniform vec2 Sub_Position;

// Basic SDF for a rounded rectangle
float getRectSDF(vec2 p, vec2 size, float roundness, float offsetPath) {
    vec2 halfSize = max(size * 0.5, vec2(0.0));
    vec2 d = abs(p) - halfSize + roundness;
    float dist = length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - roundness;
    return dist - offsetPath; 
}

// Function to handle After Effects Repeater logic for the holes
float getRepeatedSDF(vec2 p, vec2 size, float roundness, float offsetPath, float copies, vec2 posStep) {
    float minDist = 999999.0;
    float c = max(1.0, copies);
    vec2 startOffset = posStep * (c - 1.0) * 0.5; 

    // Limit to 100 copies for performance
    for(int i = 0; i < 100; i++) {
        if(float(i) >= copies) break;
        vec2 offset = -startOffset + posStep * float(i);
        float d = getRectSDF(p - offset, size, roundness, offsetPath);
        minDist = min(minDist, d);
    }
    return minDist;
}

// --- NEW: Assembles ONE complete film strip ---
float getSingleStripSDF(vec2 p) {
    // 1. Draw Base Box
    vec2 baseSize = vec2(Base_Scale_X, Base_Scale_Y);
    float baseDist = getRectSDF(p, baseSize, 0.0, Base_Offset_Paths);

    // 2. Draw Main Holes
    vec2 aeMainPos = vec2(Main_Position.x, -Main_Position.y);
    vec2 mainSize = vec2(Main_Scale_X, Main_Scale_Y);
    float mainDist = getRepeatedSDF(p, mainSize, Main_Roundness, Main_Offset_Paths, Main_Copies, aeMainPos);

    // 3. Draw Sub Holes (Sprockets)
    vec2 pSub = p;
    float subYOffset = (Base_Scale_Y * 0.25) + (Main_Scale_Y * 0.25);
    pSub.y = abs(p.y) - subYOffset; // Mirror top and bottom

    vec2 aeSubPos = vec2(Sub_Position.x, -Sub_Position.y);
    vec2 subSize = vec2(Sub_Scale_X, Sub_Scale_Y);
    float subDist = getRepeatedSDF(pSub, subSize, Sub_Roundness, Sub_Offset_Paths, Sub_Copies, aeSubPos);

    // Combine holes
    float holeDist = min(mainDist, subDist);

    // BOOLEAN SUBTRACT: Cut the holes out of the base mathematically
    // This allows strokes to outline both the outside edges AND the holes perfectly
    return max(baseDist, -holeDist);
}

void main() {
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    vec2 p = (vUv - 0.5) * resolution; 

    // Master transform offset
    p -= vec2(Global_Position.x, -Global_Position.y);

    // --- APPLY BASE REPEATER TO THE ENTIRE STRIP ---
    float finalStripDist = 999999.0;
    float c = max(1.0, Base_Copies);
    vec2 aeBasePos = vec2(Base_Position.x, -Base_Position.y);
    vec2 startOffset = aeBasePos * (c - 1.0) * 0.5;

    // Loops outer strips (limit 20 to keep frame rates high)
    for(int i = 0; i < 20; i++) {
        if(float(i) >= Base_Copies) break;

        vec2 offset = -startOffset + aeBasePos * float(i);
        // Calculate the completed film strip at this offset
        float d = getSingleStripSDF(p - offset);
        finalStripDist = min(finalStripDist, d);
    }

    float aa = 1.0;

    // Calculate final Alpha based on the combined SDF
    float filmAlpha = 1.0 - smoothstep(0.0, aa, finalStripDist);
    vec4 finalCol = vec4(Base_Color, filmAlpha);

    // Draw Stroke Outline (applies to outer edges and inner holes perfectly!)
    if (Base_Stroke > 0.5) {
        float strokeDist = abs(finalStripDist) - Base_Stroke_Width * 0.5;
        float strokeAlpha = 1.0 - smoothstep(0.0, aa, strokeDist);

        finalCol.rgb = mix(finalCol.rgb, Base_Stroke_Color, strokeAlpha);
        filmAlpha = max(filmAlpha, strokeAlpha);
        finalCol.a = filmAlpha;
    }

    // Composite over background
    vec3 blendedRGB = mix(texel.rgb, finalCol.rgb, finalCol.a);
    float blendedA = texel.a + finalCol.a * (1.0 - texel.a);

    gl_FragColor = vec4(blendedRGB, blendedA);
}

text./plugins/alipfx/shaders/sepia.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Custom Panzoid Properties
uniform float Sepia_Strength;
uniform float Ink_Tone;
uniform float Tint_Density;
uniform float Print_Definition;

void main()
{
    // Sample the original input layer
    vec4 texel = texture2D(tDiffuse, vUvScaled);

    // 1. Calculate the base Luma (Grayscale)
    float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114));

    // 2. Define the Specific Ink Tones
    vec3 toneStandard = vec3(1.0, 0.82, 0.62);  // Classic Warm Sepia
    vec3 toneGold     = vec3(1.0, 0.65, 0.75);  // Pinkish Rose
    vec3 toneCopper   = vec3(0.70, 0.95, 0.60); // Greenish Olive

    // 3. Strict conditional check to prevent color bleeding
    vec3 currentTone;
    if (Ink_Tone < 0.5) {
        currentTone = toneStandard; // Applies to 0 (Standard)
    } else if (Ink_Tone >= 0.5 && Ink_Tone < 1.5) {
        currentTone = toneGold;     // Applies to 1 (Gold)
    } else {
        currentTone = toneCopper;   // Applies to 2 (Copper)
    }

    // 4. Apply Tint Density (Depth of the chemical dye)
    float densityPower = mix(0.4, 1.4, Tint_Density);
    vec3 sepiaBase = pow(vec3(luma), vec3(densityPower)) * currentTone;

    // Boost saturation/brightness slightly at higher densities
    sepiaBase *= mix(0.85, 1.2, Tint_Density);

    // 5. Apply Print Definition (Paper grade / hardness)
    float contrast = mix(0.5, 1.1, Print_Definition);
    vec3 printedColor = (sepiaBase - 0.5) * contrast + 0.5;

    // Lift the black levels for lower print definitions to simulate faded paper
    float blackLift = mix(0.15, 0.0, Print_Definition);
    printedColor += blackLift;

    // Clamp the final processed color
    printedColor = clamp(printedColor, 0.0, 1.0);

    // 6. Apply Sepia Strength
    vec3 finalColor = mix(texel.rgb, printedColor, clamp(Sepia_Strength, 0.0, 1.0));

    // Output the final pixel
    gl_FragColor = vec4(finalColor, texel.a);
}

text./plugins/alipfx/shaders/simple-choker.gl:
