  if (i ==  7) return vec2(-0.705374, -0.668203);
  if (i ==  8) return vec2( 0.977050, -0.108615);
  if (i ==  9) return vec2( 0.063326,  0.142369);
  if (i == 10) return vec2( 0.203528,  0.214331);
  if (i == 11) return vec2(-0.667531,  0.326090);
  if (i == 12) return vec2(-0.098422, -0.295755);
  if (i == 13) return vec2(-0.885922,  0.215369);
  if (i == 14) return vec2( 0.566637,  0.605213);
  if (i == 15) return vec2( 0.039766, -0.396100);
  if (i == 16) return vec2( 0.751946,  0.453352);
  if (i == 17) return vec2( 0.078707, -0.715323);
  if (i == 18) return vec2(-0.075838, -0.529344);
  if (i == 19) return vec2( 0.724479, -0.580798);
  if (i == 20) return vec2( 0.222999, -0.215125);
  if (i == 21) return vec2(-0.467574, -0.405438);
  if (i == 22) return vec2(-0.248268, -0.814753);
  if (i == 23) return vec2( 0.354411, -0.887570);
  if (i == 24) return vec2( 0.175817,  0.382366);
  if (i == 25) return vec2( 0.487472, -0.063082);
  if (i == 26) return vec2(-0.084078,  0.898312);
  if (i == 27) return vec2( 0.488876, -0.783441);
  if (i == 28) return vec2( 0.470016,  0.217933);
  if (i == 29) return vec2(-0.696890, -0.549791);
  if (i == 30) return vec2(-0.149693,  0.605762);
  if (i == 31) return vec2( 0.034211,  0.979980);

  // Next 16 taps (32..47) – denser neighborhood
  if (i == 32) return vec2(-0.934000, -0.121000);
  if (i == 33) return vec2( 0.900000,  0.192000);
  if (i == 34) return vec2(-0.215000,  0.965000);
  if (i == 35) return vec2( 0.246000,  0.827000);
  if (i == 36) return vec2( 0.489000,  0.872000);
  if (i == 37) return vec2(-0.959000,  0.282000);
  if (i == 38) return vec2(-0.373000, -0.114000);
  if (i == 39) return vec2( 0.122000, -0.930000);
  if (i == 40) return vec2( 0.940000, -0.322000);
  if (i == 41) return vec2(-0.562000, -0.015000);
  if (i == 42) return vec2( 0.010000,  0.550000);
  if (i == 43) return vec2(-0.206000,  0.439000);
  if (i == 44) return vec2( 0.622000, -0.019000);
  if (i == 45) return vec2(-0.283000, -0.959000);
  if (i == 46) return vec2( 0.517000, -0.787000);
  if (i == 47) return vec2(-0.739000,  0.012000);

  // Final 16 taps (48..63) – extra fill for smoother “disk”
  if (i == 48) return vec2( 0.833000,  0.520000);
  if (i == 49) return vec2(-0.520000,  0.833000);
  if (i == 50) return vec2(-0.833000, -0.520000);
  if (i == 51) return vec2( 0.520000, -0.833000);
  if (i == 52) return vec2( 0.000000, -0.650000);
  if (i == 53) return vec2( 0.000000,  0.650000);
  if (i == 54) return vec2( 0.650000,  0.000000);
  if (i == 55) return vec2(-0.650000,  0.000000);
  if (i == 56) return vec2( 0.300000,  0.953000);
  if (i == 57) return vec2(-0.300000, -0.953000);
  if (i == 58) return vec2( 0.953000, -0.300000);
  if (i == 59) return vec2(-0.953000,  0.300000);
  if (i == 60) return vec2( 0.707000,  0.707000);
  if (i == 61) return vec2(-0.707000,  0.707000);
  if (i == 62) return vec2( 0.707000, -0.707000);
  if (i == 63) return vec2(-0.707000, -0.707000);

  return vec2(0.0);
}

float chokedAlpha(vec2 uv, float radiusPx, float spreadFlag)
{
  // MIN for choke/erode, MAX for spread/dilate [2](https://www.cs.auckland.ac.nz/courses/compsci773s1c/lectures/ImageProcessing-html/topic4.htm)[1](https://helpx.adobe.com/in_hi/after-effects/using/matte-effects.html)
  float aCenter = texture2D(tDiffuse, uv).a;
  if (radiusPx <= 0.0001) return aCenter;

  vec2 texel = 1.0 / resolution;
  float acc = (spreadFlag > 0.5) ? 0.0 : 1.0;

  if (spreadFlag > 0.5) acc = max(acc, aCenter);
  else                  acc = min(acc, aCenter);

  for (int i = 0; i < TAP_COUNT; i++)
  {
    vec2 off = tapOffset(i) * (radiusPx * texel);
    float sa = texture2D(tDiffuse, clampUv(uv + off)).a;

    if (spreadFlag > 0.5) acc = max(acc, sa);
    else                  acc = min(acc, sa);
  }

  // axis + diagonal stabilizers
  vec2 dx = vec2(radiusPx * texel.x, 0.0);
  vec2 dy = vec2(0.0, radiusPx * texel.y);
  vec2 dd1 = vec2(radiusPx * texel.x,  radiusPx * texel.y);
  vec2 dd2 = vec2(radiusPx * texel.x, -radiusPx * texel.y);

  float ax1 = texture2D(tDiffuse, clampUv(uv + dx)).a;
  float ax2 = texture2D(tDiffuse, clampUv(uv - dx)).a;
  float ay1 = texture2D(tDiffuse, clampUv(uv + dy)).a;
  float ay2 = texture2D(tDiffuse, clampUv(uv - dy)).a;

  float ad1 = texture2D(tDiffuse, clampUv(uv + dd1)).a;
  float ad2 = texture2D(tDiffuse, clampUv(uv - dd1)).a;
  float ad3 = texture2D(tDiffuse, clampUv(uv + dd2)).a;
  float ad4 = texture2D(tDiffuse, clampUv(uv - dd2)).a;

  if (spreadFlag > 0.5) {
    acc = max(acc, max(max(ax1, ax2), max(ay1, ay2)));
    acc = max(acc, max(max(ad1, ad2), max(ad3, ad4)));
  } else {
    acc = min(acc, min(min(ax1, ax2), min(ay1, ay2)));
    acc = min(acc, min(min(ad1, ad2), min(ad3, ad4)));
  }

  return saturate(acc);
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  float r = abs(Choke_Matte);
  float spreadFlag = (Choke_Matte < 0.0) ? 1.0 : 0.0; // AE sign rule [1](https://helpx.adobe.com/in_hi/after-effects/using/matte-effects.html)

  float newA = chokedAlpha(vUvScaled, r, spreadFlag);

  float oldA = texel.a;
  vec3 rgb = texel.rgb;
  if (oldA > 1e-6) rgb *= (newA / oldA);

  vec4 outCol = vec4(rgb, newA);

  // AE-like Matte preview [1](https://helpx.adobe.com/in_hi/after-effects/using/matte-effects.html)
  if (View >= 0.5) {
    gl_FragColor = vec4(vec3(newA), 1.0);
  } else {
    gl_FragColor = outCol;
  }
}

text./plugins/alipfx/shaders/star-trail-motio:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;

// Built-in Panzoid Uniforms
uniform vec2 resolution;

// 1. Length & Width
uniform float Min_Length;
uniform float Length;
uniform float Min_Width;
uniform float Max_Width;

// 2. Range
uniform float Min_Range;
uniform float Max_Range;

// 3. Color
uniform vec3 A;
uniform vec3 B;

// 4. Transform
uniform float Rotation_Speed;
uniform float Speed_Random;
uniform float Opacity;
uniform float Opacity_Random;

// 5. Sharp Line
uniform float Start_Length;
uniform float End_Length;
uniform float Start_Width;
uniform float End_Width;

// 6. Stroke Dash
uniform float Dash;
uniform float Offset;

// 7. Core
uniform float Seed;
uniform float time;

#define NUM_TRAILS 150 // Adjust this to increase/decrease the amount of star trails
#define PI 3.14159265359
#define TWO_PI 6.28318530718

// Pseudo-random number generator
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    // Center the coordinates and calculate polar coordinates
    vec2 p = vUv * resolution - resolution * 0.5;
    float r = length(p);
    float a = atan(p.y, p.x); 

    vec4 bg = texture2D(tDiffuse, vUvScaled);
    vec4 overlay = vec4(0.0);

    // Normalize percentage-based properties (Panzoid numbers are pure floats, dividing by 100 aligns with AE's % UI)
    float minLenRad = (Min_Length / 100.0) * TWO_PI;
    float maxLenRad = (Length / 100.0) * TWO_PI;
    float baseOpac = Opacity / 100.0;
    float spdRandBase = Speed_Random / 100.0;
    float opRandBase = Opacity_Random / 100.0;
    float sLenBase = Start_Length / 100.0;
    float eLenBase = End_Length / 100.0;
    float sWidthBase = Start_Width / 100.0;
    float eWidthBase = End_Width / 100.0;

    for(int i = 0; i < NUM_TRAILS; i++) {
        float fi = float(i);

        // Generate random characteristics for this specific trail based on Seed
        float rndRadius = hash(vec2(fi, Seed));
        float rndWidth  = hash(vec2(fi, Seed + 1.0));
        float rndSpeed  = hash(vec2(fi, Seed + 2.0));
        float rndAngle  = hash(vec2(fi, Seed + 3.0));
        float rndLength = hash(vec2(fi, Seed + 4.0));
        float rndColor  = hash(vec2(fi, Seed + 5.0));
        float rndOpac   = hash(vec2(fi, Seed + 6.0));

        // Range
        float trailRadius = mix(Min_Range, Max_Range, rndRadius);

        // Optimization check: If the pixel is too far from this trail's radius, skip calculations
        float dist = abs(r - trailRadius);
        if(dist > Max_Width * 1.5) continue; 

        // Transform & Rotation
        float currentTrailSpeed = Rotation_Speed * mix(1.0, rndSpeed * 2.0 - 1.0, spdRandBase);
        float timeOffset = time * currentTrailSpeed * 0.1; // 0.1 scales the Panzoid speed nicely
        float baseAngle = rndAngle * TWO_PI;

        // Angle Calculation (Matches AE's clockwise positive rotation)
        float ang = a - baseAngle + timeOffset; 
        ang = mod(mod(ang, TWO_PI) + TWO_PI, TWO_PI); 

        // Line Length
        float trailLen = mix(minLenRad, maxLenRad, rndLength);
        if(ang > trailLen) continue; 

        // Sharp Line (Tapering)
        float trailWidth = mix(Min_Width, Max_Width, rndWidth);
        float widthMult = 1.0;
        float startTaperRad = sLenBase * trailLen;
        float endTaperRad = eLenBase * trailLen;

        if (startTaperRad > 0.0 && ang < startTaperRad) {
            widthMult = mix(sWidthBase, 1.0, ang / startTaperRad);
        } else if (endTaperRad > 0.0 && ang > trailLen - endTaperRad) {
            widthMult = mix(eWidthBase, 1.0, (trailLen - ang) / endTaperRad);
        }

        float currentWidth = trailWidth * widthMult;

        // Render Trail with Anti-aliasing
        float alpha = smoothstep(currentWidth * 0.5 + 0.75, currentWidth * 0.5 - 0.75, dist);

        if (alpha > 0.0) {
            // Stroke Dash
            if(Dash > 0.1) {
                float arcLengthPx = trailRadius * ang; 
                float dashPhase = mod(arcLengthPx - Offset, Dash * 2.0);
                if(dashPhase > Dash) alpha = 0.0;
            }

            if (alpha > 0.0) {
                // Color & Opacity Randomization
                vec3 color = mix(A, B, rndColor);
                float trailAlpha = baseOpac * mix(1.0, rndOpac, opRandBase);
                alpha *= trailAlpha;

                // Composite using pre-multiplied alpha (Front-to-Back accumulation)
                vec4 src = vec4(color * alpha, alpha);
                overlay = src + overlay * (1.0 - src.a);
            }
        }
    }

    // Final blend with the background layer
    gl_FragColor = overlay + bg * (1.0 - overlay.a);
}

text./plugins/alipfx/shaders/stretch.glsl:
precision highp float;
precision highp int;

// Built-in Panzoid Uniforms & Varyings
uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale;
varying vec2 vUv;

// Custom Properties
uniform vec2 Anchor_Point;
uniform float Angle;
uniform float Shift_Amount;
uniform float Direction;

void main()
{
    // 1. Convert current UV to exact pixel coordinates
    vec2 p = vUv * resolution;

    // 2. Match After Effects Coordinate System
    // AE's origin (0,0) is Top-Left. Panzoid's origin is Bottom-Left.
    // We invert the Y coordinate of the Anchor Point to make your values 1:1 with AE.
    vec2 anchor = vec2(Anchor_Point.x, resolution.y - Anchor_Point.y);

    // 3. Calculate Angle Direction
    // In AE, 0 degrees stretches vertically, 90 degrees stretches horizontally.
    float rad = radians(Angle);
    vec2 dir = vec2(sin(rad), cos(rad)); // Clockwise rotation matching AE

    // 4. Calculate Distance from Anchor Line
    vec2 diff = p - anchor;
    float dist = dot(diff, dir); // Distance of current pixel along the stretch direction

    // 5. Apply Shift Cap (10000)
    float S = clamp(abs(Shift_Amount), 0.0, 10000.0);

    // 6. Shift Logic based on Direction parameter
    float dist_src = dist;

    if (Direction < 0.5) {
        // Mode 0: Both
        if (dist > S) {
            dist_src = dist - S;
        } else if (dist < -S) {
            dist_src = dist + S;
        } else {
            // Smeared pixel line in the center
            dist_src = 0.0;
        }
    } else if (Direction < 1.5) {
        // Mode 1: Forward
        if (dist > S) {
            dist_src = dist - S;
        } else if (dist > 0.0) {
            // Smeared forward gap
            dist_src = 0.0; 
        } else {
            // Backward half stays completely still
            dist_src = dist;
        }
    } else {
        // Mode 2: Backward
        if (dist < -S) {
            dist_src = dist + S;
        } else if (dist < 0.0) {
            // Smeared backward gap
            dist_src = 0.0;
        } else {
            // Forward half stays completely still
            dist_src = dist;
        }
    }

    // 7. Reconstruct the target pixel location
    // We displace the pixel backward along the direction vector to find the source pixel
    vec2 p_src = p + dir * (dist_src - dist);

    // 8. Convert back to UV space and render
    vec2 uv_src = p_src / resolution;

    // Crucial Panzoid rule: multiply by uvScale for correct buffer mapping
    vec4 texel = texture2D(tDiffuse, uv_src * uvScale);

    gl_FragColor = texel;
}

text./plugins/alipfx/shaders/take-on-me-paper:
precision highp float;
precision highp int;

// Built-in Panzoid uniforms
uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

// Built-in Panzoid varyings
varying vec2 vUv;
varying vec2 vUvScaled;

// Custom dynamic properties (Create these in your Panzoid properties menu)
uniform float Hatch_Density;     // Recommended range: 0.2 to 1.5
uniform float Outline_Strength;  // Recommended range: 1.0 to 5.0
uniform float Shading_Darkness;  // Recommended range: 0.5 to 1.5

// Helper function to calculate the brightness (luminance) of a pixel
float getLuminance(vec2 uv) {
    vec4 color = texture2D(tDiffuse, uv);
    return dot(color.rgb, vec3(0.299, 0.587, 0.114));
}

void main()
{
    // Calculate 1-pixel step size mapping correctly onto Panzoid's buffer coordinate system
    vec2 st = uvScale / resolution;

    // 3x3 Grid Sampling for Sobel Edge Detection (Outlines)
    float l00 = getLuminance(vUvScaled + vec2(-st.x, -st.y));
    float l10 = getLuminance(vUvScaled + vec2(0.0, -st.y));
    float l20 = getLuminance(vUvScaled + vec2(st.x, -st.y));
    float l01 = getLuminance(vUvScaled + vec2(-st.x, 0.0));
    float l21 = getLuminance(vUvScaled + vec2(st.x, 0.0));
    float l02 = getLuminance(vUvScaled + vec2(-st.x, st.y));
    float l12 = getLuminance(vUvScaled + vec2(0.0, st.y));
    float l22 = getLuminance(vUvScaled + vec2(st.x, st.y));

    // Sobel kernels for horizontal and vertical edge gradients
    float sobX = l00 + 2.0 * l01 + l02 - l20 - 2.0 * l21 - l22;
    float sobY = l00 + 2.0 * l10 + l20 - l02 - 2.0 * l12 - l22;
    float edge = sqrt(sobX * sobX + sobY * sobY);

    // Scale edge detection by your custom property strength
    float outline = smoothstep(0.1, 0.4, edge * Outline_Strength);

    // Get current fragment center luminance
    float currentLum = l10; // re-use center-top or l11 for center
    currentLum = getLuminance(vUvScaled);

    // Convert normalized screenspace UV to absolute pixel positions for noise lines
    vec2 pixelPos = vUv * resolution;

    // Create pencil-like hatching strokes using clean periodic wave frequencies
    float density = Hatch_Density > 0.0 ? Hatch_Density : 0.6;
    float line1 = abs(sin((pixelPos.x + pixelPos.y) * density));
    float line2 = abs(sin((pixelPos.x - pixelPos.y) * density));

    // Classical "Take On Me" background/paper colors (Light slate blue-gray paper)
    vec3 paperColor = vec3(0.84, 0.89, 0.94); 
    vec3 graphiteColor = vec3(0.12, 0.16, 0.22); // Dark sketch charcoal pencil ink

    // Determine shading based on luminance levels (cross-hatching thresholding)
    float sketchFactor = 1.0;

    // Mid-tones: Apply first diagonal pencil strokes
    if (currentLum < 0.75) {
        if (line1 < 0.25) {
            sketchFactor *= mix(1.0, currentLum, Shading_Darkness);
        }
    }
    // Shadows: Cross-hatch with opposing diagonal lines
    if (currentLum < 0.45) {
        if (line2 < 0.3) {
            sketchFactor *= mix(1.0, currentLum * 0.8, Shading_Darkness);
        }
    }
    // Deep Shadows: Fill in solid dark graphite spots
    if (currentLum < 0.18) {
        sketchFactor *= 0.4;
    }

    // Force outlines to be drawn as dark pencil ink lines
    sketchFactor = mix(sketchFactor, 0.0, outline);

    // Mix final pencil shading with the background sketch paper tint
    vec3 finalColor = mix(graphiteColor, paperColor, sketchFactor);

    gl_FragColor = vec4(finalColor, 1.0);
}

text./plugins/alipfx/shaders/texgraph.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
uniform vec2 uvScale;
uniform vec2 resolution;

// Panzoid Custom Properties Map
uniform float Scale;
uniform float Erode;
uniform float Dither_Level;
uniform float Text_Color_from_SRC;
uniform float Text_BG_Color_from_SRC;
uniform vec3 Text_Color;
uniform vec3 Text_BG_Color;
uniform float Text_BG_Alpha;

// Pseudo-random hash function for selecting characters & dithering
float hash12(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Bit extractor for the procedural 3x5 font grid
float getBit(float n, vec2 p) {
    if (p.x < 0.0 || p.x > 2.0 || p.y < 0.0 || p.y > 4.0) return 0.0;
    float bitPos = p.x + p.y * 3.0;
    // float arithmetic for WebGL 1 cross-compatibility
    return mod(floor(n / exp2(bitPos)), 2.0);
}

// 16 alphanumeric characters compressed into 15-bit float masks
float getCharMask(int index) {
    if(index == 0) return 31599.0; // 0 / O
    if(index == 1) return 29874.0; // 1
    if(index == 2) return 29671.0; // 2
    if(index == 3) return 31207.0; // 3
    if(index == 4) return 23497.0; // 4
    if(index == 5) return 31183.0; // 5
    if(index == 6) return 31215.0; // 6
    if(index == 7) return 29257.0; // 7
    if(index == 8) return 31727.0; // 8 / B
    if(index == 9) return 31711.0; // 9
    if(index == 10) return 23533.0; // H
    if(index == 11) return 29647.0; // E
    if(index == 12) return 29263.0; // C
    if(index == 13) return 27503.0; // D
    if(index == 14) return 11115.0; // L
    if(index == 15) return 23182.0; // S
    return 31599.0;
}

void main() {
    // Prevent zero division, actual text sizing logic
    float actualScale = max(Scale, 1.0);

    // Font is 3x5 pixels. We use a 4x6 block to include 1px spacing horizontally and vertically.
    vec2 blockSize = actualScale * vec2(4.0, 6.0);

    // Pixel coordinate handling mapped to screen resolution
    vec2 fragCoord = (vUvScaled / uvScale) * resolution;

    // Grid coordinates
    vec2 blockPos = floor(fragCoord / blockSize);

    // Coordinates within the current grid cell (normalized 0.0 - 1.0)
    vec2 localUv = fract(fragCoord / blockSize);

    // Coordinate mapping to our specific 4x6 pixel setup
    vec2 charPixel = floor(localUv * vec2(4.0, 6.0));

    // Sample the center of the block for accurate source coloring
    vec2 blockCenter = (blockPos + 0.5) * blockSize;
    vec2 sampleUv = (blockCenter / resolution) * uvScale;

    vec4 srcColor = texture2D(tDiffuse, sampleUv);

    // Generate random seed per block
    float randVal = hash12(blockPos);

    // Select random alphanumeric character from our dictionary (0 to 15)
    int charIdx = int(mod(randVal * 16.0, 16.0));
    float charMask = getCharMask(charIdx);

    float isText = 0.0;

    // Constrain rendering strictly within the 3x5 area, leaving a gap.
    if (charPixel.x < 3.0 && charPixel.y < 5.0) {
        isText = getBit(charMask, charPixel);

        // ERODE Logic: Thickens the contour line mathematically
        if (Erode >= 1.0 && isText == 0.0) {
            float n1 = getBit(charMask, charPixel + vec2(1.0, 0.0));
            float n2 = getBit(charMask, charPixel - vec2(1.0, 0.0));
            float n3 = getBit(charMask, charPixel + vec2(0.0, 1.0));
            float n4 = getBit(charMask, charPixel - vec2(0.0, 1.0));
            isText = max(max(n1, n2), max(n3, n4));
        }
    }

    // Source Luminance Calculation for Masking
    float lum = dot(srcColor.rgb, vec3(0.299, 0.587, 0.114));

    // DITHER Logic: Adjusts text placement probability across gradients
    float thresholdNoise = fract(randVal * 43.123);
    float ditherOffset = (thresholdNoise - 0.5) * (Dither_Level * 0.1);
    float adjustedLum = lum + ditherOffset;

    // Density Cutoff: Hides text in pure black/dark areas to map original image contours
    if (adjustedLum < 0.15 || srcColor.a < 0.1) {
        isText = 0.0;
    }

    // Process Text Color Configuration
    vec3 finalTextColor = Text_Color;
    if (Text_Color_from_SRC > 0.5) {
        finalTextColor = srcColor.rgb;
    }

    // Process Background Color Configuration
    vec3 finalBgColor = Text_BG_Color;
    if (Text_BG_Color_from_SRC > 0.5) {
        finalBgColor = srcColor.rgb;
    }

    // Normalize Alpha channel based on the 0-255 parameter
    float bgAlpha = clamp(Text_BG_Alpha / 255.0, 0.0, 1.0);
    vec4 bgColorOutput = vec4(finalBgColor, bgAlpha);
    vec4 textColorOutput = vec4(finalTextColor, 1.0); // Text itself is always opaque

    // Final compositor
    gl_FragColor = mix(bgColorOutput, textColorOutput, isText);
}

text./plugins/alipfx/shaders/the-matrix-2.gls:
precision highp float;
precision highp int;

// --- Panzoid Built-in Variables ---
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;

// --- Custom Panzoid Properties ---
// IMPORTANT: You must create dynamic number properties named "time" and "ALPHA_MODE" in Panzoid!
uniform float time;
uniform float ALPHA_MODE; // 0.0 = Solid Background, 1.0 = Transparent Overlay

// --- Shader Constants ---
const int ITERATIONS = 5;
const float SPEED = 2.0;

const float STRIP_CHARS_MIN =  3.0;
const float STRIP_CHARS_MAX = 40.0;
const float STRIP_CHAR_HEIGHT = 0.10;
const float STRIP_CHAR_WIDTH = 0.15;
const float ZCELL_SIZE = 1.0 * (STRIP_CHAR_HEIGHT * STRIP_CHARS_MAX);
const float XYCELL_SIZE = 12.0 * STRIP_CHAR_WIDTH;
const int BLOCK_SIZE = 8;
const int BLOCK_GAP = 0;

const float PI = 3.14159265359;

// --- Helper Functions ---
float hash(float v) {
    return fract(sin(v)*43758.5453123);
}

float hash(vec2 v) {
    return hash(dot(v, vec2(5.3983, 5.4427)));
}

vec2 hash2(vec2 v) {
    return fract(sin(v)*43758.5453123);
}

// Converted mat4x2 to dot products for standard WebGL 1.0 compatibility
vec4 hash4(vec2 v) {
    vec4 p = vec4(
        dot(v, vec2(127.1, 311.7)),
        dot(v, vec2(269.5, 183.3)),
        dot(v, vec2(113.5, 271.9)),
        dot(v, vec2(246.1, 124.6))
    );
    return fract(sin(p)*43758.5453123);
}

// Converted mat4x3 to dot products for standard WebGL 1.0 compatibility
vec4 hash4(vec3 v) {
    vec4 p = vec4(
        dot(v, vec3(127.1, 311.7, 74.7)),
        dot(v, vec3(269.5, 183.3, 246.1)),
        dot(v, vec3(113.5, 271.9, 124.6)),
        dot(v, vec3(271.9, 269.5, 311.7))
    );
    return fract(sin(p)*43758.5453123);
}

float rune_line(vec2 p, vec2 a, vec2 b) {
    p -= a; b -= a;
    float h = clamp(dot(p, b) / dot(b, b), 0.0, 1.0);
    return length(p - b * h);
}

float rune(vec2 U, vec2 seed, float highlight) {
    float d = 1e5;
    for (int i = 0; i < 4; i++) {
        vec4 pos = hash4(seed);
        seed += 1.0;

        if (i == 0) pos.y = 0.0;
        if (i == 1) pos.x = 0.999;
        if (i == 2) pos.x = 0.0;
        if (i == 3) pos.y = 0.999;

        vec4 snaps = vec4(2.0, 3.0, 2.0, 3.0);
        pos = (floor(pos * snaps) + 0.5) / snaps;

        if (pos.xy != pos.zw) {
            d = min(d, rune_line(U, pos.xy, pos.zw + 0.001));
        }
    }
    return smoothstep(0.1, 0.0, d) + highlight*smoothstep(0.4, 0.0, d);
}

float random_char(vec2 outer, vec2 inner, float highlight) {
    vec2 seed = vec2(dot(outer, vec2(269.5, 183.3)), dot(outer, vec2(113.5, 271.9)));
    return rune(inner, seed, highlight);
}

// Changed to return vec4 to pass both color and alpha
vec4 rain(vec3 ro3, vec3 rd3, float t) {
    vec4 result = vec4(0.0);

    vec2 ro2 = normalize(ro3.xy);
    vec2 rd2 = normalize(rd3.xy);

    bool prefer_dx = abs(rd2.x) > abs(rd2.y);
    float t3_to_t2 = prefer_dx ? rd3.x / rd2.x : rd3.y / rd2.y;

    ivec3 cell_side = ivec3(step(0.0, rd3));
    ivec3 cell_shift = ivec3(sign(rd3));

    float t2 = 0.0;
    ivec2 next_cell = ivec2(floor(ro2/XYCELL_SIZE));

    for (int i=0; i<ITERATIONS; i++) {
        ivec2 cell = next_cell;
        float t2s = t2;

        vec2 side = vec2(next_cell + cell_side.xy) * XYCELL_SIZE;
        vec2 t2_side = (side - ro2) / rd2;
        if (t2_side.x < t2_side.y) {
            t2 = t2_side.x;
            next_cell.x += cell_shift.x;
        } else {
            t2 = t2_side.y;
            next_cell.y += cell_shift.y;
        }

        vec2 cell_in_block = fract(vec2(cell) / float(BLOCK_SIZE));
        float gap = float(BLOCK_GAP) / float(BLOCK_SIZE);
        if (cell_in_block.x < gap || cell_in_block.y < gap || (cell_in_block.x < (gap+0.1) && cell_in_block.y < (gap+0.1))) {
            continue;
        }

        float t3s = t2s / t3_to_t2;
        float pos_z = ro3.z + rd3.z * t3s;
        float xycell_hash = hash(vec2(cell));
        float z_shift = xycell_hash*11.0 - t * (0.5 + xycell_hash * 1.0 + xycell_hash * xycell_hash * 1.0 + pow(xycell_hash, 16.0) * 3.0);
        float char_z_shift = floor(z_shift / STRIP_CHAR_HEIGHT);
        z_shift = char_z_shift * STRIP_CHAR_HEIGHT;
        int zcell = int(floor((pos_z - z_shift)/ZCELL_SIZE));

        for (int j=0; j<2; j++) {
            vec4 cell_hash = hash4(vec3(float(cell.x), float(cell.y), float(zcell)));
            vec4 cell_hash2 = fract(cell_hash * vec4(127.1, 311.7, 271.9, 124.6));

            float chars_count = cell_hash.w * (STRIP_CHARS_MAX - STRIP_CHARS_MIN) + STRIP_CHARS_MIN;
            float target_length = chars_count * STRIP_CHAR_HEIGHT;
            float target_rad = STRIP_CHAR_WIDTH / 2.0;
            float target_z = (float(zcell)*ZCELL_SIZE + z_shift) + cell_hash.z * (ZCELL_SIZE - target_length);
            vec2 target = vec2(cell) * XYCELL_SIZE + target_rad + cell_hash.xy * (XYCELL_SIZE - target_rad*2.0);

            vec2 s = target - ro2;
            float tmin = dot(s, rd2);
            if (tmin >= t2s && tmin <= t2) {
                float u = s.x * rd2.y - s.y * rd2.x;
                if (abs(u) < target_rad) {
                    u = (u/target_rad + 1.0) / 2.0;
                    float z = ro3.z + rd3.z * tmin/t3_to_t2;
                    float v = (z - target_z) / target_length;
                    if (v >= 0.0 && v < 1.0) {
                        float c = floor(v * chars_count);
                        float q = fract(v * chars_count);
                        vec2 char_hash = hash2(vec2(c+char_z_shift, cell_hash2.x));
                        if (char_hash.x >= 0.1 || c == 0.0) {
                            float time_factor = floor(c == 0.0 ? t*5.0 : 
                                t*(1.0*cell_hash2.z + cell_hash2.w*cell_hash2.w*4.0*pow(char_hash.y, 4.0)));
                            float a = random_char(vec2(char_hash.x, time_factor), vec2(u,q), max(1.0, 3.0 - c/2.0)*0.2);
                            a *= clamp((chars_count - 0.5 - c) / 2.0, 0.0, 1.0);
                            if (a > 0.0) {
                                float attenuation = 1.0 + pow(0.06*tmin/t3_to_t2, 2.0);
                                vec3 c_col = (c == 0.0 ? vec3(0.67, 1.0, 0.82) : vec3(0.25, 0.80, 0.40)) / attenuation;
                                float a1 = result.a;
                                result.a = a1 + (1.0 - a1) * a;
                                result.xyz = (result.xyz * a1 + c_col * (1.0 - a1) * a) / result.a;
                                if (result.a > 0.98) return result;
                            }
                        }
                    }
                }
            }
            zcell += cell_shift.z;
        }
    }
    return result;
}

// --- Main Panzoid Entry Point ---
void main() {
    if (STRIP_CHAR_WIDTH > XYCELL_SIZE || STRIP_CHAR_HEIGHT * STRIP_CHARS_MAX > ZCELL_SIZE) {
        gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);
        return;
    }

    vec2 uv = (vUv * 2.0 - 1.0) * (resolution / resolution.y);
    float t = time * SPEED;

    float level1_size = float(BLOCK_SIZE) * XYCELL_SIZE;
    float gap_size = float(BLOCK_GAP) * XYCELL_SIZE;

    vec3 ro = vec3(gap_size/2.0, gap_size/2.0, 0.0);
    vec3 rd = vec3(uv.x, 2.0, uv.y);

    vec2 p = vec2(0.0);
    ro.xy += level1_size * p;

    ro += rd * 0.2;
    rd = normalize(rd);

    // Get color and alpha composition from rain calculations
    vec4 rain_out = rain(ro, rd, t);

    // Fetch the original layer behind the shader effect
    vec4 background = texture2D(tDiffuse, vUvScaled);

    if (ALPHA_MODE > 0.5) {
        // Transparent Overlay Mode: blend matrix over background
        gl_FragColor = vec4(mix(background.rgb, rain_out.xyz, rain_out.a), background.a);
    } else {
        // Solid Background Mode: display on pure black backdrop
        gl_FragColor = vec4(rain_out.xyz * rain_out.a, 1.0);
    }
}

text./plugins/alipfx/shaders/the-matrix.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

// --- PANZOID CUSTOM PROPERTIES ---
uniform float Time;        // Dynamic number to drive upward speed
uniform float Frequency;   // Controls stream density (e.g., 0.15)
uniform float Alpha_mode;  // Checkbox / Toggle for transparency mode (0.0 = Off, 1.0 = On)

varying vec2 vUv;
varying vec2 vUvScaled;

// Simple random hash function
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main()
{
    // Grab whatever background/text layer is underneath
    vec4 baseTex = texture2D(tDiffuse, vUvScaled);

    // Grid resolution: X is columns, Y is vertical character stacking
    vec2 gridResolution = vec2(40.0, 25.0);
    vec2 st = vUv * gridResolution;

    vec2 ipos = floor(st); // Column and Row integer ID
    vec2 fpos = fract(st); // Local 0.0 to 1.0 position inside a text block

    // Give each vertical column its own unique speed multiplier
    float colRandom = hash(vec2(ipos.x, 55.33));
    float speed = 4.0 + colRandom * 4.0;

    // Animate coordinates downward to make the visual texture stream UPWARD
    float movingY = st.y - (Time * speed);
    float iposY = floor(movingY);

    // --- FREQUENCY & SPARSITY ---
    float packetId = floor(movingY / 12.0); 
    float spawnChance = hash(vec2(ipos.x, packetId));
    float visibility = step(1.0 - Frequency, spawnChance);

    // Make the digital characters morph/flicker over time
    float changeTime = floor(Time * 15.0 + colRandom * 20.0);
    float charRandom = hash(vec2(ipos.x, iposY + changeTime));

    // Procedural Glyph Generator (Creates matrix-style blocky code characters)
    float glyph = 0.0;
    vec2 subGrid = floor(fpos * 3.5); 
    float subHash = hash(subGrid + vec2(charRandom));
    if (subHash > 0.4 && fpos.x > 0.1 && fpos.x < 0.9 && fpos.y > 0.1 && fpos.y < 0.9) {
        glyph = 1.0;
    }

    // Upward fade trail: Brightest at the top head, fading out downwards
    float trail = fract(movingY * 0.08);

    // Intense glowing head at the tip of the climbing stream
    float headGlow = step(0.92, trail) * 2.5;

    // Calculate alpha channels for the effect (Feather logic is gone!)
    float finalAlpha = trail * hash(vec2(ipos.x, iposY)) * glyph * visibility;
    float finalGlow = headGlow * glyph * visibility;

    // Build the Matrix Green color profile
    vec3 matrixColor = vec3(0.0, 0.9, 0.25) * finalAlpha;       // Main code stream
    matrixColor += vec3(0.7, 1.0, 0.8) * finalGlow;             // Bright white-green tip
    matrixColor += vec3(0.0, 0.25, 0.05) * trail * 0.2 * visibility; // Soft column glow

    // Composite color additively over background elements
    vec3 finalOutColor = baseTex.rgb + matrixColor;

    // --- ALPHA / TRANSPARENCY MODE LOGIC ---
    float outAlpha = baseTex.a;

    if (Alpha_mode > 0.5) {
        // Find the total visibility strength of the matrix effect itself
        float matrixAlphaMax = clamp(finalAlpha + finalGlow, 0.0, 1.0);

        // If the background pixel is completely black, turn it transparent
        if (baseTex.rgb == vec3(0.0)) {
            outAlpha = matrixAlphaMax;
        } else {
            outAlpha = max(baseTex.a, matrixAlphaMax);
        }
    }

    // Output the final pixel with transparency adjustments
    gl_FragColor = vec4(finalOutColor, outAlpha);
}

text./plugins/alipfx/shaders/threshold.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform float Level;

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // AE-like 8-bpc scaling: 0..256 -> 0..1
  float level01;
  if (Level <= 1.0) {
    level01 = Level;
  } else {
    level01 = Level / 256.0;
  }
  level01 = clamp(level01, 0.0, 1.0);

  // Rec.709 luma / relative luminance coefficients
  // (0.2126, 0.7152, 0.0722)
  float luma709 = dot(texel.rgb, vec3(0.2126, 0.7152, 0.0722));

  // Threshold: white if luma >= level, else black
  float bw = step(level01, luma709);

  gl_FragColor = vec4(vec3(bw), texel.a);
}

text./plugins/alipfx/shaders/tint.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/* Panzoid custom properties (created in the UI) */
uniform vec3 Map_Black_To;     // Color
uniform vec3 Map_White_To;     // Color
uniform float Amount_to_Tint;  // Number (0..100 like AE)
uniform float Swap_Colors;     // Number (0 or 1)

float getLuma(vec3 c)
{
  // NTSC / “perceived” luma weights
  return dot(c, vec3(0.299, 0.587, 0.114));
}

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  // --- Amount to Tint: strict AE percent 0..100 ---
  float amt = clamp(Amount_to_Tint, 0.0, 100.0) / 100.0;

  // --- Swap colors (0 = normal, 1 = swapped) ---
  float s = step(0.5, Swap_Colors); // >= 0.5 counts as "on"
  vec3 blackMap = mix(Map_Black_To, Map_White_To, s);
  vec3 whiteMap = mix(Map_White_To, Map_Black_To, s);

  // --- Luminance mapping ---
  float luma = clamp(getLuma(texel.rgb), 0.0, 1.0);
  vec3 tinted = mix(blackMap, whiteMap, luma);

  // --- Blend original <-> tinted ---
  vec3 outRgb = mix(texel.rgb, tinted, amt);

  // Preserve original alpha
  gl_FragColor = vec4(outRgb, texel.a);
}

text./plugins/alipfx/shaders/transform.glsl:
precision highp float;
precision highp int;

// ---- Panzoid built-ins ----
uniform sampler2D tDiffuse;
uniform vec2      resolution;
varying vec2      vUvScaled;

// ---- AE Transform-style uniforms (12 parameters) ----
uniform vec2  Anchor_Point;                    // pixels (layer space)
uniform vec2  Position;                        // pixels (comp space)
uniform float Uniform_Scale;                   // 0 or 1
uniform float Scale_Height;                    // percent
uniform float Scale_Width;                     // percent
uniform float Skew;                            // degrees
uniform float Skew_Axis;                       // degrees
uniform float Rotation;                        // degrees
uniform float Opacity;                         // percent
uniform float Use_Composition_Shutter_Angle;   // kept for UI compatibility (no-op here)
uniform float Shutter_Angle;                   // kept for UI compatibility (no-op here)
uniform float Sampling;                        // 0: bilinear, 1: bicubic

// ------------------------------
// Helpers
// ------------------------------
float pctToFactor(float pct) { return pct * 0.01; }

// Mitchell-Netravali weights (B=C=1/3) — high quality bicubic
float mnWeight(float x) {
    const float B = 1.0/3.0;
    const float C = 1.0/3.0;
    float ax = abs(x);
    float ax2 = ax * ax;
    float ax3 = ax2 * ax;
    if (ax < 1.0) {
        return ((12.0 - 9.0*B - 6.0*C) * ax3 +
                (-18.0 + 12.0*B + 6.0*C) * ax2 +
                (6.0 - 2.0*B)) * ax;
    } else if (ax < 2.0) {
        return ((-B - 6.0*C) * ax3 +
                (6.0*B + 30.0*C) * ax2 +
                (-12.0*B - 48.0*C) * ax +
                (8.0*B + 24.0*C));
    }
    return 0.0;
}

vec4 sampleTexBilinear(vec2 uv01) {
    if (uv01.x < 0.0 || uv01.x > 1.0 || uv01.y < 0.0 || uv01.y > 1.0) return vec4(0.0);
    return texture2D(tDiffuse, uv01);
}

// True bicubic 16-tap (Mitchell-Netravali)
vec4 sampleBicubic(sampler2D tex, vec2 uv, vec2 texSize) {
    vec2 xy  = uv * texSize - 0.5;
    vec2 ixy = floor(xy);
    vec2 fxy = xy - ixy;

    vec4 col = vec4(0.0);
    float wSum = 0.0;

    for (int j = -1; j <= 2; ++j) {
        float wy = mnWeight(float(j) - fxy.y);
        float y  = (ixy.y + float(j)) / texSize.y;

        for (int i = -1; i <= 2; ++i) {
            float wx = mnWeight(float(i) - fxy.x);
            float x  = (ixy.x + float(i)) / texSize.x;

            float w = wx * wy;
            col += texture2D(tex, vec2(x, y)) * w;
            wSum += w;
        }
    }
    return col / wSum;
}

vec4 sampleTexHQ(vec2 uv01) {
    if (uv01.x < 0.0 || uv01.x > 1.0 || uv01.y < 0.0 || uv01.y > 1.0) return vec4(0.0);
    return sampleBicubic(tDiffuse, uv01, resolution);
}

// -----------------------------------------
// AE Position fix is implemented here:
//
// Forward AE-style (effect):
//   P_out = Position + R * Sh * S * (P_in - Anchor)
//
// Inverse used for sampling:
//   P_in = Anchor + S^-1 * Sh^-1 * R^-1 * (P_out - Position)
// -----------------------------------------
vec2 inverseMapPixel_AE(
    vec2 P_out,
    vec2 anchor,
    vec2 position,
    float scaleH_pct,
    float scaleW_pct,
    float uniformScale,
    float skewDeg,
    float skewAxisDeg,
    float rotationDeg
) {
    // Scale factors
    float sY = pctToFactor(scaleH_pct);
    float sX = (uniformScale >= 0.5) ? sY : pctToFactor(scaleW_pct);

    // Common fast path: no scale/rot/skew
    bool noRot  = abs(rotationDeg) < 1e-6;
    bool noSkew = abs(skewDeg)     < 1e-6;
    bool unitScale = (abs(sX - 1.0) < 1e-6) && (abs(sY - 1.0) < 1e-6);

    if (noRot && noSkew && unitScale) {
        // With AE mapping:
        // P_in = P_out - Position + Anchor
        return P_out - position + anchor;
    }

    // AE FIX: subtract ONLY Position (not Position+Anchor)
    vec2 p = P_out - position;

    // Inverse rotation (R^-1 = R(-rot))
    float rr = radians(-rotationDeg);
    float cr = cos(rr), sr = sin(rr);
    p = vec2(cr*p.x - sr*p.y, sr*p.x + cr*p.y);

    // Inverse skew about axis: R(axis) * Shx(-k) * R(-axis)
    if (!noSkew) {
        float k  = -tan(radians(skewDeg));
        float aa = radians(skewAxisDeg);
        float ca = cos(aa), sa = sin(aa);

        // q = R(-axis) * p
        vec2 q = vec2( ca*p.x + sa*p.y,
                      -sa*p.x + ca*p.y );

        // shear in x
        q.x = q.x + k * q.y;

        // p = R(axis) * q
        p = vec2( ca*q.x - sa*q.y,
                  sa*q.x + ca*q.y );
    }

    // Inverse scale
    float inv_sX = (abs(sX) > 1e-6) ? (1.0 / sX) : 0.0;
    float inv_sY = (abs(sY) > 1e-6) ? (1.0 / sY) : 0.0;
    p *= vec2(inv_sX, inv_sY);

    // Add Anchor at the end (AE)
    return p + anchor;
}

void main() {
    // Opacity early-out
    float op = clamp(Opacity * 0.01, 0.0, 1.0);
    if (op <= 0.00001) {
        gl_FragColor = vec4(0.0);
        return;
    }

    // Output pixel in comp/layer pixel space
    vec2 P_out = vUvScaled * resolution;

    // Inverse map to source pixel using AE-correct Position behavior
    vec2 P_in = inverseMapPixel_AE(
        P_out,
        Anchor_Point,
        Position,
        Scale_Height,
        Scale_Width,
        Uniform_Scale,
        Skew,
        Skew_Axis,
        Rotation
    );

    vec2 uv_src = P_in / resolution;

    // Sampling mode
    vec4 color = (Sampling >= 0.5) ? sampleTexHQ(uv_src) : sampleTexBilinear(uv_src);

    // Apply opacity AE-style
    color.rgb *= op;
    color.a   *= op;

    gl_FragColor = color;
}

text./plugins/alipfx/shaders/tritone.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// Built-ins (Panzoid provides these)
uniform vec2 resolution;
uniform vec2 uvScale;

// ---- Custom properties (Panzoid) ----
uniform vec3 Highlights;
uniform vec3 Midtones;
uniform vec3 Shadows;
uniform float Blend_With_Original;

// ============================================================
// Optional: sRGB <-> Linear conversions (leave OFF unless needed)
// ============================================================
#define USE_SRGB_CONVERSION 0

vec3 srgbToLinear(vec3 c) {
  vec3 low  = c / 12.92;
  vec3 high = pow((c + 0.055) / 1.055, vec3(2.4));
  return mix(high, low, step(c, vec3(0.04045)));
}

vec3 linearToSrgb(vec3 c) {
  vec3 low  = c * 12.92;
  vec3 high = 1.055 * pow(max(c, vec3(0.0)), vec3(1.0/2.4)) - 0.055;
  return mix(high, low, step(c, vec3(0.0031308)));
}

float luminance709(vec3 rgbLinear) {
  return dot(rgbLinear, vec3(0.2126, 0.7152, 0.0722));
}

void main()
{
  // EDGE FIX #1: Clamp UVs slightly inward to avoid border sampling
  vec2 texelSize = 1.0 / (resolution * uvScale);
  vec2 eps = 0.5 * texelSize;                 // half-texel inset
  vec2 uv = clamp(vUvScaled, eps, 1.0 - eps); // clamp inside bounds

  vec4 texel = texture2D(tDiffuse, uv);

  // EDGE FIX #2: Handle premultiplied alpha to prevent fringe/tint
  float a = texel.a;
  vec3 src = (a > 0.0) ? (texel.rgb / a) : vec3(0.0); // unpremultiply

  // --- Blend With Original: STRICT 0..100 (%), AE-like ---
  float blend = clamp(Blend_With_Original / 100.0, 0.0, 1.0);

  // --- Work space ---
  vec3 srcWork = src;
  vec3 hiWork  = Highlights;
  vec3 midWork = Midtones;
  vec3 shWork  = Shadows;

#if USE_SRGB_CONVERSION
  srcWork = srgbToLinear(srcWork);
  hiWork  = srgbToLinear(hiWork);
  midWork = srgbToLinear(midWork);
  shWork  = srgbToLinear(shWork);
#endif

  // --- Brightness -> Tritone ramp ---
  float luma = clamp(luminance709(srcWork), 0.0, 1.0);

  vec3 tri;
  if (luma < 0.5) {
    tri = mix(shWork, midWork, luma * 2.0);
  } else {
    tri = mix(midWork, hiWork, (luma - 0.5) * 2.0);
  }

  // --- Blend back with original (0% = full effect, 100% = original) ---
  vec3 outWork = mix(tri, srcWork, blend);

#if USE_SRGB_CONVERSION
  vec3 outRgb = linearToSrgb(outWork);
#else
  vec3 outRgb = outWork;
#endif

  // Re-premultiply so compositing is clean
  outRgb *= a;

  gl_FragColor = vec4(outRgb, a);
}

text./plugins/alipfx/shaders/turbulent-displa:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
uniform vec2 uvScale; // CRITICAL for Panzoid texturing
varying vec2 vUv;
varying vec2 vUvScaled;

// Custom properties
// NOTE: If you make properties like Displacement or Pinning "Static" in Panzoid, 
// remove their 'uniform' declarations below, as Panzoid auto-injects them via #define.
uniform int Displacement;            // 0-8
uniform float Amount;                // Intensity (pixels)
uniform float Size;                  // Scale
uniform vec2 Offset;                 // Offset (Turbulence)
uniform float Complexity;            // Detail level
uniform float Evolution;             // Time animation (in degrees)
uniform int Cycle_Evolution;         // 0 or 1
uniform float Cycle_in_Revolutions;  // Loop cycles
uniform float Random_Seed;           // Noise seed
uniform int Pinning;                 // 0-14
uniform int Resize_Layer;            // 0 or 1
uniform int Antialiasing_for_Best_Quality; // 0 or 1

// Simplex noise function
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                       -0.577350269189626, 0.024390243902439);
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod289(i);
    vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
                   + i.x + vec3(0.0, i1.x, 1.0));
    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
                            dot(x12.zw,x12.zw)), 0.0);
    m = m*m;
    m = m*m;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
    vec3 g;
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

float deg2rad(float degrees) {
    return degrees * 0.017453292519943295;
}

// Fractal noise generator
float fractalNoise(vec2 uv, float complexity, float evolution, float seed) {
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 1.0;

    // Seed Offset
    uv += vec2(seed * 100.0);

    // Evolution Translation (Simple approach, accurate 3D requires 3D noise)
    float evoRad = deg2rad(evolution) * 0.1;
    uv += vec2(cos(evoRad), sin(evoRad)) * evolution * 0.005; // Adds a swirling effect

    for (int i = 0; i < 8; i++) {
        if (float(i) >= complexity) break;
        value += amplitude * snoise(uv * frequency);
        frequency *= 2.0;
        amplitude *= 0.5;
    }

    float frac = fract(complexity);
    if (frac > 0.0 && complexity > 0.0 && complexity < 8.0) {
        value += frac * amplitude * snoise(uv * frequency);
    }
    return value;
}

float getEvolvedValue(float baseEvolution, int cycleEnabled, float cycleRevolutions) {
    if (cycleEnabled == 1 && cycleRevolutions > 0.0) {
        float totalDegrees = cycleRevolutions * 360.0;
        return mod(baseEvolution, totalDegrees);
    }
    return baseEvolution;
}

vec2 getPinningMask(vec2 uv, int pinMode) {
    vec2 mask = vec2(1.0);
    float leftDist = uv.x;
    float rightDist = 1.0 - uv.x;
    float bottomDist = uv.y;
    float topDist = 1.0 - uv.y;

    float smth = 0.05;
    float lckSmth = 0.01;
    float falloff = 0.05;

    if (pinMode == 1) { mask.x = smoothstep(0.0, smth, min(leftDist, rightDist)); mask.y = smoothstep(0.0, smth, min(bottomDist, topDist)); }
    else if (pinMode == 2) { mask.x = smoothstep(0.0, smth, min(leftDist, rightDist)); }
    else if (pinMode == 3) { mask.y = smoothstep(0.0, smth, min(bottomDist, topDist)); }
    else if (pinMode == 4) { mask.x = smoothstep(0.0, smth, leftDist); }
    else if (pinMode == 5) { mask.x = smoothstep(0.0, smth, rightDist); }
    else if (pinMode == 6) { mask.y = smoothstep(0.0, smth, topDist); }
    else if (pinMode == 7) { mask.y = smoothstep(0.0, smth, bottomDist); }
    else if (pinMode == 8) { 
        mask.x = smoothstep(0.0, lckSmth, min(leftDist, rightDist)) * smoothstep(0.0, falloff, min(leftDist, rightDist)); 
        mask.y = smoothstep(0.0, lckSmth, min(bottomDist, topDist)) * smoothstep(0.0, falloff, min(bottomDist, topDist)); 
    }
    else if (pinMode == 9) { mask.x = smoothstep(0.0, lckSmth, min(leftDist, rightDist)) * smoothstep(0.0, falloff, min(leftDist, rightDist)); }
    else if (pinMode == 10) { mask.y = smoothstep(0.0, lckSmth, min(bottomDist, topDist)) * smoothstep(0.0, falloff, min(bottomDist, topDist)); }
    else if (pinMode == 11) { mask.x = smoothstep(0.0, lckSmth, leftDist) * smoothstep(0.0, falloff, leftDist); }
    else if (pinMode == 12) { mask.x = smoothstep(0.0, lckSmth, rightDist) * smoothstep(0.0, falloff, rightDist); }
    else if (pinMode == 13) { mask.y = smoothstep(0.0, lckSmth, topDist) * smoothstep(0.0, falloff, topDist); }
    else if (pinMode == 14) { mask.y = smoothstep(0.0, lckSmth, bottomDist) * smoothstep(0.0, falloff, bottomDist); }

    return mask;
}

vec2 applyDisplacement(vec2 scaledUV, int mode, float amount, float complexity, float evolvedValue, float seed, vec2 pinMask) {
    vec2 displacement = vec2(0.0);

    vec2 amountUV = (amount * pinMask) / resolution;

    float n1 = fractalNoise(scaledUV, complexity, evolvedValue, seed);

    if (mode == 0 || mode == 3 || mode == 8) { 
        // Turbulent / Turbulent Smoother / Cross
        float comp = (mode == 3) ? max(1.0, complexity * 0.5) : complexity;
        float n2 = fractalNoise(scaledUV + vec2(100.0, 50.0), comp, evolvedValue, seed + 100.0);

        // FIX: The core issue was that standard noise ranges -1 to 1. 
        // If we want a turbulent displacement that shifts pixels primarily in one direction, 
        // we might need an absolute value or a different mapping.
        // In standard After Effects 'Turbulent' displacement, it often pushes coordinates using noise mapped to [-1, 1]
        // Let's refine the displacement mapping.
        displacement = vec2(n1, n2) * amountUV * 2.0;
    }
    else if (mode == 1 || mode == 4 || mode == 2 || mode == 5) { 
        // Bulge / Twist modes ... (keeping your previous logic)
        float comp = (mode == 4 || mode == 5) ? max(1.0, complexity * 0.5) : complexity;

        vec2 eps = vec2(0.02, 0.0);
        float nX1 = fractalNoise(scaledUV - eps.xy, comp, evolvedValue, seed);
        float nX2 = fractalNoise(scaledUV + eps.xy, comp, evolvedValue, seed);
        float nY1 = fractalNoise(scaledUV - eps.yx, comp, evolvedValue, seed);
        float nY2 = fractalNoise(scaledUV + eps.yx, comp, evolvedValue, seed);
        vec2 grad = vec2(nX2 - nX1, nY2 - nY1) * (1.0 / (2.0 * eps.x));

        if (mode == 1 || mode == 4) {
            displacement = grad * amountUV * 0.35; // Bulge
        } else {
            displacement = vec2(grad.y, -grad.x) * amountUV * 0.35; // Twist
        }
    }
    else if (mode == 6) { // Vertical Displacement
        displacement = vec2(0.0, n1 * amountUV.y * 2.0);
    }
    else if (mode == 7) { // Horizontal Displacement
        displacement = vec2(n1 * amountUV.x * 2.0, 0.0);
    }

    return displacement;
}

void main() {
    vec2 uv = vUv;

    vec2 aspect = vec2(resolution.x / min(resolution.x, resolution.y), resolution.y / min(resolution.x, resolution.y));
    vec2 aspectUV = uv * aspect;

    vec2 scaledUV = aspectUV * (100.0 / max(Size, 0.001)) - (Offset / min(resolution.x, resolution.y));

    float evolvedValue = getEvolvedValue(Evolution, Cycle_Evolution, Cycle_in_Revolutions);
    vec2 pinMask = getPinningMask(uv, Pinning);

    vec2 displacement = applyDisplacement(scaledUV, Displacement, Amount, Complexity, evolvedValue, Random_Seed, pinMask);

    vec2 displacedUV = uv + displacement;
    if (Resize_Layer == 0) {
        displacedUV = clamp(displacedUV, 0.0, 1.0);
    }

    vec2 finalBufferUV = displacedUV * uvScale;

    vec4 color;
    if (Antialiasing_for_Best_Quality == 1) {
        vec2 texelSize = uvScale / resolution;
        color = texture2D(tDiffuse, finalBufferUV);
        color += texture2D(tDiffuse, finalBufferUV + vec2(texelSize.x, 0.0));
        color += texture2D(tDiffuse, finalBufferUV + vec2(-texelSize.x, 0.0));
        color += texture2D(tDiffuse, finalBufferUV + vec2(0.0, texelSize.y));
        color += texture2D(tDiffuse, finalBufferUV + vec2(0.0, -texelSize.y));
        color /= 5.0;
    } else {
        color = texture2D(tDiffuse, finalBufferUV);
    }

    gl_FragColor = color;
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUvScaled;
varying vec2 vUv;

/* ==== AE-like controls (ALL as dynamic uniforms) ==== */
uniform float Fractal_Type;        // 0..16
uniform float Noise_Type;          // 0..3
uniform float Invert;              // 0/1
uniform float Contrast;            // default 100
uniform float Brightness;          // default 0 (-100..100)
uniform float Overflow;            // 0..3
uniform float Rotation;            // degrees
uniform float Uniform_Scaling;     // 0/1
uniform float Scale;               // percent
uniform float Scale_Width;         // percent
uniform float Scale_Height;        // percent
uniform vec2  Offset_Turbulence;   // pixels
uniform float Perspective_Offset;  // 0/1
uniform float Complexity;          // 1..12
uniform float Sub_Influence;       // 0..100
uniform float Sub_Scaling;         // 0..100
uniform float Evolution;           // degrees
uniform float Turbulence_Factor;   // 1..4 (your range)
uniform float Random_Seed;         // integer-ish
uniform float Opacity;             // 0..100
uniform float Blending_Mode;       // 0..16

/* ==== Tuning constant: AE-ish "Scale=100" feel in pixels ==== */
const float AE_BASE_SCALE_PX = 100.0;

/* Evolution scale:
   Controls how much the pattern changes over 0..360 degrees.
   If evolution feels too subtle, increase to ~6.0.
   If too jumpy, reduce to ~2.0.
*/
const float EVOLUTION_Z_CELLS_PER_360 = 4.0;

/* ===================== Utility ===================== */
float sat(float x){ return clamp(x, 0.0, 1.0); }

vec2 rot2(vec2 p, float a){
  float s = sin(a), c = cos(a);
  return vec2(c*p.x - s*p.y, s*p.x + c*p.y);
}

/* Hash helpers (ES2-safe, no bit ops) */
float hash21(vec2 p, float seed){
  vec3 p3 = fract(vec3(p.xyx) * 0.1031 + seed*0.001);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float hash31(vec3 p, float seed){
  vec3 p3 = fract(p * 0.1031 + seed*0.001);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

/* Interpolation kernels to mimic AE Noise Type feel */
float interpKernel(float t, int type){
  if(type == 0) return step(0.5, t);                 // Block
  if(type == 1) return t;                            // Linear
  if(type == 2) return t*t*(3.0 - 2.0*t);            // Soft Linear (smoothstep)
  return t*t*t*(t*(t*6.0 - 15.0) + 10.0);            // Spline (smootherstep)
}

/* ===== 3D value noise with selectable interpolation =====
   This is the key to AE-like Evolution:
   Evolution becomes the Z dimension, changing internal state without translating XY.
*/
float valueNoise3D(vec3 p, int ntype, float seed){
  vec3 i = floor(p);
  vec3 f = fract(p);

  float u = interpKernel(f.x, ntype);
  float v = interpKernel(f.y, ntype);
  float w = interpKernel(f.z, ntype);

  // 8 corners
  float n000 = hash31(i + vec3(0.0,0.0,0.0), seed);
  float n100 = hash31(i + vec3(1.0,0.0,0.0), seed);
  float n010 = hash31(i + vec3(0.0,1.0,0.0), seed);
  float n110 = hash31(i + vec3(1.0,1.0,0.0), seed);

  float n001 = hash31(i + vec3(0.0,0.0,1.0), seed);
  float n101 = hash31(i + vec3(1.0,0.0,1.0), seed);
  float n011 = hash31(i + vec3(0.0,1.0,1.0), seed);
  float n111 = hash31(i + vec3(1.0,1.0,1.0), seed);

  float x00 = mix(n000, n100, u);
  float x10 = mix(n010, n110, u);
  float y0  = mix(x00, x10, v);

  float x01 = mix(n001, n101, u);
  float x11 = mix(n011, n111, u);
  float y1  = mix(x01, x11, v);

  return mix(y0, y1, w);
}

/* ===== Fractional-octave fBm (AE-like smooth TF changes) ===== */
float fbm3D(vec3 p, int ntype, float seed, float octavesF, float lacunarity, float gain, float evoZ){
  float sum = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  float norm = 0.0;

  // octavesF supports fractional octaves (e.g. 7.35)
  for(int i = 0; i < 12; i++){
    float fi = float(i);
    float w = clamp(octavesF - fi, 0.0, 1.0);
    if(w <= 0.0) break;

    // decorrelate octaves in Z a bit (AE-like richer evolution)
    float z = evoZ + fi * 13.37;

    float n = valueNoise3D(vec3(p.xy * freq, z * freq), ntype, seed + fi*17.0);

    sum  += n * amp * w;
    norm += amp * w;

    freq *= lacunarity;
    amp  *= gain;
  }

  return (norm > 0.0) ? (sum / norm) : 0.0;
}

float turbulenceAbs(float x){ return abs(x*2.0 - 1.0); }               // 0..1
float ridged(float x){ float r = 1.0 - abs(x*2.0 - 1.0); return r*r; } // sharper ridges
float billow(float x){ return abs(x*2.0 - 1.0); }                      // cloud-ish

/* Domain warp using 3D noise (uses evoZ for true evolution) */
vec2 domainWarp(vec2 p, int ntype, float seed, float evoZ, float strength){
  float w1 = valueNoise3D(vec3(p*1.2 + vec2(13.1, 7.7), evoZ), ntype, seed+101.0);
  float w2 = valueNoise3D(vec3(p*1.2 + vec2(3.7, 19.3), evoZ), ntype, seed+202.0);
  vec2 w = vec2(w1, w2) * 2.0 - 1.0;
  return p + w * strength;
}

/* "Smeary" multi-sample */
float smearySample3D(vec3 p, int ntype, float seed){
  float n0 = valueNoise3D(p, ntype, seed);
  float n1 = valueNoise3D(p + vec3(0.65, 0.15, 0.25), ntype, seed);
  float n2 = valueNoise3D(p + vec3(-0.25, 0.55, -0.15), ntype, seed);
  return (n0*0.55 + n1*0.25 + n2*0.20);
}

/* Overflow modes */
float applyOverflow(float x, int mode){
  if(mode == 0) return clamp(x, 0.0, 1.0);  // Clip
  if(mode == 1){
    float y = 0.5 + 0.5 * ((x - 0.5) / (1.0 + abs(x - 0.5)));
    return clamp(y, 0.0, 1.0);             // Soft Clamp
  }
  if(mode == 2){
    float m = mod(x, 2.0);
    return 1.0 - abs(m - 1.0);             // Wrap Back (mirror wrap)
  }
  return x;                                 // Allow HDR
}

/* ===== Blend modes (same as before) ===== */
vec3 blendNormal(vec3 b, vec3 s){ return s; }
vec3 blendAdd(vec3 b, vec3 s){ return b + s; }
vec3 blendMultiply(vec3 b, vec3 s){ return b * s; }
vec3 blendScreen(vec3 b, vec3 s){ return 1.0 - (1.0-b)*(1.0-s); }
vec3 blendOverlay(vec3 b, vec3 s){
  return mix(2.0*b*s, 1.0 - 2.0*(1.0-b)*(1.0-s), step(0.5, b));
}
vec3 blendSoftLight(vec3 b, vec3 s){
  return (1.0-2.0*s)*b*b + 2.0*s*b;
}
vec3 blendHardLight(vec3 b, vec3 s){
  return mix(2.0*b*s, 1.0 - 2.0*(1.0-b)*(1.0-s), step(0.5, s));
}
vec3 blendColorDodge(vec3 b, vec3 s){
  return b / max(vec3(1e-4), (1.0 - s));
}
vec3 blendColorBurn(vec3 b, vec3 s){
  return 1.0 - (1.0 - b) / max(vec3(1e-4), s);
}
vec3 blendDarken(vec3 b, vec3 s){ return min(b, s); }
vec3 blendLighten(vec3 b, vec3 s){ return max(b, s); }
vec3 blendDifference(vec3 b, vec3 s){ return abs(b - s); }
vec3 blendExclusion(vec3 b, vec3 s){ return b + s - 2.0*b*s; }

/* RGB <-> HSL for Hue/Sat/Lum blend modes */
float hue2rgb(float p, float q, float t){
  if(t < 0.0) t += 1.0;
  if(t > 1.0) t -= 1.0;
  if(t < 1.0/6.0) return p + (q-p)*6.0*t;
  if(t < 1.0/2.0) return q;
  if(t < 2.0/3.0) return p + (q-p)*(2.0/3.0 - t)*6.0;
  return p;
}
vec3 rgb2hsl(vec3 c){
  float maxc = max(max(c.r,c.g),c.b);
  float minc = min(min(c.r,c.g),c.b);
  float h = 0.0;
  float s = 0.0;
  float l = (maxc + minc)*0.5;
  float d = maxc - minc;
  if(d > 1e-6){
    s = d / (1.0 - abs(2.0*l - 1.0));
    if(maxc == c.r) h = mod((c.g - c.b)/d, 6.0);
    else if(maxc == c.g) h = (c.b - c.r)/d + 2.0;
    else h = (c.r - c.g)/d + 4.0;
    h /= 6.0;
    if(h < 0.0) h += 1.0;
  }
  return vec3(h,s,l);
}
vec3 hsl2rgb(vec3 hsl){
  float h=hsl.x, s=hsl.y, l=hsl.z;
  float r,g,b;
  if(s < 1e-6){
    r=g=b=l;
  }else{
    float q = (l < 0.5) ? (l*(1.0+s)) : (l + s - l*s);
    float p = 2.0*l - q;
    r = hue2rgb(p,q,h + 1.0/3.0);
    g = hue2rgb(p,q,h);
    b = hue2rgb(p,q,h - 1.0/3.0);
  }
  return vec3(r,g,b);
}

vec3 applyBlendMode(vec3 base, vec3 src, int mode){
  if(mode == 1) return blendNormal(base, src);
  if(mode == 2) return blendAdd(base, src);
  if(mode == 3) return blendMultiply(base, src);
  if(mode == 4) return blendScreen(base, src);
  if(mode == 5) return blendOverlay(base, src);
  if(mode == 6) return blendSoftLight(base, src);
  if(mode == 7) return blendHardLight(base, src);
  if(mode == 8) return blendColorDodge(base, src);
  if(mode == 9) return blendColorBurn(base, src);
  if(mode == 10) return blendDarken(base, src);
  if(mode == 11) return blendLighten(base, src);
  if(mode == 12) return blendDifference(base, src);
  if(mode == 13) return blendExclusion(base, src);

  vec3 bHSL = rgb2hsl(base);
  vec3 sHSL = rgb2hsl(src);
  if(mode == 14) return hsl2rgb(vec3(sHSL.x, bHSL.y, bHSL.z)); // Hue
  if(mode == 15) return hsl2rgb(vec3(bHSL.x, sHSL.y, bHSL.z)); // Saturation
  if(mode == 16) return hsl2rgb(vec3(bHSL.x, bHSL.y, sHSL.z)); // Luminosity

  return src;
}

/* ===================== Main Noise Builder ===================== */
float buildFractal(vec2 p, int ftype, int ntype, float seed, float octF, float lac, float gain, float evoZ){
  float n;

  if(ftype == 0){
    n = fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ);

  }else if(ftype == 1){
    n = fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ);
    n = smoothstep(0.0, 1.0, turbulenceAbs(n));

  }else if(ftype == 2){
    n = turbulenceAbs(fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ));

  }else if(ftype == 3){
    n = ridged(fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ));

  }else if(ftype == 4){
    vec2 pw = domainWarp(p, ntype, seed, evoZ, 0.75);
    n = fbm3D(vec3(pw, 0.0), ntype, seed, octF, lac, gain, evoZ);

  }else if(ftype == 5){
    // Dynamic Progressive: warp strength grows per octave but octF controls layers
    float sum = 0.0, amp = 0.5, freq = 1.0, norm = 0.0;

    for(int i=0;i<12;i++){
      float fi = float(i);
      float w = clamp(octF - fi, 0.0, 1.0);
      if(w <= 0.0) break;

      float k = fi / max(1.0, (octF - 1.0));
      vec2 pw = domainWarp(p*freq, ntype, seed + fi*33.0, evoZ + fi*9.7, mix(0.35, 1.10, k));
      float ni = valueNoise3D(vec3(pw, evoZ + fi*13.37), ntype, seed + fi*11.0);

      sum  += ni * amp * w;
      norm += amp * w;

      freq *= lac;
      amp  *= gain;
    }
    n = (norm > 0.0) ? (sum / norm) : 0.0;

  }else if(ftype == 6){
    // Dynamic Twist: twist angle driven by evolving 3D noise
    float ang = (valueNoise3D(vec3(p*0.8 + vec2(4.0,9.0), evoZ), ntype, seed+77.0)*2.0-1.0) * 1.6;
    vec2 pt = rot2(p, ang);
    n = fbm3D(vec3(pt, 0.0), ntype, seed, octF, lac, gain, evoZ);

  }else if(ftype == 7){
    // Max: take maximum across layers (weighted by octF)
    float mx = 0.0;
    float freq = 1.0;
    float amp = 1.0;
    for(int i=0;i<12;i++){
      float fi = float(i);
      float w = clamp(octF - fi, 0.0, 1.0);
      if(w <= 0.0) break;

      float ni = valueNoise3D(vec3(p*freq, evoZ + fi*13.37), ntype, seed + fi*19.0);
      mx = max(mx, ni * amp * w);

      freq *= lac;
      amp  *= gain;
    }
    n = sat(mx);

  }else if(ftype == 8){
    float s = smearySample3D(vec3(p*0.9, evoZ), ntype, seed);
    float f = fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ);
    n = mix(s, f, 0.65);

  }else if(ftype == 9){
    vec2 q = p;
    float a = valueNoise3D(vec3(p*0.6 + vec2(6.2,3.1), evoZ), ntype, seed+300.0)*6.2831;
    q += rot2(vec2(0.35,0.0), a) * 1.1;
    n = fbm3D(vec3(q, 0.0), ntype, seed, octF, lac, gain, evoZ);

  }else if(ftype == 10){
    n = ridged(fbm3D(vec3(p*1.15, 0.0), ntype, seed, octF, lac, gain, evoZ));
    n = pow(sat(n), 0.75);

  }else if(ftype == 11){
    n = billow(fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ));
    n = smoothstep(0.0, 1.0, n);

  }else if(ftype == 12){
    float r = ridged(fbm3D(vec3(p, 0.0), ntype, seed, octF, lac, gain, evoZ));
    float oct2F = max(1.0, octF - 2.0);
    float b = fbm3D(vec3(p*0.5, 0.0), ntype, seed+55.0, oct2F, lac, gain, evoZ);
    n = sat(r*1.2 + b*0.15);

  }else if(ftype == 13){
    float octHalfF = max(1.0, octF * 0.5);
    float base = fbm3D(vec3(p, 0.0), ntype, seed, octHalfF, lac, gain, evoZ);
    float fine = fbm3D(vec3(p*2.5, 0.0), ntype, seed+88.0, octF, lac, gain*0.9, evoZ);
    n = sat(base*0.45 + fine*0.75);

  }else if(ftype == 14){
    float fine = fbm3D(vec3(p*3.0, 0.0), ntype, seed+222.0, octF, lac, gain, evoZ);
    n = pow(sat(fine), 1.8);

  }else if(ftype == 15){
    vec2 pa = vec2(p.x*3.0, p.y*0.55);
    float s = fbm3D(vec3(pa, 0.0), ntype, seed+444.0, octF, lac, gain, evoZ);
    n = smoothstep(0.52, 0.78, s);

  }else{
    vec2 pa = vec2(p.x*4.2, p.y*0.45);
    float s = fbm3D(vec3(pa, 0.0), ntype, seed+555.0, octF, lac, gain*0.92, evoZ);
    n = pow(sat(s), 2.2);
    n = smoothstep(0.55, 0.90, n);
  }

  return sat(n);
}

void main(){
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  int ftype = int(floor(Fractal_Type + 0.5));
  int ntype = int(floor(Noise_Type + 0.5));
  int oflow = int(floor(Overflow + 0.5));
  int bmode = int(floor(Blending_Mode + 0.5));

  float seed = Random_Seed;

  // === TRUE AE-like Evolution ===
  // Map degrees to a Z position in noise-space (internal state, no XY drift)
  float evoZ = (Evolution / 360.0) * EVOLUTION_Z_CELLS_PER_360;

  // Scaling selection
  float sx = (Uniform_Scaling >= 0.5) ? Scale : Scale_Width;
  float sy = (Uniform_Scaling >= 0.5) ? Scale : Scale_Height;
  sx = max(1e-3, sx);
  sy = max(1e-3, sy);

  // UV -> pixel space (Offset Turbulence is position control)
  vec2 uv = vUv;
  vec2 pPix = uv * resolution + Offset_Turbulence;

  // Center and rotate
  vec2 centered = pPix - 0.5 * resolution;
  centered = rot2(centered, radians(Rotation));

  // AE-like scale in pixels
  vec2 cell = AE_BASE_SCALE_PX * vec2(sx, sy) / 100.0;
  vec2 p = centered / max(cell, vec2(1e-4));

  // Perspective Offset
  if(Perspective_Offset >= 0.5){
    float y = (uv.y - 0.5);
    p.x += y * 0.35;
    p *= 1.0 + y*0.15;
  }

  // === TF FIX: Turbulence Factor controls layered detail (octaves) ===
  // AE-like gentler curve so TF=4 isn't insanely noisy
  float tf = clamp(Turbulence_Factor, 1.0, 4.0);
  float tfCurved = 1.0 + (tf - 1.0) * 0.55;           // 1..~2.65 instead of 1..4

  float baseOct = clamp(Complexity, 1.0, 12.0);
  float octF = clamp(baseOct * tfCurved, 1.0, 12.0);  // fractional octaves supported

  // Sub params (TF no longer touches lacunarity!)
  float lac  = pow(2.0, Sub_Scaling / 50.0);
  float gain = clamp(Sub_Influence / 100.0, 0.0, 0.99);

  float n = buildFractal(p, ftype, ntype, seed, octF, lac, gain, evoZ);

  if(Invert >= 0.5) n = 1.0 - n;

  // Contrast/Brightness (AE-like)
  float c = max(0.0, Contrast) / 100.0;
  float b = Brightness / 100.0;
  n = (n - 0.5) * c + 0.5 + b;

  n = applyOverflow(n, oflow);

  vec3 noiseColor = vec3(n);
  float op = clamp(Opacity / 100.0, 0.0, 1.0);

  vec3 outRgb;
  if(bmode == 0){
    outRgb = mix(texel.rgb, noiseColor, op);
  }else{
    vec3 blended = applyBlendMode(texel.rgb, noiseColor, bmode);
    outRgb = mix(texel.rgb, blended, op);
  }

  gl_FragColor = vec4(outRgb, texel.a);
}

text./plugins/alipfx/shaders/twirl.glsl:
precision highp float;

uniform sampler2D tDiffuse;
uniform vec2 resolution;
varying vec2 vUv;

// AE Twirl parameters
uniform float angle;          // Twirl amount in degrees
uniform float twirlRadius;    // Radius in pixels
uniform vec2 twirlCenter;     // Center in pixels

void main() {
    // Convert UV to pixel space
    vec2 uvPx = vUv * resolution;

    // Compute vector from center
    vec2 delta = uvPx - twirlCenter;
    float dist = length(delta);

    // If outside radius, no twirl
    if (dist > twirlRadius) {
        gl_FragColor = texture2D(tDiffuse, vUv);
        return;
    }

    // Normalize distance (0 at center, 1 at radius)
    float normDist = dist / twirlRadius;

    // Convert angle to radians
    float maxAngle = radians(angle);

    // Compute twist amount based on distance (AE uses smooth falloff)
    float twist = maxAngle * (1.0 - normDist);

    // Rotate delta by twist
    float cosT = cos(twist);
    float sinT = sin(twist);
    vec2 rotated = vec2(
        delta.x * cosT - delta.y * sinT,
        delta.x * sinT + delta.y * cosT
    );

    // Compute final pixel position
    vec2 finalPx = twirlCenter + rotated;

    // Convert back to UV
    vec2 finalUV = finalPx / resolution;

    // Sample texture
    gl_FragColor = texture2D(tDiffuse, finalUV);
}

text./plugins/alipfx/shaders/unmult.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

/* Panzoid custom properties (Number dynamic) */
uniform float Background_Color;       // 0 = Black, 1 = White
uniform float Black_Level;            // 0..255
uniform float Softness;               // 0..255
uniform float Remove_Color_Matting;   // 0/1
uniform float Clip_HDR_Results;       // 0/1

float max3(vec3 c) { return max(c.r, max(c.g, c.b)); }
float min3(vec3 c) { return min(c.r, min(c.g, c.b)); }

// Rec.709 luminance (good for smoke density)
float luminance709(vec3 c) {
  return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

void main() {
  vec4 texel = texture2D(tDiffuse, vUvScaled);

  float isWhiteBG = step(0.5, Background_Color); // 0 or 1
  vec3 matteColor = mix(vec3(0.0), vec3(1.0), isWhiteBG);

  // Normalize UI controls to 0..1
  float level = clamp(Black_Level / 255.0, 0.0, 1.0);
  float soft  = clamp(Softness   / 255.0, 0.0, 1.0);

  // --- KEY SIGNAL (adaptive: smoke-friendly) ---
  // For smoke/shockwaves (low saturation), luminance is more accurate.
  // For colorful highlights, max channel works better.
  float mx = max3(texel.rgb);
  float mn = min3(texel.rgb);
  float sat = clamp(mx - mn, 0.0, 1.0);     // simple saturation estimate
  float grayWeight = 1.0 - smoothstep(0.05, 0.25, sat); // 1=gray, 0=color

  float lum = clamp(luminance709(texel.rgb), 0.0, 1.0);
  float keyBlack = mix(mx, lum, grayWeight);             // adaptive for black BG
  float keyWhite = 1.0 - mix(1.0 - mn, lum, grayWeight); // not commonly used; keeps logic consistent

  // For white BG we generally want: white->transparent, dark->opaque
  // Use inverted logic based on min channel, but keep gray behavior stable:
  float keyForWhiteBG = clamp(1.0 - mn, 0.0, 1.0);
  keyForWhiteBG = mix(keyForWhiteBG, 1.0 - lum, grayWeight);

  float keySignal = mix(keyBlack, keyForWhiteBG, isWhiteBG);

  // --- AE-LIKE MATTE GENERATION ---
  // Softness is FEATHER WIDTH around the cutoff (level).
  float aKey;
  if (soft <= 1e-6) {
    aKey = step(level, keySignal);              // hard cutoff
  } else {
    float hi = min(level + soft, 1.0);
    aKey = smoothstep(level, hi, keySignal);    // feather only at the edge
  }

  // Preserve existing source alpha if present
  float outA = clamp(aKey * texel.a, 0.0, 1.0);

  // Start with straight (unmatted) color = original
  vec3 straightRGB = texel.rgb;

  // --- REMOVE COLOR MATTING (protected, AE-ish) ---
  if (Remove_Color_Matting >= 0.5) {
    float eps = 1e-6;

    // Protect very low alpha to avoid division blow-ups / “wipe out”
    float protect = smoothstep(0.02, 0.20, outA);

    // Unmat/unpremultiply against matte color (black/white)
    vec3 unmatted = (texel.rgb - matteColor * (1.0 - outA)) / max(outA, eps);

    if (Clip_HDR_Results >= 0.5) {
      unmatted = clamp(unmatted, 0.0, 1.0);
    }

    straightRGB = mix(texel.rgb, unmatted, protect);
  }

  // --- NORMAL BLEND FRIENDLY OUTPUT ---
  // Output premultiplied RGB (more consistent for GPU compositing)
  vec3 premultRGB = straightRGB * outA;

  gl_FragColor = vec4(premultRGB, outA);
}

text./plugins/alipfx/shaders/unsharp-mask.gls:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2      resolution;
varying vec2      vUvScaled;

/* === Panzoid dynamic properties (create these exactly) ===
   Number (dynamic): Amount     -> percent (0..500 recommended)
   Number (dynamic): Radius     -> pixels  (0..50+ depending on content)
   Number (dynamic): Threshold  -> levels  (0..255, AE-style)
*/
uniform float Amount;
uniform float Radius;
uniform float Threshold;

/* ------------------------------------------------------------------
   Gaussian blur approximator
   - Isotropic (samples axial + diagonal rings)
   - Radius is specified in *pixels* (AE-like)
   - Uses 6 rings -> 49 taps (center + 8*K) for good quality
   - Spacing adapts so farthest tap ~ Radius
   ------------------------------------------------------------------ */
vec3 gaussianBlur(vec2 uv, float radiusPx)
{
    if (radiusPx <= 0.0) return texture2D(tDiffuse, uv).rgb;

    const int K = 6;
    float sigma  = max(radiusPx, 0.001);
    float stepPx = max(1.0, radiusPx / float(K));
    vec2  texel  = 1.0 / resolution;

    vec3 acc   = texture2D(tDiffuse, uv).rgb;
    float wsum = 1.0;

    for (int i = 1; i <= K; ++i) {
        float d   = float(i) * stepPx;
        float w   = exp(-(d*d) / (2.0 * sigma * sigma));
        vec2  off = texel * d;

        acc  += texture2D(tDiffuse, uv + vec2( off.x, 0.0)).rgb * w;
        acc  += texture2D(tDiffuse, uv + vec2(-off.x, 0.0)).rgb * w;
        acc  += texture2D(tDiffuse, uv + vec2(0.0,  off.y)).rgb * w;
        acc  += texture2D(tDiffuse, uv + vec2(0.0, -off.y)).rgb * w;
        wsum += 4.0 * w;
    }
    return acc / wsum;
}

/* Luma (Rec.709) for threshold gating — AE threshold is in 8‑bit levels. */
float luma709(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

void main()
{
    vec2 uv  = vUvScaled;
    vec3 src = texture2D(tDiffuse, uv).rgb;

    // 1) Blur with AE-like "Radius" measured in pixels
    float r = max(Radius, 0.0);
    vec3  blur = gaussianBlur(uv, r);

    // 2) High-pass (edges)
    vec3 hp = src - blur;

    // 3) Threshold gate — AE uses 0..255 levels; here convert to 0..1 luma
    float thr = clamp(Threshold / 255.0, 0.0, 1.0);
    float edgeStrength = abs(luma709(hp));

    // Soft edge around threshold to avoid harsh banding
    float gate = smoothstep(thr, thr + (1.0/255.0), edgeStrength);

    // 4) Amount (%): 100 = add full high-pass; 50 = half; 200 = double
    float gain = Amount / 100.0;

    vec3 outColor = src + hp * gain * gate;

    gl_FragColor = vec4(clamp(outColor, 0.0, 1.0), 1.0);
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;
varying vec2 vUv;
uniform vec2 resolution;

// Custom Properties
uniform float Transition_Completion; // 0 to 100
uniform float Direction;             // Degrees
uniform float Width;                 // Slat thickness (Pixels)
uniform float Feather;               // Edge softness (Pixels)

void main() {
    vec2 uv = vUv;
    float aspect = resolution.x / resolution.y;

    // 1. Rotation (Matches AE Clockwise)
    float angle = radians(Direction);
    float s = sin(angle);
    float c = cos(angle);

    // Center, correct aspect, rotate
    vec2 centeredUv = uv - 0.5;
    centeredUv.x *= aspect;
    vec2 rotUv;
    rotUv.x = centeredUv.x * c - centeredUv.y * s;
    rotUv.y = centeredUv.x * s + centeredUv.y * c;

    // 2. Slat Grid Setup
    // Calculate slat size in UV space based on pixel Width
    // We strictly use the Y-resolution as the anchor to match pixel feel
    float slatSize = max(Width, 1.0) / resolution.y;

    // Create the repeating pattern
    // We add a large offset to prevent negative coordinate artifacts
    float val = (rotUv.x / slatSize) + 100.0; 
    float fraction = fract(val);

    // 3. Distance from Center (Symmetry)
    // This creates a V-shape: 0.0 at center, 0.5 at edges
    float dist = abs(fraction - 0.5);

    // 4. Normalized Feather
    // We calculate feather as a ratio of the slat width.
    // If Feather = Width, the gradient spans the whole slat.
    float fRatio = (Feather / max(Width, 1.0)) * 0.5;

    // 5. Smart Transition Logic
    // We map the 0-100 completion to a range that extends slightly BEYOND
    // the slat boundaries. This ensures that at 0%, the feather doesn't
    // cut into the image, and at 100%, it's fully gone.

    // The visual half-width of the slat (0.0 to 0.5)
    // We buffer the range by 'fRatio' so the gradient can exist off-slat
    float maxVisible = 0.5 + fRatio;
    float minVisible = 0.0 - fRatio;

    // Map completion to this extended range
    float progress = Transition_Completion / 100.0;
    float currentThreshold = mix(maxVisible, minVisible, progress);

    // 6. Create Mask
    // Use smoothstep to create the gradient around the threshold
    // We invert it because we want the center (dist 0) to be visible
    float mask = 1.0 - smoothstep(currentThreshold - fRatio, currentThreshold + fRatio, dist);

    // 7. Output
    vec4 texel = texture2D(tDiffuse, vUvScaled);
    gl_FragColor = texel * mask;
}

text./plugins/alipfx/shaders/warp.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;
varying vec2 vUv;

// Panzoid custom properties (dynamic numbers)
uniform float Warp_Style;               // 0..14 (integer-like)
uniform float Warp_Axis;                // 0..1  (0=Horizontal, 1=Vertical)
uniform float Bend;                     // -100..100
uniform float Horizontal_Distortion;    // -100..100
uniform float Vertical_Distortion;      // -100..100

const float PI = 3.14159265358979323846;

float sat(float x) { return clamp(x, 0.0, 1.0); }

vec2 applyAxis(vec2 p, int axis)   { return (axis == 1) ? p.yx : p; }
vec2 unapplyAxis(vec2 p, int axis) { return (axis == 1) ? p.yx : p; }

// ------------------------------------------------------------
// AE-like taper distortions (FORWARD mapping)
// - Horizontal Distortion +100 => left edge collapses to a point
// - Vertical Distortion +100   => top edge collapses to a point
// ------------------------------------------------------------
vec2 distortionForward(vec2 p, float hd, float vd)
{
    float x = p.x;
    float y = p.y;

    float hdPos = max(hd, 0.0);
    float hdNeg = max(-hd, 0.0);

    float yScaleLeft  = (1.0 + x) * 0.5; // x=-1 -> 0, x=+1 -> 1
    float yScaleRight = (1.0 - x) * 0.5; // x=+1 -> 0, x=-1 -> 1

    float yScale = 1.0;
    yScale = mix(yScale, max(yScaleLeft,  1e-4), hdPos);
    yScale = mix(yScale, max(yScaleRight, 1e-4), hdNeg);
    y *= yScale;

    float vdPos = max(vd, 0.0);
    float vdNeg = max(-vd, 0.0);

    float xScaleTop    = (1.0 - y) * 0.5; // y=+1 -> 0, y=-1 -> 1
    float xScaleBottom = (1.0 + y) * 0.5; // y=-1 -> 0, y=+1 -> 1

    float xScale = 1.0;
    xScale = mix(xScale, max(xScaleTop,    1e-4), vdPos);
    xScale = mix(xScale, max(xScaleBottom, 1e-4), vdNeg);
    x *= xScale;

    return vec2(x, y);
}

// ------------------------------------------------------------
// Radial styles forward: FishEye (11) / Inflate (12)
// FIXED: Style 11 edges pinned, Style 12 NOT pinned
// ------------------------------------------------------------
vec2 warpRadialForward(vec2 p, int style, float b, float aspect)
{
    // Aspect-corrected radial coordinates for circular behavior
    vec2 q = vec2(p.x * aspect, p.y);

    float r = length(q);
    float ang = atan(q.y, q.x);

    // AE-ish response curve strength
    float k = 1.0 + abs(b) * 1.25;
    float expn;

    if (style == 11) {
        // FishEye: lens-like (strong center), we'll pin edges
        expn = (b >= 0.0) ? (1.0 / max(k, 1e-4)) : max(k, 1e-4);
    } else {
        // Inflate: opposite curve (and NOT edge-pinned)
        expn = (b >= 0.0) ? max(k, 1e-4) : (1.0 / max(k, 1e-4));
    }

    float rr = pow(max(r, 1e-6), expn);
    vec2 qWarp = vec2(cos(ang), sin(ang)) * rr;

    // ---------- EDGE BEHAVIOR DIFFERENCE ----------
    float w = 1.0;

    if (style == 11) {
        float rEdge = max(abs(p.x), abs(p.y));
        w = pow(clamp(1.0 - rEdge, 0.0, 1.0), 2.8);
    }

    q = mix(q, qWarp, w);
    q.x /= aspect;

    return q;
}

// ------------------------------------------------------------
// AE quirk: some styles invert bend direction when Warp Axis = Vertical.
// Keep the behavior you observed: Arc family + Arch invert on Vertical axis.
// ------------------------------------------------------------
float bendEffective(int style, int axis, float b)
{
    if (axis != 1) return b;

    // Arc, Arc Lower, Arc Upper, Arch: invert on vertical axis
    if (style == 0 || style == 1 || style == 2 || style == 3) return -b;

    return b;
}

// ------------------------------------------------------------
// Forward warp per-style in axis space.
// IMPORTANT: axis already applied => u = p.x (along axis), v = p.y (perp)
// Styles implemented: 0..10, 13, 14 here. 11/12 are radial.
// NOTE: Signature updated to include axis (needed for Style 14 behavior).
// ------------------------------------------------------------
vec2 warpStyleForward(vec2 p, int style, int axis, float b)
{
    float u = p.x;
    float v = p.y;

    float uu = u*u;
    float vv = v*v;

    // 1 at center, 0 at edges
    float arcU = 1.0 - uu;
    float midV = 1.0 - vv;
    float radial = sat(1.0 - (uu + vv));

    // ---------- 0: ARC (FAN) FIXED: bottom bends more + fan flare ----------
    if (style == 0) {
        float a = abs(b);

        float thetaMax = max(a * (PI * 0.60), 1e-5);
        float theta = u * thetaMax;

        float edge = (1.0 - cos(theta));
        float edgeMax = max(1.0 - cos(thetaMax), 1e-5);
        float bulge = 1.0 - (edge / edgeMax);

        float t = (v + 1.0) * 0.5;
        float bottom = 1.0 - t;

        float wV = mix(0.30, 1.0, bottom);

        v += b * 0.95 * bulge * wV;

        float flare = 1.0 + a * 0.55 * bulge * bottom;
        u *= flare;

        return vec2(u, v);
    }

    // ---------- 1: ARC LOWER ----------
    if (style == 1) {
        float bottomMask = (1.0 - v) * 0.5;
        float m = bottomMask;
        v += b * 0.92 * arcU * m;
        return vec2(u, v);
    }

    // ---------- 2: ARC UPPER ----------
    if (style == 2) {
        float topMask = (1.0 + v) * 0.5;
        float m = topMask;
        v += b * 0.92 * arcU * m;
        return vec2(u, v);
    }

    // ---------- 3: ARCH ----------
    if (style == 3) {
        float a = abs(b);

        float thetaMax = max(a * (PI * 0.70), 1e-5);
        float theta = u * thetaMax;
        float edge = (1.0 - cos(theta));
        float edgeMax = max(1.0 - cos(thetaMax), 1e-5);
        float bulge = 1.0 - (edge / edgeMax);

        float h = 0.85 + 0.15 * (1.0 - abs(v));
        v += b * 1.10 * bulge * h;

        return vec2(u, v);
    }

    // ---------- 4: BULGE ----------
    if (style == 4) {
        float k = b * 0.60 * radial;
        u *= 1.0 + k;
        v *= 1.0 + k;
        return vec2(u, v);
    }

    // ---------- 5: SHELL LOWER ----------
    if (style == 5) {
        float a = abs(b);

        float m = (1.0 - v) * 0.5;
        m = pow(m, 1.65);

        float taper = (m * 2.0 - 1.0);
        float scaleU = 1.0 + a * 0.55 * taper;
        scaleU = max(scaleU, 0.15);
        u *= scaleU;

        float bulge = arcU;
        float bendAmt = b * 0.95 * bulge * (0.25 + 0.75 * m);
        v += bendAmt;

        return vec2(u, v);
    }

    // ---------- 6: SHELL UPPER ----------
    if (style == 6) {
        float a = abs(b);

        float m = (1.0 + v) * 0.5;
        m = pow(m, 1.65);

        float taper = (m * 2.0 - 1.0);
        float scaleU = 1.0 + a * 0.55 * taper;
        scaleU = max(scaleU, 0.15);
        u *= scaleU;

        float bulge = arcU;
        float bendAmt = b * 0.95 * bulge * (0.25 + 0.75 * m);
        v += bendAmt;

        return vec2(u, v);
    }

    // ---------- 7: FLAG ----------
    if (style == 7) {
        v += b * 0.55 * sin((u * 0.5 + 0.5) * PI);
        return vec2(u, v);
    }

    // ---------- 8: WAVE ----------
    if (style == 8) {
        v += b * 0.40 * sin((u * 0.5 + 0.5) * PI * 2.0);
        return vec2(u, v);
    }

    // ---------- 9: FISH (your current version) ----------
    // Bend > 0  => LEFT expands, RIGHT pinches
    // Bend < 0  => RIGHT expands, LEFT pinches
    if (style == 9) {
        float k = b;
        float a = abs(b);

        float uu2 = u * u;
        float vv2 = v * v;

        float midU2 = 1.0 - uu2;
        float midV2 = 1.0 - vv2;

        float belly = 1.0 + 0.45 * a * midU2 * (0.60 + 0.40 * midV2);
        u *= belly;

        float pinch = 1.0 - 0.50 * a * midU2;
        v *= pinch;

        float asym = 0.38 * k * midV2 * (-u);
        float s = 1.0 + asym;
        s = clamp(s, 0.15, 3.0);
        u *= s;

        v += 0.06 * k * (uu2 - 0.5) * midV2;

        return vec2(u, v);
    }

    // ---------- 10: RISE ----------

// ---------- 10: RISE (FIXED: AE-like curved ramp) ----------
if (style == 10) {
    // u in [-1..1] -> u01 in [0..1]
    float u01 = u * 0.5 + 0.5;

    // Curved/eased ramp (smoothstep). AE Rise feels more like this than a linear ramp.
    float ramp = u01 * u01 * (3.0 - 2.0 * u01);

    // Add a little extra curvature so the edge isn't a straight diagonal.
    // This makes Bend=50 resemble AE more closely.
    float ramp2 = ramp * ramp;

    // Final displacement
    // 1.55 is tuned so Bend=50 looks noticeably strong (like your AE screenshot)
    v += b * (1.05 * ramp + 0.50 * ramp2);

    return vec2(u, v);
}

    // ---------- 13: TWIST (FIXED: pinned edges, right/left twirl) ----------
    if (style == 13) {
        float maxTwist = 1.35 * PI;

        float r = max(abs(u), abs(v));
        float fall = 1.0 - r;
        fall = pow(max(fall, 0.0), 2.2);

        float ang = -b * maxTwist * fall;

        float cs = cos(ang);
        float sn = sin(ang);

        float u2 = cs * u - sn * v;
        float v2 = sn * u + cs * v;

        return vec2(u2, v2);
    }

    // ---------- 14: SQUEEZE (FIXED: sign chooses squeeze direction) ----------
    // Your request:
    // - Bend < 0 => squeeze horizontally (pinch left/right)
    // - Bend > 0 => squeeze vertically (pinch top/bottom)
    //
    // This works for both Warp_Axis = 0 and 1 by converting to comp-space axes.
    if (style == 14) {
        // Convert axis-space (possibly swapped) back to comp-space
        vec2 q = (axis == 1) ? vec2(v, u) : vec2(u, v); // q.x = compX, q.y = compY

        float amt = abs(b);
        float k = 0.92; // strength (tune if needed)

        float midX = 1.0 - (q.x * q.x); // 1 at center, 0 at left/right
        float midY = 1.0 - (q.y * q.y); // 1 at center, 0 at top/bottom

        if (b < 0.0) {
            // Negative => squeeze horizontally (scale X based on Y center)
            float sx = 1.0 - amt * k * midY;
            sx = max(sx, 0.08);
            q.x *= sx;
        } else if (b > 0.0) {
            // Positive => squeeze vertically (scale Y based on X center)
            float sy = 1.0 - amt * k * midX;
            sy = max(sy, 0.08);
            q.y *= sy;
        }

        // Convert back to axis-space
        vec2 outv = (axis == 1) ? vec2(q.y, q.x) : q;
        return outv;
    }

    return vec2(u, v);
}

// ------------------------------------------------------------
// Full FORWARD transform = warp then distortion (AE-like interaction)
// ------------------------------------------------------------
vec2 forwardTransform(vec2 p, int style, int axis, float b, float hd, float vd, float aspect)
{
    // FishEye & Inflate ignore axis
    if (style == 11 || style == 12) {
        p = warpRadialForward(p, style, b, aspect);
        p = distortionForward(p, hd, vd);
        return p;
    }

    float bEff = bendEffective(style, axis, b);

    vec2 pa = applyAxis(p, axis);
    pa = warpStyleForward(pa, style, axis, bEff);
    p  = unapplyAxis(pa, axis);

    // Apply distortion after warp
    p = distortionForward(p, hd, vd);
    return p;
}

// ------------------------------------------------------------
// INVERSE solve: find p_in such that forwardTransform(p_in)=p_out
// Fixed-point iteration with damping.
// ------------------------------------------------------------
vec2 inverseSolve(vec2 pOut, int style, int axis, float b, float hd, float vd, float aspect)
{
    vec2 p = pOut;

    for (int i = 0; i < 7; i++) {
        vec2 f = forwardTransform(p, style, axis, b, hd, vd, aspect);
        vec2 e = f - pOut;
        p -= e * 0.75;
    }
    return p;
}

void main()
{
    vec2 pOut = (vUv - 0.5) * 2.0;

    float aspect = resolution.x / max(resolution.y, 1.0);

    int style = int(floor(Warp_Style + 0.5));
    int axis  = int(floor(Warp_Axis  + 0.5));

    float b  = clamp(Bend / 100.0, -1.0, 1.0);
    float hd = clamp(Horizontal_Distortion / 100.0, -1.0, 1.0);
    float vd = clamp(Vertical_Distortion / 100.0, -1.0, 1.0);

    vec2 pIn = inverseSolve(pOut, style, axis, b, hd, vd, aspect);

    vec2 uvIn = pIn * 0.5 + 0.5;
    vec2 sampleUv = uvIn * uvScale;

    if (uvIn.x < 0.0 || uvIn.x > 1.0 || uvIn.y < 0.0 || uvIn.y > 1.0) {
        gl_FragColor = vec4(0.0);
    } else {
        gl_FragColor = texture2D(tDiffuse, sampleUv);
    }
}

text./plugins/alipfx/shaders/wave-warp.glsl:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform vec2 uvScale;
uniform vec2 resolution;

varying vec2 vUv;

// ---- Custom properties (Dynamic Number in Panzoid) ----
uniform float Wave_Type;       // 0..8 (int values)
uniform float Wave_Height;     // pixels
uniform float Wave_Width;      // pixels
uniform float Direction;       // degrees
uniform float Wave_Speed;      // cycles/sec-ish
uniform float Pinning;         // 0..8 (int values)
uniform float Phase;           // degrees
uniform float Antialiasing;    // 0 Low, 1 Medium, 2 High
uniform float time;            // seconds

const float PI  = 3.14159265358979323846;
const float TAU = 6.28318530717958647692;

// -------------------- Noise helpers --------------------
float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float noise1D_step(float x) {
  float i = floor(x);
  return hash11(i) * 2.0 - 1.0;
}

float noise1D_smooth(float x) {
  float i = floor(x);
  float f = fract(x);
  float a = hash11(i);
  float b = hash11(i + 1.0);
  float u = f * f * (3.0 - 2.0 * f);
  return (mix(a, b, u) * 2.0 - 1.0);
}

// -------------------- Wave shapes --------------------
// ph = radians, coordForNoise = cycles coordinate
float waveShape(float ph, int wType, int aa, float coordForNoise) {
  float s = sin(ph);
  float u = fract(ph / TAU); // 0..1

  // constant smoothing for Square when AA > 0 (no derivatives allowed)
  float k = 0.0;
  if (aa == 1) k = 0.015;   // medium smooth
  if (aa == 2) k = 0.030;   // high smooth

  if (wType == 0) {
    // Sine
    return s;
  } else if (wType == 1) {
    // Square (softened slightly if AA enabled)
    if (aa == 0) return sign(s);
    return smoothstep(-k, k, s) * 2.0 - 1.0;
  } else if (wType == 2) {
    // Triangle: 2/pi * asin(sin(x))
    return (2.0 / PI) * asin(clamp(s, -1.0, 1.0));
  } else if (wType == 3) {
    // Sawtooth: ramp -1..1
    return u * 2.0 - 1.0;
  } else if (wType == 4) {
    // Circle: alternating semicircle arcs (+ then -)
    float halfSign = (u < 0.5) ? 1.0 : -1.0;
    float uh = fract(u * 2.0);      // 0..1 within half
    float x  = uh * 2.0 - 1.0;      // -1..1
    float y  = sqrt(max(0.0, 1.0 - x*x)); // 0..1
    return y * halfSign;            // -1..1
  } else if (wType == 5) {
    // Semicircle: repeating humps, mapped to -1..1
    float x = u * 2.0 - 1.0;              // -1..1
    float y = sqrt(max(0.0, 1.0 - x*x));  // 0..1
    return y * 2.0 - 1.0;
  } else if (wType == 6) {
    // Uncircle: inverted circle-ish, signed by half
    float halfSign = (u < 0.5) ? 1.0 : -1.0;
    float uh = fract(u * 2.0);
    float x  = uh * 2.0 - 1.0;
    float y  = sqrt(max(0.0, 1.0 - x*x));
    float inv = 1.0 - y;
    return (inv * 2.0 - 1.0) * halfSign;
  } else if (wType == 7) {
    // Noise (stepped)
    return noise1D_step(coordForNoise);
  } else {
    // Smooth Noise
    return noise1D_smooth(coordForNoise);
  }
}

// -------------------- Pinning --------------------
float pinFactor(vec2 uv, vec2 n, int pinMode) {
  if (pinMode == 0) return 1.0;

  float left   = uv.x;
  float right  = 1.0 - uv.x;
  float bottom = uv.y;
  float top    = 1.0 - uv.y;

  if (pinMode == 1) {
    float e = min(min(left, right), min(top, bottom));
    return clamp(e * 2.0, 0.0, 1.0);
  }
  if (pinMode == 3) return clamp(left,   0.0, 1.0);
  if (pinMode == 5) return clamp(right,  0.0, 1.0);
  if (pinMode == 6) return clamp(bottom, 0.0, 1.0);
  if (pinMode == 4) return clamp(top,    0.0, 1.0);

  if (pinMode == 7) {
    float e = min(top, bottom);
    return clamp(e * 2.0, 0.0, 1.0);
  }
  if (pinMode == 8) {
    float e = min(left, right);
    return clamp(e * 2.0, 0.0, 1.0);
  }

  // Center pinning along displacement axis
  vec2 p = uv * resolution;
  float proj = dot(p, n);

  float W = resolution.x;
  float H = resolution.y;
  float a = W * n.x;
  float b = H * n.y;
  float mn = min(0.0, min(a, min(b, a + b)));
  float mx = max(0.0, max(a, max(b, a + b)));

  float t = (mx > mn) ? ((proj - mn) / (mx - mn)) : 0.5;
  float d = abs(t - 0.5) * 2.0; // 0 at center, 1 at edges
  return clamp(d, 0.0, 1.0);
}

// -------------------- AA sampling --------------------
vec4 sampleLayerAA(vec2 uv, int aa) {
  // outside -> transparent (matches AE feel)
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
    return vec4(0.0);
  }

  vec2 px = 0.5 / resolution;

  if (aa == 0) {
    return texture2D(tDiffuse, uv * uvScale);
  }

  if (aa == 1) {
    vec4 c0 = texture2D(tDiffuse, (uv + vec2(-px.x, -px.y)) * uvScale);
    vec4 c1 = texture2D(tDiffuse, (uv + vec2( px.x, -px.y)) * uvScale);
    vec4 c2 = texture2D(tDiffuse, (uv + vec2(-px.x,  px.y)) * uvScale);
    vec4 c3 = texture2D(tDiffuse, (uv + vec2( px.x,  px.y)) * uvScale);
    return (c0 + c1 + c2 + c3) * 0.25;
  }

  // aa == 2
  vec4 sum = vec4(0.0);
  sum += texture2D(tDiffuse, (uv + vec2(-px.x, -px.y)) * uvScale);
  sum += texture2D(tDiffuse, (uv + vec2( 0.0, -px.y)) * uvScale);
  sum += texture2D(tDiffuse, (uv + vec2( px.x, -px.y)) * uvScale);

  sum += texture2D(tDiffuse, (uv + vec2(-px.x,  0.0)) * uvScale);
  sum += texture2D(tDiffuse, (uv + vec2( 0.0,  0.0)) * uvScale);
  sum += texture2D(tDiffuse, (uv + vec2( px.x,  0.0)) * uvScale);

  sum += texture2D(tDiffuse, (uv + vec2(-px.x,  px.y)) * uvScale);
  sum += texture2D(tDiffuse, (uv + vec2( 0.0,  px.y)) * uvScale);
  sum += texture2D(tDiffuse, (uv + vec2( px.x,  px.y)) * uvScale);

  return sum / 9.0;
}

// -------------------- Main --------------------
void main() {
  vec2 uv = vUv;

  int wType = int(floor(Wave_Type + 0.5));
  int pin   = int(floor(Pinning + 0.5));
  int aa    = int(floor(Antialiasing + 0.5));

  float wWidth = max(Wave_Width, 0.0001);

  // 0° = right, 90° = up
  float ang = radians(Direction);
  vec2 d = vec2(cos(ang), sin(ang));  // travel axis
  vec2 n = vec2(-d.y, d.x);           // displacement axis

  vec2 p = uv * resolution;           // pixel position
  float coord = dot(p, d);            // pixels along travel axis

  float phaseCycles = Phase / 360.0;
  float cycles = (coord / wWidth) + (time * Wave_Speed) + phaseCycles;
  float ph = cycles * TAU;

  float w = waveShape(ph, wType, aa, cycles);

  float pinF = pinFactor(uv, n, pin);
  float dispPx = w * Wave_Height * pinF;

  vec2 uvWarp = uv + (dispPx * n) / resolution;

  gl_FragColor = sampleLayerAA(uvWarp, aa);
}
